def _blade_get_console_cp():
    """Windows 控制台当前输出代码页；非 Windows 或没有控制台时返回 0。"""
    try:
        import ctypes

        return int(ctypes.windll.kernel32.GetConsoleOutputCP() or 0)  # type: ignore[attr-defined]
    except Exception:  # noqa: BLE001 - 没有控制台句柄/非 Windows 时按 0 处理
        return 0


def _blade_set_console_cp(codepage):
    """把 Windows 控制台输出代码页切到 codepage；返回是否成功。"""
    try:
        import ctypes

        return bool(ctypes.windll.kernel32.SetConsoleOutputCP(int(codepage)))  # type: ignore[attr-defined]
    except Exception:  # noqa: BLE001 - 没有控制台句柄/非 Windows 时按失败处理
        return False


def _blade_fix_console_encoding():
    """把 Windows 控制台输出统一到 UTF-8，避免中文日志变成 `鉁?[ML寮曟搸]`。

    根因：字符串以 UTF-8 字节写出，控制台却按 GBK(936) 解释，于是
    「✅ [ML引擎]」被读成乱码。两道动作：

      1. 控制台输出代码页切到 65001（UTF-8）。有控制台才切，失败静默跳过。
      2. sys.stdout 编码表达不了中文（cp437/cp1252/ascii 等）或和代码页
         不一致时，reconfigure 成 UTF-8 + errors='replace'。

    只在 Windows 上执行；不改任何文件的编码，也不碰 stdin/stderr。
    """
    try:
        if os.name != 'nt' and sys.platform != 'win32':
            return False
    except Exception:  # noqa: BLE001 - 平台判断失败按非 Windows 处理
        return False

    changed = False
    console_is_utf8 = False
    try:
        codepage = _blade_get_console_cp()
        if codepage == 65001:
            console_is_utf8 = True
        elif codepage and _blade_set_console_cp(65001):
            console_is_utf8 = True
            changed = True
    except Exception:  # noqa: BLE001 - 代码页操作失败不影响编码兜底
        console_is_utf8 = False

    stream = sys.stdout
    if stream is None:
        return changed
    encoding = str(getattr(stream, 'encoding', '') or '')
    can_encode_chinese = True
    try:
        '中文'.encode(encoding or 'ascii')
    except (UnicodeEncodeError, LookupError):
        can_encode_chinese = False
    # 控制台已切 UTF-8 时，stdout 也必须吐 UTF-8 字节，否则又会被读成乱码。
    needs_utf8 = (not can_encode_chinese) or (
        console_is_utf8 and encoding.lower().replace('-', '') not in ('utf8', 'utf8mb4')
    )
    if not needs_utf8:
        return changed
    reconfigure = getattr(stream, 'reconfigure', None)
    if callable(reconfigure):
        try:
            reconfigure(encoding='utf-8', errors='replace')
            changed = True
        except Exception:  # noqa: BLE001,S110 - 无法 reconfigure 时保持原状  # nosec B110
            pass
    return changed


_blade_fix_console_encoding()


# ================== 🖥️ CLI 模式探测（必须最先执行，早于 Streamlit/浏览器启动） ==================
# 支持:
#   -OkoooRoute proxy -OkoooProxy "http://127.0.0.1:7890"
#   --okooo-route/--okooo-proxy（大小写不敏感）
#   python app_v84_hermes.py --daily-learn
# Streamlit: streamlit run app_v84_hermes.py -- ... -- -OkoooRoute proxy -OkoooProxy "http://..."


def _blade_cli_flag_key(token):
    text = str(token or "")
    if text.startswith("-") and "=" in text:
        text = text.split("=", 1)[0]
    return "".join(ch for ch in text.lower() if ("a" <= ch <= "z") or ("0" <= ch <= "9"))


def _blade_normalize_proxy_url(url):
    text = str(url or "").strip().strip('"').strip("'")
    if not text:
        return ""
    if "://" not in text:
        text = f"http://{text}"
    return text


def _blade_normalize_okooo_route(route):
    text = str(route or "").strip().lower()
    if text in ("proxy", "proxies", "px", "1", "on", "true", "yes"):
        return "proxy"
    if text in ("direct", "directconnect", "none", "off", "0", "false", "no"):
        return "direct"
    if text in ("auto", "detect", "default", ""):
        return "auto"
    return "auto"


def _blade_proxy_port_reachable(url, timeout=1.0):
    import socket as _socket

    text = _blade_normalize_proxy_url(url)
    if "://" not in text:
        return False
    try:
        host_port = text.split("://", 1)[1].split("/", 1)[0]
        if "@" in host_port:
            host_port = host_port.rsplit("@", 1)[1]
        host, port_s = host_port.rsplit(":", 1)
        port = int(port_s)
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return False
    sock = None
    try:
        sock = _socket.socket(_socket.AF_INET, _socket.SOCK_STREAM)
        sock.settimeout(timeout)
        sock.connect((host, port))
        return True
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return False
    finally:
        try:
            if sock is not None:
                sock.close()
        except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
            pass


def _apply_okooo_boot_cli(argv=None):
    """解析并应用 -OkoooRoute / -OkoooProxy，写回环境变量，供全局代理与澳客抓取共用。"""
    args = list(sys.argv if argv is None else argv)
    route = _blade_normalize_okooo_route(
        os.environ.get("OKOOO_ROUTE") or os.environ.get("BLADE_OKOOO_ROUTE") or ""
    )
    proxy = _blade_normalize_proxy_url(
        os.environ.get("OKOOO_PROXY") or os.environ.get("BLADE_OKOOO_PROXY") or ""
    )
    drop = set()
    i = 1
    while i < len(args):
        token = str(args[i] or "")
        key = _blade_cli_flag_key(token)
        inline = None
        if token.startswith("-") and "=" in token:
            inline = token.split("=", 1)[1]
        # OkoooRoute -> okoooroute; also accept mistype okooroute
        if key in ("okoooroute", "okooroute"):
            drop.add(i)
            if inline is not None:
                route = _blade_normalize_okooo_route(inline)
            elif i + 1 < len(args) and not str(args[i + 1]).startswith("-"):
                route = _blade_normalize_okooo_route(args[i + 1])
                drop.add(i + 1)
                i += 2
                continue
        # OkoooProxy -> okoooproxy
        elif key in ("okoooproxy", "okooopproxy"):
            drop.add(i)
            if inline is not None:
                proxy = _blade_normalize_proxy_url(inline)
            elif i + 1 < len(args) and not str(args[i + 1]).startswith("-"):
                proxy = _blade_normalize_proxy_url(args[i + 1])
                drop.add(i + 1)
                i += 2
                continue
        i += 1

    if drop and argv is None:
        sys.argv[:] = [args[j] for j in range(len(args)) if j not in drop]

    if route == "proxy" and not proxy:
        proxy = "http://127.0.0.1:7890"

    os.environ["OKOOO_ROUTE"] = route
    if route == "direct":
        # 直连：清掉启动代理绑定；探测函数按 route=direct 跳过代理
        proxy = ""
        os.environ.pop("OKOOO_PROXY", None)
        os.environ.pop("BLADE_OKOOO_PROXY", None)
    elif proxy:
        os.environ["OKOOO_PROXY"] = proxy

    if route == "proxy" and proxy:
        os.environ["OKOOO_PROXY_POOL"] = proxy
        os.environ.setdefault("BLADE_PROXY_POOL", proxy)

    return route, proxy


_CLI_OKOOO_ROUTE, _CLI_OKOOO_PROXY = _apply_okooo_boot_cli()

