def _silence_closed_websocket_writes():
    """浏览器断开后，Tornado 写页面的异步错误不再刷屏。抓取继续。"""
    try:
        import tornado.websocket as ws
    except ImportError:
        return
    proto = getattr(ws, 'WebSocketProtocol13', None)
    if proto is None:
        return
    write = getattr(proto, 'write_message', None)
    if write is None or getattr(write, '_blade_closed_safe', False):
        return

    def write_message(self, message, binary=False):
        fut = write(self, message, binary=binary)
        if fut is not None and hasattr(fut, 'add_done_callback'):
            def _done(task):
                try:
                    exc = task.exception()
                except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    return
                if exc is None or isinstance(exc, ws.WebSocketClosedError):
                    return
                try:
                    task.get_loop().call_exception_handler({
                        'message': 'websocket write failed',
                        'exception': exc,
                        'future': task,
                    })
                except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    return
            try:
                fut.add_done_callback(_done)
            except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
                pass
        return fut

    write_message.__dict__['_blade_closed_safe'] = True
    proto.write_message = write_message


_silence_closed_websocket_writes()


# ================== 📡 全局代理配置（CLI 优先，其次智能探测） ==================
def _local_proxy_base():
    """代理选择：OKOOO_ROUTE=direct 直连；proxy 用 OKOOO_PROXY；auto 则 CLI/环境优先，再探 7897/7890。"""
    route = _blade_normalize_okooo_route(os.environ.get("OKOOO_ROUTE") or _CLI_OKOOO_ROUTE or "auto")
    forced = _blade_normalize_proxy_url(
        os.environ.get("OKOOO_PROXY")
        or _CLI_OKOOO_PROXY
        or os.environ.get("HTTPS_PROXY")
        or os.environ.get("https_proxy")
        or os.environ.get("HTTP_PROXY")
        or os.environ.get("http_proxy")
        or ""
    )
    if route == "direct":
        return ""
    if forced:
        if _blade_proxy_port_reachable(forced):
            return forced
        if route == "proxy":
            # 用户指定代理路由：端口暂时不通仍绑定该地址，由后续请求/探活再降级
            return forced
    if route == "proxy":
        fallback = "http://127.0.0.1:7890"
        if _blade_proxy_port_reachable(fallback):
            return fallback
        return fallback
    import socket
    for _port in (7897, 7890):
        _s = None
        try:
            _s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            _s.settimeout(1)
            _s.connect(('127.0.0.1', _port))
            return f'http://127.0.0.1:{_port}'
        except Exception:  # noqa: BLE001,S112 - intentional degraded-mode guard or structure-preserving fallback  # nosec B112  # intentional degraded-mode continue fallback
            continue
        finally:
            try:
                if _s is not None:
                    _s.close()
            except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
                pass
    return ''


def _local_proxies():
    _base = _local_proxy_base()
    if not _base:
        return None
    return {'http': _base, 'https': _base}


def _check_proxy_available():
    route = _blade_normalize_okooo_route(os.environ.get("OKOOO_ROUTE") or _CLI_OKOOO_ROUTE or "auto")
    if route == "direct":
        return False
    base = _local_proxy_base()
    if not base:
        return False
    if route == "proxy":
        return True
    return _blade_proxy_port_reachable(base)

def _blade_quiet_asyncio_noise():
    """屏蔽 asyncio 传输层在 Windows 上的 ConnectionResetError 回溯。

    `Exception in callback _ProactorBasePipeTransport._call_connection_lost`
    是 httpx/requests 关闭连接时 proactor 的已知噪音，不影响任何业务结果。
    只忽略「连接丢失/重置」这一类，其它异常照常输出。
    """
    try:
        import asyncio
        loop = None
        try:
            loop = asyncio.get_running_loop()
        except RuntimeError:
            return
        if loop is None:
            return
        _noise = ('ConnectionResetError', '_call_connection_lost', 'Connection lost')

        def _handler(loop_, context):
            exc = context.get('exception')
            text = f'{type(exc).__name__}: {exc}' if exc else str(context.get('message') or '')
            if any(token in text for token in _noise):
                return
            try:
                loop_.default_exception_handler(context)
            except Exception:  # noqa: BLE001,S110 - 兜底处理器自身也不能抛  # nosec B110
                pass

        loop.set_exception_handler(_handler)
    except Exception:  # noqa: BLE001,S110 - 任何失败都不影响主流程  # nosec B110
        pass


def _blade_boot_banner(text):
    """每个进程只打一次 [boot] 行。

    Streamlit 每次交互都会重跑整个脚本，直接 print 会刷出几十行同样的 banner。
    """
    import os as _os
    flag = '_BLADE_BOOT_BANNER_PRINTED'
    if _os.environ.get(flag):
        return
    _os.environ[flag] = '1'
    try:
        print(f"[boot] {text}", flush=True)
        # 让日志能一眼对上构建：以后任何一段控制台输出都能被追溯到具体 pin。
        import hashlib as _hl
        _me = _os.path.abspath(__file__)
        try:
            with open(_me, 'rb') as _fh:
                _sha = _hl.sha256(_fh.read()).hexdigest()[:12]
        except OSError:
            _sha = 'unknown'
        try:
            from okooo_mobile_cs import CACHE_SCHEMA as _cs_schema
        except ImportError:  # 模块缺失时仍要打印
            _cs_schema = -1
        print(f"[build] app_sha256={_sha} cache_schema={_cs_schema}", flush=True)
    except Exception:  # noqa: BLE001 - 控制台不可用就算了
        _os.environ[flag] = '1'


_BOOT_PROXY = _local_proxy_base()
_BOOT_ROUTE = _blade_normalize_okooo_route(os.environ.get("OKOOO_ROUTE") or _CLI_OKOOO_ROUTE or "auto")
if _BOOT_PROXY and _BOOT_ROUTE != "direct":
    os.environ["http_proxy"] = _BOOT_PROXY
    os.environ["https_proxy"] = _BOOT_PROXY
    os.environ["HTTP_PROXY"] = _BOOT_PROXY
    os.environ["HTTPS_PROXY"] = _BOOT_PROXY
    os.environ["OKOOO_PROXY"] = _BOOT_PROXY
    os.environ["OKOOO_PROXY_POOL"] = _BOOT_PROXY
    os.environ["NO_PROXY"] = "localhost,127.0.0.1,::1"
    _blade_boot_banner(f"OkoooRoute={_BOOT_ROUTE} OkoooProxy={_BOOT_PROXY}")
else:
    # 代理不可用，清除环境变量避免干扰直连
    for _k in ["http_proxy", "https_proxy", "HTTP_PROXY", "HTTPS_PROXY"]:
        os.environ.pop(_k, None)
    os.environ["NO_PROXY"] = "localhost,127.0.0.1,::1"
    _blade_boot_banner("OkoooRoute=%s OkoooProxy=direct" % (_BOOT_ROUTE or "auto"))

# proxies=None 仍会吃环境变量。直连必须显式传 None 值。
_DIRECT_PROXIES = {'http': None, 'https': None}


def _forget_dead_proxy():
    """代理拒绝连接后清掉环境代理，避免后面的请求继续撞死代理。"""
    route = _blade_normalize_okooo_route(os.environ.get("OKOOO_ROUTE") or "")
    if route == "proxy":
        # CLI 强制走代理时不因一次探活失败清掉路由绑定
        return
    for _k in ("http_proxy", "https_proxy", "HTTP_PROXY", "HTTPS_PROXY"):
        os.environ.pop(_k, None)


def _http_routes():
    """端口能连才带代理，随后一定有一条不走环境代理的直连。"""
    route = _blade_normalize_okooo_route(os.environ.get("OKOOO_ROUTE") or _CLI_OKOOO_ROUTE or "auto")
    if route == "direct":
        _forget_dead_proxy()
        return [_DIRECT_PROXIES]
    _px = _local_proxies()
    if _px:
        return [
            _px,
            _DIRECT_PROXIES,
        ]
    _forget_dead_proxy()
    return [_DIRECT_PROXIES]
