def _downgrade_okooo_https(url):
    """澳客 https 降成 http。非 https、没有主机、或主机不是澳客时返回空串。"""
    try:
        from urllib.parse import urlsplit, urlunsplit
        text = str(url or '').strip()
        if not text:
            return ''
        parts = urlsplit(text)
        if (parts.scheme or '').lower() != 'https':
            return ''
        host = (parts.hostname or '').lower()
        if not host or 'okooo.com' not in host:
            return ''
        return urlunsplit(('http', parts.netloc, parts.path, parts.query, parts.fragment))
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return ''


def _allow_insecure_ssl():
    """Only disable TLS verification when the operator explicitly opts in."""
    return str(os.environ.get('BLADE_ALLOW_INSECURE_SSL', '')).strip().lower() in (
        '1', 'true', 'yes', 'on',
    )


# 【全局】带代理自动降级的requests.get；默认校验TLS，必要时由环境变量显式开启兼容模式。
def safe_api_get(url, headers=None, timeout=20, params=None):
    """请求统一入口。欧洲库地址直接返回，不发请求、不打印。"""
    _u = str(url or "").lower()
    if "api-sports.io" in _u or "api-football" in _u:
        return None
    _verify_tls = not _allow_insecure_ssl()
    if not _verify_tls:
        import urllib3
        urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

    _proxies_list = _http_routes()
    _net_errors = (
        requests.exceptions.SSLError,
        requests.exceptions.ConnectionError,
        requests.exceptions.Timeout,
        requests.exceptions.ProxyError,
    )
    # 第一轮：HTTPS（代理可用才先走，失败后直连且不吃环境代理）
    for proxies in _proxies_list:
        try:
            r = requests.get(url, headers=headers, timeout=timeout,
                             proxies=cast(Any, proxies), verify=_verify_tls, params=params)
        except _net_errors:
            if proxies is not _DIRECT_PROXIES:
                _forget_dead_proxy()
            continue
        return r
    # 第二轮：仅澳客 https 降为 http。用 urlsplit 换协议，避免 url[8:] 切坏非标准地址。
    http_url = _downgrade_okooo_https(url)
    if http_url:
        for proxies in _proxies_list:
            try:
                r = requests.get(http_url, headers=headers, timeout=timeout,
                                 proxies=cast(Any, proxies), params=params)
            except _net_errors:
                if proxies is not _DIRECT_PROXIES:
                    _forget_dead_proxy()
                continue
            return r
    print(f"   ⚠️ [safe_api_get] 所有链路均失败，return None 让调用方降级: {str(url)[:80]}")
    return None

