def compute_lambda_bias_correction():
    """基于历史复盘数据自动计算λ偏差校准系数。
    统计所有已完赛比赛的 预期总进球(lambda_sum) vs 实际总进球(actual_total)，
    计算系统性偏差比率，返回校准乘数。
    """
    try:
        history = load_json(HISTORY_FILE) if os.path.exists(HISTORY_FILE) else {}
        if not history:
            return 1.0
        total_expected = 0.0
        total_actual = 0.0
        valid_count = 0
        if not isinstance(history, dict):
            print("   ⚠️ [λ偏差校准] 历史不是字典，无法计算，校准系数保持 1.0")
            return 1.0
        for fid, info in history.items():
            try:
                if not isinstance(info, dict) or info.get('status') != 'completed':
                    continue
                actual_score = info.get('actual_score', '')
                if not actual_score or '-' not in str(actual_score):
                    continue
                h, a = parse_score(actual_score)
                if h is None or a is None or h >= 9 or a >= 9:
                    continue
                lam_h = info.get('lambda_home') or info.get('lam_h')
                lam_a = info.get('lambda_away') or info.get('lam_a')
                if lam_h is None or lam_a is None:
                    continue
                expected_total = float(lam_h) + float(lam_a)
                if expected_total <= 0:
                    continue
                total_expected += expected_total
                total_actual += h + a
                valid_count += 1
            except (TypeError, ValueError, KeyError, ZeroDivisionError, OverflowError) as err:
                print(f"   ⚠️ [λ偏差校准] 场次 {fid} 跳过：{type(err).__name__}: {err}")
                continue
        if valid_count < 5:
            return 1.0
        if total_expected <= 0:
            print("   ⚠️ [λ偏差校准] 预期总进球为 0，不计算比率，校准系数保持 1.0")
            return 1.0
        bias_ratio = total_actual / total_expected
        correction = max(0.70, min(1.30, bias_ratio))
        correction = 1.0 + 0.6 * (correction - 1.0)
        return round(correction, 4)
    except (OSError, ValueError, TypeError, KeyError) as err:
        print(f"   ⚠️ [λ偏差校准] 历史读取失败：{type(err).__name__}: {err}。校准系数保持 1.0")
        return 1.0

# ================= 【竞彩足球官方比分范围】 =================
# 竞彩足球波胆玩法共计31个投注选项（不是31种比分）：
# 主胜13个选项 = 12种标准主胜比分 + 胜其它
# 平局5个选项 = 4种标准平局比分 + 平其它
# 客胜13个选项 = 12种标准客胜比分 + 负其它
# 所有分析必须严格限制在此31个选项内，不得超出！

# 主胜标准比分（12种）
JCZQ_HOME_WIN_SCORES = ['1-0', '2-0', '2-1', '3-0', '3-1', '3-2', '4-0', '4-1', '4-2', '5-0', '5-1', '5-2']
# 平局标准比分（4种）
JCZQ_DRAW_SCORES = ['0-0', '1-1', '2-2', '3-3']
# 客胜标准比分（12种）
JCZQ_AWAY_WIN_SCORES = ['0-1', '0-2', '1-2', '0-3', '1-3', '2-3', '0-4', '1-4', '2-4', '0-5', '1-5', '2-5']

# "其它"类别：除去上述标准比分外的所有同方向比分均视为"其它"
# 胜其它：如 6-0, 7-1, 6-2, 4-3, 5-3 等主队获胜但不在上述12种中的比分
# 平其它：如 4-4, 5-5 等平局但不在上述4种中的比分
# 负其它：如 0-6, 1-7, 2-6, 3-4, 3-5 等客队获胜但不在上述12种中的比分

# 28种标准比分集合
JCZQ_STANDARD_SCORES = JCZQ_HOME_WIN_SCORES + JCZQ_DRAW_SCORES + JCZQ_AWAY_WIN_SCORES
JCZQ_VALID_SET = set(JCZQ_STANDARD_SCORES)  # 用于快速查找标准比分

# 完整的31个竞彩投注选项（含"其它"类）
JCZQ_ALL_OPTIONS = JCZQ_STANDARD_SCORES + ['胜其它', '平其它', '负其它']  # 31个投注选项
JCZQ_ALL_OPTIONS_SET = set(JCZQ_ALL_OPTIONS)
# 安全比分解析辅助函数（处理"胜其它"/"平其它"/"负其它"）

# ================= 【全局统一比分解析工具函数】 =================
def parse_score(score_str):
    """统一比分字符串解析工具函数，全局唯一入口。
    返回 (home, away) 整数元组；解析失败或含'其它'返回 (None, None)。
    """
    if not score_str or '其它' in str(score_str):
        return None, None
    try:
        h, a = map(int, str(score_str).replace(':', '-').split('-'))
        return h, a
    except (ValueError, TypeError, AttributeError):
        return None, None
# ================================================================

def _safe_parse_score(score_str):
    """其它类返回代表分。数字比分解析失败返回 None，不记成 0-0。"""
    text = str(score_str or '')
    if '其它' in text:
        if '胜' in text:
            return (5, 0)
        if '平' in text:
            return (4, 4)
        return (0, 5)
    h, a = parse_score(score_str)
    if h is None or a is None:
        print(f"   ⚠️ [比分解析] 无法解析 {text!r}，不记成 0-0")
        return None
    return (h, a)


def _as_dict(value):
    """Return dict values as-is and normalize absent/invalid dynamic payloads to {}."""
    return value if isinstance(value, dict) else {}



def standardize_ou_line(raw_line):
    """将原始大小球线对齐到最近的标准盘口（0.25为最小单位）。
    
    标准盘口值: 1.5, 1.75, 2.0, 2.25, 2.5, 2.75, 3.0, 3.25, 3.5, 3.75, 4.0, ...
    
    Args:
        raw_line: float|None, 原始大小球盘口线（可能是多家公司平均值等非标准值）
    
    Returns:
        float|None: 标准化后的盘口线（0.25的倍数）。缺失或无法解析时返回 None。
    """
    if raw_line is None:
        return None
    try:
        raw_line = float(raw_line)
    except (ValueError, TypeError):
        return None
    if raw_line <= 0:
        return None
    # 四舍五入到最近的0.25
    standardized = round(raw_line * 4) / 4
    # 限制在合理范围内
    standardized = max(1.5, min(standardized, 6.0))
    return standardized

def standardize_ah_line(raw_line):
    """将原始亚盘线对齐到最近的标准盘口（0.25为最小单位）。
    标准盘口值: ..., -2.5, -2.25, -2.0, -1.75, -1.5, -1.25, -1.0, -0.75, -0.5, -0.25, 0, +0.25, +0.5, ...
    Args:
        raw_line: float|None, 原始亚盘盘口线（可能是多家公司平均值等非标准值）
    Returns:
        float|None: 标准化后的盘口线（0.25的倍数），输入None返回None
    """
    if raw_line is None:
        return None
    try:
        raw_line = float(raw_line)
    except (ValueError, TypeError):
        return None
    # 四舍五入到最近的0.25
    standardized = round(raw_line * 4) / 4
    # 限制在合理范围内
    standardized = max(-4.0, min(standardized, 4.0))
    return standardized

def jczq_classify_score(score_str):
    """将任意比分分类到竞彩足球官方31个投注选项之一
    返回: (jczq_option, category)
    jczq_option: 竞彩投注选项（如 '2-1' 或 '胜其它'）
    category: 'home_win', 'draw', 'away_win'
    """
    try:
        h, a = parse_score(score_str)
        if h is None or a is None:
            return None, None
        s = f"{h}-{a}"
        if s in JCZQ_VALID_SET:
            # 标准比分，直接返回
            if h > a:
                return s, 'home_win'
            elif h == a:
                return s, 'draw'
            else:
                return s, 'away_win'
        else:
            # 非标准比分 → 归入对应方向的"其它"选项
            if h > a:
                return '胜其它', 'home_win'
            elif h == a:
                return '平其它', 'draw'
            else:
                return '负其它', 'away_win'
    except (ValueError, TypeError):
        return score_str, 'unknown'


