class ModuleVerdict:
    """一赛一方案·模块独立判决数据契约
    
    每个分析模块针对每场比赛必须独立产出自己的推荐比分和方向，
    而不是简单地按概率排序取最高。每个模块的判决包含：
    - 推荐方向（主胜/平局/客胜）
    - 推荐比分（首选/次选）
    - 大小球判定
    - 判决依据（数理逻辑链，非概率排序）
    - 置信权重（该模块对本场比赛的适用度）
    - 庄家风控剥离标记（是否检测到庄家操控痕迹）
    """
    
    def __init__(self, module_name, direction='', first_score='', second_score='',
                 ou_verdict='', reasoning='', confidence=0.5,
                 bookmaker_manipulation_detected=False,
                 manipulation_details='', raw_data=None):
        self.module_name = module_name          # 模块名称
        self.direction = direction              # 'home'/'draw'/'away'
        self.first_score = first_score          # 首选比分
        self.second_score = second_score        # 次选比分
        self.ou_verdict = ou_verdict            # '大球'/'小球'/''
        self.reasoning = reasoning              # 数理逻辑推理链
        self.confidence = confidence            # 0.0~1.0 该模块对本场的适用置信度
        self.bookmaker_manipulation_detected = bookmaker_manipulation_detected  # 庄家操控检测
        self.manipulation_details = manipulation_details  # 操控细节
        self.raw_data = raw_data or {}          # 原始数据（供审计）
    
    def to_dict(self):
        return {
            'module': self.module_name,
            'direction': self.direction,
            'first_score': self.first_score,
            'second_score': self.second_score,
            'ou_verdict': self.ou_verdict,
            'reasoning': self.reasoning,
            'confidence': self.confidence,
            'manipulation_detected': self.bookmaker_manipulation_detected,
            'manipulation_details': self.manipulation_details,
        }
    
    def get_direction_label(self):
        """返回中文方向标签"""
        _map = {'home': '主胜', 'draw': '平局', 'away': '客胜'}
        return _map.get(self.direction, self.direction)


class OneMatchOnePlanCollector:
    """一赛一方案·模块判决收集器
    
    在 analyze_match 主流程中，各模块分析完成后将自己的独立判决
    注册到此收集器，最终由 UnifiedConvergenceArbitrator 统一仲裁。
    """
    
    def __init__(self, match_name='', fixture_id=''):
        self.match_name = match_name
        self.fixture_id = fixture_id
        self.verdicts = []  # List[ModuleVerdict]
        self._module_names = set()
        self.direction_lock_payload = {}
    
    def register(self, verdict):
        """注册一个模块的独立判决。方向锁存在时，比分和方向先收进提示方向。"""
        if not isinstance(verdict, ModuleVerdict):
            return
        payload = getattr(self, 'direction_lock_payload', None)
        # 压赔模块抓到冷门防范时保留原比分和原方向，供仲裁抬权。不写终裁 first_score。
        _keep_cold_hedge = (
            getattr(verdict, 'module_name', '') == '比分博弈与压赔矩阵'
            and bool(getattr(verdict, 'bookmaker_manipulation_detected', False))
        )
        try:
            if payload and DeepSeekAnalyzer is not None and not _keep_cold_hedge:
                _va, _vb = DeepSeekAnalyzer.snap_score_pair(verdict.first_score, verdict.second_score, payload)
                if (_va or '', _vb or '') != (verdict.first_score or '', verdict.second_score or ''):
                    print(f"   🔒 [方向锁] 模块投票 {verdict.module_name} {verdict.first_score or '-'}/{verdict.second_score or '-'} → {_va or '-'}/{_vb or '-'}")
                    verdict.first_score = _va or ''
                    verdict.second_score = _vb or ''
                _vlab = DeepSeekAnalyzer._classify_score_wdl(_va)[1] if _va else ''
                _vdir = {'胜': 'home', '平': 'draw', '负': 'away'}.get(_vlab)
                if _vdir and verdict.direction != _vdir:
                    verdict.direction = _vdir
        except Exception as _v_lock_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [方向锁] 模块投票未收口: {_v_lock_err}")
        self.verdicts.append(verdict)
        self._module_names.add(verdict.module_name)
    
    def get_all(self):
        return self.verdicts
    
    def get_by_module(self, module_name):
        for v in self.verdicts:
            if v.module_name == module_name:
                return v
        return None
    
    def module_count(self):
        return len(self._module_names)
    
    def summary(self):
        """生成模块判决摘要"""
        lines = [f"📋 一赛一方案收集器: {self.match_name} ({len(self.verdicts)}个模块参与)"]
        for v in self.verdicts:
            lines.append(
                f"  [{v.module_name}] 方向={v.get_direction_label()} "
                f"比分={v.first_score}/{v.second_score} "
                f"大小球={v.ou_verdict or '-'} "
                f"置信={v.confidence:.2f} "
                f"{'⚠️庄操' if v.bookmaker_manipulation_detected else ''}"
            )
        return "\n".join(lines)


def ou_verdict_from_score_safe(score_str, ou_line):
    """按比分和盘口线判大小球。OverUnderEngine 尚未定义时返回空串。"""
    try:
        fn = OverUnderEngine.ou_verdict_from_score
    except NameError:
        return ''
    try:
        return fn(score_str, ou_line) or ''
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return ''


class UnifiedConvergenceArbitrator:
    """统一收敛仲裁引擎
    
    核心范式：不以概率大小作为判定比分的最终标准，
    而是以数理逻辑的合理性及对庄家风控剥离为基础。
    
    仲裁三层机制：
    1. 方向只读特征无关方向锁（五道闸门、V16.2 平局刹车与 V16.1 浅差熔断）；模块加权投票只作对照
    2. 比分逻辑一致性校验层：检验推荐比分与盘口/方向的数理自洽性
    3. 收敛层：锁定方向内只沿已有比分收口，不写 first_score
    
    判定原则：
    - 庄家操控检测到的模块，其"反向"判决权重提升（剥离庄家意图）
    - 数理逻辑自洽性 > 概率大小（比分必须与盘口/方向物理自洽）
    - 多模块逻辑一致的结论 > 单一模块的高概率输出
    """
    
    # 模块基础权重（基于数理逻辑可靠性而非历史命中率）
    MODULE_BASE_WEIGHTS: ClassVar[dict[str, float]] = {
        'RTM顺位追踪矩阵': 1.0,          # 位移极差=纯数理逻辑，不可伪造
        'DPS动态提权选择器': 0.7,          # 聚类分析=数理逻辑
        'V-Entropy量化引擎': 0.85,         # 信息熵=纯数理逻辑
        '泊松期望模型': 0.6,               # 概率模型，但受λ偏差影响
        '博弈策略专家系统': 0.0,           # 已关闭，不投票
        '拓扑博弈论过滤器': 0.9,           # 非线性拓扑=数理逻辑
        'BetfairSqueeze分析器': 1.05,      # 资金流=硬数据，庄家风控核心（原0.95→1.05，基于高流动性深度穿盘验证提权）
        '博弈动能雷达': 0.7,               # IBI导数=数理逻辑
        'AI预测引擎': 0.0,                # 已关闭，不投票
        '反庄家引擎': 0.85,                # 庄家风控剥离核心模块
        '比分博弈与压赔矩阵': 0.85,        # 市均对竞彩的硬赔偏离，只投票不写终裁
    }
    @classmethod
    def _lock_side_and_picks(cls, match_context):
        """读特征无关方向锁。没有锁时返回空，不另投方向。"""
        ctx = match_context if isinstance(match_context, dict) else {}
        raw_payload = ctx.get('direction_lock_payload')
        payload = raw_payload if isinstance(raw_payload, dict) else {}
        raw_lock = payload.get('direction_lock')
        lock = raw_lock if isinstance(raw_lock, dict) else {}
        raw_ctx_lock = ctx.get('direction_lock')
        if not lock and isinstance(raw_ctx_lock, dict):
            lock = raw_ctx_lock
        raw = str(lock.get('direction') or '')
        side = {'胜': 'home', '平': 'draw', '负': 'away', 'home': 'home', 'draw': 'draw', 'away': 'away'}.get(raw, '')
        picks = []
        for score in list(lock.get('v15_pick_scores') or lock.get('scores') or []):
            text = str(score or '').replace(':', '-').strip()
            if text and text not in picks:
                picks.append(text)
        return side, picks, lock

    @classmethod
    def _v1631_lock_speech(cls, lock):
        """只读已经落锁的 V16.31 日志，话术取引擎模板。不改方向，不写 first_score。"""
        lock = lock if isinstance(lock, dict) else {}
        raw_pack = lock.get('v1623_high_entropy')
        pack = raw_pack if isinstance(raw_pack, dict) else {}
        from blade_deepseek_pipeline import V1631StandardUnifiedEngine
        templates = V1631StandardUnifiedEngine._TEMPLATES
        lock_type = str(pack.get('lock_type') or '')
        if not lock_type:
            logged = str(lock.get('log_code') or '')
            if logged in templates:
                lock_type = logged
        if not lock_type:
            return '', ''
        return lock_type, templates.get(lock_type, V1631StandardUnifiedEngine._TEMPLATE_FALLBACK)

    @classmethod
    def _mean_gap_ratio_audit(cls, match_context, lock):
        """投票结算前复述引擎的 5.0/1.35 量级分档。不改 voted_direction，不写 first_score。"""
        from blade_deepseek_pipeline import audit_mean_gap_ratio
        ctx = match_context if isinstance(match_context, dict) else {}
        payload = ctx.get('direction_lock_payload') if isinstance(ctx.get('direction_lock_payload'), dict) else {}
        if not payload and isinstance(ctx.get('ds_payload'), dict):
            payload = ctx.get('ds_payload')
        return audit_mean_gap_ratio(lock if isinstance(lock, dict) else {}, payload)

    @classmethod
    def _blank_candidate(cls):
        return {
            'logic_score': 0.0, 'supporters': [],
            'direction_consistent': False, 'ou_consistent': False,
            'ah_consistent': False, 'reasoning': [],
        }
    
    @classmethod
    def arbitrate(cls, collector, match_context=None):
        """执行统一收敛仲裁
        
        Args:
            collector: OneMatchOnePlanCollector 实例
            match_context: dict 比赛上下文（盘口/OU线等）
            
        Returns:
            dict: {
                'lock_type': str,            # V16.31 审计日志，只读方向锁
                'lock_speech': str,          # 同一套话术模板原句
                'final_direction': str,      # 最终方向
                'final_first_score': str,    # 最终首选比分
                'final_second_score': str,   # 最终次选比分
                'final_ou': str,             # 最终大小球
                'convergence_score': float,  # 收敛度 0-1
                'arbitration_log': str,      # 仲裁日志
                'module_votes': dict,        # 各模块投票明细
                'logic_consistency': dict,   # 逻辑一致性检验结果
                'manipulation_stripped': bool, # 是否执行了庄家风控剥离
                'mean_gap_ratio_audit': dict,  # 5.0/1.35 量级分档，不改方向
            }
        """
        match_context = match_context or {}
        verdicts = collector.get_all()
        
        if not verdicts:
            return cls._fallback_result("无模块判决输入")
        
        log_lines = ["═══ 统一收敛仲裁引擎 ═══"]
        
        # ═══ 第一层：方向投票 + 庄家风控剥离加权 ═══
        direction_votes = {'home': 0.0, 'draw': 0.0, 'away': 0.0}
        manipulation_modules = []
        
        for v in verdicts:
            if not v.direction or v.direction not in direction_votes:
                continue
            
            # 基础权重
            base_w = cls.MODULE_BASE_WEIGHTS.get(v.module_name, 0.5)
            # 置信度调制
            effective_w = base_w * v.confidence
            
            # 【庄家风控剥离核心逻辑】
            # 当模块检测到庄家操控时，该模块的判决具有更高的"反向价值"
            # 即：庄家想让你看到的方向是陷阱，真实方向是庄家恐惧的方向
            if v.bookmaker_manipulation_detected:
                manipulation_modules.append(v.module_name)
                # 操控检测模块的权重提升30%（其判断更接近剥离后的真相）
                effective_w *= 1.3
            
            direction_votes[v.direction] += effective_w
        
        # 方向投票结果
        total_vote = sum(direction_votes.values()) or 1.0
        direction_probs = {k: v / total_vote for k, v in direction_votes.items()}
        module_direction = max(direction_votes, key=lambda key: direction_votes[key])
        direction_margin = direction_probs[module_direction] - sorted(direction_probs.values())[-2] if len([v for v in direction_probs.values() if v > 0]) > 1 else direction_probs[module_direction]
        lock_side, lock_picks, lock = cls._lock_side_and_picks(match_context)
        ratio_audit = cls._mean_gap_ratio_audit(match_context, lock)
        from convergence_arbitrator import (
            ou_from_scores,
            resolve_cores,
            resolve_direction,
        )
        # resolve_direction 现在按文档返回 (direction, resolution)，但历史版本只返回字符串。
        # 两种形状都吃下，绝不因为解包失败而整段降级。
        _vote_ret = resolve_direction(lock_side, module_direction)
        if isinstance(_vote_ret, tuple) and len(_vote_ret) == 2:
            voted_direction, direction_resolution = _vote_ret
        else:
            voted_direction, direction_resolution = str(_vote_ret or ''), {}
        if not isinstance(direction_resolution, dict):
            direction_resolution = {}
        adapted = resolve_cores(lock if lock_side else {}, lock_picks if lock_side else [])
        tuple(adapted.get('cover') or ())
        tuple(adapted.get('hedge') or ())
        
        log_lines.append(f"[方向投票] 主胜={direction_probs.get('home',0):.2%} "
                        f"平局={direction_probs.get('draw',0):.2%} "
                        f"客胜={direction_probs.get('away',0):.2%} | 模块{module_direction} | 输出{voted_direction}")
        log_lines.append("[均差比值分档] {}".format(ratio_audit.get('fuse')))
        log_lines.append("[2倍邻近] {}".format(ratio_audit.get('neighbor')))
        if ratio_audit.get('inside_band') and module_direction != 'draw':
            log_lines.append("[均差比值分档] 高度混淆已命中。模块票不因此改平，输出仍按方向锁。")
        if direction_resolution.get('conflict'):
            log_lines.append(
                "[方向容错] 模块方向与方向锁不一致，输出只保留方向锁，模块票降为对照。"
            )
        else:
            log_lines.append("[方向容错] 输出与方向锁一致。" if lock_side else "[方向容错] 本场没有方向锁，模块方向只作对照。")
        log_lines.append(
            "[均差余地] 模式={} | 零封权重={} | 打击权重={} | 技能={}".format(
                adapted.get('mode'),
                adapted.get('clean_weight'),
                adapted.get('attack_weight'),
                "/".join(adapted.get('skills') or []),
            )
        )
        log_lines.append(f"[庄家操控检测] {len(manipulation_modules)}个模块触发: {manipulation_modules or '无'}")
        
        # ═══ 第二层：比分逻辑一致性校验 ═══
        # 收集所有模块推荐的比分，按数理逻辑自洽性评分
        score_candidates = {}  # score -> {logic_score, supporters, reasoning}
        
        ou_line = match_context.get('ou_line')
        # 平手盘 ah=0.0 是真实盘口：`or` 会让它落到另一个键甚至 None。
        _ah_ctx = match_context.get('ah_line')
        ah_line = _ah_ctx if _ah_ctx is not None else match_context.get('asian_handicap')
        
        for v in verdicts:
            for score_str in [v.first_score, v.second_score]:
                if not score_str or '其它' in str(score_str):
                    # "其它"类特殊处理
                    if score_str and score_str not in score_candidates:
                        score_candidates[score_str] = cls._blank_candidate()
                    if score_str:
                        score_candidates[score_str]['supporters'].append(v.module_name)
                    continue
                    
                if score_str not in score_candidates:
                    score_candidates[score_str] = cls._blank_candidate()
                
                score_candidates[score_str]['supporters'].append(v.module_name)
                if (
                    v.module_name == '比分博弈与压赔矩阵'
                    and v.bookmaker_manipulation_detected
                    and ScoreOddsAnalyzer.row_is_cold_hedge(score_str, v.raw_data)
                ):
                    score_candidates[score_str]['cold_hedge'] = True
                if v.reasoning:
                    score_candidates[score_str]['reasoning'].append(f"[{v.module_name}]{v.reasoning[:60]}")
        
        # 对每个候选比分执行数理逻辑一致性校验
        for score_str, info in score_candidates.items():
            logic_bonus = 0.0
            
            # 校验1：方向一致性（比分方向是否与投票方向一致）
            try:
                if '其它' in str(score_str):
                    if '胜' in str(score_str):
                        s_dir = 'home'
                    elif '负' in str(score_str):
                        s_dir = 'away'
                    else:
                        s_dir = 'draw'
                else:
                    h, a = parse_score(score_str)
                    if h is None or a is None:
                        continue
                    s_dir = 'home' if h > a else ('draw' if h == a else 'away')
                
                if s_dir == voted_direction:
                    info['direction_consistent'] = True
                    logic_bonus += 0.5  # 方向一致=数理逻辑自洽
                elif not lock_side and direction_margin < 0.15:
                    # 没有方向锁且投票接近时，允许次优方向
                    logic_bonus += 0.1
            except (ValueError, IndexError, TypeError):
                pass
            
            # 校验2：大小球一致性（比分总进球与OU线的物理关系）
            try:
                if ou_line is not None and '其它' not in str(score_str):
                    ou_val = float(ou_line)
                    h, a = parse_score(score_str)
                    if h is None or a is None:
                        continue
                    total = h + a
                    # 大小球投票
                    ou_votes = {'大球': 0, '小球': 0}
                    for v in verdicts:
                        if v.ou_verdict in ou_votes:
                            ou_votes[v.ou_verdict] += cls.MODULE_BASE_WEIGHTS.get(v.module_name, 0.5) * v.confidence
                    voted_ou = max(ou_votes, key=lambda key: ou_votes[key]) if any(ou_votes.values()) else ''
                    
                    # 【OverUnderEngine驱动】精确判定投票与比分的一致性
                    _score_ou = ou_verdict_from_score_safe(score_str, ou_val)  # 【Bug4修复】s → score_str
                    if voted_ou and voted_ou == _score_ou:
                        info['ou_consistent'] = True
                        logic_bonus += 0.3
                    elif not voted_ou:
                        # 无明确大小球判定时，靠近OU线的比分更合理
                        if abs(total - ou_val) <= 1.0:
                            info['ou_consistent'] = True
                            logic_bonus += 0.2
                    else:
                        # 大小球方向与比分矛盾：扣分
                        logic_bonus -= 0.2
            except (ValueError, TypeError):
                pass
            
            # 校验3：让球一致性（比分净胜球与亚盘的物理关系）
            try:
                if ah_line is not None and '其它' not in str(score_str):
                    ah_val = float(ah_line)
                    h, a = parse_score(score_str)
                    if h is None or a is None:
                        continue
                    net = h - a
                    # 亚盘方向一致性（主让为负）
                    if ah_val < -0.5 and net >= 1 or ah_val > 0.5 and net <= -1:
                        info['ah_consistent'] = True
                        logic_bonus += 0.3
                    elif abs(ah_val) <= 0.5 and abs(net) <= 1:
                        info['ah_consistent'] = True
                        logic_bonus += 0.2
                    elif abs(ah_val) > 1.5:
                        # 深盘场景：净胜球必须覆盖盘口深度
                        needed_net = int(abs(ah_val))
                        if ah_val < 0 and net >= needed_net:
                            info['ah_consistent'] = True
                            logic_bonus += 0.5  # 深盘覆盖=强逻辑自洽
                        elif ah_val > 0 and (-net) >= needed_net:
                            info['ah_consistent'] = True
                            logic_bonus += 0.5
                        else:
                            logic_bonus -= 0.3  # 深盘不覆盖=逻辑矛盾
            except (ValueError, TypeError):
                pass
            
            # 校验4：多模块支持度（被多个独立模块推荐=逻辑收敛）
            supporter_count = len(set(info['supporters']))
            if supporter_count >= 4:
                logic_bonus += 0.4  # 4+模块共识=强收敛
            elif supporter_count >= 3:
                logic_bonus += 0.25
            elif supporter_count >= 2:
                logic_bonus += 0.1
            info['logic_score'] += logic_bonus
        sorted_candidates = sorted(
            score_candidates.items(),
            key=lambda x: x[1]['logic_score'],
            reverse=True
        )
        final_first = ''
        final_second = ''
        for v in verdicts:
            token = str(v.first_score or '').strip()
            if not token:
                continue
            final_first = token
            second = str(v.second_score or '').strip()
            final_second = '' if second == token else second
            break
        
        # 大小球最终判定
        final_ou = ou_from_scores(final_first, final_second, ou_line)
        ou_votes_final = {'source': 'score_vs_line', 'verdict': final_ou}
        
        # 计算收敛度
        if sorted_candidates:
            top_score = sorted_candidates[0][1]['logic_score']
            second_score_val = sorted_candidates[1][1]['logic_score'] if len(sorted_candidates) > 1 else 0
            convergence = min(1.0, top_score / max(top_score + second_score_val, 0.01))
        else:
            convergence = 0.0
        
        # 逻辑一致性汇总
        logic_consistency = {
            'direction_unanimous': direction_margin > 0.3,
            'direction_margin': round(direction_margin, 3),
            'first_score_direction_ok': score_candidates.get(final_first, {}).get('direction_consistent', False),
            'first_score_ou_ok': score_candidates.get(final_first, {}).get('ou_consistent', False),
            'first_score_ah_ok': score_candidates.get(final_first, {}).get('ah_consistent', False),
            'supporter_count_first': len(set(score_candidates.get(final_first, {}).get('supporters', []))),
            'total_modules': collector.module_count(),
        }
        
        log_lines.append("[比分逻辑评分] Top5: " + 
                        " | ".join(f"{s}={info['logic_score']:.2f}({'✓' if info.get('direction_consistent') else '✗'}方向"
                                   f"{'✓' if info.get('ou_consistent') else '✗'}OU"
                                   f"{'✓' if info.get('ah_consistent') else '✗'}AH"
                                   f" {len(set(info['supporters']))}模块)"
                                   for s, info in sorted_candidates[:5]))
        log_lines.append(f"[最终锁定] 首选={final_first} 次选={final_second} "
                        f"方向={voted_direction} 大小球={final_ou} "
                        f"收敛度={convergence:.2%}")
        log_lines.append(f"[庄家风控剥离] {'已执行' if manipulation_modules else '未触发'}")
        lock_type, lock_speech = cls._v1631_lock_speech(lock)
        if lock_type:
            log_lines.append(f"[V16.31审计日志] {lock_type}")
            log_lines.append(f"[架构解析] {lock_speech}")
        
        return {
            'lock_type': lock_type,
            'lock_speech': lock_speech,
            'final_direction': voted_direction,
            'final_first_score': final_first,
            'final_second_score': final_second,
            'final_ou': final_ou,
            'convergence_score': round(convergence, 4),
            'arbitration_log': "\n".join(log_lines),
            'module_votes': {
                'direction_probs': direction_probs,
                'ou_votes': ou_votes_final,
                'score_rankings': [(s, info['logic_score'], len(set(info['supporters'])))
                                   for s, info in sorted_candidates[:10]],
            },
            'logic_consistency': logic_consistency,
            'manipulation_stripped': bool(manipulation_modules),
            'manipulation_modules': manipulation_modules,
            'primary_core_scores': [],
            'secondary_attack_scores': [],
            'direction_resolution': direction_resolution,
            'active_skills': list(adapted.get('skills') or []),
            'skill_space': adapted.get('skill_space'),
            'core_mode': adapted.get('mode'),
            'mean_gap_ratio_audit': ratio_audit,
            'writes_first_score': False,
        }
    
    @classmethod
    def _fallback_result(cls, reason):
        return {
            'lock_type': '',
            'lock_speech': '',
            'final_direction': '',
            'final_first_score': '',
            'final_second_score': '',
            'final_ou': '',
            'convergence_score': 0.0,
            'arbitration_log': f"[仲裁降级] {reason}",
            'module_votes': {},
            'logic_consistency': {},
            'manipulation_stripped': False,
            'manipulation_modules': [],
            'mean_gap_ratio_audit': {
                'available': False,
                'inside_band': False,
                'changes_direction': False,
                'forces_draw': False,
                'writes_first_score': False,
                'fuse': '胜或负均差缺失，不做1.35比值判定。不改锁定方向。',
            },
        }


class ScoreOddsAnalyzer:
    """市均对竞彩的比分偏离。压赔深度达到规则表门槛才记防范。不写 first_score。"""

    def __init__(self, df_scores, min_depth=None):
        self.df: Any
        if df_scores is None:
            self.df = pd.DataFrame()
        elif isinstance(df_scores, pd.DataFrame):
            self.df = df_scores.copy()
        else:
            self.df = pd.DataFrame(list(df_scores))
        if min_depth is None:
            try:
                import json as _json_press
                _rule_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'blade_rule_table.json')
                with open(_rule_path, encoding='utf-8') as _rule_f:
                    min_depth = (_json_press.load(_rule_f).get('institution_press') or {}).get('min_depth', 0.03)
            except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                min_depth = 0.03
        try:
            self.min_depth = float(min_depth)
        except (TypeError, ValueError):
            self.min_depth = 0.03

    @staticmethod
    def frame_from_odds(market_avg, lottery_odds):
        market = market_avg if isinstance(market_avg, dict) else {}
        lottery = lottery_odds if isinstance(lottery_odds, dict) else {}
        keys = set()
        norm_market = {}
        norm_lottery = {}
        for raw, bucket, src in (
            (market, norm_market, market),
            (lottery, norm_lottery, lottery),
        ):
            for key, val in src.items():
                score = str(key or '').replace(':', '-').strip()
                if not score:
                    continue
                keys.add(score)
                bucket[score] = val
        rows = []
        for score in sorted(keys):
            rows.append({
                'score': score,
                'market_avg': norm_market.get(score),
                'lottery_odds': norm_lottery.get(score),
            })
        return pd.DataFrame(rows)

    @staticmethod
    def _outcome_group(score):
        text = str(score or '').replace(':', '-').strip()
        if '胜' in text and '负' not in text:
            return '胜'
        if '负' in text:
            return '负'
        if '平' in text:
            return '平'
        if '-' not in text:
            return ''
        try:
            home_s, away_s = text.split('-', 1)
            home_i, away_i = int(home_s), int(away_s)
        except (TypeError, ValueError):
            return ''
        if home_i > away_i:
            return '胜'
        if home_i == away_i:
            return '平'
        return '负'

    @staticmethod
    def _is_cold_hedge(score, market, deviation, suppressed):
        """高赔或闷平被压低，视为庄家隐性防范。热门浅压不算。"""
        if not suppressed:
            return False
        text = str(score or '').strip()
        try:
            market_f = float(market)
            dev = float(deviation)
        except (TypeError, ValueError):
            return False
        if text in {'0-0', '1-1', '2-2', '3-3'}:
            return True
        return market_f >= 8.5 and dev >= 0.08

    @staticmethod
    def row_is_cold_hedge(score, raw_data):
        text = str(score or '').strip()
        for rec in raw_data or []:
            if isinstance(rec, dict) and str(rec.get('score') or '') == text and rec.get('is_cold_hedge'):
                return True
        return False

    def run_full_analysis(self):
        if self.df is None or self.df.empty:
            return pd.DataFrame()
        frame = self.df.copy()
        if 'score' not in frame.columns:
            return pd.DataFrame()
        for col in ('market_avg', 'lottery_odds', 'outcome_group'):
            if col not in frame.columns:
                frame[col] = None
        records = []
        for row in frame.to_dict(orient='records'):
            score = str(row.get('score') or '').replace(':', '-').strip()
            if not score:
                continue
            try:
                market = float(row.get('market_avg'))
                lottery = float(row.get('lottery_odds'))
            except (TypeError, ValueError):
                continue
            if market <= 1.0 or lottery <= 1.0:
                continue
            deviation = (lottery - market) / lottery
            suppressed = market < lottery and deviation >= self.min_depth
            cold_hedge = self._is_cold_hedge(score, market, deviation, suppressed)
            if cold_hedge:
                signal = '恶意压赔防范'
            elif suppressed and market <= 8.5:
                signal = '焦点高热压榨'
            elif suppressed and deviation >= 0.08:
                signal = '深度压赔防范'
            elif suppressed:
                signal = '压赔防范'
            else:
                signal = '抽水标准'
            outcome = str(row.get('outcome_group') or '').strip() or self._outcome_group(score)
            records.append({
                'score': score,
                'outcome_group': outcome,
                'market_avg': market,
                'lottery_odds': lottery,
                'deviation_rate': deviation,
                'is_suppressed': bool(suppressed),
                'is_cold_hedge': bool(cold_hedge),
                'signal_type': signal,
            })
        if not records:
            return pd.DataFrame()
        out = pd.DataFrame(records)
        out['_sup'] = out['is_suppressed'].astype(int)
        out['_ord'] = out.apply(
            lambda r: -float(r['deviation_rate']) if r['is_suppressed'] else abs(float(r['deviation_rate'])),
            axis=1,
        )
        out = out.sort_values(['_sup', '_ord'], ascending=[False, True]).drop(columns=['_sup', '_ord'])
        return out.reset_index(drop=True)


class ScoreOddsAnalyzerModule:
    """比分赔率偏离分析的一赛一方案适配器。只向收集器投票，不写终裁比分。"""

    module_name = '比分博弈与压赔矩阵'

    @staticmethod
    def _direction(score, outcome):
        mapped = {
            '胜': 'home', '平': 'draw', '负': 'away',
            '主胜': 'home', '平局': 'draw', '客胜': 'away',
        }.get(str(outcome or '').strip())
        if mapped:
            return mapped
        group = ScoreOddsAnalyzer._outcome_group(score)
        return {'胜': 'home', '平': 'draw', '负': 'away'}.get(group, '')

    @staticmethod
    def _pickable(score):
        text = str(score or '').strip()
        if not text or '其它' in text:
            return False
        blocked = {'4-0', '4-1', '4-2', '0-4', '1-4', '2-4'}
        try:
            blocked |= set(JCZQ_MACRO_BAIT_SCORES)
        except NameError:
            pass
        return text not in blocked

    @classmethod
    def analyze(cls, match_data, df_scores):
        if df_scores is None:
            return None
        analyzer = ScoreOddsAnalyzer(df_scores)
        res_df = cast(Any, analyzer.run_full_analysis())
        if res_df is None or res_df.empty:
            return None
        usable = res_df[res_df['score'].map(cls._pickable)]
        if usable.empty:
            return None
        signal = usable['signal_type'].fillna('').astype(str)
        suppressed_items = usable[usable['is_suppressed'] | signal.str.contains('压榨|防范', regex=True)]
        if 'is_cold_hedge' not in usable.columns:
            usable = usable.copy()
            usable['is_cold_hedge'] = False
        cold_items = suppressed_items[suppressed_items['is_cold_hedge']] if not suppressed_items.empty else suppressed_items
        reasoning_parts = []
        manipulation_detected = not cold_items.empty
        if not suppressed_items.empty:
            top = suppressed_items.iloc[0]
            first_score = str(top['score'])
            direction = cls._direction(first_score, top.get('outcome_group'))
            reasoning_parts.append(
                f"检测到比分 {first_score} 出现异常压赔"
                f"（市均={float(top['market_avg']):.2f}, 竞彩={float(top['lottery_odds']):.2f}, "
                f"偏离率={float(top['deviation_rate']):.2%}），方向={direction}。"
            )
            if manipulation_detected:
                reasoning_parts.append('冷门比分被压低，仲裁按庄家风控剥离提升该票权重。')
            rest = suppressed_items[suppressed_items['score'] != first_score]
            if manipulation_detected and not bool(top.get('is_cold_hedge')) and not cold_items.empty:
                second_score = str(cold_items.iloc[0]['score'])
            elif not rest.empty:
                second_score = str(rest.iloc[0]['score'])
            else:
                others = usable[usable['score'] != first_score]
                second_score = str(others.iloc[0]['score']) if not others.empty else ''
        else:
            first_score = str(usable.iloc[0]['score'])
            direction = cls._direction(first_score, usable.iloc[0].get('outcome_group'))
            others = usable[usable['score'] != first_score]
            second_score = str(others.iloc[0]['score']) if not others.empty else ''
            reasoning_parts.append('盘口抽水标准，未检测到恶性压赔，按基础偏离度排序选取。')
        if not direction:
            return None
        ou_line = None
        if isinstance(match_data, dict):
            ou_line = match_data.get('ou_line')
        ou_verdict = ''
        if ou_line is not None:
            ou_verdict = ou_verdict_from_score_safe(first_score, ou_line) or ''
        return ModuleVerdict(
            module_name=cls.module_name,
            direction=direction,
            first_score=first_score,
            second_score=second_score,
            ou_verdict=ou_verdict,
            reasoning=' | '.join(reasoning_parts),
            confidence=0.88 if manipulation_detected else 0.55,
            bookmaker_manipulation_detected=manipulation_detected,
            manipulation_details=f"识别到 {len(suppressed_items)} 个异常偏离比分选项。",
            raw_data=res_df.to_dict(orient='records'),
        )


def run_match_analysis_pipeline(match_id, match_context, raw_score_odds_list, collector=None):
    """把比分压赔矩阵注册进一赛一方案收集器，再交给统一收敛仲裁。

    其他模块应先注册到同一个 collector。本函数不写 first_score。
    """
    match_context = match_context if isinstance(match_context, dict) else {}
    home = str(match_context.get('home_team') or '').strip()
    away = str(match_context.get('away_team') or '').strip()
    match_name = str(match_context.get('match_name') or '').strip() or f"{home} vs {away}".strip()
    if collector is None:
        collector = OneMatchOnePlanCollector(
            match_name=match_name,
            fixture_id=str(match_id or ''),
        )
    lock_payload = match_context.get('direction_lock_payload')
    if isinstance(lock_payload, dict) and not getattr(collector, 'direction_lock_payload', None):
        collector.direction_lock_payload = lock_payload
    if isinstance(raw_score_odds_list, pd.DataFrame):
        df_scores = raw_score_odds_list.copy()
    else:
        df_scores = pd.DataFrame(list(raw_score_odds_list or []))
    verdict_odds = ScoreOddsAnalyzerModule.analyze(match_context, df_scores)
    if verdict_odds:
        collector.register(verdict_odds)
    final_arbitration_result = UnifiedConvergenceArbitrator.arbitrate(collector, match_context)
    if isinstance(final_arbitration_result, dict):
        final_arbitration_result['writes_first_score'] = False
    return final_arbitration_result


