    @staticmethod
    def from_topology_filter(topo_gt_tag_map, pool15_enriched=None, ou_line=None, betfair_volume=None):
        """从拓扑博弈论过滤器产出独立判决
        
        拓扑判决逻辑（非线性拓扑，非概率）：
        - HIDDEN_CORE_ANCHOR = 被庄家深度掩护的真实核心 → 推荐
        - POISON_BAIT = 庄家投毒诱饵 → 剥离
        - STABLE_ANCHOR = 收敛锚点 → 辅助确认
        
        【新增】流动性门槛检测：当必发交易量低于阈值时降低置信度，
        防止小流动性赛事的噪音数据干扰博弈论判断。
        """
        if not topo_gt_tag_map or not isinstance(topo_gt_tag_map, dict):
            return None
        
        try:
            hidden_cores = [s for s, t in topo_gt_tag_map.items() if t == 'HIDDEN_CORE_ANCHOR']
            poison_baits = [s for s, t in topo_gt_tag_map.items() if t == 'POISON_BAIT']
            stable_anchors = [s for s, t in topo_gt_tag_map.items() if t == 'STABLE_ANCHOR']
            
            # 首选：隐性核心铁锚（庄家掩护的真实通道）
            first_score = hidden_cores[0] if hidden_cores else (stable_anchors[0] if stable_anchors else '')
            second_score = hidden_cores[1] if len(hidden_cores) > 1 else (stable_anchors[0] if stable_anchors and stable_anchors[0] != first_score else '')
            
            if not first_score:
                return None
            
            # 方向
            direction = ''
            if first_score and '-' in first_score and '其它' not in first_score:
                h, a = parse_score(first_score)
                if h is not None and a is not None:
                    direction = 'home' if h > a else ('draw' if h == a else 'away')
            
            # 大小球【OverUnderEngine驱动】
            ou_verdict = ''
            if first_score and '-' in first_score and '其它' not in first_score:
                ou_verdict = ou_verdict_from_score_safe(first_score, ou_line)
            
            # 庄家操控检测：有毒饵=操控
            manipulation = len(poison_baits) >= 2
            
            # 【新增·流动性门槛检测】低流动性时降低拓扑博弈论置信度
            _topo_confidence = 0.85
            _topo_reasoning_suffix = ''
            _bf_vol = float(betfair_volume or 0)
            if 0 < _bf_vol < LIQUIDITY_THRESHOLD_VOLUME:
                _topo_confidence *= LIQUIDITY_LOW_CONFIDENCE_FACTOR
                _topo_reasoning_suffix = f' | ⚠️低流动性({_bf_vol:.0f}万<{LIQUIDITY_THRESHOLD_VOLUME:.0f}万)置信度降权'
            
            return ModuleVerdict(
                module_name='拓扑博弈论过滤器',
                direction=direction,
                first_score=first_score,
                second_score=second_score,
                ou_verdict=ou_verdict,
                reasoning=f"拓扑非线性：隐性核心={hidden_cores[:3]} 毒饵={poison_baits[:3]}{_topo_reasoning_suffix}",
                confidence=_topo_confidence,
                bookmaker_manipulation_detected=manipulation,
                manipulation_details=f"毒饵{len(poison_baits)}个" if manipulation else '',
                raw_data={'hidden': hidden_cores, 'poison': poison_baits, 'stable': stable_anchors}
            )
        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [一赛一方案·拓扑过滤器适配] 异常: {e}")
            return None
    
    @staticmethod
    def from_betfair_squeeze(betfair_data, pool15_enriched=None, ou_line=None):
        """从BetfairSqueeze分析器产出独立判决
        
        Betfair判决逻辑（资金流硬数据，非概率）：
        - 庄家死亡敞口方向 = 庄家最恐惧的真实方向
        - 陷阱方向 = 庄家诱导散户追逐的方向（必须剥离）
        """
        if not betfair_data or not isinstance(betfair_data, dict):
            return None
        if not betfair_data.get('available'):
            return None
        
        try:
            squeeze_status = betfair_data.get('squeeze_status', '')
            true_dir = betfair_data.get('squeeze_true_direction', '')
            trap_dir = betfair_data.get('squeeze_trap_direction', '')
            
            # 方向：庄家恐惧方向=真实方向
            direction = ''
            if true_dir in ('home', 'draw', 'away'):
                direction = true_dir
            elif betfair_data.get('direction'):
                direction = betfair_data['direction']
            
            if not direction:
                return None
            
            # 从pool15中选与方向一致的最佳比分
            first_score = ''
            second_score = ''
            if pool15_enriched:
                dir_scores = []
                for item in pool15_enriched:
                    s = item.get('score', '')
                    if not s or '其它' in s:
                        continue
                    try:
                        h, a = parse_score(s)
                        if h is None or a is None:
                            continue
                        s_dir = 'home' if h > a else ('draw' if h == a else 'away')
                        if s_dir == direction:
                            dir_scores.append((s, float(item.get('theory', 0))))
                    except (ValueError, IndexError):
                        continue
                dir_scores.sort(key=lambda x: x[1], reverse=True)
                if dir_scores:
                    first_score = dir_scores[0][0]
                if len(dir_scores) > 1:
                    second_score = dir_scores[1][0]
            
            # 大小球
            ou_verdict = ''
            if first_score and '-' in first_score and '其它' not in first_score:
                ou_verdict = ou_verdict_from_score_safe(first_score, ou_line)
            
            # 庄家操控检测：SEVERE_SQUEEZE = 极度操控
            manipulation = squeeze_status == 'SEVERE_SQUEEZE'
            confidence = 0.95 if manipulation else 0.7
            
            # 【新增·流动性门槛检测】低流动性时降低BetfairSqueeze置信度
            _bf_reasoning_suffix = ''
            _bf_vol = float(betfair_data.get('volume', betfair_data.get('total_volume', 0)) or 0)
            if 0 < _bf_vol < LIQUIDITY_THRESHOLD_VOLUME:
                confidence *= LIQUIDITY_LOW_CONFIDENCE_FACTOR
                _bf_reasoning_suffix = f' | ⚠️低流动性({_bf_vol:.0f}万)置信度降权'
            
            return ModuleVerdict(
                module_name='BetfairSqueeze分析器',
                direction=direction,
                first_score=first_score,
                second_score=second_score,
                ou_verdict=ou_verdict,
                reasoning=f"必发资金流：真实方向={true_dir} 陷阱方向={trap_dir} 状态={squeeze_status}{_bf_reasoning_suffix}",
                confidence=confidence,
                bookmaker_manipulation_detected=manipulation,
                manipulation_details=f"SEVERE_SQUEEZE 陷阱={trap_dir}" if manipulation else '',
                raw_data=betfair_data
            )
        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [一赛一方案·Betfair适配] 异常: {e}")
            return None
    
    @staticmethod
    def from_poisson(prob_dict, lam_h, lam_a, ou_line=None, asian_handicap=None):
        """从泊松期望模型产出独立判决
        
        泊松判决逻辑（数学期望，但不以概率排序为最终标准）：
        - λ比值决定方向强度（非概率大小）
        - 总λ与OU线的物理关系决定大小球
        - 选取与λ期望最物理自洽的比分（非最高概率）
        """
        if not prob_dict or lam_h is None or lam_a is None:
            return None
        
        try:
            lam_h = float(lam_h)
            lam_a = float(lam_a)
            
            total_lambda = lam_h + lam_a
            lambda_ratio = max(lam_h, lam_a) / max(min(lam_h, lam_a), 0.1)
            confidence = min(0.8, 0.4 + (lambda_ratio - 1.0) * 0.2)
            return ModuleVerdict(
                module_name='泊松期望模型',
                direction='',
                first_score='',
                second_score='',
                ou_verdict='',
                reasoning=f"λ期望：主{lam_h:.2f}/客{lam_a:.2f} 总{total_lambda:.2f}。泊松不另定两个比分，也不另定大小球。",
                confidence=confidence,
                raw_data={'lam_h': lam_h, 'lam_a': lam_a}
            )
        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [一赛一方案·泊松适配] 异常: {e}")
            return None
    
    @staticmethod
    def from_dps(dps_purified, ou_line=None, asian_handicap=None):
        """从DPS动态提权选择器产出独立判决
        
        DPS判决逻辑（聚类分析，非概率排序）：
        - KMeans聚类中心 = 数据自然聚集的真实模式
        - 核爆探针 = 被庄家极度压制的异常节点
        """
        if not dps_purified:
            return None
        
        try:
            # 从DPS提权结果中选取首选
            first_score = ''
            second_score = ''
            
            if hasattr(dps_purified[0], 'score_str'):
                first_score = dps_purified[0].score_str
                if len(dps_purified) > 1:
                    second_score = dps_purified[1].score_str
            elif isinstance(dps_purified[0], dict):
                first_score = dps_purified[0].get('score', '')
                if len(dps_purified) > 1:
                    second_score = dps_purified[1].get('score', '')
            
            if not first_score:
                return None
            
            # 方向
            direction = ''
            if first_score and '-' in first_score and '其它' not in first_score:
                h, a = parse_score(first_score)
                if h is not None and a is not None:
                    direction = 'home' if h > a else ('draw' if h == a else 'away')
            
            # 大小球
            ou_verdict = ''
            if first_score and '-' in first_score and '其它' not in first_score:
                ou_verdict = ou_verdict_from_score_safe(first_score, ou_line)
            
            return ModuleVerdict(
                module_name='DPS动态提权选择器',
                direction=direction,
                first_score=first_score,
                second_score=second_score,
                ou_verdict=ou_verdict,
                reasoning=f"KMeans聚类提权：首选={first_score}",
                confidence=0.7,
                raw_data={'count': len(dps_purified)}
            )
        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [一赛一方案·DPS适配] 异常: {e}")
            return None
    
    @staticmethod
    def from_ai_prediction(ai_pred, ou_line=None):
        """从AI预测引擎产出独立判决"""
        if not ai_pred or not isinstance(ai_pred, dict) or not ai_pred.get('available'):
            return None
        
        try:
            # 方向
            wdl = ai_pred.get('wdl_pred', '')
            direction = ''
            if '主' in wdl:
                direction = 'home'
            elif '客' in wdl:
                direction = 'away'
            elif '平' in wdl:
                direction = 'draw'
            
            # 比分
            scores = ai_pred.get('scores', [])
            first_score = scores[0].get('score', '') if len(scores) >= 1 else ''
            second_score = scores[1].get('score', '') if len(scores) >= 2 else ''
            
            # 大小球
            ou_verdict = ai_pred.get('ou_pred', '')
            
            # 置信度
            wdl_conf = ai_pred.get('wdl_conf', 50) / 100.0
            confidence = min(0.8, wdl_conf)
            return ModuleVerdict(
                module_name='AI预测引擎',
                direction=direction,
                first_score=first_score,
                second_score=second_score,
                ou_verdict=ou_verdict,
                reasoning=f"AI综合研判: {ai_pred.get('summary', '')[:80]}",
                confidence=confidence,
                bookmaker_manipulation_detected=False,
                manipulation_details='',
                raw_data=ai_pred
            )
        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [一赛一方案·AI适配] 异常: {e}")
            return None
    @staticmethod
    def from_game_theory_radar(hermes_radar_summary, pool15_enriched=None, ou_line=None, betfair_volume=None):
        """从博弈动能雷达产出独立判决
        
        雷达判决逻辑（IBI导数+量价背离，非概率）：
        - dIBI/dt > 0 = 庄家正在加注防守该方向（真实威胁）
        - 量价背离 = 资金流与赔率走势矛盾（庄家操控信号）
        
        【新增】流动性门槛检测：当必发交易量低于阈值时降低置信度，
        IBI梯度信号标记为“低置信”，防止小流动性赛事噪音干扰。
        """
        if not hermes_radar_summary or not isinstance(hermes_radar_summary, dict):
            return None
        
        try:
            ibi_deriv = hermes_radar_summary.get('ibi_derivative', {})
            volume_price = hermes_radar_summary.get('volume_price', {})
            
            if not ibi_deriv.get('available') and not volume_price.get('available'):
                return None
            
            # 【新增·流动性门槛检测】低流动性时IBI梯度信号标记为低置信
            _radar_low_liquidity = False
            _radar_confidence = 0.7
            _bf_vol = float(betfair_volume or 0)
            if 0 < _bf_vol < LIQUIDITY_THRESHOLD_VOLUME:
                _radar_low_liquidity = True
                _radar_confidence *= LIQUIDITY_LOW_CONFIDENCE_FACTOR
            
            direction = ''
            manipulation = False
            reasoning_parts = []
            
            # IBI导数方向
            if ibi_deriv.get('available'):
                accel_dir = ibi_deriv.get('acceleration_direction', '')
                if accel_dir in ('home', 'draw', 'away'):
                    direction = accel_dir
                    _ibi_label = f"IBI加速方向={accel_dir}"
                    if _radar_low_liquidity:
                        _ibi_label += '(低置信❗)'
                    reasoning_parts.append(_ibi_label)
            
            # 量价背离
            if volume_price.get('available'):
                vp_dir = volume_price.get('direction', '')
                vp_tag = volume_price.get('verdict_tag', '')
                if 'DIVERGENCE' in str(vp_tag).upper():
                    manipulation = True
                    reasoning_parts.append(f"量价背离={vp_tag}")
                if vp_dir and not direction:
                    direction = vp_dir
            
            if not direction:
                return None
            
            # 从pool15中选方向一致的比分
            first_score = ''
            second_score = ''
            if pool15_enriched:
                dir_scores = []
                for item in pool15_enriched:
                    s = item.get('score', '')
                    if not s or '其它' in s:
                        continue
                    try:
                        h, a = parse_score(s)
                        if h is None or a is None:
                            continue
                        s_dir = 'home' if h > a else ('draw' if h == a else 'away')
                        if s_dir == direction:
                            dir_scores.append((s, float(item.get('theory', 0))))
                    except (ValueError, IndexError):
                        continue
                dir_scores.sort(key=lambda x: x[1], reverse=True)
                if dir_scores:
                    first_score = dir_scores[0][0]
                if len(dir_scores) > 1:
                    second_score = dir_scores[1][0]
            
            if not first_score:
                return None
            
            # 大小球
            ou_verdict = ''
            if first_score and '-' in first_score and '其它' not in first_score:
                ou_verdict = ou_verdict_from_score_safe(first_score, ou_line)
            
            # 流动性信息追加到reasoning
            if _radar_low_liquidity:
                reasoning_parts.append(f"⚠️低流动性({_bf_vol:.0f}万)置信度降权")
            
            return ModuleVerdict(
                module_name='博弈动能雷达',
                direction=direction,
                first_score=first_score,
                second_score=second_score,
                ou_verdict=ou_verdict,
                reasoning=" | ".join(reasoning_parts),
                confidence=_radar_confidence,
                bookmaker_manipulation_detected=manipulation,
                manipulation_details='量价背离检测' if manipulation else '',
                raw_data=hermes_radar_summary
            )
        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [一赛一方案·博弈雷达适配] 异常: {e}")
            return None


