def _deepseek_http_client(use_proxy):
    """DeepSeek 走显式 httpx。代理开时固定 127.0.0.1:7897，不再只靠环境变量。"""
    import httpx
    timeout = httpx.Timeout(120.0, connect=20.0)
    _px = _local_proxy_base() if use_proxy else ''
    if _px:
        return httpx.Client(proxy=_px, timeout=timeout, trust_env=False)
    return httpx.Client(timeout=timeout, trust_env=False)


class _MissingDeepSeekClient:
    """Lazy placeholder used when no DeepSeek API key is configured."""

    class _Completions:
        @staticmethod
        def create(*args, **kwargs):
            raise RuntimeError(
                "DeepSeek API key is not configured. Set DEEPSEEK_API_KEY "
                "or BLADE_DEEPSEEK_API_KEY before using LLM features."
            )

    class _Chat:
        def __init__(self, completions):
            self.completions = completions

    def __init__(self):
        self.chat = self._Chat(self._Completions())


def _make_deepseek_client(use_proxy=None):
    """返回 (OpenAI客户端, 是否走代理)。base 保持 /v1。"""
    if use_proxy is None:
        use_proxy = _check_proxy_available()
    # 占位符/非 ASCII 密钥在 HTTP 头里必然报 codec 错误，构造客户端前先停用。
    guard_integration_secrets()
    if not DEEPSEEK_API_KEY:
        return _MissingDeepSeekClient(), bool(use_proxy)
    base = str(_DEEPSEEK_BASE_URL or 'https://api.deepseek.com').rstrip('/')
    if not base.endswith('/v1'):
        base = base + '/v1'
    return OpenAI(
        api_key=DEEPSEEK_API_KEY,
        base_url=base,
        http_client=cast(Any, _deepseek_http_client(bool(use_proxy))),
    ), bool(use_proxy)


