def llm_call_with_retry(messages, temperature=0.7, timeout=90, max_retries=3,
                        model=None, provider="deepseek", json_mode=False, expect_json=False):
    """【统一 LLM 调用器】支持重试 + 超时保护 + JSON Mode。

    Args:
        messages:    OpenAI 格式的消息列表
        temperature: 生成温度
        timeout:     单次请求超时（秒）
        max_retries: 最大重试次数（递增等待 3s/6s/9s）
        model:       可选，显式覆盖默认模型名
        provider:    路由目标（当前仅支持 deepseek）
        json_mode:   向后兼容别名，等同 expect_json
        expect_json: 为True时启用 response_format={"type":"json_object"}，
                     强制模型输出合法JSON（调用方需确保prompt中要求JSON输出）

    Returns:
        OpenAI ChatCompletion 响应对象；全链路失败时返回 None。
    """
    cfg = _LLM_ROUTER.get('deepseek')
    if not isinstance(cfg, dict):
        raise TypeError('LLM router provider "deepseek" is not configured')
    # 首次调用前的第二道守卫：配置里残留占位符就停用，不给 codec 错误开口子。
    _secret_report = guard_integration_secrets()
    if _secret_report.get('deepseek'):
        return None
    active_client = cfg['client']()
    active_model = model or cfg['model']

    # json_mode 和 expect_json 任一为 True 即启用 JSON Mode
    _use_json_mode = expect_json or json_mode

    global ds_client, client, openai_client, ai_client, _ds_via_proxy
    if _ds_via_proxy and not _check_proxy_available():
        _forget_dead_proxy()
        try:
            ds_client, _ds_via_proxy = _make_deepseek_client(use_proxy=False)
            client = openai_client = ai_client = ds_client
            active_client = ds_client
            try:
                bind_hermes_runtime(ds_client=ds_client)
            except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
                pass
        except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
            pass
    last_err = None
    tried_other_route = False
    for attempt in range(1, max_retries + 1):
        try:
            create_kwargs = {
                "model": active_model,
                "messages": messages,
                "temperature": temperature,
                "timeout": timeout,
            }
            if _use_json_mode:
                create_kwargs["response_format"] = {"type": "json_object"}
            return active_client.chat.completions.create(**create_kwargs)
        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            last_err = e
            err_text = str(e)
            is_conn = (
                'Connection' in err_text
                or 'Connect' in err_text
                or 'Timeout' in err_text
                or 'timed out' in err_text.lower()
            )
            if is_conn and not tried_other_route:
                tried_other_route = True
                try:
                    ds_client, _ds_via_proxy = _make_deepseek_client(use_proxy=not _ds_via_proxy)
                    client = openai_client = ai_client = ds_client
                    active_client = ds_client
                    try:
                        bind_hermes_runtime(ds_client=ds_client)
                    except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
                        pass
                except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
                    pass
            if attempt < max_retries:
                time.sleep(3 * attempt)

    print(f"   [deepseek] 调用失败: {last_err}")
    return None


# ── 向后兼容包装器：保留旧函数名，旧代码无需改动即可继续工作 ──
def deepseek_call_with_retry(messages, temperature=0.7, timeout=90, max_retries=3, model=None, expect_json=False):
    """【兼容包装器】保留旧函数名，内部转发到 llm_call_with_retry（DeepSeek）。"""
    return llm_call_with_retry(
        messages=messages,
        temperature=temperature,
        timeout=timeout,
        max_retries=max_retries,
        model=model,
        provider='deepseek',
        expect_json=expect_json,
    )


def _ds_flash_takeover(task, facts, temperature=0.2, timeout=120):
    """复盘正文由 deepseek-flash 撰写。失败返回空串。不写 first_score。"""
    system = (
        '你是 BladeQuant 复盘官，模型固定为 deepseek-flash（DeepSeek-V4.1-Flash）。'
        '只根据事实包写作，不得编造事实包里没有的比分、命中率或场次。'
        '不得改写 first_score 或 second_score，不得把终裁改成其他比分。'
        '全中文。任务要求的标题必须原样写出。'
    )
    user = f"任务：{task}\n\n事实包：\n{str(facts or '')[:18000]}"
    try:
        resp = deepseek_call_with_retry(
            messages=[
                {'role': 'system', 'content': system},
                {'role': 'user', 'content': user},
            ],
            temperature=float(temperature),
            timeout=int(timeout),
            max_retries=2,
            model='deepseek-flash',
        )
        if resp is None:
            return ''
        return (resp.choices[0].message.content or '').strip()
    except Exception as _e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [deepseek-flash复盘] 调用失败: {_e}")
        return ''


def _split_flash_review_sections(text):
    """按固定标题切开 deepseek-flash 复盘。未命中的标题不返回。"""
    heads = (
        '模型表现自动分析报告',
        '模型改进代码建议',
        '新增技能代码',
        '模型自适应权重学习器',
    )
    raw = str(text or '')
    found = []
    for head in heads:
        idx = raw.find(head)
        if idx >= 0:
            found.append((idx, head))
    found.sort()
    out = {}
    for n, (idx, head) in enumerate(found):
        end = found[n + 1][0] if n + 1 < len(found) else len(raw)
        out[head] = raw[idx:end].strip()
    return out
