def normalize_game_theory_model_name(name):
    """将博弈模型名称标准化为系统内部统一名称"""
    if not name:
        return ''
    name = name.strip().lower()
    mapping = {
        '囚徒困境': '囚徒困境', 'prisoner': '囚徒困境', "prisoner's dilemma": '囚徒困境',
        '纳什均衡': '纳什均衡', 'nash': '纳什均衡', 'nash equilibrium': '纳什均衡',
        '斗鸡博弈': '斗鸡博弈', 'chicken': '斗鸡博弈', '胆小鬼博弈': '斗鸡博弈',
        '零和博弈': '零和/非零和', '零和/非零和': '零和/非零和', 'zero-sum': '零和/非零和',
        '非零和': '零和/非零和', '零和': '零和/非零和',
        '斯塔克尔伯格': '斯塔克尔伯格', 'stackelberg': '斯塔克尔伯格', '领导者-跟随者': '斯塔克尔伯格',
        '古诺': '古诺', 'cournot': '古诺', '古诺竞争': '古诺', '古诺博弈': '古诺',
        '信号博弈': '信号博弈', 'signaling': '信号博弈', 'signal': '信号博弈',
        '鹰鸽博弈': '鹰鸽博弈', 'hawk-dove': '鹰鸽博弈', '鹰鸽': '鹰鸽博弈',
        # 新增博弈模型映射
        '逆向选择': '逆向选择', 'adverse selection': '逆向选择', '柠檬市场': '逆向选择',
        '信息不对称': '信息不对称', 'information asymmetry': '信息不对称', '信息差': '信息不对称',
        '最大最小': '最大最小', 'minimax': '最大最小', 'maximin': '最大最小', '最大最小值': '最大最小',
        '混合策略纳什': '混合策略纳什', 'mixed strategy': '混合策略纳什', '混合策略': '混合策略纳什', 'mixed nash': '混合策略纳什',
        '贝叶斯博弈': '贝叶斯博弈', 'bayesian': '贝叶斯博弈', 'bayesian game': '贝叶斯博弈',
        '序贯博弈': '序贯博弈', 'sequential': '序贯博弈', 'sequential game': '序贯博弈', '序贯': '序贯博弈',
        '重复博弈': '重复博弈', 'repeated': '重复博弈', 'repeated game': '重复博弈',
        '演化博弈': '演化博弈', 'evolutionary': '演化博弈', 'evolutionary game': '演化博弈',
    }
    # 精确匹配
    if name in mapping:
        return mapping[name]
    # 模糊匹配
    for key, val in mapping.items():
        if key in name or name in key:
            return val
    return name

