# 抓取+研判只允许一场。可重入：单场分析内部再调发报不会把自己卡死。
_SINGLE_MATCH_PIPELINE = threading.RLock()
_TG_FORCE_SEND = False  # TG「分析」指令触发时置True，绕过去重机制强制发送

# =====================================================================
# 【修复·问题1】auto_run 调度器并发冲突 —— 跨平台文件排他锁（FileLock）
# 根因：Streamlit 多 worker / schedule 重复注册 / 残留进程重叠时，
#       仅靠内存标志 auto_run_lock（threading.Lock）无法跨进程互斥。
# 方案：文件级排他锁 + 内存锁双层防护。
# 【v84.2修复】Windows 假「残留进程」误拦：
#   - 锁文件 Permission denied / 句柄泄漏时，旧逻辑 <30min 一律拦截
#   - 同 PID 线程崩溃未释放 + Streamlit 主进程仍存活 → 永久死锁
#   - 现：死 PID / 同PID且内存锁空闲 / 不可读超时 → 强制回收或 DEGRADED
# =====================================================================
import tempfile as _tempfile_mod

# 锁文件路径：使用系统临时目录，Windows/Linux 均可写
AUTO_RUN_LOCK_FILE = os.path.join(_tempfile_mod.gettempdir(), "blade_quant_auto_run.lock")
# 防止多线程重复打印残留锁日志
_FILELOCK_STALE_WARNED = False
# 活跃互斥：同进程其它线程/其它存活进程真正在跑 → 跳过（非僵尸）
_LOCK_ACTIVE_SECONDS = 1800  # 30min：存活持有者最长视为「在跑」
# 不可读/无元数据：超过该秒数视为僵尸，允许回收（Windows 权限锁常见）
_LOCK_UNREADABLE_STALE_SECONDS = 90


def _filelock_log(msg):
    """安全打印（Windows GBK 控制台遇 emoji 不崩）。"""
    try:
        print(msg)
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        try:
            print(str(msg).encode('gbk', errors='ignore').decode('gbk', errors='ignore'))
        except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
            pass


def _is_pid_alive(pid):
    """检查指定PID进程是否仍然存活（跨平台）。"""
    try:
        pid = int(pid or 0)
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return False
    if pid <= 0:
        return False
    try:
        if os.name == 'nt':
            import ctypes
            kernel32 = ctypes.windll.kernel32
            SYNCHRONIZE = 0x00100000
            handle = kernel32.OpenProcess(SYNCHRONIZE, 0, pid)
            if handle:
                kernel32.CloseHandle(handle)
                return True
            return False
        else:
            os.kill(pid, 0)
            return True
    except (OSError, ProcessLookupError, PermissionError):
        return False
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return False


def _read_lock_metadata(path):
    """读取锁文件中的PID和时间戳元数据。
    Returns: (pid: int|None, timestamp: float|None, readable: bool)
    """
    content = ''
    try:
        with open(path, 'r', encoding='utf-8', errors='ignore') as f:
            content = f.read(512).strip()
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        # Windows 偶发 Permission denied：再试二进制共享读
        try:
            with open(path, 'rb') as f:
                content = f.read(512).decode('utf-8', errors='ignore').strip()
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            return None, None, False
    if not content:
        return None, None, True
    try:
        if 'pid=' in content and 'ts=' in content:
            parts = content.replace('\n', ' ').split()
            pid = int(next(p for p in parts if p.startswith('pid=')).split('=', 1)[1])
            ts = float(next(p for p in parts if p.startswith('ts=')).split('=', 1)[1])
            return pid, ts, True
        if '|' in content:
            pid_str, ts_str = content.split('|', 1)
            return int(pid_str.strip()), float(ts_str.strip()), True
        # 纯数字 PID
        if content.split()[0].isdigit():
            return int(content.split()[0]), None, True
    except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
        pass
    return None, None, True


def _lock_file_age_sec(path):
    try:
        return max(0.0, time.time() - os.path.getmtime(path))
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return 0.0


def _try_remove_lock_file(path):
    """尽力删除/隔离锁文件（Windows WinError 32 时改名）。"""
    if not path or not os.path.exists(path):
        return True
    for attempt in range(3):
        try:
            os.remove(path)
            return True
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            try:
                tomb = f"{path}.stale_{int(time.time())}_{attempt}"
                os.replace(path, tomb)
                return True
            except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                time.sleep(0.15)
    return not os.path.exists(path)


def _write_lock_meta(fh):
    try:
        fh.seek(0)
        fh.truncate()
        fh.write(f"pid={os.getpid()} ts={time.time():.0f}\n")
        fh.flush()
        try:
            os.fsync(fh.fileno())
        except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
            pass
    except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
        pass


def _open_and_lock(path):
    """打开锁文件并加非阻塞排他锁。成功返回 fh，失败返回 None。"""
    fh = None
    try:
        fh = open(path, 'a+')  # noqa: SIM115 - intentional degraded-mode guard or structure-preserving fallback
        if os.name == 'nt':
            import msvcrt
            fh.seek(0)
            msvcrt.locking(fh.fileno(), msvcrt.LK_NBLCK, 1)
        else:
            import fcntl
            fcntl.flock(fh, fcntl.LOCK_EX | fcntl.LOCK_NB)
        _write_lock_meta(fh)
        return fh
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        try:
            if fh:
                fh.close()
        except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
            pass
        return None


def _force_reclaim_lock(path, reason=''):
    """强制回收锁文件并重新加锁；失败则 DEGRADED。"""
    global _FILELOCK_STALE_WARNED
    if not _FILELOCK_STALE_WARNED:
        _filelock_log(f"   🚨 [FileLock] 强制回收锁: {reason or 'stale'}")
        _FILELOCK_STALE_WARNED = True
    _try_remove_lock_file(path)
    fh = _open_and_lock(path)
    if fh is not None:
        _filelock_log("   ✅ [FileLock] 回收成功，已重新持锁")
        _FILELOCK_STALE_WARNED = False
        return fh
    _filelock_log("   ✅ [FileLock] 回收后仍无法加锁 → 降级为仅内存锁，允许执行")
    return 'DEGRADED'


def acquire_auto_run_file_lock(lock_file_path=None):
    """获取 auto_run 跨进程文件排他锁（非阻塞，Windows兼容版）。

    Returns:
        文件对象: 获取成功（须保持引用直到 release）
        'DEGRADED': 降级模式（僵尸锁/异常），允许执行但无文件锁保护
        None: 真正被其他活跃实例持有，应跳过本次 auto_run
    """
    global _FILELOCK_STALE_WARNED
    _path = lock_file_path or AUTO_RUN_LOCK_FILE

    try:
        fh = _open_and_lock(_path)
        if fh is not None:
            _FILELOCK_STALE_WARNED = False
            return fh
        # 加锁失败 → 分类：同PID孤儿 / 死PID / 不可读超时 / 真并发
        return _check_stale_and_degrade(_path, _LOCK_ACTIVE_SECONDS)

    except Exception as _e_lock:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        _filelock_log(f"   ⚠️ [FileLock] 文件锁获取异常（降级为仅内存锁模式）: {_e_lock}")
        return 'DEGRADED'


def _check_stale_and_degrade(lock_path, stale_seconds):
    """锁获取失败后的回收/拦截判定。

    优先级：
    1) 同 PID + 内存锁空闲 → 本进程孤儿句柄，强制回收
    2) 死 PID / 无 PID 且过短超时 / 不可读过短超时 → 强制回收或 DEGRADED
    3) 其它存活 PID 且未超长跑窗口 → None（真并发，跳过）
    4) 其它存活 PID 但锁龄过大 → DEGRADED（防 Streamlit 永久死锁）
    """
    global _FILELOCK_STALE_WARNED
    try:
        if not os.path.exists(lock_path):
            return _force_reclaim_lock(lock_path, reason='锁文件已消失，重建')

        _lock_age = _lock_file_age_sec(lock_path)
        _pid, _ts, _readable = _read_lock_metadata(lock_path)
        _my_pid = os.getpid()
        _mem_held = False
        try:
            _mem_held = bool(auto_run_lock.locked())
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            _mem_held = False

        # —— 同进程孤儿：文件锁残留但 auto_run 内存锁已空 ——
        if _pid == _my_pid and not _mem_held:
            return _force_reclaim_lock(
                lock_path,
                reason=f'同PID={_my_pid}孤儿锁(内存锁空闲, age={_lock_age:.0f}s)',
            )
        if _pid == _my_pid and _mem_held:
            if not _FILELOCK_STALE_WARNED:
                _filelock_log(f"   ℹ️ [FileLock] 本进程已有 auto_run 在跑(PID={_my_pid})，跳过并发")
                _FILELOCK_STALE_WARNED = True
            return None

        # —— 死进程：立即回收（不再等 30 分钟）——
        if _pid and not _is_pid_alive(_pid):
            return _force_reclaim_lock(
                lock_path,
                reason=f'持锁PID={_pid}已死亡 age={_lock_age:.0f}s',
            )

        # —— 不可读 / 无元数据：仅短超时后当僵尸（活跃持有时读失败很常见，不可立即回收）——
        if (not _readable) or (_pid is None):
            # 内存锁已被本进程持有 → 必然是本进程并发，跳过
            if _mem_held:
                if not _FILELOCK_STALE_WARNED:
                    _filelock_log(
                        "   ℹ️ [FileLock] 本进程内存锁占用中且文件锁不可解析，跳过并发"
                    )
                    _FILELOCK_STALE_WARNED = True
                return None
            if _lock_age >= _LOCK_UNREADABLE_STALE_SECONDS:
                return _force_reclaim_lock(
                    lock_path,
                    reason=f'锁不可读/无PID超时 age={_lock_age:.0f}s readable={_readable}',
                )
            if not _FILELOCK_STALE_WARNED:
                _filelock_log(
                    f"   ℹ️ [FileLock] 锁暂不可解析(age={_lock_age:.0f}s)，"
                    f"疑似活跃实例，跳过本次"
                )
                _FILELOCK_STALE_WARNED = True
            return None

        # —— 其它存活 PID ——
        if _is_pid_alive(_pid):
            if _lock_age > float(stale_seconds):
                # 超长持有：多半是崩溃未释放 + PID 被系统复用/Streamlit 残骸
                return _force_reclaim_lock(
                    lock_path,
                    reason=f'存活PID={_pid}但锁龄{_lock_age:.0f}s超限，防死锁回收',
                )
            if not _FILELOCK_STALE_WARNED:
                _filelock_log(
                    f"   ℹ️ [FileLock] 其它实例持锁中(PID={_pid}, age={_lock_age:.0f}s)，"
                    f"本次跳过"
                )
                _FILELOCK_STALE_WARNED = True
            return None

        # PID 状态不明
        return _force_reclaim_lock(lock_path, reason=f'PID={_pid}状态不明，回收')

    except Exception as _e_check:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        if not _FILELOCK_STALE_WARNED:
            _filelock_log(f"   ⚠️ [FileLock] 僵尸锁检查异常({_e_check})，降级允许执行")
            _FILELOCK_STALE_WARNED = True
        return 'DEGRADED'


def release_auto_run_file_lock(lock_fh):
    """释放 auto_run 跨进程文件排他锁（带安全降级，绝不抛异常）。"""
    global _FILELOCK_STALE_WARNED
    if lock_fh is None or lock_fh == 'DEGRADED':
        return
    _path = AUTO_RUN_LOCK_FILE
    try:
        if os.name == 'nt':
            import msvcrt
            try:
                lock_fh.seek(0)
                msvcrt.locking(lock_fh.fileno(), msvcrt.LK_UNLCK, 1)
            except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
                pass
        else:
            import fcntl
            try:
                fcntl.flock(lock_fh, fcntl.LOCK_UN)
            except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
                pass
    except Exception as _e_unlock:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        _filelock_log(f"   ⚠️ [FileLock] 释放锁异常（已忽略）: {_e_unlock}")
    finally:
        try:
            lock_fh.close()
        except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
            pass
        # 释放后尽力清掉锁文件，避免下次 Permission denied 假死
        try:
            _try_remove_lock_file(_path)
        except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
            pass
        _FILELOCK_STALE_WARNED = False
auto_reanalyze_lock = threading.Lock()  # 防止未开赛自动重分析并发重入
daily_learn_lock = threading.Lock()  # 防止每日赛果学习报告并发重入

