def parse_fallback_time(time_str):
    """容错解析：带秒 / ISO / 斜杠日期 / 无年份等异常格式。

    Returns:
        datetime | None
    """
    s = str(time_str or '').strip()
    if not s:
        return None
    # 归一：去时区尾巴 / 毫秒；T→空格便于统一格式
    s_norm = s.replace('Z', '').split('+')[0].split('.')[0].strip()
    s_space = s_norm.replace('T', ' ')
    formats = (
        ('%Y-%m-%d %H:%M:%S', s_space),
        ('%Y-%m-%d %H:%M', s_space),
        ('%Y/%m/%d %H:%M:%S', s_space),
        ('%Y/%m/%d %H:%M', s_space),
        ('%Y-%m-%d', s_space[:10]),
        ('%Y/%m/%d', s_space[:10]),
        ('%m-%d %H:%M:%S', s_space),
        ('%m-%d %H:%M', s_space),
        ('%m/%d %H:%M:%S', s_space),
        ('%m/%d %H:%M', s_space),
    )
    for fmt, candidate in formats:
        try:
            dt = datetime.strptime(candidate, fmt)
            if fmt.startswith('%m'):
                now = datetime.now()
                dt = dt.replace(year=now.year)
                if dt > now + timedelta(days=180):
                    dt = dt.replace(year=now.year - 1)
            return dt
        except ValueError:
            continue
    return None


def parse_match_time(time_str):
    """解析历史记录中的比赛时间字符串。

    主格式：%Y-%m-%d %H:%M；失败则走 parse_fallback_time。
    """
    if not time_str or time_str in ["未知", "None", "null", "---"]:
        return None
    time_str = str(time_str).strip()
    if not time_str or time_str in ("未知", "None", "null", "---"):
        return None
    try:
        return datetime.strptime(time_str, '%Y-%m-%d %H:%M')
    except ValueError:
        # 增加容错逻辑，处理带秒或无年份等异常格式
        return parse_fallback_time(time_str)
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return parse_fallback_time(time_str)


# 澳客自动取分：每场按自己的开赛时间，满 150 分钟再拉完场比分。
OKOOO_SCORE_FETCH_AFTER = timedelta(minutes=150)
MATCH_FT_ESTIMATE = OKOOO_SCORE_FETCH_AFTER
POST_FT_OKOOO_FETCH_DELAY = timedelta(0)


def get_inferred_match_status(info, now=None):
    """在history状态滞后时，基于比赛时间推断更合理的展示状态。"""
    status = str(info.get('status', 'pending') or 'pending')
    if status in ['completed', 'live']:
        return status
    match_time = parse_match_time(
        info.get('match_time') or info.get('time') or info.get('kickoff_time')
        or info.get('fixture_date') or ''
    )
    if match_time is None:
        return status
    now = now or datetime.now()
    if _kickoff_is_unconfirmed_daycut(info):
        return status
    # 开赛满 150 分钟仍无完场比分 → 超时待取分
    if now >= match_time + OKOOO_SCORE_FETCH_AFTER:
        return 'stale_pending'
    if now >= match_time:
        return 'likely_live'
    return 'pending'


def is_history_match_not_started(info, now=None):
    """阶段2补发白名单：仅未开赛。已开赛/进行中/完场一律 False。"""
    if not isinstance(info, dict):
        return False
    now = now or datetime.now()
    st = str(info.get('status') or 'pending').strip().lower()
    if st in (
        'completed', 'live', 'finished', 'ft', 'aet', 'pen',
        'cancelled', 'canceled', 'postponed', 'abandoned',
    ):
        return False
    actual = str(info.get('actual_score') or info.get('final_score') or '').strip()
    if actual and actual not in ('?', 'VS', 'vs', 'Vs', '---', '未知', 'None', ''):  # noqa: SIM102 - intentional degraded-mode guard or structure-preserving fallback
        if re.match(r'^\d+\s*[-:：]\s*\d+', actual):
            return False
    ko = (
        info.get('match_time') or info.get('time') or info.get('kickoff_time')
        or info.get('fixture_date') or ''
    )
    if 'T' in str(ko):
        ko = str(ko).replace('T', ' ')[:16]
    dt = parse_match_time(ko)
    # 行内 22:00 是竞彩日切。没读到「比赛时间」时，不能据此判已开赛。
    if _kickoff_is_unconfirmed_daycut(info):
        dt = None
    if dt is not None and dt <= now:
        return False
    inferred = get_inferred_match_status(info, now=now)
    return inferred not in ('completed', 'live', 'likely_live', 'stale_pending')


def get_display_status(info, now=None):
    """统一输出给UI使用的比赛状态文案。"""
    inferred = get_inferred_match_status(info, now=now)
    if inferred == 'completed':
        return '✅ 完结'
    if inferred == 'live':
        return '🟢 进行中'
    if inferred == 'stale_pending':
        return '⚠️ 可能已完赛（待获取）'
    if inferred == 'likely_live':
        return '🟡 可能进行中'
    return '⏳ 未开赛'


def should_prioritize_pending_fetch(info, now=None):
    """开赛满 150 分钟仍无完场比分时，优先触发自动取分。"""
    return should_auto_fetch_post_match_result(info, now=now)


def _match_kickoff_dt(info):
    if not isinstance(info, dict):
        return None
    ko = (
        info.get('match_time') or info.get('time') or info.get('kickoff_time')
        or info.get('fixture_date') or ''
    )
    if 'T' in str(ko):
        ko = str(ko).replace('T', ' ')[:16]
    return parse_match_time(ko)


def _kickoff_is_unconfirmed_daycut(info):
    """行内可见的 22:00 是竞彩日切，不是这场开赛。没读到「比赛时间」之前不能拿它取分。"""
    if not isinstance(info, dict):
        return False
    if str(info.get('kickoff_source') or '') == 'okooo_match_time':
        return False
    stored = str(info.get('time') or info.get('match_time') or '')
    return stored.endswith('22:00')


def estimated_fulltime_dt(info):
    """取分时刻 = 这场开赛时间 + 150 分钟。"""
    kickoff = _match_kickoff_dt(info)
    if kickoff is None:
        return None
    return kickoff + OKOOO_SCORE_FETCH_AFTER


def should_auto_fetch_post_match_result(info, now=None):
    """每场比赛开赛满 150 分钟，才允许自动从澳客取分。"""
    if not isinstance(info, dict):
        return False
    now = now or datetime.now()
    actual = str(info.get('actual_score') or '').replace(' (进行中)', '').strip()
    if actual and actual not in ('➖', '?', '', '无', '---') and re.match(r'^\d+\s*[-:：]\s*\d+', actual):  # noqa: SIM102 - intentional degraded-mode guard or structure-preserving fallback
        if '进行中' not in str(info.get('actual_score') or ''):
            return False
    if _kickoff_is_unconfirmed_daycut(info):
        return False
    kickoff = _match_kickoff_dt(info)
    if kickoff is None:
        return False
    return now >= kickoff + OKOOO_SCORE_FETCH_AFTER


def resolve_okooo_match_id_for_result(fid, info):
    """解析澳客 MatchID：优先落盘字段，其次 history 键（非500网场次）。"""
    info = info if isinstance(info, dict) else {}
    mid = str(info.get('okooo_match_id') or '').strip()
    if mid:
        return mid
    fid_s = str(fid or '').strip()
    if fid_s.isdigit() and not info.get('fixture_id_500'):
        return fid_s
    return ''


def update_match_result(info, actual_score, status='completed', source=''):
    """统一回写比分与状态，避免多处重复逻辑。"""
    if not isinstance(info, dict):
        return
    info['actual_score'] = actual_score
    info['status'] = status
    if source:
        info['result_source'] = source
    hot8 = None
    if status == 'completed' and DeepSeekAnalyzer is not None:
        try:
            hot8 = DeepSeekAnalyzer.evaluate_result_in_hot_top8(info, actual_score)
            info['hot_top8_result'] = hot8
            fv = info.get('feature_vector')
            if isinstance(fv, dict) and hot8.get('available'):
                fv['_result_in_hot_top8'] = 1 if hot8.get('in_hot8') else 0
                fv['_hot_top8_rank'] = int(hot8.get('rank') or 0)
            if hot8.get('available'):
                _rank = hot8.get('rank')
                _rank_txt = f'（第{_rank}热）' if _rank else ''
                print(
                    f"   📐 [市热全列] {info.get('match', '')} 赛果{hot8.get('actual_score')} "
                    f"{'在' if hot8.get('in_hot8') else '不在'}市热全列{_rank_txt}"
                )
        except Exception as _hot8_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            info['hot_top8_result'] = {
                'available': False,
                'in_hot8': None,
                'writes_first_score': False,
                'reason': str(_hot8_err)[:160],
            }
            print(f"   ⚠️ [市热全列] 核对异常(已保留赛果): {_hot8_err}")
    # 【特征库】若该场比赛已经落入特征库，则赛果更新时自动同步SQLite
    fixture_id = str(info.get('fixture_id') or info.get('id') or '').strip()
    if fixture_id:
        update_feature_result_in_db(
            fixture_id, actual_score, status=status, source=source, hot8=hot8,
        )
    if status == 'completed':
        info['auto_reviewed'] = True
        try:
            _posterior_update = update_ventropy_parameters_from_result(info, actual_score)
            info['ventropy_bayesian_update'] = _posterior_update
            if _posterior_update.get('updated'):
                print(
                    f"   🧬 [V-Entropy贝叶斯更新] "
                    f"{_posterior_update.get('home_team', '')} vs {_posterior_update.get('away_team', '')} "
                    f"攻强后验={_posterior_update.get('home_attack_strength', 0):.3f}/"
                    f"{_posterior_update.get('away_attack_strength', 0):.3f}"
                )
        except Exception as _ventropy_update_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            info['ventropy_bayesian_update'] = {
                'updated': False,
                'reason': f'update_exception:{_ventropy_update_err}',
            }
            print(f"   ⚠️ [V-Entropy贝叶斯更新] 异常(已保留赛果): {_ventropy_update_err}")

def load_brain_rules():
    """加载历史教训规则库"""
    if os.path.exists(RULES_FILE):
        with open(RULES_FILE, 'r', encoding='utf-8') as f:
            return f.read()
    return "1. 敬畏市场，严控仓位。"

def save_brain_rules(new_rule):
    """追加新教训到规则库"""
    rules = load_brain_rules()
    with open(RULES_FILE, 'w', encoding='utf-8') as f:
        f.write(rules + f"\n- {new_rule}")

def _ensure_tg_proxy_session():
    """发送前再探一次 7897。启动时端口没开，后面代理起来仍要走代理。"""
    global TG_PROXIES, _TG_SESSION_PROXY, _TG_SESSION_PROXY_NOVERIFY
    _px = _local_proxies()
    if not _px:
        return
    _needs_noverify = _allow_insecure_ssl()
    if (
        TG_PROXIES == _px
        and _TG_SESSION_PROXY is not None
        and (not _needs_noverify or _TG_SESSION_PROXY_NOVERIFY is not None)
    ):
        return
    TG_PROXIES = _px
    _TG_SESSION_PROXY = _build_tg_session(proxies=TG_PROXIES, verify=True)
    _TG_SESSION_PROXY_NOVERIFY = (
        _build_tg_session(proxies=TG_PROXIES, verify=False)
        if _needs_noverify else None
    )


def _tg_listen_gate():
    """同一进程里只许一个 getUpdates。Streamlit 重跑会新开线程，Windows 文件锁挡不住。"""
    gate = getattr(threading, "_blade_tg_listen_gate", None)
    if gate is None:
        gate = threading.Lock()
        setattr(threading, "_blade_tg_listen_gate", gate)  # noqa: B010
    return gate


def _tg_fail_should_log():
    now = time.time()
    last = float(getattr(threading, "_blade_tg_fail_log_at", 0.0) or 0.0)
    if now - last < 600:
        return False
    setattr(threading, "_blade_tg_fail_log_at", now)  # noqa: B010
    return True


_TG_DELIVERY_STATE = {
    'unreachable': False,     # 本轮已确认无法投递（缺 chat_id / token 无效 / 永久 4xx）
    'suppressed': 0,          # 被折叠掉的“所有方式均失败”次数
    'last_reason': '',
    'reasons': set(),         # 本轮已打印过的失败原因（去重）
}
_TG_DELIVERY_STATE_LOCK = threading.Lock()


def tg_delivery_disabled():
    """True when this run already established Telegram cannot deliver."""
    return bool(_TG_DELIVERY_STATE.get('unreachable'))


def tg_failure_seen(reason):
    """Mark one failure reason; True the first time it is seen this run.

    同一条原因只打印一次，避免一场比赛刷几十行相同的失败日志。
    """
    key = str(reason or '').strip() or 'unknown'
    with _TG_DELIVERY_STATE_LOCK:
        seen = _TG_DELIVERY_STATE.setdefault('reasons', set())
        if key in seen:
            return False
        seen.add(key)
        return True


def _tg_mark_delivery_unreachable(reason='', already_explained=False):
    """Acknowledge the first real delivery failure; count every later one.

    一条可操作的告警后，本轮后续失败只累加计数，由 tg_delivery_summary()
    在收尾处汇总一次，避免每场都刷同一行。原因相同则完全不重复打印。

    already_explained=True 表示调用方刚刚已经打印过具体原因（例如永久 4xx
    的动作提示），这里只记状态与计数，不再补一条泛化告警。
    """
    should_warn = False
    suppressed = 0
    with _TG_DELIVERY_STATE_LOCK:
        if not _TG_DELIVERY_STATE['unreachable']:
            _TG_DELIVERY_STATE['unreachable'] = True
            _TG_DELIVERY_STATE['last_reason'] = str(reason or '')
            should_warn = not already_explained
        else:
            _TG_DELIVERY_STATE['suppressed'] = int(_TG_DELIVERY_STATE['suppressed']) + 1
            suppressed = _TG_DELIVERY_STATE['suppressed']
        seen = _TG_DELIVERY_STATE.setdefault('reasons', set())
        first_time = str(reason or '') not in seen
        seen.add(str(reason or ''))
    if should_warn and first_time:
        print(
            "   ⚠️ TG发送失败: 所有方式均失败；本轮不再重复告警"
            + (f"（{reason}）" if reason else '')
            + "，收尾时给出累计条数",
            flush=True,
        )
    elif suppressed and suppressed % 25 == 0:
        print(f"   ℹ️ TG 本轮已累计跳过 {suppressed} 条推送（Telegram 不可达/无效）", flush=True)
    return should_warn


def tg_delivery_summary():
    """One-line end-of-run summary; empty when nothing failed."""
    with _TG_DELIVERY_STATE_LOCK:
        suppressed = int(_TG_DELIVERY_STATE.get('suppressed') or 0)
        reason = str(_TG_DELIVERY_STATE.get('last_reason') or '')
        unreachable = bool(_TG_DELIVERY_STATE.get('unreachable'))
    total = suppressed + (1 if unreachable else 0)
    if not total:
        return ''
    return f"[TG] 本次运行发送失败 {total} 次（原因已在上方{'：' + reason if reason else ''}）"


def reset_tg_delivery_state():
    """Test hook: forget the run-level Telegram failure state."""
    with _TG_DELIVERY_STATE_LOCK:
        _TG_DELIVERY_STATE['unreachable'] = False
        _TG_DELIVERY_STATE['suppressed'] = 0
        _TG_DELIVERY_STATE['last_reason'] = ''
        _TG_DELIVERY_STATE['reasons'] = set()


# =====================================================================
# 【TG chat_id · 会话发现与持久化】
# Telegram 没有“用 token 反查 chat_id”的接口，而 configure 向导只写 token。
# 所以：轮询里看到任何入站消息的 chat.id 就采纳它，并落到
# <installdir>/models/data/tg_chat_id.txt（与 feature_store.db 同一个 data 目录）。
# 下次启动环境变量没配时从这里读。群聊是负数（-100...），一律按字符串保存。
# =====================================================================
_TG_CHAT_ID_FILE_NAME = 'tg_chat_id.txt'
_TG_CHAT_CAPTURE_STATE = {'captured': '', 'printed': ''}


def resolve_tg_chat_id_path():
    """tg_chat_id.txt 的绝对路径：<MODELS_DIR>/data/tg_chat_id.txt。"""
    return os.path.abspath(os.path.join(_configured_models_dir(), 'data', _TG_CHAT_ID_FILE_NAME))


def _normalize_chat_id(value):
    """chat_id 统一成字符串；空值/非法值返回空串（支持群聊负数）。"""
    text = str(value if value is not None else '').strip()
    if not text:
        return ''
    # 允许 -1001234567890 / 123456789；其它形态一律拒绝，避免把垃圾写进请求。
    body = text.removeprefix('-')
    return text if body.isdigit() and body else ''


def load_persisted_tg_chat_id(path=None):
    """从磁盘读回上次记录的 chat_id；文件不存在/内容无效返回空串。"""
    target = str(path or resolve_tg_chat_id_path())
    try:
        if not os.path.exists(target):
            return ''
        with open(target, 'r', encoding='utf-8') as fh:
            return _normalize_chat_id(fh.readline().strip())
    except OSError:
        return ''


def persist_tg_chat_id(chat_id, path=None):
    """把 chat_id 写盘（目录按需创建）。写入失败不影响发送链路。"""
    value = _normalize_chat_id(chat_id)
    if not value:
        return False
    target = str(path or resolve_tg_chat_id_path())
    try:
        parent = os.path.dirname(target)
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(target, 'w', encoding='utf-8') as fh:
            fh.write(value + '\n')
        return True
    except OSError as exc:
        if tg_failure_seen('chat_id 落盘失败'):
            print(f"   ⚠️ [TG] chat_id 落盘失败（不影响本次回发）: {type(exc).__name__}")
        return False


def current_tg_chat_id():
    """当前生效的 chat_id：环境变量 > 本轮捕获 > 磁盘记录。"""
    return (
        _normalize_chat_id(AUTO_CHAT_ID)
        or _normalize_chat_id(_TG_CHAT_CAPTURE_STATE.get('captured'))
        or load_persisted_tg_chat_id()
    )


def _bootstrap_tg_chat_id():
    """启动时若环境变量为空，就从磁盘补上，并写回 AUTO_CHAT_ID 供旧调用点使用。"""
    global AUTO_CHAT_ID
    if _normalize_chat_id(AUTO_CHAT_ID):
        return _normalize_chat_id(AUTO_CHAT_ID)
    disk = load_persisted_tg_chat_id()
    if disk:
        AUTO_CHAT_ID = disk
        _TG_CHAT_CAPTURE_STATE['captured'] = disk
        print(f"   [TG] 已从 {_TG_CHAT_ID_FILE_NAME} 读回会话 chat_id={disk}", flush=True)
    return disk


def capture_tg_chat_id(chat_id, persist=True):
    """记录入站消息里的 chat.id；变化时打印一次并落盘。

    返回最终生效的 chat_id（字符串），空串表示这次没有可用值。
    """
    global AUTO_CHAT_ID
    value = _normalize_chat_id(chat_id)
    if not value:
        return current_tg_chat_id()
    previous = current_tg_chat_id()
    if value == previous:
        _TG_CHAT_CAPTURE_STATE['captured'] = value
        return value
    AUTO_CHAT_ID = value
    _TG_CHAT_CAPTURE_STATE['captured'] = value
    if persist:
        persist_tg_chat_id(value)
    if _TG_CHAT_CAPTURE_STATE.get('printed') != value:
        _TG_CHAT_CAPTURE_STATE['printed'] = value
        print(f"[TG] 已记录会话 chat_id={value}（之后自动回发到这里）", flush=True)
    return value


_bootstrap_tg_chat_id()

# =====================================================================
# 【TG 失败分类】
# 400/401/403/404 是“这条请求本身永远不可能成功”（chat_id 空、token 错、
# 被拉黑、接口不存在），换代理/直连/SSL 都没有意义：立即停手、只记一行。
# 只有网络级错误（超时、连接重置、代理拒绝、SSL）才走代理→直连→SSL 的阶梯。
# =====================================================================
_TG_PERMANENT_STATUSES = (400, 401, 403, 404)


def _tg_response_body(response):
    """尽量取出 Telegram 的 description，用来区分“永久配置错误”与临时问题。"""
    try:
        text = str(getattr(response, 'text', '') or '')
    except Exception:  # noqa: BLE001 - 读不到响应体就按空处理
        return ''
    return text


def _tg_is_permanent_failure(status_code, body=''):
    """True when this response means retrying can never help."""
    try:
        code = int(status_code)
    except (TypeError, ValueError):
        return False
    if code not in _TG_PERMANENT_STATUSES:
        return False
    # 400 里有两种：HTML 解析失败（可回退纯文本重发）和真正的配置错误。
    return not (code == 400 and "can't parse entities" in str(body or ''))


def _tg_permanent_failure_hint(body=''):
    """把永久 4xx 翻译成一句可操作的中文提示（不含 token/URL）。"""
    text = str(body or '')
    if 'chat_id is empty' in text:
        return '缺少 chat_id：先给机器人发一条消息（例如「状态」），程序会自动记录'
    if 'chat not found' in text:
        return 'chat_id 不存在或机器人不在该会话：先给机器人发一条消息，让它重新记录会话'
    if 'bot was blocked' in text:
        return '机器人已被该会话拉黑：在 Telegram 里先解除拉黑再试'
    if 'Unauthorized' in text:
        return 'bot token 无效或已被撤销：请运行 configure_blade_quant.ps1 重新配置 token'
    return 'Telegram 拒绝了这条请求（永久错误，不再重试）'




def _tg_api_url(method):
    base = str(os.environ.get('TELEGRAM_API_BASE_URL') or 'https://api.telegram.org').strip().rstrip('/')
    return f"{base}/bot{SNIPER_BOT_TOKEN}/{method}"


def _tg_print_invalid_token_once():
    if getattr(threading, "_blade_tg_invalid_token_logged", False):
        return
    setattr(threading, "_blade_tg_invalid_token_logged", True)  # noqa: B010
    print("[TG] bot token 无效或已被撤销，请检查 TELEGRAM_BOT_TOKEN；已停止轮询", flush=True)


def _tg_validate_bot_token_once(force=False):
    """Validate Telegram bot token with getMe once; cache result for polling/diagnose."""
    if not SNIPER_BOT_TOKEN:
        result = {'ok': False, 'status': 'missing_token', 'message': 'token not configured'}
        setattr(threading, "_blade_tg_getme_status", result)  # noqa: B010
        return result
    cached = getattr(threading, "_blade_tg_getme_status", None)
    if isinstance(cached, dict) and not force:
        return cached
    _ensure_tg_proxy_session()
    strategies = []
    if TG_PROXIES and _TG_SESSION_PROXY is not None:
        strategies.append((_TG_SESSION_PROXY, True, '代理'))
    if TG_PROXIES and _TG_SESSION_PROXY_NOVERIFY is not None:
        strategies.append((_TG_SESSION_PROXY_NOVERIFY, False, '代理'))
    strategies.append((_TG_SESSION_DIRECT, True, '直连'))
    result = {'ok': False, 'status': 'network_unchecked', 'message': 'not checked'}
    for _sess, _vf, _label in strategies:
        try:
            if not _vf:
                import urllib3
                urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)
            resp = _sess.get(_tg_api_url('getMe'), timeout=(5, 8))
            status = int(resp.status_code)
            if status == 200:
                payload = resp.json()
                result = {
                    'ok': bool(payload.get('ok')),
                    'status': 'ok' if payload.get('ok') else 'api_not_ok',
                    'route': _label,
                    'username': ((payload.get('result') or {}).get('username') if isinstance(payload, dict) else None),
                }
                break
            if status in (401, 404):
                result = {'ok': False, 'status': 'invalid_token', 'http_status': status, 'route': _label}
                _tg_print_invalid_token_once()
                break
            if status >= 500:
                result = {'ok': False, 'status': 'telegram_server_error', 'http_status': status, 'route': _label}
                continue
            result = {'ok': False, 'status': 'api_error', 'http_status': status, 'route': _label}
        except requests.exceptions.ProxyError:
            result = {'ok': False, 'status': 'proxy_unreachable', 'route': _label}
        except requests.exceptions.ConnectTimeout:
            result = {'ok': False, 'status': 'connect_timeout', 'route': _label}
        except requests.exceptions.Timeout:
            result = {'ok': False, 'status': 'timeout', 'route': _label}
        except requests.exceptions.ConnectionError:
            result = {'ok': False, 'status': 'network_unreachable', 'route': _label}
        except Exception:  # noqa: BLE001 - Telegram diagnose must never crash app startup
            result = {'ok': False, 'status': 'unknown_error', 'route': _label}
    setattr(threading, "_blade_tg_getme_status", result)  # noqa: B010
    return result


def build_system_diagnostics(force_tg_check=False):
    """Collect one-command health diagnostics without exposing secrets."""
    try:
        db_status = feature_store_schema_status()
    except Exception as exc:  # noqa: BLE001 - diagnostics should report, not crash
        db_status = {'path': resolve_feature_db_path(), 'error': str(exc)}
    token_present = bool(SNIPER_BOT_TOKEN)
    getme = _tg_validate_bot_token_once(force=force_tg_check) if token_present else {
        'ok': False,
        'status': 'missing_token',
    }
    proxy_url = ''
    proxy_reachable = None
    proxies = _local_proxies()
    if isinstance(proxies, dict):
        proxy_url = str(proxies.get('https') or proxies.get('http') or '')
        proxy_reachable = _blade_proxy_port_reachable(proxy_url) if proxy_url else None
    return {
        'db': db_status,
        'deepseek_key_present': bool(os.environ.get('DEEPSEEK_API_KEY') or os.environ.get('DEEPSEEK_KEY')),
        'telegram_token_present': token_present,
        'telegram_getme': getme,
        'proxy': {
            'route': _blade_normalize_okooo_route(os.environ.get("OKOOO_ROUTE") or _CLI_OKOOO_ROUTE or "auto"),
            'url_configured': bool(proxy_url),
            'reachable': proxy_reachable,
        },
    }


def format_system_diagnostics_text(force_tg_check=False):
    diag = _as_dict(build_system_diagnostics(force_tg_check=force_tg_check))
    db = _as_dict(diag.get('db'))
    row_counts = _as_dict(db.get('row_counts'))
    counts_text = ', '.join(f"{k}={v}" for k, v in sorted(row_counts.items())) or '无'
    getme = _as_dict(diag.get('telegram_getme'))
    proxy = _as_dict(diag.get('proxy'))
    proxy_reachable = proxy.get('reachable')
    lines = [
        "🧪【系统诊断】",
        f"DB路径: {db.get('path') or resolve_feature_db_path()}",
        f"DB schema_version: {db.get('schema_version') or 'unknown'}",
        f"DB row_counts: {counts_text}",
        f"DeepSeek key: {'present' if diag.get('deepseek_key_present') else 'missing'}",
        f"Telegram token: {'present' if diag.get('telegram_token_present') else 'missing'}",
        f"Telegram getMe: {getme.get('status') or 'unknown'}"
        + (f" @{getme.get('username')}" if getme.get('username') else ''),
        f"Proxy route: {proxy.get('route') or 'auto'}",
        f"Proxy reachable: {proxy_reachable if proxy_reachable is not None else 'not_configured'}",
    ]
    if db.get('error'):
        lines.append(f"DB error: {db.get('error')}")
    return "\n".join(lines)


def _tg_post(url, payload):
    """TG发送统一入口：智能重试 + 代理探测；SSL绕过需显式环境开关。
    返回: True=成功, False=网络失败, 'PARSE_ERROR'=HTML解析失败(需回退纯文本)
    修复 SSLError/MaxRetries 问题：
    1. 跳过不可用代理（启动时已探测）
    2. 直连失败后指数退避重试 3 次
    3. 仅当 BLADE_ALLOW_INSECURE_SSL=1 时才回退 SSL verify=False。
    连接超时不再对同一条直连路由连打三次。
    """
    import time as _t
    _ensure_tg_proxy_session()
    # 【Session 连接池复用】优先用预构建的全局持久化 Session（复用连接池、
    # 减少 SSL 握手）。每个策略携带其专属 Session；若全局 Session 未初始化则
    # 降级为临时请求。策略列表：(session, proxies, verify, timeout, label)
    strategies = []
    if TG_PROXIES:
        strategies.append((_TG_SESSION_PROXY, TG_PROXIES, True, TG_TIMEOUT, '代理'))
    strategies.append((_TG_SESSION_DIRECT, None, True, TG_TIMEOUT, '直连'))
    if _allow_insecure_ssl():
        strategies.append((_TG_SESSION_NOVERIFY, None, False, TG_TIMEOUT, 'SSL绕过'))

    max_retries = 3
    for strat_idx, (session, proxies, verify, timeout, label) in enumerate(strategies):
        for attempt in range(max_retries):
            try:
                if not verify:
                    import urllib3
                    urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)
                # 优先走复用 Session（持久连接池）；无 Session 时降级为临时请求
                if session is not None:
                    r = session.post(url, json=payload, timeout=timeout)
                else:
                    r = requests.post(url, json=payload, proxies=proxies, timeout=timeout, verify=verify)
                if r.status_code == 200:
                    if attempt > 0 or strat_idx > 0:
                        print(f"   ✅ [TG] {label}第{attempt+1}次尝试成功")
                    return True
                elif r.status_code == 400 and "can't parse entities" in r.text:
                    print(f"   ⚠️ [TG] HTML解析失败(400)，将回退纯文本: {r.text[:120]}")
                    return 'PARSE_ERROR'
                elif r.status_code == 429:
                    # Rate limited - wait and retry
                    _wait = min(int(r.headers.get('Retry-After', 5)), 30)
                    print(f"   ⏳ [TG] 频率限制，等待{_wait}秒...")
                    _t.sleep(_wait)
                    continue
                elif _tg_is_permanent_failure(r.status_code, _tg_response_body(r)):
                    # 400/401/403/404：请求本身永久错误，换代理/直连/SSL 都没用，立刻停。
                    _hint = _tg_permanent_failure_hint(_tg_response_body(r))
                    if tg_failure_seen(f'HTTP {r.status_code} {_hint}'):
                        print(f"   ❌ [TG] HTTP {r.status_code}（永久错误，不再重试）：{_hint}", flush=True)
                    return 'PERMANENT'
                else:
                    _detail = f'HTTP {r.status_code}'
                    if tg_failure_seen(f'{label}返回{_detail}'):
                        print(f"   ⚠️ [TG] {label}返回{_detail}: {_tg_response_body(r)[:100]}")
                    break  # 其它非网络错误，换策略
            except requests.exceptions.ConnectTimeout as e:
                if tg_failure_seen(f'{label}连接超时'):
                    print(f"   ⚠️ [TG] {label}连接超时: {type(e).__name__}")
                if label != '代理':
                    return False
                break
            except (requests.exceptions.SSLError, requests.exceptions.ConnectionError) as e:
                if attempt < max_retries - 1:
                    _backoff = (attempt + 1) * 2  # 2s, 4s, 6s
                    if tg_failure_seen(f'{label}连接失败'):
                        print(f"   🔄 [TG] {label}第{attempt+1}次失败({type(e).__name__})，{_backoff}秒后重试...")
                    _t.sleep(_backoff)
                else:
                    if tg_failure_seen(f'{label}达到最大重试次数'):
                        print(f"   ⚠️ [TG] {label}达到最大重试次数: {type(e).__name__}")
            except requests.exceptions.Timeout:
                if attempt < max_retries - 1:
                    if tg_failure_seen(f'{label}超时'):
                        print(f"   🔄 [TG] {label}超时，重试中...")
                    _t.sleep(2)
                else:
                    if tg_failure_seen(f'{label}超时达上限'):
                        print(f"   ⚠️ [TG] {label}达到最大重试次数(超时)")
            except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                if tg_failure_seen(f'{label}未知异常'):
                    print(f"   ⚠️ [TG] {label}未知异常: {type(e).__name__}")
                break  # 未知异常换策略
    if tg_failure_seen('所有策略均失败'):
        print("   ❌ [TG] 所有策略均失败（代理/直连/SSL绕过×3次重试）")
    return False

def send_tg(text, parse_mode=None):
    """发送Telegram消息（代理优先→直连降级→SSL绕过）
    parse_mode: 'HTML' 支持 <b>加粗</b> 等标签，None 为纯文本（默认）
    当 Telegram 返回 400 can't parse entities 时，自动剥离所有HTML标签后纯文本重发
    """
    import html as _html_mod
    # 保护：空内容不发送
    if not text or not text.strip():
        print("   ⚠️ TG发送跳过：消息内容为空")
        return
    # 本轮已确认不可达 / token 形态不可用：不再逐条重试，只累加计数。
    if tg_delivery_disabled():
        _tg_mark_delivery_unreachable()
        return
    if not SNIPER_BOT_TOKEN:
        _tg_mark_delivery_unreachable('TELEGRAM_BOT_TOKEN 未配置或不可用')
        return
    # 【chat_id 闸门】没有 chat_id 时一个 HTTP 请求都不发：Telegram 必然回
    # 400 chat_id is empty，重试阶梯只是在打一条永远不可能成功的请求。
    _chat_id = current_tg_chat_id()
    if not _chat_id:
        if tg_failure_seen('缺少 chat_id'):
            print(
                '[TG] 缺少 chat_id：先给机器人发一条消息（例如「状态」），程序会自动记录',
                flush=True,
            )
        _tg_mark_delivery_unreachable('缺少 chat_id')
        return
    try:
        if DeepSeekAnalyzer is not None and hasattr(DeepSeekAnalyzer, 'strip_tg_english'):
            text = DeepSeekAnalyzer.strip_tg_english(text)
    except Exception as _tg_zh_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [TG中文] {_tg_zh_err}")
    if not text or not str(text).strip():
        print("   ⚠️ TG发送跳过：去掉英文后正文为空")
        return
    # 硬闸：发报前剔除已关闭研判段（防旧进程路径/模型变体标题漏网）
    try:
        if DeepSeekAnalyzer is not None and hasattr(
            DeepSeekAnalyzer, 'strip_judgment_tg_suppressed_sections'
        ):
            text = DeepSeekAnalyzer.strip_judgment_tg_suppressed_sections(text)
    except Exception as _tg_strip_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [TG关闭段剔除] {_tg_strip_err}")
    _closed_engine_marks = (
        '博弈策略专家系统', 'AI预测引擎', '泊松融合', 'GBDT×泊松几何平均',
    )
    text = "\n".join(
        ln for ln in str(text).splitlines()
        if not any(mark in ln for mark in _closed_engine_marks)
    )
    if not str(text).strip():
        return
    # 硬闸：同名章节与长段复制只留第一次。HTML 已在转标签前清洗，这里只处理纯文本。
    try:
        if (
            parse_mode != 'HTML'
            and DeepSeekAnalyzer is not None
            and hasattr(DeepSeekAnalyzer, 'collapse_repeated_judgment_blocks')
            and '<' not in str(text)[:120]
        ):
            text = DeepSeekAnalyzer.collapse_repeated_judgment_blocks(text)
            if hasattr(DeepSeekAnalyzer, 'sanitize_bot_output'):
                text = DeepSeekAnalyzer.sanitize_bot_output(text)
    except Exception as _tg_dedupe_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [报告去重] {_tg_dedupe_err}")
    # 硬闸：撕掉六盘口「缺盘口」刷屏 + 原始 contradiction dict 粘贴
    try:
        if DeepSeekAnalyzer is not None and hasattr(
            DeepSeekAnalyzer, 'sanitize_six_market_tg_text'
        ):
            text = DeepSeekAnalyzer.sanitize_six_market_tg_text(text)
    except Exception as _tg_six_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [TG六盘口净化] {_tg_six_err}")
    if not text or not str(text).strip():
        print("   ⏭️ TG发送跳过：剔除关闭段后正文为空")
        return
    url = _tg_api_url('sendMessage')
    max_len = 4000

    def _strip_html(t):
        """Remove HTML tags and unescape entities for plain text fallback"""
        t = re.sub(r'<[^>]+>', '', t)
        t = _html_mod.unescape(t)
        return t

    def _send_chunk(chunk, use_parse_mode):
        """Send a single chunk, return True on success"""
        payload = {"chat_id": _chat_id, "text": chunk}
        if use_parse_mode:
            payload["parse_mode"] = use_parse_mode
        result = _tg_post(url, payload)
        if result == 'PARSE_ERROR':
            # HTML解析失败，立即剥离HTML标签后纯文本重发
            plain_chunk = _strip_html(chunk)
            print("   🔄 [TG] HTML解析失败，回退纯文本发送...")
            result2 = _tg_post(url, {"chat_id": _chat_id, "text": plain_chunk})
            return result2 is True
        elif result is True:
            return True
        elif result == 'PERMANENT':
            # 永久错误：不再用纯文本重打一遍，直接向上返回失败。
            return False
        else:
            # 网络失败，尝试纯文本
            if use_parse_mode:
                plain_chunk = _strip_html(chunk)
                result2 = _tg_post(url, {"chat_id": _chat_id, "text": plain_chunk})
                return result2 is True
            return False

    if len(text) <= max_len and '\x0c' not in text:
        if tg_delivery_disabled():
            _tg_mark_delivery_unreachable()
            return
        ok = _send_chunk(text, parse_mode)
        if not ok:
            # _tg_post 已经打印过永久错误的具体原因，这里不再补一条泛化告警。
            _tg_mark_delivery_unreachable('永久错误（详见上方提示）', already_explained=True)
    else:
        # HTML-aware splitting: split at newlines to avoid breaking tags.
        # 分页符即使正文未超长，也拆成独立 Telegram 消息。
        if parse_mode == "HTML" or '\x0c' in text:
            try:
                from blade_deepseek_pipeline import split_tg_html_preserving_pre
                parts = split_tg_html_preserving_pre(text, max_len)
            except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                lines = text.split('\n')
                parts = []
                current = ""
                for line in lines:
                    if len(current) + len(line) + 1 > max_len:
                        if current:
                            parts.append(current)
                        current = line
                    else:
                        current = current + '\n' + line if current else line
                if current:
                    parts.append(current)
        else:
            lines = text.split('\n')
            parts = []
            current = ''
            for line in lines:
                if len(line) > max_len:
                    if current:
                        parts.append(current)
                        current = ''
                    for start in range(0, len(line), max_len):
                        parts.append(line[start:start + max_len])
                    continue
                if len(current) + len(line) + 1 > max_len:
                    if current:
                        parts.append(current)
                    current = line
                else:
                    current = current + '\n' + line if current else line
            if current:
                parts.append(current)
        non_empty_parts = [(i, part) for i, part in enumerate(parts) if part.strip()]
        total_valid = len(non_empty_parts)
        if total_valid == 0:
            print("   ⚠️ TG发送跳过：所有分段内容均为空白")
            return
        for seq, (i, part) in enumerate(non_empty_parts):
            if tg_delivery_disabled():
                _tg_mark_delivery_unreachable()
                continue
            if total_valid > 1:
                marker = f"[{seq+1}/{total_valid}]"
                first, sep, rest = part.partition('\n')
                plain_first = re.sub(r'<[^>]+>', '', first).strip()
                keep_title = False
                try:
                    keep_title = (
                        DeepSeekAnalyzer is not None
                        and DeepSeekAnalyzer._is_tg_match_title_line(plain_first)
                    )
                except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    keep_title = False
                if keep_title:
                    part = first + '\n' + marker + (sep + rest if sep else '')
                else:
                    part = marker + '\n' + part
            ok = _send_chunk(part, parse_mode)
            if not ok:
                _tg_mark_delivery_unreachable(f'第{seq+1}段失败', already_explained=True)
            time.sleep(1)


# ============================================================================
# 【DeviationDrivenEngine·无特征偏差驱动决策引擎】
# 唯一决策口径：Deviation + IBI 双轨分级；不再使用诱饵、EV、Kelly或主观标签分配资金。
# ============================================================================


# 【_safe_float 已收拢至 MathUtils.safe_float】模块级定义已删除，全文统一调用 MathUtils.safe_float。


class DeviationDrivenEngine:
    """【架构统一·纯特征提取器】Deviation + IBI 双轨分级特征引擎。
    本引擎不修改任何概率数值：仅从理论/市场概率对中提取偏差(deviation)、
    IBI、分级(tier)等结构化特征，输出供 GBDTEnsembleClassifier 消费。
    最终决策唯一归属 GBDT 分类器，本引擎的 tier/score 仅为特征与解释性输出。"""

    VALID_TIERS = ('TIER_1_KILL', 'TIER_2_DEFENSE')

    @classmethod
    def _extract_deviation(cls, record):
        """统一偏差刻度；显式 deviation 优先，禁止各子系统自行定义偏差。"""
        try:
            if not isinstance(record, dict):
                return 0.0
            explicit = record.get('deviation')
            if explicit is not None and str(explicit).strip() != '':
                return MathUtils.safe_float(explicit, 0.0)

            explicit_pct = record.get('delta_pct')
            if explicit_pct is not None and str(explicit_pct).strip() != '':
                return MathUtils.safe_float(explicit_pct, 0.0)

            delta = record.get('delta', record.get('Delta'))
            if delta is not None and str(delta).strip() != '':
                delta_value = MathUtils.safe_float(delta, 0.0)
                return delta_value * (10000.0 if abs(delta_value) <= 1.0 else 100.0)

            theory = MathUtils.safe_float(
                record.get('theory_prob', record.get('theory', record.get('T_Prob', 0.0))),
                0.0,
            )
            market = MathUtils.safe_float(
                record.get('market_prob', record.get('market', record.get('M_Prob', 0.0))),
                0.0,
            )
            if abs(theory) <= 1.0 and abs(market) <= 1.0:
                return (market - theory) * 10000.0
            return (market - theory) * 100.0
        except Exception as deviation_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [DeviationDrivenEngine] deviation提取异常(已置零): {deviation_error}")
            return 0.0

    @classmethod
    def normalize_record(cls, record, context=None):
        """兼容所有子系统字段，统一生成 option/deviation/ibi 和比赛标识。"""
        try:
            if not isinstance(record, dict):
                return None
            context = context if isinstance(context, dict) else {}
            option = str(
                record.get('option')
                or record.get('score')
                or record.get('Score')
                or record.get('selection')
                or ''
            ).replace(':', '-').strip()
            if not option:
                return None

            theory = MathUtils.safe_float(
                record.get('theory_prob', record.get('theory', record.get('T_Prob', 0.0))),
                0.0,
            )
            market = MathUtils.safe_float(
                record.get('market_prob', record.get('market', record.get('M_Prob', 0.0))),
                0.0,
            )
            ibi_value = record.get(
                'ibi',
                record.get('IBI', record.get('ibi_at_art', record.get('art_ibi', None))),
            )
            ibi = MathUtils.safe_float(ibi_value, 0.0)
            if (ibi_value is None or str(ibi_value).strip() == '') and theory > 0.0 and market >= 0.0:
                ibi = market / theory
            ibi = max(0.0, ibi)

            # 赔率字段透传
            odds_value = MathUtils.safe_float(
                record.get('odds', record.get('pool_odds', record.get('Odds', 0.0))),
                0.0,
            )
            normalized = {
                'option': option,
                'deviation': round(cls._extract_deviation(record), 8),
                'ibi': round(ibi, 8),
                'odds': round(odds_value, 6),
                'match': str(record.get('match') or context.get('match') or '').strip(),
                'match_id': str(
                    record.get('match_id')
                    or record.get('fixture_id')
                    or context.get('match_id')
                    or context.get('fixture_id')
                    or ''
                ).strip(),
                'home_team': str(record.get('home_team') or context.get('home_team') or '').strip(),
                'away_team': str(record.get('away_team') or context.get('away_team') or '').strip(),
                'theory_prob': theory,
                'market_prob': market,
                'source': str(record.get('source') or context.get('source') or 'DeviationDrivenEngine'),
            }
            # 【平局形态阻吓识别】标记透传（detect_draw_deterrence → classify_and_score 特殊加权）
            if record.get('draw_deterrence'):
                normalized['draw_deterrence'] = True
                normalized['draw_deterrence_strength'] = MathUtils.safe_float(
                    record.get('draw_deterrence_strength', 1.0), 1.0)
                normalized['draw_deterrence_level'] = str(
                    record.get('draw_deterrence_level', '弱阻吓'))
                normalized['draw_deterrence_reason'] = str(
                    record.get('draw_deterrence_reason', ''))
            if record.get('draw_decoy'):
                normalized['draw_decoy'] = True
            return normalized
        except Exception as normalize_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [DeviationDrivenEngine] 单项标准化异常(已跳过): {normalize_error}")
            return None

    @classmethod
    def normalize_records(cls, records, context=None):
        """批量标准化，单项异常不影响同场或同日其余选项。"""
        try:
            normalized = []
            for record in records or []:
                try:
                    item = cls.normalize_record(record, context=context)
                    if item:
                        normalized.append(item)
                except Exception as item_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [DeviationDrivenEngine] 单项标准化异常(已跳过): {item_error}")
            return normalized
        except Exception as batch_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [DeviationDrivenEngine] 批量标准化异常(已降级为空): {batch_error}")
            return []

    @staticmethod
    def classify_and_score(ratio_data: list[dict]) -> list[dict]:
        """按唯一 Tier 规则分级，并保留跨系统审计字段。"""
        try:
            classified_results = []
            for item in ratio_data or []:
                try:
                    if not isinstance(item, dict):
                        continue
                    dev = float(item['deviation'])
                    ibi = float(item['ibi'])
                    if not (math.isfinite(dev) and math.isfinite(ibi)):
                        raise ValueError('deviation/ibi 必须为有限数值')

                    score = 0.0
                    tier = 'UNKNOWN'
                    # 【IBI硬阀门·全系统统一阈值6.58】IBI>6.58无条件剔除，
                    # 不得进入任何Tier，也不参与阻吓节点提升。
                    if ibi > 6.58:
                        result = dict(item)
                        result.update({
                            'option': item['option'],
                            'tier': 'UNKNOWN',
                            'score': 0.0,
                            'ibi_hard_cull': True,
                            'ibi_hard_cull_note': f'IBI={ibi:.4f}>6.58，触发统一硬阀门无条件剔除',
                        })
                        classified_results.append(result)
                        continue
                    if dev > 200.0 and 2.0 <= ibi <= 6.58:
                        tier = 'TIER_1_KILL'
                        score = np.log1p(dev) * ibi
                    elif dev < 0.0 and ibi < 1.0:
                        tier = 'TIER_2_DEFENSE'
                        score = 1.0 / (ibi + 0.1)

                    # 【平局形态阻吓节点 · 特殊加权】
                    # detect_draw_deterrence 判定为机构暗中阻吓的平局，具备真实
                    # 防范价值：若尚未入防御层则提升为 TIER_2_DEFENSE（阻吓即防御），
                    # 并按阻吓强度加权得分（强度每+1，得分上浮25%）。
                    dd_note = ''
                    if item.get('draw_deterrence'):
                        dd_strength = float(item.get('draw_deterrence_strength', 1.0) or 1.0)
                        dd_level = str(item.get('draw_deterrence_level', '弱阻吓'))
                        if tier == 'UNKNOWN':
                            tier = 'TIER_2_DEFENSE'
                            score = 1.0 / (min(ibi, 0.9) + 0.1)
                            dd_note = f'平局阻吓节点提升入防御层({dd_level})'
                        boost = 1.0 + 0.25 * max(0.0, dd_strength)
                        score *= boost
                        dd_note = (dd_note + ('；' if dd_note else '')
                                   + f'阻吓强度{dd_strength:.1f}→得分加权×{boost:.2f}')
                    elif item.get('draw_decoy') and tier == 'TIER_1_KILL':
                        # 声东击西中被机构放任炒热的诱饵平局：击杀层得分打折，
                        # 避免追高机构制造的虚假热度。
                        score *= 0.7
                        dd_note = '平局诱饵节点(声东击西)：击杀得分×0.70降权'

                    result = dict(item)
                    result.update({
                        'option': item['option'],
                        'tier': tier,
                        'score': round(float(score), 4),
                    })
                    if dd_note:
                        result['draw_deterrence_note'] = dd_note
                    classified_results.append(result)
                except Exception as item_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [DeviationDrivenEngine] 单项分级异常(已跳过): {item_error}")
            return classified_results
        except Exception as classify_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [DeviationDrivenEngine] 批量分级异常(已降级为空): {classify_error}")
            return []

    @classmethod
    def prioritize_allocation(cls, classified_results: list[dict], total_budget: float) -> list[dict]:
        """排除 UNKNOWN，并按 score 权重覆盖 Tier 1 / Tier 2 全部有效选项。"""
        try:
            budget = max(0.0, float(total_budget or 0.0))
            valid = [
                dict(result) for result in (classified_results or [])
                if isinstance(result, dict)
                and result.get('tier') in cls.VALID_TIERS
                and float(result.get('score', 0.0) or 0.0) > 0.0
            ]
            total_score = sum(float(result.get('score', 0.0) or 0.0) for result in valid)
            if total_score <= 0.0 or budget <= 0.0:
                return []
            for item in valid:
                try:
                    item['bet_amount'] = round(
                        (float(item.get('score', 0.0) or 0.0) / total_score) * budget,
                        2,
                    )
                except Exception as allocation_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [DeviationDrivenEngine] 单项预算计算异常(已置零): {allocation_error}")
                    item['bet_amount'] = 0.0
            valid = [item for item in valid if float(item.get('bet_amount', 0.0) or 0.0) > 0.0]
            valid.sort(key=lambda item: float(item.get('score', 0.0) or 0.0), reverse=True)
            return valid
        except Exception as allocation_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [DeviationDrivenEngine] 预算分配异常(已降级为空): {allocation_error}")
            return []

    @staticmethod
    def _match_key(item):
        try:
            return str(item.get('match_id') or item.get('match') or '').strip()
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·return ''降级 L3922] {_silent_err}")
            return ''

    @classmethod
    def evaluate_records(cls, records, total_budget=1.0, context=None):
        """所有系统共用的唯一评估入口。"""
        try:
            normalized = cls.normalize_records(records, context=context)
            classified = cls.classify_and_score(normalized)
            allocations = cls.prioritize_allocation(classified, total_budget)
            return {
                'available': bool(allocations),
                'execution_order': [
                    '提取option/deviation/ibi',
                    'classify_and_score分级',
                    'prioritize_allocation生成金额',
                    '排除UNKNOWN',
                    'Tier 1/Tier 2覆盖',
                ],
                'ratio_data': normalized,
                'classified_results': classified,
                'allocations': allocations,
                'tier_1_allocations': [item for item in allocations if item.get('tier') == 'TIER_1_KILL'],
                'tier_2_allocations': [item for item in allocations if item.get('tier') == 'TIER_2_DEFENSE'],
                'unknown_count': sum(1 for item in classified if item.get('tier') == 'UNKNOWN'),
                'total_budget': max(0.0, MathUtils.safe_float(total_budget, 0.0)),
                'allocated_total': round(sum(MathUtils.safe_float(item.get('bet_amount'), 0.0) for item in allocations), 2),
                'source': 'DeviationDrivenEngine唯一决策核心',
            }
        except Exception as evaluate_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [DeviationDrivenEngine] 统一评估异常(已降级为空): {evaluate_error}")
            return {
                'available': False,
                'ratio_data': [], 'classified_results': [], 'allocations': [],
                'tier_1_allocations': [], 'tier_2_allocations': [], 'unknown_count': 0,
                'total_budget': max(0.0, MathUtils.safe_float(total_budget, 0.0)),
                'allocated_total': 0.0,
                'source': 'DeviationDrivenEngine唯一决策核心',
                'error': str(evaluate_error),
            }

    @classmethod
    def build_prediction_output(cls, records, context=None):
        """把唯一偏差结论映射为比分、胜平负和大小球，供 AI/MoE 兼容输出。"""
        try:
            decision = cls.evaluate_records(records, total_budget=1.0, context=context)
            allocations = list(decision.get('allocations', []) or [])
            top = allocations[:2]
            if not top:
                return {
                    'available': False,
                    'ou_pred': '', 'ou_conf': 0, 'ou_reason': '无有效Tier，UNKNOWN已排除',
                    'scores': [], 'score': [],
                    'handicap_pred': '', 'handicap_reason': '无有效Tier',
                    'wdl_pred': '', 'wdl_conf': 0, 'wdl_reason': '无有效Tier',
                    'summary': 'DeviationDrivenEngine未发现Tier 1/Tier 2有效比分，未输出主观替代结论。',
                    'deviation_decision': decision,
                    'source': 'DeviationDrivenEngine唯一决策核心',
                }

            total_score = sum(max(MathUtils.safe_float(item.get('score'), 0.0), 0.0) for item in allocations)
            score_rows = []
            for item in top:
                try:
                    confidence = round(100.0 * MathUtils.safe_float(item.get('score'), 0.0) / total_score) if total_score > 0.0 else 0
                    score_rows.append({
                        'score': item.get('option', ''),
                        'conf': max(0, min(100, confidence)),
                        'reason': (
                            f"{item.get('tier')}｜Deviation={MathUtils.safe_float(item.get('deviation'), 0.0):+.2f}%｜"
                            f"IBI={MathUtils.safe_float(item.get('ibi'), 0.0):.4f}｜Score={MathUtils.safe_float(item.get('score'), 0.0):.4f}"
                        ),
                        'tier': item.get('tier', 'UNKNOWN'),
                        'deviation': MathUtils.safe_float(item.get('deviation'), 0.0),
                        'ibi': MathUtils.safe_float(item.get('ibi'), 0.0),
                        'bet_amount': MathUtils.safe_float(item.get('bet_amount'), 0.0),
                    })
                except Exception as score_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [DeviationDrivenEngine] 预测比分映射异常(已跳过): {score_error}")

            first_option = str(score_rows[0].get('score', '') or '') if score_rows else ''
            direction = ''
            goal_sum = None
            try:
                if '胜其它' in first_option:
                    direction = '主胜'
                elif '平其它' in first_option:
                    direction = '平'
                elif '负其它' in first_option:
                    direction = '客胜'
                elif '-' in first_option and '其它' not in first_option and '其他' not in first_option:
                    home_goals, away_goals = parse_score(first_option)
                    if home_goals is None or away_goals is None:
                        raise ValueError(f"invalid score: {first_option}")
                    direction = '主胜' if home_goals > away_goals else ('客胜' if home_goals < away_goals else '平')
                    goal_sum = home_goals + away_goals
            except Exception as direction_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                print(f"   ⚠️ [DeviationDrivenEngine] 比分方向映射异常(已置空): {direction_error}")
                direction = ''
                goal_sum = None

            top_conf = int(score_rows[0].get('conf', 0) or 0) if score_rows else 0
            # 【OverUnderEngine驱动】使用精确盘口结算替代错误的 goal_sum>=3 硬编码
            _ou_line_ctx = None
            if context and context.get('ou_line') not in (None, ''):
                try:
                    _ou_line_ctx = float(context.get('ou_line'))
                except (TypeError, ValueError):
                    _ou_line_ctx = None
            if goal_sum is not None and first_option and '-' in first_option and _ou_line_ctx is not None:
                ou_pred = ou_verdict_from_score_safe(first_option, _ou_line_ctx)
            else:
                ou_pred = ''
            tier_summary = ' / '.join(
                f"{row.get('score')}[{row.get('tier')}]" for row in score_rows
            )
            return {
                'available': bool(score_rows),
                'ou_pred': ou_pred,
                'ou_conf': top_conf if ou_pred else 0,
                'ou_reason': '由偏差核心首选比分进球数映射，不接受其他模块覆写',
                'scores': score_rows,
                'score': [row.get('score', '') for row in score_rows],
                'handicap_pred': '跟随偏差核心首选比分方向' if direction else '',
                'handicap_reason': 'DeviationDrivenEngine唯一决策核心',
                'wdl_pred': direction,
                'wdl_conf': top_conf if direction else 0,
                'wdl_reason': '由偏差核心首选比分严格映射',
                'summary': f'唯一决策核心输出：{tier_summary}；UNKNOWN已排除，AI/MoE/A.R.T./信息熵不得覆写。',
                'deviation_decision': decision,
                'source': 'DeviationDrivenEngine唯一决策核心',
                'raw': '',
                'error': None,
            }
        except Exception as prediction_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [DeviationDrivenEngine] 预测结构映射异常(已降级): {prediction_error}")
            return {
                'available': False, 'ou_pred': '', 'ou_conf': 0, 'ou_reason': '',
                'scores': [], 'score': [], 'handicap_pred': '', 'handicap_reason': '',
                'wdl_pred': '', 'wdl_conf': 0, 'wdl_reason': '',
                'summary': f'DeviationDrivenEngine映射异常，未恢复旧决策：{prediction_error}',
                'deviation_decision': {}, 'source': 'DeviationDrivenEngine唯一决策核心',
                'raw': '', 'error': str(prediction_error),
            }


def clean_old_data():
    """清理超过24小时的已完结数据。"""
    history = load_json(HISTORY_FILE)
    cleaned = False
    new_history = {}
    now = datetime.now()
    for fid, info in history.items():
        if not isinstance(info, dict):
            new_history[fid] = info
            continue
        if info.get('status') == 'completed':
            time_str = info.get("time", "")
            try:
                if now > datetime.strptime(time_str, "%Y-%m-%d %H:%M") + timedelta(hours=24):
                    cleaned = True
                    continue
            except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                print(f"   ⚠️ [异常已捕获·pass降级 L4801] {_silent_err}")
        new_history[fid] = info
    if cleaned:
        save_json(HISTORY_FILE, new_history)

def save_hit_history(date_str, stats):
    """保存每日命中率到历史文件"""
    history = load_json(HIT_HISTORY_FILE)
    history[date_str] = stats
    sorted_dates = sorted(history.keys(), reverse=True)[:7]
    trimmed = {d: history[d] for d in sorted_dates}
    save_json(HIT_HISTORY_FILE, trimmed)

def is_low_tier_league(league_name):
    """【】判断是否为低级别联赛"""
    if not league_name:
        return False
    for kw in LOW_TIER_LEAGUES:
        if kw in league_name:
            return True
    return False

def is_cup_match(match_name):
    """【】判断是否为杯赛/淘汰赛"""
    if not match_name:
        return False
    for kw in CUP_KEYWORDS:
        if kw in match_name:
            return True
    return False

def detect_cup_mode(match_name, first_leg_score=None):
    """
    【升级一】检测淘汰赛模式类型
    first_leg_score: 首回合比分字符串，如 "1-3" 表示主队首回合1-3落后
    返回: (模式名称, 主队λ修正系数, 客队λ修正系数, 说明)
    """
    if not is_cup_match(match_name):
        return ("常规", 1.0, 1.0, "非杯赛场次")

    if first_leg_score is None:
        return ("杯赛常规", 1.0, 1.0, "无首回合数据")

    try:
        h1, a1 = parse_score(first_leg_score)

    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return ("杯赛常规", 1.0, 1.0, "首回合比分解析失败")
    if h1 is None or a1 is None:
        return ("杯赛常规", 1.0, 1.0, "首回合比分解析失败")

    diff = h1 - a1  # 正数=主队首回合领先，负数=主队首回合落后

    if diff <= -3:
        # 投降模式：首回合落后≥3球（教训#53）
        return ("投降模式", 1.0, 0.85, f"首回合{first_leg_score}落后≥3球，主队λ不变，客队λ×0.85")
    elif diff < 0:
        # 反扑模式：首回合落后1-2球（教训#57，+25%）
        return ("反扑模式", 1.25, 0.90, f"首回合{first_leg_score}落后1-2球，主队λ×1.25(#57)，客队λ×0.90")
    elif diff == 0:
        # 首回合平局：中性化规则（教训#58）
        return ("平局中性", 1.0, 1.0, f"首回合{first_leg_score}平局，不额外上调主队λ，冷门分+2(#58)")
    elif diff >= 2:
        # 保守模式：首回合领先≥2球
        return ("保守模式", 0.90, 0.85, f"首回合{first_leg_score}领先≥2球，主队λ×0.90，客队λ×0.85")
    else:
        # 小幅领先（1球）
        return ("微幅领先", 0.95, 0.95, f"首回合{first_leg_score}领先1球，双方λ×0.95")


# ================= 3.5 机器学习内核模块 =================

def ensure_models_dir():
    """确保模型缓存目录存在。"""
    os.makedirs(MODELS_DIR, exist_ok=True)


def _load_pickle_cache(path):
    """加载pickle模型缓存。"""
    models_root = os.path.abspath(MODELS_DIR)
    cache_path = os.path.abspath(path)
    if not cache_path.startswith(models_root + os.sep):
        print(f"   ⚠️ [ML] 拒绝读取模型目录外的缓存: {path}")
        return None
    if not os.path.exists(cache_path):
        return None
    try:
        with open(cache_path, 'rb') as f:
            # Trusted local model cache constrained to MODELS_DIR.
            return pickle.load(f)  # nosec B301
    except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [ML] 读取模型缓存失败 {path}: {e}")
        return None


def _save_pickle_cache(path, obj):
    """保存pickle模型缓存。"""
    ensure_models_dir()
    models_root = os.path.abspath(MODELS_DIR)
    cache_path = os.path.abspath(path)
    if not cache_path.startswith(models_root + os.sep):
        print(f"   ⚠️ [ML] 拒绝写入模型目录外的缓存: {path}")
        return False
    try:
        with open(cache_path, 'wb') as f:
            pickle.dump(obj, f)
        return True
    except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [ML] 写入模型缓存失败 {path}: {e}")
        return False


def apply_vector_intensity_calibration(lambda_vector, recent_bias_vector, decay=0.3):
    """
    基于近期复盘数据的多维特征空间λ向量偏差自动校准。
    
    Args:
        lambda_vector: dict, 底层模型输出的初始多维强度向量 (如 {'home': lam_h, 'away': lam_a})
        recent_bias_vector: dict, 滚动历史平均残差向量 (actual_intensity - predicted_lambda)
        decay: float, 衰减因子，阻尼常数，防止单日极端值过度修正
    
    Returns:
        dict: 校准后的多维强度向量
    """
    corrected_vector = {}
    for axis, base_val in lambda_vector.items():
        bias_val = recent_bias_vector.get(axis, 0.0)
        # 施加平滑加法阻尼平移，并根据空间物理下限限制边界
        corrected_val = max(0.15, base_val + bias_val * decay)
        corrected_vector[axis] = round(corrected_val, 4)
    return corrected_vector



# ─── 【改进】大小球判定逻辑优化 - OU偏差校准 ───
# 问题: 大小球命中率偏低，实际进球倾向于比OU线高
# 升级: 引入历史偏差补偿常量
OU_CALIBRATION_BIAS = 0.15  # 正值表示实际进球倾向于比OU线高


# ═══════════════════════════════════════════════════════════════════════════════
# 【OverUnderEngine】大小球（Over/Under）结构化引擎
# 正确定义：
#   大球（Over）：常规时间内双方总进球数严格大于盘口线
#   小球（Under）：常规时间内双方总进球数严格小于盘口线
#   盘口线（Line）：博彩公司开出的预期总进球分界线
# 三大盘口类型：半球盘(2.5/3.5) | 整数盘(2.0/3.0) | 季度盘(2.25/2.75)
# 五类结算结果：全赢(+1) | 赢半(+0.5) | 走盘(0) | 输半(-0.5) | 全输(-1)
# ═══════════════════════════════════════════════════════════════════════════════
class OverUnderEngine:
    """大小球（Over/Under）结构化引擎 - 精确结算 + 泊松理论概率 + 市场偏差检测。

    核心职责：
    1. settle_ou_bet(): 精确结算三类盘口（半球/整数/季度），输出五类结果
    2. calculate_theoretical_ou_prob(): 基于泊松分布计算理论大小球概率
    3. calculate_market_implied_ou(): 从赔率反推市场隐含概率
    4. detect_ou_deviation(): 检测理论 vs 市场偏差
    5. classify_ou_line(): 盘口类型识别
    6. predict_ou(): 综合判定大小球方向（替代旧 calc_big_small）
    """

    # ═══════════════════════════════════════════════════════════════
    # 偏差阈值常量
    # ═══════════════════════════════════════════════════════════════
    DEVIATION_WARNING_THRESHOLD = 0.08   # 偏差超过8%标注警告
    DEVIATION_SEVERE_THRESHOLD = 0.15    # 偏差超过15%标注严重警告
    MAX_POISSON_N = 15                   # 泊松计算最大进球数
    EDGE_THRESHOLD = 0.05                # 边缘区域阈值（概率差<5%视为边缘）

    # ═══════════════════════════════════════════════════════════════
    # 盘口类型识别
    # ═══════════════════════════════════════════════════════════════
    @staticmethod
    def classify_ou_line(line):
        """识别大小球盘口类型。

        Args:
            line: float, 大小球盘口线（如 2.5, 3.0, 2.25, 2.75）

        Returns:
            str: 'half'(半球盘) | 'whole'(整数盘) | 'quarter'(季度盘) | None(无效)
        """
        try:
            val = float(line)
            if val <= 0:
                return None
            frac = abs(val) % 1.0
            if abs(frac - 0.5) < 1e-9:
                return 'half'
            elif abs(frac) < 1e-9 or abs(frac - 1.0) < 1e-9:
                return 'whole'
            elif abs(frac - 0.25) < 1e-9 or abs(frac - 0.75) < 1e-9:
                return 'quarter'
            else:
                return None
        except (TypeError, ValueError):
            return None

    # ═══════════════════════════════════════════════════════════════
    # 核心结算逻辑
    # ═══════════════════════════════════════════════════════════════
    @staticmethod
    def settle_ou_bet(total_goals, line):
        """精确结算大小球盘口 - 三类盘口五类结果。

        结算规则：
        - 半球盘(2.5/3.5): 总进球>line→大球全赢; 总进球<line→小球全赢
        - 整数盘(2.0/3.0): 总进球>line→大球全赢; 总进球=line→走盘; 总进球<line→小球全赢
        - 季度盘(2.25=2/2.5): 拆分为两注
          · 2.25球: 总进球>=3→大球全赢; 总进球=2→大球输一半,小球赢一半; 总进球<=1→小球全赢
          · 2.75球: 总进球>=4→大球全赢; 总进球=3→大球赢一半,小球输一半; 总进球<=2→小球全赢

        Args:
            total_goals: int, 比赛总进球数
            line: float, 大小球盘口线

        Returns:
            dict: {line_type, over_result, under_result, over_multiplier, under_multiplier, description}
        """
        try:
            total_goals = int(total_goals)
            line = float(line)
            line_type = OverUnderEngine.classify_ou_line(line)

            if line_type == 'half':
                if total_goals > line:
                    return {'line_type': 'half', 'over_result': 'full_win', 'under_result': 'full_lose',
                            'over_multiplier': 1.0, 'under_multiplier': -1.0,
                            'description': f'总进球{total_goals}>{line}，大球全赢'}
                else:
                    return {'line_type': 'half', 'over_result': 'full_lose', 'under_result': 'full_win',
                            'over_multiplier': -1.0, 'under_multiplier': 1.0,
                            'description': f'总进球{total_goals}<{line}，小球全赢'}

            elif line_type == 'whole':
                if total_goals > line:
                    return {'line_type': 'whole', 'over_result': 'full_win', 'under_result': 'full_lose',
                            'over_multiplier': 1.0, 'under_multiplier': -1.0,
                            'description': f'总进球{total_goals}>{line}，大球全赢'}
                elif total_goals == line:
                    return {'line_type': 'whole', 'over_result': 'push', 'under_result': 'push',
                            'over_multiplier': 0.0, 'under_multiplier': 0.0,
                            'description': f'总进球{total_goals}={line}，走盘退本金'}
                else:
                    return {'line_type': 'whole', 'over_result': 'full_lose', 'under_result': 'full_win',
                            'over_multiplier': -1.0, 'under_multiplier': 1.0,
                            'description': f'总进球{total_goals}<{line}，小球全赢'}

            elif line_type == 'quarter':
                frac = line % 1.0
                if abs(frac - 0.25) < 1e-9:
                    line_low = math.floor(line)
                    line_high = math.floor(line) + 0.5
                elif abs(frac - 0.75) < 1e-9:
                    line_low = math.floor(line) + 0.5
                    line_high = math.ceil(line)
                else:
                    line_low = line - 0.25
                    line_high = line + 0.25

                r_low = OverUnderEngine.settle_ou_bet(total_goals, line_low)
                r_high = OverUnderEngine.settle_ou_bet(total_goals, line_high)

                over_mult = (r_low['over_multiplier'] + r_high['over_multiplier']) / 2.0
                under_mult = (r_low['under_multiplier'] + r_high['under_multiplier']) / 2.0

                def _mult_to_result(m):
                    if abs(m - 1.0) < 1e-9:
                        return 'full_win'
                    elif abs(m - 0.5) < 1e-9:
                        return 'half_win'
                    elif abs(m) < 1e-9:
                        return 'push'
                    elif abs(m - (-0.5)) < 1e-9:
                        return 'half_lose'
                    else:
                        return 'full_lose'

                over_result = _mult_to_result(over_mult)
                under_result = _mult_to_result(under_mult)
                _desc_map = {'full_win': '全赢', 'half_win': '赢一半', 'push': '走盘',
                             'half_lose': '输一半', 'full_lose': '全输'}
                desc = f'总进球{total_goals} vs 盘口{line}(季度盘{line_low}/{line_high})，大球{_desc_map.get(over_result, over_result)}'

                return {'line_type': 'quarter', 'over_result': over_result, 'under_result': under_result,
                        'over_multiplier': over_mult, 'under_multiplier': under_mult,
                        'description': desc}

            else:
                if total_goals > line:
                    return {'line_type': 'unknown', 'over_result': 'full_win', 'under_result': 'full_lose',
                            'over_multiplier': 1.0, 'under_multiplier': -1.0,
                            'description': f'总进球{total_goals}>{line}，大球全赢(盘口类型未识别)'}
                elif abs(total_goals - line) < 1e-9:
                    return {'line_type': 'unknown', 'over_result': 'push', 'under_result': 'push',
                            'over_multiplier': 0.0, 'under_multiplier': 0.0,
                            'description': f'总进球{total_goals}={line}，走盘(盘口类型未识别)'}
                else:
                    return {'line_type': 'unknown', 'over_result': 'full_lose', 'under_result': 'full_win',
                            'over_multiplier': -1.0, 'under_multiplier': 1.0,
                            'description': f'总进球{total_goals}<{line}，小球全赢(盘口类型未识别)'}

        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            return {'line_type': 'error', 'over_result': 'error', 'under_result': 'error',
                    'over_multiplier': 0.0, 'under_multiplier': 0.0,
                    'description': f'结算异常: {e}'}

    # ═══════════════════════════════════════════════════════════════
    # 泊松理论概率计算
    # ═══════════════════════════════════════════════════════════════
    @staticmethod
    def calculate_theoretical_ou_prob(lambda_home, lambda_away, line):
        """基于泊松分布计算理论大小球概率。

        数学定义：
        - 期望总进球 lambda_total = lambda_home + lambda_away
        - P(Over L) = Sum P(Total Goals=k) for k=ceil(L) to infinity
        - 整数盘需单独计算 P(Push) = P(Total Goals=L)
        - 季度盘的概率 = 两注的加权平均

        Args:
            lambda_home: float, 主队泊松进球期望
            lambda_away: float, 客队泊松进球期望
            line: float, 大小球盘口线

        Returns:
            dict: {over_prob, under_prob, push_prob, over_prob_raw, under_prob_raw, lambda_total, line, line_type}
        """
        try:
            lam_h = max(0.05, float(lambda_home))
            lam_a = max(0.05, float(lambda_away))
            lam_total = lam_h + lam_a
            line_val = float(line)
            line_type = OverUnderEngine.classify_ou_line(line_val)

            max_n = OverUnderEngine.MAX_POISSON_N
            total_probs = {}
            cum_prob = 0.0
            for n in range(max_n + 1):
                pn = math.exp(-lam_total) * (lam_total ** n) / math.factorial(n)
                total_probs[n] = pn
                cum_prob += pn

            tail_prob = max(0.0, 1.0 - cum_prob)

            if line_type == 'quarter':
                frac = line_val % 1.0
                if abs(frac - 0.25) < 1e-9:
                    line_low = math.floor(line_val)
                    line_high = math.floor(line_val) + 0.5
                elif abs(frac - 0.75) < 1e-9:
                    line_low = math.floor(line_val) + 0.5
                    line_high = math.ceil(line_val)
                else:
                    line_low = line_val - 0.25
                    line_high = line_val + 0.25

                r_low = OverUnderEngine.calculate_theoretical_ou_prob(lam_h, lam_a, line_low)
                r_high = OverUnderEngine.calculate_theoretical_ou_prob(lam_h, lam_a, line_high)

                over_prob = (r_low['over_prob'] + r_high['over_prob']) / 2.0
                under_prob = (r_low['under_prob'] + r_high['under_prob']) / 2.0

                return {
                    'over_prob': over_prob, 'under_prob': under_prob, 'push_prob': 0.0,
                    'over_prob_raw': over_prob, 'under_prob_raw': under_prob,
                    'lambda_total': lam_total, 'line': line_val, 'line_type': 'quarter'
                }

            p_over_raw = 0.0
            p_under_raw = 0.0
            p_push = 0.0

            for n, pn in total_probs.items():
                if n > line_val:
                    p_over_raw += pn
                elif n < line_val:
                    p_under_raw += pn
                else:
                    p_push += pn

            p_over_raw += tail_prob

            p_over = p_over_raw + p_push * 0.5
            p_under = p_under_raw + p_push * 0.5

            total_sum = p_over + p_under
            if total_sum > 0:
                p_over /= total_sum
                p_under /= total_sum

            return {
                'over_prob': p_over, 'under_prob': p_under, 'push_prob': p_push,
                'over_prob_raw': p_over_raw, 'under_prob_raw': p_under_raw,
                'lambda_total': lam_total, 'line': line_val, 'line_type': line_type or 'half'
            }

        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   \u26a0\ufe0f [OverUnderEngine] 理论概率计算异常: {e}")
            return {
                'over_prob': 0.5, 'under_prob': 0.5, 'push_prob': 0.0,
                'over_prob_raw': 0.5, 'under_prob_raw': 0.5,
                'lambda_total': 0.0, 'line': float(line) if line else None,
                'line_type': 'error'
            }

    # ═══════════════════════════════════════════════════════════════
    # 市场隐含概率计算
    # ═══════════════════════════════════════════════════════════════
    @staticmethod
    def calculate_market_implied_ou(over_odds, under_odds):
        """从赔率反推市场隐含大小球概率（去除水差/juice）。

        Args:
            over_odds: float, 大球赔率（如 1.85）
            under_odds: float, 小球赔率（如 1.95）

        Returns:
            dict: {over_prob, under_prob, juice, raw_over, raw_under}
        """
        try:
            over_odds = float(over_odds)
            under_odds = float(under_odds)

            if over_odds <= 1.0 or under_odds <= 1.0:
                return {'over_prob': 0.5, 'under_prob': 0.5, 'juice': 0.0,
                        'raw_over': 0.5, 'raw_under': 0.5}

            raw_over = 1.0 / over_odds
            raw_under = 1.0 / under_odds
            total_implied = raw_over + raw_under
            juice = total_implied - 1.0

            if total_implied > 0:
                over_prob = raw_over / total_implied
                under_prob = raw_under / total_implied
            else:
                over_prob = 0.5
                under_prob = 0.5

            return {
                'over_prob': over_prob, 'under_prob': under_prob, 'juice': juice,
                'raw_over': raw_over, 'raw_under': raw_under
            }

        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   \u26a0\ufe0f [OverUnderEngine] 市场隐含概率计算异常: {e}")
            return {'over_prob': 0.5, 'under_prob': 0.5, 'juice': 0.0,
                    'raw_over': 0.5, 'raw_under': 0.5}

    # ═══════════════════════════════════════════════════════════════
    # 偏差检测
    # ═══════════════════════════════════════════════════════════════
    @staticmethod
    def detect_ou_deviation(theoretical_prob, market_prob):
        """检测理论概率 vs 市场隐含概率的偏差。

        偏差 = 理论概率 - 市场概率
        正偏差 = 理论认为大球概率更高（市场低估大球）
        负偏差 = 理论认为小球概率更高（市场高估大球）

        Args:
            theoretical_prob: dict, calculate_theoretical_ou_prob 的输出
            market_prob: dict, calculate_market_implied_ou 的输出

        Returns:
            dict: {over_deviation, under_deviation, abs_deviation, severity, warning_text, direction}
        """
        try:
            theo_over = float(theoretical_prob.get('over_prob', 0.5))
            mkt_over = float(market_prob.get('over_prob', 0.5))

            over_dev = theo_over - mkt_over
            under_dev = -over_dev
            abs_dev = abs(over_dev)

            if abs_dev >= OverUnderEngine.DEVIATION_SEVERE_THRESHOLD:
                severity = 'severe'
            elif abs_dev >= OverUnderEngine.DEVIATION_WARNING_THRESHOLD:
                severity = 'warning'
            else:
                severity = 'normal'

            warning_text = ''
            if over_dev > OverUnderEngine.DEVIATION_WARNING_THRESHOLD:
                direction = 'market_underestimates_over'
                warning_text = f'\u26a0\ufe0f市场低估大球(偏差{abs_dev:.1%})'
            elif over_dev < -OverUnderEngine.DEVIATION_WARNING_THRESHOLD:
                direction = 'market_overestimates_over'
                warning_text = f'\u26a0\ufe0f市场高估大球(偏差{abs_dev:.1%})'
            else:
                direction = 'aligned'

            return {
                'over_deviation': round(over_dev, 4), 'under_deviation': round(under_dev, 4),
                'abs_deviation': round(abs_dev, 4), 'severity': severity,
                'warning_text': warning_text, 'direction': direction
            }

        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   \u26a0\ufe0f [OverUnderEngine] 偏差检测异常: {e}")
            return {
                'over_deviation': 0.0, 'under_deviation': 0.0, 'abs_deviation': 0.0,
                'severity': 'normal', 'warning_text': '', 'direction': 'aligned'
            }

    # ═══════════════════════════════════════════════════════════════
    # 综合大小球判定（替代旧 calc_big_small）
    # ═══════════════════════════════════════════════════════════════
    @classmethod
    def predict_ou(cls, lambda_home, lambda_away, ou_line, market_over_odds=None, market_under_odds=None):
        """综合判定大小球方向 - 基于泊松理论概率 + 市场偏差检测。

        替代旧的 calc_big_small 函数（错误的加权均值阈值法）。
        正确方法：直接计算 P(Over) 和 P(Under)，概率高者为预测方向。

        Args:
            lambda_home: float, 主队泊松进球期望
            lambda_away: float, 客队泊松进球期望
            ou_line: float, 大小球盘口线
            market_over_odds: float|None, 大球赔率（可选）
            market_under_odds: float|None, 小球赔率（可选）

        Returns:
            tuple: (verdict: str, expected_goals: float, is_edge: bool, deviation_info: dict)
        """
        try:
            lam_h = max(0.05, float(lambda_home))
            lam_a = max(0.05, float(lambda_away))
            lam_total = lam_h + lam_a
            if ou_line is None:
                return '', round(lam_total, 3), False, {
                    'severity': 'missing_line', 'warning_text': '', 'direction': '',
                    'over_deviation': 0.0, 'abs_deviation': 0.0,
                }
            line_val = float(ou_line)

            theo = cls.calculate_theoretical_ou_prob(lam_h, lam_a, line_val)
            over_prob = theo['over_prob']
            under_prob = theo['under_prob']

            deviation_info = {'severity': 'normal', 'warning_text': '', 'direction': 'aligned',
                              'over_deviation': 0.0, 'abs_deviation': 0.0}
            if market_over_odds and market_under_odds:
                try:
                    market_implied = cls.calculate_market_implied_ou(market_over_odds, market_under_odds)
                    deviation_info = cls.detect_ou_deviation(theo, market_implied)
                except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
                    pass

            prob_diff = over_prob - under_prob
            is_edge = abs(prob_diff) < cls.EDGE_THRESHOLD

            if is_edge:
                verdict = '大球' if over_prob >= under_prob else '小球'
            elif over_prob > under_prob:
                verdict = '大球'
            else:
                verdict = '小球'

            return verdict, round(lam_total, 3), is_edge, deviation_info

        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   \u26a0\ufe0f [OverUnderEngine] predict_ou 异常: {e}")
            return '未知', 0.0, False, {'severity': 'normal', 'warning_text': '', 'direction': 'aligned',
                                         'over_deviation': 0.0, 'abs_deviation': 0.0}

    # ═══════════════════════════════════════════════════════════════
    # 从比分判定大小球方向（用于各模块 from_xxx 的 ou_verdict）
    # ═══════════════════════════════════════════════════════════════
    @staticmethod
    def ou_verdict_from_score(score_str, ou_line):
        """根据单个比分和盘口线判定大小球方向（精确三类盘口）。

        用于替代各模块中简化的 'total > ou_line ? 大球 : 小球' 逻辑。
        正确处理整数盘走盘和季度盘赢半/输半的情况。

        Args:
            score_str: str, 比分字符串（如 '2-1'）
            ou_line: float|None, 大小球盘口线

        Returns:
            str: '大球'|'小球'|'走盘'|''
        """
        try:
            if not score_str or not ou_line or '其它' in str(score_str):
                return ''
            if '-' not in str(score_str):
                return ''

            h, a = parse_score(score_str)
            if h is None or a is None:
                return ''

            total = h + a
            line_val = float(ou_line)

            settle = OverUnderEngine.settle_ou_bet(total, line_val)
            over_mult = settle.get('over_multiplier', 0.0)

            if over_mult > 0:
                return '大球'
            elif over_mult < 0:
                return '小球'
            else:
                return '走盘'

        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            return ''

    # ═══════════════════════════════════════════════════════════════
    # 与15池分差聚合矩阵联动
    # ═══════════════════════════════════════════════════════════════
    @staticmethod
    def ou_stats_from_pool15(pool15_scores, ou_line):
        """从15池比分列表统计大小球分布。

        Args:
            pool15_scores: list, 15池比分列表 [{'score': '2-1', 'prob': 0.11}, ...]
            ou_line: float, 大小球盘口线

        Returns:
            dict: {over_count, under_count, push_count, over_prob_sum, under_prob_sum, push_prob_sum, avg_total_goals}
        """
        try:
            over_count, under_count, push_count = 0, 0, 0
            over_prob_sum, under_prob_sum, push_prob_sum = 0.0, 0.0, 0.0
            total_goals_list = []
            if ou_line is None:
                return {
                    'over_count': 0, 'under_count': 0, 'push_count': 0,
                    'over_prob_sum': 0.0, 'under_prob_sum': 0.0, 'push_prob_sum': 0.0,
                    'avg_total_goals': 0.0,
                }
            line_val = float(ou_line)

            for item in (pool15_scores or []):
                score_str = item.get('score', '') if isinstance(item, dict) else str(item)
                prob = float(item.get('prob', item.get('theory', 0))) if isinstance(item, dict) else 0.0

                if not score_str or '其它' in score_str or '-' not in score_str:
                    continue

                try:
                    h, a = parse_score(score_str)
                    if h is None or a is None:
                        continue

                    total = h + a
                    total_goals_list.append(total)

                    settle = OverUnderEngine.settle_ou_bet(total, line_val)
                    over_mult = settle.get('over_multiplier', 0.0)

                    if over_mult > 0:
                        over_count += 1
                        over_prob_sum += prob
                    elif over_mult < 0:
                        under_count += 1
                        under_prob_sum += prob
                    else:
                        push_count += 1
                        push_prob_sum += prob
                except (ValueError, IndexError):
                    continue

            avg_total = sum(total_goals_list) / len(total_goals_list) if total_goals_list else 0.0

            return {
                'over_count': over_count, 'under_count': under_count, 'push_count': push_count,
                'over_prob_sum': over_prob_sum, 'under_prob_sum': under_prob_sum, 'push_prob_sum': push_prob_sum,
                'avg_total_goals': round(avg_total, 2)
            }

        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   \u26a0\ufe0f [OverUnderEngine] pool15统计异常: {e}")
            return {'over_count': 0, 'under_count': 0, 'push_count': 0,
                    'over_prob_sum': 0.0, 'under_prob_sum': 0.0, 'push_prob_sum': 0.0,
                    'avg_total_goals': 0.0}




# ============================================================================
# 【博弈比对评分模型 · GameTheoryBattleEngine】
# 对15池中每个比分，系统化比对4个维度：
#   市场概率（market）、理论概率（theory）、偏差（deviation）、防备指数（IBI）
# 建立博弈模型评分机制，综合4个维度对每个比分打分。
# 通过博弈评分得出：2个比分预判 + 大小球预判 + 亚盘预判
# 最后执行三维一致性检查（比分↔大小球↔亚盘）
# ============================================================================


class GameTheoryBattleEngine:
    """博弈比对评分模型 — 四维系统化博弈比对引擎

    对15池中每个比分在多系统中执行博弈比对：
    - 维度1 市场概率（market）：市场资金分布反映的隐含概率
    - 维度2 理论概率（theory）：泊松/MLE模型计算的纯数理概率
    - 维度3 偏差（deviation）：市场-理论的百分点差（正=庄家高估防守，负=庄家低估诱导）
    - 维度4 防备指数（IBI）：market/theory比值，反映机构对该比分的防备程度

    评分机制：
    - 理论概率高 → 基础分高（数理支撑强）
    - 市场概率与理论正向偏差适中 → 加分（市场认可但未过热）
    - IBI在黄金防备区间(0.6-1.2) → 加分（机构真实防备，非诱导）
    - 偏差为负且IBI低 → 加分（被低估的真实价值洼地）
    - IBI极高(>2.0) → 扣分（资金诱饵陷阱）
    - 偏差极大正值 → 扣分（过热泡沫）
    """

    # 评分权重配置
    W_THEORY = 0.30       # 理论概率权重
    W_MARKET = 0.20       # 市场概率权重
    W_DEVIATION = 0.25    # 偏差信号权重
    W_IBI = 0.25          # 防备指数权重

    # IBI区间定义
    IBI_GOLDEN_LOW = 0.6   # 黄金防备区间下限
    IBI_GOLDEN_HIGH = 1.2  # 黄金防备区间上限
    IBI_TRAP_THRESHOLD = 2.0  # 诱饵陷阱阈值
    IBI_FROZEN_THRESHOLD = 0.5  # 冰封阈值（极低IBI=机构极度防备）

    @classmethod
    def evaluate_pool15_battle(cls, pool15_enriched):
        """对15池执行四维博弈比对评分

        Args:
            pool15_enriched: list of dict, 每个元素包含:
                score, theory(百分比), market(百分比), ibi, delta(百分点差)

        Returns:
            list of dict: 按博弈评分降序排列，每个元素包含:
                score, battle_score, theory, market, deviation, ibi,
                dim_scores(各维度分项), diff_group(分差组)
        """
        try:
            if not pool15_enriched:
                return []

            results = []
            # 计算全池统计量（用于归一化）
            theories = []
            markets = []
            ibis = []
            for item in pool15_enriched:
                _t = float(item.get('theory', item.get('theory_prob', 0)) or 0)
                _m = float(item.get('market', item.get('market_prob', 0)) or 0)
                _i = float(item.get('ibi', 0) or 0)
                theories.append(_t)
                markets.append(_m)
                ibis.append(_i)

            max_theory = max(theories) if theories else 1.0
            max_market = max(markets) if markets else 1.0
            sum(ibis) / len(ibis) if ibis else 1.0

            for item in pool15_enriched:
                try:
                    score_str = str(item.get('score', '') or '').strip()
                    if not score_str:
                        continue

                    theory = float(item.get('theory', item.get('theory_prob', 0)) or 0)
                    market = float(item.get('market', item.get('market_prob', 0)) or 0)
                    ibi = float(item.get('ibi', 0) or 0)
                    deviation = float(item.get('delta', item.get('deviation', 0)) or 0)

                    # ── 维度1：理论概率评分（归一化到0-100） ──
                    dim_theory = (theory / max_theory * 100) if max_theory > 0 else 0

                    # ── 维度2：市场概率评分（归一化到0-100） ──
                    dim_market = (market / max_market * 100) if max_market > 0 else 0

                    # ── 维度3：偏差信号评分 ──
                    # 负偏差（市场低估）+ 低IBI = 价值洼地 → 高分
                    # 正偏差适中 = 市场认可 → 中等分
                    # 正偏差过大 = 过热泡沫 → 低分
                    if deviation < -2.0 and ibi < cls.IBI_GOLDEN_HIGH:
                        # 被低估的真实价值洼地
                        dim_deviation = 80 + min(20, abs(deviation) * 3)
                    elif -2.0 <= deviation <= 2.0:
                        # 偏差适中，市场与理论基本一致
                        dim_deviation = 60 + (10 - abs(deviation) * 5)
                    elif deviation > 2.0 and deviation <= 5.0:
                        # 轻度过热
                        dim_deviation = 50 - (deviation - 2.0) * 5
                    else:
                        # 严重过热或极端低估
                        dim_deviation = max(10, 50 - abs(deviation) * 3)

                    dim_deviation = max(0, min(100, dim_deviation))

                    # ── 维度4：IBI防备指数评分 ──
                    # 黄金防备区间(0.6-1.2) → 高分（真实防备）
                    # 冰封(<0.5) → 中高分（极度防备，可能是真实底牌）
                    # 高IBI(>2.0) → 低分（诱饵陷阱）
                    if cls.IBI_GOLDEN_LOW <= ibi <= cls.IBI_GOLDEN_HIGH:
                        dim_ibi = 85 + (1.0 - abs(ibi - 0.9)) * 15  # 越接近0.9越高
                    elif ibi < cls.IBI_FROZEN_THRESHOLD:
                        dim_ibi = 75  # 冰封=极度防备，有价值但风险高
                    elif cls.IBI_FROZEN_THRESHOLD <= ibi < cls.IBI_GOLDEN_LOW:
                        dim_ibi = 70 + (ibi - cls.IBI_FROZEN_THRESHOLD) * 30
                    elif cls.IBI_GOLDEN_HIGH < ibi <= cls.IBI_TRAP_THRESHOLD:
                        dim_ibi = 70 - (ibi - cls.IBI_GOLDEN_HIGH) * 20
                    else:
                        # IBI > 2.0: 诱饵陷阱
                        dim_ibi = max(5, 30 - (ibi - cls.IBI_TRAP_THRESHOLD) * 10)

                    dim_ibi = max(0, min(100, dim_ibi))

                    # ── 综合博弈评分 ──
                    battle_score = (
                        cls.W_THEORY * dim_theory +
                        cls.W_MARKET * dim_market +
                        cls.W_DEVIATION * dim_deviation +
                        cls.W_IBI * dim_ibi
                    )

                    # ── 额外加成/惩罚 ──
                    # 多维一致性加成：理论高+市场认可+IBI适中 = 三维共振
                    if dim_theory > 60 and dim_market > 50 and cls.IBI_GOLDEN_LOW <= ibi <= cls.IBI_GOLDEN_HIGH:
                        battle_score += 8  # 三维共振加成

                    # 价值洼地加成：理论高但市场低估（负偏差）+ IBI冰封
                    if theory > 5.0 and deviation < -1.5 and ibi < 0.8:
                        battle_score += 6  # 价值洼地加成

                    # 诱饵惩罚：IBI极高 + 正偏差 = 典型诱饵
                    if ibi > cls.IBI_TRAP_THRESHOLD and deviation > 2.0:
                        battle_score -= 10  # 诱饵惩罚

                    # 计算分差组
                    diff_group = None
                    h, a = parse_score(score_str)
                    if h is not None and a is not None:
                        diff_group = h - a
                    elif '胜其它' in score_str:
                        diff_group = 3  # 虚拟分差
                    elif '平其它' in score_str:
                        diff_group = 0
                    elif '负其它' in score_str:
                        diff_group = -3

                    results.append({
                        'score': score_str,
                        'battle_score': round(battle_score, 2),
                        'theory': theory,
                        'market': market,
                        'deviation': deviation,
                        'ibi': ibi,
                        'diff_group': diff_group,
                        'dim_scores': {
                            'theory': round(dim_theory, 1),
                            'market': round(dim_market, 1),
                            'deviation': round(dim_deviation, 1),
                            'ibi': round(dim_ibi, 1),
                        },
                    })
                except Exception:  # noqa: BLE001,S112 - intentional degraded-mode guard or structure-preserving fallback  # nosec B112  # intentional degraded-mode continue fallback
                    continue

            # 按博弈评分降序排列
            results.sort(key=lambda x: x['battle_score'], reverse=True)
            return results

        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [GameTheoryBattleEngine] 评分异常: {e}")
            return []

    @classmethod
    def select_top2_scores(cls, battle_results):
        """从博弈评分结果中选出top2比分（不同分差组优先，避免同质化）

        策略：
        1. 首选：博弈评分最高的比分
        2. 次选：与首选不同分差组中评分最高的比分
           如果所有比分都在同一分差组，则取评分第二高的

        Args:
            battle_results: list of dict, evaluate_pool15_battle的输出

        Returns:
            tuple: (first_score_str, second_score_str)
        """
        try:
            if not battle_results:
                return ('', '')

            # 过滤掉"其它"类虚拟比分（优先选标准比分）
            standard_results = [r for r in battle_results if '其它' not in r.get('score', '')]
            if not standard_results:
                standard_results = battle_results

            first = standard_results[0]
            first_score = first['score']
            first_diff = first.get('diff_group')

            # 寻找不同分差组的次选
            second_score = ''
            for r in standard_results[1:]:
                if r.get('diff_group') != first_diff:
                    second_score = r['score']
                    break

            # 如果没有不同分差组的，取评分第二高的
            if not second_score and len(standard_results) > 1:
                second_score = standard_results[1]['score']

            return (first_score, second_score)

        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [GameTheoryBattleEngine·top2选取] 异常: {e}")
            return ('', '')

    @classmethod
    def predict_over_under(cls, battle_results, ou_line, top_n=5):
        """基于博弈评分top比分的进球总数分布预判大小球

        Args:
            battle_results: list of dict, 博弈评分结果
            ou_line: float, 大小球盘口线（已standardize）
            top_n: int, 取top N个比分计算

        Returns:
            dict: {verdict: '大球'|'小球'|'走盘', confidence: float,
                   avg_goals: float, over_count: int, under_count: int,
                   weighted_avg_goals: float}
        """
        try:
            if not battle_results or ou_line is None:
                return {'verdict': '', 'confidence': 0.0, 'avg_goals': 0.0,
                        'over_count': 0, 'under_count': 0, 'weighted_avg_goals': 0.0}

            std_line = standardize_ou_line(ou_line)
            if std_line is None:
                return {'verdict': '', 'confidence': 0.0, 'avg_goals': 0.0,
                        'over_count': 0, 'under_count': 0, 'weighted_avg_goals': 0.0}
            top_items = battle_results[:min(top_n, len(battle_results))]

            over_weight = 0.0
            under_weight = 0.0
            push_weight = 0.0
            total_goals_weighted = 0.0
            total_weight = 0.0
            over_count = 0
            under_count = 0

            for item in top_items:
                score_str = item.get('score', '')
                battle_w = max(item.get('battle_score', 0), 0.01)

                if '其它' in score_str or '-' not in score_str:
                    continue

                h, a = parse_score(score_str)
                if h is None or a is None:
                    continue

                total = h + a
                total_goals_weighted += total * battle_w
                total_weight += battle_w

                # 使用OverUnderEngine精确判定
                verdict = ou_verdict_from_score_safe(score_str, std_line)
                if verdict == '大球':
                    over_weight += battle_w
                    over_count += 1
                elif verdict == '小球':
                    under_weight += battle_w
                    under_count += 1
                else:
                    push_weight += battle_w

            weighted_avg = total_goals_weighted / total_weight if total_weight > 0 else 0.0
            total_decision_weight = over_weight + under_weight + push_weight

            if total_decision_weight <= 0:
                return {'verdict': '', 'confidence': 0.0, 'avg_goals': weighted_avg,
                        'over_count': over_count, 'under_count': under_count,
                        'weighted_avg_goals': weighted_avg}

            over_ratio = over_weight / total_decision_weight
            under_ratio = under_weight / total_decision_weight

            if over_ratio > under_ratio:
                verdict = '大球'
                confidence = over_ratio
            elif under_ratio > over_ratio:
                verdict = '小球'
                confidence = under_ratio
            else:
                verdict = '走盘'
                confidence = push_weight / total_decision_weight

            return {
                'verdict': verdict,
                'confidence': round(confidence, 3),
                'avg_goals': round(weighted_avg, 2),
                'over_count': over_count,
                'under_count': under_count,
                'weighted_avg_goals': round(weighted_avg, 2),
            }

        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [GameTheoryBattleEngine·大小球预判] 异常: {e}")
            return {'verdict': '', 'confidence': 0.0, 'avg_goals': 0.0,
                    'over_count': 0, 'under_count': 0, 'weighted_avg_goals': 0.0}

    @classmethod
    def predict_asian_handicap(cls, battle_results, ah_line, top_n=5):
        """基于博弈评分top比分的净胜球分布预判亚盘方向

        Args:
            battle_results: list of dict, 博弈评分结果
            ah_line: float, 亚盘让球线（主让为负）
            top_n: int, 取top N个比分计算

        Returns:
            dict: {verdict: '上盘'|'下盘'|'走盘', confidence: float,
                   avg_net_goals: float, upper_count: int, lower_count: int}
        """
        try:
            if not battle_results or ah_line is None:
                return {'verdict': '', 'confidence': 0.0, 'avg_net_goals': 0.0,
                        'upper_count': 0, 'lower_count': 0}

            ah_val = float(ah_line)
            top_items = battle_results[:min(top_n, len(battle_results))]

            upper_weight = 0.0
            lower_weight = 0.0
            push_weight = 0.0
            net_goals_weighted = 0.0
            total_weight = 0.0
            upper_count = 0
            lower_count = 0

            for item in top_items:
                score_str = item.get('score', '')
                battle_w = max(item.get('battle_score', 0), 0.01)

                if '其它' in score_str or '-' not in score_str:
                    continue

                h, a = parse_score(score_str)
                if h is None or a is None:
                    continue

                net = h - a
                net_goals_weighted += net * battle_w
                total_weight += battle_w

                # 使用AsianHandicapEngine精确结算
                settle = AsianHandicapEngine.settle_bet(h, a, ah_val)
                mult = settle.get('multiplier', 0.0)

                if mult > 0:
                    upper_weight += battle_w
                    upper_count += 1
                elif mult < 0:
                    lower_weight += battle_w
                    lower_count += 1
                else:
                    push_weight += battle_w

            weighted_avg_net = net_goals_weighted / total_weight if total_weight > 0 else 0.0
            total_decision_weight = upper_weight + lower_weight + push_weight

            if total_decision_weight <= 0:
                return {'verdict': '', 'confidence': 0.0, 'avg_net_goals': weighted_avg_net,
                        'upper_count': upper_count, 'lower_count': lower_count}

            upper_ratio = upper_weight / total_decision_weight
            lower_ratio = lower_weight / total_decision_weight

            if upper_ratio > lower_ratio:
                verdict = '上盘'
                confidence = upper_ratio
            elif lower_ratio > upper_ratio:
                verdict = '下盘'
                confidence = lower_ratio
            else:
                verdict = '走盘'
                confidence = push_weight / total_decision_weight

            return {
                'verdict': verdict,
                'confidence': round(confidence, 3),
                'avg_net_goals': round(weighted_avg_net, 2),
                'upper_count': upper_count,
                'lower_count': lower_count,
            }

        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [GameTheoryBattleEngine·亚盘预判] 异常: {e}")
            return {'verdict': '', 'confidence': 0.0, 'avg_net_goals': 0.0,
                    'upper_count': 0, 'lower_count': 0}

    @classmethod
    def consistency_check(cls, first_score, second_score, ou_prediction, ah_prediction, ou_line, ah_line):
        """三维一致性检查：比分预判 ↔ 大小球预判 ↔ 亚盘预判

        检查规则：
        1. 比分预判的进球总数应与大小球预判方向一致
        2. 比分预判的净胜球应与亚盘预判方向一致
        3. 如果不一致，标记冲突并给出风险提示

        Args:
            first_score: str, 首选比分
            second_score: str, 次选比分
            ou_prediction: dict, 大小球预判结果
            ah_prediction: dict, 亚盘预判结果
            ou_line: float, 大小球盘口线
            ah_line: float, 亚盘让球线

        Returns:
            dict: {
                consistent: bool, 是否三维一致
                score_ou_ok: bool, 比分↔大小球一致
                score_ah_ok: bool, 比分↔亚盘一致
                ou_ah_ok: bool, 大小球↔亚盘方向逻辑一致
                conflicts: list[str], 冲突描述
                confidence_level: str, '高'|'中'|'低'
                summary: str, 一致性摘要文本
            }
        """
        try:
            conflicts = []
            score_ou_ok = True
            score_ah_ok = True
            ou_ah_ok = True

            ou_verdict = ou_prediction.get('verdict', '') if ou_prediction else ''
            ah_verdict = ah_prediction.get('verdict', '') if ah_prediction else ''
            std_ou_line = standardize_ou_line(ou_line)

            # ── 检查1：比分①进球总数 vs 大小球预判 ──
            if first_score and ou_verdict and '-' in first_score and '其它' not in first_score:
                h1, a1 = parse_score(first_score)
                if h1 is not None and a1 is not None:
                    score1_ou = ou_verdict_from_score_safe(first_score, std_ou_line)
                    if score1_ou and ou_verdict and score1_ou != ou_verdict and score1_ou != '走盘' and ou_verdict != '走盘':
                        score_ou_ok = False
                        conflicts.append(
                            f"比分①{first_score}(总{h1+a1}球→{score1_ou})与大小球预判({ou_verdict})矛盾"
                        )

            # ── 检查2：比分①净胜球 vs 亚盘预判 ──
            if first_score and ah_verdict and ah_line is not None and '-' in first_score and '其它' not in first_score:
                h1, a1 = parse_score(first_score)
                if h1 is not None and a1 is not None:
                    settle = AsianHandicapEngine.settle_bet(h1, a1, float(ah_line))
                    mult = settle.get('multiplier', 0.0)
                    if mult > 0:
                        score1_ah = '上盘'
                    elif mult < 0:
                        score1_ah = '下盘'
                    else:
                        score1_ah = '走盘'

                    if score1_ah != ah_verdict and score1_ah != '走盘' and ah_verdict != '走盘':
                        score_ah_ok = False
                        conflicts.append(
                            f"比分①{first_score}(净胜{h1-a1}→{score1_ah})与亚盘预判({ah_verdict})矛盾"
                        )

            # ── 检查3：大小球与亚盘方向逻辑一致性 ──
            # 大球+上盘=进攻型（一致）；小球+下盘=防守型（一致）
            # 大球+下盘 或 小球+上盘 = 方向矛盾（但不一定错，需标记）
            if ou_verdict and ah_verdict:
                if ou_verdict == '大球' and ah_verdict == '下盘':
                    # 大球但下盘：进球多但客队赢？可能是高比分客胜
                    # 不算硬冲突，但标记为需关注
                    pass  # 弱冲突，不标记
                elif ou_verdict == '小球' and ah_verdict == '上盘':
                    # 小球但上盘：进球少但主队赢？如1-0
                    pass  # 合理场景，不标记

            # ── 综合判定 ──
            all_consistent = score_ou_ok and score_ah_ok and ou_ah_ok
            conflict_count = len(conflicts)

            if all_consistent and not conflicts:
                confidence_level = '高'
                summary = '三维一致→置信度高'
            elif conflict_count == 1:
                confidence_level = '中'
                summary = f'存在1处偏差→置信度中({conflicts[0][:30]}...)'
            else:
                confidence_level = '低'
                summary = f'存在{conflict_count}处矛盾→置信度低'

            return {
                'consistent': all_consistent,
                'score_ou_ok': score_ou_ok,
                'score_ah_ok': score_ah_ok,
                'ou_ah_ok': ou_ah_ok,
                'conflicts': conflicts,
                'confidence_level': confidence_level,
                'summary': summary,
            }

        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [GameTheoryBattleEngine·一致性检查] 异常: {e}")
            return {
                'consistent': False,
                'score_ou_ok': True,
                'score_ah_ok': True,
                'ou_ah_ok': True,
                'conflicts': [f'一致性检查异常: {e}'],
                'confidence_level': '低',
                'summary': '一致性检查异常→置信度低',
            }

    @classmethod
    def format_tg_report(cls, battle_results, top2_scores, ou_pred, ah_pred, consistency):
        """格式化博弈比对结果为TG报告文本

        Args:
            battle_results: list, 博弈评分结果
            top2_scores: tuple, (first_score, second_score)
            ou_pred: dict, 大小球预判
            ah_pred: dict, 亚盘预判
            consistency: dict, 一致性检查结果

        Returns:
            str: TG报告文本段落
        """
        try:
            lines = []
            lines.append("🎲【博弈比对评分模型·四维系统化比对】")

            # top2比分
            s1, s2 = top2_scores if top2_scores else ('', '')
            if battle_results and len(battle_results) >= 2:
                r1 = battle_results[0]
                # 找到s2对应的结果
                r2_data = next((r for r in battle_results if r['score'] == s2), battle_results[1] if len(battle_results) > 1 else {})
                lines.append(
                    f"博弈比分①: {s1}"
                    f"(评分{r1.get('battle_score', 0):.1f} "
                    f"T{r1.get('dim_scores', {}).get('theory', 0):.0f}/"
                    f"M{r1.get('dim_scores', {}).get('market', 0):.0f}/"
                    f"D{r1.get('dim_scores', {}).get('deviation', 0):.0f}/"
                    f"I{r1.get('dim_scores', {}).get('ibi', 0):.0f})"
                )
                if s2:
                    lines.append(
                        f"博弈比分②: {s2}"
                        f"(评分{r2_data.get('battle_score', 0):.1f} "
                        f"T{r2_data.get('dim_scores', {}).get('theory', 0):.0f}/"
                        f"M{r2_data.get('dim_scores', {}).get('market', 0):.0f}/"
                        f"D{r2_data.get('dim_scores', {}).get('deviation', 0):.0f}/"
                        f"I{r2_data.get('dim_scores', {}).get('ibi', 0):.0f})"
                    )
            elif s1:
                lines.append(f"博弈比分①: {s1}")
                if s2:
                    lines.append(f"博弈比分②: {s2}")

            # 大小球预判
            if ou_pred and ou_pred.get('verdict'):
                lines.append(
                    f"博弈大小球: {ou_pred['verdict']}"
                    f"(置信{ou_pred.get('confidence', 0)*100:.0f}% "
                    f"加权均球{ou_pred.get('weighted_avg_goals', 0):.1f})"
                )

            # 亚盘预判
            if ah_pred and ah_pred.get('verdict'):
                lines.append(
                    f"博弈亚盘: {ah_pred['verdict']}"
                    f"(置信{ah_pred.get('confidence', 0)*100:.0f}% "
                    f"加权净胜{ah_pred.get('avg_net_goals', 0):+.1f})"
                )

            # 一致性检查结果
            if consistency:
                conf_level = consistency.get('confidence_level', '低')
                summary = consistency.get('summary', '')
                if conf_level == '高':
                    lines.append(f"✅ 一致性: {summary}")
                elif conf_level == '中':
                    lines.append(f"⚠️ 一致性: {summary}")
                else:
                    lines.append(f"❌ 一致性: {summary}")

                # 输出具体冲突
                for conflict in consistency.get('conflicts', [])[:2]:
                    lines.append(f"  └ {conflict}")

            return "\n".join(lines)

        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [GameTheoryBattleEngine·TG格式化] 异常: {e}")
            return ""


# ═══════════════════════════════════════════════════════════════════════════════
# 【纯系统确定性决策引擎】PureSystemDeterministicEngine
# 完全剥离AI，基于严格的数学阈值与状态机完成自动裁判。
# ═══════════════════════════════════════════════════════════════════════════════
class PureSystemDeterministicEngine:
    """
    【纯系统确定性决策引擎】
    完全剥离AI，基于严格的数学阈值与状态机完成自动裁判。
    """

    def __init__(self):
        self.DOMINANCE_PROB = 0.75
        self.DEEP_HANDICAP = 1.5
        self.IBI_FROZEN_LIMIT = 0.40
        self.TENSOR_DELTA_LIMIT = 2.0

    def evaluate_match_deterministically(self, match_data):
        decision_report = {
            "final_winner": "",
            "final_scores": [],
            "execution_path": "DEFAULT_FLOW",
            "risk_flag": False
        }

        poisson_home = match_data.get('poisson_home_prob', 0.0)
        handicap = abs(match_data.get('handicap_line', 0.0))
        match_data.get('pool31_records', [])
        gt_triggered = match_data.get('game_theory_triggered', [])
        match_data.get('nash_equilibrium_score')

        # 【博弈论干预】平局力场强化 (囚徒困境)
        if "Prisoners_Dilemma" in gt_triggered:
            decision_report["execution_path"] = "GT_PRISONERS_DILEMMA_DRAW"
            decision_report["risk_flag"] = True
            return decision_report

        # 铁律1：绝对实力与深盘统治局只记路径，不另定两个比分。
        if poisson_home >= self.DOMINANCE_PROB and handicap >= self.DEEP_HANDICAP:
            decision_report["execution_path"] = "RULE_1_ABSOLUTE_DOMINANCE"
            return decision_report

        # 铁律2：张量裂缝与反向暗桩触发 (包含信息不对称信号)
        market_away = match_data.get('market_away_prob', 0.0)
        theory_away = match_data.get('theory_away_prob', 0.0)
        asym_dir = match_data.get('asymmetry_edge_direction')

        if (market_away - theory_away) >= 5.0 or asym_dir == 'away' or "Information_Asymmetry" in gt_triggered:
            decision_report["execution_path"] = "RULE_2_TENSOR_FISSURE_COUNTER"
            if asym_dir == 'away':
                decision_report["execution_path"] = "GT_INFO_ASYMMETRY_AWAY"
            decision_report["risk_flag"] = True
            return decision_report

        if "Chicken_Game" in gt_triggered:
            decision_report["execution_path"] = "GT_CHICKEN_GAME_EXTREME"
            decision_report["risk_flag"] = True
            return decision_report

        decision_report["execution_path"] = "RULE_3_STANDARD_IBI_ANCHOR"
        if "Adverse_Selection" in gt_triggered:
            decision_report["risk_flag"] = True
            decision_report["execution_path"] += "_LEMON_TRAP_ADJUSTED"
        return decision_report


# ═══════════════════════════════════════════════════════════════════════════════
# 【风控优先与 DSCV 一票否决决策引擎】RiskFirstDecisionEngine
# 核心规则：DSCV（动态交叉验证/风险引擎）一旦发出警告或检测到张量裂缝冲突，
# 系统自动剥夺纯数理模型（PSDE）的主导权，强制切换为 DSCV 的防守或反向纠偏结果。
# ═══════════════════════════════════════════════════════════════════════════════

# 高风险大比分（总进球≥4 或单边≥4）—— Hard Risk Gate 禁止仲裁在否决态强行覆写为此类
_HARD_RISK_HIGH_SCORE_TOTAL = 4


def _is_high_risk_large_score(score_str):
    """判定是否为高风险大比分（总球≥4 或单边≥4）。"""
    try:
        s = str(score_str or '').replace(':', '-').strip()
        if not s or '其它' in s or '其他' in s or '-' not in s:
            return False
        h, a = parse_score(s)
        if h is None or a is None:
            return False
        return (h + a) >= _HARD_RISK_HIGH_SCORE_TOTAL or h >= 4 or a >= 4
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return False


def apply_hard_risk_gate(risk_engine_result, arbitration_result=None):
    """风控一票否决硬约束（Hard Risk Gate）。

    若 RiskFirst / DSCV 触发 conflict 或 dscv_veto：
      - 采用 safe_scores（保守风控建议）
      - override_flag=False（禁止收敛仲裁强行推高风险大比分）
    否则采用仲裁比分。
    """
    risk = risk_engine_result if isinstance(risk_engine_result, dict) else {}
    arb = arbitration_result if isinstance(arbitration_result, dict) else {}
    veto = bool(
        risk.get('dscv_veto')
        or risk.get('conflict')
        or risk.get('has_conflict')
        or (
            risk.get('risk_flag')
            and risk.get('execution_path') == 'DSCV_OVERRIDE_VETO_ACTIVE'
        )
    )
    out = {
        'gated': False,
        'override_flag': True,
        'final_scores': [],
        'reason': '',
        'source': 'arbitration',
    }
    if veto:
        safe = risk.get('safe_scores') or risk.get('final_scores') or risk.get('suggested_scores') or []
        if isinstance(safe, (list, tuple)):
            safe = [str(x).replace(':', '-').strip() for x in safe if str(x or '').strip()]
        else:
            safe = []
        # 过滤掉仍混入的高风险大比分
        safe = [s for s in safe if s and not _is_high_risk_large_score(s)] or safe
        out['gated'] = True
        out['override_flag'] = False
        out['final_scores'] = list(safe)[:2]
        out['reason'] = 'HardRiskGate: dscv_veto/conflict → 保守 safe_scores，禁止仲裁覆写'
        out['source'] = 'risk_safe_scores'
        return out
    # 无否决：可用仲裁比分，但仍丢弃仲裁侧高风险大比分若与 risk 冲突标记
    scores = []
    if arb.get('scores'):
        scores = list(arb.get('scores') or [])
    elif arb.get('final_first_score'):
        scores = [arb.get('final_first_score'), arb.get('final_second_score')]
    scores = [str(x).replace(':', '-').strip() for x in scores if str(x or '').strip()]
    out['final_scores'] = scores[:2]
    out['override_flag'] = True
    out['source'] = 'arbitration'
    return out


class RiskFirstDecisionEngine:
    """
    【风控优先与 DSCV 一票否决决策引擎】
    核心规则：DSCV（动态交叉验证/风险引擎）一旦发出警告或检测到张量裂缝冲突，
    系统自动剥夺纯数理模型（PSDE）的主导权，强制切换为 DSCV 的防守或反向纠偏结果。
    """

    def __init__(self):
        pass

    def evaluate_final_decision(self, psde_result, dscv_audit_payload):
        """
        终裁仲裁逻辑：
        - psde_result: 纯数理模型算出的默认结果（如 2-0, 0-0，主胜）
        - dscv_audit_payload: 动态交叉验证引擎的审计结果（包含风险标记、裂缝、冲突状态）
        """
        final_decision = dict(psde_result) if isinstance(psde_result, dict) else {}

        # 1. 提取 DSCV 的警告与冲突状态
        dscv_has_warning = bool(dscv_audit_payload.get("has_warning", False))
        dscv_has_conflict = bool(dscv_audit_payload.get("has_conflict", False))
        dscv_suggested_direction = dscv_audit_payload.get("suggested_direction", None)
        dscv_suggested_scores = list(dscv_audit_payload.get("suggested_scores", []) or [])

        # Hard Risk Gate 字段（供下游 apply_hard_risk_gate 消费）
        final_decision["conflict"] = dscv_has_conflict
        final_decision["dscv_veto"] = False
        final_decision["safe_scores"] = [
            str(s).replace(':', '-').strip()
            for s in dscv_suggested_scores
            if str(s or '').strip() and not _is_high_risk_large_score(s)
        ] or [
            str(s).replace(':', '-').strip()
            for s in dscv_suggested_scores
            if str(s or '').strip()
        ]

        # 2. 【核心熔断：DSCV 一票否决权】
        if dscv_has_warning or dscv_has_conflict:
            final_decision["execution_path"] = "DSCV_OVERRIDE_VETO_ACTIVE"
            final_decision["risk_flag"] = True
            final_decision["dscv_veto"] = True

            # 如果 DSCV 建议了更具防守性或反向的方向（如平局、客胜或冷门矩阵），强行覆盖 PSDE
            if dscv_suggested_direction and dscv_suggested_direction != final_decision.get("final_winner"):
                final_decision["final_winner"] = dscv_suggested_direction

            # 保守比分：优先 safe_scores，禁止高风险大比分
            if final_decision["safe_scores"]:
                final_decision["final_scores"] = list(final_decision["safe_scores"][:2])
            elif dscv_suggested_scores:
                final_decision["final_scores"] = [
                    str(s).replace(':', '-').strip() for s in dscv_suggested_scores[:2]
                    if str(s or '').strip()
                ]

            final_decision["override_reason"] = (
                f"\U0001f6e1\ufe0f 【DSCV 风险一票否决触发】\n"
                f"\u00b7 现象：动态交叉验证检测到市场张量裂缝或盘口冲突。\n"
                f"\u00b7 裁决：已剥夺数理底座(PSDE)主导权，强制以 DSCV 防御/纠偏结果 [{final_decision.get('final_winner')}] 执行。\n"
                f"\u00b7 Hard Risk Gate：禁止收敛仲裁覆写为高风险大比分。"
            )
        else:
            final_decision["execution_path"] = "PSDE_DOMINANT_NORMAL"
            final_decision["dscv_veto"] = False
            final_decision["conflict"] = False

        return final_decision


# ═══════════════════════════════════════════════════════════════════════════════
# 【16种足球博弈论量化策略核心引擎】FootballGameTheoryEngine
# 将经典的与高阶演化的16种博弈论模型全部固化为可执行的纯Python数理判断逻辑，
# 用于对一场足球比赛的泊松矩阵、盘口数据和资金流进行深度穿透与意图识别。
# ═══════════════════════════════════════════════════════════════════════════════
class FootballGameTheoryEngine:
    """
    【16种足球博弈论量化策略核心引擎】
    将经典的与高阶演化的16种博弈论模型全部固化为可执行的纯Python数理判断逻辑，
    用于对一场足球比赛的泊松矩阵、盘口数据和资金流进行深度穿透与意图识别。
    """

    def __init__(self, match_context=None):
        self.ctx = match_context or {}

    # ==================== 第一部分：经典博弈模型（8种） ====================

    def model_prisoners_dilemma(self, home_lambda, away_lambda, market_over_line=None):
        """1. 囚徒困境 (Prisoner's Dilemma)
        识别双方是否在利益驱动下倾向于保守防御（如势均力敌或各取所需的局面）。
        """
        try:
            if home_lambda is None or away_lambda is None or market_over_line is None:
                return {
                    "model": "Prisoners_Dilemma",
                    "triggered": False,
                    "strategy": "LINE_OR_LAMBDA_MISSING",
                }
            expected_total = float(home_lambda) + float(away_lambda)
            market_over_line = float(market_over_line)
        except (TypeError, ValueError):
            return {
                "model": "Prisoners_Dilemma",
                "triggered": False,
                "strategy": "LINE_OR_LAMBDA_MISSING",
            }
        is_conservative_intent = expected_total < market_over_line and abs(float(home_lambda) - float(away_lambda)) < 0.4
        return {
            "model": "Prisoners_Dilemma",
            "triggered": is_conservative_intent,
            "strategy": "BOTH_DEFEND_TOWARDS_DRAW" if is_conservative_intent else "NORMAL_OPEN_PLAY"
        }

    def model_nash_equilibrium(self, pool31_records):
        """2. 纳什均衡 (Nash Equilibrium)
        寻找各方在当前偏差下都不愿单方面偏离的稳定平衡点。
        """
        if not pool31_records:
            return {
                "model": "Nash_Equilibrium",
                "equilibrium_score": "",
                "stability_index": 0.0
            }
        stable_nodes = sorted(pool31_records, key=lambda x: abs(float(x.get('market', 0)) - float(x.get('theory', 0))))
        eq_node = stable_nodes[0] if stable_nodes else None
        return {
            "model": "Nash_Equilibrium",
            "equilibrium_score": eq_node.get('score') if eq_node else "",
            "stability_index": abs(float(eq_node.get('market', 0)) - float(eq_node.get('theory', 0))) if eq_node else 0.0
        }

    def model_chicken_game(self, importance_home, importance_away):
        """3. 斗鸡博弈 (Chicken Game)
        识别双方互不相让、高风险对抗的极端场景。
        """
        is_extreme_duel = importance_home >= 8.0 and importance_away >= 8.0
        return {
            "model": "Chicken_Game",
            "triggered": is_extreme_duel,
            "description": "双方战意极高，互不相让，极易产生红牌、极端大比分或大开大合。"
        }

    def model_zero_sum_game(self, volume, bookmaker_profit_spread):
        """4. 零和/非零和博弈 (Zero-Sum Game)
        衡量市场资金的此消彼长，判断是否属于存量博弈。
        """
        is_zero_sum = volume < 200000 and bookmaker_profit_spread < 0.05
        return {
            "model": "Zero_Sum_Game",
            "is_zero_sum": is_zero_sum,
            "triggered": is_zero_sum,
            "description": "低流动性纯存量博弈，资金对撞直接决定赔付归属。"
        }

    def model_stackelberg_game(self, home_theo_prob, handicap_line):
        """5. 斯塔克尔伯格博弈 (Stackelberg Game)
        领导者-跟随者模式：实力更强的强队（领导者）先定盘，弱队被迫应战。
        """
        is_leader_follower = home_theo_prob > 0.65 and abs(handicap_line) >= 1.25
        return {
            "model": "Stackelberg_Game",
            "triggered": is_leader_follower,
            "leader_role": "STRONG_HOME_TEAM",
            "strategy": "STRONG_TEAM_SETS_TEMPO"
        }

    def model_cournot_competition(self, home_lambda, away_lambda):
        """6. 古诺竞争 (Cournot Competition)
        侧重于进球期望和火力产出的数量竞争模型。
        """
        try:
            total_firepower = float(home_lambda) + float(away_lambda)
        except (TypeError, ValueError):
            return {
                "model": "Cournot_Competition",
                "total_expected_output": None,
                "competition_intensity": "MISSING",
            }
        return {
            "model": "Cournot_Competition",
            "total_expected_output": round(total_firepower, 2),
            "competition_intensity": "HIGH" if total_firepower > 3.0 else "LOW"
        }

    def model_signaling_game(self, odds_movement, water_trend):
        """7. 信号博弈 (Signaling Game)
        解读庄家通过升降水、变盘释放的虚假或真实信号。
        """
        is_fake_signal = odds_movement == "UP" and water_trend == "LOW"
        return {
            "model": "Signaling_Game",
            "triggered": is_fake_signal,
            "signal_type": "TRAP_INDUCING" if is_fake_signal else "GENUINE_TREND",
            "description": "做市商盘路变动意图解析"
        }

    def model_hawk_dove_game(self, elo_diff):
        """8. 鹰鸽博弈 (Hawk-Dove Game)
        强弱分明或激进与保守之间的策略选择。
        """
        is_clear_tier = abs(elo_diff) > 200
        return {
            "model": "Hawk_Dove_Game",
            "triggered": is_clear_tier,
            "strategy_assigned": "STRONG_HAWK_VS_WEAK_DOVE" if is_clear_tier else "BOTH_DOVE_BALANCED"
        }

    # ==================== 第二部分：高阶演化与信息博弈模型（8种） ====================

    def model_adverse_selection(self, market_prob, theory_prob, ibi):
        """9. 逆向选择 (Adverse Selection)
        识别庄家利用信息优势压低大热比分赔率的柠檬市场陷阱。
        """
        is_lemon_trap = market_prob < theory_prob and ibi < 0.5
        return {
            "model": "Adverse_Selection",
            "triggered": is_lemon_trap,
            "description": "庄家利用信息差刻意压低正路赔率，制造诱买陷阱。"
        }

    def model_information_asymmetry(self, smart_money_flow, public_sentiment):
        """10. 信息不对称 (Information Asymmetry)
        捕捉资金异动与盘口背离时，机构与散户之间的信息差利润点。
        """
        has_asymmetry = smart_money_flow != public_sentiment
        return {
            "model": "Information_Asymmetry",
            "triggered": has_asymmetry,
            "edge_direction": smart_money_flow if has_asymmetry else "NONE"
        }

    def model_minimax_strategy(self, max_liability):
        """11. 最大最小策略 (Minimax Strategy)
        模拟做市商"最小化最大损失"的风险防线。
        """
        safety_threshold = 500000
        is_hedged = max_liability > safety_threshold
        return {
            "model": "Minimax_Strategy",
            "triggered": is_hedged,
            "bookmaker_hedging_active": is_hedged,
            "objective": "MINIMIZE_MAXIMUM_PAYOUT_RISK"
        }

    def model_mixed_strategy_nash(self, home_p, draw_p, away_p):
        """12. 混合策略纳什 (Mixed Strategy Nash)
        当胜平负概率极度接近、形成均匀分布时，寻找概率混同的平衡点。
        """
        entropy = -sum([p * math.log(p + 1e-9) for p in [home_p, draw_p, away_p] if p > 0])
        is_uniform = entropy > 1.0
        return {
            "model": "Mixed_Strategy_Nash",
            "entropy": round(entropy, 3),
            "triggered": is_uniform,
            "description": "胜平负概率均等混同，呈混合策略均衡态。"
        }

    def model_bayesian_game(self, prior_prob, new_evidence_weight):
        """13. 贝叶斯博弈 (Bayesian Game)
        在不完全信息下通过先验和后验概率动态更新判断。
        """
        posterior = prior_prob * (1.0 + new_evidence_weight)
        return {
            "model": "Bayesian_Game",
            "posterior_probability": round(min(1.0, posterior), 4)
        }

    def model_sequential_game(self, early_odds, live_odds):
        """14. 序贯博弈 (Sequential Game)
        利用亚指和大小球随时间变化的时序先后信号进行推演。
        """
        trend_shift = live_odds - early_odds
        return {
            "model": "Sequential_Game",
            "triggered": abs(trend_shift) > 0.15,
            "time_axis_trend": "SHIFTING_TOWARDS_FAVORITE" if trend_shift < 0 else "DEFENDING_UNDERDOG"
        }

    def model_repeated_game(self, head_to_head_draw_rate):
        """历史交锋已清除。不按交锋平率判定。"""
        return {
            "model": "Repeated_Game",
            "triggered": False,
            "historical_inertia": "",
        }

    def model_evolutionary_game(self, public_heat_shift):
        """16. 演化博弈 (Evolutionary Game)
        观察市场群体情绪演化及新策略对旧平衡的入侵与稳定。
        """
        is_invaded = abs(public_heat_shift) > 0.3
        return {
            "model": "Evolutionary_Game",
            "triggered": is_invaded,
            "market_equilibrium_state": "UNSTABLE_POPULATION_SHIFT" if is_invaded else "STABLE_ESS"
        }

    def run_all_16_models(self, match_data):
        """一键运行全部 16 种博弈论模型并汇总结果"""
        results = {}
        results["1_prisoners"] = self.model_prisoners_dilemma(
            match_data.get('h_lam'), match_data.get('a_lam'), match_data.get('ou_line'))
        results["2_nash"] = self.model_nash_equilibrium(match_data.get('pool31', []))
        results["3_chicken"] = self.model_chicken_game(match_data.get('h_imp', 5.0), match_data.get('a_imp', 5.0))
        results["4_zerosum"] = self.model_zero_sum_game(match_data.get('vol', 100000), match_data.get('spread', 0.02))
        results["5_stackelberg"] = self.model_stackelberg_game(match_data.get('h_theo', 0.5), match_data.get('hcap', 0.5))
        results["6_cournot"] = self.model_cournot_competition(match_data.get('h_lam'), match_data.get('a_lam'))
        results["7_signaling"] = self.model_signaling_game(match_data.get('odds_m', 'DOWN'), match_data.get('water', 'HIGH'))
        results["8_hawkdove"] = self.model_hawk_dove_game(match_data.get('elo_diff', 50))

        results["9_adverse"] = self.model_adverse_selection(match_data.get('mkt_p', 0.1), match_data.get('theo_p', 0.2), match_data.get('ibi', 0.4))
        results["10_info_asym"] = self.model_information_asymmetry(match_data.get('smart', 'home'), match_data.get('pub', 'home'))
        results["11_minimax"] = self.model_minimax_strategy(match_data.get('liability', 300000))
        results["12_mixed_nash"] = self.model_mixed_strategy_nash(match_data.get('hp', 0.33), match_data.get('dp', 0.33), match_data.get('ap', 0.33))
        results["13_bayesian"] = self.model_bayesian_game(match_data.get('prior', 0.5), match_data.get('evidence', 0.1))
        results["14_sequential"] = self.model_sequential_game(match_data.get('early', 1.9), match_data.get('live', 1.85))
        results["15_repeated"] = self.model_repeated_game(match_data.get('h2h_draw', 0.2))
        results["16_evolutionary"] = self.model_evolutionary_game(match_data.get('heat_shift', 0.1))

        return results


