# 【新增技能】特征盲区与空间形变拓扑触发器 (OutOfBoundsTopologyTrigger)
# 发现: 极端爆冷或基础理论塌缩时，真实物理落点往往溢出到常规收敛池（15池）之外
# 功能: 实时监控多空流动性账本突变与空间形变梯度，向候选池动态补充“长尾极值项”
# ═══════════════════════════════════════════════════════════════════════════
class OutOfBoundsTopologyTrigger:
    """特征空间盲区主动捕获器 - 基于多维信号突变动态扩展高维可行域。
    
    三个信号:
    1. 结构性杠杆反转（非线性压力突变）
    2. 局部相空间剧烈撕裂（高IBI但理论过拟合未被入池的孤立突刺项）
    3. 多空账本发生严重单边亏损（庄家死亡敞口暴露）
    
    单次最高允许弹性扩展3个长尾奇点节点。
    """

    TRIGGER_MISALIGNMENT_JUMP = 1.0      # 特征位移撕裂跳变阈值
    TRIGGER_MISALIGNMENT_FLOOR = 2.0     # 跳变后防备指标下限

    @classmethod
    def detect_out_of_bounds_candidates(cls, current_pool15, liquidity_ledger=None, structural_trajectory='neutral'):
        """
        检测并返回应被纳入扩展可行域的长尾极值节点。
        
        Args:
            current_pool15: 当前提纯池节点集合 (list of dict)
            liquidity_ledger: 多空流动性账本数据 (含量、盈亏、极差)
            structural_trajectory: 结构性杠杆变动轨迹
        
        Returns:
            list: 空列表。越界只记事实，不补写死比分。
        """
        return []


# ─── 【新增技能】欧冠特殊赛事特征工程空间构建 ───
def extract_ucl_special_features(match_data, data_500, liquidity_ledger):
    """
    欧冠（UCL）特殊赛事特征工程空间构建。
    抽取时序与回合能量、流动性与清算极差、自适应风控判定。
    """
    try:
        ucl_features = {}
        # 1. 抽取时序与回合能量
        is_ucl = "欧冠" in str(match_data.get("league_name", "") or match_data.get("league", ""))
        ucl_features['feat_is_ucl'] = int(is_ucl)

        if is_ucl:
            # 捕捉回合对仗与残差势能
            leg_mode = 2.0 if "次回合" in str(match_data.get("match_name", "")) else 1.0
            ucl_features['feat_leg_sequence_mode'] = leg_mode

            # 提取首回合残差（无比分抽象化）
            first_leg_score = match_data.get("first_leg_score") or ""
            if "-" in str(first_leg_score) and leg_mode == 2.0:
                _flh, _fla = parse_score(first_leg_score)
                if _flh is not None and _fla is not None:
                    ucl_features['feat_first_leg_residual_gap'] = float(_flh - _fla)
                else:
                    ucl_features['feat_first_leg_residual_gap'] = 0.0
            else:
                ucl_features['feat_first_leg_residual_gap'] = 0.0

            # 2. 流动性与清算极差
            _liq = liquidity_ledger if isinstance(liquidity_ledger, dict) else {}
            volume = float(_liq.get('volume', 0.0) or 0)
            ucl_features['feat_pool_liquidity_density'] = volume

            max_loss = abs(float(_liq.get('max_loss', 0.0) or 0))
            max_profit = float(_liq.get('max_profit', 0.0) or 0)
            ucl_features['feat_cross_market_fissure_score'] = max_loss + max_profit

            # 3. 触发自适应风控判定
            # 欧冠极限高流下，极差突破500万，即锁死为真实逼空态 (Squeeze Area)
            ucl_features['feat_squeeze_priority_lock'] = int(volume > 500.0 and (max_loss + max_profit) > 500.0)
        else:
            ucl_features['feat_leg_sequence_mode'] = 1.0
            ucl_features['feat_first_leg_residual_gap'] = 0.0
            _liq = liquidity_ledger if isinstance(liquidity_ledger, dict) else {}
            ucl_features['feat_pool_liquidity_density'] = float(_liq.get('volume', 0.0) or 0)
            ucl_features['feat_cross_market_fissure_score'] = 0.0
            ucl_features['feat_squeeze_priority_lock'] = 0

        return ucl_features
    except Exception as _ucl_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [UCL特征工程] 异常(已降级): {_ucl_err}")
        return {'feat_is_ucl': 0, 'feat_leg_sequence_mode': 1.0,
                'feat_first_leg_residual_gap': 0.0, 'feat_pool_liquidity_density': 0.0,
                'feat_cross_market_fissure_score': 0.0, 'feat_squeeze_priority_lock': 0}


# ─── 【新增技能】多模态覆写前置置信度门控 (MultiModalConfidenceGate) ───
class MultiModalConfidenceGate:
    """
    多模态硬覆写前置审计 - 严格封锁低纯度流动性介质引发的有害熵增。
    
    审计维度:
    1. 流动性通量密度（>300万绝对单位为高置信）
    2. 多空清算极差张力（最大暴露敲口>400万为高置信）
    3. 拓扑锚点自洽性（物理相空间铁锚与资金账本恐惧轴共振为高置信）
    """
    VOLUME_HIGH = 300.0          # 极高通量阈值
    SPREAD_HIGH = 400.0          # 极高张力极差阈值
    CONFIDENCE_THRESHOLD = 0.65  # 激活强制物理覆写的最低安全阀值

    @classmethod
    def evaluate(cls, liquidity_ledger, topology_snapshot=None):
        if not liquidity_ledger or not isinstance(liquidity_ledger, dict):
            return 0.0, False, "外部流动性介质断连"

        score = 0.0
        reasons = []

        # 维度1: 流动性通量密度
        volume = float(liquidity_ledger.get('volume', 0) or 0)
        if volume >= cls.VOLUME_HIGH:
            score += 0.4
            reasons.append(f"介质通量{volume:.0f}(深水高压)")
        elif volume >= 150.0:
            score += 0.2
            reasons.append(f"介质通量{volume:.0f}(中等水压)")
        else:
            reasons.append(f"介质通量{volume:.0f}(浅水盲区)")

        # 维度2: 多空清算极差
        max_negative_exposure = abs(float(liquidity_ledger.get('max_loss', 0) or 0))
        max_positive_exposure = float(liquidity_ledger.get('max_profit', 0) or 0)
        spread = max_negative_exposure + max_positive_exposure
        if spread >= cls.SPREAD_HIGH:
            score += 0.4
            reasons.append(f"极差张力{spread:.0f}(显性撕裂)")
        elif spread >= 200.0:
            score += 0.2
            reasons.append(f"极差张力{spread:.0f}(中性振荡)")

        # 维度3: 拓扑映射自洽性
        if topology_snapshot and isinstance(topology_snapshot, dict):
            true_risk_axis = liquidity_ledger.get('true_direction', '')
            iron_anchors = topology_snapshot.get('anchors', [])
            if iron_anchors and true_risk_axis:
                anchor_vector_axes = set()
                for anchor in iron_anchors:
                    node_str = str(anchor).replace(':', '-').strip()
                    if '-' in node_str and '其它' not in node_str:
                        try:
                            val_pos, val_neg = parse_score(node_str)
                            if val_pos is None or val_neg is None:
                                continue

                            if val_pos > val_neg:
                                anchor_vector_axes.add('axis_positive')
                            elif val_pos == val_neg:
                                anchor_vector_axes.add('axis_neutral')
                            else:
                                anchor_vector_axes.add('axis_negative')
                        except (ValueError, IndexError):
                            pass
                # 将方向映射为兼容格式
                _axis_dir_map = {'home': 'axis_positive', 'draw': 'axis_neutral', 'away': 'axis_negative'}
                _mapped_risk = _axis_dir_map.get(true_risk_axis, true_risk_axis)
                if _mapped_risk in anchor_vector_axes:
                    score += 0.2
                    reasons.append("底层物理铁锚与多空介质真实风险轴达成同频共振")

        should_correct = score >= cls.CONFIDENCE_THRESHOLD
        return score, should_correct, " | ".join(reasons)


# ─── 【新增技能】系统状态标量期望动态校准器 (StateMagnitudeCalibrator) ───
class StateMagnitudeCalibrator:
    """
    标量（系统总能级）动态校准 - 基于滑动窗口对系统性外溢/衰减残差进行卷积自愈。
    """
    WINDOW_SIZE = 20      # 马尔可夫链滑动记忆窗口
    MAX_CORRECTION = 0.5  # 绝对物理限幅边界

    @classmethod
    def compute_calibration(cls, history_data):
        samples = []
        for fid, info in (history_data.items() if isinstance(history_data, dict) else []):
            if not isinstance(info, dict) or info.get('status') != 'completed':
                continue
            # 提取真实拓扑落点
            actual_node = str(info.get('actual_topology_node', info.get('actual_score', ''))).strip()
            if not actual_node or '-' not in actual_node:
                continue
            _an_h, _an_a = parse_score(actual_node)
            if _an_h is None or _an_a is None:
                continue
            actual_magnitude = _an_h + _an_a
            expected_magnitude = float(info.get('expected_magnitude', info.get('predicted_total_goals', 0)) or 0)
            if expected_magnitude > 0:
                samples.append(actual_magnitude - expected_magnitude)

        if len(samples) < 5:
            return 0.0

        recent_residuals = samples[-cls.WINDOW_SIZE:]
        avg_bias = sum(recent_residuals) / len(recent_residuals)
        calibration = max(-cls.MAX_CORRECTION, min(cls.MAX_CORRECTION, avg_bias))
        return round(calibration, 3)


# ─── 【改进】系统标量边界判定拓扑优化 (calibrated_boundary_prediction) ───
MAGNITUDE_CALIBRATION_BIAS = 0.15  # 正值表示实际标量长期呈现"动能外溢"，需施加上溢补偿

def calibrated_boundary_prediction(expected_magnitude, threshold_line, calibration=MAGNITUDE_CALIBRATION_BIAS):
    """
    校准后的标量阈值越界判定：融入历史残差补偿势能。
    替代原有的绝对判定，转为物理能级的"上穿"与"下沉"。
    """
    adjusted_magnitude = expected_magnitude + calibration
    if adjusted_magnitude >= threshold_line + 0.25:
        return 'Upper_Bound_Breakout'  # 突破上界 (火力外溢)
    elif adjusted_magnitude <= threshold_line - 0.25:
        return 'Lower_Bound_Sediment'  # 沉淀下界 (动能冰封)
    else:
        return 'Upper_Bound_Breakout' if adjusted_magnitude >= threshold_line else 'Lower_Bound_Sediment'


# ─── 【改进三】反共识陷阱检测器（升级版） ───
CONVERGENCE_SUSPICION_THRESHOLD = 0.80  # 降低阈值以更早触发检测


# ─── 拓扑能距（分差）聚合分析器 ───
class TopologyDeltaMatrixAnalyzer:
    """
    拓扑能距（分差）聚合分析器
    将离散的相空间节点按“势能差（净胜球）”进行降维切片，
    探测机构在同一物理能级下的防御断层，以及跨能级的动能溢出梯度。
    """

    # 定义极限冰封防御的物理红线
    FROZEN_IBI_THRESHOLD = 0.50
    # 定义同一分差组内产生“诱饵断层”的极差阈值
    FISSURE_SPREAD_THRESHOLD = 1.50

    @staticmethod
    def _parse_node_delta(node_coordinate: str) -> int:
        """解析空间坐标的势能差 (例如 '[2, 1]' -> 1, '[0, 2]' -> -2)"""
        try:
            cleaned = node_coordinate.replace('[', '').replace(']', '').replace(',', '-')
            _nc_h, _nc_a = parse_score(cleaned)
            if _nc_h is None or _nc_a is None:
                return 0
            return _nc_h - _nc_a
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·return 0降级 L5972] {_silent_err}")
            return 0

    @classmethod
    def execute_matrix_analysis(cls, pool15_data: list) -> dict:
        """执行全量相空间降维解析，输出聚合报告与预警信号"""
        if not pool15_data:
            return {}

        # 1. 按势能差 (Goal Difference) 进行正交聚合
        delta_groups = {}
        for node in pool15_data:
            delta = cls._parse_node_delta(node.get('node_coordinate', ''))
            if delta not in delta_groups:
                delta_groups[delta] = {
                    'nodes': [],
                    'total_intrinsic': 0.0,
                    'total_market': 0.0
                }
            delta_groups[delta]['nodes'].append(node)
            delta_groups[delta]['total_intrinsic'] += node.get('intrinsic_potential', 0.0)
            delta_groups[delta]['total_market'] += node.get('market_conversion', 0.0)

        # 2. 初始化侦测报告
        analysis_report = {
            'grouped_summary': {},
            'detected_fissures': [],
            'kinetic_gradients': {}
        }

        # 3. 遍历各聚合群，探测内部断层 (Intra-group Fissure)
        for delta, group in delta_groups.items():
            nodes = group['nodes']
            group_deviation = group['total_market'] - group['total_intrinsic']
            analysis_report['grouped_summary'][delta] = {
                'intrinsic_mass': round(group['total_intrinsic'], 4),
                'market_mass': round(group['total_market'], 4),
                'group_deviation': round(group_deviation, 4),
                'node_count': len(nodes)
            }

            if len(nodes) >= 2:
                ibis = [n.get('institutional_resistance', 1.0) for n in nodes]
                min_ibi = min(ibis)
                max_ibi = max(ibis)

                if min_ibi <= cls.FROZEN_IBI_THRESHOLD and (max_ibi - min_ibi) >= cls.FISSURE_SPREAD_THRESHOLD:
                    frozen_node = next(n for n in nodes if n.get('institutional_resistance') == min_ibi)
                    bait_node = next(n for n in nodes if n.get('institutional_resistance') == max_ibi)

                    analysis_report['detected_fissures'].append({
                        'delta_level': delta,
                        'frozen_anchor': frozen_node['node_coordinate'],
                        'bait_trap': bait_node['node_coordinate'],
                        'fissure_spread': round(max_ibi - min_ibi, 2),
                        'warning': f"检测到精确波胆定点爆破，机构正在掩护 {frozen_node['node_coordinate']}"
                    })

        # 4. 计算跨维动能梯度 (Cross-group Gradient)
        for direction in [1, -1]:
            base_delta = 1 * direction
            next_delta = 2 * direction

            if base_delta in delta_groups and next_delta in delta_groups:
                base_ibis = [n.get('institutional_resistance', 1.0) for n in delta_groups[base_delta]['nodes']]
                next_ibis = [n.get('institutional_resistance', 1.0) for n in delta_groups[next_delta]['nodes']]

                avg_base_ibi = statistics.mean(base_ibis) if base_ibis else 1.0
                avg_next_ibi = statistics.mean(next_ibis) if next_ibis else 1.0

                gradient = avg_next_ibi - avg_base_ibi
                status = "smooth_overflow" if gradient < 0.8 else "hard_wall_blockade"
                analysis_report['kinetic_gradients'][f"{base_delta}_to_{next_delta}"] = {
                    'gradient_value': round(gradient, 2),
                    'status': status,
                    'implication': "动能顺势溢出通道敎开" if status == "smooth_overflow" else "遇到高阶物理硬墙阻断"
                }

        return analysis_report


# ─── A.R.T. 兼容入口：唯一委托 DeviationDrivenEngine ───
def classify_score_logic(score_data):
    """兼容旧调用方；仅返回TIER_1_KILL/TIER_2_DEFENSE/UNKNOWN。"""
    try:
        normalized = DeviationDrivenEngine.normalize_record(score_data)
        if not normalized:
            return 'UNKNOWN'
        classified = DeviationDrivenEngine.classify_and_score([normalized])
        return str(classified[0].get('tier', 'UNKNOWN')) if classified else 'UNKNOWN'
    except Exception as classify_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [A.R.T.偏差兼容入口] 分级异常(已置UNKNOWN): {classify_error}")
        return 'UNKNOWN'


def check_annihilation(pool15_classified):
    """旧湮灭强制比分规则已删除；任何情形均不得覆写偏差核心。"""
    try:
        _ = pool15_classified
        return False, None, '旧A.R.T.湮灭强制比分已停用，唯一决策核心为DeviationDrivenEngine'
    except Exception as annihilation_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [A.R.T.偏差兼容入口] 湮灭停用检查异常: {annihilation_error}")
        return False, None, ''
# ─── 降维视图格式化器 (Telegram 呈现优化) ───
class TelegramReportFormatter:
    """
    降维视图格式化器 (针对 Telegram 呈现优化)
    """

    @staticmethod
    def _get_delta_label(delta: int) -> str:
        """映射物理能距到人类可读的盘口标签"""
        if delta == 0: return "(平局)"
        elif delta > 0: return f"(主胜{delta}球)"
        else: return f"(客胜{abs(delta)}球)"

    @staticmethod
    def _format_deviation(dev: float) -> str:
        """偏差视觉锚点：极性判定"""
        dev_pct = dev * 100
        if dev_pct > 0.5:
            return f"+{dev_pct:.1f}% 📈"
        elif dev_pct < -0.5:
            return f"{dev_pct:.1f}% 📉"
        return f"{dev_pct:.1f}% ⟖"

    @staticmethod
    def _format_ibi(ibi: float) -> str:
        """机构阻力视觉锚点：冰封与过载判定"""
        if ibi <= 0.50:
            return f"{ibi:.2f} ❄️"
        elif ibi >= 2.50:
            return f"{ibi:.2f} 🔥"
        return f"{ibi:.2f}"

    @classmethod
    def generate_tg_markdown(cls, pool15_data: list, analysis_report: dict) -> str:
        """
        组装 Telegram Markdown 报告文本（新版：仅输出top2分差组及组内有效比分）

        pool15_data 中每个节点须含以下字段（由调用处从 _pool15_enriched 直接传入）：
          score                  原始比分字符串，如 '1-0'
          theory / intrinsic_potential  理论概率（百分比，0-100）
          market / market_conversion    市场概率（百分比，0-100）
          ibi / institutional_resistance  IBI值
          delta / topological_deviation   偏差（百分比差，如 -2.3）

        剔除规则（同一分差内不可能的比分）：
          1. theory_prob <= 1.0%
          2. market_prob == 0.0%
          3. IBI > 6.58（过载区）
          4. 含"其它"的虚拟比分不参与分差聚合

        分差组排序：组内所有有效比分的 market 概率之和降序，取 top2。
        """
        # ── Step 1: 解析每个节点，兼容新旧字段名 ──
        parsed_nodes = []
        for node in pool15_data:
            # 兼容两种字段名：score 或 node_coordinate
            score = node.get('score', '')
            if not score:
                coord = node.get('node_coordinate', '')
                score = coord.replace('[', '').replace(']', '').replace(', ', '-').replace(' ', '')
            score = str(score).strip()

            # 剔除虚拟比分
            if '其它' in score:
                continue

            # 解析主客队进球数
            if '-' not in score:
                continue
            try:
                home_g, away_g = parse_score(score)


            except Exception:  # noqa: BLE001,S112 - intentional degraded-mode guard or structure-preserving fallback  # nosec B112  # intentional degraded-mode continue fallback
                continue
            if home_g is None or away_g is None:
                continue

            # 兼容两种字段名：theory/intrinsic_potential，market/market_conversion，ibi/institutional_resistance，delta/topological_deviation
            theory = float(node.get('theory', node.get('intrinsic_potential', 0)) or 0)
            market = float(node.get('market', node.get('market_conversion', 0)) or 0)
            ibi = float(node.get('ibi', node.get('institutional_resistance', 1.0)) or 1.0)
            delta = float(node.get('delta', node.get('topological_deviation', 0)) or 0)

            # ── 剔除规则 ──
            if theory <= 1.0:   # theory_prob <= 1.0%
                continue
            if market == 0.0:   # market_prob == 0.0%
                continue
            if ibi > 6.58:      # IBI过载区
                continue

            diff = home_g - away_g  # 带符号分差
            parsed_nodes.append({
                'score': score,
                'diff': diff,
                'theory': theory,
                'market': market,
                'ibi': ibi,
                'delta': delta,
            })

        if not parsed_nodes:
            return "📊 *〈15池分差聚合矩阵 | 理论 vs 市场 vs IBI〉*\n  ⚠️ 无有效比分数据"

        # ── Step 2: 按分差分组 ──
        diff_group_map = {}
        for nd in parsed_nodes:
            d = nd['diff']
            if d not in diff_group_map:
                diff_group_map[d] = []
            diff_group_map[d].append(nd)

        # ── Step 3: 计算各分差组的 market 概率之和，降序取 top2 ──
        group_scores = []
        for d, nodes in diff_group_map.items():
            market_sum = sum(nd['market'] for nd in nodes)
            group_scores.append((d, nodes, market_sum))
        group_scores.sort(key=lambda x: x[2], reverse=True)
        top2_groups = group_scores[:2]

        # ── Step 4: 组装TG报告 ──
        lines = []
        lines.append("📊 *〈15池分差聚合矩阵 | 理论 vs 市场 vs IBI〉*")

        for d, nodes, _ in top2_groups:
            # 分差标签
            if d > 0:
                diff_label = f"分差+{d}"
            elif d < 0:
                diff_label = f"分差{d}"
            else:
                diff_label = "分差0"

            # 组内比分按 market 降序排列
            nodes_sorted = sorted(nodes, key=lambda x: x['market'], reverse=True)

            score_parts = []
            for nd in nodes_sorted:
                sc = nd['score']
                th = nd['theory']
                mk = nd['market']
                ib = nd['ibi']
                score_parts.append(f"{sc}(理论{th:.1f}%/市场{mk:.1f}%/IBI {ib:.2f})")

            scores_str = ", ".join(score_parts)
            lines.append(f"{diff_label}: {scores_str}")

        return "\n".join(lines)


# ============================================================================
# 【统一研判报告骨架 · Unified Analysis Report Skeleton】
# 一个 formatter，三个渲染器：CLI 指令输出 / Telegram 文本 / Streamlit 页面。
# 所有分析输出共用同一骨架，顺序固定，不随入口改变：
#   结论 → 关键数据 → 分歧点 → 风险与陷阱 → 证据链 → 教训匹配
# ============================================================================
UNIFIED_REPORT_SCHEMA = 'blade.unified_report.v1'
UNIFIED_REPORT_SECTIONS: tuple[tuple[str, str], ...] = (
    ('verdict', '结论'),
    ('key_data', '关键数据'),
    ('divergence', '分歧点'),
    ('risk', '风险与陷阱'),
    ('evidence', '证据链'),
    ('lessons', '教训匹配'),
)
UNIFIED_REPORT_SECTION_KEYS: tuple[str, ...] = tuple(key for key, _title in UNIFIED_REPORT_SECTIONS)
UNIFIED_REPORT_SECTION_ICONS = {
    'verdict': '🎯',
    'key_data': '📊',
    'divergence': '⚖️',
    'risk': '⚠️',
    'evidence': '🧾',
    'lessons': '📖',
}
UNIFIED_REPORT_TELEGRAM_LIMIT = 4096
# 留出安全余量：send_tg 自身按 4000 字分片，这里先压到 3900 以内。
UNIFIED_REPORT_TELEGRAM_BUDGET = 3900
_CONFIDENCE_RANK = {'高': 5, '中偏高': 4, '中': 3, '中偏低': 2, '低': 1}
_CONFIDENCE_MID_SCORE = {'高': 82.0, '中偏高': 70.0, '中': 55.0, '中偏低': 40.0, '低': 25.0}


def _ur_float(value: Any, default: float = 0.0) -> float:
    """把任意输入压成有限浮点，NaN/inf/垃圾值统一回退 default。"""
    try:
        number = float(value)
    except (TypeError, ValueError):
        return default
    return number if math.isfinite(number) else default


def _ur_mapping(value: Any) -> dict[str, Any]:
    return value if isinstance(value, dict) else {}


def _ui_dict(value: Any) -> dict[str, Any]:
    """Pyright 友好版本：显式标注返回 dict，避免 Optional 窄化丢失。"""
    if isinstance(value, dict):
        return value
    return {}


def _ur_confidence_label(info: dict[str, Any]) -> str:
    label = str(info.get('confidence') or '').strip()
    return label if label in _CONFIDENCE_RANK else '低'


def _ur_confidence_score(info: dict[str, Any]) -> float:
    """融合强度优先；缺失时按置信度档位给出中位分，保证骨架永远有数可看。"""
    strength = get_prediction_strength(info) if callable(globals().get('get_prediction_strength')) else 0.0
    if strength and strength > 0:
        return round(_ur_float(strength), 1)
    return _CONFIDENCE_MID_SCORE.get(_ur_confidence_label(info), 25.0)


def _ur_match_label(info: dict[str, Any]) -> str:
    name = str(info.get('match') or info.get('cn_name') or '').strip()
    return name or '未命名赛事'


def _ur_title_line(info: dict[str, Any]) -> str:
    """赛号/星期/开赛时间/对阵 的统一标题行，缺字段就降级，不抛异常。"""
    name = _ur_match_label(info)
    kickoff = str(info.get('time') or info.get('match_time') or info.get('kickoff') or '').strip()
    analyzer = globals().get('DeepSeekAnalyzer')
    if analyzer is not None:
        try:
            header = analyzer.format_tg_match_header(
                str(info.get('match') or ''),
                kickoff=kickoff,
                match_no=str(info.get('no') or info.get('local_id') or ''),
            )
            if header:
                return str(header)
        except Exception as exc:  # noqa: BLE001 - 标题美化失败不能影响主报告
            print(f"   ⚠️ [统一报告] 标题格式化降级: {type(exc).__name__}")
    return f"{kickoff} | {name}" if kickoff else name


def _ur_market_implied_1x2(info: dict[str, Any]) -> dict[str, float]:
    """把 1X2 欧赔换成去水后的市场隐含概率；数据不全就返回空 dict。"""
    odds = _ur_mapping(info.get('odds_1x2'))
    if not odds:
        return {}
    home = _ur_float(odds.get('Home', odds.get('home')), 0.0)
    draw = _ur_float(odds.get('Draw', odds.get('draw')), 0.0)
    away = _ur_float(odds.get('Away', odds.get('away')), 0.0)
    if min(home, draw, away) <= 1.0:
        return {}
    inverse = (1.0 / home) + (1.0 / draw) + (1.0 / away)
    if inverse <= 0:
        return {}
    return {
        'home': (1.0 / home) / inverse,
        'draw': (1.0 / draw) / inverse,
        'away': (1.0 / away) / inverse,
        'return_rate': 1.0 / inverse,
    }


def _ur_market_over_prob(info: dict[str, Any], line: float | None) -> float | None:
    """用总进球隐含分布反推大球概率，行数缺失时返回 None。"""
    if line is None:
        return None
    implied = _ur_mapping(info.get('tg_implied_probs'))
    if not implied:
        return None
    scale = 1.0
    sample = next((v for v in implied.values() if isinstance(v, (int, float))), None)
    if sample is not None and _ur_float(sample) > 1.5:
        scale = 100.0
    over = 0.0
    seen = False
    for goals in range(7):
        raw = implied.get(f'prob_{goals}')
        if raw is None:
            continue
        seen = True
        if goals > line:
            over += _ur_float(raw) / scale
    seven_plus = implied.get('prob_7plus')
    if seven_plus is not None:
        seen = True
        if 7 > line:
            over += _ur_float(seven_plus) / scale
    return over if seen else None


def _ur_divergence_items(info: dict[str, Any]) -> list[dict[str, Any]]:
    """模型 vs 市场的分歧点，按百分点差距降序，最多 4 条。"""
    items: list[dict[str, Any]] = []
    markets = _ur_mapping(info.get('derived_markets'))

    model_1x2 = _ur_mapping(markets.get('1x2'))
    market_1x2 = _ur_market_implied_1x2(info)
    if model_1x2 and market_1x2:
        labels = (('home', '主胜'), ('draw', '平局'), ('away', '客胜'))
        gaps = []
        for key, label in labels:
            model_p = _ur_float(model_1x2.get(key))
            market_p = _ur_float(market_1x2.get(key))
            gaps.append((abs(model_p - market_p), label, model_p, market_p))
        gaps.sort(reverse=True)
        gap, label, model_p, market_p = gaps[0]
        if gap > 0.01:
            direction = '模型更看好' if model_p > market_p else '市场更看好'
            items.append({
                'topic': f'胜平负·{label}',
                'model': f'{model_p:.1%}',
                'market': f'{market_p:.1%}',
                'magnitude_pp': round(gap * 100, 1),
                'magnitude_text': f'{gap * 100:.1f}pp',
                'note': f'{direction}{label}，模型与市场相差 {gap * 100:.1f} 个百分点',
            })

    ou = _ur_mapping(markets.get('ou'))
    if ou:
        line = _ur_float(ou.get('line'), 2.5) if ou.get('line') is not None else None
        model_over = _ur_float(ou.get('over'))
        market_over = _ur_market_over_prob(info, line)
        if market_over is not None:
            gap = abs(model_over - market_over)
            if gap > 0.01:
                side = '模型更看大' if model_over > market_over else '模型更看小'
                items.append({
                    'topic': f'大小球·{line if line is not None else 2.5}',
                    'model': f'大球 {model_over:.1%}',
                    'market': f'大球 {market_over:.1%}',
                    'magnitude_pp': round(gap * 100, 1),
                    'magnitude_text': f'{gap * 100:.1f}pp',
                    'note': f'{side}，与市场隐含相差 {gap * 100:.1f} 个百分点',
                })

    ml = _ur_mapping(info.get('ml_prediction'))
    if ml.get('used'):
        trad = _ur_mapping(ml.get('traditional_lambda'))
        poisson = _ur_mapping(ml.get('poisson_lambda'))
        if trad and poisson:
            delta_h = _ur_float(poisson.get('home')) - _ur_float(trad.get('home'))
            delta_a = _ur_float(poisson.get('away')) - _ur_float(trad.get('away'))
            worst = max(abs(delta_h), abs(delta_a))
            if worst > 0.05:
                base = max(abs(_ur_float(trad.get('home'))), abs(_ur_float(trad.get('away'))), 0.05)
                items.append({
                    'topic': 'λ 标定·ML vs 传统',
                    'model': f'ML λ=({_ur_float(poisson.get("home")):.2f},{_ur_float(poisson.get("away")):.2f})',
                    'market': f'传统 λ=({_ur_float(trad.get("home")):.2f},{_ur_float(trad.get("away")):.2f})',
                    'magnitude_pp': round(worst / base * 100, 1),
                    'magnitude_text': f'λ 偏移 {worst:.2f} 球',
                    'note': f'ML 融合矩阵较传统泊松偏移 {worst:.2f} 球，注意总进球口径',
                })

    lock = _ur_mapping(info.get('direction_lock'))
    locked = str(lock.get('direction') or '').strip()
    predicted = str(info.get('predicted_result') or '').strip()
    if locked in ('胜', '平', '负') and predicted in ('胜', '平', '负') and locked != predicted:
        items.append({
            'topic': '方向·方向锁 vs 模型',
            'model': f'方向锁 {locked}',
            'market': f'模型 {predicted}',
            'magnitude_pp': 100.0,
            'magnitude_text': '方向相反',
            'note': '方向锁与模型倾向相反，按方向锁执行，模型结论仅作参考',
        })

    items.sort(key=lambda item: _ur_float(item.get('magnitude_pp')), reverse=True)
    return items[:4]


def _ur_risk_items(info: dict[str, Any]) -> list[dict[str, Any]]:
    """风险与陷阱：每条都必须带可核对的触发条件。"""
    risks: list[dict[str, Any]] = []
    markets = _ur_mapping(info.get('derived_markets'))
    ou = _ur_mapping(markets.get('ou'))
    ou_line = info.get('ou_line')
    if ou_line is None and ou.get('line') is not None:
        ou_line = ou.get('line')

    if info.get('is_edge'):
        over_p = _ur_float(ou.get('over'))
        risks.append({
            'level': '中',
            'title': '大小球高度边缘',
            'trigger': f'盘口线 {ou_line if ou_line is not None else "未知"}，模型大球概率 {over_p:.1%}',
            'detail': '边缘盘建议同时保留反向预案，不要单边重仓。',
        })
    if info.get('dti_protected'):
        risks.append({
            'level': '高',
            'title': 'DTI 保护已激活',
            'trigger': f'保护类型 {info.get("dti_protection_type") or "未标注"}',
            'detail': '保护态的比分分布被压平，首选比分可信度下降，优先看方向。',
        })
    cold = _ur_float(info.get('cold_score'))
    if cold >= 50:
        risks.append({
            'level': '高' if cold >= 70 else '中',
            'title': '冷门预警',
            'trigger': f'冷门分 {cold:.0f} ≥ 50',
            'detail': '热门方向存在被做局可能，仓位下调并保留次选。',
        })
    cup_mode = str(info.get('cup_mode') or '常规')
    if cup_mode not in ('常规', ''):
        risks.append({
            'level': '中',
            'title': '杯赛/淘汰赛模式',
            'trigger': f'检测到 {cup_mode}',
            'detail': str(info.get('cup_note') or '两回合制会改变球队进攻意愿，模型假设需打折。'),
        })
    if info.get('homo_triggered'):
        risks.append({
            'level': '中',
            'title': '同质化 λ 惩罚',
            'trigger': '当日已出现相同 λ 模式场次',
            'detail': '同模式重复下注会被集中定价，建议错开或减仓。',
        })
    anomaly = _ur_mapping(info.get('anomaly_payload'))
    if anomaly.get('is_squeeze'):
        risks.append({
            'level': '高',
            'title': '逼空/陷阱形态',
            'trigger': 'anomaly_payload.is_squeeze = True',
            'detail': '市场在诱导单边，陷阱预警段为反向分析模式。',
        })
    completeness = _ur_float(info.get('feature_completeness'))
    if 0 < completeness < 0.6:
        risks.append({
            'level': '低',
            'title': '特征完整度偏低',
            'trigger': f'特征完整度 {completeness:.0%} < 60%',
            'detail': '缺失特征由先验填补，结论稳定性弱于常规场次。',
        })
    # 数据不足场次：把“缺的是哪个源”写进风险段，报告里能直接看出为什么没比分。
    missing_inputs = _ur_missing_inputs(info)
    if missing_inputs and _ur_data_insufficient(info, missing_inputs):
        risks.insert(0, {
            'level': '高',
            'title': '关键输入未形成（数据不足）',
            'trigger': '；'.join(missing_inputs),
            'detail': (
                '上游明确不补默认进球期望，本场不出比分结论；'
                '补齐手机市均/盘口后重新分析，不要按旧结论或空整合包下单。'
            ),
        })
    if not risks:
        risks.append({
            'level': '低',
            'title': '未触发硬风险闸门',
            'trigger': '冷门分<50、无 DTI 保护、盘口非边缘、非杯赛模式',
            'detail': '风险面干净，但仍按仓位纪律执行。',
        })
    return risks


def _ur_evidence_items(info: dict[str, Any]) -> list[dict[str, Any]]:
    """证据链：原始信号 + 来源 + 时间戳，便于复盘回溯。"""
    calib = _ur_mapping(info.get('lambda_calibration'))
    items: list[dict[str, Any]] = [
        {
            'signal': '抓取完成时间',
            'value': str(info.get('pipeline_scrape_at') or '未记录'),
            'source': str(info.get('correct_score_channel') or 'mobile'),
            'timestamp': str(info.get('pipeline_scrape_at') or ''),
        },
        {
            'signal': '赔率快照时间',
            'value': str(info.get('odds_snapshot_time_curr') or '未记录'),
            'source': 'odds_snapshot_curr',
            'timestamp': str(info.get('odds_snapshot_time_curr') or ''),
        },
        {
            'signal': '比分池版本',
            'value': f'{len(info.get("top15_scores") or [])} 个候选',
            'source': 'score_pool31_views',
            'timestamp': str(info.get('pipeline_scrape_at') or ''),
        },
        {
            'signal': '数据源就绪',
            'value': '500网 ' + ('可用' if info.get('data_500_available') else '缺失'),
            'source': 'data_500',
            'timestamp': str(info.get('pipeline_scrape_at') or ''),
        },
    ]
    if calib.get('available'):
        hist = _ur_mapping(calib.get('historical'))
        final = _ur_mapping(calib.get('final'))
        items.append({
            'signal': 'λ 校准样本',
            'value': (
                f'{int(_ur_float(calib.get("sample_count")))} 家机构 | '
                f'历史λ=({_ur_float(hist.get("home")):.2f},{_ur_float(hist.get("away")):.2f}) → '
                f'最终λ=({_ur_float(final.get("home")):.2f},{_ur_float(final.get("away")):.2f})'
            ),
            'source': 'LambdaCalibrator',
            'timestamp': str(info.get('pipeline_scrape_at') or ''),
        })
    if info.get('okooo_match_id'):
        items.append({
            'signal': '澳客赛事ID',
            'value': str(info.get('okooo_match_id')),
            'source': 'okooo_mobile_cs',
            'timestamp': str(info.get('pipeline_scrape_at') or ''),
        })
    return items


def _ur_lesson_items(info: dict[str, Any], limit: int = 3) -> list[dict[str, Any]]:
    """从教训库挑与本场语境相关的条目，命中关键词即视为适用。"""
    try:
        raw = load_brain_rules() if callable(globals().get('load_brain_rules')) else ''
    except Exception as exc:  # noqa: BLE001 - 教训库读取失败不应影响主报告
        print(f"   ⚠️ [统一报告] 教训库读取降级: {type(exc).__name__}")
        raw = ''
    rules = [line.strip().lstrip('-• ').strip() for line in str(raw or '').splitlines()]
    rules = [rule for rule in rules if rule]
    if not rules:
        return []
    context_tokens = []
    if _ur_float(info.get('cold_score')) >= 50:
        context_tokens.append('冷门')
    if info.get('is_edge'):
        context_tokens.append('边缘')
    if str(info.get('cup_mode') or '常规') not in ('常规', ''):
        context_tokens.append('杯赛')
    if str(info.get('big_small') or '') in ('大球', '小球'):
        context_tokens.append('大小球')
    direction = str(info.get('predicted_result') or '').strip()
    if direction in ('胜', '平', '负'):
        context_tokens.append(direction)
    matched: list[dict[str, Any]] = []
    seen: set[str] = set()
    for rule in rules:
        if rule in seen:
            continue
        hits = [token for token in context_tokens if token and token in rule]
        if hits:
            seen.add(rule)
            matched.append({'rule': rule, 'reason': f'命中本场语境：{"、".join(hits)}'})
        if len(matched) >= limit:
            break
    if matched:
        return matched
    for rule in rules[:limit]:
        matched.append({'rule': rule, 'reason': '通用铁律，长期有效'})
    return matched


def _ur_missing_inputs(data: dict[str, Any]) -> list[str]:
    """列出本场缺失的关键输入（λ 未形成 / 手机市均未就绪 等）。

    优先用分析时写下的 missing_inputs；没有就按字段现算。
    只依据记录里的字段判断，不猜、不补默认值；同一原因只列一次。
    """
    recorded = data.get('missing_inputs')
    if isinstance(recorded, list) and recorded:
        return [str(item) for item in recorded if str(item or '').strip()]

    missing: list[str] = []

    def _add(text: str, marker: str) -> None:
        if not text:
            return
        if any(marker in item for item in missing):
            return
        missing.append(text)

    _add(str(data.get('score_not_formed_reason') or '').strip(), 'λ')
    lam_h = data.get('lambda_home') if data.get('lambda_home') is not None else data.get('lam_h')
    lam_a = data.get('lambda_away') if data.get('lambda_away') is not None else data.get('lam_a')
    if lam_h is None or lam_a is None:
        _add('λ 未形成（上游拒绝补默认进球期望）', 'λ')
    if data.get('correct_score_available') is False:
        _add('手机市均未就绪（比分市均/盘口未抓到）', '手机市均')
    if not data.get('odds_1x2') and not data.get('derived_markets') and not data.get('top15_scores'):
        _add('胜平负赔率未形成', '胜平负赔率')
    return missing


def _ur_record_analysed(data: dict[str, Any]) -> bool:
    """这条记录是否真的跑过分析（而不是一条空壳/未抓取记录）。"""
    if data.get('pipeline_scrape_done') or data.get('pipeline_scrape_at'):
        return True
    if str(data.get('score_not_formed_reason') or '').strip():
        return True
    if isinstance(data.get('odds_1x2'), dict) and data.get('odds_1x2'):
        return True
    return bool(data.get('derived_markets') or data.get('top15_scores'))


def _ur_data_insufficient(data: dict[str, Any], missing: list[str]) -> bool:
    """True when this record was analysed but has no score verdict and a recorded reason."""
    primary = str(data.get('predicted_score') or data.get('first_score') or '').strip()
    has_score = bool(primary and primary not in ('➖', 'None', 'none'))
    if has_score or not missing:
        return False
    return _ur_record_analysed(data)


def build_unified_analysis_report(
    info: Any,
    source: str = 'streamlit',
    generated_at: str | None = None,
) -> dict[str, Any]:
    """把任意一场 history 记录压成统一六段骨架。任何字段缺失都不抛异常。

    λ 未形成 / 手机市均未就绪时不出比分结论，结论段写「数据不足」并点名
    缺的输入；关键数据仍展示已经到手的赔率/1x2 事实；风险段记下缺失来源。
    """
    data = info if isinstance(info, dict) else {}
    confidence = _ur_confidence_label(data)
    confidence_score = _ur_confidence_score(data)
    primary = str(data.get('predicted_score') or data.get('first_score') or '').strip()
    secondary = str(data.get('second_score') or '').strip()
    direction = str(data.get('predicted_result') or '').strip()
    lock = _ur_mapping(data.get('direction_lock'))
    if str(lock.get('direction') or '') in ('胜', '平', '负'):
        direction = str(lock.get('direction'))

    missing_inputs = _ur_missing_inputs(data)
    data_insufficient = _ur_data_insufficient(data, missing_inputs)
    if data_insufficient:
        verdict = (
            '数据不足：' + '；'.join(missing_inputs)
            + '。本场不出比分结论，不补默认 λ，也不拿空整合包冒充手机市均。'
        )
    elif primary and primary not in ('➖', 'None', 'none'):
        verdict = (
            f"首选 {primary}｜次选 {secondary or '未形成'}｜方向 {direction or '未形成'}"
            f"｜置信度 {confidence}（{confidence_score:.1f}%）"
        )
    else:
        verdict = '尚未形成结论：缺少抓取结果，先执行「分析」再研判。'

    markets = _ur_mapping(data.get('derived_markets'))
    ou = _ur_mapping(markets.get('ou'))
    metrics = [
        {'label': '融合强度', 'value': f'{_ur_float(get_prediction_strength(data) if callable(globals().get("get_prediction_strength")) else 0.0):.1f}%', 'hint': '模型首选比分概率'},
        {'label': '冷门分', 'value': f'{_ur_float(data.get("cold_score")):.0f}', 'hint': '≥50 触发冷门预警'},
        {'label': 'DTI', 'value': f'{_ur_float(data.get("dti")):.3f}', 'hint': '离散度张力指标'},
        {'label': '大小球', 'value': str(data.get('big_small') or '未形成'), 'hint': f'盘口线 {data.get("ou_line") if data.get("ou_line") is not None else (ou.get("line") if ou.get("line") is not None else "未知")}'},
        {'label': 'λ 主/客', 'value': _ur_lambda_text(data), 'hint': '泊松期望进球（未形成时不补默认值）'},
        {'label': '特征完整度', 'value': f'{_ur_float(data.get("feature_completeness")):.0%}', 'hint': '低于 60% 需降权'},
    ]
    # 数据不足时，把已经到手的赔率/1x2 事实单独列出来，别让“缺 λ”吞掉真数据。
    if data_insufficient:
        metrics.extend(_ur_arrived_market_metrics(data))

    return {
        'schema': UNIFIED_REPORT_SCHEMA,
        'source': str(source or 'streamlit'),
        'generated_at': generated_at or datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
        'title': _ur_title_line(data),
        'match': _ur_match_label(data),
        'league': str(data.get('league') or '未知联赛'),
        'confidence': confidence,
        'confidence_score': confidence_score,
        'data_insufficient': data_insufficient,
        'missing_inputs': missing_inputs,
        'sections': [
            {
                'key': 'verdict',
                'title': '结论',
                'verdict': verdict,
                'confidence': confidence,
                'confidence_score': confidence_score,
                'direction': direction,
                'primary': primary,
                'secondary': secondary,
                'data_insufficient': data_insufficient,
                'missing_inputs': missing_inputs,
            },
            {'key': 'key_data', 'title': '关键数据', 'metrics': metrics},
            {'key': 'divergence', 'title': '分歧点', 'items': _ur_divergence_items(data)},
            {'key': 'risk', 'title': '风险与陷阱', 'items': _ur_risk_items(data)},
            {'key': 'evidence', 'title': '证据链', 'items': _ur_evidence_items(data)},
            {'key': 'lessons', 'title': '教训匹配', 'items': _ur_lesson_items(data)},
        ],
    }


def _ur_lambda_text(data: dict[str, Any]) -> str:
    """λ 展示：未形成就明说，不把 None 显示成 0.00。"""
    lam_h = data.get('lambda_home') if data.get('lambda_home') is not None else data.get('lam_h')
    lam_a = data.get('lambda_away') if data.get('lambda_away') is not None else data.get('lam_a')
    if lam_h is None or lam_a is None:
        return '未形成'
    return f'{_ur_float(lam_h):.2f} / {_ur_float(lam_a):.2f}'


def _ur_arrived_market_metrics(data: dict[str, Any]) -> list[dict[str, Any]]:
    """数据不足场次里，列出真正到达的盘口事实（1x2 赔率 / 盘口线）。"""
    rows: list[dict[str, Any]] = []
    odds_1x2 = _ur_mapping(data.get('odds_1x2'))
    if odds_1x2:
        home = _safe_odds(odds_1x2.get('Home', odds_1x2.get('home')))
        draw = _safe_odds(odds_1x2.get('Draw', odds_1x2.get('draw')))
        away = _safe_odds(odds_1x2.get('Away', odds_1x2.get('away')))
        if home or draw or away:
            rows.append({
                'label': '胜平负赔率',
                'value': ' / '.join(
                    '-' if value is None else f'{value:.2f}' for value in (home, draw, away)
                ),
                'hint': '1X2 已到达（主/平/客），但 λ 未形成，不出比分',
            })
    implied = _ur_market_implied_1x2(data)
    if implied:
        rows.append({
            'label': '去水隐含',
            'value': (
                f"主{implied['home']:.1%}/平{implied['draw']:.1%}/客{implied['away']:.1%}"
            ),
            'hint': f"返还率 {implied['return_rate']:.1%}，仅记市场事实",
        })
    line = data.get('ou_line')
    if line is None:
        line = _ur_mapping(_ur_mapping(data.get('derived_markets')).get('ou')).get('line')
    if line is not None:
        rows.append({
            'label': '大小球盘口',
            'value': str(line),
            'hint': '盘口线已到达，缺少 λ 无法算理论大小球概率',
        })
    return rows


def _ur_section(report: dict[str, Any], key: str) -> dict[str, Any]:
    for section in report.get('sections') or []:
        if isinstance(section, dict) and section.get('key') == key:
            return section
    return {'key': key, 'title': key}


def _ur_risk_line(item: dict[str, Any]) -> str:
    return (
        f"[{item.get('level') or '低'}] {item.get('title')}"
        f" | 触发: {item.get('trigger')} | {item.get('detail')}"
    )


def _ur_magnitude_text(item: dict[str, Any]) -> str:
    """分歧力度的人类可读文本：概率类用 pp，λ 类用球数。"""
    text = str(item.get('magnitude_text') or '').strip()
    if text:
        return text
    return f"{_ur_float(item.get('magnitude_pp')):.1f}pp"


def _ur_divergence_line(item: dict[str, Any]) -> str:
    return (
        f"{item.get('topic')}: 模型 {item.get('model')} vs 市场 {item.get('market')}"
        f" | 差 {_ur_magnitude_text(item)} | {item.get('note')}"
    )


def format_unified_report_cli(report: dict[str, Any]) -> str:
    """CLI 指令渲染器：纯文本、可管道、无 emoji 依赖。"""
    lines: list[str] = [
        f"==== 统一研判报告 [{report.get('schema')}] ====",
        f"赛事: {report.get('title')}",
        f"联赛: {report.get('league')} | 来源: {report.get('source')} | 生成: {report.get('generated_at')}",
        '-' * 60,
    ]
    verdict = _ur_section(report, 'verdict')
    lines.append(f"[{verdict.get('title')}]")
    lines.append(f"  {verdict.get('verdict')}")

    key_data = _ur_section(report, 'key_data')
    lines.append(f"[{key_data.get('title')}]")
    metrics = key_data.get('metrics') or []
    if metrics:
        for metric in metrics:
            lines.append(f"  - {metric.get('label')}: {metric.get('value')}  ({metric.get('hint')})")
    else:
        lines.append('  - 暂无关键数据')

    divergence = _ur_section(report, 'divergence')
    lines.append(f"[{divergence.get('title')}]")
    div_items = divergence.get('items') or []
    if div_items:
        lines.extend(f"  - {_ur_divergence_line(item)}" for item in div_items)
    else:
        lines.append('  - 模型与市场暂无明显分歧')

    risk = _ur_section(report, 'risk')
    lines.append(f"[{risk.get('title')}]")
    for item in risk.get('items') or []:
        lines.append(f"  - {_ur_risk_line(item)}")

    evidence = _ur_section(report, 'evidence')
    lines.append(f"[{evidence.get('title')}]")
    for item in evidence.get('items') or []:
        lines.append(
            f"  - {item.get('signal')}: {item.get('value')} | 来源 {item.get('source')}"
            f" | {item.get('timestamp') or '无时间戳'}"
        )

    lessons = _ur_section(report, 'lessons')
    lines.append(f"[{lessons.get('title')}]")
    lesson_items = lessons.get('items') or []
    if lesson_items:
        lines.extend(f"  - {item.get('rule')}  ({item.get('reason')})" for item in lesson_items)
    else:
        lines.append('  - 教训库暂无匹配条目')
    lines.append('-' * 60)
    return '\n'.join(lines)


def _ur_fit(text: str, budget: int) -> str:
    """把一段文本压到 budget 字符内，优先在换行处截断并留省略号。"""
    if budget <= 0:
        return ''
    if len(text) <= budget:
        return text
    suffix = '\n  …（已截断）'
    keep = max(0, budget - len(suffix))
    clipped = text[:keep]
    cut = clipped.rfind('\n')
    if cut > keep // 2:
        clipped = clipped[:cut]
    return clipped + suffix


def format_unified_report_telegram(
    report: dict[str, Any],
    max_chars: int = UNIFIED_REPORT_TELEGRAM_BUDGET,
) -> str:
    """Telegram 渲染器：整体不超 max_chars，且结论与风险永远优先保住。

    骨架顺序不变（结论→关键数据→分歧点→风险→证据链→教训匹配）。
    预算分配分两轮：先给结论/风险按硬保留额度切块，剩余额度再按骨架顺序
    填中间段落；超长时限截断中间段，绝不截断结论和风险。
    """
    limit = min(int(max_chars or UNIFIED_REPORT_TELEGRAM_BUDGET), UNIFIED_REPORT_TELEGRAM_LIMIT)
    verdict = _ur_section(report, 'verdict')
    risk = _ur_section(report, 'risk')
    key_data = _ur_section(report, 'key_data')
    divergence = _ur_section(report, 'divergence')
    evidence = _ur_section(report, 'evidence')
    lessons = _ur_section(report, 'lessons')

    head = (
        f"🧭【统一研判】{report.get('title')}\n"
        f"{report.get('league')}｜生成 {report.get('generated_at')}"
    )
    verdict_block = f"🎯【结论】\n{verdict.get('verdict')}"
    risk_lines = ['⚠️【风险与陷阱】']
    for item in risk.get('items') or []:
        risk_lines.append(
            f"· [{item.get('level') or '低'}] {item.get('title')}\n"
            f"  触发: {item.get('trigger')}\n"
            f"  应对: {item.get('detail')}"
        )
    risk_block = '\n'.join(risk_lines)

    key_block_lines = ['📊【关键数据】']
    for metric in key_data.get('metrics') or []:
        key_block_lines.append(f"· {metric.get('label')}: {metric.get('value')}")
    key_block = '\n'.join(key_block_lines)

    div_lines = ['⚖️【分歧点】']
    div_items = divergence.get('items') or []
    if div_items:
        for item in div_items:
            div_lines.append(
                f"· {item.get('topic')}: 模型 {item.get('model')} vs 市场 {item.get('market')}"
                f"（{_ur_magnitude_text(item)}）"
            )
    else:
        div_lines.append('· 模型与市场暂无明显分歧')
    div_block = '\n'.join(div_lines)

    ev_lines = ['🧾【证据链】']
    for item in evidence.get('items') or []:
        ev_lines.append(f"· {item.get('signal')}: {item.get('value')}（{item.get('source')}）")
    ev_block = '\n'.join(ev_lines)

    les_lines = ['📖【教训匹配】']
    lesson_items = lessons.get('items') or []
    if lesson_items:
        for item in lesson_items:
            les_lines.append(f"· {item.get('rule')}（{item.get('reason')}）")
    else:
        les_lines.append('· 教训库暂无匹配条目')
    les_block = '\n'.join(les_lines)

    # 第一轮：结论与风险是硬保留段，先切出各自的额度。
    remaining = max(0, limit - len(head) - 2)
    verdict_budget = max(120, min(remaining // 4, 560))
    risk_budget = max(200, min(remaining - verdict_budget - 2, 1500))
    if verdict_budget + risk_budget + 2 > remaining:
        verdict_budget = max(90, remaining // 3)
        risk_budget = max(140, remaining - verdict_budget - 2)
    verdict_text = _ur_fit(verdict_block, verdict_budget)
    risk_text = _ur_fit(risk_block, risk_budget)

    # 第二轮：中间段按骨架顺序吃剩余额度，额度不足时整段跳过而不是砍一半。
    middle_budget = limit - len(head) - 2 - len(verdict_text) - len(risk_text) - 4
    middle: list[str] = []
    for block in (key_block, div_block, ev_block, les_block):
        if middle_budget <= 80:
            break
        piece = _ur_fit(block, min(len(block), middle_budget))
        middle.append(piece)
        middle_budget -= len(piece) + 2

    text = '\n\n'.join([head, verdict_text, *middle, risk_text])
    if len(text) > limit:
        # 兜底：只裁中间段，结论与风险保留原样。
        overflow = len(text) - limit
        middle_text = '\n'.join(middle)
        if middle_text:
            trimmed = middle_text[:max(0, len(middle_text) - overflow - 20)]
            parts = [head, verdict_text, trimmed, risk_text]
            text = '\n\n'.join(parts)
        while len(text) > limit and len(middle) > 1:
            middle.pop()
            parts = [head, verdict_text, *middle, risk_text]
            text = '\n\n'.join(parts)
    return text


def render_unified_report_streamlit(report: dict[str, Any]) -> None:
    """Streamlit 渲染器：指标卡 + 表格 + 风险横幅，与 CLI/TG 同一份骨架。"""
    if not isinstance(report, dict):
        st.info('暂无统一研判报告可渲染')
        return
    verdict = _ur_section(report, 'verdict')
    confidence = str(verdict.get('confidence') or '低')
    st.markdown(f"#### 🎯 结论 · {confidence}置信度（{_ur_float(verdict.get('confidence_score')):.1f}%）")
    st.success(str(verdict.get('verdict') or '尚未形成结论'))

    key_data = _ur_section(report, 'key_data')
    metrics = [m for m in (key_data.get('metrics') or []) if isinstance(m, dict)]
    if metrics:
        st.markdown('#### 📊 关键数据')
        for start in range(0, len(metrics), 3):
            row = metrics[start:start + 3]
            columns = st.columns(len(row))
            for column, metric in zip(columns, row):
                column.metric(str(metric.get('label') or '-'), str(metric.get('value') or '-'),
                              help=str(metric.get('hint') or ''))

    divergence = _ur_section(report, 'divergence')
    st.markdown('#### ⚖️ 分歧点')
    div_items = [i for i in (divergence.get('items') or []) if isinstance(i, dict)]
    if div_items:
        st.dataframe(
            pd.DataFrame([
                {
                    '主题': item.get('topic'),
                    '模型': item.get('model'),
                    '市场': item.get('market'),
                    '差距(pp)': _ur_float(item.get('magnitude_pp')),
                    '说明': item.get('note'),
                }
                for item in div_items
            ]),
            hide_index=True,
            width='stretch',
        )
    else:
        st.caption('模型与市场暂无明显分歧')

    st.markdown('#### ⚠️ 风险与陷阱')
    for item in _ur_section(report, 'risk').get('items') or []:
        level = str(item.get('level') or '低')
        line = f"**{item.get('title')}** — 触发：{item.get('trigger')}\n\n应对：{item.get('detail')}"
        if level == '高':
            st.error(line)
        elif level == '中':
            st.warning(line)
        else:
            st.info(line)

    st.markdown('#### 🧾 证据链')
    st.dataframe(
        pd.DataFrame([
            {
                '信号': item.get('signal'),
                '值': item.get('value'),
                '来源': item.get('source'),
                '时间戳': item.get('timestamp') or '—',
            }
            for item in _ur_section(report, 'evidence').get('items') or []
            if isinstance(item, dict)
        ]),
        hide_index=True,
        width='stretch',
    )

    st.markdown('#### 📖 教训匹配')
    lesson_items = [i for i in (_ur_section(report, 'lessons').get('items') or []) if isinstance(i, dict)]
    if lesson_items:
        for item in lesson_items:
            st.markdown(f"- {item.get('rule')}  \n  <span style='color:#6B7280'>{item.get('reason')}</span>",
                        unsafe_allow_html=True)
    else:
        st.caption('教训库暂无匹配条目')


class AntiConsensusDetector:
    """反共识陷阱检测 - 当系统高度一致时搜索被忽略的反向信号。
    核心逻辑: 庄家可以同时操控多个信号源（赔率/盘口/资金流），
    使得所有模块得出相同结论。此时需要寻找"不可伪造"的硬信号:
    1. 近期交锋记录（历史数据不可篡改）
    2. 球队真实实力差距（联赛排名/近期战绩不可伪造）
    3. 伤停/红牌等硬事实
    """
    CONSENSUS_THRESHOLD = 0.80

    @classmethod
    def detect(cls, convergence_score, voted_direction, match_context=None):
        """检测是否存在反共识陷阱。
        Args:
            convergence_score: float, 收敛度 0-1
            voted_direction: str, 投票方向 ('home'/'draw'/'away')
            match_context: dict, 比赛上下文 (h2h_text, injury_text, feature_vector, h2h_data等)
        Returns:
            (is_trap: bool, counter_direction: str, evidence: str)
        """
        if convergence_score < cls.CONSENSUS_THRESHOLD:
            return False, '', '收敛度未达阈值，无需反共识检测'
        match_context = match_context or {}
        counter_signals = []
        counter_direction = ''
        opposite_map = {'home': 'away', 'away': 'home', 'draw': ''}

        # 历史交锋已清除，不参与反共识判定。
        h2h_data = []
        h2h_text = ''
        if h2h_data and isinstance(h2h_data, list):
            h2h_home_wins = 0
            h2h_away_wins = 0
            h2h_draws = 0
            for row in h2h_data[-6:]:  # 最近6场交锋
                if not isinstance(row, dict):
                    continue
                score_text = str(row.get('score', '')).replace(':', '-').strip()
                m = re.search(r'(\d+)\s*[-]\s*(\d+)', score_text)
                if not m:
                    continue
                gh, ga = int(m.group(1)), int(m.group(2))
                if gh > ga:
                    h2h_home_wins += 1
                elif gh == ga:
                    h2h_draws += 1
                else:
                    h2h_away_wins += 1
            total_h2h = h2h_home_wins + h2h_away_wins + h2h_draws
            if total_h2h >= 3:
                # 判断交锋历史是否与共识方向矛盾
                if voted_direction == 'home' and h2h_away_wins > h2h_home_wins and h2h_away_wins >= 3:
                    counter_signals.append(f"交锋记录反向: 客队{h2h_away_wins}胜vs主队{h2h_home_wins}胜(近{total_h2h}场)")
                    counter_direction = 'away'
                elif voted_direction == 'away' and h2h_home_wins > h2h_away_wins and h2h_home_wins >= 3:
                    counter_signals.append(f"交锋记录反向: 主队{h2h_home_wins}胜vs客队{h2h_away_wins}胜(近{total_h2h}场)")
                    counter_direction = 'home'
                elif voted_direction in ('home', 'away') and h2h_draws >= total_h2h * 0.5:
                    counter_signals.append(f"交锋记录高平率: {h2h_draws}平(近{total_h2h}场)，共识方向{voted_direction}存疑")
                    counter_direction = 'draw'
        elif h2h_text:
            # 降级: 从文本中提取信号
            if voted_direction == 'home' and ('客胜' in h2h_text or '客队占优' in h2h_text):
                counter_signals.append("交锋文本暗示客队历史占优")
                counter_direction = 'away'
            elif voted_direction == 'away' and ('主胜' in h2h_text or '主队占优' in h2h_text):
                counter_signals.append("交锋文本暗示主队历史占优")
                counter_direction = 'home'

        # ═══ 硬信号2: 球队真实实力差距（近期战绩/进攻防守差值） ═══
        fv = match_context.get('feature_vector') or {}
        form_attack_diff = fv.get('form_attack_diff')  # 正=主队进攻强
        form_defense_diff = fv.get('form_defense_diff')  # 正=主队防守强
        # 如果近期战绩显示实力差距与共识方向矛盾
        if form_attack_diff is not None and form_defense_diff is not None:
            strength_score = (form_attack_diff + form_defense_diff) / 2
            if voted_direction == 'home' and strength_score < -0.4:
                counter_signals.append(f"实力差距反向: 客队近期攻防优势明显(差值{strength_score:.2f})")
                if not counter_direction:
                    counter_direction = 'away'
            elif voted_direction == 'away' and strength_score > 0.4:
                counter_signals.append(f"实力差距反向: 主队近期攻防优势明显(差值{strength_score:.2f})")
                if not counter_direction:
                    counter_direction = 'home'

        # ═══ 硬信号3: 关键伤停/红牌（不可伪造的硬事实） ═══
        injury_text = match_context.get('injury_text', '') or ''
        injury_home_count = match_context.get('injury_home_count', 0)
        injury_away_count = match_context.get('injury_away_count', 0)
        if injury_text:
            # 主队大面积伤停但共识看主胜 → 反共识信号
            if voted_direction == 'home' and injury_home_count >= 3 and injury_away_count <= 1:
                counter_signals.append(f"主队伤停严重({injury_home_count}人)但共识看主胜")
                if not counter_direction:
                    counter_direction = opposite_map.get(voted_direction, '')
            elif voted_direction == 'away' and injury_away_count >= 3 and injury_home_count <= 1:
                counter_signals.append(f"客队伤停严重({injury_away_count}人)但共识看客胜")
                if not counter_direction:
                    counter_direction = opposite_map.get(voted_direction, '')

        # ═══ 综合判定 ═══
        if counter_signals:
            evidence = " | ".join(counter_signals)
            return True, counter_direction, evidence
        return False, '', '未发现反共识硬信号'


def check_convergence_trap(convergence_score, manipulation_modules, voted_direction='', match_context=None):
    """统一收敛仲裁一致性陷阱检测（升级版）。
    兼容旧调用签名，同时支持新的 AntiConsensusDetector 三维度检测。
    Returns: (is_trap: bool, trap_msg: str)
    """
    # 第一层: 原始一致性陷阱检测（高收敛+无庄家操控）
    if convergence_score >= CONVERGENCE_SUSPICION_THRESHOLD and not manipulation_modules:
        base_warning = "⚠️ 一致性陷阱: 所有模块高度一致但未检测到庄家操控，需警惕统一诱导"
    else:
        base_warning = ""
    # 第二层: 反共识硬信号检测（升级）
    is_anti, counter_dir, evidence = AntiConsensusDetector.detect(
        convergence_score, voted_direction, match_context
    )
    if is_anti:
        anti_msg = f"⚠️ 反共识陷阱: 硬信号与共识方向({voted_direction})矛盾 → 反向={counter_dir} | 证据: {evidence}"
        if base_warning:
            return True, f"{base_warning}\n{anti_msg}"
        return True, anti_msg
    if base_warning:
        return True, base_warning
    return False, ""


# =====================================================================
# 【架构升级④·泊松厚尾修正】ZIP零膨胀 + 对角线膨胀（Diagonal Inflation）
# 真实足球比赛中进球具有传染性（负二项/厚尾特征），且 0:0 出现的
# 概率往往显著高于标准泊松的理论预测。本模块在 λ 冻结前对基础泊松
# 模型做解析级修正（发生在 calc_poisson_prob 内核，先于任何下游消费）：
#   1. ZIP 零膨胀：以结构零概率 π₀ 直接抬升 P(0-0)，
#      π₀ 随总进球期望 λ_total 递减（低期望战术僵局盘 π₀ 更大）；
#   2. 对角线膨胀：对 0-0 / 1-1 施加对角膨胀系数 κ(k)，
#      修正泊松独立性假设对'互交白卷/互咬平局'的系统性低估；
#   3. 修正后全矩阵重新归一化，保证概率测度完整（∑P=1）。
# 该修正发生在 Dixon-Coles ρ 协方差修正之后、归一化之前，属于
# 第二层（概率基座层）内核修正，不改变 λ 冻结契约（FROZEN λ 不被篡改，
# 仅修正由 λ 生成的比分分布形态）。
# =====================================================================
ZIP_DIAGONAL_INFLATION_ENABLED = False  # 0-0/1-1 不再单独抬权
ZIP_PI0_BASE = 0.045                    # 结构零基准概率（λ_total≈2.5 时）
ZIP_PI0_LAMBDA_REF = 2.5                # π₀ 衰减参考总进球期望
DIAG_INFLATION_00 = 1.10                # 0-0 对角膨胀系数 κ(0)
DIAG_INFLATION_11 = 1.06                # 1-1 对角膨胀系数 κ(1)


def _zip_structural_zero_pi(lam_total):
    """【架构升级④】计算 ZIP 结构零概率 π₀。
    π₀ = ZIP_PI0_BASE × exp(-(λ_total - λ_ref) × 0.55)，截断于 [0, 0.12]。
    λ_total 越低（防守僵局盘），结构零越大；强攻对轰盘 π₀ 趋近 0。"""
    try:
        pi0 = ZIP_PI0_BASE * math.exp(-(float(lam_total) - ZIP_PI0_LAMBDA_REF) * 0.55)
        return max(0.0, min(0.12, pi0))
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return 0.0


def calc_poisson_prob(lam_h, lam_a, max_goals=8, rho=-0.05, matrix_context=None,
                      zip_inflation=None):
    """
    【λ冻结架构·厚尾修正版】Dixon-Coles 双变量泊松比分概率矩阵
    + ZIP零膨胀 + 对角线膨胀（架构升级④）。
    概率内核为标准泊松 PMF + Dixon-Coles ρ 低比分协方差修正，
    再叠加 ZIP/对角膨胀专门修正 0:0 与 1:1 的理论概率
    （进球传染性 → 厚尾；0:0 真实频率 > 泊松理论值）。
    不再接受任何场态偏置乘数（low_score_bias/aggressive_bias/draw_boost 等
    已全部废弃并转为 GBDTEnsembleClassifier 的输入特征）。
    matrix_context 参数仅为向后兼容保留，其内容不参与概率计算。
    zip_inflation: None=跟随全局开关；True/False 强制开/关厚尾修正。

    λ 未形成（None/非数/非正）时返回 {} —— 明确未形成，绝不补默认 λ。
    """
    try:
        lam_h = float(lam_h)
        lam_a = float(lam_a)
    except (TypeError, ValueError):
        return {}
    if not (math.isfinite(lam_h) and math.isfinite(lam_a)) or lam_h <= 0 or lam_a <= 0:
        return {}
    lam_h = max(0.05, lam_h)
    lam_a = max(0.05, lam_a)

    # ── numpy矢量化路径：Dixon-Coles泊松矩阵 ──
    if NUMPY_VEC_AVAILABLE and _POISSON_VEC_FACT_TABLE is not None and max_goals <= _POISSON_VEC_FACT_MAX:
        fact = _POISSON_VEC_FACT_TABLE[:max_goals]
        goals = np.arange(max_goals, dtype=np.float64)
        p_home = np.exp(-lam_h) * np.power(lam_h, goals) / fact
        p_away = np.exp(-lam_a) * np.power(lam_a, goals) / fact
        prob_matrix = np.outer(p_home, p_away)

        # Dixon-Coles低比分协方差修正
        prob_matrix[0, 0] *= (1 - lam_h * lam_a * rho)
        prob_matrix[0, 1] *= (1 + lam_h * rho)
        prob_matrix[1, 0] *= (1 + lam_a * rho)
        prob_matrix[1, 1] *= (1 - rho)

        labels = _POISSON_VEC_LABELS.get(max_goals) if _POISSON_VEC_LABELS is not None else None
        if labels is None:
            labels = [[f"{h}-{a}" for a in range(max_goals)] for h in range(max_goals)]
        score_probs = {}
        for h in range(max_goals):
            for a in range(max_goals):
                p = prob_matrix[h, a]
                if p > 0.0001:
                    score_probs[labels[h][a]] = max(float(p), 0.0)
    else:
        # ── 降级路径：纯Python循环 ──
        score_probs = {}
        for h in range(max_goals):
            for a in range(max_goals):
                prob = (
                    math.exp(-lam_h) * (lam_h ** h) / math.factorial(h)
                    * math.exp(-lam_a) * (lam_a ** a) / math.factorial(a)
                )
                # Dixon-Coles 低比分协方差修正
                if h == 0 and a == 0:
                    prob *= (1 - lam_h * lam_a * rho)
                elif h == 0 and a == 1:
                    prob *= (1 + lam_h * rho)
                elif h == 1 and a == 0:
                    prob *= (1 + lam_a * rho)
                elif h == 1 and a == 1:
                    prob *= (1 - rho)
                if prob > 0.0001:
                    score_probs[f"{h}-{a}"] = max(prob, 0.0)

    # 0-0 / 1-1 不再单独抬权，也不把其余比分按结构零改写。
    _zip_on = False

    if score_probs:
        total = sum(score_probs.values())
        if total > 0:
            score_probs = {k: v / total for k, v in score_probs.items()}
    return score_probs
# ============================================================================
# 【31池完整比分理论vs市场概率对比图谱】generate_31pool_theory_vs_market_chart
# 覆盖竞彩足球比分玩法全部31个投注选项：
#   主胜13个（12种具体比分 + 胜其它）
#   平局5个（4种具体比分 + 平其它）
#   客胜13个（12种具体比分 + 负其它）
# 理论概率：MLE泊松模型 λ_home / λ_away 计算（Dixon-Coles修正泊松矩阵）；
#   "胜其它/平其它/负其它" = 该方向全部比分概率之和 - 已列出具体比分概率之和。
# 市场概率：竞彩波胆赔率反推（1/赔率，去除水分后归一化）。
# 偏差 = 理论概率 - 市场概率：正偏差=市场低估（可能有价值），负偏差=市场高估。
# ============================================================================
def chart31_pool_verdict(text: Any) -> dict[str, Any]:
    """判断31池图谱到底是「生成对比行」还是「只发了降级说明」。

    判据用生成函数自己的输出结构，不看日志措辞：
      * 降级文本只有「标题 + 一行 ⚠️」
      * 正常文本一定有表头 `排名 | 比分 | …` 和 31 行数据
    返回 {'status': 'degraded'|'theory_only'|'full', 'rows': int, 'note': str}。
    """
    lines = [ln for ln in str(text or '').splitlines() if ln.strip()]
    if not lines:
        return {'status': 'empty', 'rows': 0, 'note': '无输出'}
    data_rows = sum(1 for ln in lines if re.match(r'^\d{2}\s*\|', ln))
    degraded = data_rows == 0 and any('⚠️' in ln for ln in lines[1:])
    market_zero = '市场概率均置0' in str(text or '')
    if degraded:
        note = lines[-1].strip() if lines else ''
        return {'status': 'degraded', 'rows': 0, 'note': note}
    if market_zero:
        return {'status': 'theory_only', 'rows': data_rows,
                'note': '波胆市均不可用，市场概率全为0'}
    return {'status': 'full', 'rows': data_rows, 'note': ''}


def generate_31pool_theory_vs_market_chart(match_data):
    """生成31池完整比分理论vs市场概率对比图谱的TG报告文本段。

    Args:
        match_data: dict，比赛分析数据。支持的字段（按优先级读取）：
            - 'lam_h' / 'lambda_home': MLE泊松模型主队λ
            - 'lam_a' / 'lambda_away': MLE泊松模型客队λ
            - 'odds_correct_score': dict，波胆赔率 {'1-0': 7.5, ...}
              （key支持'1-0'或'1:0'格式，'胜其它/平其它/负其它'为汇总选项赔率）
            - 'prob_dict': dict，可选，已计算好的泊松比分概率矩阵（小数），
              若提供则优先使用（保持与主链路概率基座一致），否则由λ重算。

    Returns:
        str: 全中文TG报告文本段；数据不足时返回降级提示文本。
    """
    try:
        if not isinstance(match_data, dict):
            return "📊 31池理论vs市场概率对比图谱\n  ⚠️ 输入数据无效，已跳过31池图谱。"
        # ── 1. 提取λ并构建理论概率矩阵（优先复用主链路prob_dict） ──
        lam_h = match_data.get('lam_h', match_data.get('lambda_home'))
        lam_a = match_data.get('lam_a', match_data.get('lambda_away'))
        prob_dict = match_data.get('prob_dict')
        if not (isinstance(prob_dict, dict) and prob_dict):
            if lam_h is None or lam_a is None:
                return "📊 31池理论vs市场概率对比图谱\n  ⚠️ 缺少λ参数与概率矩阵，已跳过31池图谱。"
            prob_dict = calc_poisson_prob(float(lam_h), float(lam_a), max_goals=10)
        if not prob_dict:
            return "📊 31池理论vs市场概率对比图谱\n  ⚠️ 泊松概率矩阵为空，已跳过31池图谱。"
        # 泊松矩阵按方向聚合总概率（含所有比分，用于"其它"选项= 方向总概率-已列出之和）
        _dir_total = {'home': 0.0, 'draw': 0.0, 'away': 0.0}
        for _sc, _p in prob_dict.items():
            _sc_s = str(_sc).replace(':', '-').strip()
            if '其它' in _sc_s or '-' not in _sc_s:
                continue
            try:
                _h, _a = parse_score(_sc_s)
            except (ValueError, IndexError):
                continue
            if _h is None or _a is None:
                continue
            _pv = max(0.0, float(_p or 0.0))
            if _h > _a:
                _dir_total['home'] += _pv
            elif _h == _a:
                _dir_total['draw'] += _pv
            else:
                _dir_total['away'] += _pv
        # 12/4/12种具体比分的理论概率
        theory_probs = {}
        _listed_dir_sum = {'home': 0.0, 'draw': 0.0, 'away': 0.0}
        for _sc in JCZQ_HOME_WIN_SCORES:
            _pv = max(0.0, float(prob_dict.get(_sc, 0.0) or 0.0))
            theory_probs[_sc] = _pv
            _listed_dir_sum['home'] += _pv
        for _sc in JCZQ_DRAW_SCORES:
            _pv = max(0.0, float(prob_dict.get(_sc, 0.0) or 0.0))
            theory_probs[_sc] = _pv
            _listed_dir_sum['draw'] += _pv
        for _sc in JCZQ_AWAY_WIN_SCORES:
            _pv = max(0.0, float(prob_dict.get(_sc, 0.0) or 0.0))
            theory_probs[_sc] = _pv
            _listed_dir_sum['away'] += _pv
        # "其它"汇总选项 = 1(方向总概率) - 已列出具体比分之和（下限0）
        theory_probs['胜其它'] = max(0.0, _dir_total['home'] - _listed_dir_sum['home'])
        theory_probs['平其它'] = max(0.0, _dir_total['draw'] - _listed_dir_sum['draw'])
        theory_probs['负其它'] = max(0.0, _dir_total['away'] - _listed_dir_sum['away'])
        # 31池内归一化（泊松矩阵截断误差校正，保证31项合计=100%）
        _theory_total = sum(theory_probs.values())
        if _theory_total > 0:
            theory_probs = {k: v / _theory_total for k, v in theory_probs.items()}
        # ── 2. 市场概率：竞彩波胆赔率反推（去水归一化） ──
        odds_cs_raw = match_data.get('odds_correct_score') or {}
        market_probs = {}
        _market_available = False
        if isinstance(odds_cs_raw, dict) and odds_cs_raw:
            # key归一化：'1:0'→'1-0'，汇总选项名原样保留
            _odds_norm = {}
            for _k, _v in odds_cs_raw.items():
                _nk = str(_k).replace(':', '-').strip()
                try:
                    _fv = float(_v)
                except (TypeError, ValueError):
                    continue
                if _fv > 1.0:
                    _odds_norm[_nk] = _fv
            # 仅统计31池内选项的隐含概率，去除水分后归一化
            _inv_sum = 0.0
            _inv_map = {}
            for _opt in JCZQ_ALL_OPTIONS:
                _ov = _odds_norm.get(_opt)
                if _ov and _ov > 1.0:
                    _inv = 1.0 / _ov
                    _inv_map[_opt] = _inv
                    _inv_sum += _inv
            # 【修复】当波胆赔率不含"胜其它/平其它/负其它"时（API-Football通常不提供），
            # 用各方向已有具体比分的隐含概率之和推算汇总选项的市场概率：
            # "X其它" 市场概率 = 该方向理论占比中"其它"的比例 × 该方向具体比分市场概率之和
            # 即用理论概率中"其它"占该方向的比例来分配市场概率的剩余部分
            if _inv_sum > 0 and len(_inv_map) >= 5:
                # 检查是否缺少汇总选项
                _other_keys = ['胜其它', '平其它', '负其它']
                _has_others = any(_ok in _inv_map for _ok in _other_keys)
                if not _has_others and len(_inv_map) >= 15:
                    # 按方向聚合已有具体比分的隐含概率
                    _dir_inv = {'home': 0.0, 'draw': 0.0, 'away': 0.0}
                    for _sc_key, _sc_inv in _inv_map.items():
                        if _sc_key in JCZQ_HOME_WIN_SCORES:
                            _dir_inv['home'] += _sc_inv
                        elif _sc_key in JCZQ_DRAW_SCORES:
                            _dir_inv['draw'] += _sc_inv
                        elif _sc_key in JCZQ_AWAY_WIN_SCORES:
                            _dir_inv['away'] += _sc_inv
                    # 用理论概率中"其它"占该方向的比例来推算汇总选项的市场隐含概率
                    # 公式：other_inv = dir_inv × (theory_other / theory_listed)
                    _theory_other_home = theory_probs.get('胜其它', 0.0)
                    _theory_listed_home = _listed_dir_sum.get('home', 0.0)
                    _theory_other_draw = theory_probs.get('平其它', 0.0)
                    _theory_listed_draw = _listed_dir_sum.get('draw', 0.0)
                    _theory_other_away = theory_probs.get('负其它', 0.0)
                    _theory_listed_away = _listed_dir_sum.get('away', 0.0)
                    if _theory_listed_home > 0.001:
                        _other_home_inv = _dir_inv['home'] * (_theory_other_home / _theory_listed_home)
                        _inv_map['胜其它'] = _other_home_inv
                        _inv_sum += _other_home_inv
                    if _theory_listed_draw > 0.001:
                        _other_draw_inv = _dir_inv['draw'] * (_theory_other_draw / _theory_listed_draw)
                        _inv_map['平其它'] = _other_draw_inv
                        _inv_sum += _other_draw_inv
                    if _theory_listed_away > 0.001:
                        _other_away_inv = _dir_inv['away'] * (_theory_other_away / _theory_listed_away)
                        _inv_map['负其它'] = _other_away_inv
                        _inv_sum += _other_away_inv
            if _inv_sum > 0 and len(_inv_map) >= 5:
                _market_available = True
                for _opt in JCZQ_ALL_OPTIONS:
                    market_probs[_opt] = _inv_map.get(_opt, 0.0) / _inv_sum
        # ── 2b. 回退路径：当波胆赔率不可用时，使用合成市场概率(synth_market) ──
        if not _market_available:
            _synth_mkt = match_data.get('synth_market') or {}
            if isinstance(_synth_mkt, dict) and _synth_mkt:
                # synth_market 的 key 格式为 '1-0' 等，值为小数概率（已归一化）
                # 将其映射到31池选项
                def _score_dir_matches(score_key, direction):
                    _h, _a = parse_score(score_key)
                    if _h is None or _a is None:
                        return False
                    if direction == 'home':
                        return _h > _a
                    if direction == 'draw':
                        return _h == _a
                    return _h < _a

                _synth_sum = 0.0
                _synth_mapped = {}
                for _opt in JCZQ_ALL_OPTIONS:
                    if '其它' in _opt:
                        # 汇总选项：该方向所有比分概率之和 - 已列出具体比分之和
                        if _opt == '胜其它':
                            _dir_all = sum(v for k, v in _synth_mkt.items() if '-' in k and _score_dir_matches(k, 'home'))
                            _dir_listed = sum(_synth_mkt.get(sc, 0.0) for sc in JCZQ_HOME_WIN_SCORES)
                            _synth_mapped[_opt] = max(0.0, _dir_all - _dir_listed)
                        elif _opt == '平其它':
                            _dir_all = sum(v for k, v in _synth_mkt.items() if '-' in k and _score_dir_matches(k, 'draw'))
                            _dir_listed = sum(_synth_mkt.get(sc, 0.0) for sc in JCZQ_DRAW_SCORES)
                            _synth_mapped[_opt] = max(0.0, _dir_all - _dir_listed)
                        elif _opt == '负其它':
                            _dir_all = sum(v for k, v in _synth_mkt.items() if '-' in k and _score_dir_matches(k, 'away'))
                            _dir_listed = sum(_synth_mkt.get(sc, 0.0) for sc in JCZQ_AWAY_WIN_SCORES)
                            _synth_mapped[_opt] = max(0.0, _dir_all - _dir_listed)
                    else:
                        _synth_mapped[_opt] = _synth_mkt.get(_opt, 0.0)
                    _synth_sum += _synth_mapped.get(_opt, 0.0)
                # 归一化
                if _synth_sum > 0:
                    market_probs = {k: v / _synth_sum for k, v in _synth_mapped.items()}
                    _market_available = True
                else:
                    market_probs = {_opt: 0.0 for _opt in JCZQ_ALL_OPTIONS}
            else:
                market_probs = {_opt: 0.0 for _opt in JCZQ_ALL_OPTIONS}
        # ── 3. 组装31项并按理论概率降序排列 ──
        _rows = []
        for _opt in JCZQ_ALL_OPTIONS:
            if _opt in JCZQ_HOME_WIN_SCORES or _opt == '胜其它':
                _direction = '主胜'
            elif _opt in JCZQ_DRAW_SCORES or _opt == '平其它':
                _direction = '平局'
            else:
                _direction = '客胜'
            _tp = theory_probs.get(_opt, 0.0) * 100.0
            _mp = market_probs.get(_opt, 0.0) * 100.0
            _dev = _tp - _mp  # 偏差=理论-市场：正=市场低估(可能有价值)，负=市场高估
            _rows.append({
                'option': _opt, 'direction': _direction,
                'theory': _tp, 'market': _mp, 'deviation': _dev,
            })
        _rows.sort(key=lambda x: x['theory'], reverse=True)
        # ── 4. 生成全中文TG报告文本段 ──
        lines = []
        lines.append("📊 31池理论vs市场概率对比图谱")
        _msrc = str(match_data.get('market_source_note') or '').strip()
        if _msrc:
            # 市场口径可能是「市均+竞彩31比分」的混合来源，必须写在抬头，
            # 免得有人把竞彩比分赔率当成市均读。
            lines.append(f"  市场来源: {_msrc}")
        lines.append("━━━━━━━━━━━━━━━━━━━━━━")
        lines.append("排名 | 比分 | 方向 | 理论概率 | 市场概率 | 偏差")
        for _idx, _row in enumerate(_rows, 1):
            _opt_disp = _row['option'].replace('-', ':') if '其它' not in _row['option'] else _row['option']
            lines.append(
                f"{_idx:02d} | {_opt_disp:<4s} | {_row['direction']} | "
                f"{_row['theory']:.1f}% | {_row['market']:.1f}% | {_row['deviation']:+.1f}%"
            )
        lines.append("━━━━━━━━━━━━━━━━━━━━━━")
        if not _market_available:
            lines.append("⚠️ 波胆赔率不可用，市场概率均置0，偏差仅供参考。")
        else:
            # 摘要：市场最低估(正偏差最大)与最高估(负偏差最小)选项
            _pos_sorted = sorted(_rows, key=lambda x: x['deviation'], reverse=True)
            _top_under = [r for r in _pos_sorted[:3] if r['deviation'] > 0.3]
            _top_over = [r for r in sorted(_rows, key=lambda x: x['deviation'])[:3] if r['deviation'] < -0.3]
            if _top_under:
                lines.append(
                    "💎 市场低估(正偏差·可能有价值): "
                    + "、".join(f"{r['option'].replace('-', ':') if '其它' not in r['option'] else r['option']}({r['deviation']:+.1f}%)" for r in _top_under)
                )
            if _top_over:
                lines.append(
                    "🔥 市场高估(负偏差·热度虚高): "
                    + "、".join(f"{r['option'].replace('-', ':') if '其它' not in r['option'] else r['option']}({r['deviation']:+.1f}%)" for r in _top_over)
                )
            # 三方向合计对照
            _dir_sum = {}
            for _r in _rows:
                _d = _dir_sum.setdefault(_r['direction'], {'t': 0.0, 'm': 0.0})
                _d['t'] += _r['theory']
                _d['m'] += _r['market']
            _dir_line_parts = []
            for _dn in ('主胜', '平局', '客胜'):
                _dv = _dir_sum.get(_dn, {'t': 0.0, 'm': 0.0})
                _dir_line_parts.append(f"{_dn} 理论{_dv['t']:.1f}%/市场{_dv['m']:.1f}%")
            lines.append("📐 方向合计: " + " | ".join(_dir_line_parts))
        return "\n".join(lines)
    except Exception as _chart31_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return f"📊 31池理论vs市场概率对比图谱\n  ⚠️ 生成异常(已降级): {_chart31_err}"
# ============================================================================
# 【新增】四大模块：底层数据结构 + 跨盘口管道 + 风险防御 + 矩阵重构
# ============================================================================

class ScoreNode:
    """【模块一·数据结构】每个比分实例化为独立对象。

    属性：
      - home_goals / away_goals: 主客队进球数
      - goal_diff: 主队净胜球（h - a）
      - total_goals: 总进球数
      - prob_theory: Dixon-Coles 理论概率
      - prob_market: 市场隐含概率（从波胆赔率反推）
      - ev: 期望价值（理论概率 × 赔率 - 1）
      - quadrant: 所属象限（home_win / draw / away_win）
      - tags: 标签列表（零封 / 大球 / 小球 / 赢盘 / 输盘 等）
    """
    def __init__(self, h, a, prob_theory, odds_dict=None, ou_line=None, asian_handicap=0.0):
        self.home_goals = int(h)
        self.away_goals = int(a)
        self.goal_diff = self.home_goals - self.away_goals
        self.total_goals = self.home_goals + self.away_goals
        self.prob_theory = float(prob_theory or 0.0)

        score_str = f"{self.home_goals}-{self.away_goals}"
        try:
            market_odds = float((odds_dict or {}).get(score_str, 0.0) or 0.0)
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            market_odds = 0.0
        self.market_odds = market_odds
        self.prob_market = (1.0 / market_odds) if market_odds > 1.0 else 0.0
        self.ev = (self.prob_theory * market_odds - 1.0) if market_odds > 1.0 else -1.0

        if self.home_goals > self.away_goals:
            self.quadrant = "home_win"
        elif self.home_goals == self.away_goals:
            self.quadrant = "draw"
        else:
            self.quadrant = "away_win"

        self.tags = []
        if self.home_goals == 0 or self.away_goals == 0:
            self.tags.append("零封")
        _line = None
        if ou_line is not None:
            try:
                _line = float(ou_line)
            except (TypeError, ValueError):
                _line = None
        if _line is not None:
            _settle = OverUnderEngine.settle_ou_bet(self.total_goals, _line)
            _mult = _settle.get('over_multiplier', 0.0)
            if _mult > 0:
                self.tags.append("大球")
            elif _mult < 0:
                self.tags.append("小球")
            else:
                self.tags.append("走盘")
        try:
            _ah = float(asian_handicap) if asian_handicap is not None else 0.0
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            _ah = 0.0
        adjusted = self.goal_diff + _ah
        if adjusted > 0:
            self.tags.append("赢盘")
        elif adjusted < 0:
            self.tags.append("输盘")
        else:
            self.tags.append("走盘")

    def to_dict(self):
        return {
            'score': f"{self.home_goals}-{self.away_goals}",
            'home_goals': self.home_goals,
            'away_goals': self.away_goals,
            'goal_diff': self.goal_diff,
            'total_goals': self.total_goals,
            'prob_theory': round(self.prob_theory, 6),
            'prob_market': round(self.prob_market, 6),
            'market_odds': round(self.market_odds, 4),
            'ev': round(self.ev, 6),
            'quadrant': self.quadrant,
            'tags': list(self.tags),
        }


class ScoreMatrix:
    """【模块一·矩阵容器】三个独立子空间承载 ScoreNode。

    home_win_matrix / draw_matrix / away_win_matrix 均为 DataFrame：
      - 行索引: goal_diff（主队净胜球）
      - 列索引: conceded（失球数，作为 Z 轴维度的代理）
    所有 ScoreNode 同时存入 self.nodes（按 "h-a" 字符串索引），便于跨象限检索。
    """
    def __init__(self, prob_dict, odds_dict=None, ou_line=None, asian_handicap=0.0):
        self.nodes = {}
        self.ou_line = ou_line
        self.asian_handicap = asian_handicap
        for score_str, prob in (prob_dict or {}).items():
            try:
                h_str, a_str = parse_score(score_str)
                if h_str is None:
                    continue
                node = ScoreNode(h_str, a_str, prob, odds_dict, ou_line, asian_handicap)
                self.nodes[score_str] = node
            except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                print(f"   ⚠️ [异常已捕获·continue降级 L6436] {_silent_err}")
                continue

        # 按象限拆分构建 DataFrame；行=goal_diff，列=conceded（失球）
        self.home_win_matrix = self._build_subspace("home_win")
        self.draw_matrix = self._build_subspace("draw")
        self.away_win_matrix = self._build_subspace("away_win")

    def _build_subspace(self, quadrant):
        records = {}
        for node in self.nodes.values():
            if node.quadrant != quadrant:
                continue
            row = node.goal_diff
            col = node.away_goals  # conceded 视角：以失球数作为 Z 轴坐标
            records.setdefault(row, {})[col] = node
        if not records:
            return pd.DataFrame()
        rows = sorted(records.keys())
        cols = sorted({c for inner in records.values() for c in inner})
        df = pd.DataFrame(index=rows, columns=cols, dtype=object)
        for r in rows:
            for c in cols:
                df.at[r, c] = records.get(r, {}).get(c)
        return df

    def get_node(self, h, a):
        return self.nodes.get(f"{int(h)}-{int(a)}")

    def get_all_nodes(self):
        return list(self.nodes.values())

    def get_nodes_by_quadrant(self, quadrant):
        return [n for n in self.nodes.values() if n.quadrant == quadrant]

    def get_nodes_by_diff(self, diff):
        return [n for n in self.nodes.values() if n.goal_diff == diff]

    def get_nodes_by_total(self, total):
        return [n for n in self.nodes.values() if n.total_goals == total]

    def summary(self):
        return {
            'total_nodes': len(self.nodes),
            'home_win_count': len(self.get_nodes_by_quadrant('home_win')),
            'draw_count': len(self.get_nodes_by_quadrant('draw')),
            'away_win_count': len(self.get_nodes_by_quadrant('away_win')),
        }
# ============================================================================
def build_kelly_odds_matrix(euro_odds_500=None, odds_1x2_dict=None, api_football_response=None):
    """将系统中的多家公司欧赔数据转成 KellyVarianceFilter 需要的 odds_matrix。

    数据源优先级（自高到低）：
      1. ``api_football_response``：api-football 的 /odds 原始 JSON（经白名单过滤）；
      2. ``euro_odds_500``：500 网百家欧赔（每条含 ``instant_home/instant_draw/instant_away``）；
      3. ``odds_1x2_dict``：聚合后的单家平均赔率（仅形成单条记录，作为最末兜底）。
    返回 list[dict]，每条形如 {'home', 'draw', 'away', 'company'}。
    """
    odds_matrix = []
    try:
        # —— 优先级 2：500 网百家欧赔 ——
        if not odds_matrix:
            for entry in euro_odds_500 or []:
                try:
                    home = entry.get('instant_home') or entry.get('home_now') or entry.get('home')
                    draw = entry.get('instant_draw') or entry.get('draw_now') or entry.get('draw')
                    away = entry.get('instant_away') or entry.get('away_now') or entry.get('away')
                    if home and draw and away and float(home) > 1.0 and float(draw) > 1.0 and float(away) > 1.0:
                        odds_matrix.append({
                            'home': float(home),
                            'draw': float(draw),
                            'away': float(away),
                            'company': str(entry.get('company') or entry.get('bookmaker') or 'unknown'),
                        })
                except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [异常已捕获·continue降级 L6620] {_silent_err}")
                    continue

        # —— 优先级 3：缺多源数据时，回退到单家平均赔率（仅做兜底，过滤器会因样本不足自动 no-op） ——
        if not odds_matrix and odds_1x2_dict:
            home = float(odds_1x2_dict.get('Home') or odds_1x2_dict.get('home') or 0)
            draw = float(odds_1x2_dict.get('Draw') or odds_1x2_dict.get('draw') or 0)
            away = float(odds_1x2_dict.get('Away') or odds_1x2_dict.get('away') or 0)
            if home > 1.0 and draw > 1.0 and away > 1.0:
                odds_matrix.append({'home': home, 'draw': draw, 'away': away, 'company': 'avg_1x2'})
    except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [异常已捕获·pass降级 L6630] {_silent_err}")
    return odds_matrix


# ============================================================================
# 【正反连算三维阵列】CrossMarketAnomalyDetector
# ----------------------------------------------------------------------------
# 核心思路：
#   庄家可以在欧赔（1x2）上通过升降水来骗人，但他们绝对不敢同时在亚盘（AH）
#   和大小球（O/U）上骗人——三盘口之间存在严格的数学换算关系（无套利定价）。
#   一旦庄家为了诱导散户而在某一端强行造势，三者的联动就会出现“裂缝”。
#
# 工作流：
#   1) parse_api_football_full_markets：一次性把 1x2 / AH / O/U 全部抽出，
#      仅采信白名单博彩公司，且必须三盘口齐全方记为有效样本；
#   2) CrossMarketAnomalyDetector：
#        a. 用亚盘水位换算主胜深度概率；
#        b. 与欧赔隐含主胜概率比对，偏差超阈值 → 触发“虚假示弱”警报；
#        c. 用大小球隐含 Over 概率反推总进球期望，与欧赔进球期望对比；
#        d. 三盘口联动给出 fissure_score（裂缝分），分数越高越可疑；
#   3) 输出 lambda 修正系数 / 高波动溢出组配额加成，供主流程调用。
# 多源数据缺失或解析失败时，所有 API 安全降级（available=False，返回空载荷），
# 绝不影响原有 KellyVarianceFilter / 异常检测主链路。
# ============================================================================


def build_synthetic_market_data_from_500(data_500):
    """[【备用数据阵列】当 API-Football 盘口数据崩溃时，用 500 网数据合成仿真 full_market_data。

    将 500 网的欧赔平均值、亚盘平均盘口、大小球平均盘口转换为
    parse_api_football_full_markets 兼容的 list[dict] 格式。

    返回:
        list[dict] — 单条合成样本（来源标记为 '500网合成'），或空 list。
    """
    if not data_500 or not isinstance(data_500, dict):
        return []

    try:
        # 欧赔 1x2
        euro_home = MathUtils.safe_float(data_500.get('euro_avg_home'), 0.0)
        euro_draw = MathUtils.safe_float(data_500.get('euro_avg_draw'), 0.0)
        euro_away = MathUtils.safe_float(data_500.get('euro_avg_away'), 0.0)
        ok_1x2 = euro_home > 1.0 and euro_draw > 1.0 and euro_away > 1.0

        # 亚盘 AH
        ah_line = MathUtils.safe_float(data_500.get('ah_avg_line'), None)
        ah_home_water = MathUtils.safe_float(data_500.get('ah_avg_home_water'), 0.0)
        ah_away_water = MathUtils.safe_float(data_500.get('ah_avg_away_water'), 0.0)
        ok_ah = ah_line is not None and ah_home_water > 0 and ah_away_water > 0

        # 大小球 OU
        _ou_avg_raw = data_500.get('ou_avg_line')
        ou_line_val = standardize_ou_line(_ou_avg_raw) if _ou_avg_raw is not None else None
        ou_over = MathUtils.safe_float(data_500.get('ou_avg_over'), 0.0)
        ou_under = MathUtils.safe_float(data_500.get('ou_avg_under'), 0.0)
        ok_ou = ou_line_val is not None and ou_over > 0 and ou_under > 0

        if not (ok_1x2 and ok_ah and ok_ou):
            _missing = []
            if not ok_1x2:
                _missing.append('欧赔')
            if not ok_ah:
                _missing.append('亚盘')
            if not ok_ou:
                _missing.append('大小球')
            print(f"      ⚠️ [500网备用阵列] 数据不完整，缺少: {','.join(_missing)}，无法合成")
            return []

        synthetic_entry = {
            'bookmaker': '500网合成',
            '1x2': {
                'home': euro_home,
                'draw': euro_draw,
                'away': euro_away,
            },
            'ah': {
                'line': standardize_ah_line(ah_line) or ah_line,
                'home': ah_home_water,
                'away': ah_away_water,
            },
            'ou': {
                'line': standardize_ou_line(ou_line_val),
                'over': ou_over,
                'under': ou_under,
            },
        }
        print(f"      🚀 [500网备用阵列] 合成成功! "
              f"1x2={euro_home}/{euro_draw}/{euro_away} | "
              f"AH={ah_line}({ah_home_water}/{ah_away_water}) | "
              f"OU={ou_line_val}(大{ou_over}/小{ou_under})")
        return [synthetic_entry]

    except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"      ❌ [500网备用阵列] 合成异常: {e}")
        return []


# ============================================================================
# 【LambdaCalibrator】λ逆向推导校准器
# ----------------------------------------------------------------------------
# 核心数学逻辑：
#   λ_home + λ_away ≈ O/U Line                （大小球线 = 总进球预期）
#   λ_home - λ_away ≈ -AH Line                 （亚盘让球 = 净胜球差，主让为负）
# 联立解得：
#   λ_home = (O/U Line - AH Line) / 2
#   λ_away = (O/U Line + AH Line) / 2
#
# 用市场资金（庄家防线）α=0.70 与历史模型（托底防线）α=0.30 做动量平滑，
# 让 31 个波胆矩阵在生成之前先被市场盘口校准过的真实泊松底层喂进来。
# 任何异常或数据缺失时，安全降级返回原始 (historical_lambda_h, historical_lambda_a)，
# 完全向后兼容，不影响 KellyVarianceFilter / CrossMarketAnomalyDetector / K-Means 主链路。
# ============================================================================


def betfair_null_imputation_smoothing(lam_h, lam_a, euro_odds=None, ou_line=None, asian_handicap=None):
    """不按对冲改写进球期望。"""
    return lam_h, lam_a, '不改写进球期望'


def _ou_line_lambda_floor(market_ou_line):
    """大小球 ≥ 3.0 时，λ 总量的硬下限。

    下限取泊松结算里大球概率首次不低于小球的最小总量，与衍生盘口同一口径：
    总球高于盘口计大球，低于盘口计小球，整数盘走水对半。
    盘口 3.00 的均衡点约 3.16（系数约 1.05）。扣水净期望 Line−0.25 只有 2.75，
    总量停在 2.85 时反推仍是小球约 57%、大球约 43%，所以不能用扣水线当下限。
    盘口缺失、低于 3.0 或高于 8.0 时不设下限。
    """
    import math
    try:
        line = float(market_ou_line)
    except (TypeError, ValueError):
        return None
    if line < 3.0 or line > 8.0:
        return None
    key = round(line * 4.0) / 4.0
    cache = getattr(_ou_line_lambda_floor, '_cache', None)
    if cache is None:
        cache = {}
        _ou_line_lambda_floor.__dict__['_cache'] = cache
    if key in cache:
        return cache[key]

    def _over_minus_under(lam):
        over = 0.0
        under = 0.0
        cum = 0.0
        prob = math.exp(-lam)
        for n in range(41):
            if n:
                prob *= lam / n
            cum += prob
            if n > key:
                over += prob
            elif n < key:
                under += prob
            else:
                over += prob * 0.5
                under += prob * 0.5
        over += max(0.0, 1.0 - cum)
        return over - under

    lo, hi = 0.5, key + 4.0
    for _ in range(48):
        mid = (lo + hi) / 2.0
        if _over_minus_under(mid) >= 0.0:
            hi = mid
        else:
            lo = mid
    cache[key] = hi
    return hi


def _lift_lambda_pair_to_floor(lam_h, lam_a, floor_total):
    """总量低于下限时按现有攻防比补足，不改主客比例。

    λ 未形成时原样返回 (lam_h, lam_a, False)：不补、不改。
    """
    if not lambda_ready(lam_h, lam_a):
        return lam_h, lam_a, False
    total = float(lam_h) + float(lam_a)
    if floor_total is None or total <= 1e-9 or total + 1e-9 >= float(floor_total):
        return float(lam_h), float(lam_a), False
    ratio_h = float(lam_h) / total
    ratio_a = float(lam_a) / total
    return float(floor_total) * ratio_h, float(floor_total) * ratio_a, True


def calibrate_lambda_with_market_line(lambda_home, lambda_away, market_ou_line):
    """盘口强制对齐。大小球 ≥ 3.0 时，λ 总量不得低于该盘的泊松均衡下限。

    低于下限才按主客攻击力比例拉伸。缺盘口、盘口低于 3.0、或总量已不低于下限时不改 λ。
    不写 first_score，不改方向锁。
    """
    try:
        lam_h = float(lambda_home)
        lam_a = float(lambda_away)
    except (TypeError, ValueError):
        return lambda_home, lambda_away
    floor_total = _ou_line_lambda_floor(market_ou_line)
    if floor_total is None:
        return lam_h, lam_a
    lifted_h, lifted_a, _changed = _lift_lambda_pair_to_floor(lam_h, lam_a, floor_total)
    return lifted_h, lifted_a


def apply_lambda_offset_compensation(lambda_val, offset, lo=0.1, hi=6.0):
    """偏移补偿：必须作用于融合后的 final λ，禁止只补偿 history。

    final = clamp(fused_lambda + offset)
    """
    try:
        return max(float(lo), min(float(hi), float(lambda_val) + float(offset or 0.0)))
    except (TypeError, ValueError):
        return lambda_val


def calibrate_lambdas_by_market(historical_lambda_h, historical_lambda_a, full_market_data,
                                ref_ah_line=None, ref_ou_line=None,
                                rtm_direction=None, betfair_missing=False,
                                offset_h=0.0, offset_a=0.0,
                                auto_offset=True, offset_threshold=0.4,
                                offset_frac=0.3, offset_cap=0.35):
    """用亚盘/大小球盘口逆向求解并平滑修正底层进球期望 (Lambda)。

    正确顺序（写死）:
      1) market_λ 由 AH/OU 解出
      2) fused = market×α + history×(1-α)
      3) final = apply_compensation(fused, offset)   ← 补偿只作用于融合后的 λ

    参数:
        historical_lambda_h, historical_lambda_a : float
            历史/模型先验 λ（托底）。
        full_market_data : list[dict]
            多家盘口样本（可空）；空时仅依赖 ref_ah_line / ref_ou_line（澳客真值）。
        ref_ah_line, ref_ou_line : float | None
            外层主链路权威亚盘/大小球（澳客）。缺样本或浅盘污染时以真值为锚。
        offset_h, offset_a : float
            显式偏移；若 auto_offset=True 且未显式传入非零值，则按
            market−history 系统性偏移自动生成（超阈才补偿）。
        auto_offset : bool
            是否根据 implied vs history 自动生成偏移（默认开）。
        offset_threshold / offset_frac / offset_cap :
            自动偏移：|Δ|>threshold 时 offset=clip(Δ×frac, ±cap)。

    返回:
        (final_lambda_h, final_lambda_a) : tuple[float, float]
    """
    import math

    # —— 真值盘口安全转换 ——
    def _to_float_or_none(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            return float(v)
        try:
            return float(v)
        except (ValueError, TypeError):
            return None

    ref_ah = _to_float_or_none(ref_ah_line)
    ref_ou = _to_float_or_none(ref_ou_line)

    # —— 多源数据缺失 → 若有外层真值盘口仍可校准，否则优雅降级 ——
    if not full_market_data and (ref_ah is None or ref_ou is None):
        return historical_lambda_h, historical_lambda_a

    # —— 健壮提取 AH/OU 数值，兑容字符串/中文盘口格式 ——
    def _safe_float_line(val):
        """将 ah/ou line 安全转为 float，支持中文盘口格式"""
        if val is None:
            return None
        if isinstance(val, (int, float)):
            return float(val)
        # 尝试直接 float 转换
        return float(val)
        # 尝试中文盘口解析
        try:
            parsed = _500_clean_line(str(val))
            if parsed is not None:
                return float(parsed)
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L7018] {_silent_err}")
        return None

    # —— 从 full_market_data 提取 API 盘口均值（可能为浅盘档位）——
    avg_ah_line = None
    avg_ou_line = None
    try:
        if full_market_data:
            ah_vals = [_safe_float_line(m['ah']['line']) for m in full_market_data]
            ou_vals = [_safe_float_line(m['ou']['line']) for m in full_market_data]
            ah_vals = [v for v in ah_vals if v is not None]
            ou_vals = [v for v in ou_vals if v is not None]
            if ah_vals:
                avg_ah_line = standardize_ah_line(sum(ah_vals) / len(ah_vals))
            if ou_vals:
                avg_ou_line = standardize_ou_line(sum(ou_vals) / len(ou_vals))
    except (KeyError, TypeError, ZeroDivisionError, ValueError):
        avg_ah_line = None
        avg_ou_line = None

    # —— 【问题2修复·真值锚定】用外层主链路真实盘口校正 API 浅盘污染 ——
    # 规则：① API 缺失 → 直接用真值；② API 与真值方向/深度差异过大 → 以真值为准。
    #   API-Football 的 Asian Handicap values[0] 常取浅盘档（如 -0.5/-1），
    #   会把 -2.703 这类深盘误压成浅盘，是 λ 低估的直接成因。
    _LINE_DIVERGENCE_TOL = 0.75  # AH/OU 偏差容忍阈（球）
    if ref_ah is not None:  # noqa: SIM102 - intentional degraded-mode guard or structure-preserving fallback
        if avg_ah_line is None or abs(avg_ah_line - ref_ah) > _LINE_DIVERGENCE_TOL:
            avg_ah_line = standardize_ah_line(ref_ah)
    if ref_ou is not None:  # noqa: SIM102 - intentional degraded-mode guard or structure-preserving fallback
        if avg_ou_line is None or abs(avg_ou_line - ref_ou) > _LINE_DIVERGENCE_TOL:
            avg_ou_line = standardize_ou_line(ref_ou)

    # —— 仍无有效盘口 → 优雅降级 ——
    if avg_ah_line is None or avg_ou_line is None:
        return historical_lambda_h, historical_lambda_a

    # —— 解方程组，得出市场隐含的绝对 Lambda ——
    #   λ_home = (O/U - AH)/2,  λ_away = (O/U + AH)/2  （AH 主让为负）
    try:
        implied_lambda_h = (avg_ou_line - avg_ah_line) / 2.0
        implied_lambda_a = (avg_ou_line + avg_ah_line) / 2.0
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return historical_lambda_h, historical_lambda_a

    # —— 防止数学下溢出 / NaN ——
    if math.isnan(implied_lambda_h) or math.isnan(implied_lambda_a):
        return historical_lambda_h, historical_lambda_a
    implied_lambda_h = max(0.1, implied_lambda_h)
    implied_lambda_a = max(0.1, implied_lambda_a)

    # —— 【问题2修复·深盘高市场权重】——
    # 普通盘：70% 市场 + 30% 历史；70%市场+30%历史在极端深盘下会向均值严重回归，
    # 故盘口越深、市场权重越高，削弱历史 λ 对深盘的拖累。
    _ah_depth = abs(avg_ah_line)
    if _ah_depth > 2.0:
        alpha_market = 0.90
    elif _ah_depth > 1.5:
        alpha_market = 0.85
    elif _ah_depth > 1.0:
        alpha_market = 0.78
    else:
        alpha_market = 0.70

    # ==========================================================================
    # 【核心重构三·软权重自洽平衡（Dynamic Mixing Rate）】
    # 当检测到必发数据缺失时，市场定价维度缺乏了资金量的立体支撑
    # （此时的“市场价”往往只是博彩公司的防守价），系统必须自动降低市场权重，
    # 提升近期实际火力的比例。动态公式：必发缺失时权重自动滑向 [50%市场+50%历史火力]。
    # 为不破坏深盘高市场权重的保护，仅在 alpha_market > 0.5 时才下拉至 0.5。
    # ==========================================================================
    try:
        if betfair_missing and alpha_market > 0.5:
            _orig_alpha_market = alpha_market
            alpha_market = 0.5
            print(f"   🛡️ [低置信度市场面·火力托举增强] 必发数据缺失，市场权重降至50%，"
                  f"历史火力权重升至50%（原{_orig_alpha_market*100:.0f}%市场→现50%）")
    except Exception as _dmr_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        try:
            print(f"   ⚠️ [软权重自洽平衡] 动态混合率调整异常，保留原权重: {_dmr_err}")
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L7098] {_silent_err}")

    alpha_history = 1.0 - alpha_market

    # —— 步骤2：先融合 market×α + history×(1-α) ——
    # 【禁止】先对 history 做偏移补偿再融合，或把补偿结果当成 final（错把 history 传进补偿）。
    try:
        fused_lambda_h = (implied_lambda_h * alpha_market) + (float(historical_lambda_h) * alpha_history)
        fused_lambda_a = (implied_lambda_a * alpha_market) + (float(historical_lambda_a) * alpha_history)
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return historical_lambda_h, historical_lambda_a

    # —— 【问题2修复·深盘 λ 总量兜底】作用于融合后的 fused λ ——
    # 若平滑后总 λ 被历史项严重拖低（< O/U 线 * 0.8），说明 λ 被低估，
    # 强制将总 λ 拉回 O/U 线 * 0.9，并按主客比例重新分配，保持净胜球差不变。
    try:
        _final_total = fused_lambda_h + fused_lambda_a
        _floor_total = avg_ou_line * 0.8
        if _final_total < _floor_total and avg_ou_line > 0:
            _target_total = avg_ou_line * 0.9
            # 净胜球差 = -AH（主让为负 → 主净胜为正）
            _diff = -avg_ah_line
            new_h = (_target_total + _diff) / 2.0
            new_a = (_target_total - _diff) / 2.0
            fused_lambda_h = max(0.1, new_h)
            fused_lambda_a = max(0.1, new_a)
    except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [异常已捕获·pass降级 L7123] {_silent_err}")

    # —— 步骤3：偏移补偿只作用于融合后的 fused λ ——
    _comp_offset_h = float(offset_h or 0.0)
    _comp_offset_a = float(offset_a or 0.0)
    try:
        if auto_offset and abs(_comp_offset_h) < 1e-12 and abs(_comp_offset_a) < 1e-12:
            _delta_h = float(implied_lambda_h) - float(historical_lambda_h)
            _delta_a = float(implied_lambda_a) - float(historical_lambda_a)
            _thr = float(offset_threshold)
            _frac = float(offset_frac)
            _cap = float(offset_cap)
            if abs(_delta_h) > _thr:
                _comp_offset_h = max(-_cap, min(_cap, _delta_h * _frac))
            if abs(_delta_a) > _thr:
                _comp_offset_a = max(-_cap, min(_cap, _delta_a * _frac))
    except Exception as _auto_off_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [λ偏移自动生成] 异常已跳过: {_auto_off_err}")

    final_lambda_h = apply_lambda_offset_compensation(fused_lambda_h, _comp_offset_h)
    final_lambda_a = apply_lambda_offset_compensation(fused_lambda_a, _comp_offset_a)
    if abs(_comp_offset_h) > 1e-12 or abs(_comp_offset_a) > 1e-12:
        print(
            f"   🎯 [λ偏移补偿·融合后] fused=({fused_lambda_h:.3f},{fused_lambda_a:.3f}) "
            f"offset=({_comp_offset_h:+.3f},{_comp_offset_a:+.3f}) → "
            f"final=({final_lambda_h:.3f},{final_lambda_a:.3f})"
        )

    # ==========================================================================
    # ⚓🎣 【全维度顺位追踪矩阵·精算表 → LambdaCalibrator 方向一致性复核】
    # 【方案 A】由于本场 RTM 必然晚于 λ 校准（RTM 需要完整 enriched 池），
    # 这里接受上游传入的 RTM 方向性判断 rtm_direction ∈ {'home','away','draw'}。
    # 仅当 RTM 给出强方向信号且与市场隐含方向一致时，对已校准 λ 做
    # 受限方向偏置（幅度上限 ±8%），绝不硬造。方向冲突时不动，避免被诱饵带偏。
    # ==========================================================================
    try:
        if rtm_direction in ('home', 'away'):
            _market_diff = final_lambda_h - final_lambda_a  # >0 偏主 / <0 偏客
            _BIAS = 0.08  # 受限偏置幅度上限
            if rtm_direction == 'home' and _market_diff > 0:
                # RTM 与市场同向看主：主队 λ 轻度上提，客队 λ 轻度下压
                final_lambda_h = min(final_lambda_h * (1.0 + _BIAS), final_lambda_h + 0.30)
                final_lambda_a = max(final_lambda_a * (1.0 - _BIAS), 0.1)
            elif rtm_direction == 'away' and _market_diff < 0:
                final_lambda_a = min(final_lambda_a * (1.0 + _BIAS), final_lambda_a + 0.30)
                final_lambda_h = max(final_lambda_h * (1.0 - _BIAS), 0.1)
    except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [异常已捕获·pass降级 L7144] {_silent_err}")

    # 深盘下限放在方向偏置之后。大小球 ≥ 3.0 时，总量不得停在「小球概率高于大球」的一侧。
    try:
        _floor_total = coerce_float(_ou_line_lambda_floor(avg_ou_line))
        _now_total = float(final_lambda_h) + float(final_lambda_a)
        lifted_h, lifted_a, _lifted = _lift_lambda_pair_to_floor(
            final_lambda_h, final_lambda_a, _floor_total
        )
        if _lifted:
            _avg_ou_line = coerce_float(avg_ou_line)
            _coeff = _floor_total / _avg_ou_line if _avg_ou_line else 0.0
            print(
                f"   📐 [λ下限·盘口对齐] OU={_avg_ou_line:.2f} "
                f"下限={_floor_total:.3f}(系数{_coeff:.3f}) > 合计{_now_total:.3f}，"
                f"按攻防比抬到 {lifted_h:.3f}/{lifted_a:.3f}"
            )
            final_lambda_h, final_lambda_a = lifted_h, lifted_a
    except Exception as _floor_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [λ下限·盘口对齐] 已跳过: {_floor_err}")

    return final_lambda_h, final_lambda_a


# ============================================================================
# 【架构升级一·Shannon Entropy Smooth Constraints】香农熵网格平滑约束防火墙
# ----------------------------------------------------------------------------
# 在 LambdaCalibrator 与动态托举之前的前置数据清洗层。
# 核心思想：当当前泊松矩阵的「总进球分布众数(Mode)」与市场大小球线(ou_line)
# 产生系统性背离时，判定上游 λ 修正源（API-Football 兜底概率、异常盘口转化值）
# 被「数据投毒」，触发降权锁，保护最终 λ 不被污染。
#
# 数学：
#   1. 由当前 (lam_h, lam_a) 生成波胆矩阵，聚合为总进球概率分布 P(total=k)。
#   2. 香农熵 H = -Σ p_i · log2(p_i)，刻画分布的不确定度（仅诊断/日志用）。
#   3. 众数 Mode = argmax_k P(total=k)，即最可能的总进球数。
#   4. 系统性背离判据：
#        · Mode == 1 且 ou_line >= 3.0  → 低开高走背离（盘口看大但矩阵塌缩到极低分）
#        · Mode >= 4 且 ou_line <= 2.0  → 高开低走背离（盘口看小但矩阵爆量到极高分）
#   5. 命中任一判据 → poisoned=True，返回降权系数（默认 0.1）。
# 全程 try/except 包裹，任何异常一律判为「未中毒」，完全向后兼容。
# ============================================================================
def shannon_entropy_smooth_guard(lam_h, lam_a, ou_line, lambda_shared=0.0,
                                 max_goals=8,
                                 poison_weight=0.1):
    """香农熵网格平滑约束：检测总进球分布众数与市场 OU 线的系统性背离。

    参数:
        lam_h, lam_a : float
            当前（校准前）的主/客队进球期望 λ。
        ou_line : float | None
            市场大小球盘口线（总进球预期）。None 时跳过判定。
        lambda_shared : float
            双变量泊松共享强度，与 calc_bivariate_poisson_matrix 保持一致。
        max_goals : int
            泊松矩阵截断上限。
        poison_weight : float
            判定中毒后返回的污染源降权系数（0~1，越小越严厉）。

    返回 dict:
        {
          'poisoned': bool,        # 是否判定为数据投毒
          'mode': int | None,      # 总进球分布众数
          'entropy': float | None, # 香农熵 H（bits）
          'ou_line': float | None, # 参与判定的 OU 线
          'penalty_weight': float, # 命中时为 poison_weight，否则 1.0
          'reason': str,           # 背离类型说明
        }
    """
    import math as _math
    result = {
        'poisoned': False,
        'mode': None,
        'entropy': None,
        'ou_line': None,
        'penalty_weight': 1.0,
        'reason': '',
    }
    try:
        # —— OU 线安全转换；缺失则无法判定背离，直接放行 ——
        try:
            _ou = float(ou_line) if ou_line is not None else None
        except (ValueError, TypeError):
            _ou = None
        if _ou is None or _ou <= 0:
            result['reason'] = 'ou_line 缺失或非法，跳过香农熵判定'
            return result
        result['ou_line'] = round(_ou, 3)

        # —— 生成波胆矩阵并聚合为总进球概率分布 ——
        _matrix = calc_bivariate_poisson_matrix(
            lam_h, lam_a, lambda_shared=lambda_shared, max_goals=max_goals
        )
        if not _matrix:
            result['reason'] = '泊松矩阵为空，跳过香农熵判定'
            return result

        _total_dist = {}
        for _sc, _p in _matrix.items():
            try:
                _h, _a = parse_score(_sc)
            except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                print(f"   ⚠️ [异常已捕获·continue降级 L7227] {_silent_err}")
                continue
            if _h is None or _a is None:
                continue
            _k = _h + _a
            _total_dist[_k] = _total_dist.get(_k, 0.0) + float(_p)
        if not _total_dist:
            result['reason'] = '总进球分布为空，跳过香农熵判定'
            return result

        # —— 归一化 ——
        _s = sum(_total_dist.values())
        if _s <= 0:
            result['reason'] = '总进球分布概率和<=0，跳过香农熵判定'
            return result
        _total_dist = {k: v / _s for k, v in _total_dist.items()}

        # —— 香农熵 H = -Σ p·log2(p) ——
        _H = 0.0
        for _p in _total_dist.values():
            if _p > 0:
                _H -= _p * _math.log2(_p)
        result['entropy'] = round(_H, 4)

        # —— 众数 Mode = argmax_k P(total=k) ——
        _mode = max(_total_dist.items(), key=lambda kv: kv[1])[0]
        result['mode'] = int(_mode)

        # —— 系统性背离判据 ——
        _poisoned = False
        _reason = '众数与OU线一致，无系统性背离'
        if _mode == 1 and _ou >= 3.0:
            _poisoned = True
            _reason = f'低开高走背离: 众数={_mode}(极低分) 但 OU线={_ou:.2f}>=3.0(盘口看大)'
        elif _mode >= 4 and _ou <= 2.0:
            _poisoned = True
            _reason = f'高开低走背离: 众数={_mode}(极高分) 但 OU线={_ou:.2f}<=2.0(盘口看小)'
        result['reason'] = _reason

        if _poisoned:
            result['poisoned'] = True
            try:
                _pw = float(poison_weight)
            except (ValueError, TypeError):
                _pw = 0.1
            result['penalty_weight'] = max(0.0, min(1.0, _pw))
    except Exception as _e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        # 任何异常一律判为未中毒，保证向后兼容
        result['poisoned'] = False
        result['penalty_weight'] = 1.0
        result['reason'] = f'香农熵守卫异常已跳过: {_e}'
    return result


def apply_generalized_dna_correction(lambda_h, lambda_a, ev_data, trajectory_ou):
    """进球期望原样返回。不按写死比分改上下限。"""
    try:
        if lambda_h is None or lambda_a is None:
            return lambda_h, lambda_a
        return float(lambda_h), float(lambda_a)
    except (TypeError, ValueError):
        return lambda_h, lambda_a


# 兼容旧接口：保留原函数名作为别名
def apply_dna_lambda_correction(league_name, home_team, away_team, lambda_h, lambda_a,
                                ev_data=None, trajectory_ou='neutral'):
    """兼容层：转发到  全域泛化版 DNA 修正"""
    return apply_generalized_dna_correction(lambda_h, lambda_a, ev_data, trajectory_ou)


