def calculate_total_goals(score_str):
    """从比分字符串提取总进球数
    Args:
        score_str: str, 比分字符串如 '2-1', '3:0', '胜其它' 等
    Returns:
        int: 总进球数，无法解析时返回 0
    """
    if not score_str or not isinstance(score_str, str):
        return 0
    # 跳过"胜其它/平其它/负其它"
    if '其它' in score_str:
        return 0
    try:
        h, a = parse_score(score_str)
        if h is None or a is None:
            return 0

        return h + a
    except (ValueError, IndexError, TypeError):
        return 0


# 【废弃代码清理】check_ibi_gradient_smoothness 定义已删除（架构统一重构）。

def update_strategy_weights(candidate_pool, overflow_candidates, direction_lock_payload=None, game_signal_count=None):
    """将受保护的高能比分项提升至决策权重，形成"主力+顺势"双决策
    Args:
        candidate_pool: list of dict, 完整候选池
        overflow_candidates: list of dict, 被保护的高能比分项
    Returns:
        list of dict: 更新权重后的候选池
    """
    try:
        signal_n = int(game_signal_count) if game_signal_count is not None else None
    except (TypeError, ValueError):
        signal_n = None
    if signal_n == 0:
        print('   ℹ️ [动态修正] 博弈信号数为0，停用方向锁二次加码，方向锁只读保留')
        return candidate_pool
    if not overflow_candidates:
        return candidate_pool
    # 找到当前池中权重最高的项（主力）
    max_weight = 0.0
    for item in candidate_pool:
        w = float(item.get('weight_multiplier', 1.0) or 1.0)
        max_weight = max(max_weight, w)
    # 将受保护项的权重提升至主力权重的 90%（形成"顺势"决策）
    boost_weight = max(max_weight * 0.90, 1.0)
    boosted_scores = []
    _boost_dir = ''
    _boost_analyzer = _ensure_deepseek_analyzer() if direction_lock_payload else None
    if direction_lock_payload and _boost_analyzer is not None:
        try:
            _boost_dir = _boost_analyzer.matrix_direction_lock(direction_lock_payload).get('direction') or ''
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            _boost_dir = ''
    _boost_drop = []
    for item in candidate_pool:
        score_str = str(item.get('score', '')).strip()
        is_overflow = any(
            str(oc.get('score', '')).strip() == score_str
            for oc in overflow_candidates
        )
        if not is_overflow:
            continue
        if _boost_dir and score_str:
            try:
                if _boost_analyzer is not None and _boost_analyzer._classify_score_wdl(score_str)[1] != _boost_dir:
                    _boost_drop.append(score_str)
                    continue
            except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
                pass
        if is_overflow:
            item['weight_multiplier'] = boost_weight
            item['firepower_override'] = True
            boosted_scores.append(score_str)
    if _boost_drop:
        print(f"   🔒 [方向锁] 顺势提权跳过方向外 {_boost_drop}")
    if boosted_scores:
        print(f"   🔥 [动态修正·顺势提权] 受保护高能比分已提升至决策权重({boost_weight:.2f}): {boosted_scores}")
    return candidate_pool


# 【废弃代码清理】apply_firepower_exemption 定义已删除（架构统一重构）。

def override_model_convergence(candidate_pool, static_manipulation_score, match_context=None, direction_lock_payload=None, game_signal_count=None):
    """静态诱导修正：高诱导场次提升受保护的球队能力/理论高能比分。"""
    try:
        override_log = ""
        override_triggered = False
        if not candidate_pool:
            return candidate_pool, False, ""
        deviation = max(0.0, min(1.0, float(static_manipulation_score or 0.0)))
        if deviation > 0.20:
            overflow_candidates = [i for i in candidate_pool if i.get('is_protected')]
            if overflow_candidates:
                candidate_pool = update_strategy_weights(
                    candidate_pool, overflow_candidates,
                    direction_lock_payload=direction_lock_payload,
                    game_signal_count=game_signal_count,
                )
                if game_signal_count == 0 or str(game_signal_count) == '0':
                    return candidate_pool, False, '博弈信号数为0，停用二次加码，方向锁只读保留'
                override_triggered = True
                _oc_scores = [str(oc.get('score', '')) for oc in overflow_candidates]
                override_log = (
                    f"静态诱导分值={deviation:.4f}(>0.20)，"
                    f"市场赔率噪音较高 → 受保护理论高能比分{_oc_scores}已提升决策权重"
                )
                print(f"   🔥 [静态诱导修正] {override_log}")
        return candidate_pool, override_triggered, override_log
    except Exception as _static_override_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        try:
            return candidate_pool, False, f"静态诱导修正异常(已降级):{_static_override_err}"
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            return [], False, "静态诱导修正异常(已降级)"


# ═══ 全局生命周期锁状态类 ═══
class PipelineLifecycle:
    """终极流程生命周期锁：物理阻断后处理阶段的特征逆向回流"""
    CURRENT_STAGE = "INITIALIZATION"

    @classmethod
    def advance(cls, stage):
        cls.CURRENT_STAGE = stage

    @classmethod
    def is_post_gate(cls):
        return cls.CURRENT_STAGE in ["POST_GATE_CORRECTION", "FINAL_REPORT_OUT", "ACCURACY_ANALYSIS"]


def execute_ibi_gradient_analysis(matrix_df, current_stage=None):
    """
    终极架构改造：基于流程生命周期的特征写入绝对熔断锁
    【升级】单阶单流过滤器：计算结果缓存，下游只读，杜绝重复打印
    """
    # 单阶单流：如果已有冻结快照，直接返回快照数据，不重复计算/打印
    try:
        if hasattr(FeatureSpaceSnapshot, '_frozen') and FeatureSpaceSnapshot._frozen:
            _cached = FeatureSpaceSnapshot.get_ibi_gradient()
            if _cached is not None:
                return _cached
    except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [异常已捕获·pass降级 L9163] {_silent_err}")
    if PipelineLifecycle.is_post_gate():
        print("   🛡️ [Lifecycle Lock] 强行拦截最末端特征回流套娃异常，直接吐出只读快照。")
        return None
    # 仅允许在符合单向单流的初始清洗与二次精修阶段正常计算
    try:
        return compute_ibi_smoothness_gradient(matrix_df, verbose=False) if callable(globals().get('compute_ibi_smoothness_gradient')) else None
    except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [Lifecycle Lock] IBI梯度计算异常: {e}")
        return None


def sanitize_routing_payload(entropy_route_dict, true_iron_anchors):
    """
    自适应路由空值自愈清洗锁：杜绝非结构化字符泄露到下游决策层
    """
    if not isinstance(entropy_route_dict, dict) or not true_iron_anchors:
        return entropy_route_dict
    try:
        for route_key in ['first_choice', 'secondary_choice']:
            val = entropy_route_dict.get(route_key)
            if val in ['N/A', None, 'NULL', '', 'None', 'nan']:
                backup_idx = 0 if route_key == 'first_choice' else min(1, len(true_iron_anchors) - 1)
                backup_anchor = true_iron_anchors[backup_idx] if backup_idx < len(true_iron_anchors) else true_iron_anchors[0]
                entropy_route_dict[route_key] = backup_anchor
                print(f"   💾 [空值自愈] 发现特征流出空洞 {route_key} -> 已自动平移补充真实资产: {backup_anchor}")
    except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [空值自愈] 清洗异常(已降级): {e}")
    return entropy_route_dict


def unified_account_checklist(first_score, second_score, match_context):
    """
    一元化自洽对账收敛矩阵：最终输出前的多维一致性网格过滤
    对账红线：大小盘期望上限、让球空间深度包络线、方向一致性
    """
    try:
        result = {'passed': True, 'adjustments': [], 'checklist_items': []}

        # 解析比分
        h1, a1 = parse_score(first_score)
        h2, a2 = parse_score(second_score)
        if h1 is None or a1 is None or h2 is None or a2 is None:
            result['passed'] = False
            result['checklist_items'].append("⚠️ 比分解析失败，跳过自洽对账")
            return result
        total1, total2 = h1 + a1, h2 + a2

        # 提取对账参数
        ou_line = match_context.get('ou_line')
        ah_line = match_context.get('ah_line')
        match_context.get('or_direction', '')
        ai_ou_pred = match_context.get('ai_ou_pred', '')
        rtm_anchors = match_context.get('rtm_anchors', [])

        # ═══ 对账项1：大小球期望上限红线 ═══
        if ou_line is not None:
            try:
                ou_val = float(ou_line)
                avg_total = (total1 + total2) / 2
                if abs(avg_total - ou_val) > 1.5:
                    result['checklist_items'].append(f"⚠️ 大小球红线：均总进球{avg_total:.1f}偏离OU线{ou_val}超1.5球")
                    result['passed'] = False
                else:
                    result['checklist_items'].append(f"✅ 大小球对账：均总进球{avg_total:.1f} vs OU线{ou_val}（偏差{abs(avg_total-ou_val):.1f}）")
            except (ValueError, TypeError):
                pass

        # ═══ 对账项2：让球空间深度包络线 ═══
        if ah_line is not None:
            try:
                ah_val = float(ah_line)
                margin1, margin2 = h1 - a1, h2 - a2
                avg_margin = (margin1 + margin2) / 2
                if ah_val > 0 and avg_margin < -1:
                    result['checklist_items'].append(f"⚠️ 让球红线：主让{ah_val}但均净胜{avg_margin:.1f}（方向严重反向）")
                    result['passed'] = False
                elif ah_val < 0 and avg_margin > 1:
                    result['checklist_items'].append(f"⚠️ 让球红线：客让{abs(ah_val)}但均净胜{avg_margin:.1f}（方向严重反向）")
                    result['passed'] = False
                else:
                    result['checklist_items'].append(f"✅ 让球对账：AH={ah_val} vs 均净胜{avg_margin:.1f}（方向一致）")
            except (ValueError, TypeError):
                pass

        # ═══ 对账项3：AI大小球判定与比分总进球一致性 ═══
        if ai_ou_pred:
            is_big = '大' in str(ai_ou_pred)
            is_small = '小' in str(ai_ou_pred)
            if ou_line is not None:
                try:
                    ou_val = float(ou_line)
                    if is_big and total1 <= ou_val and total2 <= ou_val:
                        result['checklist_items'].append(f"⚠️ AI判大球但两比分{first_score}/{second_score}均≤OU线{ou_val}")
                        result['passed'] = False
                    elif is_small and total1 > ou_val and total2 > ou_val:
                        result['checklist_items'].append(f"⚠️ AI判小球但两比分{first_score}/{second_score}均>OU线{ou_val}")
                        result['passed'] = False
                    else:
                        result['checklist_items'].append("✅ AI大小球与比分总进球方向一致")
                except (ValueError, TypeError):
                    pass

        # ═══ 对账项4：RTM铁锚覆盖率 ═══
        if rtm_anchors:
            anchor_coverage = sum(1 for s in [first_score, second_score] if s in rtm_anchors)
            if anchor_coverage == 0:
                result['checklist_items'].append(f"⚠️ 铁锚覆盖率=0：{first_score}/{second_score}均不在铁锚{rtm_anchors[:3]}中")
            else:
                result['checklist_items'].append(f"✅ 铁锚覆盖率={anchor_coverage}/2")

        # ═══ 对账项5：两比分方向一致性 ═══
        dir1 = 'H' if h1 > a1 else ('D' if h1 == a1 else 'A')
        dir2 = 'H' if h2 > a2 else ('D' if h2 == a2 else 'A')
        if dir1 != dir2:
            result['checklist_items'].append(f"ℹ️ 方向分散：首选{first_score}({dir1}) vs 次选{second_score}({dir2})")
        else:
            result['checklist_items'].append(f"✅ 方向一致：{dir1}")

        # ====================================================================
        # 【博弈论升级·模块2·unified_account_checklist】纳什均衡收敛判定
        # 将每个对账项视为一个博弈方(player)，其“策略”为通过(1)或违反(0)。
        # 在原有逐项对账的基础上，叠加一层纳什均衡检查：
        #   - 若所有对账项同时满足(无一方可通过单方面偏离提升收益)，则达成纯策略纳什均衡。
        #   - 用“违反项数”量化偏离均衡的距离(stability_gap)；违反越多越偏离。
        #   - 计算收敛度 convergence = 满足项/总项，作为均衡质量。
        # 新增字段写入 result: 'nash_equilibrium'/'nash_convergence'/'nash_stability_gap'等。
        # 全程 try/except，不影响原有 passed/checklist_items 结果。
        # ====================================================================
        try:
            _nash_items = result.get('checklist_items', []) or []
            # 将对账项量化为博弈方策略: ✅=满足(payoff=1), ⚠️=违反(payoff=0), ℹ️=中性(不计入均衡强约束)
            _players = []  # [(item_text, payoff_satisfied: bool, is_hard: bool)]
            for _ci in _nash_items:
                _txt = str(_ci)
                if _txt.startswith('✅'):
                    _players.append((_txt, True, True))
                elif _txt.startswith('⚠️'):
                    _players.append((_txt, False, True))
                else:
                    # ℹ️ 等软信息项不作为硬约束博弈方
                    _players.append((_txt, True, False))
            _hard_players = [p for p in _players if p[2]]
            _total_p = len(_hard_players)
            _satisfied_p = sum(1 for p in _hard_players if p[1])
            _violation_cnt = _total_p - _satisfied_p
            # 纳什均衡: 所有硬约束博弈方同时满足(无单方面有益偏离)
            _nash_reached = (_total_p > 0 and _violation_cnt == 0)
            _nash_convergence = (_satisfied_p / _total_p) if _total_p > 0 else 1.0
            result['nash_equilibrium'] = bool(_nash_reached)
            result['nash_convergence'] = round(_nash_convergence, 4)
            result['nash_stability_gap'] = int(_violation_cnt)
            result['nash_player_count'] = int(_total_p)
            if _nash_reached:
                result['checklist_items'].append(
                    f"⚖️ 纳什均衡达成: {_total_p}个对账博弈方均满足，无单方面偏离有益的纯策略均衡点(收敛度=100%)"
                )
            else:
                result['checklist_items'].append(
                    f"⚖️ 纳什均衡未达成: 存在{_violation_cnt}个偏离项(收敛度={_nash_convergence*100:.0f}%)，该比分组合非稳定均衡点"
                )
        except Exception as _nash_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            try:
                result['checklist_items'].append(f"⚖️ 纳什均衡判定异常(已降级): {_nash_err}")
            except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                print(f"   ⚠️ [异常已捕获·pass降级 L9324] {_silent_err}")

        return result
    except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return {'passed': True, 'adjustments': [], 'checklist_items': [f"⚠️ 对账异常: {e}"]}


# ============================================================================
# 【架构重构一·特征空间单向隔离阻断协议（Pipeline Monodirectional Block）】
# 核心：IBI梯度分析与全维度合理性分析只在前级执行一次，产出不可变快照。
# 下游模块（GBDT掩码锁后/AI引擎后/TG报告）统一消费快照，禁止反向重算。
# ============================================================================
class FeatureSpaceSnapshot:
    """特征空间只读快照管理器：防止下游决策层反向回流调用上游特征清洗模块"""
    _instance = None
    _frozen = False
    _ibi_gradient_snapshot: ClassVar[dict[str, Any]] = {}
    _full_dim_snapshot: ClassVar[dict[str, Any]] = {}
    _snapshot_stage = 'INIT'  # INIT → COMPUTED → FROZEN
    
    @classmethod
    def reset(cls):
        """每场比赛开始时重置快照状态"""
        cls._frozen = False
        cls._ibi_gradient_snapshot = {}
        cls._full_dim_snapshot = {}
        cls._snapshot_stage = 'INIT'
    
    @classmethod
    def compute_and_freeze(cls, pool15_enriched, direction_lock_payload=None):
        """一次性计算IBI梯度和全维度分析，然后冻结为只读快照。
        此方法只允许调用一次（per match），重复调用直接返回已有快照。
        """
        if cls._frozen:
            print("   🔒 [Pipeline Lock] 特征空间已冻结，跳过重复计算（只读快照生效中）")
            return cls._ibi_gradient_snapshot, cls._full_dim_snapshot
        
        try:
            cls._ibi_gradient_snapshot = compute_ibi_smoothness_gradient(pool15_enriched)
        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [Pipeline Lock] IBI梯度计算异常: {e}")
            cls._ibi_gradient_snapshot = {}
        
        try:
            _fdim = compute_full_dimension_smoothness(
                pool15_enriched, direction_lock_payload=direction_lock_payload,
            )
            cls._full_dim_snapshot = _fdim if _fdim else {}
        except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [Pipeline Lock] 全维度分析异常: {e}")
            cls._full_dim_snapshot = {}
        
        cls._frozen = True
        cls._snapshot_stage = 'FROZEN'
        _n_grad = len(cls._ibi_gradient_snapshot)
        _n_focus = len(cls._full_dim_snapshot.get('focus_scores', []))
        print(f"   🔒 [Pipeline Lock] 特征空间快照已冻结: IBI梯度={_n_grad}项, 全维度重点关注={_n_focus}项")
        return cls._ibi_gradient_snapshot, cls._full_dim_snapshot
    
    @classmethod
    def get_ibi_gradient(cls):
        """获取IBI梯度只读快照（下游消费专用）"""
        if not cls._frozen:
            print("   ⚠️ [Pipeline Lock] 警告：快照未冻结就被读取，可能存在调用顺序问题")
        return cls._ibi_gradient_snapshot.copy()
    
    @classmethod
    def get_full_dim(cls):
        """获取全维度分析只读快照（下游消费专用）"""
        if not cls._frozen:
            print("   ⚠️ [Pipeline Lock] 警告：快照未冻结就被读取")
        return cls._full_dim_snapshot.copy() if isinstance(cls._full_dim_snapshot, dict) else {}
    
    @classmethod
    def is_frozen(cls):
        return cls._frozen


def handicap_slicer(score_matrix, asian_handicap=0.0, ah_odds=None):
    """【模块二·亚盘穿透测试器·正确AH引擎驱动】
    
    沿 X 轴切片求和，计算任意让球盘口的理论胜率。
    正确处理三类盘口（半球系/整数系/季度系），输出五类概率。
    
    P_AH 通过 AsianHandicapEngine.settle_bet() 精确结算每个比分格。
    返回字典兼容旧接口（theory_win/theory_lose/theory_push）
    并新增五类细分概率（home_full_win/home_half_win/push/away_half_win/away_full_win）。
    """
    try:
        _ah = float(asian_handicap) if asian_handicap is not None else 0.0
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        _ah = 0.0
    
    # 从 score_matrix 提取比分概率
    prob_dict = {}
    try:
        nodes = score_matrix.get_all_nodes() if score_matrix else []
        for n in nodes:
            score_key = f"{n.h}-{n.a}" if hasattr(n, 'h') else str(getattr(n, 'score', ''))
            prob_dict[score_key] = n.prob_theory
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        # 兼容不同 score_matrix 接口
        try:
            if hasattr(score_matrix, 'items'):
                prob_dict = dict(score_matrix)
            elif isinstance(score_matrix, list):
                for item in score_matrix:
                    if isinstance(item, dict):
                        prob_dict[item.get('score', '')] = item.get('prob', 0)
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            prob_dict = {}
    
    # 使用 AsianHandicapEngine 进行精确穿透计算
    engine = AsianHandicapEngine(asian_handicap=_ah, prob_dict=prob_dict, market_odds=ah_odds or {})
    penetration = engine.handicap_probability_penetration(handicap_line=_ah, prob_dict=prob_dict)
    
    # 计算与市场水位的套利差值（兼容旧接口）
    arbitrage = None
    if isinstance(ah_odds, dict):
        try:
            home_odds = float(ah_odds.get('home_win', ah_odds.get('home', 0)) or 0)
            if home_odds > 1.0:
                implied = 1.0 / home_odds
                arbitrage = round(penetration.get('home_cover_prob', 0) - implied, 4)
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            arbitrage = None
    
    return {
        'handicap_line': _ah,
        'handicap_type': penetration.get('handicap_type'),
        # 兼容旧接口
        'theory_win': penetration.get('theory_win', 0.0),
        'theory_lose': penetration.get('theory_lose', 0.0),
        'theory_push': penetration.get('theory_push', 0.0),
        'arbitrage_gap': arbitrage if arbitrage is not None else penetration.get('arbitrage_gap'),
        # 新增五类细分概率
        'home_full_win': penetration.get('home_full_win', 0.0),
        'home_half_win': penetration.get('home_half_win', 0.0),
        'push': penetration.get('push', 0.0),
        'away_half_win': penetration.get('away_half_win', 0.0),
        'away_full_win': penetration.get('away_full_win', 0.0),
        'home_cover_prob': penetration.get('home_cover_prob', 0.0),
        'away_cover_prob': penetration.get('away_cover_prob', 0.0),
        'penetration_alert': penetration.get('penetration_alert'),
    }


def total_goals_aggregator(score_matrix, ou_line=None, ou_odds=None):
    """【模块二·大小球张力聚合器】Z 轴扫描，计算任意大小球盘口的理论概率。

    返回字典：theory_over / theory_under / sticky_low（≤2 球的累积概率）/ tension_warning。
    若 sum(P(total<=2)) >= 0.90 但盘口水位异常，则抛出"低进球粘滞"警告。
    """
    _line = None
    if ou_line is not None:
        try:
            _line = float(ou_line)
        except (TypeError, ValueError):
            _line = None
    nodes = score_matrix.get_all_nodes() if score_matrix else []
    if _line is None:
        p_over = p_under = p_push = 0.0
    else:
        p_over = sum(n.prob_theory for n in nodes if n.total_goals > _line)
        p_under = sum(n.prob_theory for n in nodes if n.total_goals < _line)
        p_push = max(0.0, 1.0 - p_over - p_under)
    sticky_low = sum(n.prob_theory for n in nodes if n.total_goals <= 2)

    tension_warning = None
    if sticky_low >= 0.90:
        market_over = None
        if isinstance(ou_odds, dict):
            try:
                _o = float(ou_odds.get('over', 0) or 0)
                if _o > 1.0:
                    market_over = 1.0 / _o
            except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                market_over = None
        if market_over is not None and market_over > (1 - sticky_low) + 0.10:
            tension_warning = f"⚠️低进球粘滞：≤2球理论概率达{sticky_low:.1%}，但市场大球水位异常偏高，警惕反向诱盘"
        else:
            tension_warning = f"⚠️低进球粘滞：≤2球理论概率达{sticky_low:.1%}，需谨慎大球高水位押注"
    return {
        'ou_line': _line,
        'theory_over': round(p_over, 4),
        'theory_under': round(p_under, 4),
        'theory_push': round(p_push, 4),
        'sticky_low': round(sticky_low, 4),
        'tension_warning': tension_warning,
    }


# ---------------- 模块三：风险与防御模块 ----------------

def tail_risk_convergence_engine(score_matrix, threshold=0.05):
    """【模块三·尾部坍塌预警】计算 P_home_other = P_home_win - sum(known_home_scores)。

    若 P_home_other > 5%，强制熔断小比分高杠杆押注，返回 (warning_text, p_home_other)。
    同时对客胜尾部做对称检测。
    """
    if score_matrix is None:
        return [], {}
    known_home_scores = {'1-0', '2-0', '2-1', '3-0', '3-1', '3-2', '4-0', '4-1', '4-2',
                         '5-0', '5-1', '5-2'}
    known_away_scores = {'0-1', '0-2', '1-2', '0-3', '1-3', '2-3', '0-4', '1-4', '2-4',
                         '0-5', '1-5', '2-5'}
    nodes = score_matrix.get_all_nodes()
    p_home_win = sum(n.prob_theory for n in nodes if n.quadrant == 'home_win')
    p_known_home = sum(n.prob_theory for n in nodes
                       if n.quadrant == 'home_win' and f"{n.home_goals}-{n.away_goals}" in known_home_scores)
    p_home_other = max(0.0, p_home_win - p_known_home)

    p_away_win = sum(n.prob_theory for n in nodes if n.quadrant == 'away_win')
    p_known_away = sum(n.prob_theory for n in nodes
                       if n.quadrant == 'away_win' and f"{n.home_goals}-{n.away_goals}" in known_away_scores)
    p_away_other = max(0.0, p_away_win - p_known_away)

    warnings_list = []
    if p_home_other > threshold:
        warnings_list.append(
            f"🚨尾部坍塌预警：主胜其他比分概率达 {p_home_other:.1%}（>阈值{threshold:.0%}），强制熔断小比分高杠杆押注"
        )
    if p_away_other > threshold:
        warnings_list.append(
            f"🚨尾部坍塌预警：客胜其他比分概率达 {p_away_other:.1%}（>阈值{threshold:.0%}），强制熔断小比分高杠杆押注"
        )
    metrics = {
        'p_home_other': round(p_home_other, 4),
        'p_away_other': round(p_away_other, 4),
        'threshold': threshold,
        'circuit_breaker': bool(warnings_list),
    }
    return warnings_list, metrics


def layered_harvesting_detector(score_matrix, ev_variance_threshold=0.5,
                                clean_sheet_threshold=0.55):
    """【模块三·分层收割探测器】

    横向探测：计算同一行（同净胜球）的 EV 分布方差，检测庄家诱盘
    纵向探测：计算同一列（如零封列）的理论概率总和，激活"单边碾压"策略
    """
    import statistics as _stats_local
    warnings_list = []
    metrics = {'rows': {}, 'columns': {}, 'strategies': []}
    if score_matrix is None:
        return warnings_list, metrics
    nodes = score_matrix.get_all_nodes()

    # 横向探测（按净胜球分组）
    for diff in range(-5, 6):
        row_nodes = [n for n in nodes if n.goal_diff == diff and n.ev > -1.0]
        if len(row_nodes) >= 3:
            try:
                ev_var = _stats_local.variance([n.ev for n in row_nodes])
            except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                ev_var = 0.0
            metrics['rows'][diff] = round(ev_var, 4)
            if ev_var > ev_variance_threshold:
                warnings_list.append(
                    f"⚠️分层收割探测·横向：净胜{diff:+d}球EV方差={ev_var:.3f}，警惕庄家EV诱盘"
                )

    # 纵向探测（零封列：away_goals == 0 或 home_goals == 0）
    p_home_clean = sum(n.prob_theory for n in nodes if n.away_goals == 0)
    p_away_clean = sum(n.prob_theory for n in nodes if n.home_goals == 0)
    metrics['columns']['home_clean_sheet'] = round(p_home_clean, 4)
    metrics['columns']['away_clean_sheet'] = round(p_away_clean, 4)
    if p_home_clean >= clean_sheet_threshold:
        warnings_list.append(
            f"⚡单边碾压·主队零封列：理论概率达 {p_home_clean:.1%}，激活单边碾压策略"
        )
        metrics['strategies'].append('home_clean_sheet_dominance')
    if p_away_clean >= clean_sheet_threshold:
        warnings_list.append(
            f"⚡单边碾压·客队零封列：理论概率达 {p_away_clean:.1%}，激活单边碾压策略"
        )
        metrics['strategies'].append('away_clean_sheet_dominance')
    return warnings_list, metrics


# ==========================================================================
# 【信息熵核心升级】ShannonEntropyEngine
# --------------------------------------------------------------------------
# 将全量比分视为离散随机变量的互斥结果，使用 Shannon 信息熵统一驱动：
#   1) 确定性过滤器：H(T) 与归一化熵识别确定态/混沌态；
#   2) 操控强度检测：H(M)-H(T) + 分差组熵减/IBI抬升互相关；
#   3) 波胆权重优化：熵调制 Kelly 变体，低熵时强化双核钻石节点。
# 所有公开方法均有 try/except 降级保护，保持旧调用链兼容。
# ==========================================================================
class ShannonEntropyEngine:
    """比分池 Shannon 信息熵核心引擎（单位：bit）。"""

    EPSILON = 1e-12
    CHAOS_THRESHOLD = 0.88
    CERTAINTY_THRESHOLD = 0.62
    DELTA_H_EPSILON = 0.03
    DEFENSE_COATING_ENTROPY_DROP = 0.03
    DEFENSE_COATING_IBI_RATIO = 1.15

    @classmethod
    def normalize_probabilities(cls, values):
        """将非负权重归一化为概率分布；非法值自动按0处理。"""
        try:
            cleaned = [max(0.0, MathUtils.safe_float(v, 0.0)) for v in (values or [])]
            total = sum(cleaned)
            if total <= cls.EPSILON:
                return [0.0 for _ in cleaned], 0.0
            return [v / total for v in cleaned], total
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            return [], 0.0

    @classmethod
    def calculate_entropy(cls, probabilities):
        """计算 H(X)=-Σp·log2(p)，并返回最大熵与归一化熵。"""
        fallback = {
            'entropy_bits': 0.0,
            'max_entropy_bits': 0.0,
            'normalized_entropy': 0.0,
            'effective_outcomes': 1.0,
            'distribution': [],
        }
        try:
            distribution, _ = cls.normalize_probabilities(probabilities)
            positive = [p for p in distribution if p > cls.EPSILON]
            if not positive:
                return fallback
            entropy_bits = -sum(p * math.log2(p) for p in positive)
            n = len(distribution)
            max_entropy = math.log2(n) if n > 1 else 0.0
            normalized = entropy_bits / max_entropy if max_entropy > cls.EPSILON else 0.0
            return {
                'entropy_bits': round(entropy_bits, 6),
                'max_entropy_bits': round(max_entropy, 6),
                'normalized_entropy': round(max(0.0, min(1.0, normalized)), 6),
                'effective_outcomes': round(2.0 ** entropy_bits, 6),
                'distribution': distribution,
            }
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            return fallback

    @classmethod
    def _state_label(cls, normalized_entropy):
        try:
            value = MathUtils.safe_float(normalized_entropy, 0.0)
            if value >= cls.CHAOS_THRESHOLD:
                return 'CHAOS', '高熵混沌态'
            if value >= 0.78:
                return 'BALANCED', '均衡博弈态'
            if value > cls.CERTAINTY_THRESHOLD:
                return 'DIRECTED', '方向收敛态'
            return 'CERTAIN', '低熵确定态'
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            return 'UNKNOWN', '场态未知'

    @classmethod
    def analyze_state(cls, score_data, min_market_coverage=0.25):
        """计算全池/15池 H(T)、H(M)、ΔH 与确定性过滤器判定。"""
        fallback = {
            'available': False,
            'score_count': 0,
            'h_theory': 0.0,
            'h_market': 0.0,
            'delta_h': 0.0,
            'max_entropy': 0.0,
            'normalized_h_theory': 0.0,
            'normalized_h_market': 0.0,
            'state_code': 'UNKNOWN',
            'state_label': '场态未知',
            'chaos_warning': False,
            'market_valid': False,
            'market_coverage': 0.0,
            'delta_interpretation': '数据不足',
            'theory_distribution': {},
            'market_distribution': {},
        }
        try:
            rows = [row for row in (score_data or []) if isinstance(row, dict) and str(row.get('score', '')).strip()]
            if not rows:
                return fallback

            labels = [str(row.get('score', '')).strip() for row in rows]
            theory_raw = [max(0.0, MathUtils.safe_float(row.get('theory_prob', row.get('theory', 0.0)), 0.0)) for row in rows]
            market_raw = [max(0.0, MathUtils.safe_float(row.get('market_prob', row.get('market', 0.0)), 0.0)) for row in rows]

            theory_dist, theory_total = cls.normalize_probabilities(theory_raw)
            market_dist_real, market_total = cls.normalize_probabilities(market_raw)
            market_coverage = sum(1 for value in market_raw if value > cls.EPSILON) / max(len(market_raw), 1)
            market_valid = bool(market_total > cls.EPSILON and market_coverage >= float(min_market_coverage))
            # 市场波胆缺失时使用理论分布作无偏回退，使主流程可继续，但明确标记无市场证据。
            market_dist = market_dist_real if market_valid else list(theory_dist)

            t_stats = cls.calculate_entropy(theory_dist)
            m_stats = cls.calculate_entropy(market_dist)
            h_theory = MathUtils.safe_float(t_stats.get('entropy_bits'), 0.0)
            h_market = MathUtils.safe_float(m_stats.get('entropy_bits'), h_theory)
            delta_h = h_market - h_theory
            normalized_t = MathUtils.safe_float(t_stats.get('normalized_entropy'), 0.0)
            normalized_m = MathUtils.safe_float(m_stats.get('normalized_entropy'), normalized_t)
            state_code, state_label = cls._state_label(normalized_t)

            if not market_valid:
                delta_interpretation = '市场比分概率不足，H(M)采用理论分布回退，不作操控判定'
            elif delta_h > cls.DELTA_H_EPSILON:
                delta_interpretation = '熵增：市场将理论确定性模糊化，存在诱导分流嫌疑'
            elif delta_h < -cls.DELTA_H_EPSILON:
                delta_interpretation = '熵减：市场分布更集中，存在锁定结果迹象'
            else:
                delta_interpretation = '熵差中性：理论与市场不确定度基本一致'

            return {
                'available': bool(theory_total > cls.EPSILON),
                'score_count': len(labels),
                'h_theory': round(h_theory, 6),
                'h_market': round(h_market, 6),
                'delta_h': round(delta_h, 6),
                'max_entropy': round(MathUtils.safe_float(t_stats.get('max_entropy_bits'), 0.0), 6),
                'normalized_h_theory': round(normalized_t, 6),
                'normalized_h_market': round(normalized_m, 6),
                'effective_outcomes_theory': t_stats.get('effective_outcomes', 1.0),
                'effective_outcomes_market': m_stats.get('effective_outcomes', 1.0),
                'state_code': state_code,
                'state_label': state_label,
                'chaos_warning': bool(normalized_t >= cls.CHAOS_THRESHOLD),
                'certainty_score': round(max(0.0, min(1.0, 1.0 - normalized_t)), 6),
                'market_valid': market_valid,
                'market_coverage': round(market_coverage, 6),
                'delta_interpretation': delta_interpretation,
                'theory_distribution': dict(zip(labels, theory_dist)),
                'market_distribution': dict(zip(labels, market_dist)),
            }
        except Exception as exc:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            fallback['error'] = str(exc)
            return fallback

    @classmethod
    def build_score_metrics(cls, score_data, state=None):
        """为每个比分计算自信息量、熵贡献及无固定比例的动态熵筛选分数。"""
        try:
            rows = [row for row in (score_data or []) if isinstance(row, dict)]
            state = state if isinstance(state, dict) and state.get('available') else cls.analyze_state(rows)
            theory_dist = state.get('theory_distribution', {}) or {}
            market_dist = state.get('market_distribution', {}) or {}
            n = max(int(state.get('score_count', len(rows)) or len(rows)), 1)
            max_info_scale = max(math.log2(n), 1.0)
            norm_t = MathUtils.safe_float(state.get('normalized_h_theory'), 0.0)
            norm_m = MathUtils.safe_float(state.get('normalized_h_market'), norm_t)
            certainty_t = max(0.0, min(1.0, 1.0 - norm_t))
            certainty_m = max(0.0, min(1.0, 1.0 - norm_m))
            market_valid = bool(state.get('market_valid'))
            coverage = MathUtils.safe_float(state.get('market_coverage'), 0.0)

            # 可靠度完全由各自熵值及市场覆盖率决定，替换旧有固定60/40权重。
            theory_reliability = 0.15 + certainty_t ** 1.5
            market_reliability = (0.15 + certainty_m ** 1.5) * (0.50 + 0.50 * coverage) if market_valid else 0.0
            reliability_total = theory_reliability + market_reliability
            if reliability_total <= cls.EPSILON:
                theory_weight, market_weight = 1.0, 0.0
            else:
                theory_weight = theory_reliability / reliability_total
                market_weight = market_reliability / reliability_total

            max_t = max(theory_dist.values()) if theory_dist else 1.0
            max_m = max(market_dist.values()) if market_dist else max_t
            metrics = {}
            for row in rows:
                try:
                    score = str(row.get('score', '')).strip()
                    if not score:
                        continue
                    p_t = max(MathUtils.safe_float(theory_dist.get(score), 0.0), cls.EPSILON)
                    p_m = max(MathUtils.safe_float(market_dist.get(score, p_t), p_t), cls.EPSILON)
                    info_t = -math.log2(p_t)
                    info_m = -math.log2(p_m)
                    contribution_t = -p_t * math.log2(p_t)
                    contribution_m = -p_m * math.log2(p_m)
                    consensus = theory_weight * p_t + market_weight * p_m
                    focus_t = p_t / max(max_t, cls.EPSILON)
                    focus_m = p_m / max(max_m, cls.EPSILON)
                    certainty_boost = 1.0 + certainty_t * focus_t + certainty_m * focus_m
                    agreement = 1.0 - min(1.0, abs(p_t - p_m) / max(p_t, p_m, cls.EPSILON))
                    local_information = theory_weight * info_t + market_weight * info_m
                    information_efficiency = 1.0 / (1.0 + local_information / max_info_scale)
                    entropy_adjusted_score = consensus * certainty_boost * (0.80 + 0.20 * agreement) * (0.90 + 0.20 * information_efficiency)
                    metrics[score] = {
                        'score': score,
                        'theory_share': p_t,
                        'market_share': p_m,
                        'consensus_prob': consensus,
                        'self_information_bits': round(info_t, 6),
                        'market_self_information_bits': round(info_m, 6),
                        'entropy_contribution_bits': round(contribution_t, 6),
                        'market_entropy_contribution_bits': round(contribution_m, 6),
                        'entropy_weight': round(certainty_boost, 6),
                        'entropy_adjusted_score': round(entropy_adjusted_score, 12),
                        'distribution_agreement': round(agreement, 6),
                        'theory_reliability_weight': round(theory_weight, 6),
                        'market_reliability_weight': round(market_weight, 6),
                    }
                except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [异常已捕获·continue降级 L9781] {_silent_err}")
                    continue
            return metrics
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·return empty降级 L9784] {_silent_err}")
            return {}

    @staticmethod
    def _margin_key(score):
        try:
            score = str(score or '').strip()
            if '其它' in score:
                if '胜' in score:
                    return '胜其它'
                if '平' in score:
                    return '平其它'
                return '负其它'
            if '-' not in score:
                return '未知'
            home, away = parse_score(score)
            if home is None or away is None:
                return '未知'
            return f'净胜{abs(home - away)}球'
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·return '未知'降级 L9801] {_silent_err}")
            return '未知'

    @classmethod
    def _pearson(cls, xs, ys):
        try:
            if len(xs) != len(ys) or len(xs) < 3:
                return 0.0
            mean_x = sum(xs) / len(xs)
            mean_y = sum(ys) / len(ys)
            numerator = sum((x - mean_x) * (y - mean_y) for x, y in zip(xs, ys))
            den_x = math.sqrt(sum((x - mean_x) ** 2 for x in xs))
            den_y = math.sqrt(sum((y - mean_y) ** 2 for y in ys))
            if den_x <= cls.EPSILON or den_y <= cls.EPSILON:
                return 0.0
            return max(-1.0, min(1.0, numerator / (den_x * den_y)))
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·return 0.0降级 L9817] {_silent_err}")
            return 0.0

    @classmethod
    def analyze_manipulation_intensity(cls, score_data, state=None):
        """用 ΔH、比分熵贡献与 IBI 的互相关识别分差组“防御涂层”。"""
        fallback = {
            'available': False,
            'ibi_entropy_correlation': 0.0,
            'global_weighted_ibi': 0.0,
            'intensity_score': 0.0,
            'intensity_level': '数据不足',
            'defense_coating_groups': [],
            'groups': [],
        }
        try:
            rows = [row for row in (score_data or []) if isinstance(row, dict)]
            if not rows:
                return fallback
            state = state if isinstance(state, dict) and state.get('available') else cls.analyze_state(rows)
            t_dist = state.get('theory_distribution', {}) or {}
            m_dist = state.get('market_distribution', {}) or {}
            market_valid = bool(state.get('market_valid'))

            weighted_ibi_num = 0.0
            weighted_ibi_den = 0.0
            entropy_compressions = []
            ibi_deviations = []
            groups = {}
            for row in rows:
                try:
                    score = str(row.get('score', '')).strip()
                    p_t = max(MathUtils.safe_float(t_dist.get(score), 0.0), 0.0)
                    p_m = max(MathUtils.safe_float(m_dist.get(score, p_t), p_t), 0.0)
                    ibi = MathUtils.safe_float(row.get('ibi'), 0.0)
                    if ibi <= 0.0:
                        raw_t = MathUtils.safe_float(row.get('theory_prob', row.get('theory', 0.0)), 0.0)
                        raw_m = MathUtils.safe_float(row.get('market_prob', row.get('market', 0.0)), 0.0)
                        ibi = raw_m / raw_t if raw_t > cls.EPSILON else 0.0
                    ibi_clamped = max(0.0, min(10.0, ibi))
                    weighted_ibi_num += ibi_clamped * p_t
                    weighted_ibi_den += p_t
                    t_contrib = -p_t * math.log2(p_t) if p_t > cls.EPSILON else 0.0
                    m_contrib = -p_m * math.log2(p_m) if p_m > cls.EPSILON else 0.0
                    entropy_compressions.append(t_contrib - m_contrib)
                    ibi_deviations.append(ibi_clamped - 1.0)
                    groups.setdefault(cls._margin_key(score), []).append({
                        'score': score,
                        'theory_prob': MathUtils.safe_float(row.get('theory_prob', row.get('theory', 0.0)), 0.0),
                        'market_prob': MathUtils.safe_float(row.get('market_prob', row.get('market', 0.0)), 0.0),
                        'ibi': ibi_clamped,
                    })
                except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [异常已捕获·continue降级 L9869] {_silent_err}")
                    continue

            global_ibi = weighted_ibi_num / weighted_ibi_den if weighted_ibi_den > cls.EPSILON else 1.0
            correlation = cls._pearson(entropy_compressions, ibi_deviations) if market_valid else 0.0
            group_reports = []
            coating_groups = []
            for group_name, group_rows in groups.items():
                try:
                    theory_values = [max(0.0, MathUtils.safe_float(r.get('theory_prob'), 0.0)) for r in group_rows]
                    market_values = [max(0.0, MathUtils.safe_float(r.get('market_prob'), 0.0)) for r in group_rows]
                    t_stats = cls.calculate_entropy(theory_values)
                    if market_valid and sum(market_values) > cls.EPSILON:
                        m_stats = cls.calculate_entropy(market_values)
                    else:
                        m_stats = t_stats
                    h_t_group = MathUtils.safe_float(t_stats.get('entropy_bits'), 0.0)
                    h_m_group = MathUtils.safe_float(m_stats.get('entropy_bits'), h_t_group)
                    entropy_drop = h_t_group - h_m_group
                    weights, _ = cls.normalize_probabilities(theory_values)
                    avg_ibi = sum(r.get('ibi', 0.0) * w for r, w in zip(group_rows, weights)) if weights else 0.0
                    ibi_lift = avg_ibi - global_ibi
                    coating = bool(
                        market_valid
                        and len(group_rows) >= 2
                        and entropy_drop >= cls.DEFENSE_COATING_ENTROPY_DROP
                        and avg_ibi >= max(1.15, global_ibi * cls.DEFENSE_COATING_IBI_RATIO)
                    )
                    group_item = {
                        'group': group_name,
                        'scores': [r.get('score', '') for r in group_rows],
                        'h_theory': round(h_t_group, 6),
                        'h_market': round(h_m_group, 6),
                        'entropy_drop': round(entropy_drop, 6),
                        'avg_ibi': round(avg_ibi, 6),
                        'ibi_lift': round(ibi_lift, 6),
                        'defense_coating': coating,
                    }
                    group_reports.append(group_item)
                    if coating:
                        coating_groups.append(group_item)
                except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [异常已捕获·continue降级 L9910] {_silent_err}")
                    continue

            delta_h = abs(MathUtils.safe_float(state.get('delta_h'), 0.0))
            max_entropy = max(MathUtils.safe_float(state.get('max_entropy'), 1.0), 1.0)
            coating_component = min(1.0, len(coating_groups) / 3.0)
            intensity_score = min(1.0, (delta_h / max_entropy) * 2.5 + abs(correlation) * 0.35 + coating_component * 0.45)
            if not market_valid:
                intensity_level = '市场数据不足'
            elif intensity_score >= 0.65:
                intensity_level = '强操控'
            elif intensity_score >= 0.35:
                intensity_level = '中等操控'
            else:
                intensity_level = '低操控'

            coating_groups.sort(key=lambda x: (x.get('entropy_drop', 0.0), x.get('avg_ibi', 0.0)), reverse=True)
            group_reports.sort(key=lambda x: x.get('entropy_drop', 0.0), reverse=True)
            return {
                'available': bool(market_valid),
                'ibi_entropy_correlation': round(correlation, 6),
                'global_weighted_ibi': round(global_ibi, 6),
                'intensity_score': round(intensity_score, 6),
                'intensity_level': intensity_level,
                'defense_coating_groups': coating_groups,
                'groups': group_reports,
            }
        except Exception as exc:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            fallback['error'] = str(exc)
            return fallback

    @classmethod
    def allocate_deviation_driven(cls, score_data, total_budget=1.0):
        """V-Entropy 资金兼容层：只使用 deviation 与 IBI 执行双轨分配。"""
        fallback = {
            'available': False,
            'allocations': [],
            'tier_1_allocations': [],
            'tier_2_allocations': [],
            'unknown_count': 0,
            'total_budget': 0.0,
            'allocated_total': 0.0,
            'allocation_method': 'deviation_driven_dual_track',
        }
        try:
            budget = max(0.0, float(total_budget or 0.0))
            ratio_data = []
            for row in score_data or []:
                try:
                    if not isinstance(row, dict):
                        continue
                    option = str(row.get('option') or row.get('score') or row.get('selection') or '').strip()
                    if not option:
                        continue
                    theory = MathUtils.safe_float(row.get('theory_prob', row.get('theory', 0.0)), 0.0)
                    market = MathUtils.safe_float(row.get('market_prob', row.get('market', 0.0)), 0.0)
                    ibi = MathUtils.safe_float(row.get('ibi', 0.0), 0.0)
                    if ibi == 0.0 and theory > 0.0 and market >= 0.0:
                        ibi = market / theory

                    explicit_deviation = row.get('deviation')
                    if explicit_deviation is not None and str(explicit_deviation).strip() != '':
                        deviation = MathUtils.safe_float(explicit_deviation, 0.0)
                    elif row.get('delta_pct') is not None and str(row.get('delta_pct')).strip() != '':
                        deviation = MathUtils.safe_float(row.get('delta_pct'), 0.0)
                    elif row.get('delta') is not None and str(row.get('delta')).strip() != '':
                        delta = MathUtils.safe_float(row.get('delta'), 0.0)
                        deviation = delta * (10000.0 if abs(delta) <= 1.0 else 100.0)
                    elif abs(theory) <= 1.0 and abs(market) <= 1.0:
                        deviation = (market - theory) * 10000.0
                    else:
                        deviation = (market - theory) * 100.0

                    ratio_data.append({
                        'option': option,
                        'deviation': round(deviation, 8),
                        'ibi': round(ibi, 8),
                        'source': 'V-Entropy15池',
                    })
                except Exception as row_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [V-Entropy偏差分配] 单项提取异常(已跳过): {row_error}")

            result = DeviationDrivenEngine.evaluate_records(ratio_data, total_budget=budget)
            allocations = list(result.get('allocations', []) or [])
            for item in allocations:
                try:
                    item['allocation_weight'] = round(float(item.get('bet_amount', 0.0) or 0.0), 8)
                    item['allocation_pct'] = round(float(item.get('bet_amount', 0.0) or 0.0) * 100.0, 4)
                except Exception as item_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [V-Entropy偏差分配] 权重字段回填异常(已保留金额): {item_error}")

            return {
                'available': bool(allocations),
                'allocations': allocations,
                'tier_1_allocations': [item for item in allocations if item.get('tier') == 'TIER_1_KILL'],
                'tier_2_allocations': [item for item in allocations if item.get('tier') == 'TIER_2_DEFENSE'],
                'unknown_count': int(result.get('unknown_count', 0) or 0),
                'total_budget': budget,
                'allocated_total': round(sum(float(item.get('bet_amount', 0.0) or 0.0) for item in allocations), 8),
                'total_exposure': round(sum(float(item.get('bet_amount', 0.0) or 0.0) for item in allocations), 8),
                'allocation_method': 'deviation_driven_dual_track',
            }
        except Exception as allocation_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            fallback['error'] = str(allocation_error)
            print(f"   ⚠️ [V-Entropy偏差分配] 执行异常(已降级为空): {allocation_error}")
            return fallback

    @classmethod
    def allocate_entropy_kelly(cls, score_data, state=None, score_metrics=None,
                               risk_aversion=VENTROPY_RISK_AVERSION):
        """兼容旧调用名；旧 Kelly 决策已删除，仅委托偏差双轨分配。"""
        try:
            return cls.allocate_deviation_driven(score_data, total_budget=1.0)
        except Exception as compatibility_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [V-Entropy偏差分配兼容入口] 异常(已降级为空): {compatibility_error}")
            return {
                'available': False,
                'allocations': [],
                'tier_1_allocations': [],
                'tier_2_allocations': [],
                'unknown_count': 0,
                'total_budget': 1.0,
                'allocated_total': 0.0,
                'allocation_method': 'deviation_driven_dual_track',
                'error': str(compatibility_error),
            }

    @classmethod
    def compact_summary(cls, state):
        """生成可安全透传/持久化的熵上下文，剔除大体积分布字典。"""
        try:
            if not isinstance(state, dict):
                return {}
            keys = (
                'available', 'score_count', 'h_theory', 'h_market', 'delta_h',
                'max_entropy', 'normalized_h_theory', 'normalized_h_market',
                'effective_outcomes_theory', 'effective_outcomes_market',
                'state_code', 'state_label', 'chaos_warning', 'certainty_score',
                'market_valid', 'market_coverage', 'delta_interpretation',
            )
            summary = {key: state.get(key) for key in keys if key in state}
            if isinstance(state.get('manipulation'), dict):
                manipulation = state.get('manipulation', {})
                summary['manipulation'] = {
                    'available': manipulation.get('available', False),
                    'ibi_entropy_correlation': manipulation.get('ibi_entropy_correlation', 0.0),
                    'global_weighted_ibi': manipulation.get('global_weighted_ibi', 0.0),
                    'intensity_score': manipulation.get('intensity_score', 0.0),
                    'intensity_level': manipulation.get('intensity_level', '数据不足'),
                    'defense_coating_groups': manipulation.get('defense_coating_groups', []),
                }
            try:
                deviation_allocation = state.get('deviation_allocation', {})
                if isinstance(deviation_allocation, dict):
                    summary['deviation_allocation'] = deviation_allocation
            except Exception as allocation_summary_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                summary['deviation_allocation'] = {
                    'available': False,
                    'allocations': [],
                    'error': str(allocation_summary_error),
                }
            return summary
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·return empty降级 L10072] {_silent_err}")
            return {}

    @classmethod
    def format_tg_report(cls, state):
        """信息熵只作场态描述；终裁与资金仅展示DeviationDrivenEngine结果。"""
        try:
            state = state if isinstance(state, dict) else {}
            h_t = MathUtils.safe_float(state.get('h_theory'), 0.0)
            h_m = MathUtils.safe_float(state.get('h_market'), h_t)
            delta_h = MathUtils.safe_float(state.get('delta_h'), 0.0)
            max_h = MathUtils.safe_float(state.get('max_entropy'), 0.0)
            norm_t = MathUtils.safe_float(state.get('normalized_h_theory'), 0.0)
            norm_m = MathUtils.safe_float(state.get('normalized_h_market'), norm_t)
            lines = [
                '📐【信息熵场态分析】',
                '━━━━━━━━━━━━━━━━━━━━',
                '说明：熵指标仅作描述，不参与比分筛选、资金分配或否决。',
                f'━ 理论信息熵 H(T): {h_t:.4f} bit / Hmax={max_h:.4f}（归一化{norm_t:.1%}）',
                f'━ 市场信息熵 H(M): {h_m:.4f} bit（归一化{norm_m:.1%}）',
                f'━ 熵差 ΔH=H(M)-H(T): {delta_h:+.4f} bit',
            ]
            allocation = state.get('deviation_allocation', {}) if isinstance(state.get('deviation_allocation'), dict) else {}
            tier_1 = allocation.get('tier_1_allocations', []) or []
            tier_2 = allocation.get('tier_2_allocations', []) or []
            lines.append('━ 【偏差唯一终裁】')
            lines.append(
                f'  Tier 1={len(tier_1)} | Tier 2={len(tier_2)} | '
                f'UNKNOWN排除={int(allocation.get("unknown_count", 0) or 0)}'
            )
            allocations = allocation.get('allocations', []) or []
            if allocations:
                for item in allocations[:5]:
                    lines.append(
                        f'  • {item.get("option", "-")} | {item.get("tier", "UNKNOWN")} | '
                        f'Dev={MathUtils.safe_float(item.get("deviation"), 0.0):+.2f}% | '
                        f'IBI={MathUtils.safe_float(item.get("ibi"), 0.0):.4f} | '
                        f'权重={MathUtils.safe_float(item.get("allocation_pct"), 0.0):.2f}%'
                    )
            else:
                lines.append('  • 无有效Tier；不生成熵驱动替代结论。')
            lines.append('━━━━━━━━━━━━━━━━━━━━')
            return '\n'.join(lines)
        except Exception as report_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            return f'📐【信息熵场态分析】\n━ 报告异常，已停止旧熵决策：{report_error}'



# ---------------- V-Entropy 分层量化核心 ----------------

class PredictionSystemShutdown(RuntimeError):
    """混沌熔断专用异常：只拒绝当前场预测，不中断整批任务。"""

    def __init__(self, message, payload=None):
        super().__init__(message)
        self.payload = payload or {}


# 【现代化重构】旧 VEntropyQuantEngine 类已删除。其硬编码规则树、分层泊松
# 内核与手动调参逻辑由 CoreQuantEngine（文件前部定义）的双变量泊松概率矩阵
# + Deviation/IBI 双轨分级裁决统一替代。原类中仍被下游依赖、且不属于痛点
# 的独立模块（贝叶斯攻防后验自进化、动态λ乘积、Shannon熵、静态诱导检测、
# 3σ混沌熔断）迁移至 AdvancedGameModel（继承 CoreQuantEngine）予以保留。


class AdvancedGameModel(CoreQuantEngine):
    """基于 CoreQuantEngine 双变量泊松基座的高级模型。

    保留模块：肥尾蒙特卡洛、熵差操控检测、3σ混沌熔断、贝叶斯攻防参数
    自进化、动态λ乘积与静态诱导检测。概率矩阵统一由
    ``CoreQuantEngine.calculate_bivariate_poisson`` 生成（15池概率基座），
    旧分层泊松 get_poisson_probability 与代数反推λ逻辑已废弃。
    """

    DEFAULT_STRENGTH = 1.0
    MIN_STRENGTH = 0.25
    MAX_STRENGTH = 4.0
    LEAGUE_GOAL_BASELINE = 1.35

    def __init__(self, risk_aversion=VENTROPY_RISK_AVERSION, max_goals=8,
                 parameter_file=VENTROPY_PARAM_FILE, random_seed=None):
        super().__init__(max_goals=max(2, int(max_goals)))
        self.risk_aversion = max(0.0, min(1.0, float(risk_aversion)))
        self.random_seed = random_seed
        self.parameter_file = str(parameter_file or VENTROPY_PARAM_FILE)
        self.parameter_state = self._load_parameter_state()
        # 静态诱导检测统一读取系统既有攻防后验参数，不维护第二套球队能力数据。
        try:
            self.params = {}
            self._refresh_ability_params()
            self.last_static_manipulation = {
                'available': False,
                'score': 0.0,
                'reason': 'not_evaluated',
            }
        except Exception as _static_param_init_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            self.params = {}
            self.last_static_manipulation = {
                'available': False,
                'score': 0.0,
                'reason': f'ability_param_init_failed:{_static_param_init_err}',
            }

    def build_score_probability_matrix(self, home_lambda, away_lambda, max_goals=None,
                                       hierarchy=None):
        """【兼容入口】统一委托 CoreQuantEngine 双变量泊松生成概率矩阵。

        旧分层泊松混合内核已删除；``hierarchy`` 参数仅为签名兼容保留，
        不再参与计算。
        """
        limit = max(2, int(max_goals or self.max_goals))
        original_limit = self.max_goals
        try:
            self.max_goals = limit
            return self.calculate_bivariate_poisson(home_lambda, away_lambda)
        finally:
            self.max_goals = original_limit

    def calculate_entropy(self, probabilities, normalize=False):
        """计算 Shannon 信息熵；``normalize=True`` 时返回 [0, 1] 归一化熵。"""
        normalized = MathUtils.normalize_probabilities(probabilities)
        if not normalized:
            return 0.0
        entropy = -sum(probability * math.log2(probability) for probability in normalized)
        if normalize and len(normalized) > 1:
            entropy /= math.log2(len(normalized))
        return float(entropy)

    def _load_parameter_state(self):
        default = {'version': 1, 'updated_at': '', 'teams': {}}
        with VENTROPY_PARAM_LOCK:
            try:
                if os.path.exists(self.parameter_file):
                    with open(self.parameter_file, 'r', encoding='utf-8') as handle:
                        state = json.load(handle)
                    if isinstance(state, dict):
                        state.setdefault('version', 1)
                        state.setdefault('updated_at', '')
                        state.setdefault('teams', {})
                        if isinstance(state['teams'], dict):
                            return state
            except Exception as exc:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                print(f'   ⚠️ [CoreQuant参数] 读取失败，使用中性先验: {exc}')
        return default

    def _save_parameter_state(self):
        with VENTROPY_PARAM_LOCK:
            directory = os.path.dirname(self.parameter_file)
            if directory:
                os.makedirs(directory, exist_ok=True)
            self.parameter_state['updated_at'] = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            temp_file = f'{self.parameter_file}.tmp'
            with open(temp_file, 'w', encoding='utf-8') as handle:
                json.dump(self.parameter_state, handle, ensure_ascii=False, indent=2,
                          cls=SafeJSONEncoder)
            os.replace(temp_file, self.parameter_file)

    def get_team_parameters(self, team_name):
        """返回球队可变攻强/防弱参数；无历史时使用中性先验。"""
        key = str(team_name or '').strip() or 'UNKNOWN_TEAM'
        team = self.parameter_state.setdefault('teams', {}).setdefault(key, {})
        return {
            'attack_strength': max(self.MIN_STRENGTH, min(
                self.MAX_STRENGTH,
                MathUtils.safe_float(team.get('attack_strength'), self.DEFAULT_STRENGTH)
            )),
            'defense_strength': max(self.MIN_STRENGTH, min(
                self.MAX_STRENGTH,
                MathUtils.safe_float(team.get('defense_strength'), self.DEFAULT_STRENGTH)
            )),
            'matches': max(0, int(MathUtils.safe_float(team.get('matches'), 0))),
            'last_updated': str(team.get('last_updated', '') or ''),
        }

    def _team_ability_logit(self, team_id):
        """将既有攻强/防弱后验压缩为 Bradley-Terry 对数能力参数。"""
        try:
            team_state = self.get_team_parameters(team_id)
            attack_strength = max(
                self.MIN_STRENGTH,
                MathUtils.safe_float(team_state.get('attack_strength'), self.DEFAULT_STRENGTH),
            )
            # 本系统 defense_strength 作为对手进球乘数，值越高代表防线越弱。
            defense_weakness = max(
                self.MIN_STRENGTH,
                MathUtils.safe_float(team_state.get('defense_strength'), self.DEFAULT_STRENGTH),
            )
            composite_ability = max(1e-8, attack_strength / defense_weakness)
            return float(np.log(composite_ability))
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·return 0.0降级 L10281] {_silent_err}")
            return 0.0

    def _refresh_ability_params(self):
        """刷新 ``self.params``，其唯一来源为已有球队攻防能力参数。"""
        try:
            refreshed = {}
            team_keys = list((self.parameter_state.get('teams', {}) or {}).keys())
            for team_id in team_keys:
                try:
                    refreshed[str(team_id)] = self._team_ability_logit(team_id)
                except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    refreshed[str(team_id)] = 0.0
            self.params = refreshed
            return dict(self.params)
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            self.params = getattr(self, 'params', {}) if isinstance(getattr(self, 'params', {}), dict) else {}
            return dict(self.params)

    def _resolve_ability_param(self, team_id):
        """按需从攻防后验解析球队能力参数，缺失球队使用中性先验。"""
        try:
            team_key = (str(team_id).strip() if team_id is not None else '') or 'UNKNOWN_TEAM'
            if not isinstance(getattr(self, 'params', None), dict):
                self.params = {}
            if team_key not in self.params:
                self.params[team_key] = self._team_ability_logit(team_key)
            return float(self.params.get(team_key, 0.0) or 0.0)
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·return 0.0降级 L10309] {_silent_err}")
            return 0.0

    def static_manipulation_score(self, home_id, away_id, market_odds):
        """比较球队能力模型概率与主胜市场赔率隐含概率，返回静态诱导偏离度。"""
        try:
            home_key = (str(home_id).strip() if home_id is not None else '') or 'UNKNOWN_HOME'
            away_key = (str(away_id).strip() if away_id is not None else '') or 'UNKNOWN_AWAY'
            decimal_odds = float(market_odds)
            if not math.isfinite(decimal_odds) or decimal_odds <= 1.0:
                raise ValueError('market_odds_must_be_decimal_and_greater_than_one')

            # 严格复用系统攻防后验生成 self.params，不引入独立静态能力表。
            self.params[home_key] = self._resolve_ability_param(home_key)
            self.params[away_key] = self._resolve_ability_param(away_key)
            home_exp = np.exp(np.clip(self.params[home_key], -50.0, 50.0))
            away_exp = np.exp(np.clip(self.params[away_key], -50.0, 50.0))
            denominator = float(home_exp + away_exp)
            if denominator <= 0.0 or not math.isfinite(denominator):
                raise ValueError('invalid_ability_denominator')

            p_model = float(home_exp / denominator)
            p_market = float(1.0 / decimal_odds)
            deviation = float(abs(p_model - p_market))
            self.last_static_manipulation = {
                'available': True,
                'score': deviation,
                'p_model': p_model,
                'p_market': p_market,
                'market_odds': decimal_odds,
                'home_id': home_key,
                'away_id': away_key,
                'home_param': float(self.params[home_key]),
                'away_param': float(self.params[away_key]),
                'parameter_source': 'ventropy_attack_defense_posterior',
                'reason': 'ok',
            }
            return deviation
        except Exception as _static_manipulation_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            try:
                self.last_static_manipulation = {
                    'available': False,
                    'score': 0.0,
                    'home_id': str(home_id) if home_id is not None else '',
                    'away_id': str(away_id) if away_id is not None else '',
                    'market_odds': MathUtils.safe_float(market_odds, 0.0),
                    'reason': f'static_manipulation_failed:{_static_manipulation_err}',
                }
            except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                print(f"   ⚠️ [异常已捕获·pass降级 L10357] {_silent_err}")
            return 0.0

    @classmethod
    def _feature_strength(cls, value, default=1.0):
        """将近期场均进球/失球映射为有界乘数。"""
        try:
            if value is None:
                return float(default)
            ratio = float(value) / cls.LEAGUE_GOAL_BASELINE
            return max(0.55, min(1.80, ratio))
        except (TypeError, ValueError):
            return float(default)

    def calculate_dynamic_lambdas(self, home_team, away_team, base_home_lambda,
                                  base_away_lambda, feature_vector=None):
        """用 ``team_att × opponent_def`` 动态乘积生成主客 λ。"""
        feature_vector = feature_vector or {}
        base_home = MathUtils.safe_float(base_home_lambda)
        base_away = MathUtils.safe_float(base_away_lambda)
        if base_home is None or base_away is None or base_home <= 0 or base_away <= 0:
            return {
                'home_lambda': None,
                'away_lambda': None,
                'reason': '缺少进球期望，不补默认λ',
            }
        base_home = max(0.05, base_home)
        base_away = max(0.05, base_away)
        home_state = self.get_team_parameters(home_team)
        away_state = self.get_team_parameters(away_team)

        home_form_attack = self._feature_strength(feature_vector.get('home_form_avg_goals_for'))
        away_form_attack = self._feature_strength(feature_vector.get('away_form_avg_goals_for'))
        home_form_defense = self._feature_strength(feature_vector.get('home_form_avg_goals_against'))
        away_form_defense = self._feature_strength(feature_vector.get('away_form_avg_goals_against'))

        # 几何融合可避免近期小样本与长期后验任一方单独支配 λ。
        home_attack_factor = math.sqrt(home_state['attack_strength'] * home_form_attack)
        away_attack_factor = math.sqrt(away_state['attack_strength'] * away_form_attack)
        home_defense_factor = math.sqrt(home_state['defense_strength'] * home_form_defense)
        away_defense_factor = math.sqrt(away_state['defense_strength'] * away_form_defense)

        home_team_att = math.sqrt(base_home) * home_attack_factor
        away_opponent_def = math.sqrt(base_home) * away_defense_factor
        away_team_att = math.sqrt(base_away) * away_attack_factor
        home_opponent_def = math.sqrt(base_away) * home_defense_factor
        home_lambda = max(0.05, min(6.0, home_team_att * away_opponent_def))
        away_lambda = max(0.05, min(6.0, away_team_att * home_opponent_def))
        return {
            'home_lambda': home_lambda,
            'away_lambda': away_lambda,
            'home_team_att': home_team_att,
            'away_opponent_def': away_opponent_def,
            'away_team_att': away_team_att,
            'home_opponent_def': home_opponent_def,
            'home_attack_strength': home_state['attack_strength'],
            'away_attack_strength': away_state['attack_strength'],
            'home_defense_strength': home_state['defense_strength'],
            'away_defense_strength': away_state['defense_strength'],
            'home_form_attack_factor': home_form_attack,
            'away_form_attack_factor': away_form_attack,
            'home_form_defense_factor': home_form_defense,
            'away_form_defense_factor': away_form_defense,
        }

    def bayesian_update_attack_strength(self, home_team, away_team, home_goals,
                                        away_goals, base_home_lambda=None,
                                        base_away_lambda=None):
        """赛后以 Poisson 似然 + 对数正态先验执行攻防参数后验估计。"""
        try:
            home_goals = max(0, int(home_goals))
            away_goals = max(0, int(away_goals))
        except (TypeError, ValueError):
            return {'updated': False, 'reason': 'invalid_actual_score'}
        home_name = str(home_team or '').strip()
        away_name = str(away_team or '').strip()
        if not home_name or not away_name:
            return {'updated': False, 'reason': 'missing_team_name'}

        if MathUtils.safe_float(base_home_lambda) is None or MathUtils.safe_float(base_away_lambda) is None:
            return {'updated': False, 'reason': '缺少进球期望，不补默认λ'}
        home_state = self.get_team_parameters(home_name)
        away_state = self.get_team_parameters(away_name)
        prior_strengths = np.array([
            home_state['attack_strength'], away_state['attack_strength'],
            home_state['defense_strength'], away_state['defense_strength'],
        ], dtype=float)
        prior_logs = np.log(np.clip(prior_strengths, self.MIN_STRENGTH, self.MAX_STRENGTH))
        base_home = max(0.05, coerce_float(base_home_lambda))
        base_away = max(0.05, coerce_float(base_away_lambda))
        prior_sigma = 0.35

        def negative_log_posterior(log_params):
            strengths = np.exp(np.asarray(log_params, dtype=float))
            home_attack, away_attack, home_defense, away_defense = strengths
            expected_home = max(1e-8, base_home * home_attack * away_defense)
            expected_away = max(1e-8, base_away * away_attack * home_defense)
            poisson_nll = (
                expected_home - home_goals * math.log(expected_home) + math.lgamma(home_goals + 1)
                + expected_away - away_goals * math.log(expected_away) + math.lgamma(away_goals + 1)
            )
            prior_penalty = float(np.sum((np.asarray(log_params) - prior_logs) ** 2) /
                                  (2.0 * prior_sigma ** 2))
            return poisson_nll + prior_penalty

        bounds = [(math.log(self.MIN_STRENGTH), math.log(self.MAX_STRENGTH))] * 4
        result = minimize(negative_log_posterior, prior_logs, method='L-BFGS-B', bounds=bounds)
        if not result.success or not np.all(np.isfinite(result.x)):
            return {'updated': False, 'reason': f'optimizer_failed:{result.message}'}
        posterior = np.exp(result.x)
        now = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        teams = self.parameter_state.setdefault('teams', {})
        teams[home_name] = {
            'attack_strength': round(float(posterior[0]), 8),
            'defense_strength': round(float(posterior[2]), 8),
            'matches': home_state['matches'] + 1,
            'last_updated': now,
        }
        teams[away_name] = {
            'attack_strength': round(float(posterior[1]), 8),
            'defense_strength': round(float(posterior[3]), 8),
            'matches': away_state['matches'] + 1,
            'last_updated': now,
        }
        self._save_parameter_state()
        try:
            self._refresh_ability_params()
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L10475] {_silent_err}")
        return {
            'updated': True,
            'home_team': home_name,
            'away_team': away_name,
            'home_attack_strength': round(float(posterior[0]), 6),
            'away_attack_strength': round(float(posterior[1]), 6),
            'home_defense_strength': round(float(posterior[2]), 6),
            'away_defense_strength': round(float(posterior[3]), 6),
            'optimizer_iterations': int(getattr(result, 'nit', 0) or 0),
            'posterior_loss': round(float(result.fun), 8),
        }



    def simulate_game(self, home_lambda, away_lambda, simulations=VENTROPY_MONTE_CARLO_SIMS,
                      max_goals=None, tail_shape=7.0, random_seed=None):
        """执行至少 10000 次 Gamma-Poisson 混合模拟以覆盖肥尾比分。"""
        simulations = max(10000, int(simulations or VENTROPY_MONTE_CARLO_SIMS))
        limit = max(2, int(max_goals or self.max_goals))
        home_lambda = MathUtils.safe_float(home_lambda)
        away_lambda = MathUtils.safe_float(away_lambda)
        if home_lambda is None or away_lambda is None or home_lambda <= 0 or away_lambda <= 0:
            return {
                'score_probabilities': {},
                'simulations': 0,
                'retained_simulations': 0,
                'overflow_count': 0,
                'overflow_rate': 0.0,
                'home_mean': None,
                'away_mean': None,
                'reason': '缺少进球期望，不补默认λ',
            }
        home_lambda = max(0.01, home_lambda)
        away_lambda = max(0.01, away_lambda)
        tail_shape = max(1.0, MathUtils.safe_float(tail_shape, 7.0))
        seed = self.random_seed if random_seed is None else random_seed
        rng = np.random.default_rng(seed)

        # 共享节奏项制造相关性，Gamma-Poisson 混合令方差高于均值以承接肥尾。
        tempo_sigma = 0.22
        tempo = rng.lognormal(mean=-0.5 * tempo_sigma ** 2, sigma=tempo_sigma,
                              size=simulations)
        home_latent = rng.gamma(shape=tail_shape, scale=home_lambda / tail_shape,
                                size=simulations) * tempo
        away_latent = rng.gamma(shape=tail_shape, scale=away_lambda / tail_shape,
                                size=simulations) * tempo
        home_goals = rng.poisson(home_latent)
        away_goals = rng.poisson(away_latent)

        score_counts = {}
        overflow_count = 0
        for home_goal, away_goal in zip(home_goals, away_goals):
            home_goal = int(home_goal)
            away_goal = int(away_goal)
            if home_goal >= limit or away_goal >= limit:
                overflow_count += 1
                continue
            score = f'{home_goal}-{away_goal}'
            score_counts[score] = score_counts.get(score, 0) + 1
        retained = sum(score_counts.values())
        score_probabilities = {
            score: count / retained for score, count in score_counts.items()
        } if retained > 0 else self.build_score_probability_matrix(
            home_lambda, away_lambda, max_goals=limit
        )
        return {
            'score_probabilities': score_probabilities,
            'simulations': simulations,
            'retained_simulations': retained,
            'overflow_count': overflow_count,
            'overflow_rate': round(overflow_count / simulations, 8),
            'home_mean': round(float(np.mean(home_goals)), 6),
            'away_mean': round(float(np.mean(away_goals)), 6),
            'home_variance': round(float(np.var(home_goals)), 6),
            'away_variance': round(float(np.var(away_goals)), 6),
            'entropy': round(self.calculate_entropy(score_probabilities), 8),
            'model': 'gamma_poisson_heavy_tail_monte_carlo',
        }

    @staticmethod
    def load_entropy_history(history_file=HISTORY_FILE, limit=200):
        values = []
        try:
            history = load_json(history_file)
            for record in (history or {}).values():
                if not isinstance(record, dict):
                    continue
                quant = record.get('ventropy_quant', {}) or {}
                manipulation = quant.get('manipulation', {}) if isinstance(quant, dict) else {}
                value = manipulation.get('entropy_delta') if isinstance(manipulation, dict) else None
                if value is None:
                    value = record.get('ventropy_entropy_delta')
                try:
                    value = coerce_float(value)
                except (TypeError, ValueError):
                    continue
                if math.isfinite(value):
                    values.append(value)
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·return empty降级 L10568] {_silent_err}")
            return []
        return values[-max(1, int(limit)):]

    def detect_manipulation(self, theory_probabilities, market_probabilities,
                            entropy_history=None,
                            warning_threshold=VENTROPY_ENTROPY_WARNING):
        """以市场熵增检测修饰痕迹，并对历史熵差 3σ 异常执行系统熔断。"""
        theory_entropy = self.calculate_entropy(theory_probabilities)
        market_entropy = self.calculate_entropy(market_probabilities)
        entropy_delta = market_entropy - theory_entropy
        history = []
        for value in (entropy_history or []):
            try:
                number = float(value)
            except (TypeError, ValueError):
                continue
            if math.isfinite(number):
                history.append(number)
        history_mean = float(np.mean(history)) if history else 0.0
        history_std = float(np.std(history, ddof=1)) if len(history) >= 2 else 0.0
        deviation = abs(entropy_delta - history_mean) if history else 0.0
        z_score = deviation / history_std if history_std > 1e-12 else 0.0
        system_shutdown = bool(len(history) >= 5 and history_std > 1e-12 and
                               deviation > 3.0 * history_std)
        warning = bool(entropy_delta > float(warning_threshold))
        instruction = 'SYSTEM_SHUTDOWN' if system_shutdown else ('WARNING' if warning else 'NORMAL')
        return {
            'theory_entropy': round(theory_entropy, 8),
            'market_entropy': round(market_entropy, 8),
            'entropy_delta': round(entropy_delta, 8),
            'warning_threshold': float(warning_threshold),
            'warning': warning,
            'history_count': len(history),
            'history_mean': round(history_mean, 8),
            'history_std': round(history_std, 8),
            'deviation': round(deviation, 8),
            'z_score': round(z_score, 6),
            'system_shutdown': system_shutdown,
            'instruction': instruction,
            'reason': (
                'entropy_volatility_exceeds_3sigma' if system_shutdown
                else ('market_entropy_increase_exceeds_0.5' if warning else 'within_entropy_limits')
            ),
        }


def update_ventropy_parameters_from_result(match_record, actual_score=None):
    """从已完赛记录提取队名和赛果，幂等触发攻防参数的贝叶斯后验更新。"""
    if not isinstance(match_record, dict):
        return {'updated': False, 'reason': 'invalid_match_record'}
    score_text = str(actual_score or match_record.get('actual_score', '') or '')
    score_text = score_text.replace(' (进行中)', '').replace(':', '-').strip()
    if not score_text or '其它' in score_text:
        return {'updated': False, 'reason': 'missing_or_virtual_actual_score'}
    parsed = re.match(r'^\s*(\d+)\s*-\s*(\d+)\s*$', score_text)
    if not parsed:
        return {'updated': False, 'reason': 'invalid_actual_score'}
    home_goals, away_goals = int(parsed.group(1)), int(parsed.group(2))

    previous = match_record.get('ventropy_bayesian_update', {}) or {}
    if isinstance(previous, dict) and previous.get('updated') and previous.get('actual_score') == score_text:
        return previous

    home_team = str(match_record.get('home_team', '') or '').strip()
    away_team = str(match_record.get('away_team', '') or '').strip()
    if not home_team or not away_team:
        match_name = str(match_record.get('match', match_record.get('match_name', '')) or '').strip()
        parts = re.split(r'\s+(?:vs\.?|v)\s+', match_name, maxsplit=1, flags=re.IGNORECASE)
        if len(parts) != 2 and ' - ' in match_name:
            parts = match_name.split(' - ', 1)
        if len(parts) == 2:
            home_team = home_team or parts[0].strip()
            away_team = away_team or parts[1].strip()
    if not home_team or not away_team:
        return {'updated': False, 'reason': 'unable_to_parse_team_names'}

    dynamic_meta = match_record.get('ventropy_dynamic_lambda', {}) or {}
    base_home = dynamic_meta.get('base_home_lambda', match_record.get('lam_h'))
    base_away = dynamic_meta.get('base_away_lambda', match_record.get('lam_a'))
    engine = AdvancedGameModel()
    result = engine.bayesian_update_attack_strength(
        home_team,
        away_team,
        home_goals,
        away_goals,
        base_home_lambda=base_home,
        base_away_lambda=base_away,
    )
    result['actual_score'] = score_text
    result['updated_at'] = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    return result




# ---------------- 三重数学防火墙闭环核心 ----------------

class AdvancedBayesianEngine(AdvancedGameModel):
    """复用V-Entropy攻防后验的动态贝叶斯校准层。"""

    def __init__(self, n_teams=0, *args, **kwargs):
        try:
            super().__init__(*args, **kwargs)
            self.n_teams = max(0, int(n_teams or 0))
            self.last_parameter_updates = []
            self.last_xg_integrations = []
        except Exception as init_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [贝叶斯校准层] 初始化异常(保留安全空状态): {init_error}")
            self.n_teams = 0
            self.last_parameter_updates = []
            self.last_xg_integrations = []

    @staticmethod
    def _safe_probability(value, default=0.0):
        try:
            probability = float(value)
            if 1.0 < probability <= 100.0:
                probability /= 100.0
            if not math.isfinite(probability):
                return float(default)
            return min(1.0, max(0.0, probability))
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            return float(default)

    @staticmethod
    def _extract_team_names(match):
        try:
            home_team = str(match.get('home_team', '') or '').strip()
            away_team = str(match.get('away_team', '') or '').strip()
            if home_team and away_team:
                return home_team, away_team
            match_name = str(match.get('match', match.get('match_name', '')) or '').strip()
            parts = re.split(r'\s+(?:vs\.?|v)\s+', match_name, maxsplit=1, flags=re.IGNORECASE)
            if len(parts) != 2 and ' - ' in match_name:
                parts = match_name.split(' - ', 1)
            if len(parts) == 2:
                home_team = home_team or parts[0].strip()
                away_team = away_team or parts[1].strip()
            return home_team, away_team
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            return '', ''

    @classmethod
    def _extract_xg_pair(cls, match):
        """兼容常见字段提取主客预期进球；无真实数据时返回None。"""
        try:
            containers = [match] if isinstance(match, dict) else []
            if isinstance(match, dict):
                for key in ('xg_data', 'expected_goals', 'xg', 'match_xg', 'statistics'):
                    nested = match.get(key)
                    if isinstance(nested, dict):
                        containers.append(nested)
            key_pairs = (
                ('home_xg', 'away_xg'),
                ('xg_home', 'xg_away'),
                ('expected_goals_home', 'expected_goals_away'),
                ('home_expected_goals', 'away_expected_goals'),
                ('home', 'away'),
            )
            for container in containers:
                for home_key, away_key in key_pairs:
                    try:
                        home_xg = coerce_float(container.get(home_key))
                        away_xg = coerce_float(container.get(away_key))
                        if (math.isfinite(home_xg) and math.isfinite(away_xg)
                                and home_xg >= 0.0 and away_xg >= 0.0):
                            return home_xg, away_xg, f'{home_key}/{away_key}'
                    except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                        print(f"   ⚠️ [异常已捕获·continue降级 L10736] {_silent_err}")
                        continue
            return None
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·return None降级 L10739] {_silent_err}")
            return None

    def integrate_xg_data(self, match, home_lambda=None, away_lambda=None):
        """以有界几何收缩融合真实xG，降低单场随机噪声而不覆盖后验参数。"""
        try:
            base_home = MathUtils.safe_float(home_lambda)
            base_away = MathUtils.safe_float(away_lambda)
            if base_home is None or base_away is None or base_home <= 0 or base_away <= 0:
                result = {
                    'available': False,
                    'home_lambda': None,
                    'away_lambda': None,
                    'reason': '缺少进球期望，不补默认λ',
                }
                self.last_xg_integrations.append(result)
                return result
            base_home = max(0.05, min(6.0, base_home))
            base_away = max(0.05, min(6.0, base_away))
            xg_pair = self._extract_xg_pair(match if isinstance(match, dict) else {})
            if not xg_pair:
                result = {
                    'available': False,
                    'home_lambda': base_home,
                    'away_lambda': base_away,
                    'reason': '未提供可用预期进球数据，保留贝叶斯后验强度',
                }
                self.last_xg_integrations.append(result)
                return result

            home_xg, away_xg, source = xg_pair
            home_xg = max(0.05, min(6.0, float(home_xg)))
            away_xg = max(0.05, min(6.0, float(away_xg)))
            sample_count = 0.0
            try:
                sample_count = max(0.0, float(
                    match.get('xg_sample_count', match.get('expected_goals_sample_count', 0.0)) or 0.0
                ))
            except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                sample_count = 0.0
            xg_weight = min(0.45, max(0.20, 0.20 + 0.025 * min(sample_count, 10.0)))
            home_smoothed = math.exp((1.0 - xg_weight) * math.log(base_home) + xg_weight * math.log(home_xg))
            away_smoothed = math.exp((1.0 - xg_weight) * math.log(base_away) + xg_weight * math.log(away_xg))
            result = {
                'available': True,
                'source': source,
                'home_xg_raw': round(home_xg, 6),
                'away_xg_raw': round(away_xg, 6),
                'xg_weight': round(xg_weight, 6),
                'home_lambda_before_xg': round(base_home, 6),
                'away_lambda_before_xg': round(base_away, 6),
                'home_lambda': round(max(0.05, min(6.0, home_smoothed)), 6),
                'away_lambda': round(max(0.05, min(6.0, away_smoothed)), 6),
                'reason': '采用有界几何收缩融合预期进球，抑制单场极端值噪声',
            }
            self.last_xg_integrations.append(result)
            return result
        except Exception as xg_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [贝叶斯校准层·预期进球] 融合异常(已降级保留原λ): {xg_error}")
            return {
                'available': False,
                'home_lambda': MathUtils.safe_float(home_lambda),
                'away_lambda': MathUtils.safe_float(away_lambda),
                'reason': f'预期进球融合异常，已安全降级：{xg_error}',
            }

    def update_parameters(self, result_records):
        """调用现有赛果后验更新函数，幂等修正球队攻防参数。"""
        try:
            if isinstance(result_records, dict):
                if any(key in result_records for key in ('match', 'status', 'actual_score')):
                    records = [result_records]
                else:
                    records = list(result_records.values())
            elif isinstance(result_records, (list, tuple)):
                records = list(result_records)
            else:
                records = []

            updates = []
            for record in records:
                try:
                    if not isinstance(record, dict):
                        continue
                    actual_score = str(record.get('actual_score', '') or '').replace(':', '-').strip()
                    status = str(record.get('status', '') or '').lower().strip()
                    has_real_score = bool(re.match(r'^\s*\d+\s*-\s*\d+\s*$', actual_score))
                    if status != 'completed' and not has_real_score:
                        continue
                    update_result = update_ventropy_parameters_from_result(record, actual_score)
                    updates.append(update_result)
                except Exception as record_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    updates.append({'updated': False, 'reason': f'单场后验更新异常:{record_error}'})

            try:
                self.parameter_state = self._load_parameter_state()
                self._refresh_ability_params()
            except Exception as refresh_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                print(f"   ⚠️ [贝叶斯校准层] 参数快照刷新异常(沿用内存状态): {refresh_error}")
            self.last_parameter_updates = updates
            return updates
        except Exception as update_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [贝叶斯校准层] 批量参数更新异常(已降级跳过): {update_error}")
            self.last_parameter_updates = []
            return []

    @staticmethod
    def _posterior_probability_for_score(score, probability_matrix):
        try:
            normalized_score = str(score or '').replace(':', '-').strip()
            if normalized_score in JCZQ_VALID_SET:
                return float(probability_matrix.get(normalized_score, 0.0) or 0.0)
            if normalized_score not in ('胜其它', '平其它', '负其它'):
                return 0.0
            probability = 0.0
            for exact_score, value in (probability_matrix or {}).items():
                try:
                    if exact_score in JCZQ_VALID_SET or '-' not in exact_score:
                        continue
                    home_goals, away_goals = parse_score(exact_score)
                    if home_goals is None or away_goals is None:
                        continue
                    if normalized_score == '胜其它' and home_goals > away_goals or normalized_score == '平其它' and home_goals == away_goals or normalized_score == '负其它' and home_goals < away_goals:
                        probability += float(value or 0.0)
                except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [异常已捕获·continue降级 L10854] {_silent_err}")
                    continue
            return max(0.0, min(1.0, probability))
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·return 0.0降级 L10857] {_silent_err}")
            return 0.0

    def recalculate_match_probabilities(self, match):
        """以最新攻防后验和可用xG重新计算当前15池每个比分的精确概率。"""
        try:
            if not isinstance(match, dict):
                return {}
            calibrated_match = dict(match)
            selections = [dict(item) for item in (match.get('selections', []) or []) if isinstance(item, dict)]
            if not selections:
                calibrated_match['bayesian_calibration'] = {
                    'available': False,
                    'reason': '15池无有效比分选项',
                }
                return calibrated_match

            home_team, away_team = self._extract_team_names(match)
            dynamic_meta = match.get('ventropy_dynamic_lambda', {})
            if not isinstance(dynamic_meta, dict):
                dynamic_meta = {}
            base_home = dynamic_meta.get(
                'base_home_lambda', match.get('lam_h', match.get('lambda_home'))
            )
            base_away = dynamic_meta.get(
                'base_away_lambda', match.get('lam_a', match.get('lambda_away'))
            )
            feature_vector = match.get('feature_vector', match.get('llm_feature_vector', {}))
            if not isinstance(feature_vector, dict):
                feature_vector = {}

            if home_team and away_team:
                dynamic = self.calculate_dynamic_lambdas(
                    home_team,
                    away_team,
                    base_home,
                    base_away,
                    feature_vector=feature_vector,
                )
                posterior_home_lambda = coerce_float(dynamic.get('home_lambda', base_home) or base_home)
                posterior_away_lambda = coerce_float(dynamic.get('away_lambda', base_away) or base_away)
            else:
                dynamic = {
                    'home_lambda': MathUtils.safe_float(base_home),
                    'away_lambda': MathUtils.safe_float(base_away),
                    'reason': '球队名称缺失，沿用当前λ',
                }
                posterior_home_lambda = coerce_float(dynamic['home_lambda'])
                posterior_away_lambda = coerce_float(dynamic['away_lambda'])

            xg_result = self.integrate_xg_data(
                match,
                home_lambda=posterior_home_lambda,
                away_lambda=posterior_away_lambda,
            )
            final_home_lambda = float(xg_result.get('home_lambda', posterior_home_lambda) or posterior_home_lambda)
            final_away_lambda = float(xg_result.get('away_lambda', posterior_away_lambda) or posterior_away_lambda)
            probability_matrix = self.build_score_probability_matrix(
                final_home_lambda,
                final_away_lambda,
                max_goals=max(10, int(getattr(self, 'max_goals', 8) or 8)),
            )

            inverse_odds_total = 0.0
            for selection in selections:
                try:
                    odds = float(selection.get('odds', 0.0) or 0.0)
                    if odds > 1.0:
                        inverse_odds_total += 1.0 / odds
                except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [异常已捕获·continue降级 L10926] {_silent_err}")
                    continue

            calibrated_selections = []
            for selection in selections:
                try:
                    score = str(selection.get('score', selection.get('selection', '')) or '').replace(':', '-').strip()
                    if not score:
                        continue
                    prior_probability = self._safe_probability(
                        selection.get('probability', selection.get('theory_prob', 0.0)),
                        0.0,
                    )
                    posterior_probability = self._posterior_probability_for_score(score, probability_matrix)
                    if posterior_probability <= 0.0:
                        posterior_probability = prior_probability
                    odds = MathUtils.safe_float(selection.get('odds'), 0.0)
                    market_probability = self._safe_probability(selection.get('market_prob'), 0.0)
                    if market_probability <= 0.0 and odds > 1.0 and inverse_odds_total > 0.0:
                        market_probability = (1.0 / odds) / inverse_odds_total
                    art_ibi = MathUtils.safe_float(selection.get('ibi_at_art', selection.get('ibi')), 0.0)
                    if art_ibi <= 0.0 and market_probability > 0.0 and prior_probability > 0.0:
                        art_ibi = market_probability / prior_probability
                    posterior_ibi = (
                        market_probability / posterior_probability
                        if market_probability > 0.0 and posterior_probability > 0.0 else art_ibi
                    )
                    updated_selection = dict(selection)
                    updated_selection.update({
                        'prior_probability': round(prior_probability, 10),
                        'bayesian_probability': round(posterior_probability, 10),
                        'probability': round(posterior_probability, 10),
                        'probability_pct': round(posterior_probability * 100.0, 6),
                        'theory_prob': round(posterior_probability, 10),
                        'market_prob': round(market_probability, 10),
                        'ibi_at_art': round(art_ibi, 8),
                        'ibi': round(art_ibi, 8),
                        'posterior_ibi': round(posterior_ibi, 8),
                        'single_ev': round(odds * posterior_probability - 1.0, 10) if odds > 1.0 else -1.0,
                        'information_bits': round(-math.log2(max(posterior_probability, 1e-12)), 8),
                        'bayesian_calibrated': True,
                        'probability_source': '球队攻防后验+分层泊松+xG有界降噪' if xg_result.get('available') else '球队攻防后验+分层泊松',
                        'source': '15池闭环',
                    })
                    calibrated_selections.append(updated_selection)
                except Exception as selection_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [贝叶斯校准层] 单比分后验重算异常(已跳过): {selection_error}")

            calibrated_match['home_team'] = home_team
            calibrated_match['away_team'] = away_team
            calibrated_match['selections'] = calibrated_selections
            calibrated_match['bayesian_calibration'] = {
                'available': bool(calibrated_selections),
                'home_lambda': round(final_home_lambda, 6),
                'away_lambda': round(final_away_lambda, 6),
                'posterior_dynamic': dynamic,
                'xg_integration': xg_result,
                'score_probability_count': len(probability_matrix),
                'posterior_entropy_bits': round(
                    self.calculate_entropy([item.get('probability', 0.0) for item in calibrated_selections]),
                    8,
                ),
                'execution_stage': '第二重防火墙：贝叶斯参数动态校准层',
            }
            return calibrated_match
        except Exception as recalculation_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [贝叶斯校准层] 单场概率重算异常(已降级保留原场次): {recalculation_error}")
            fallback = dict(match) if isinstance(match, dict) else {}
            fallback['bayesian_calibration'] = {
                'available': False,
                'reason': f'概率重算异常，已保留原概率：{recalculation_error}',
            }
            return fallback

    def recalculate_daily_matches(self, matches):
        try:
            recalculated = []
            for match in matches or []:
                try:
                    calibrated_match = self.recalculate_match_probabilities(match)
                    if calibrated_match:
                        recalculated.append(calibrated_match)
                except Exception as match_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [贝叶斯校准层] 日池单场异常(已跳过): {match_error}")
            return recalculated
        except Exception as daily_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [贝叶斯校准层] 日池重算异常(已降级为空): {daily_error}")
            return []


class FinalClosedLoopEngine:
    """最终闭环：仅执行 DeviationDrivenEngine 偏差双轨决策。"""

    def __init__(self, n_teams=0, daily_budget=1000.0):
        try:
            self.n_teams = max(0, int(n_teams or 0))
        except Exception as team_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [偏差闭环] 球队数量初始化异常(已置零): {team_error}")
            self.n_teams = 0
        try:
            self.daily_budget = max(0.0, float(daily_budget or 0.0))
        except Exception as budget_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [偏差闭环] 每日预算初始化异常(已置零): {budget_error}")
            self.daily_budget = 0.0
        self.last_cycle = {}

    @staticmethod
    def _count_unique_teams(matches):
        try:
            teams = set()
            for match in matches or []:
                if not isinstance(match, dict):
                    continue
                for key in ('home_team', 'away_team'):
                    team = str(match.get(key, '') or '').strip()
                    if team:
                        teams.add(team)
            return len(teams)
        except Exception as team_count_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [偏差闭环] 球队计数异常(已置零): {team_count_error}")
            return 0

    @classmethod
    def _extract_deviation(cls, selection):
        """兼容入口：统一委托 DeviationDrivenEngine 偏差口径。"""
        try:
            return DeviationDrivenEngine._extract_deviation(selection)
        except Exception as deviation_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [偏差闭环] deviation提取异常(已置零): {deviation_error}")
            return 0.0

    @classmethod
    def _selection_to_ratio(cls, selection, match=None):
        """兼容入口：统一委托 DeviationDrivenEngine 字段标准化。"""
        try:
            return DeviationDrivenEngine.normalize_record(selection, context=match)
        except Exception as ratio_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [偏差闭环] 单项比例数据转换异常(已跳过): {ratio_error}")
            return None

    @classmethod
    def _extract_ratio_data(cls, raw_matches):
        """从每日抓取结果提取扁平 option/deviation/ibi 数据。"""
        try:
            ratio_data = []
            for match in raw_matches or []:
                try:
                    if not isinstance(match, dict):
                        continue
                    selections = match.get('selections', [])
                    for selection in selections if isinstance(selections, (list, tuple)) else []:
                        try:
                            ratio = cls._selection_to_ratio(selection, match=match)
                            if ratio:
                                ratio_data.append(ratio)
                        except Exception as selection_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                            print(f"   ⚠️ [偏差闭环] 单个选项提取异常(已跳过): {selection_error}")
                except Exception as match_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [偏差闭环] 单场提取异常(已跳过): {match_error}")
            return ratio_data
        except Exception as extraction_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [偏差闭环] 每日比例数据提取异常(已降级为空): {extraction_error}")
            return []

    def execute_daily_cycle(self, raw_matches_data, historical_results=None, top_n=5):
        """每日唯一决策链：提取 ratio_data → 分级 → 预算覆盖。"""
        try:
            raw_matches = [dict(item) for item in (raw_matches_data or []) if isinstance(item, dict)]
            ratio_data = self._extract_ratio_data(raw_matches)
            result = DeviationDrivenEngine.evaluate_records(ratio_data, total_budget=self.daily_budget)
            allocations = list(result.get('allocations', []) or [])
            classified = list(result.get('classified_results', []) or [])

            cycle = dict(result)
            cycle.update({
                'available': bool(allocations),
                'raw_match_count': len(raw_matches),
                'match_count': len({
                    str(item.get('match_id') or item.get('match') or '')
                    for item in ratio_data if isinstance(item, dict)
                }),
                'ratio_count': len(ratio_data),
                'tier_1_count': sum(1 for item in classified if item.get('tier') == 'TIER_1_KILL'),
                'tier_2_count': sum(1 for item in classified if item.get('tier') == 'TIER_2_DEFENSE'),
                'unknown_count': sum(1 for item in classified if item.get('tier') == 'UNKNOWN'),
                'total_budget': self.daily_budget,
                'allocated_total': round(sum(float(item.get('bet_amount', 0.0) or 0.0) for item in allocations), 2),
                'combination_count': 0,
                'source': 'DeviationDrivenEngine偏差双轨闭环',
            })
            self.last_cycle = cycle
            return cycle
        except Exception as cycle_error:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [偏差闭环] 日闭环异常(不影响单场主流程): {cycle_error}")
            fallback = {
                'available': False,
                'execution_order': ['偏差识别', '双轨分级', '分数归一化预算覆盖'],
                'raw_match_count': len(raw_matches_data or []),
                'match_count': 0,
                'ratio_count': 0,
                'tier_1_count': 0,
                'tier_2_count': 0,
                'unknown_count': 0,
                'ratio_data': [],
                'classified_results': [],
                'allocations': [],
                'tier_1_allocations': [],
                'tier_2_allocations': [],
                'total_budget': getattr(self, 'daily_budget', 0.0),
                'allocated_total': 0.0,
                'source': 'DeviationDrivenEngine偏差双轨闭环',
            }
            self.last_cycle = fallback
            return fallback

