# ==========================================================================
# 【robust_feature_tensor_imputation】高维张量泛化平滑替补网络
# 独立函数：负责 features_dict 级别的业务字段空洞填补与 API 惰性数据清洗。
# 与合成软输出/情景工具的 NaN/Inf 处理职责互补：
#   · 本函数处理「必发盈亏空洞」与「API 35/35/30 惰性数据」两类业务语义缺失
#   · _impute_feature_matrix 处理特征矩阵中所有列的通用 NaN/Inf 数值替补
# ==========================================================================
def robust_feature_tensor_imputation(features_dict, match_context):
    """
    核心自愈：高维张量的泛化平滑替补网络
    """
    try:
        # 必发失联保持空值。不按 λ 填虚拟盈亏，不用 -1 冒充成交量。
        # 2. API 惰性数据(35-35-30)清洗替换
        if features_dict.get('api_prob_h') == 35.0 and features_dict.get('api_prob_a') == 30.0:
            # 直接利用从 500/澳客提取的真实欧赔反推隐式概率，覆盖掉废弃的 API 数据
            features_dict['api_prob_h'] = match_context['implied_prob_h']
            features_dict['api_prob_a'] = match_context['implied_prob_a']

    except Exception as _rfit_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        try:
            print(f"   ⚠️ [robust_feature_tensor_imputation] 张量替补异常(已跳过): {_rfit_err}")
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L17907] {_silent_err}")

    return features_dict


# ==========================================================================
# 【情景合成软输出 & 掩码工具】（原 XGBoostScenarioPredictor 已删除）
# 以下三个纯数学/规则函数不依赖任何 GBDT/XGBoost，独立保留供主流程掩码锁与降级补位使用。
# ==========================================================================
def build_synthetic_soft_output(pool15_enriched=None, prob_dict=None,
                                dps_purified=None, reason="情景软输出"):
    """【合成软输出】纯泊松+DPS+pool15理论加权兜底，不依赖任何 GBDT/XGBoost。
    为下游 KNN Hard Gate 与 MoE 提供一个软信号参照，避免完全丧失机器学习维度参照。
    产出结构：{available, ranked_scores:[(score,prob)], consensus_top2:[(score,prob)],
             sample_count, model_type, synthetic:True}
    """
    _out = {"available": False, "ranked_scores": [], "consensus_top2": [],
            "sample_count": 0, "model_type": "synthetic_poisson_dps", "synthetic": True}
    try:
        # 1) 收集泊松理论概率（标准化为 0~1）
        _poisson = {}
        if isinstance(prob_dict, dict) and prob_dict:
            for _k, _v in prob_dict.items():
                _ks = str(_k).replace(":", "-").strip()
                try:
                    _poisson[_ks] = max(0.0, float(_v))
                except (ValueError, TypeError):
                    continue
        # 2) 收集 DPS 提纯池排序权重（priority 越小越优 -> 转为越大权重）
        _dps_weight = {}
        if dps_purified:
            _dps_list = list(dps_purified)
            _n_dps = len(_dps_list)
            for _rank, _item in enumerate(_dps_list):
                try:
                    _sc = str(_item.get("score", "") if isinstance(_item, dict)
                              else getattr(_item, "score_str", "")).replace(":", "-").strip()
                    if not _sc:
                        continue
                    _dps_weight[_sc] = max(0.05, (_n_dps - _rank) / float(_n_dps)) if _n_dps > 0 else 0.0
                except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [异常已捕获·continue降级 L17948] {_silent_err}")
                    continue
        # 3) 从 pool15 取 theory 作为回退信号
        _pool_theory = {}
        for _it in (pool15_enriched or []):
            try:
                _sc = str(_it.get("score", "")).replace(":", "-").strip()
                if not _sc:
                    continue
                _pool_theory[_sc] = max(0.0, float(_it.get("theory", 0.0) or 0.0)) / 100.0
            except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                print(f"   ⚠️ [异常已捕获·continue降级 L17958] {_silent_err}")
                continue
        # 4) 候选集合：优先 pool15，其次泊松高概率项
        _candidates = set(_pool_theory.keys()) | set(_dps_weight.keys())
        if not _candidates and _poisson:
            _candidates = set(sorted(_poisson, key=lambda k: -_poisson[k])[:15])
        if not _candidates:
            _out["reason"] = f"{reason}；合成软输出无可用候选池"
            return _out
        # 5) 加权合成：0.5*泊松 + 0.3*DPS排序 + 0.2*pool15理论
        _raw = {}
        for _sc in _candidates:
            _p_pois = _poisson.get(_sc, 0.0)
            _p_dps = _dps_weight.get(_sc, 0.0)
            _p_pool = _pool_theory.get(_sc, 0.0)
            _raw[_sc] = 0.5 * _p_pois + 0.3 * _p_dps + 0.2 * _p_pool
        _tot = sum(_raw.values())
        if _tot <= 0:
            _out["reason"] = f"{reason}；合成软输出权重总和为0"
            return _out
        _ranked = sorted(((_sc, _v / _tot) for _sc, _v in _raw.items()),
                         key=lambda kv: -kv[1])
        _consensus_top2 = [(_sc, _p) for _sc, _p in _ranked
                           if ("-" in str(_sc)) and str(_sc) in JCZQ_ALL_OPTIONS_SET][:2]
        _out.update({
            "available": True,
            "ranked_scores": _ranked,
            "consensus_top2": _consensus_top2,
            "sample_count": 0,
            "model_type": "synthetic_poisson_dps",
            "synthetic": True,
            "reason": f"{reason}→已合成泊松+DPS软输出信号",
        })
        try:
            _top3 = _ranked[:3]
            print("   🧩 [合成软输出·降级补位] 原因=" + str(reason) + " | 合成Top3: "
                  + ", ".join(f"{s}={p:.1%}" for s, p in _top3)
                  + " | 信号源=泊松0.5+DPS0.3+pool15·0.2（仅供KNN/MoE参照，不决策）")
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L17996] {_silent_err}")
        return _out
    except Exception as _syn_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        try:
            print(f"   ⚠️ [合成软输出] 构造异常(已降级): {_syn_err}")
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L18002] {_silent_err}")
        _out["reason"] = f"合成软输出异常: {_syn_err}"
        return _out


def build_binary_mask_matrix(score_list, veto_direction=None, extra_kill_scores=None):
    """【二进制决策掩码矩阵生成器】纯规则，不依赖任何 GBDT/XGBoost。
    根据风控穿盘方向 veto_direction('home'/'away') 与可选额外击杀名单，
    为 score_list 生成 {score_str: 0/1} 掩码：0=逆向/平局应清零，1=同向保留。
    """
    _vd = str(veto_direction or "").lower().strip()
    _extra = {str(x).replace(":", "-").strip() for x in (extra_kill_scores or [])}
    _mask = {}
    for _sc in (score_list or []):
        _sc_norm = str(_sc).replace(":", "-").strip()
        _m = 1
        if _sc_norm in _extra:
            _mask[_sc_norm] = 0
            continue
        if _vd in ("home", "away"):
            if "-" not in _sc_norm:
                if _vd == "home":
                    _m = 0 if (("平" in _sc_norm) or ("负" in _sc_norm)) else 1
                else:
                    _m = 0 if (("平" in _sc_norm) or ("胜" in _sc_norm)) else 1
            else:
                try:
                    _h, _a = parse_score(_sc_norm)
                    if _h is None or _a is None:
                        _m = 1
                    elif _vd == "home":
                        _m = 0 if ((_a > _h) or (_h == _a)) else 1
                    else:
                        _m = 0 if ((_h > _a) or (_h == _a)) else 1
                except (ValueError, TypeError):
                    _m = 1
        _mask[_sc_norm] = _m
    return _mask


def mask_penalty_score(score_str, veto_direction=None):
    """【软性掩码惩罚分级器】纯规则，不依赖任何 GBDT/XGBoost。
    返回软性指数衰减所需 penalty_score：完全逆向1.0 / 平局0.7 / 弱逆向0.4。
    """
    _vd = str(veto_direction or "").lower().strip()
    _s = str(score_str or "").replace(":", "-").strip()
    try:
        if "其它" in _s:
            if ("平" in _s):
                return 0.7
            if _vd == "home":
                return 1.0 if ("负" in _s) else 0.4
            if _vd == "away":
                return 1.0 if ("胜" in _s) else 0.4
            return 0.4
        _h, _a = parse_score(_s)
        if _h is None or _a is None:
            return 0.4
        if _h == _a:
            return 0.7
        if _vd == "home":
            return 1.0 if (_a > _h) else 0.4
        if _vd == "away":
            return 1.0 if (_h > _a) else 0.4
        return 0.4
    except (ValueError, TypeError):
        return 0.4
# ── 3. 2D 相空间全息分析器 (Phase Space Adjudicator) ──
class PhaseSpaceAnalyzer:
    """负责对任意节点进行 Δ-IBI 二维量子相空间定性"""
    @staticmethod
    def classify_node(delta: float, ibi: float) -> str:
        if ibi > 6.0:
            return PhaseZone.NUCLEAR_PROBE
        if delta < 0 and 1.5 < ibi <= 6.0:
            return PhaseZone.SMART_MONEY
        if delta < -10.0 and ibi < 0.6:
            return PhaseZone.POISSON_COLLAPSE
        if -5.0 <= delta <= 0.0 and 0.8 <= ibi <= 1.2:
            return PhaseZone.REAL_VALUE
        if delta > 0.0 and ibi > 2.5:
            return PhaseZone.DAM_MARKDOWN
        return PhaseZone.VAMPIRE_SHELTER


# ==========================================================================
class DynamicPoolSelector:
    """结合相空间定性，强制提权危险探针，剪枝僵尸节点，交付高纯度15池"""
    @staticmethod
    def process_and_filter(raw_data: list[dict[str, float]],
                           first_score: str | None = None, second_score: str | None = None,
                           rtm_result: dict | None = None):
        # 【全维度顺位追踪矩阵·精算表】解析铁锚/诱饵/物理奇点，作为提权/降权依据
        _dps_anchor_set = set()
        _dps_bait_set = set()
        _dps_singularity_set = set()
        if rtm_result and isinstance(rtm_result, dict) and rtm_result.get('ok'):
            _dps_anchor_set = {str(x).replace(':', '-').strip() for x in (rtm_result.get('anchor_scores', []) or [])}
            _dps_bait_set = {str(x).replace(':', '-').strip() for x in (rtm_result.get('bait_scores', []) or [])}
            _dps_singularity_set = {str(x).replace(':', '-').strip() for x in (rtm_result.get('singularity_score_names', []) or [])}
        nodes = []
        _ban_dps = {'theory_le_1': 0, 'market_0': 0, 'delta_0': 0}
        for d in raw_data:
            score_str = str(d.get("score", "")).strip()
            theory_p = float(d.get("theory_p", 0.0) or 0.0)
            market_p = float(d.get("market_p", 0.0) or 0.0)
            delta = d.get("delta", market_p - theory_p)

            # 【硬性禁入条件】理论<=1%, 市场=0%, 偏差=0%；禁止逐条刷屏
            if '其它' not in score_str:
                if theory_p <= 0.01:
                    _ban_dps['theory_le_1'] += 1
                    continue
                if market_p <= 0.0:
                    _ban_dps['market_0'] += 1
                    continue
                if abs(theory_p - market_p) < 1e-9:
                    _ban_dps['delta_0'] += 1
                    continue

            ibi = d["ibi"]
            zone = PhaseSpaceAnalyzer.classify_node(delta, ibi)

            # 初始优先级划分
            if zone in [PhaseZone.NUCLEAR_PROBE, PhaseZone.DAM_MARKDOWN]:
                priority = 1
            elif zone == PhaseZone.SMART_MONEY:
                priority = 2
            else:
                priority = 3

            nodes.append(V14ScoreNode(
                score_str=str(d["score"]), theory_p=d["theory_p"], market_p=d["market_p"],
                delta=delta, ibi=ibi, priority=priority, phase_zone=zone
            ))
        _ban_dps_n = int(_ban_dps['theory_le_1'] + _ban_dps['market_0'] + _ban_dps['delta_0'])
        if _ban_dps_n:
            _legacy_eng_log(
                f"   🚫 [DPS禁入] 汇总 n={_ban_dps_n}"
                f"｜市%0={_ban_dps['market_0']}"
                f"｜理≤1%={_ban_dps['theory_le_1']}"
                f"｜Δ0={_ban_dps['delta_0']}（逐条已禁）"
            )

        # 【模块二集成】K-Means 赔率轨迹聚类，作为额外聚类维度辅助提权/剪枝
        _cluster_res = {"ok": False, "boost_scores": set(), "probe_scores": set(),
                        "labels": {}, "dists": {}, "roles": {}}
        try:
            _cluster_res = {'ok': False, 'reason': 'KMeans已删除'}
            if _cluster_res.get("ok"):
                for n in nodes:
                    _sc = str(n.score_str).replace(":", "-").strip()
                    n.cluster_label = _cluster_res["labels"].get(_sc, -1)
                    n.cluster_dist = _cluster_res["dists"].get(_sc, 0.0)
                    n.cluster_role = _cluster_res["roles"].get(_sc, "普通")
                    # 同簇加分：若与首/次选同簇且原为低优先级，提升一级
                    if _sc in _cluster_res["boost_scores"] and n.priority == 3:
                        n.priority = 2
                    # 孤立探针：强制提权为最高优先级
                    if _sc in _cluster_res["probe_scores"]:
                        n.priority = min(n.priority, 1)
        except Exception as _ce:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            try:
                print(f"   ⚠️ [KMeans聚类] 降级跳过: {_ce}")
            except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                print(f"   ⚠️ [异常已捕获·pass降级 L18291] {_silent_err}")

        # 【全维度顺位追踪矩阵·精算表】提权/降权修正：
        # 铁锚→强制提为最高优先级(1)；诱饵/物理奇点→强制降为最低优先级(3)。
        if _dps_anchor_set or _dps_bait_set or _dps_singularity_set:
            for n in nodes:
                _sc = str(n.score_str).replace(":", "-").strip()
                if _sc in _dps_anchor_set:
                    n.priority = 1
                elif _sc in _dps_singularity_set or _sc in _dps_bait_set:
                    n.priority = 3
            try:
                print(f"   ⚓ [DynamicPoolSelector] 顺位追踪矩阵提权词: "
                      f"铁锚{sorted(_dps_anchor_set) or '无'}↑ | 诱饵{sorted(_dps_bait_set) or '无'}↓ | "
                      f"物理奇点{sorted(_dps_singularity_set) or '无'}↓")
            except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                print(f"   ⚠️ [异常已捕获·pass降级 L18307] {_silent_err}")

        # 基础按理论概率降序
        nodes.sort(key=lambda x: x.theory_p, reverse=True)

        top_15_pool = nodes[:15]
        outside_pool = nodes[15:]

        # 捕获游离在15名开外的高危相空间探针
        vip_probes = [n for n in outside_pool if n.priority in [1, 2]]
        # 提取用于终极溢出防御的核爆探针（含 KMeans 孤立探针）
        nuclear_probes = [n for n in outside_pool if n.phase_zone == PhaseZone.NUCLEAR_PROBE
                          or n.cluster_role == "孤立探针"]

        # 动态置换：猎杀僵尸节点
        if vip_probes:
            for i in range(14, 8, -1):
                if not vip_probes:
                    break
                if i >= len(top_15_pool):
                    continue
                candidate = top_15_pool[i]
                is_zombie = (candidate.priority == 3 and
                             0.95 <= candidate.ibi <= 1.05 and
                             abs(candidate.delta) < 0.5)
                if is_zombie:
                    top_15_pool[i] = vip_probes.pop(0)

            # 极端情况暴力腾出舱位
            while vip_probes:
                replaced = False
                for i in range(14, -1, -1):
                    if i < len(top_15_pool) and top_15_pool[i].priority == 3:
                        top_15_pool[i] = vip_probes.pop(0)
                        replaced = True
                        break
                if not replaced:
                    top_15_pool.append(vip_probes.pop(0))

        return sorted(top_15_pool, key=lambda x: (x.priority, -x.theory_p)), nuclear_probes


