def compute_are_and_risk_chain(ranked_scores, prob_dict, odds_correct_score,
                               odds_1x2_dict, asian_handicap,
                               anomaly_payload_out=None):
    """【ARE + 风控链矩阵组装器】
    运筹学终审引擎已彻底删除。本函数仅负责调用两个独立且仍被下游（AI预测引擎/
    TG报告/复盘/UI）消费的模块——反逆向工程引擎(ARE)与庄家风控链矩阵——
    并组装成与旧 or_prediction 兼容的结果字典（保留 anti_reverse_engineering /
    risk_chain_analysis / final_score 兜底键），不再执行任何三源融合/线性规划/
    权重终审等运筹学逻辑。
    """
    result = {
        'final_score': '',
        'final_result': '',
        'confidence': 0.0,
        'or_top5': [],
        'method': 'are_risk_chain_only',
        'result_probs': {},
    }
    if not ranked_scores or not prob_dict:
        return result

    # 竞彩范围过滤 + 理论/市场概率映射（仅用于喂给 ARE / 风控链）
    scores_universe = [s for s, _ in ranked_scores[:15]
                       if s in JCZQ_VALID_SET or s in ('胜其它', '平其它', '负其它')]
    p_theory = {s: float(prob_dict.get(s, 0.0)) for s in scores_universe}
    p_market = {}
    if odds_correct_score and len(odds_correct_score) >= 3:
        total_inv = sum(1.0 / v for v in odds_correct_score.values()
                        if isinstance(v, (int, float)) and v > 0)
        if total_inv > 0:
            for s in scores_universe:
                odds_val = odds_correct_score.get(s) or odds_correct_score.get(s.replace('-', ':'))
                p_market[s] = ((1.0 / float(odds_val)) / total_inv) if (odds_val and float(odds_val) > 0) else 0.0

    # 兜底首选比分：直接取排序后的理论首选
    try:
        _first = scores_universe[0] if scores_universe else (ranked_scores[0][0] if ranked_scores else '')
        result['final_score'] = _first
        if '-' in str(_first):
            _h, _a = parse_score(_first)
            if _h is not None and _a is not None:
                result['final_result'] = '主胜' if _h > _a else ('平局' if _h == _a else '客胜')
        elif '胜其它' in str(_first):
            result['final_result'] = '主胜'
        elif '平其它' in str(_first):
            result['final_result'] = '平局'
        elif '负其它' in str(_first):
            result['final_result'] = '客胜'
    except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [异常已捕获·pass降级 L18781] {_silent_err}")

    # === 反逆向工程引擎(ARE) ===
    _are_result = None
    try:
        _are_pool15 = []
        for _are_s in scores_universe:
            _are_tp = p_theory.get(_are_s, 0.0) * 100
            _are_mp = p_market.get(_are_s, _are_tp * 0.8) * 100 if p_market else _are_tp * 0.8
            _are_ibi = (_are_mp / _are_tp) if _are_tp > 0.01 else 0.0
            _are_pool15.append({
                'score': _are_s,
                'theory_prob': _are_tp,
                'market_prob': _are_mp,
                'ibi': _are_ibi,
            })
        _are_kelly = None
        if anomaly_payload_out and isinstance(anomaly_payload_out, dict):
            _are_kelly = anomaly_payload_out.get('kelly_variance', None)
        _are_result = v10_anti_reverse_engineering_engine(
            pool15_data=_are_pool15,
            kelly_variance_data=_are_kelly,
            asian_handicap=asian_handicap,
            anomaly_payload_out=anomaly_payload_out,
            odds_correct_score=odds_correct_score,
        )
    except Exception as _are_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [ARE引擎] 异常(已降级跳过): {_are_err}")
        _are_result = None

    # === 庄家风控链矩阵 ===
    _rcm_result = None
    try:
        _rcm_all_ibi = {}
        if odds_correct_score and isinstance(odds_correct_score, dict):
            _rcm_total_inv = sum(1.0 / v for v in odds_correct_score.values()
                                 if isinstance(v, (int, float)) and v > 0)
            if _rcm_total_inv > 0:
                for _rcm_sc in JCZQ_ALL_OPTIONS:
                    _rcm_odds_val = odds_correct_score.get(_rcm_sc) or odds_correct_score.get(_rcm_sc.replace('-', ':'))
                    _rcm_mp = (1.0 / float(_rcm_odds_val)) / _rcm_total_inv * 100 if _rcm_odds_val and float(_rcm_odds_val) > 0 else 0.0
                    _rcm_tp = p_theory.get(_rcm_sc, 0.0) * 100
                    _rcm_ibi = (_rcm_mp / _rcm_tp) if _rcm_tp > 0.01 else 0.0
                    _rcm_all_ibi[_rcm_sc] = _rcm_ibi
        _rcm_result = None  # 风控链矩阵已删除
    except Exception as _rcm_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [风控链矩阵] 异常(已降级跳过): {_rcm_err}")
        _rcm_result = None

    if _are_result and isinstance(_are_result, dict):
        result['anti_reverse_engineering'] = _are_result
    if _rcm_result and isinstance(_rcm_result, dict):
        result['risk_chain_analysis'] = _rcm_result

    return result


# =====================================================
# 【核心装甲】自适应弹性逼空判定算法 (Adaptive Squeeze Engine)
# 放置于 execute_15to2_matrix 上方，作为独立辅助函数。
# 三维度评分（A 返还率下杀深度 50% / B 亚盘位移动能 30% / C 资金烈度 20%），
# 结合联赛自适应基准与方向合规性校验，输出 0-100 的逼空指数。
# 返回: (is_squeeze, squeeze_dir, squeeze_score, reason_log)
# =====================================================
def detect_adaptive_squeeze(ai_fund_signal, ai_handicap_signal, league_name):
    """
    【核心装甲】自适应弹性逼空判定算法 (Adaptive Squeeze Engine)
    结合联赛基准、返还率惩罚、盘口位移动能与资金烈度，输出弹性逼空判定。
    返回: (is_squeeze, squeeze_dir, squeeze_score, reason_log)
    """
    try:
        ai_fund_signal = ai_fund_signal or {}
        ai_handicap_signal = ai_handicap_signal or {}

        from odds_index_math import normalize_return_rate, return_rate_pct
        _rr_frac = normalize_return_rate(ai_fund_signal.get('return_rate_avg', 0.0))
        # 后续阈值仍按「百分数」书写（如 97/93）；内部先归一再 *100
        return_rate = float(return_rate_pct(_rr_frac) or 0.0)
        exposure_dir = str(
            ai_fund_signal.get('exposure_direction')
            or ai_fund_signal.get('fund_direction')
            or 'neutral'
        ).lower()
        ah_traj = str(ai_handicap_signal.get('ah_trajectory', 'neutral') or 'neutral').lower()
        # 防御性读取 ah_change_magnitude，缺字段时默认 0.0
        try:
            ah_mag = float(ai_handicap_signal.get('ah_change_magnitude', 0.0) or 0.0)
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            ah_mag = 0.0
        fund_anomaly = bool(ai_fund_signal.get('fund_anomaly', False))
        fund_concentration = str(ai_fund_signal.get('fund_concentration', 'medium') or 'medium').lower()

        # 1. 基础过滤：缺返还率或方向不明，直接退回
        if return_rate <= 0 or exposure_dir == 'neutral' or ah_traj == 'neutral':
            return False, '', 0.0, "条件不足(缺RR或方向不明)"

        # 2. 联赛自适应基准 (League-tier Baseline)
        major_leagues = [
            '英超', '西甲', '意甲', '德甲', '法甲',
            '欧冠', '欧联', '欧洲杯', '世界杯',
            'Champions League', 'Europa', 'Premier League', 'La Liga',
            'Serie A', 'Bundesliga', 'Ligue 1', 'World Cup', 'Euro'
        ]
        league_str = str(league_name or '')
        is_major = any(l in league_str for l in major_leagues)
        base_threshold = 94.0 if is_major else 92.0

        squeeze_score = 0.0
        log_parts = []

        # 3. 维度 A：返还率下杀深度 (权重 50%)
        if return_rate < base_threshold:
            drop = base_threshold - return_rate
            rr_score = min(50.0, drop * 15.0)  # 跌 1% 加 15 分
            squeeze_score += rr_score
            log_parts.append(f"RR下杀({return_rate:.1f}%<基准{base_threshold}, 得分{rr_score:.1f})")
        else:
            return False, '', 0.0, f"RR正常({return_rate:.1f}%>=基准{base_threshold})"

        # 4. 维度 B：亚盘位移动能 (权重 30%)
        if ah_mag > 0:
            mag_score = min(30.0, ah_mag * 50.0)
            squeeze_score += mag_score
            log_parts.append(f"盘口动能(变动{ah_mag:.2f}, 得分{mag_score:.1f})")

        # 5. 维度 C：资金烈度预警 (权重 20%)
        if fund_anomaly or fund_concentration == 'high':
            squeeze_score += 20.0
            log_parts.append("资金异动(得分20.0)")

        # 6. 方向合规性校验
        is_directional_squeeze = False
        squeeze_dir = ''
        if exposure_dir == 'home' and ah_traj == 'home_strengthen':
            is_directional_squeeze = True
            squeeze_dir = 'home'
        elif exposure_dir == 'away' and (ah_traj == 'away_strengthen' or ah_traj == 'home_weaken'):
            is_directional_squeeze = True
            squeeze_dir = 'away'

        # 7. 弹性触发：分数>=60 且方向合规
        activation_threshold = 60.0
        is_squeeze = is_directional_squeeze and (squeeze_score >= activation_threshold)

        reason_log = " | ".join(log_parts) + f" => 总逼空分:{squeeze_score:.1f}"
        if not is_directional_squeeze:
            reason_log += f" | 方向不合规(exposure={exposure_dir}/ah={ah_traj})"
        return is_squeeze, squeeze_dir, squeeze_score, reason_log
    except Exception as _ase_exc:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        # 任何异常都安全降级，向后兼容旧链路
        return False, '', 0.0, f"AdaptiveSqueeze异常降级:{_ase_exc}"


# =====================================================================
# 【架构升级②·概率簇输出（第六层）】
# 将比赛结果视为动态分布空间而非几个孤立的点：算法不再仅输出
# 单一/双比分，而是输出“概率簇 (Probability Clusters)”。
# 当 KLDivergenceAnomalyDetector 触发高阈值时，直接输出高概率比分
# 集群（如“0-1/0-2防冷簇”或“大球穿盘簇”），比死磕“最优双比分”
# 具有更强的实战抗风险能力。保留 first_score/second_score 作为
# 簇内最优，额外输出 cluster 信息。
# =====================================================================

# =====================================================================
# 【第六层·BladeQuant V2】概率簇拓扑引擎 ClusterDecisionEngine
# 升级 build_probability_cluster 的底层拓扑能力：基于 MLE 冻结λ
# 生成 6×6 泊松基础矩阵，当 DrawCrossPairAnalyzer 剪切力警报触发时
# 执行异常拓扑变形：
#   Δ_02>0（死防0:0掩护2:2）→ 高方差变形：低分区×0.1压制、高分区×1.5提振
#   Δ_02<0（死防2:2诱导0:0）→ 冰封变形：仅保留 0-0/1-0/0-1 低波动区
# 常态输出泊松 Top-3 核心簇。输出结果由 build_probability_cluster 消费。
# =====================================================================
class ClusterDecisionEngine:
    def __init__(self, lambda_h, lambda_a):
        self.lambda_h = max(float(lambda_h or 0.0), 1e-6)
        self.lambda_a = max(float(lambda_a or 0.0), 1e-6)
        self.max_goals = 5

    def _generate_base_matrix(self):
        matrix = np.zeros((self.max_goals + 1, self.max_goals + 1))
        for h in range(self.max_goals + 1):
            for a in range(self.max_goals + 1):
                matrix[h][a] = poisson.pmf(h, self.lambda_h) * poisson.pmf(a, self.lambda_a)
        return matrix

    def generate_probability_cluster(self, cross_features):
        """根据交叉配对异化特征生成概率簇（Top-3）。
        返回 [{'score': 'h:a', 'prob': float, 'type': str}, ...]"""
        matrix = self._generate_base_matrix()
        cross_features = cross_features or {}
        trap_02 = cross_features.get('Trap_Alert_02', 0)
        delta_02 = cross_features.get('Delta_02', 0.0)

        # 异常拓扑变形
        if trap_02 == 1:
            if delta_02 > 0:  # 庄家死防0:0，掩护2:2 (高方差)
                variance_matrix = matrix.copy()
                variance_matrix[0:2, 0:2] *= 0.1  # 压制低分
                variance_matrix[2:, 2:] *= 1.5    # 提振高分
                flat_indices = np.argsort(variance_matrix, axis=None)[::-1]
                return [{'score': f"{h}:{a}", 'prob': round(float(matrix[h][a]), 4), 'type': 'High-Variance'}
                        for h, a in [np.unravel_index(idx, variance_matrix.shape) for idx in flat_indices[:3]]]

            else:  # 庄家死防2:2，诱导0:0 (冰封低波动)
                freeze_matrix = np.zeros_like(matrix)
                for h in [0, 1]:
                    for a in [0, 1]:
                        if h + a <= 1 or (h == 0 and a == 0):
                            freeze_matrix[h][a] = matrix[h][a]
                flat_indices = np.argsort(freeze_matrix, axis=None)[::-1]
                return [{'score': f"{h}:{a}", 'prob': round(float(matrix[h][a]), 4), 'type': 'Freeze'}
                        for h, a in [np.unravel_index(idx, freeze_matrix.shape) for idx in flat_indices[:3]] if freeze_matrix[h][a] > 0]

        # 常态输出Top-3
        flat_indices = np.argsort(matrix, axis=None)[::-1]
        return [{'score': f"{h}:{a}", 'prob': round(float(matrix[h][a]), 4), 'type': 'Core'}
                for h, a in [np.unravel_index(idx, matrix.shape) for idx in flat_indices[:3]]]


# =====================================================================
# 【第五/六层·BladeQuant V2】亚盘降维定价器 AsianHandicapPricer
# 新增亚盘穿透计算：将概率簇（高维比分空间）投影到亚盘盘口
# （低维让球强度层）计算簇EV：逐格判定赢盘/赢半/走盘/输半/输盘
# 乘数，加权求和后强制扣减 StaticMarginConfig.EV_HAIRCUT 静态滑点安全垫。
# handicap 取主队视角（让球为负，如 -0.25），与 500 网亚盘数据对接。
# =====================================================================
class AsianHandicapPricer:
    def __init__(self, lambda_h, lambda_a):
        self.engine = ClusterDecisionEngine(lambda_h, lambda_a)
        self.matrix = self.engine._generate_base_matrix()
        self.max_goals = 5

    def _get_multiplier(self, h, a, handicap):
        """精确计算盈亏乘数（由 AsianHandicapEngine.settle_bet 驱动）。
        
        替代旧版阈值近似逻辑，正确处理三类盘口：
        - 半球系：非赢即输 (1.0 / -1.0)
        - 整数系：含走盘 (1.0 / 0.0 / -1.0)
        - 季度系：含赢半/输半 (1.0 / 0.5 / 0.0 / -0.5 / -1.0)
        """
        return AsianHandicapEngine.get_settlement_multiplier(h, a, handicap)


    def calculate_cluster_ev(self, handicap, decimal_odds, cluster):
        """簇EV穿透计算：cluster 成员支持 'h:a' 或 'h-a' 比分键。"""
        try:
            net_odds = float(decimal_odds) - 1.0
            handicap = float(handicap)
        except (TypeError, ValueError):
            return None
        expected_value = 0.0
        cluster_scores = set()
        for item in (cluster or []):
            if isinstance(item, dict):
                _sc = str(item.get('score', ''))
            elif isinstance(item, (tuple, list)) and item:
                _sc = str(item[0])
            else:
                _sc = str(item)
            cluster_scores.add(_sc.replace('-', ':').strip())

        for h in range(self.max_goals + 1):
            for a in range(self.max_goals + 1):
                if f"{h}:{a}" not in cluster_scores:
                    continue

                prob = self.matrix[h][a]
                multiplier = self._get_multiplier(h, a, handicap)

                if multiplier == 1.0:
                    expected_value += prob * net_odds
                elif multiplier == 0.5:
                    expected_value += prob * (net_odds / 2)
                elif multiplier == -0.5:
                    expected_value += prob * (-0.5)
                elif multiplier == -1.0:
                    expected_value += prob * (-1.0)

        # 强制扣减静态滑点安全垫
        adj_ev = expected_value - StaticMarginConfig.EV_HAIRCUT
        return round(adj_ev, 4)


def build_probability_cluster(prob_dict, first_score, second_score,
                              kl_result=None, ou_line=None,
                              lam_h=None, lam_a=None, max_members=4,
                              cross_features=None):
    """【架构升级②·BladeQuant V2升级】概率簇构建器。
    V2新增：若传入 cross_features（DrawCrossPairAnalyzer 输出）且触发
    Trap_Alert_02 剪切力警报，优先调用 ClusterDecisionEngine 执行拓扑变形：
      Δ_02>0 → 高方差簇(high_variance)；Δ_02<0 → 冰封簇(freeze)。
    参数:
        prob_dict: 比分概率字典 {'1-0': 0.11, ...}
        first_score/second_score: 传统双比分输出（作为簇内最优保留）
        kl_result: KLDivergenceAnomalyDetector.detect() 的输出 dict（可选）
        ou_line: 大小球盘口（用于大球穿盘簇判定）
    返回 dict:
        cluster_type: 'cold_defense'防冷簇 / 'over_breakout'大球穿盘簇 /
                      'draw_anchor'平局锚簇 / 'regular'常规主簇
        cluster_label: 中文簇名（如 '0-1/0-2防冷簇'）
        members: [(score, prob), ...] 簇成员（含概率，降序）
        cluster_prob: 簇总概率
        best_in_cluster: 簇内最优比分（与 first_score 兼容）
        kl_triggered: 是否由 KL 高阈值触发
        display: 中文展示文本
    全程降级保护：异常时返回以 first/second 为成员的常规簇。"""
    def _fallback():
        _m = []
        for _s in [first_score, second_score]:
            if _s:
                _m.append((_s, float(prob_dict.get(_s, 0.0) or 0.0) if prob_dict else 0.0))
        return {
            'cluster_type': 'regular', 'cluster_label': '常规双比分簇(降级)',
            'members': _m, 'cluster_prob': round(sum(p for _, p in _m), 4),
            'best_in_cluster': first_score, 'kl_triggered': False,
            'display': f"【概率簇】常规双比分簇(降级): {first_score}/{second_score}",
        }
    try:
        if not prob_dict:
            return _fallback()
        # 解析数值比分池（跳过“胜其它/平其它/负其它”类虚拟比分）
        pool = []
        for _s, _p in prob_dict.items():
            try:
                _ss = str(_s).replace(':', '-').strip()
                if '-' not in _ss or '其' in _ss:
                    continue
                _h, _a = parse_score(_ss)
                pool.append((_ss, _h, _a, float(_p)))
            except Exception:  # noqa: BLE001,S112 - intentional degraded-mode guard or structure-preserving fallback  # nosec B112  # intentional degraded-mode continue fallback
                continue
        if not pool:
            return _fallback()
        # ── 【BladeQuant V2·拓扑变形优先】剪切力警报触发时由 ClusterDecisionEngine 接管 ──
        _cf = cross_features if isinstance(cross_features, dict) else {}
        if _cf.get('Trap_Alert_02') == 1:
            try:
                _cde = ClusterDecisionEngine(lam_h, lam_a)
                _v2_cluster = _cde.generate_probability_cluster(_cf)
                if _v2_cluster:
                    _v2_type_raw = _v2_cluster[0].get('type', 'Core')
                    _v2_type = 'high_variance' if _v2_type_raw == 'High-Variance' else (
                        'freeze' if _v2_type_raw == 'Freeze' else 'regular')
                    _v2_members = []
                    for _keep in (first_score, second_score):
                        _keep_n = str(_keep).replace(':', '-').strip() if _keep else ''
                        if _keep_n and _keep_n not in {s for s, _ in _v2_members} and '其' not in _keep_n:
                            _p_keep = float(prob_dict.get(_keep, prob_dict.get(_keep_n, 0.0)) or 0.0) if prob_dict else 0.0
                            _v2_members.append((_keep_n, _p_keep))
                    _v2_prob = round(sum(p for _, p in _v2_members), 4)
                    _v2_label = '拓扑变形只记事实，不另定两个比分'
                    _d02_v2 = _cf.get('Delta_02', 0)
                    _v2_display = (
                        f"🎯【概率簇输出 · BQV2拓扑变形·{'高方差簇' if _v2_type == 'high_variance' else '冰封簇'}】{_v2_label}\n"
                        f"簇成员: {' / '.join(f'{s}({p*100:.1f}%)' for s, p in _v2_members) or '未形成'} | 簇总概率: {_v2_prob*100:.1f}%\n"
                        f"⚡ 剪切力陷阱警报触发(Δ_02={_d02_v2:+.3f})："
                        + ('拓扑矩阵压制低分、提振高分，不另定比分' if _d02_v2 > 0
                           else '拓扑矩阵冰封低分区，不另定比分')
                    )
                    return {
                        'cluster_type': _v2_type, 'cluster_label': _v2_label,
                        'members': _v2_members, 'cluster_prob': _v2_prob,
                        'best_in_cluster': str(first_score or ''),
                        'kl_triggered': False,
                        'bqv2_topology': True,
                        'bqv2_cluster_type_raw': _v2_type_raw,
                        'cross_features': dict(_cf),
                        'display': _v2_display,
                    }
            except Exception as _cde_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                print(f"   ⚠️ [BQV2·拓扑变形] 异常(回退传统簇逻辑): {_cde_err}")

        kl = kl_result if isinstance(kl_result, dict) else {}
        kl_high = bool(kl.get('real_defense')) or bool(kl.get('kl_surge'))
        str(kl.get('real_defense_direction') or '').lower()
        rd_scores = [str(x).replace(':', '-').strip() for x in (kl.get('real_defense_scores') or [])]
        _ou = None
        try:
            _ou = float(ou_line) if ou_line is not None else None
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            _ou = None
        cluster_type, cluster_label, members = 'regular', '', []
        if kl_high:
            # ── KL高阈值触发：直接输出高概率比分集群 ──
            if rd_scores:
                # 优先用真实防范标记比分定簇型
                _rd_totals = []
                _rd_dirs = []
                for _rs in rd_scores:
                    try:
                        _rh, _ra = parse_score(_rs)
                        if _rh is None or _ra is None:
                            continue
                        _rd_totals.append(_rh + _ra)
                        _rd_dirs.append('home' if _rh > _ra else ('away' if _rh < _ra else 'draw'))
                    except Exception:  # noqa: BLE001,S112 - intentional degraded-mode guard or structure-preserving fallback  # nosec B112  # intentional degraded-mode continue fallback
                        continue
                if _ou is None:
                    cluster_label = '盘口未抓到，不另定比分簇'
                else:
                    cluster_label = '高阈值只记防范，不另定比分簇'
            else:
                if _ou is None:
                    cluster_label = '盘口未抓到，不另定比分簇'
                else:
                    cluster_label = '不按低比分另定比分簇'
        if not members:
            # ── 常规簇：以 first_score 为核心，聚合同方向、总进球±1的相邻比分 ──
            cluster_type = cluster_type if cluster_type != 'regular' else 'regular'
            _fh = _fa = None
            try:
                _fh, _fa = parse_score(first_score)
            except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
                pass
            if _fh is not None:
                cluster_label = cluster_label or '沿已收口的两个比分'
            else:
                cluster_label = '未形成，不另定比分簇'
        # 确保 first/second 作为簇内最优保留：若不在簇内则补入
        _member_scores = {s for s, _ in members}
        for _keep in [first_score, second_score]:
            _keep_n = str(_keep).replace(':', '-').strip() if _keep else ''
            if _keep_n and _keep_n not in _member_scores and '其' not in _keep_n:
                members.append((_keep_n, float(prob_dict.get(_keep, prob_dict.get(_keep_n, 0.0)) or 0.0)))
                _member_scores.add(_keep_n)
        members = members[:max(max_members, 4)]
        cluster_prob = round(sum(p for _, p in members), 4)
        best_in_cluster = str(first_score).replace(':', '-').strip() if first_score else ''
        _type_cn = {
            'cold_defense': '防冷簇', 'over_breakout': '大球穿盘簇',
            'draw_anchor': '平局锚簇', 'regular': '常规主簇',
            'high_variance': '高方差簇', 'freeze': '冰封簇',
        }
        _mem_text = ' / '.join(f"{s}({p*100:.1f}%)" for s, p in members)
        display = (
            f"🎯【概率簇输出 · {_type_cn.get(cluster_type, cluster_type)}】{cluster_label}\n"
            f"簇成员: {_mem_text} | 簇总概率: {cluster_prob*100:.1f}%\n"
            f"簇内最优: {best_in_cluster}（保留传统双比分 {first_score}/{second_score} 作为簇内最优）"
            + ("\n⚡ KL散度高阈值触发：直接输出高概率比分集群，以分布空间抵抗单点风险" if kl_high else "")
        )
        return {
            'cluster_type': cluster_type, 'cluster_label': cluster_label,
            'members': members, 'cluster_prob': cluster_prob,
            'best_in_cluster': best_in_cluster, 'kl_triggered': kl_high,
            'display': display,
        }
    except Exception as _pc_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [架构升级②·概率簇] 构建异常(已降级): {_pc_err}")
        return _fallback()


# =====================================================================
# 【λ未形成 · NOT_FORMED 统一出口】
# 上游 pipeline 明确“不补默认进球期望”（λ 为 None），所以本文件里任何
# 涉及 λ 的算术/比较都必须先过这道闸：要么返回明确的未形成结果，要么
# 走已经 documented 的降级分支，绝不允许把 None 送进 `- lam` 这类表达式。
# =====================================================================
LAMBDA_NOT_FORMED = 'lambda_not_formed'
NOT_FORMED_SCORE = (None, None, LAMBDA_NOT_FORMED)
_LAMBDA_NOT_FORMED_REASONS = {
    'lambda_not_formed': 'λ 未形成（上游拒绝补默认进球期望）',
    'mobile_market_not_ready': '手机市均未就绪，λ 无法标定',
    'prob_matrix_empty': '比分概率矩阵未形成',
    'pool_not_formed': '15 进 2 候选池未形成',
}


def _one_lambda_ready(value):
    """单侧 λ 是否已形成（有限正数）。"""
    try:
        number = float(value)
    except (TypeError, ValueError):
        return False
    return math.isfinite(number) and number > 0


def lambda_ready(lam_h, lam_a):
    """两个 λ 都是有限正数才算“已形成”。"""
    return _one_lambda_ready(lam_h) and _one_lambda_ready(lam_a)


def lambda_not_formed_reason(lam_h, lam_a, prob_dict=None,
                             mobile_market_ready=None):
    """说明 λ 为什么没形成；返回可直接进结论段的短语（不含 traceback）。"""
    missing = []
    if not _one_lambda_ready(lam_h) and not _one_lambda_ready(lam_a):
        missing.append('λ 未形成')
    elif not _one_lambda_ready(lam_h):
        missing.append('主队 λ 未形成')
    elif not _one_lambda_ready(lam_a):
        missing.append('客队 λ 未形成')
    if missing:
        missing[0] = missing[0] + '（上游拒绝补默认进球期望）'
    parts = list(missing)
    if mobile_market_ready is False:
        parts.append('手机市均未就绪')
    if prob_dict is not None and not prob_dict:
        parts.append('比分概率矩阵为空')
    return '；'.join(parts) or '比分未形成'


def is_not_formed_result(first_score, second_score, note=None):
    """判断一处 15进2 输出是不是“未形成”，用于报告分流。"""
    if first_score not in (None, '') or second_score not in (None, ''):
        return False
    if note is None:
        return True
    return any(mark in str(note) for mark in (
        LAMBDA_NOT_FORMED, 'λ 未形成', '未形成', '数据不足',
    ))


def _safe_lambda(value, default=0.0):
    """λ 的数值安全转换：None/NaN/非数一律回落到 default（仅用于展示/门控）。"""
    try:
        number = float(value)
    except (TypeError, ValueError):
        return float(default)
    return number if math.isfinite(number) else float(default)


def _safe_odds(value, default=None):
    """赔率安全转换：非正数或不可转换时返回 default，避免 None 参与比较。"""
    try:
        number = float(value)
    except (TypeError, ValueError):
        return default
    if not math.isfinite(number) or number <= 0:
        return default
    return number


# =====================================================================
# 【架构升级①·结构化解析顺序（第五层/第六层）】
# 确立绝对的、从高维到低维的结构化解析顺序：
#   第1步 比分盈利矩阵（赔率体系的尽头，最大风险敲口与最完整庄家意图）
#   第2步 胜平负（1x2，方向层）
#   第3步 亚盘（让球强度层）
#   第4步 大小球盘（总进球期望层）
# 从比分盈利矩阵反推基础盘面属于降维分析：高维（比分）空间的庄家
# 意图投影到低维（1x2/亚盘/OU）后，若与低维盘面实际定价矛盾，
# 即可识别亚盘与胜平负中人为制造的“掩护”与“阻吓”。
# 本函数为纯特征/诊断提取器：不修改任何概率数值，输出结构化诊断
# 供 execute_15to2_matrix 消费，并写入 anomaly_payload_out。
# =====================================================================
def run_structured_parsing_order(prob_dict, odds_correct_score, odds_1x2_dict,
                                 asian_handicap, ou_line, lam_h=1.2, lam_a=0.9):
    """【架构升级①】高维→低维降维解析编排器。
    返回 dict：
      order: 固定解析顺序列表
      cs_matrix: 比分盈利矩阵层诊断（庄家盈利分布/风险敲口方向）
      wdl: 胜平负层诊断（高维反推 vs 市场定价差）
      ah: 亚盘层诊断（掩护识别）
      ou: 大小球层诊断（阻吓识别）
      cover_flags: 降维识别出的掩护/阻吓标记列表
      report_lines: 中文报告行
    全程降级保护：任何异常均返回 available=False，不影响主流程。"""
    out = {
        'available': False,
        'order': ['比分盈利矩阵', '胜平负', '亚盘', '大小球盘'],
        'cs_matrix': {}, 'wdl': {}, 'ah': {}, 'ou': {},
        'cover_flags': [], 'report_lines': [],
        'summary': '结构化解析顺序未执行（数据不足）。',
    }
    try:
        if not prob_dict:
            return out
        eps = 1e-9
        rl = ['🧭【结构化解析顺序 · 高维→低维降维分析】解析链：比分盈利矩阵→胜平负→亚盘→大小球']

        # ──── 第1步：比分盈利矩阵（最高维，赔率体系尽头） ────
        # 庄家视角：每个比分的“盈利贡献”≈ 理论概率×赔率-1（若有波胆赔率）；
        # 风险敲口 = 理论概率高但赔率压得深的比分（庄家主动防守的方向）。
        cs_diag = {'available': False}
        _dir_theory = {'home': 0.0, 'draw': 0.0, 'away': 0.0}
        _dir_market = {'home': 0.0, 'draw': 0.0, 'away': 0.0}
        _risk_scores = []       # (score, 理论%, 市场隐含%, 赔率, 风险敲口强度)
        _profit_rows = []
        _cs_market_raw = {}
        if isinstance(odds_correct_score, dict):
            for _sc, _od in odds_correct_score.items():
                try:
                    _odv = float(_od)
                    if _odv > 1.0:
                        _cs_market_raw[str(_sc).replace(':', '-').strip()] = 1.0 / _odv
                except Exception:  # noqa: BLE001,S112 - intentional degraded-mode guard or structure-preserving fallback  # nosec B112  # intentional degraded-mode continue fallback
                    continue
        _cs_market_total = sum(_cs_market_raw.values())
        for _sc, _p in prob_dict.items():
            try:
                _scs = str(_sc).replace(':', '-').strip()
                if '-' not in _scs or '其' in _scs:
                    continue
                _hg, _ag = parse_score(_scs)
                if _hg is None or _ag is None:
                    continue
                _d = 'home' if _hg > _ag else ('away' if _hg < _ag else 'draw')
                _dir_theory[_d] += float(_p)
                _mk_p = (_cs_market_raw.get(_scs, 0.0) / _cs_market_total) if _cs_market_total > 0 else None
                if _mk_p is not None:
                    _dir_market[_d] += _mk_p
                    # 庄家盈利期望（每1单位投注流入该比分时庄家的期望盈亏）
                    _odds_v = 1.0 / max(_mk_p * _cs_market_total, eps) if _cs_market_total > 0 else 0.0
                    _bk_profit = 1.0 - float(_p) * _odds_v
                    _profit_rows.append((_scs, round(_bk_profit, 4)))
                    # 风险敲口：理论高但市场隐含被压低（赔率偏高不敢收集）或反之
                    if float(_p) >= 0.04:
                        _risk_gap = _mk_p - float(_p)
                        _risk_scores.append((_scs, round(float(_p) * 100, 2),
                                             round(_mk_p * 100, 2), round(_odds_v, 2),
                                             round(_risk_gap * 100, 2)))
            except Exception:  # noqa: BLE001,S112 - intentional degraded-mode guard or structure-preserving fallback  # nosec B112  # intentional degraded-mode continue fallback
                continue
        # 庄家最大风险敲口方向 = 市场隐含占比相对理论超配最多的方向（收集了超额投注）
        _theory_total = sum(_dir_theory.values()) or 1.0
        _dir_theory_n = {k: v / _theory_total for k, v in _dir_theory.items()}
        _market_total = sum(_dir_market.values())
        _overload_dir, _shield_dir = '', ''
        if _market_total > 0.5:
            _dir_market_n = {k: v / _market_total for k, v in _dir_market.items()}
            _gaps = {k: _dir_market_n[k] - _dir_theory_n[k] for k in _dir_theory_n}
            _overload_dir = max(_gaps, key=lambda key: _gaps[key])   # 市场超配（庄家风险最大→防守端）
            _shield_dir = min(_gaps, key=lambda key: _gaps[key])     # 市场欠配（庄家盈利垫→可能被阻吓端）
            cs_diag = {
                'available': True,
                'dir_theory': {k: round(v, 4) for k, v in _dir_theory_n.items()},
                'dir_market': {k: round(v, 4) for k, v in _dir_market_n.items()},
                'dir_gaps': {k: round(v, 4) for k, v in _gaps.items()},
                'bookmaker_max_exposure_dir': _overload_dir,
                'bookmaker_profit_cushion_dir': _shield_dir,
                'risk_knock_scores': sorted(_risk_scores, key=lambda x: x[4])[:5],
                'bookmaker_profit_rows': sorted(_profit_rows, key=lambda x: x[1])[:5],
            }
            _dir_cn = {'home': '主胜', 'draw': '平局', 'away': '客胜'}
            rl.append(
                f"  ①比分盈利矩阵：市场超配方向={_dir_cn.get(_overload_dir, _overload_dir)}"
                f"（庄家最大风险敲口），欠配方向={_dir_cn.get(_shield_dir, _shield_dir)}"
                f"（庄家盈利垫/疑似阻吓端）"
            )
        else:
            cs_diag = {'available': False, 'reason': '波胆赔率缺失，仅用理论矩阵方向分布'}
            cs_diag['dir_theory'] = {k: round(v, 4) for k, v in _dir_theory_n.items()}
            rl.append('  ①比分盈利矩阵：波胆赔率缺失，降维反推仅基于理论矩阵方向分布')

        # ──── 第2步：胜平负（高维反推 vs 1x2 市场定价） ────
        wdl_diag = {'available': False}
        cover_flags = []
        try:
            if isinstance(odds_1x2_dict, dict):
                _oh = float(odds_1x2_dict.get('Home', 0) or 0)
                _od_ = float(odds_1x2_dict.get('Draw', 0) or 0)
                _oa = float(odds_1x2_dict.get('Away', 0) or 0)
                if _oh > 1.0 and _od_ > 1.0 and _oa > 1.0:
                    _imp = {'home': 1.0 / _oh, 'draw': 1.0 / _od_, 'away': 1.0 / _oa}
                    _imp_t = sum(_imp.values())
                    _imp_n = {k: v / _imp_t for k, v in _imp.items()}
                    _wdl_gap = {k: _imp_n[k] - _dir_theory_n.get(k, 0.0) for k in _imp_n}
                    wdl_diag = {
                        'available': True,
                        'implied_1x2': {k: round(v, 4) for k, v in _imp_n.items()},
                        'matrix_reversed': {k: round(_dir_theory_n.get(k, 0.0), 4) for k in _imp_n},
                        'gap_1x2_vs_matrix': {k: round(v, 4) for k, v in _wdl_gap.items()},
                    }
                    _dir_cn = {'home': '主胜', 'draw': '平局', 'away': '客胜'}
                    # 降维识别：1x2 定价与矩阵反推差距最大的方向若与矩阵盈利垫方向
                    # 重合 → 1x2 该方向存在人为掩护/阻吓嫌疑
                    _max_gap_dir = max(_wdl_gap, key=lambda k: abs(_wdl_gap[k]))
                    if abs(_wdl_gap[_max_gap_dir]) >= 0.06:
                        _flag_type = '掩护(人为抬价吸篹)' if _wdl_gap[_max_gap_dir] > 0 else '阻吓(人为压价驱离)'
                        _flag = {
                            'layer': '胜平负', 'direction': _max_gap_dir,
                            'type': _flag_type,
                            'gap': round(_wdl_gap[_max_gap_dir], 4),
                            'matrix_support': bool(_max_gap_dir == _shield_dir or _max_gap_dir == _overload_dir),
                        }
                        cover_flags.append(_flag)
                        rl.append(
                            f"  ②胜平负：{_dir_cn.get(_max_gap_dir, _max_gap_dir)}方向 1x2 定价与高维矩阵反推"
                            f"差距{_wdl_gap[_max_gap_dir]*100:+.1f}% → 疑似{_flag_type}"
                            f"{'（矩阵方向佐证）' if _flag['matrix_support'] else ''}"
                        )
                    else:
                        rl.append('  ②胜平负：1x2 定价与高维矩阵反推基本一致，无明显掩护/阻吓')
        except Exception as _wdl_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            rl.append(f'  ②胜平负：解析异常已跳过({_wdl_err})')

        # ──── 第3步：亚盘（高维反推净胜期望 vs 盘口） ────
        ah_diag = {'available': False}
        try:
            if asian_handicap is not None:
                _ah = float(asian_handicap)
                # 矩阵反推的期望净胜球差（主-客）
                _exp_margin = 0.0
                for _sc, _p in prob_dict.items():
                    try:
                        _scs = str(_sc).replace(':', '-').strip()
                        if '-' not in _scs or '其' in _scs:
                            continue
                        _hg, _ag = parse_score(_scs)
                        if _hg is None or _ag is None:
                            continue
                        _exp_margin += (_hg - _ag) * float(_p)
                    except Exception:  # noqa: BLE001,S112 - intentional degraded-mode guard or structure-preserving fallback  # nosec B112  # intentional degraded-mode continue fallback
                        continue
                # 亚盘盘口隐含净胜差 ≈ -asian_handicap（主让为负）
                _ah_implied_margin = -_ah
                _margin_gap = _exp_margin - _ah_implied_margin
                ah_diag = {
                    'available': True,
                    'matrix_expected_margin': round(_exp_margin, 4),
                    'ah_implied_margin': round(_ah_implied_margin, 4),
                    'margin_gap': round(_margin_gap, 4),
                }
                if abs(_margin_gap) >= 0.45:
                    _flag_type = ('掩护(盘口浅于矩阵真实强度，压盘防走热)'
                                  if _margin_gap > 0 else
                                  '阻吓(盘口深于矩阵真实强度，抬盘吸上盘)')
                    _flag = {
                        'layer': '亚盘',
                        'direction': 'home' if _margin_gap > 0 else 'away',
                        'type': _flag_type, 'gap': round(_margin_gap, 4),
                        'matrix_support': True,
                    }
                    cover_flags.append(_flag)
                    rl.append(
                        f"  ③亚盘：矩阵反推净胜期望{_exp_margin:+.2f}球 vs 盘口隐含{_ah_implied_margin:+.2f}球"
                        f"（差距{_margin_gap:+.2f}）→ 疑似{_flag_type}"
                    )
                else:
                    rl.append(
                        f"  ③亚盘：矩阵反推净胜期望{_exp_margin:+.2f}球与盘口隐含{_ah_implied_margin:+.2f}球一致，无掩护痕迹"
                    )
            else:
                rl.append('  ③亚盘：亚盘盘口未抓到，不拿默认盘比对。')
        except Exception as _ah_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            rl.append(f'  ③亚盘：解析异常已跳过({_ah_err})')

        # ──── 第4步：大小球盘（高维反推总进球期望 vs 盘口） ────
        ou_diag = {'available': False}
        try:
            if ou_line is not None:
                _ou = float(ou_line)
                _exp_total = 0.0
                for _sc, _p in prob_dict.items():
                    try:
                        _scs = str(_sc).replace(':', '-').strip()
                        if '-' not in _scs or '其' in _scs:
                            continue
                        _hg, _ag = parse_score(_scs)
                        if _hg is None or _ag is None:
                            continue
                        _exp_total += (_hg + _ag) * float(_p)
                    except Exception:  # noqa: BLE001,S112 - intentional degraded-mode guard or structure-preserving fallback  # nosec B112  # intentional degraded-mode continue fallback
                        continue
                _total_gap = _exp_total - _ou
                ou_diag = {
                    'available': True,
                    'matrix_expected_total': round(_exp_total, 4),
                    'ou_line': round(_ou, 2),
                    'total_gap': round(_total_gap, 4),
                }
                if abs(_total_gap) >= 0.4:
                    _flag_type = ('阻吓(盘口低于矩阵进球期望，小球盘吓阻大球盁)'
                                  if _total_gap > 0 else
                                  '掩护(盘口高于矩阵进球期望，大球盘掩护小球意图)')
                    _flag = {
                        'layer': '大小球',
                        'direction': 'over' if _total_gap > 0 else 'under',
                        'type': _flag_type, 'gap': round(_total_gap, 4),
                        'matrix_support': True,
                    }
                    cover_flags.append(_flag)
                    rl.append(
                        f"  ④大小球：矩阵反推总进球期望{_exp_total:.2f} vs 盘口{_ou:.2f}"
                        f"（差距{_total_gap:+.2f}）→ 疑似{_flag_type}"
                    )
                else:
                    rl.append(
                        f"  ④大小球：矩阵反推总进球期望{_exp_total:.2f}与盘口{_ou:.2f}一致，无阻吓痕迹"
                    )
            else:
                rl.append('  ④大小球：大小球盘口未抓到，不拿默认盘比对。')
        except Exception as _ou_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            rl.append(f'  ④大小球：解析异常已跳过({_ou_err})')

        _summary = (
            f"结构化解析顺序完成（比分盈利矩阵→胜平负→亚盘→大小球）："
            f"识别出{len(cover_flags)}个掩护/阻吓标记。"
        ) if cover_flags else '结构化解析顺序完成：各层定价自洽，未发现人为掩护/阻吓。'
        out.update({
            'available': True,
            'cs_matrix': cs_diag, 'wdl': wdl_diag, 'ah': ah_diag, 'ou': ou_diag,
            'cover_flags': cover_flags, 'report_lines': rl, 'summary': _summary,
        })
        return out
    except Exception as _spo_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [架构升级①·结构化解析顺序] 异常(已降级): {_spo_err}")
        out['summary'] = f'结构化解析顺序异常(已降级): {_spo_err}'
        return out


def execute_15to2_matrix(prob_dict, odds_1x2_dict, asian_handicap, ou_line,  # pyright: ignore[reportGeneralTypeIssues] - Pyright complexity limit; semantic split is unsafe in this monolithic decision matrix.
                         odds_correct_score=None, ai_report="",
                         lam_h=1.2, lam_a=0.9, cup_mode=False,
                         ai_fund_signal=None, ai_handicap_signal=None,
                         derived_markets=None, tg_implied_probs=None,
                         ev_results_ref=None, dynamic_context=None,
                         deepseek_game_signals=None,
                         llm_features=None, anomaly_payload_out=None,
                         euro_odds_500=None, api_football_odds_response=None,
                         league_name='', static_manipulation_score=0.0,
                         static_manipulation_details=None,
                         direction_lock_payload=None,
                         mobile_market_ready=None):
    """
    【核心算法】15进2矩阵 × 核心博弈论模型
    四阶漏斗：3%铁律强切 → 宏观资金主盘绞杀 → 核心博弈论过滤 → 双波胆锁定
    参数:
        prob_dict: 泊松概率字典 {比分: 概率}
        odds_1x2_dict: 胜平负赔率 {'Home': x, 'Draw': x, 'Away': x}
        asian_handicap: 亚盘让球值（负数=主让）
        ou_line: 大小球盘口
        odds_correct_score: 波胆赔率字典（可选）
        ai_report: DeepSeek生成的报告文本（用于信号提取）
        lam_h, lam_a: 主客队进球期望值（用于古诺模型等）。可以是 None：
            上游 pipeline 在进球期望未形成时明确不补默认 λ，此时本函数
            不抛异常，直接返回未形成结果 (None, None, 'lambda_not_formed')。
        cup_mode: 是否淘汰赛模式（影响零和/非零和博弈权重）
        ai_fund_signal: 第一步资金分析提取的信号字典（可选）
            {'fund_direction': 'home'|'away'|'neutral',
             'fund_anomaly': True|False,
             'profit_bias': 'home'|'away'|'draw'|'neutral'}
        ai_handicap_signal: 第二步盘口剖析提取的信号字典（可选）
            {'ah_direction': 'home'|'away'|'neutral',
             'ou_bias': 'over'|'under'|'neutral',
             'handicap_divergence': True|False,
             'retreat_direction': 'over'|'under'|None}
        deepseek_game_signals: DeepSeek Step3 结构化博弈论判断结果（可选）
        mobile_market_ready: 上游手机市均是否就绪（可选，只用于说明未形成原因）
    返回: (first_score, second_score, game_theory_log)

    【未形成契约】λ 未形成（任一侧为 None/非有限值）或 prob_dict 为空时：
        返回 (None, None, 'lambda_not_formed') 或 (None, None, 'prob_matrix_empty')。
        调用方据此出“数据不足”报告，不得把 None 当成 0.0 参与后续计算。
    """
    import re
    # =====================================================
    # 【Step 0·λ 未形成闸门】上游拒绝补默认进球期望时，这里必须显式返回
    # 未形成结果。曾在此处直接把 None 送进 abs(lam_h - lam_a)，导致
    # TypeError 让整场分析中断（15 场全崩）。闸门放在任何算术之前。
    # =====================================================
    _lam_reason = ''
    if not lambda_ready(lam_h, lam_a):
        _lam_reason = LAMBDA_NOT_FORMED
        print(
            "   ⏭️ [15进2] "
            + lambda_not_formed_reason(lam_h, lam_a, prob_dict, mobile_market_ready)
            + "：不计算比分，按数据不足回报"
        )
        if isinstance(anomaly_payload_out, dict):
            anomaly_payload_out['lambda_gate'] = {
                'available': False,
                'reason': _lam_reason,
                'detail': lambda_not_formed_reason(lam_h, lam_a, prob_dict, mobile_market_ready),
                'lam_h': lam_h if lam_h is not None else None,
                'lam_a': lam_a if lam_a is not None else None,
                'mobile_market_ready': mobile_market_ready,
            }
        return None, None, _lam_reason
    if not prob_dict:
        print("   ⏭️ [15进2] 比分概率矩阵未形成：不计算比分，按数据不足回报")
        if isinstance(anomaly_payload_out, dict):
            anomaly_payload_out['lambda_gate'] = {
                'available': False,
                'reason': 'prob_matrix_empty',
                'detail': _LAMBDA_NOT_FORMED_REASONS['prob_matrix_empty'],
                'lam_h': _safe_lambda(lam_h),
                'lam_a': _safe_lambda(lam_a),
                'mobile_market_ready': mobile_market_ready,
            }
        return None, None, 'prob_matrix_empty'
    # 闸门之后才允许进入数值域：此处两个 λ 一定已是有限正数。
    lam_h = float(lam_h)
    lam_a = float(lam_a)
    # =====================================================
    # 【Step 1】直接使用 Dixon-Coles 泊松矩阵作为基座，不再做三模型融合；决策统一由 DeviationDrivenEngine 完成
    # =====================================================


    # 初始化结构化信号
    if ai_fund_signal is None:
        ai_fund_signal = {}
    if ai_handicap_signal is None:
        ai_handicap_signal = {}

    log_steps = []

    # =====================================================
    # 【架构升级①·结构化解析顺序】绝对高维→低维降维解析：
    # 任何计算前先从比分盈利矩阵自上而下分析，接着胜平负，
    # 再亚盘，最后大小球盘；降维反推识别人为“掩护”与“阻吓”。
    # 诊断结果写入 anomaly_payload_out['structured_parsing']，
    # 供后续漏斗与 AI 报告消费；不修改任何概率数值。
    # =====================================================
    structured_parsing = None
    try:
        structured_parsing = run_structured_parsing_order(
            prob_dict, odds_correct_score, odds_1x2_dict,
            asian_handicap, ou_line, lam_h=lam_h, lam_a=lam_a,
        )
        if structured_parsing and structured_parsing.get('available'):
            for _spo_line in structured_parsing.get('report_lines', []):
                print(f"   {_spo_line}")
            log_steps.append(
                "A-1结构化解析顺序(比分盈利矩阵→胜平负→亚盘→大小球):掩护/阻吓标记{}个".format(
                    len(structured_parsing.get('cover_flags', []) or [])
                )
            )
        else:
            log_steps.append("A-1结构化解析顺序:数据不足已降级跳过")
        if isinstance(anomaly_payload_out, dict):
            anomaly_payload_out['structured_parsing'] = structured_parsing
    except Exception as _spo_exc:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [架构升级①·结构化解析顺序] 接入异常(已降级): {_spo_exc}")
        structured_parsing = None

    _static_decision_score = 0.0
    _static_decision_gate = 0.0
    _static_decision_details = {}
    try:
        _static_decision_score = max(0.0, min(1.0, float(static_manipulation_score or 0.0)))
        _static_decision_gate = max(0.0, min(0.75, _static_decision_score))
        _static_decision_details = (
            dict(static_manipulation_details)
            if isinstance(static_manipulation_details, dict) else {}
        )
        _static_decision_details['score'] = _static_decision_score
        _static_decision_details['market_noise_gate'] = _static_decision_gate
        log_steps.append(
            f"A0静态诱导:分值={_static_decision_score:.4f}/市场噪音门控={_static_decision_gate:.4f}"
        )
    except Exception as _static_decision_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        _static_decision_score = 0.0
        _static_decision_gate = 0.0
        _static_decision_details = {
            'available': False,
            'score': 0.0,
            'market_noise_gate': 0.0,
            'reason': f'static_decision_input_failed:{_static_decision_err}',
        }

    # =====================================================
    # 【】三级异常检测管道：在底层泊松矩阵计算完毕后、
    # 进入15进2选池/博弈论过滤之前对 prob_dict 做剪枝。
    # 缺数据时安全降级，不影响原有流程。
    # =====================================================
    try:
        prob_dict_pre_anomaly = dict(prob_dict or {})
        pruned_prob_dict, anomaly_pipeline_payload = run_anomaly_detection_pipeline(
            prob_dict_pre_anomaly,
            odds_1x2_dict=odds_1x2_dict,
            asian_handicap=asian_handicap,
            ou_line=ou_line,
            derived_markets=derived_markets,
            llm_features=llm_features,
            ai_handicap_signal=ai_handicap_signal,
            dynamic_context=dynamic_context,
            # 【紧急修复·第二道免疫防线】透传 ai_fund_signal 用于 Squeeze 豁免识别
            ai_fund_signal=ai_fund_signal,
        )
    except Exception as _ano_exc:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        prob_dict_pre_anomaly = dict(prob_dict or {})
        pruned_prob_dict = prob_dict_pre_anomaly
        anomaly_pipeline_payload = {
            'spread': {'available': False},
            'stagnation': {'available': False},
            'pruning': {'available': False},
            'summary': {
                'spread_1x2_ah': 0.0, 'spread_ah_ou': 0.0,
                'is_divergent': False, 'is_stagnation': False,
                'strategy_mode': 'hunt_trap', 'trap_flag': False,
                'public_heat_flag': False, 'pruned_score_count': 0,
                # 【紧急修复·第二道免疫防线】降级垄化填充字段，防止上游 .get 报错
                'squeeze_exempt': False, 'squeeze_return_rate': 0.0,
                'boosted_score_count': 0,
                'exception': str(_ano_exc),
            },
        }

    _ano_summary = anomaly_pipeline_payload.get('summary', {})
    try:
        anomaly_pipeline_payload['static_manipulation'] = dict(_static_decision_details)
        if isinstance(_ano_summary, dict):
            _ano_summary['static_manipulation_score'] = _static_decision_score
            _ano_summary['static_market_noise_gate'] = _static_decision_gate
    except Exception as _static_payload_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        log_steps.append(f"A0静态诱导载荷异常(已降级):{_static_payload_err}")
    log_steps.append(
        "A0异常检测:spread1x2_ah={:.3f}/spreadAH_OU={:.3f}/{}/{}/剪枝{}个".format(
            float(_ano_summary.get('spread_1x2_ah', 0.0)),
            float(_ano_summary.get('spread_ah_ou', 0.0)),
            '滞止' if _ano_summary.get('is_stagnation') else '常态',
            '陷阱' if _ano_summary.get('trap_flag') else '无陷阱',
            int(_ano_summary.get('pruned_score_count', 0)),
        )
    )
    # 【紧急修复·第二道免疫防线】机构逼空(Squeeze) 豁免走入控台日志
    try:
        if _ano_summary.get('squeeze_exempt'):
            log_steps.append(
                "A0.5Squeeze豁免:返还率{:.1f}%+顺势升盘，陷阱警报已解除，顺势波胆提权{}个".format(
                    float(_ano_summary.get('squeeze_return_rate', 0.0)),
                    int(_ano_summary.get('boosted_score_count', 0)),
                )
            )
    except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [异常已捕获·pass降级 L19072] {_silent_err}")

    # 将剪枝后的概率作为后续15进2与博弈论过滤的真实输入
    prob_dict = pruned_prob_dict

    # =====================================================

    # =====================================================
    # 【止血补丁三·前置守门】体育逻辑 vs 金融逻辑分离
    # 在 K-Means 聚类 / 陷阱预警激活之前，先用纯泊松基本面计算一个
    # 「是否允许激活阴谋论/诱导陷阱分支」的开关：
    #   - 只有当两队基本面差距极小（|λ_h - λ_a| < 0.3）且总进球较低（λ_total < 3.0）
    #     时，才允许后续逻辑覆写到陷阱/低比分；
    #   - 实力悬殊（|λ_h - λ_a| >= 1.0）或火力极猛（λ_total >= 3.0）时，
    #     强制走正向 EV 击穿逻辑，禁止陷阱预警覆写。
    # 该开关回写至 anomaly_pipeline_payload，供陷阱模块读取。
    # =====================================================
    try:
        _bp3_lam_h = float(lam_h or 0.0)
        _bp3_lam_a = float(lam_a or 0.0)
        _bp3_lam_total = _bp3_lam_h + _bp3_lam_a
        _bp3_lam_gap = abs(_bp3_lam_h - _bp3_lam_a)
        _bp3_allow_trap = (_bp3_lam_gap < 0.3) and (_bp3_lam_total < 3.0)
        _bp3_force_offensive = (_bp3_lam_total >= 3.0) or (_bp3_lam_gap >= 1.0)
        _bp3_reason = ''
        if _bp3_force_offensive:
            _bp3_reason = (
                f"λ_total={_bp3_lam_total:.2f}"
                f"{'≥3.0(火力极猛)' if _bp3_lam_total >= 3.0 else ''}"
                f"{' / ' if (_bp3_lam_total >= 3.0 and _bp3_lam_gap >= 1.0) else ''}"
                f"{'|Δλ|=' + format(_bp3_lam_gap, '.2f') + '≥1.0(实力悬殊)' if _bp3_lam_gap >= 1.0 else ''}"
            )
        anomaly_pipeline_payload['fundamental_gate'] = {
            'lam_h': _bp3_lam_h,
            'lam_a': _bp3_lam_a,
            'lam_total': _bp3_lam_total,
            'lam_gap': _bp3_lam_gap,
            'allow_trap_branch': bool(_bp3_allow_trap),
            'force_offensive_ev': bool(_bp3_force_offensive),
            'reason': _bp3_reason,
        }
        if _bp3_force_offensive:
            log_steps.append(
                f"A0.4基本面守门(止血补丁三):强制正向EV[{_bp3_reason}]→禁陷阱覆写"
            )
    except Exception as _bp3_exc:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        anomaly_pipeline_payload['fundamental_gate'] = {
            'available': False,
            'allow_trap_branch': True,
            'force_offensive_ev': False,
            'reason': f'fundamental_gate异常({_bp3_exc})',
        }

    # =====================================================

    # 通过外部传入的可变容器（dict/list）回传中间变量，便于上层 Step3 prompt 使用
    if isinstance(anomaly_payload_out, dict):
        try:
            anomaly_payload_out.clear()
            anomaly_payload_out.update(anomaly_pipeline_payload)
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L19133] {_silent_err}")
    elif isinstance(anomaly_payload_out, list):
        try:
            anomaly_payload_out.clear()
            anomaly_payload_out.append(anomaly_pipeline_payload)
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L19139] {_silent_err}")
    # ===== 【竞彩足球官方比分范围】严格限制为31种标准比分 ======
    # 使用全局常量 JCZQ_STANDARD_SCORES，超出范围的概率归入"其它"类
    BASE_31 = JCZQ_STANDARD_SCORES  # 28种标准比分 + 其它类

    # 构建全量候选池：仅保留竞彩范围内的比分，超出部分归入"其它"
    all_scores_in_prob = set(prob_dict.keys())
    # 过滤：只保留竞彩标准范围内的比分
    all_candidate_scores = [s for s in list(set(BASE_31) | all_scores_in_prob) if s in JCZQ_VALID_SET]
    # 超出范围的比分概率累加到"其它"类
    _oth_home, _oth_draw, _oth_away = 0.0, 0.0, 0.0
    for s in all_scores_in_prob:
        if s not in JCZQ_VALID_SET and '-' in s:
            try:
                _h, _a = parse_score(s)
                _p = prob_dict.get(s, 0.0)
                if _h > _a: _oth_home += _p
                elif _h == _a: _oth_draw += _p
                else: _oth_away += _p
            except (ValueError, TypeError):
                pass
    candidates = {}
    for s in all_candidate_scores:
        candidates[s] = prob_dict.get(s, 0.0)

    # ===== 计算波胆隐含概率（如有波胆赔率）=====
    cs_implied = {}
    if odds_correct_score and len(odds_correct_score) >= 3:
        total_inv = sum(1.0 / v for v in odds_correct_score.values() if v > 0)
        if total_inv > 0:
            for s in all_candidate_scores:
                if s in odds_correct_score and odds_correct_score[s] > 0:
                    cs_implied[s] = (1.0 / odds_correct_score[s]) / total_inv
                else:
                    cs_implied[s] = 0.0

    # ===== 解析AI信号（结构化信号优先，文本正则兑底） =====
    ai_signals = []

    # 优先从结构化信号字典提取（三步串联流程传入）
    # Step1 庄家敞口信号
    fund_dir = ai_fund_signal.get('fund_direction', '')
    fund_anomaly = ai_fund_signal.get('fund_anomaly', False)
    profit_bias = ai_fund_signal.get('profit_bias', '')
    exposure_direction = ai_fund_signal.get('exposure_direction', fund_dir)  # 庄家敞口方向
    exposure_score = ai_fund_signal.get('exposure_score', '')                # 资金最集中比分
    defense_focus = ai_fund_signal.get('defense_focus', '')                  # 庄家防守重点
    fund_concentration = ai_fund_signal.get('fund_concentration', 'medium')  # 资金集中程度
    # Step2 升降水轨迹信号
    ah_dir = ai_handicap_signal.get('ah_direction', '')
    ou_bias = ai_handicap_signal.get('ou_bias', '')
    handicap_div = ai_handicap_signal.get('handicap_divergence', False)
    retreat_dir = ai_handicap_signal.get('retreat_direction', None)
    ah_trajectory = ai_handicap_signal.get('ah_trajectory', 'neutral')       # 亚指轨迹
    ou_trajectory = ai_handicap_signal.get('ou_trajectory', 'neutral')       # 大小球轨迹
    synergy = ai_handicap_signal.get('synergy', False)                        # 两者是否协同
    divergence_strength = ai_handicap_signal.get('divergence_strength', 'none')  # 背离强度
    trap_signal = ai_handicap_signal.get('trap_signal', False)                # 陷阱信号
    ah_change_magnitude = ai_handicap_signal.get('ah_change_magnitude', 0.0)  # 亚指变化幅度
    ou_change_magnitude = ai_handicap_signal.get('ou_change_magnitude', 0.0)  # 大小球变化幅度

    dynamic_context = dynamic_context or {}
    signal_strength = max(0.50, float(dynamic_context.get('signal_strength', 1.0) or 1.0))
    dynamic_dti = max(0.0, float(dynamic_context.get('dynamic_dti', 0.0) or 0.0))
    market_volatility = max(0.0, float(dynamic_context.get('market_volatility', 0.0) or 0.0))

    deepseek_game_signals = deepseek_game_signals or {}
    deepseek_game_signals = {
        normalize_game_theory_model_name(k): v
        for k, v in deepseek_game_signals.items()
        if normalize_game_theory_model_name(k) in GAME_THEORY_RETAINED_MODELS
    }
    model_compare_summary = {
        model: {
            'code_scores': set(),
            'ds_scores': list(dict.fromkeys((deepseek_game_signals.get(model, {}) or {}).get('matching_scores', []) or [])),
            'ds_triggered': bool((deepseek_game_signals.get(model, {}) or {}).get('triggered', False)),
            'agreements': 0,
            'conflicts': 0,
            'ds_only': 0,
            'cross_delta': 0.0,
        }
        for model in GAME_THEORY_RETAINED_MODELS
    }

    def _track_model_compare(model_name, score, code_triggered, code_adjustment, cv_result):
        canonical = normalize_game_theory_model_name(model_name)
        summary = model_compare_summary.setdefault(canonical, {
            'code_scores': set(), 'ds_scores': [], 'ds_triggered': False,
            'agreements': 0, 'conflicts': 0, 'ds_only': 0, 'cross_delta': 0.0,
        })
        if code_triggered:
            summary['code_scores'].add(score)
        if cv_result.get('ds_matched') and score not in summary['ds_scores']:
            summary['ds_scores'].append(score)
        compare_state = cv_result.get('compare_state', '')
        if '一致' in compare_state:
            summary['agreements'] += 1
        elif ('矛盾' in compare_state) or ('降权' in compare_state):
            summary['conflicts'] += 1
        elif 'DS补充' in compare_state:
            summary['ds_only'] += 1
        summary['cross_delta'] += float(cv_result.get('final_adjustment', 0.0)) - (float(code_adjustment) if code_triggered else 0.0)


    # 资金方向信号
    if fund_dir == 'home' or exposure_direction == 'home':
        ai_signals.append("资金→主")
    elif fund_dir == 'away' or exposure_direction == 'away':
        ai_signals.append("资金→客")
    # 资金异动信号
    if fund_anomaly or fund_concentration == 'high':
        ai_signals.append("资金异动")
    # 盈亏偏向信号
    if profit_bias in ('home', 'away', 'draw'):
        bias_label = {'home': '主', 'away': '客', 'draw': '平'}.get(profit_bias, profit_bias)
        ai_signals.append(f"盈亏→{bias_label}")
    # 庄家防守重点信号
    if defense_focus in ('home_win', 'away_win', 'draw'):
        focus_label = {'home_win': '主胜', 'away_win': '客胜', 'draw': '平局'}.get(defense_focus, defense_focus)
        ai_signals.append(f"防守→{focus_label}")

    # 盘口方向信号
    if ou_bias == 'under' or ou_trajectory == 'under_strengthen':
        ai_signals.append("低进球")
    elif ou_bias == 'over' or ou_trajectory == 'over_strengthen':
        ai_signals.append("高进球")
    # 盘口背离信号
    if handicap_div or divergence_strength in ('strong', 'medium'):
        ai_signals.append("盘口背离")
    # 退水方向信号
    if retreat_dir == 'under' or ou_trajectory == 'under_strengthen':
        ai_signals.append("退水→小")
    elif retreat_dir == 'over' or ou_trajectory == 'over_strengthen':
        ai_signals.append("退水→大")
    # 亚指轨迹信号
    if ah_trajectory == 'home_strengthen':
        ai_signals.append("亚指强主")
    elif ah_trajectory == 'home_weaken':
        ai_signals.append("亚指弱主")
    # 协同信号
    if synergy:
        ai_signals.append("协同信号")
    # 陷阱信号
    if trap_signal:
        ai_signals.append("陷阱预警")

    # 兑底：从 ai_report 文本中正则提取（兼容无结构化信号的场景）
    if ai_report and not ai_fund_signal and not ai_handicap_signal:
        fund_home_pats = [r'资金流向主队', r'主队资金占优', r'资金涌入主队', r'主胜资金']
        fund_away_pats = [r'资金流向客队', r'客队资金占优', r'资金涌入客队', r'客胜资金']
        low_goal_pats = [r'小球', r'低进球', r'防守型', r'火力不足', r'进攻乏力']
        high_goal_pats = [r'大球', r'高进球', r'进攻型', r'对攻', r'进球大战']
        trap_pats = [r'诱盘', r'陷阱', r'庄家诱多', r'大众情人']
        for pat in fund_home_pats:
            if re.search(pat, ai_report):
                ai_signals.append("资金→主")
                break
        for pat in fund_away_pats:
            if re.search(pat, ai_report):
                ai_signals.append("资金→客")
                break
        for pat in low_goal_pats:
            if re.search(pat, ai_report):
                ai_signals.append("低进球")
                break
        for pat in high_goal_pats:
            if re.search(pat, ai_report):
                ai_signals.append("高进球")
                break
        for pat in trap_pats:
            if re.search(pat, ai_report):
                ai_signals.append("诱盘警告")
                break

    # =====================================================
    # 第一阶：动态生成15个待选比分（从全量prob_dict筛选）
    # 规则：概率>3%的比分全部入围，超过15个取概率最高直15个，不足则补充概率最高的比分
    # =====================================================
    THRESHOLD_3PCT = 0.03
    THRESHOLD_5PCT = 0.05
    THRESHOLD_8PCT = 0.08

    # 按泊松概率降序排序全量候选
    sorted_all_cands = sorted(candidates.items(), key=lambda x: x[1], reverse=True)

    # 筛选概率>3%的比分
    above_3pct = [(s, p) for s, p in sorted_all_cands if p > THRESHOLD_3PCT]
    # 其余比分（用于补充）
    below_3pct = [(s, p) for s, p in sorted_all_cands if p <= THRESHOLD_3PCT]

    # 确定15个待选比分
    if len(above_3pct) >= 15:
        # 超过15个：取概率最高直15个
        pool_15 = above_3pct[:15]
        supplemented_scores = set()  # 无补充项
    else:
        # 不足则补充（标注这些是补充项）
        pool_15 = above_3pct[:]
        supplement_needed = 15 - len(pool_15)
        supplemented_scores = set()
        for s, p in below_3pct:
            if supplement_needed <= 0:
                break
            pool_15.append((s, p))
            supplemented_scores.add(s)
            supplement_needed -= 1

    # 构建待选比分字典
    step1_pool = {s: p for s, p in pool_15}
    log_steps.append(f"A1动态筛选:{len(sorted_all_cands)}→{len(step1_pool)}(其中{len(above_3pct)}个>3%,补充{len(supplemented_scores)}个)")

    # =====================================================
    # 第二阶：15个比分统一归为“可能比分波胆”
    # 保留 sig_support 作为后续博弈论选取的内部支持度评分
    # =====================================================

    def _signal_support_score(s):
        """计算信号支持强度，供后续博弈论选取与排序参考。"""
        h, a = parse_score(s)
        if h is None or a is None:
            return 0.0
        total_g = h + a
        direction = _score_direction_home_draw_away(s)
        support = 0

        # sig_support 动态阈值（sigmoid）：
        #   sig_support_multiplier = 1 / (1 + exp(-10 * (DTI - 0.08)))
        # 强化 DTI > 0.08 场次的信号权重（快速趋近 1），低DTI 场次衰减到 ≈ 0。
        # 同时保留  复盘改进#5 的 fusion_strength 修正作为辅助加权。
        _dti_val = float(dynamic_context.get('dynamic_dti', 0.0))
        _fusion_val = float(dynamic_context.get('fusion_strength', 0.0))
        _sig_multiplier = 1.0
        try:
            # 核心动态阈值公式
            _sig_multiplier = 1.0 / (1.0 + math.exp(-10.0 * (_dti_val - 0.08)))
            # 辅助：fusion_strength 足够高时额外加权，低于 5% 时表示信号不足不衰减过多
            if _fusion_val > 0.05:
                _sig_multiplier *= max(1.0, min(2.0, _fusion_val / 0.05))
            # 上下界保护
            _sig_multiplier = max(0.05, min(2.5, _sig_multiplier))
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            # 异常时回退到原  逻辑
            if _dti_val > 0.4 and _fusion_val > 0.05:
                _sig_multiplier = (1.0 / (1.0 + math.exp(-10.0 * (_dti_val - 0.4)))) * (_fusion_val / 0.05)
            else:
                _sig_multiplier = 0.1

        # Step1庄家敞口信号
        if exposure_direction == 'home' and direction == 'Home' or exposure_direction == 'away' and direction == 'Away' or exposure_direction == 'draw' and direction == 'Draw':
            support += 0.3
        if exposure_score and s == exposure_score:
            support += 0.5
        if defense_focus == 'home_win' and direction == 'Home' or defense_focus == 'away_win' and direction == 'Away' or defense_focus == 'draw' and direction == 'Draw':
            support += 0.3

        # 泊松概率内部排名奖励（侧重数学模型而非市场）
        prob = step1_pool.get(s, 0)
        sorted_probs = sorted(step1_pool.values(), reverse=True)
        if prob in sorted_probs[:3]:
            support += 2  # 概率前3名
        elif prob in sorted_probs[:7]:
            support += 1  # 概率前7名

        # Step2升降水轨迹信号
        if synergy:
            if ah_trajectory == 'home_strengthen' and ou_trajectory == 'under_strengthen':
                if direction == 'Home' and total_g <= 2:
                    support += 2
            elif ah_trajectory == 'home_weaken' and ou_trajectory == 'under_strengthen':
                if direction == 'Away' and total_g <= 2:
                    support += 2
            elif ah_trajectory == 'home_strengthen' and ou_trajectory == 'over_strengthen':
                if direction == 'Home' and total_g >= 3:
                    support += 2
            elif ah_trajectory == 'home_weaken' and ou_trajectory == 'over_strengthen':  # noqa: SIM102 - intentional degraded-mode guard or structure-preserving fallback
                if direction == 'Away' and total_g >= 3:
                    support += 2
        elif ah_trajectory == 'home_strengthen' and direction == 'Home' or ah_trajectory == 'home_weaken' and direction == 'Away':
            support += 1
        if ou_trajectory == 'under_strengthen' and total_g <= 2 or ou_trajectory == 'over_strengthen' and total_g >= 3:
            support += 1

        # 【复盘改进#5】统一乘上 sigmoid(DTI_new,fusion_strength) 信号乘子
        support = float(support) * float(_sig_multiplier)

        return support

    # 全部15个比分统一纳入“可能比分波胆”池
    group_possible = []
    sig_support_map = {}
    supplement_flags = {}
    for s, p in pool_15:
        is_supplement = s in supplemented_scores
        sig_support = _signal_support_score(s)
        sig_support_map[s] = sig_support
        supplement_flags[s] = is_supplement
        group_possible.append((s, p, sig_support, is_supplement))

    group_possible.sort(key=lambda x: (x[1], x[2]), reverse=True)

    def _score_gap_dir(s):
        """返回 (h, a, 分差, 方向标签)。"""
        h2, a2 = parse_score(s)
        gap = h2 - a2
        if gap > 0:
            dir_label = f'主胜{gap}球'
        elif gap < 0:
            dir_label = f'客胜{abs(gap)}球'
        else:
            dir_label = '平局'
        return h2, a2, gap, dir_label

    def _get_implied_prob(s):
        """获取比分 s 的隐含概率（优先 cs_implied，其次从赔率反推）。"""
        if cs_implied and s in cs_implied and cs_implied[s] > 0:
            return cs_implied[s]
        if odds_correct_score and s in odds_correct_score and odds_correct_score[s] > 0:
            return 1.0 / odds_correct_score[s]
        return None

    def _fmt_group(grp, show_odds=True):
        parts = []
        for s, p, sig, is_sup in grp:
            tag = '★' if sig >= 2 else ('▲' if sig >= 1 else '')
            sup_tag = '[补]' if is_sup else ''
            odds_tag = ''
            if show_odds:
                imp = _get_implied_prob(s)
                if imp and imp > 0:
                    odds_val = 1.0 / imp
                    imp_pct = imp * 100
                    odds_tag = f"/赔{odds_val:.1f}/隐{imp_pct:.1f}%"
            _, _, _gap, dir_label = _score_gap_dir(s)
            parts.append(f"{s}({p*100:.1f}%{odds_tag}分差:{dir_label}{tag}{sup_tag})")
        return ' / '.join(parts) if parts else '无'

    def _build_gap_analysis(grp, group_name):
        lines = [f"【{group_name}分差与隐含概率分析】"]
        for s, p, sig, is_sup in grp:
            _h2, _a2, gap, dir_label = _score_gap_dir(s)
            imp = _get_implied_prob(s)
            imp_str = f"{imp*100:.1f}%" if imp else '无数据'
            if imp:
                bias = p - imp
                bias_str = f"偏高{bias*100:.1f}%" if bias > 0.005 else (f"偏低{abs(bias)*100:.1f}%" if bias < -0.005 else '居中')
            else:
                bias_str = '无对比'
            lines.append(
                f"  {s}: 波松概率{p*100:.1f}% | 隐含概率{imp_str} | 偏差:{bias_str} | 分差:{dir_label}({gap:+d}) | 信号支持:{sig}"
            )
        return "\n".join(lines)

    gap_analysis_text = _build_gap_analysis(group_possible, '可能比分波胆')

    group_display = (
        f"〆15个可能比分波胆〇\n"
        f"▶ 可能比分波胆（{len(group_possible)}个）：{_fmt_group(group_possible, show_odds=True)}\n"
        f"\n{gap_analysis_text}"
    )
    log_steps.append(f"A2统一池:可能比分波胆{len(group_possible)}")

    step2_pool = {s: p for s, p, _, _ in group_possible}
    unlikely_scores = set()
    eligible_scores = {s for s, _, _, _ in group_possible}

    # =====================================================
    # 第三阶：核心博弈论过滤（已删除低贡献模型）
    # =====================================================
    game_theory_scores = {}
    triggered_models = []

    # 预计算辅助变量（赔率可能是 None/非数：统一走 _safe_odds，默认值参与比较，
    # 绝不让 None 进 abs() 或大小比较里）
    home_odd = _safe_odds(odds_1x2_dict.get('Home') if isinstance(odds_1x2_dict, dict) else None, 3.0)
    away_odd = _safe_odds(odds_1x2_dict.get('Away') if isinstance(odds_1x2_dict, dict) else None, 3.0)
    draw_odd = _safe_odds(odds_1x2_dict.get('Draw') if isinstance(odds_1x2_dict, dict) else None, 3.3)
    odds_gap = abs(home_odd - away_odd)
    ah = asian_handicap if asian_handicap is not None else 0.0
    ou = ou_line if ou_line is not None else None
    _derived_markets = derived_markets or {}
    tg_model_dist = _derived_markets.get('total_goals', {}) if _derived_markets else {}
    ou_model_dist = _derived_markets.get('ou', {}) if _derived_markets else {}
    tg_market_probs = tg_implied_probs or {}
    goal_dispersion_gap = 0.0
    if tg_model_dist and tg_market_probs:
        for tg_key in range(7):
            model_p = tg_model_dist.get(tg_key, tg_model_dist.get(str(tg_key), 0))
            market_p = tg_market_probs.get(f'prob_{tg_key}', 0)
            goal_dispersion_gap += abs(model_p - market_p)
        goal_dispersion_gap += abs(sum(v for k, v in tg_model_dist.items() if int(k) >= 7) - tg_market_probs.get('prob_7plus', 0))

    for s in step2_pool:
        h, a = parse_score(s)
        total_goals = h + a
        net_goals = h - a
        direction = 'Home' if h > a else ('Draw' if h == a else 'Away')
        poisson_p = candidates.get(s, 0.0)
        implied_p = cs_implied.get(s, 0.0) if cs_implied else 0.0
        gt_score = 0.0
        models_hit = []

        # ===== 结构化信号加权（来自三步串联的前两步） =====

        # ① Step1 庄家敞口方向加权：庄家敞口方向与比分方向一致
        exposure_match = False
        if exposure_direction == 'home' and direction == 'Home' or exposure_direction == 'away' and direction == 'Away' or exposure_direction == 'draw' and direction == 'Draw':
            exposure_match = True
        if exposure_match:
            gt_score += 0.06
            models_hit.append("敞口匹配+6%")

        # ② 庄家防守重点加权：防守重点与比分方向一致时加权
        defense_match = False
        if defense_focus == 'home_win' and direction == 'Home' or defense_focus == 'away_win' and direction == 'Away' or defense_focus == 'draw' and direction == 'Draw':
            defense_match = True
        if defense_match:
            gt_score += 0.03
            models_hit.append("防守匹配+3%")

        # ③ 资金集中比分加权：庄家资金最集中的具体比分与当前比分一致
        if exposure_score and s == exposure_score:
            models_hit.append("资金集中比分匹配")

        # ④ Step2 协同信号加权（+15%）：亚指与大小球协同且与比分方向一致
        synergy_match = False
        if synergy:
            # 主强化+小球强化 → 小比分主胜
            if ah_trajectory == 'home_strengthen' and ou_trajectory == 'under_strengthen':
                if direction == 'Home' and total_goals <= 2:
                    synergy_match = True
            # 主弱化+小球强化 → 小比分客胜
            elif ah_trajectory == 'home_weaken' and ou_trajectory == 'under_strengthen':
                if direction == 'Away' and total_goals <= 2:
                    synergy_match = True
            # 主强化+大球强化 → 大比分主胜
            elif ah_trajectory == 'home_strengthen' and ou_trajectory == 'over_strengthen':
                if direction == 'Home' and total_goals >= 3:
                    synergy_match = True
            # 主弱化+大球强化 → 大比分客胜
            elif ah_trajectory == 'home_weaken' and ou_trajectory == 'over_strengthen':  # noqa: SIM102 - intentional degraded-mode guard or structure-preserving fallback
                if direction == 'Away' and total_goals >= 3:
                    synergy_match = True
        if synergy_match:
            # gt_score += 0.15 # 删减主观加权
            models_hit.append("协同信号+15%")        # ⑤ 资金异动信号：异动时平局和小比分加权（庄家对冲风控）
        if fund_anomaly or fund_concentration == 'high':  # noqa: SIM102 - intentional degraded-mode guard or structure-preserving fallback
            if direction == 'Draw' or total_goals <= 1:
                models_hit.append("资金异动+")
        # 盈亏偏向信号：庄家盈亏方向与比分方向一致时加权
        if profit_bias == 'home' and direction == 'Home':
            gt_score += 0.03 * signal_strength
            models_hit.append("盈亏主+")
        elif profit_bias == 'away' and direction == 'Away':
            gt_score += 0.03 * signal_strength
            models_hit.append("盈亏客+")
        elif profit_bias == 'draw' and direction == 'Draw':
            gt_score += 0.03 * signal_strength
            models_hit.append("盈亏平+")
        # 盘口背离信号：背离时平局和小分差比分加权
        if handicap_div or divergence_strength in ('strong', 'medium'):  # noqa: SIM102 - intentional degraded-mode guard or structure-preserving fallback
            if direction == 'Draw' or abs(net_goals) <= 1:
                models_hit.append("背离+")
        # 退水方向信号加权
        if (retreat_dir == 'under' or ou_trajectory == 'under_strengthen') and total_goals <= 2:
            models_hit.append("退水小+")
        elif (retreat_dir == 'over' or ou_trajectory == 'over_strengthen') and total_goals >= 3:
            models_hit.append("退水大+")

        # ===== 保留的核心博弈模型（其余低贡献模型已删除） =====

        # 1. 囚徒困境：双方赔率接近 → 平局/谨慎比赛受益
        prisoner_triggered = odds_gap < 0.45 and direction == 'Draw'
        prisoner_adjust = 0.0
        prisoner_cv = apply_game_theory_cross_validation('囚徒困境', s, prisoner_triggered, prisoner_adjust, deepseek_game_signals)
        gt_score += prisoner_cv['final_adjustment']
        _track_model_compare('囚徒困境', s, prisoner_triggered, prisoner_adjust, prisoner_cv)
        if prisoner_triggered or prisoner_cv['ds_matched']:
            models_hit.append('囚徒')

        # 2. 纳什均衡：净胜球≈亚盘让球 且 总进球≈大小球盘口
        nash_net_fit = 0.0
        nash_total_fit = 0.0
        nash_bonus = 0.0
        nash_triggered = nash_bonus > 0.08
        nash_adjust = nash_bonus if nash_triggered else 0.0
        nash_cv = apply_game_theory_cross_validation('纳什均衡', s, nash_triggered, nash_adjust, deepseek_game_signals)
        gt_score += nash_cv['final_adjustment']
        _track_model_compare('纳什均衡', s, nash_triggered, nash_adjust, nash_cv)
        if nash_triggered or nash_cv['ds_matched']:
            models_hit.append('纳什')

        # 2a. 模型-市场总进球偏离：保留为基础纠偏器
        if goal_dispersion_gap > 0.5:
            gt_score -= 0.20
            models_hit.append('进球严重偏离⚠️⚠️')
        elif goal_dispersion_gap > 0.3:
            # gt_score -= 0.10 # 删减主观加权
            models_hit.append('进球离散⚠️')

        # 2b. 总进球纠偏对比：总进球分布EV + 大小球一致性
        if total_goals >= 7:
            tg_model_prob = sum(v for k, v in tg_model_dist.items() if int(k) >= 7) if tg_model_dist else 0
            tg_market_prob = tg_market_probs.get('prob_7plus') if tg_market_probs else None
        else:
            tg_model_prob = tg_model_dist.get(total_goals, tg_model_dist.get(str(total_goals), 0)) if tg_model_dist else 0
            tg_market_prob = tg_market_probs.get(f'prob_{total_goals}') if tg_market_probs else None

        tg_ev_label = '中性'
        ou_consistency = '中性'

        if tg_market_prob is not None and tg_market_prob > 0 and tg_model_prob > 0:
            if tg_model_prob > tg_market_prob * 1.2:
                # gt_score += 0.18 # 删减主观加权
                tg_ev_label = '价值+'
                models_hit.append('总进球价值+')
            elif tg_model_prob < tg_market_prob * 0.8:
                # gt_score -= 0.15 # 删减主观加权
                tg_ev_label = '高估-'
                models_hit.append('总进球高估-')

        if ou is None:
            ou_consistency = '盘口未抓到'
        elif total_goals > ou and ou_model_dist.get('over', 0) > 0.55:
            ou_consistency = '大球吻合+'
            models_hit.append('大球吻合+')
        elif total_goals < ou and ou_model_dist.get('under', 0) > 0.55:
            ou_consistency = '小球吻合+'
            models_hit.append('小球吻合+')
        elif total_goals == ou:
            ou_consistency = '走水'

        # 3. 斗鸡博弈：陷阱/强背离时，平局与小分差比分更值得防守
        chicken_weight = 0.12
        if trap_signal or divergence_strength == 'strong':
            chicken_weight = 0.22
        chicken_triggered = direction == 'Draw' or abs(net_goals) == 1
        chicken_adjust = 0.0
        chicken_cv = apply_game_theory_cross_validation('斗鸡博弈', s, chicken_triggered, chicken_adjust, deepseek_game_signals)
        gt_score += chicken_cv['final_adjustment']
        _track_model_compare('斗鸡博弈', s, chicken_triggered, chicken_adjust, chicken_cv)
        if chicken_triggered or chicken_cv['ds_matched']:
            models_hit.append('斗鸡')

        # 4. 零和/非零和：杯赛压平，联赛开放平局与守和
        zero_sum_triggered = direction == 'Draw'
        zero_sum_adjust = 0.0
        if cup_mode and direction == 'Draw':
            zero_sum_adjust = 0.0
        elif (not cup_mode) and direction == 'Draw':
            zero_sum_adjust = 0.0 # 删减主观加权
        zero_sum_cv = apply_game_theory_cross_validation('零和/非零和', s, zero_sum_triggered, zero_sum_adjust, deepseek_game_signals)
        gt_score += zero_sum_cv['final_adjustment']
        _track_model_compare('零和/非零和', s, zero_sum_triggered, zero_sum_adjust, zero_sum_cv)
        if zero_sum_triggered or zero_sum_cv['ds_matched']:
            models_hit.append('零和-' if zero_sum_cv['final_adjustment'] < 0 else '非零和')

        # 5. 斯塔克尔伯格：让球方具备先动优势
        stack_triggered = False
        stack_adjust = 0.0
        if ah < 0 and direction == 'Home':
            stack_fit = max(0, 1 - abs(net_goals - abs(ah)))
            if stack_fit > 0.5:
                stack_triggered = True
        elif ah > 0 and direction == 'Away':
            stack_fit = max(0, 1 - abs(abs(net_goals) - abs(ah)))
            if stack_fit > 0.5:
                stack_triggered = True
        stack_cv = apply_game_theory_cross_validation('斯塔克尔伯格', s, stack_triggered, stack_adjust, deepseek_game_signals)
        gt_score += stack_cv['final_adjustment']
        _track_model_compare('斯塔克尔伯格', s, stack_triggered, stack_adjust, stack_cv)
        if stack_triggered or stack_cv['ds_matched']:
            models_hit.append('斯塔克')

        # 6. 古诺：双方 λ 接近时，更关注接近期望值的比分
        cournot_triggered = abs(lam_h - lam_a) < 0.65
        cournot_fit = max(0, 1 - abs(h - lam_h) * 0.3 - abs(a - lam_a) * 0.3) if cournot_triggered else 0.0
        cournot_adjust = 0.0
        cournot_cv = apply_game_theory_cross_validation('古诺', s, cournot_triggered, cournot_adjust, deepseek_game_signals)
        gt_score += cournot_cv['final_adjustment']
        _track_model_compare('古诺', s, cournot_triggered, cournot_adjust, cournot_cv)
        if (cournot_triggered and cournot_fit > 0.3) or cournot_cv['ds_matched']:
            models_hit.append('古诺')

        # 7. 信号博弈：动态信号强度直接影响盘口信号的权重
        signal_weight = (0.08 + market_volatility * 0.03) * signal_strength
        if trap_signal or divergence_strength == 'strong':
            signal_weight *= 1.5
        signal_triggered = False
        if ah_trajectory != 'neutral' or ou_trajectory != 'neutral':
            if ah_trajectory == 'home_strengthen' and direction == 'Home' or ah_trajectory == 'home_weaken' and direction == 'Away':
                signal_triggered = True
            if ou_trajectory == 'under_strengthen' and total_goals <= 2:
                models_hit.append('信号小')
            elif ou_trajectory == 'over_strengthen' and total_goals >= 3:
                models_hit.append('信号大')
        elif ai_report:
            signal_pat = re.search(r'(?:盘口.*(?:升|降|变化|移动)|(?:升盘|降盘|升水|退水))', ai_report)
            if signal_pat:  # noqa: SIM102 - intentional degraded-mode guard or structure-preserving fallback
                if (ah < 0 and direction == 'Home') or (ah > 0 and direction == 'Away'):
                    signal_triggered = True
        signal_adjust = signal_weight if signal_triggered else 0.0
        signal_cv = apply_game_theory_cross_validation('信号博弈', s, signal_triggered, signal_adjust, deepseek_game_signals)
        gt_score += signal_cv['final_adjustment']
        _track_model_compare('信号博弈', s, signal_triggered, signal_adjust, signal_cv)
        if signal_triggered or signal_cv['ds_matched']:
            models_hit.append('信号')

        # 8. 鹰鸽博弈：强弱分明时，小胜/不败比分更合理
        hawk_dove_triggered = False
        hawk_dove_adjust = 0.0
        if odds_gap > 0.90:  # noqa: SIM102 - intentional degraded-mode guard or structure-preserving fallback
            if (home_odd < away_odd and direction == 'Home' and net_goals <= 2) or                (away_odd < home_odd and direction == 'Away' and abs(net_goals) <= 2):
                hawk_dove_triggered = True
        hawk_dove_cv = apply_game_theory_cross_validation('鹰鸽博弈', s, hawk_dove_triggered, hawk_dove_adjust, deepseek_game_signals)
        gt_score += hawk_dove_cv['final_adjustment']
        _track_model_compare('鹰鸽博弈', s, hawk_dove_triggered, hawk_dove_adjust, hawk_dove_cv)
        if hawk_dove_triggered or hawk_dove_cv['ds_matched']:
            models_hit.append('鹰鸽')
        # ===== 新增8个博弈模型 =====
        # 9. 逆向选择：庄家利用信息优势设置诱盘，大热比分赔率异常低时触发
        adverse_triggered = False
        adverse_adjust = 0.0
        if odds_correct_score and s in odds_correct_score:
            cs_odd = odds_correct_score[s]
            if cs_odd > 0 and poisson_p > 0:
                fair_odd = 1.0 / poisson_p
                # 赔率显著低于公平值（庄家压低大热）→ 逆向选择降权
                if cs_odd < fair_odd * 0.80 and poisson_p > 0.08:
                    adverse_triggered = True
                # 赔率显著高于公平值（庄家抬高冷门）→ 可能是真实价值
                elif cs_odd > fair_odd * 1.30 and poisson_p > 0.04:
                    adverse_triggered = True
                    adverse_adjust = 0.0 # 删减主观加权 * signal_strength
        adverse_cv = apply_game_theory_cross_validation('逆向选择', s, adverse_triggered, adverse_adjust, deepseek_game_signals)
        gt_score += adverse_cv['final_adjustment']
        _track_model_compare('逆向选择', s, adverse_triggered, adverse_adjust, adverse_cv)
        if adverse_triggered or adverse_cv['ds_matched']:
            models_hit.append('逆向选择')
        # 10. 信息不对称：庄家与玩家信息差异——资金异动+盘口背离同时出现时触发
        info_asym_triggered = False
        info_asym_adjust = 0.0
        if (fund_anomaly or fund_concentration == 'high') and (handicap_div or divergence_strength in ('strong', 'medium')):
            # 庄家有内幕信息，资金和盘口同时异动
            if direction == 'Draw':
                info_asym_triggered = True
            elif (fund_dir == 'home' and direction == 'Away') or (fund_dir == 'away' and direction == 'Home'):
                info_asym_triggered = True
                info_asym_adjust = 0.0 # 删减主观加权 * signal_strength  # 资金与结果反向 = 庄家诱导
        info_asym_cv = apply_game_theory_cross_validation('信息不对称', s, info_asym_triggered, info_asym_adjust, deepseek_game_signals)
        gt_score += info_asym_cv['final_adjustment']
        _track_model_compare('信息不对称', s, info_asym_triggered, info_asym_adjust, info_asym_cv)
        if info_asym_triggered or info_asym_cv['ds_matched']:
            models_hit.append('信息不对称')
        # 11. 最大最小（Minimax）：庄家最小化最大损失——选择低赔付结果
        minimax_triggered = False
        minimax_adjust = 0.0
        # 波胆赔率可能是 None/非数：先过 _safe_odds，None 不参与 > < 比较
        _cs_clean = {
            _k: _safe_odds(_v)
            for _k, _v in (odds_correct_score or {}).items()
            if _safe_odds(_v) is not None
        } if isinstance(odds_correct_score, dict) else {}
        if _cs_clean:
            # 找出庄家赔付最少的比分（赔率最低）
            min_odd_score = min(_cs_clean, key=lambda k: _cs_clean[k])
            min_odd_val = _cs_clean.get(min_odd_score, 999.0)
            if s == min_odd_score and min_odd_val < 8.0:
                minimax_triggered = True
            elif _cs_clean.get(s, 0.0) > 0:
                current_odd = _cs_clean[s]
                # 庄家愿意高赔的比分 = 庄家认为不太可能，但如果波松概率还不错则有价值
                if current_odd > 15.0 and poisson_p > 0.05:
                    minimax_triggered = True
                    minimax_adjust = 0.0 # 删减主观加权 * signal_strength
        minimax_cv = apply_game_theory_cross_validation('最大最小', s, minimax_triggered, minimax_adjust, deepseek_game_signals)
        gt_score += minimax_cv['final_adjustment']
        _track_model_compare('最大最小', s, minimax_triggered, minimax_adjust, minimax_cv)
        if minimax_triggered or minimax_cv['ds_matched']:
            models_hit.append('最大最小')
        # 12. 混合策略纳什：当胜平负概率接近时，混合策略均衡——平局和小分差受益
        mixed_nash_triggered = False
        mixed_nash_adjust = 0.0
        if home_odd > 0 and away_odd > 0 and draw_odd > 0:
            # 计算胜平负概率分布的熔（用赔率倒数归一化）
            inv_sum = (1/home_odd + 1/draw_odd + 1/away_odd)
            p_h = (1/home_odd) / inv_sum
            p_d = (1/draw_odd) / inv_sum
            p_a = (1/away_odd) / inv_sum
            # 熔值：三方概率接近时熔值高
            entropy = -(p_h * math.log(p_h + 1e-9) + p_d * math.log(p_d + 1e-9) + p_a * math.log(p_a + 1e-9))
            max_entropy = math.log(3)  # 均匀分布的最大熔
            entropy_ratio = entropy / max_entropy
            if entropy_ratio > 0.92:  # 接近均匀分布  # noqa: SIM102 - intentional degraded-mode guard or structure-preserving fallback
                if direction == 'Draw' or abs(net_goals) <= 1:
                    mixed_nash_triggered = True
                    mixed_nash_adjust = 0.0 # 删减主观加权 * signal_strength * entropy_ratio
        mixed_nash_cv = apply_game_theory_cross_validation('混合策略纳什', s, mixed_nash_triggered, mixed_nash_adjust, deepseek_game_signals)
        gt_score += mixed_nash_cv['final_adjustment']
        _track_model_compare('混合策略纳什', s, mixed_nash_triggered, mixed_nash_adjust, mixed_nash_cv)
        if mixed_nash_triggered or mixed_nash_cv['ds_matched']:
            models_hit.append('混合策略')
        # 13. 贝叶斯博弈：利用先验信息（伤停、战意、近况）更新后验概率
        bayes_triggered = False
        bayes_adjust = 0.0
        # 当波松概率与市场隐含概率偏差较大时，贝叶斯更新可能有价值
        if implied_p > 0 and poisson_p > 0:
            ratio = implied_p / poisson_p
            if ratio > 1.5:  # 市场认为比模型高很多，可能有未反映的信息
                bayes_triggered = True
                bayes_adjust = 0.0 # 删减主观加权 * signal_strength * min(ratio - 1.0, 1.0)
            elif ratio < 0.5:  # 市场认为比模型低很多，可能有负面信息
                bayes_triggered = True
        bayes_cv = apply_game_theory_cross_validation('贝叶斯博弈', s, bayes_triggered, bayes_adjust, deepseek_game_signals)
        gt_score += bayes_cv['final_adjustment']
        _track_model_compare('贝叶斯博弈', s, bayes_triggered, bayes_adjust, bayes_cv)
        if bayes_triggered or bayes_cv['ds_matched']:
            models_hit.append('贝叶斯')
        # 14. 序贯博弈：盘口变动的时序信号——亚指和大小球变化方向一致时触发
        seq_triggered = False
        seq_adjust = 0.0
        # 两个盘口同时向同一方向变动 = 序贯信号
        if ah_change_magnitude > 0 and ou_change_magnitude > 0:
            # 亚指和大小球同时变动，且方向一致
            if ah_trajectory == 'home_strengthen' and ou_trajectory == 'under_strengthen':
                # 主队加强 + 小球加强 → 小比分主胜
                if direction == 'Home' and total_goals <= 2:
                    seq_triggered = True
            elif ah_trajectory == 'home_weaken' and ou_trajectory == 'over_strengthen':
                # 主队削弱 + 大球加强 → 大比分客胜
                if direction == 'Away' and total_goals >= 3:
                    seq_triggered = True
            elif ah_trajectory != 'neutral' and ou_trajectory != 'neutral':
                # 其他组合也算序贯信号，但权重较低
                seq_triggered = True
                seq_adjust = 0.0 # 删减主观加权 * signal_strength
        seq_cv = apply_game_theory_cross_validation('序贯博弈', s, seq_triggered, seq_adjust, deepseek_game_signals)
        gt_score += seq_cv['final_adjustment']
        _track_model_compare('序贯博弈', s, seq_triggered, seq_adjust, seq_cv)
        if seq_triggered or seq_cv['ds_matched']:
            models_hit.append('序贯')
        # 15. 重复博弈：历史交锋模式——同一对手反复出现的结果模式
        repeat_triggered = False
        repeat_adjust = 0.0
        # 利用波松概率与隐含概率的一致性作为“历史重复”的代理指标
        if implied_p > 0 and poisson_p > 0:
            consistency = 1.0 - abs(implied_p - poisson_p) / max(implied_p, poisson_p)
            if consistency > 0.80 and poisson_p > 0.06:
                # 模型与市场高度一致 = 历史模式稳定重复
                repeat_triggered = True
                repeat_adjust = 0.0 # 删减主观加权 * signal_strength * consistency
            elif consistency < 0.40 and poisson_p > 0.05:
                # 模型与市场严重分歧 = 历史模式被打破
                repeat_triggered = True
        repeat_cv = apply_game_theory_cross_validation('重复博弈', s, repeat_triggered, repeat_adjust, deepseek_game_signals)
        gt_score += repeat_cv['final_adjustment']
        _track_model_compare('重复博弈', s, repeat_triggered, repeat_adjust, repeat_cv)
        if repeat_triggered or repeat_cv['ds_matched']:
            models_hit.append('重复')
        # 16. 演化博弈：市场趋势演化——当前赔率趋势与波松偏差方向一致时触发
        evo_triggered = False
        evo_adjust = 0.0
        # 演化稳定策略（ESS）：市场波动低 + 模型/市场一致 = 稳定均衡
        if market_volatility < 0.3 and implied_p > 0 and poisson_p > 0:
            if abs(implied_p - poisson_p) / max(implied_p, poisson_p) < 0.20:
                evo_triggered = True
                evo_adjust = 0.0 # 删减主观加权 * signal_strength  # 稳定均衡加权
        # 演化突变：市场波动高 + 盘口背离 = 新策略入侵
        elif market_volatility > 0.6 and (handicap_div or divergence_strength == 'strong'):  # noqa: SIM102 - intentional degraded-mode guard or structure-preserving fallback
            if direction == 'Draw' or (total_goals >= 3 and direction != 'Draw'):
                evo_triggered = True
                evo_adjust = 0.0 # 删减主观加权 * signal_strength  # 突变环境下非常规结果受益
        evo_cv = apply_game_theory_cross_validation('演化博弈', s, evo_triggered, evo_adjust, deepseek_game_signals)
        gt_score += evo_cv['final_adjustment']
        _track_model_compare('演化博弈', s, evo_triggered, evo_adjust, evo_cv)
        if evo_triggered or evo_cv['ds_matched']:
            models_hit.append('演化')
        game_theory_scores[s] = {
            'gt_total': gt_score,
            'models': models_hit,
            'poisson_p': poisson_p,
            'implied_p': implied_p,
            'tg_model_prob': tg_model_prob,
            'tg_market_prob': tg_market_prob,
            'tg_ev_label': tg_ev_label,
            'ou_consistency': ou_consistency,
        }

    # 取博弈综合分前4名（从全部15个可能比分波胆中取）
    sorted_gt = sorted(game_theory_scores.items(), key=lambda x: (x[1]['gt_total'], sig_support_map.get(x[0], 0)), reverse=True)
    eligible_gt = [(s, info) for s, info in sorted_gt if s in eligible_scores]
    fallback_gt = [(s, info) for s, info in sorted_gt if s not in eligible_scores]
    step3_pool = dict((eligible_gt + fallback_gt)[:4])

    def _score_sort_key(s):
        """比分排序键：按总进球数升序，同总进球按主队进球降序"""
        try:
            h, a = parse_score(s)
            return (h + a, -h)
        except (ValueError, AttributeError):
            return (99, 0)

    if deepseek_game_signals:
        compare_lines = []
        print('   ♟️ [DeepSeek博弈论判断 vs 代码硬编码判断]')
        for model in GAME_THEORY_RETAINED_MODELS:
            summary = model_compare_summary.get(model, {})
            code_scores = sorted(summary.get('code_scores', set()), key=_score_sort_key)[:3]
            ds_scores = sorted(set(summary.get('ds_scores', [])), key=_score_sort_key)[:3]
            if code_scores and ds_scores and set(code_scores) & set(ds_scores):
                verdict = '一致加强'
            elif code_scores and ds_scores:
                verdict = '矛盾降权/取均值'
            elif code_scores and not ds_scores:
                verdict = '代码单边'
            elif ds_scores and not code_scores:
                verdict = 'DeepSeek补充'
            else:
                verdict = '未触发'
            delta = summary.get('cross_delta', 0.0)
            line = f"{model}: DS={ds_scores if ds_scores else ['未触发']} | 代码={code_scores if code_scores else ['未触发']} | 结论={verdict} | 交叉调整Δ={delta:+.3f}"
            compare_lines.append(line)
            print(f"      - {line}")
        log_steps.append('A3-DS交叉:' + ' || '.join(compare_lines[:3]))

    # 收集触发的主要模型
    all_models = set()
    for s, info in list(step3_pool.items()):
        all_models.update(info['models'])
    triggered_models = list(all_models)

    log_steps.append(f"A3博弈:{len(step2_pool)}→{len(step3_pool)}(核心模型:{'|'.join(triggered_models[:5])})")
    code_game_signals = {}
    for model, summary in model_compare_summary.items():
        scores = sorted(str(item) for item in (summary.get('code_scores') or set()) if item)
        if not scores:
            continue
        code_game_signals[model] = {
            'model': model,
            'triggered': True,
            'matching_scores': scores[:8],
            'source': 'code',
        }
    if isinstance(anomaly_payload_out, dict):
        anomaly_payload_out['game_theory_code_signals'] = code_game_signals
        anomaly_payload_out['game_theory_code_signal_count'] = len(code_game_signals)

    # =====================================================
    # 第四阶：陷阱预警检测 + 反向分析（REVERSE_ANALYSIS）
    # 如果检测到陷阱信号，从候选比分中找出利于庄家的比分
    # =====================================================

    # ----- 陷阱预警判断（多维综合研判：庄家敎口+盈亏分析+返还率） -----
    # 返还率硬口径：先归一为 0~1，再转百分数比较（>1.5 视为已是百分数）
    try:
        from odds_index_math import normalize_return_rate, return_rate_pct
        _rr_frac = normalize_return_rate(ai_fund_signal.get('return_rate_avg', 0.0))
        return_rate_avg = float(return_rate_pct(_rr_frac) or 0.0)
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return_rate_avg = float(ai_fund_signal.get('return_rate_avg', 0.0) or 0.0)
        if 0 < return_rate_avg <= 1.5:
            return_rate_avg *= 100.0
    # 偏高(>97%)资金集中；偏低(<93%)水钱偏厚
    rr_anomaly_high = return_rate_avg > 97.0 if return_rate_avg > 0 else False
    rr_anomaly_low = return_rate_avg < 93.0 if return_rate_avg > 0 else False
    rr_anomaly = rr_anomaly_high or rr_anomaly_low

    # 盈亏分析：profit_bias与exposure_direction是否矛盾（庄家盈亏方向与投注方向相反）
    profit_exposure_conflict = (
        profit_bias and exposure_direction and
        profit_bias != 'neutral' and exposure_direction != 'neutral' and
        profit_bias != exposure_direction
    )

    synergy_text = str(ai_handicap_signal.get('synergy_signal', ''))  # 应对字符串形式
    trap_keywords = ['反向', '陷阱', '诱导', '诱盘', '庄家误导']
    synergy_trap = any(kw in synergy_text for kw in trap_keywords)

    # 欧赔暗示方向
    odds_home = odds_1x2_dict.get('Home', 2.0) if odds_1x2_dict else 2.0
    odds_away = odds_1x2_dict.get('Away', 2.0) if odds_1x2_dict else 2.0
    odds_implied_dir = 'home' if odds_home < odds_away else ('away' if odds_away < odds_home else 'neutral')

    # 核心三维判断（必须同时满足，缺一不可）

    # 维度一：庄家敎口方向（庄家敎口方向已明确且非中性）
    cond_exposure = bool(exposure_direction and exposure_direction not in ('', 'neutral'))

    # 维度二：盈亏偏向（profit_bias已明确且非中性）
    # 盈亏偏向与敎口方向矛盾时陷阱信号更强，但即便一致也计入维度二
    cond_profit = bool(profit_bias and profit_bias not in ('', 'neutral'))

    # 维度三：返还率异常（偏高>97% 或 偏低<93%）
    cond_rr = rr_anomaly

    # 陷阱预警激活规则：庄家敗口方向 + 盈亏偏向 + 返还率异常，三者必须同时满足
    trap_activated = cond_exposure and cond_profit and cond_rr

    # =====================================================
    # 【核心修复】调用自适应弹性逼空引擎 (Adaptive Squeeze Engine)
    # 升级点：
    #   - 废除  写死的返还率 92.5% 阈值与二值判断。
    #   - 三维度评分（RR 下杀 50% / 亚盘动能 30% / 资金烈度 20%）产出 0-100 逼空指数。
    #   - 五大联赛 94% 基准、其他联赛 92% 基准，防御误杀与假阳。
    #   - 方向合规性校验：exposure_dir 与 ah_trajectory 必须同向。
    #   - is_squeeze=True 时强制解除 trap_activated，并将所有字段写入 anomaly_payload_out
    #     给下游 operations_research_prediction 中的 Squeeze 提权逻辑使用。
    # =====================================================
    is_squeeze = False
    squeeze_dir = ''
    squeeze_score = 0.0
    squeeze_reason = ''
    _v92_rr = 0.0  # 保留同名变量，为下游报告/旧调用者向后兼容
    try:
        _v92_rr = float(return_rate_avg or 0.0)
        # 调用  自适应弹性逼空引擎
        is_squeeze, squeeze_dir, squeeze_score, squeeze_reason = detect_adaptive_squeeze(
            ai_fund_signal,
            ai_handicap_signal,
            league_name,
        )
        _sq_lock_scores = []
        try:
            if direction_lock_payload and DeepSeekAnalyzer is not None:
                _sq_lk = DeepSeekAnalyzer.matrix_direction_lock(direction_lock_payload)
                _sq_locked = {'胜': 'home', '平': 'draw', '负': 'away'}.get(_sq_lk.get('direction') or '')
                _sq_lock_scores = [
                    str(s).replace(':', '-').strip()
                    for s in (_sq_lk.get('scores') or [])
                    if str(s or '').strip()
                ]
                if is_squeeze and _sq_locked and squeeze_dir and squeeze_dir != _sq_locked:
                    print(f"   🔒 [方向锁] 逼空方向不改向 {squeeze_dir} → {_sq_locked}")
                    squeeze_dir = _sq_locked
        except Exception as _sq_lock_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [方向锁] 逼空方向未收口: {_sq_lock_err}")

        # 逻辑分流：是真实逼空时不可能是陷阱，强制解除陷阱预警
        if is_squeeze:
            if trap_activated:
                log_steps.append(
                    f"V9.5Squeeze引擎强制解除陷阱:dir={squeeze_dir}/score={squeeze_score:.1f}"
                )
            trap_activated = False
            cond_a = False
            cond_b = False
            print(
                f"   🚨 [风控纠偏·] 发现庄家关门逼空 (Squeeze)！方向={squeeze_dir}，"
                f"逼空分={squeeze_score:.1f}，强制解除陷阱预警，启动顺势穿盘提权！"
            )
            print(f"   🚨 [逼空细节] {squeeze_reason}")
        else:
            # 未命中逼空时保留原始陷阱逻辑
            trap_activated = cond_exposure and cond_profit and cond_rr
            if squeeze_reason:
                log_steps.append(f"V9.5Squeeze引擎未触发:{squeeze_reason}")

        # 将逼空状态写入全局 payload，供下游 operations_research_prediction 提权使用
        if isinstance(anomaly_payload_out, dict):
            anomaly_payload_out['is_squeeze'] = is_squeeze
            anomaly_payload_out['squeeze_dir'] = squeeze_dir
            anomaly_payload_out['squeeze_score'] = squeeze_score
            anomaly_payload_out['squeeze_reason'] = squeeze_reason
            anomaly_payload_out['squeeze_return_rate'] = _v92_rr
            if trap_activated:
                anomaly_payload_out['ultimate_trap_active'] = True
                anomaly_payload_out['ultimate_trap_bait'] = (exposure_direction or '').lower()
            else:
                # 没激活陷阱时显式置 False，避免读到旧值
                anomaly_payload_out['ultimate_trap_active'] = False
                if 'ultimate_trap_bait' not in anomaly_payload_out:
                    anomaly_payload_out['ultimate_trap_bait'] = ''
    except Exception as _v95_squeeze_exc:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [Adaptive Squeeze] 识别异常，安全降级: {_v95_squeeze_exc}")

    # =====================================================
    # 【基本面 λ 绝对否决权】 (针对“2-4 惨案 / 绝对对攻局被强行按成 1-1”的修复)
    # 如果赛前的基本面总进球期望极高 (λ_h + λ_a >= 3.0) 或市场大小球盘口极深 (ou_line >= 3.0)，
    # 坚决剥夺系统将比赛定性为“沉闷平局/诱盘小球”的权力——绝对的火力面前，没有阴谋。
    # 注：与下方“止血补丁三”协同；本块负责“基本面热战否决”，补丁三负责
    # “fundamental_gate.force_offensive_ev 强制正向 EV”，二者互补。
    # =====================================================
    try:
        _v91_lam_h = float(lam_h or 0.0)
        _v91_lam_a = float(lam_a or 0.0)
        expected_total_firepower = _v91_lam_h + _v91_lam_a
        try:
            _v91_ou_line = float(ou_line) if ou_line is not None else 0.0
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            _v91_ou_line = 0.0
        if trap_activated and (expected_total_firepower >= 3.0 or _v91_ou_line >= 3.0):
            print(
                f"   🛡️ [风控否决·] 陷阱预警原已激活，但双方火力期望极高 "
                f"(λ={expected_total_firepower:.2f}, OU={_v91_ou_line})，"
                f"强制取消反向平局诱导，尊重对攻基本面！"
            )
            log_steps.append(
                f"A0.5风控否决:λ_total={expected_total_firepower:.2f}/OU={_v91_ou_line}≥3.0，trap强制关闭"
            )
            trap_activated = False
            # 同步关闭辅助信号，避免后续误激活
            cond_a = False
            cond_b = False
            # 高波动比分提权，让 31 节点的“对攻型”候选自然冒头
            try:
                if isinstance(anomaly_payload_out, dict):
                    _cm_payload_v91 = anomaly_payload_out.get('cross_market', {}) or {}
                    _cm_payload_v91['high_volatility_boost'] = max(
                        2.0, float(_cm_payload_v91.get('high_volatility_boost', 1.0) or 1.0)
                    )
                    anomaly_payload_out['cross_market'] = _cm_payload_v91
            except Exception as _v91_boost_exc:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                print(f"   ⚠️ [风控否决·] high_volatility_boost 写入异常: {_v91_boost_exc}")
    except Exception as _v91_veto_exc:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [风控否决·] 基本面 λ 绝对否决权异常，安全降级: {_v91_veto_exc}")

    # =====================================================
    # 【止血补丁三·陷阱预警前置守门】体育逻辑 vs 金融逻辑分离
    # 读取上游计算的 fundamental_gate：若基本面裁定为「强制正向 EV」
    # （火力极猛/实力悬殊），则无条件熜灭陷阱预警激活。
    # =====================================================
    fundamental_gate_block = False
    fundamental_gate_reason = ''
    try:
        _fg = (anomaly_pipeline_payload or {}).get('fundamental_gate', {}) or {}
        if _fg.get('force_offensive_ev'):
            if trap_activated:
                fundamental_gate_block = True
                fundamental_gate_reason = _fg.get('reason', '')
                log_steps.append(
                    f"A5陷阱预警被基本面否决(止血补丁三):{fundamental_gate_reason}"
                )
                print(
                    f"   ⚠️ [止血补丁三] 基本面否决陷阱预警激活：{fundamental_gate_reason}"
                )
            trap_activated = False
            cond_a = False
            cond_b = False
    except Exception as _bp3_trap_exc:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [止血补丁三] 陷阱预警守门异常: {_bp3_trap_exc}")

    # 辅助信号（不参与激活判断，但用于陷阱类型描述和置信度增强）
    # 全部显式布尔化：exposure_direction 可能是空串，`'' and ...` 会返回 ''，
    # 后面 sum([cond_a, cond_b, cond_c]) 就会炸（TypeError: int + str）。
    cond_a = bool(bool(trap_signal) or bool(profit_exposure_conflict)) if 'trap_signal' in locals() else bool(profit_exposure_conflict)
    cond_b = bool(
        exposure_direction and exposure_direction != 'neutral'  # 赔率反向信号
        and exposure_direction != odds_implied_dir
        and exposure_direction in ('home', 'away')
    )
    cond_c = bool(synergy_trap)  # 盘口误导信号
    cond_d = bool(rr_anomaly)    # 返还率异常信号

    # 【改进#6】陷阱预警增强阈值：DTI < 0.15 且 预期总进球与实际分布偏差较大时追加触发。
    # 作为三维主判断之外的“补位阈值”，仅在 DTI 极低且总进球存在明显偏差时才论发，
    # 避免误伤。偏差代理量采用 |market_total - model_total|，数据缺失时安全降级。
    try:
        _ctx = dynamic_context or {}
        _v85_dti = float(_ctx.get('dynamic_dti', 0.0) or 0.0)
        _v85_market_total = None
        _v85_model_total = None
        if derived_markets and isinstance(derived_markets.get('total_goals'), dict):
            _tg_dist = derived_markets['total_goals']
            try:
                _v85_model_total = sum(float(k) * float(v) for k, v in _tg_dist.items())
            except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                _v85_model_total = None
        if tg_implied_probs and isinstance(tg_implied_probs, dict):
            try:
                _v85_market_total = sum(float(k) * float(v) for k, v in tg_implied_probs.items())
            except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                _v85_market_total = None
        if (
            _v85_model_total is not None
            and _v85_market_total is not None
            and _v85_dti > 0
            and _v85_dti < float(V85_TRAP_DTI_THRESHOLD)
        ):
            _v85_dev = abs(float(_v85_market_total) - float(_v85_model_total))
            if _v85_dev >= float(V85_TRAP_DEVIATION_THRESHOLD):
                # 【止血补丁三】基本面否决权同样适用于  增强陷阱途径
                _fg_v85 = (anomaly_pipeline_payload or {}).get('fundamental_gate', {}) or {}
                if _fg_v85.get('force_offensive_ev'):
                    fundamental_gate_block = True
                    fundamental_gate_reason = _fg_v85.get('reason', fundamental_gate_reason)
                    print(
                        f"   ⚠️ [止血补丁三] 基本面否决  陷阱增强追加触发：{fundamental_gate_reason}"
                    )
                elif is_squeeze:
                    # 【Squeeze 免疫阀】逼空局不可被  陷阱增强重新点亮
                    print(
                        f"   🚨 [Squeeze 免疫阀] DTI={_v85_dti:.3f}<{V85_TRAP_DTI_THRESHOLD} 且总进球偏差={_v85_dev:.2f}，"
                        f"但逼空局({squeeze_dir})互斥，拒绝追加触发陷阱！"
                    )
                else:
                    trap_activated = True
                    cond_a = True  # 提升辅助信号计数以增强置信度
                    print(
                        f"   ⚠️ [陷阱增强] DTI={_v85_dti:.3f}<{V85_TRAP_DTI_THRESHOLD} 且 总进球偏差={_v85_dev:.2f}≥0.8，追加触发陷阱预警"
                    )
                    # 同步更新 anomaly_payload_out 陷阱状态
                    if isinstance(anomaly_payload_out, dict):
                        anomaly_payload_out['ultimate_trap_active'] = True
                        anomaly_payload_out['ultimate_trap_bait'] = (exposure_direction or '').lower()
    except Exception as _e_v85_trap:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [陷阱增强] 阈值检测异常: {_e_v85_trap}")

    # 陷阱类型判断（多维组合描述）
    # 陷阱类型描述：三维核心判断结果展示
    rr_label = (f'返还率偏高({return_rate_avg:.1f}%)' if rr_anomaly_high
                else (f'返还率偏低({return_rate_avg:.1f}%)' if rr_anomaly_low
                      else f'返还率正常({return_rate_avg:.1f}%)'))
    trap_type_parts = [
        f'庄家敎口方向={exposure_direction}',
        f'盈亏偏向={profit_bias}{"(与敎口矛盾)" if profit_exposure_conflict else ""}',
        rr_label,
    ]
    # 辅助信号补充描述
    if cond_b:
        trap_type_parts.append(f'赔率反向(敎口={exposure_direction}与欧赔暗示={odds_implied_dir}相反)')
    if cond_c:
        trap_type_parts.append('盘口误导信号')
    trap_type = ' | '.join(trap_type_parts)

    # 陷阱置信度：三维全满为高，辅助信号越多置信度越高
    aux_count = sum([cond_a, cond_b, cond_c])  # 辅助信号数量
    if trap_activated:
        trap_confidence = '高' if aux_count >= 2 else ('中' if aux_count >= 1 else '低')
    else:
        trap_confidence = '未激活'

    # ----- 反向分析模块 -----
    reverse_analysis = None  # 无陷阱时为None
    if trap_activated:
        # 庄家利益比分筛选
        # 亚盘方向：让主队则庄家希望客队赢或平；让帧则庄家希望主队赢
        if ah is not None and ah < 0:  # 让主队（ah为负）
            bookie_favors = ['away', 'draw']  # 庄家希望客队赢或平
        elif ah is not None and ah > 0:  # 让帧队（ah为正）
            bookie_favors = ['home', 'draw']  # 庄家希望主队赢或平
        else:
            bookie_favors = ['draw']  # 平盘时庄家希望平局

        # 大小球修正：如果大小球线偏高(>2.75)，庄家希望小球
        ou_bookie_bias = 'under' if (ou and ou > 2.75) else ('over' if (ou and ou <= 2.25) else 'neutral')
        if ou_bookie_bias == 'under':
            ou_filter = lambda h, a: (h + a) <= 2  # 庄家希望小球
        elif ou_bookie_bias == 'over':
            ou_filter = lambda h, a: (h + a) >= 3  # 庄家希望大球
        else:
            ou_filter = lambda h, a: True

        # 欧赔结构：赔率最高的结果是庄家真正期望的
        if odds_1x2_dict:
            sorted_odds = sorted(odds_1x2_dict.items(), key=lambda x: x[1], reverse=True)
            highest_odds_dir = sorted_odds[0][0].lower() if sorted_odds else 'neutral'
            if highest_odds_dir == 'home':
                bookie_favors = list(set(bookie_favors + ['home']))
            elif highest_odds_dir == 'away':
                bookie_favors = list(set(bookie_favors + ['away']))
            elif highest_odds_dir == 'draw':
                bookie_favors = list(set(bookie_favors + ['draw']))

        # 从全部15个可能比分波胆中筛选庄家利益比分
        def _score_dir(s):
            h2, a2 = parse_score(s)
            if h2 > a2: return 'home'
            if h2 < a2: return 'away'
            return 'draw'

        def _score_gap(s):
            h2, a2 = parse_score(s)
            return abs(h2 - a2)

        def _score_total(s):
            h2, a2 = parse_score(s)
            return h2 + a2

        bookie_target_scores = []
        for s, _, sig_score, _ in group_possible:
            h2, a2 = parse_score(s)
            s_dir = _score_dir(s)
            if s_dir in bookie_favors and ou_filter(h2, a2):
                prob_val = step1_pool.get(s, candidates.get(s, 0))
                support_bonus = 1 + sig_support_map.get(s, 0) * 0.03
                bookie_target_scores.append((s, prob_val * support_bonus, _score_gap(s), _score_total(s)))

        # 按概率降序排序
        bookie_target_scores.sort(key=lambda x: x[1], reverse=True)

        # 分差区间分析：结合亚盘让球数判断最佳分差
        ah_abs = abs(ah) if ah else 0
        if ah_abs <= 0.25:
            ideal_gap = 0  # 平盘庄家希望平局或小分差
        elif ah_abs <= 0.75:
            ideal_gap = 1  # 让球小庄家希望分差=1
        elif ah_abs <= 1.25:
            ideal_gap = 1  # 让球中庄家希望分差=1
        elif ah_abs <= 1.75:
            ideal_gap = 2  # 让球大庄家希望分差=2
        else:
            ideal_gap = 2  # 大让球庄家希望大分差

        # 分差区间加权：分差与理想分差一致的比分额外加分
        def _gap_weight(gap):
            if gap == ideal_gap: return 1.3
            if abs(gap - ideal_gap) == 1: return 1.0
            return 0.7

        # 【复盘改进#3】分差函数中，预测与实际分差的托盘权重，
        # 对主胜场次提升至 1.5 倍（gap>0表示主队净胜，即主胜导向）。
        # 主胜场次识别依赖 ai_fund_signal/exposure_direction 与 ah_trajectory（与改进#2 保持一致）。
        _is_home_dominant_match = (
            (ai_fund_signal.get('exposure_direction') == 'home')
            or (ai_handicap_signal.get('ah_trajectory') == 'home_strengthen')
        )
        def _home_win_boost(_gap):
            return 1.5 if (_is_home_dominant_match and _gap > 0) else 1.0

        bookie_target_scores_weighted = [
            (s, prob * _gap_weight(gap) * _home_win_boost(gap), gap, total)
            for s, prob, gap, total in bookie_target_scores
        ]
        bookie_target_scores_weighted.sort(key=lambda x: x[1], reverse=True)

        # 取前3个庄家目标比分
        top_bookie = bookie_target_scores_weighted[:3]

        # 反向置信度评估
        if len(top_bookie) >= 2 and (cond_a or (cond_b and cond_c)):
            reverse_confidence = '高'
        elif len(top_bookie) >= 1 and (cond_a or cond_b or cond_c):
            reverse_confidence = '中'
        else:
            reverse_confidence = '低'

        # 分差区间说明
        gap_desc = {
            0: '分差=0（平局）',
            1: '分差=1（单球差）',
            2: '分差=2（双球差）',
        }
        main_gap = top_bookie[0][2] if top_bookie else ideal_gap
        gap_note = gap_desc.get(main_gap, f'分差={main_gap}（大比分）')

        # 陷阱类型文字化
        bookie_dir_label = '/'.join({
            '主队赢' if d == 'home' else ('平局' if d == 'draw' else '客队赢')
            for d in bookie_favors
        })
        trap_type_full = f'{trap_type}（庄家目标：{bookie_dir_label}）'

        # 庄家目标比分展示字符串
        target_display = ' / '.join(
            f"{s}({prob*100:.1f}%)"
            for s, prob, gap, total in bookie_target_scores[:3]
        ) or '无匹配比分'

        # 反向首选和次选
        rev_first = top_bookie[0][0] if top_bookie else None
        rev_second = top_bookie[1][0] if len(top_bookie) > 1 else None

        # 反向首选理由
        def _rev_reason(s, gap):
            s_dir = _score_dir(s)
            dir_label = '主队赢' if s_dir == 'home' else ('平局' if s_dir == 'draw' else '客队赢')
            return f'庄家目标，{gap_desc.get(gap, f"分差={gap}")}，{dir_label}'

        rev_first_reason = _rev_reason(rev_first, top_bookie[0][2]) if rev_first else ''
        rev_second_reason = _rev_reason(rev_second, top_bookie[1][2]) if rev_second else ''

        # 构建 REVERSE_ANALYSIS 结构化输出
        reverse_display = (
            f"⚠️【陷阱预警·反向分析已激活】\n"
            f"陷阱类型：{trap_type_full}\n"
            f"庄家利益比分：{target_display}\n"
            f"分差分析：{gap_note}，亚盘让球|{ah_abs}|对应理想分差={ideal_gap}\n"
            f"反向首选：{rev_first or '无'}（{rev_first_reason}）\n"
            f"反向次选：{rev_second or '无'}（{rev_second_reason}）\n"
            f"反向置信度：{reverse_confidence}"
        )

        # 【复盘改进#7】陷阱预警场次改为双侧概率分布（非单边）
        # 含义：同时输出“庄家目标侧”与“反向侧”两组概率，供下游双边布局使用。
        # 这里以当前 15 池（step1_pool）在庄家目标方向与反方向上的总概率作为双侧顶层分布。
        try:
            _bookie_prob_sum = 0.0
            _opp_prob_sum = 0.0
            _bookie_top = []
            _opp_top = []
            for _s, _p in step1_pool.items():
                _sd = _score_dir(_s)
                if _sd in bookie_favors:
                    _bookie_prob_sum += float(_p)
                    _bookie_top.append((_s, float(_p)))
                else:
                    _opp_prob_sum += float(_p)
                    _opp_top.append((_s, float(_p)))
            _bookie_top.sort(key=lambda x: x[1], reverse=True)
            _opp_top.sort(key=lambda x: x[1], reverse=True)
            dual_distribution = {
                'bookie_side': {
                    'total_prob': round(_bookie_prob_sum, 4),
                    'top_scores': [(s, round(p, 4)) for s, p in _bookie_top[:5]],
                    'directions': sorted(set(bookie_favors)),
                },
                'reverse_side': {
                    'total_prob': round(_opp_prob_sum, 4),
                    'top_scores': [(s, round(p, 4)) for s, p in _opp_top[:5]],
                },
            }
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            dual_distribution = {}

        reverse_analysis = {
            'activated': True,
            'trap_type': trap_type_full,
            'confidence': reverse_confidence,
            'rev_first': rev_first,
            'rev_second': rev_second,
            'rev_first_reason': rev_first_reason,
            'rev_second_reason': rev_second_reason,
            'target_display': target_display,
            'gap_note': gap_note,
            'display': reverse_display,
            # 【复盘改进#7】双侧概率分布（取代单边判断）
            'dual_distribution': dual_distribution,
        }
        log_steps.append(f"A4陷阱预警激活({trap_type})置信度={reverse_confidence}")
    else:
        reverse_display = ''
        # 【】自适应逼空 (Adaptive Squeeze) 局报告展示：代替原陷阱提示，顺势推送穿盘机会
        try:
            if is_squeeze and squeeze_dir:
                _sq_dir_label = {'home': '主队', 'away': '客队', 'draw': '平局'}.get(squeeze_dir, squeeze_dir)
                _sq_pick = ' / '.join(_sq_lock_scores[:3]) if _sq_lock_scores else '未形成'
                _sq_rr_text = f"{_v92_rr:.2f}%" if isinstance(_v92_rr, (int, float)) else 'N/A'
                _sq_score_text = f"{squeeze_score:.1f}" if isinstance(squeeze_score, (int, float)) else 'N/A'
                _sq_reason_text = squeeze_reason if squeeze_reason else 'N/A'
                reverse_display = (
                    f"🚨【Adaptive Squeeze 弹性逼空引擎】庄家关门拒载，陷阱预警被迫解除！\n"
                    f"逼空方向：{_sq_dir_label} | 逼空指数：{_sq_score_text}/100 | 返还率：{_sq_rr_text} | 亚盘轨迹：{ah_trajectory}\n"
                    f"评分明细：{_sq_reason_text}\n"
                    f"顺势策略：庄家越怕大热打穿，我们越要重仓{_sq_dir_label}方向的比分 ({_sq_pick}) ！"
                )
                log_steps.append(
                    f"A4Squeeze逼空引擎激活:方向={squeeze_dir}/score={squeeze_score:.1f}/rr={_v92_rr:.2f}/ah={ah_trajectory}"
                )
        except Exception as _v95_report_exc:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [Adaptive Squeeze] 报告展示异常，安全降级: {_v95_report_exc}")

    # =====================================================
    # 第五阶：双波胆锁定（4进2，一主一防）
    # 关键：从全部15个“可能比分波胆”中选取，并继续参考 sig_support 做优先级排序
    # =====================================================
    if not step3_pool:
        eligible_sorted = sorted(
            [(s, p, sig_support_map.get(s, 0)) for s, p in step1_pool.items() if s in eligible_scores],
            key=lambda x: (x[1], x[2]), reverse=True
        )
        first_score = eligible_sorted[0][0] if eligible_sorted else ''
        second_score = eligible_sorted[1][0] if len(eligible_sorted) > 1 else ''
        log_steps.append(f"A4兑底(可能比分波胆):{first_score}/{second_score}")
        # 【架构升级②·概率簇输出】兑底路径同样输出概率簇，保留双比分作为簇内最优
        try:
            _pc_kl = None
            _pc_cf = None
            if isinstance(anomaly_payload_out, dict):
                _pc_kl = anomaly_payload_out.get('kl_anomaly')
                _pc_cf = (anomaly_payload_out.get('draw_deterrence') or {}).get('cross_features')
            _prob_cluster = build_probability_cluster(
                prob_dict, first_score, second_score,
                kl_result=_pc_kl, ou_line=ou_line, lam_h=lam_h, lam_a=lam_a,
                cross_features=_pc_cf,
            )
            if isinstance(anomaly_payload_out, dict):
                anomaly_payload_out['probability_cluster'] = _prob_cluster
            if _prob_cluster:
                log_steps.append(
                    f"A7概率簇:{_prob_cluster.get('cluster_label', '')}"
                    f"(总概率{_prob_cluster.get('cluster_prob', 0)*100:.1f}%)"
                )
                group_display = group_display + "\n" + str(_prob_cluster.get('display', ''))
        except Exception as _pc_exc:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [架构升级②·概率簇] 兑底路径接入异常(已降级): {_pc_exc}")
        game_theory_log = group_display + "\n" + " | ".join(log_steps)
        return first_score, second_score, game_theory_log

    # 综合分只留博弈总分。盘口距离、大小球距离和泊松加成不参与排序。
    def _sigmoid_compress(x, center=0.5, steepness=5):
        return 1 / (1 + math.exp(-steepness * (x - center)))

    final_scores = {}
    for s, info in step3_pool.items():
        h, a = parse_score(s)
        net = h - a
        total_goals = h + a

        # 亚盘契合度：净胜球与亚盘让球的匹配程度
        ah_fit = max(0, 1 - abs(net - abs(ah)) * 0.4) if ah != 0 else (1.0 if net == 0 else 0.5)
        # 如果亚盘方向与比分方向一致，额外加分
        if (ah < 0 and net > 0) or (ah > 0 and net < 0) or (abs(ah) <= 0.25 and net == 0):
            ah_fit = min(1.0, ah_fit + 0.2)

        # 大小球契合度：总进球与盘口的匹配程度
        ou_fit = max(0, 1 - abs(total_goals - ou) * 0.3) if ou else 0.5

        direction = 'Home' if h > a else ('Draw' if h == a else 'Away')
        fusion_prob = float(info.get('poisson_p', candidates.get(s, 0)) or 0.0)
        fusion_prob_bonus = min(fusion_prob * 1.6, 0.18)
        gt_compressed = _sigmoid_compress(info['gt_total'], center=0.5, steepness=4)

        dispersion_risk = 0

        expected_total = lam_h + lam_a
        goals_deviation = abs(total_goals - expected_total)
        goals_risk = min(goals_deviation * 0.05, 0.10)

        # 内部离散度奖励：泊松概率越高的比分，在15个中排名越靠前，奖励越大
        poisson_rank = list(step3_pool.keys()).index(s) if s in step3_pool else 3
        internal_dispersion_bonus = max(0, (4 - poisson_rank) * 0.05)  # 排名1→+0.15, 排名2→+0.10, 排名3→+0.05, 排名4→0

        # 市场异常信号奖励：已移除EV/异常模块，固定为0
        anomaly_signal_bonus = 0

        composite = gt_compressed * 0.50 + anomaly_signal_bonus - dispersion_risk

        # 静态诱导越高，越降低市场信号的相对支配，有限回归球队能力/理论概率。
        _static_theory_bonus = 0.0
        try:
            _static_theory_bonus = _static_decision_gate * min(max(fusion_prob, 0.0) * 2.0, 0.20)
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            _static_theory_bonus = 0.0

        # 阈值调整（仅作用于首选选择阶段的权重乘子）：
        #   ① 融合强度 > 20% 且 DTI > 0.08 时，首选权重 × 1.5
        #   ② DTI < 0.04 时，首选权重 × 0.5
        # 仅在取到 dynamic_context / dti_for_threshold / fusion_strength 的场景下生效；异常不修正。
        try:
            _dti_val_adj = None
            _fusion_val_adj = None
            try:
                _dti_val_adj = float(dynamic_context.get('dynamic_dti', 0.0))
                _fusion_val_adj = float(dynamic_context.get('fusion_strength', 0.0))
            except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                _dti_val_adj, _fusion_val_adj = None, None
            _first_w = 1.0
            if _dti_val_adj is not None and _fusion_val_adj is not None:
                # 融合强度 允许传入比例（0~1）或百分数（0~100）
                _fusion_norm = _fusion_val_adj / 100.0 if _fusion_val_adj > 1.0 else _fusion_val_adj
                if _fusion_norm > 0.20 and _dti_val_adj > 0.08:
                    _first_w = 1.5
                elif _dti_val_adj < 0.04:
                    _first_w = 0.5
            composite = float(composite) * float(_first_w)
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L20566] {_silent_err}")

        final_scores[s] = {
            'composite': composite,
            'gt_total': info['gt_total'],
            'gt_compressed': gt_compressed,
            'dispersion_risk': dispersion_risk,
            'goals_risk': goals_risk,
            'internal_dispersion_bonus': internal_dispersion_bonus,
            'anomaly_signal_bonus': anomaly_signal_bonus,
            'static_manipulation_score': _static_decision_score,
            'static_market_noise_gate': _static_decision_gate,
            'static_theory_bonus': _static_theory_bonus,
            'ah_fit': ah_fit,
            'ou_fit': ou_fit,
            'fusion_prob': fusion_prob,
            'direction': direction,
            'eligible': s in eligible_scores,
            'sig_support': sig_support_map.get(s, 0),
        }

    # 首选：优先从全部15个可能比分波胆中选综合分最高的
    sorted_final = sorted(final_scores.items(), key=lambda x: (x[1]['composite'], x[1].get('sig_support', 0)), reverse=True)
    eligible_final = [(s, info) for s, info in sorted_final if info['eligible']]
    if eligible_final:
        first_score = eligible_final[0][0]
        first_dir = eligible_final[0][1]['direction']
    else:
        first_score = ''
        first_dir = ''

    # =====================================================
    # 【问题4修复·深盘一致性硬约束】
    # 多模型投票（V-Entropy等）在深盘下可能各执一词，导致首选
    # 净胜球不足以覆盖盘口深度（如亚盘 -2.703 却首选 2-1）。这里施加硬约束：
    #   当 abs(ah)>2.0 时，首选主队净胜球必须 >= floor(abs(ah))（主让）；
    #   客让对称（客队净胜>=floor(abs(ah))）。
    # 不满足则从候选池中选满足约束的最高概率（综合分）比分强制覆盖。
    # 该函数后续在陷阱替换 / 止血补丁 / 外层覆写后会被重复调用以守住约束。
    # =====================================================
    def _deep_handicap_required_net():
        """返回 (深盘是否激活, 需要的方向 'home'/'away', 最小净胜球阈值)"""
        try:
            _ahv = float(ah)
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            return (False, None, 0)
        _depth = abs(_ahv)
        if _depth <= 2.0:
            return (False, None, 0)
        _need = math.floor(_depth)
        if _ahv < 0:
            return (True, 'home', _need)   # 主队深让
        else:
            return (True, 'away', _need)   # 客队深让

    def _score_satisfies_deep(score_str, need_dir, need_net):
        """判断单个比分是否满足深盘净胜约束；'其它'类按方向宽松放行"""
        try:
            if any(k in str(score_str) for k in ('胜其它', '平其它', '负其它', '其它')):
                # 胜其它=主队大胜延伸，负其它=客队大胜延伸
                if need_dir == 'home' and '胜其它' in str(score_str):
                    return True
                return bool(need_dir == 'away' and '负其它' in str(score_str))
            _h, _a = parse_score(score_str)
            if _h is None:
                return True
            _net = _h - _a
            if need_dir == 'home':
                return _net >= need_net
            elif need_dir == 'away':
                return (-_net) >= need_net
            return True
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·return False降级 L20640] {_silent_err}")
            return False

    def _enforce_deep_handicap(cur_first, cur_second=None):
        """对首选施加深盘硬约束；不满足则从 sorted_final 选满足约束的最高综合分比分。
        返回 (new_first, changed, note)。
        """
        _active, _need_dir, _need_net = _deep_handicap_required_net()
        if not _active:
            return cur_first, False, ''
        if _score_satisfies_deep(cur_first, _need_dir, _need_net):
            return cur_first, False, ''
        # 从候选池（综合分降序）中找首个满足约束、且非次选的比分
        for _s, _info in sorted_final:
            if _s == cur_second:
                continue
            if _score_satisfies_deep(_s, _need_dir, _need_net):
                _note = (f"⚠️深盘一致性约束(止血补丁四)：ah={ah}深度>2.0，"
                         f"原首选{cur_first}净胜不足，强制改为{_s}(需{_need_dir}净胜>={_need_net})")
                return _s, True, _note
        # 候选池无满足约束者：保持原值（不硬造比分），仅记录
        return cur_first, False, (f"⚠️深盘一致性约束：ah={ah}深度>2.0 但候选池无满足净胜>={_need_net}的比分")

    _dh_first_new, _dh_changed, _dh_note = _enforce_deep_handicap(first_score, None)
    if _dh_changed:
        log_steps.append(f"A4深盘一致性约束只记录{_dh_first_new}，不替换两个比分")
        print(f"   深盘约束只记录{_dh_first_new}，不替换两个比分")
    elif _dh_note:
        log_steps.append(_dh_note)

    # 次选：也从全部15个可能比分波胆中选，对冲首选最大逻辑漏洞
    second_score = None
    # 合法候选中排除首选
    remaining_eligible = [s for s, info in eligible_final if s != first_score]
    # 如果合法候选不足，兑底到全部sorted_final
    remaining_all = [s for s, _ in sorted_final if s != first_score]

    def _pick_second(pool):
        """次选只取同一排序的下一项。不按总球对侧，也不按另一胜平负另选。"""
        return pool[0] if pool else None

    # 先尝试从合法候选中选次选
    second_score = _pick_second(remaining_eligible)
    if not second_score:
        remaining_non_unlikely = [s for s in remaining_all if s not in unlikely_scores]
        second_score = _pick_second(remaining_non_unlikely)
    if not second_score and remaining_eligible:
        second_score = remaining_eligible[0]
    if not second_score and len(sorted_final) > 1:
        second_score = sorted_final[1][0]
    if not second_score:
        second_score = ''

    # =====================================================
    # 陷阱预警激活时：按置信度替换首选/次选
    # =====================================================
    trap_note = ''  # 陷阱预警标注
    if trap_activated and reverse_analysis:
        ra = reverse_analysis
        rev_first = ra.get('rev_first')
        rev_second = ra.get('rev_second')
        confidence = ra.get('confidence', '低')

        if confidence == '高' and rev_first and rev_second:
            trap_note = f"陷阱预警[高置信度]只记录{rev_first}/{rev_second}，不替换两个比分"
            log_steps.append(trap_note)
        elif confidence == '中' and rev_first:
            trap_note = f"陷阱预警[中置信度]只记录{rev_first}，不替换两个比分"
            log_steps.append(trap_note)
        else:
            # 置信度低：不改变选择，仅标注
            trap_note = f"⚠️陷阱预警[低置信度]：保持原选择，建议关注{rev_first or '无'}"
            log_steps.append("A5陷阱低置信度标注，不替换")

    # 【问题4修复·陷阱替换后重校深盘约束】陷阱反向替换可能把首选改回浅盘/反向比分，
    # 深盘场景下需重新约束。以当前次选为排除项，避免首/次选重复。
    _dh_first_new, _dh_changed, _dh_note = _enforce_deep_handicap(first_score, second_score)
    if _dh_changed:
        trap_note = (trap_note + " | " if trap_note else "") + f"深盘约束只记录{_dh_first_new}，不替换两个比分"
        log_steps.append(f"A5深盘一致性约束只记录{_dh_first_new}，不替换两个比分")
        print(f"   深盘约束只记录{_dh_first_new}，不替换两个比分")

    # 构建日志
    f1_info = final_scores.get(first_score, {})
    f2_info = final_scores.get(second_score, {})
    f1_group = "可能比分波胆"
    f2_group = "可能比分波胆"
    if not trap_activated:  # 无陷阱时才记录A4锁定日志
        log_steps.append(
            f"A4锁定:首选{first_score}[组:{f1_group}](综合{f1_info.get('composite', 0):.2f})"
            f"/次选{second_score}[组:{f2_group}](综合{f2_info.get('composite', 0):.2f})"
        )
    if ai_signals:
        log_steps.append(f"AI信号:{'|'.join(ai_signals)}")
    if f1_info:
        log_steps.append(
            f"NL对冲: gt_comp={f1_info.get('gt_compressed', 0):.3f}, disp_risk={f1_info.get('dispersion_risk', 0):.3f}, goals_risk={f1_info.get('goals_risk', 0):.3f}"
        )
    if f2_info:
        log_steps.append(
            f"NL对冲: gt_comp={f2_info.get('gt_compressed', 0):.3f}, disp_risk={f2_info.get('dispersion_risk', 0):.3f}, goals_risk={f2_info.get('goals_risk', 0):.3f}"
        )

    # 构建最终波胆展示文本
    f1_prob = step1_pool.get(first_score, candidates.get(first_score, 0))
    f2_prob = step1_pool.get(second_score, candidates.get(second_score, 0))

    if trap_activated and reverse_analysis:
        # 陷阱激活时：展示反向分析结果
        ra = reverse_analysis
        # 【复盘改进#7】双侧概率分布展示
        _dd = ra.get('dual_distribution') or {}
        _dual_text = ''
        if _dd:
            _bs = _dd.get('bookie_side', {}) or {}
            _rs = _dd.get('reverse_side', {}) or {}
            _bs_top = ' / '.join(f"{s}({p*100:.1f}%)" for s, p in _bs.get('top_scores', []))
            _rs_top = ' / '.join(f"{s}({p*100:.1f}%)" for s, p in _rs.get('top_scores', []))
            _dual_text = (
                f"\n『双侧概率分布』\n"
                f"  · 庄家目标侧总概率：{float(_bs.get('total_prob', 0))*100:.1f}% Top: {_bs_top or '无'}\n"
                f"  · 反向侧总概率：{float(_rs.get('total_prob', 0))*100:.1f}% Top: {_rs_top or '无'}"
            )
        final_display = (
            f"{ra['display']}\n\n"
            f"『最终2个波胆』（陷阱预警只记录，不替换这一对）\n"
            f"① {first_score}（{f1_group}组，概率{f1_prob*100:.1f}%，反向置信度:{ra['confidence']}）\n"
            f"② {second_score}（{f2_group}组，概率{f2_prob*100:.1f}%）"
            f"{_dual_text}"
        )
        if trap_note:
            final_display = trap_note + "\n" + final_display
    else:
        final_display = (
            f"『最终2个波胆』（从15个可能比分波胆中研判）\n"
            f"① {first_score}（{f1_group}，概率{f1_prob*100:.1f}%，综合分{f1_info.get('composite', 0):.2f}）\n"
            f"② {second_score}（{f2_group}，概率{f2_prob*100:.1f}%，综合分{f2_info.get('composite', 0):.2f}）"
        )

    # =====================================================
    # 【止血补丁一·基本面λ绝对否决权】
    # 赛前纯泊松期望 λ_total = λ_h + λ_a >= 3.0 时，
    # 系统被剥夺将首选覆写为 0-0 / 1-1 的权力。
    # 如果首选违反该红线，则强制从 sorted_final 中
    # 取排名第二/第三的「非低比分」补上；次选同理。
    # =====================================================
    bp1_veto_note = ''
    try:
        _bp1_lam_total = float(lam_h or 0.0) + float(lam_a or 0.0)

        # 战术僵局只记事实，不改比分
        # 当双方均为豪门重炮手（λ差距小）且大小球轨迹为 under_strengthen
        # 且 0 球比分 EV 较高时，认定为战术僵局，允许保留低比分选项
        _bp1_lam_gap = abs(float(lam_h or 0.0) - float(lam_a or 0.0))
        _bp1_is_big_clash = (_bp1_lam_total >= 3.0) and (_bp1_lam_gap < 0.8)  # 双方火力均强且接近
        _bp1_ou_under = (ou_trajectory == 'under_strengthen') if 'ou_trajectory' in locals() else False
        _bp1_ev_0_goal = 0.0
        is_tactical_stalemate = (
            _bp1_is_big_clash and
            _bp1_ou_under and
            _bp1_ev_0_goal > 30.0
        )

        if _bp1_lam_total >= 3.0 and not is_tactical_stalemate:
            bp1_veto_note = (
                f"基本面λ={_bp1_lam_total:.2f}>=3.0。只记总球事实，不改比分。"
            )
            log_steps.append(bp1_veto_note)
            print(f"   [基本面λ] {bp1_veto_note}")
        elif _bp1_lam_total >= 3.0 and is_tactical_stalemate:
            # 战术僵局保护触发，允许 1-1, 1-0 等战术比分成为首选
            print(
                f"   🛡️ [战术僵局安全阀] 触发保护：λ_total={_bp1_lam_total:.2f}≥3.0 但双方火力接近"
                f"(Δλ={_bp1_lam_gap:.2f}<0.8) + OU轨迹=under_strengthen + "
                f"0球EV={_bp1_ev_0_goal:.1f}%>30%，保留低比分选项"
            )
            log_steps.append(
                f"A6战术僵局安全阀:λ_total={_bp1_lam_total:.2f}/Δλ={_bp1_lam_gap:.2f}/"
                f"OU=under/0球EV={_bp1_ev_0_goal:.1f}%，允许低比分首选"
            )
    except Exception as _bp1_exc:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [止血补丁一] 基本面否决权异常，安全降级: {_bp1_exc}")

    # 【问题4修复·止血补丁一后重校深盘约束】
    # 止血补丁一可能把首选改为不满足深盘净胜约束的比分，再次强制校正。
    try:
        _dh_first_new, _dh_changed, _dh_note = _enforce_deep_handicap(first_score, second_score)
        if _dh_changed:
            log_steps.append(f"A6深盘一致性约束只记录{_dh_first_new}，不替换两个比分")
            print(f"   深盘约束只记录{_dh_first_new}，不替换两个比分")
    except Exception as _dh_bp1_exc:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [深盘约束·止血补丁后] 异常降级: {_dh_bp1_exc}")

    # 同步拼接「基本面否决权」标记到 group_display 顶部，便于上游报告检索
    if bp1_veto_note:
        group_display = bp1_veto_note + "\n" + group_display

    # 同步拼接「陷阱被基本面否决」提示（补丁三）
    try:
        if fundamental_gate_block and fundamental_gate_reason:
            _bp3_note = (
                f"⚠️ 陷阱预警被基本面否决(止血补丁三)：{fundamental_gate_reason}，已强制走正向 EV 击穿"
            )
            final_display = _bp3_note + "\n" + final_display
            group_display = _bp3_note + "\n" + group_display
    except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [异常已捕获·pass降级 L20939] {_silent_err}")

    # 【LLM 数据静默逻辑已删除】不再篡改 prob_dict，直接向 LLM 提供真实的推演结论。

    # =====================================================
    # 【架构升级②·概率簇输出（第六层）】
    # 将输出形态从孤立双比分升级为概率簇：KL高阈值触发时输出
    # 防冷簇/大球穿盘簇，否则输出围绕首选的常规主簇/平局锚簇。
    # first_score/second_score 仍作为簇内最优保留，簇信息额外输出。
    # =====================================================
    try:
        _pc_kl = None
        _pc_cf = None
        if isinstance(anomaly_payload_out, dict):
            _pc_kl = anomaly_payload_out.get('kl_anomaly')
            _pc_cf = (anomaly_payload_out.get('draw_deterrence') or {}).get('cross_features')
        _prob_cluster = build_probability_cluster(
            prob_dict, first_score, second_score,
            kl_result=_pc_kl, ou_line=ou_line, lam_h=lam_h, lam_a=lam_a,
            cross_features=_pc_cf,
        )
        if isinstance(anomaly_payload_out, dict):
            anomaly_payload_out['probability_cluster'] = _prob_cluster
        if _prob_cluster:
            log_steps.append(
                f"A7概率簇:{_prob_cluster.get('cluster_label', '')}"
                f"(总概率{_prob_cluster.get('cluster_prob', 0)*100:.1f}%"
                f"{'/KL高阈值触发' if _prob_cluster.get('kl_triggered') else ''})"
            )
            final_display = final_display + "\n\n" + str(_prob_cluster.get('display', ''))
            print(f"   {_prob_cluster.get('display', '')}")
    except Exception as _pc_exc:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [架构升级②·概率簇] 主路径接入异常(已降级): {_pc_exc}")

    game_theory_log = group_display + "\n" + final_display + "\n" + " | ".join(log_steps)
    return first_score, second_score, game_theory_log


def calc_big_small(prob_dict, ou_line, lam_h=None, lam_a=None, market_over_odds=None, market_under_odds=None):
    """根据泊松理论概率计算大小球判断（由 OverUnderEngine 驱动）。

    正确方法：基于泊松分布计算 P(Over) 和 P(Under)，概率高者为预测方向。
    替代旧的错误加权均值阈值法。

    Args:
        prob_dict: dict, 比分概率字典（用于反推λ，当 lam_h/lam_a 未传入时）
        ou_line: float, 大小球盘口线
        lam_h: float|None, 主队泊松λ（优先使用）
        lam_a: float|None, 客队泊松λ（优先使用）
        market_over_odds: float|None, 大球赔率（用于偏差检测）
        market_under_odds: float|None, 小球赔率（用于偏差检测）

    Returns:
        tuple: (verdict: str, weighted_goals: float, is_edge: bool)
               verdict: '大球'|'小球'|'未知'
               weighted_goals: 期望总进球数
               is_edge: 是否为边缘判定
    """
    try:
        if not prob_dict or ou_line is None:
            return "未知", 0, False

        # 获取λ值：优先使用传入参数，否则从 prob_dict 反推
        _lam_h = lam_h
        _lam_a = lam_a
        if _lam_h is None or _lam_a is None:
            _lam_h_approx = 0.0
            _lam_a_approx = 0.0
            _total_p = 0.0
            for score_str, prob in (prob_dict or {}).items():
                if '其它' in str(score_str) or '-' not in str(score_str):
                    continue
                try:
                    h, a = parse_score(score_str)
                    if h is None or a is None:
                        continue

                    p = float(prob or 0.0)
                    _lam_h_approx += h * p
                    _lam_a_approx += a * p
                    _total_p += p
                except (ValueError, IndexError):
                    continue
            if _total_p > 0:
                _lam_h = _lam_h_approx / _total_p if _lam_h is None else _lam_h
                _lam_a = _lam_a_approx / _total_p if _lam_a is None else _lam_a
            else:
                return "未知", 0, False

        # 使用 OverUnderEngine 计算
        verdict, expected_goals, is_edge, _deviation_info = OverUnderEngine.predict_ou(
            _lam_h, _lam_a, ou_line, market_over_odds, market_under_odds
        )

        return verdict, round(expected_goals, 2), is_edge

    except Exception as _e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [calc_big_small] OverUnderEngine驱动异常，安全降级: {_e}")
        return "未知", 0, False

def homogenization_check(all_first_scores):
    """同质化判定已关闭。不因批内占比触发重检或换角。"""
    return False, None, 0


