def _okooo_decode_page(resp):
    """澳客页面按中文命中选编码。apparent_encoding 猜成 ISO-8859-5 时不能用来建场。"""
    raw = getattr(resp, 'content', b'') or b''
    if not raw:
        return ''
    best = ''
    best_score = -1
    for enc in ('gb18030', 'utf-8', 'gbk'):
        try:
            text = raw.decode(enc, 'ignore')
        except Exception:  # noqa: BLE001,S112 - intentional degraded-mode guard or structure-preserving fallback  # nosec B112  # intentional degraded-mode continue fallback
            continue
        score = sum(text.count(ch) for ch in '一二三四五六日')
        score += text.count('竞')
        score -= text.count('\ufffd') * 3
        if score > best_score:
            best, best_score = text, score
    if best_score > 0:
        return best
    enc = getattr(resp, 'apparent_encoding', None) or 'utf-8'
    try:
        return raw.decode(enc, 'ignore')
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return raw.decode('utf-8', 'ignore')


def _okooo_list_page_ok(url, resp):
    """200 的滑动验证页或空壳不能当成赛程。"""
    if resp is None or getattr(resp, 'status_code', 0) != 200:
        return False
    raw = getattr(resp, 'content', b'') or b''
    if len(raw) <= 500:
        return False
    text = _okooo_decode_page(resp)
    low = text.lower()
    if ('aliyuncaptcha' in low) or ('滑动验证' in text) or ('title>405' in low):
        return False
    url = str(url or '')
    if 'm.okooo.com' in url:
        return ('ctrl_eachmatch' in text) and ('jsContentBar' in text)
    if 'jingcai' in url:
        return ('data-mid' in text) and ('data-ordercn' in text)
    return True


def _okooo_http_get(url, headers=None, timeout=15, proxies=None):
    """澳客专用请求：代理优先→直连，http→https 归一。验证页继续下一条。"""
    _headers = headers or {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 '
                      '(KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
        'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8',
        'Referer': 'https://www.okooo.com/jingcai/',
    }
    if isinstance(url, str) and url.startswith('http://www.okooo.com'):
        url = 'https://' + url[len('http://'):]
    session = requests.Session()
    session.trust_env = False
    _proxy_try = proxies if proxies is not None else (_local_proxies() or _DIRECT_PROXIES)
    for _px in [_proxy_try, None]:
        try:
            resp = session.get(
                url,
                headers=_headers,
                proxies=_px,
                timeout=timeout,
                verify=not _allow_insecure_ssl(),
            )
            if _okooo_list_page_ok(url, resp):
                return resp
        except Exception:  # noqa: BLE001,S112 - intentional degraded-mode guard or structure-preserving fallback  # nosec B112  # intentional degraded-mode continue fallback
            continue
    return None


def fetch_okooo_jingcai_match_map(proxies=None):
    """抓取澳客竞彩在售列表，返回完整队名 + 开赛时间。

    注意：data-hname/data-aname 常被澳客截成短名；须从行内全文还原完整队名。
    """
    from bs4 import BeautifulSoup as _BS
    url = 'https://www.okooo.com/jingcai/'
    print(f"   📡 [澳客竞彩] 抓取赛程列表: {url}")
    resp = _okooo_http_get(url, proxies=proxies, timeout=20)
    if resp is None:
        print("   ⚠️ [澳客竞彩] 列表抓取失败")
        return {}
    text = _okooo_decode_page(resp)
    soup = _BS(text, 'html.parser')
    result = {}
    for div in soup.select('[data-mid][data-ordercn]'):
        mid = str(div.get('data-mid') or '').strip()
        ordercn = str(div.get('data-ordercn') or '').strip()
        if not mid or not ordercn:
            continue
        h_short = str(div.get('data-hname') or '').strip()
        a_short = str(div.get('data-aname') or '').strip()
        row_txt = div.get_text(' ', strip=True) or ''
        h_full, a_full = _okooo_expand_full_team_names(row_txt, h_short, a_short)
        kick = ''
        kickoff_source = ''
        time_node = div.select_one('.shijian, [title*="比赛时间"]')
        titled = str(time_node.get('title') or '') if time_node is not None else ''
        titled_m = re.search(r'(\d{4}-\d{2}-\d{2})\s+(\d{1,2}):(\d{2})', titled)
        if titled_m:
            kick = f"{titled_m.group(1)} {int(titled_m.group(2)):02d}:{titled_m.group(3)}"
            kickoff_source = 'okooo_match_time'
        if not kick:
            kick = _okooo_parse_kickoff_from_row(ordercn, row_txt)
        item = {
            'okooo_match_id': mid,
            'ordercn': ordercn,
            'hname': h_full or h_short,
            'aname': a_full or a_short,
            'hname_short': h_short,
            'aname_short': a_short,
            'match_time': kick or '',
            'time': kick or '',
            'kickoff_time': kick or '',
            'kickoff_source': kickoff_source,
            'row_text': row_txt[:240],
            'data_end': str(div.get('data-end') or '').strip(),
            'jc_handicap_int_okooo': None,
        }
        try:
            rq = div.get('data-rq')
            if rq is not None and str(rq).strip() != '':
                item['jc_handicap_int_okooo'] = int(str(rq).strip())
        except (TypeError, ValueError):
            pass
        result[ordercn] = item
        result[mid] = item
        m_no = re.search(r'(\d{3})$', ordercn)
        if m_no:
            suffix = m_no.group(1)
            prev = result.get(suffix)
            prev_end = str((prev or {}).get('data_end') or '') if isinstance(prev, dict) else '1'
            this_end = str(item.get('data_end') or '')
            if (not isinstance(prev, dict)) or (prev_end == '1' and this_end != '1'):
                result[suffix] = item
    print(f"   ✅ [澳客竞彩] 已映射 {len(result)} 条场次ID（完整队名+开赛时间）")
    return result


_OKOOO_DIGIT_WEEK = {
    '一': '周一', '二': '周二', '三': '周三', '四': '周四',
    '五': '周五', '六': '周六', '日': '周日',
}


def fetch_okooo_mobile_jingcai_board(proxies=None, now=None):
    """澳客手机竞足赛程。已开售才可建场；end=1 与完场比分为停售，未开售单独标出。"""
    from bs4 import BeautifulSoup as _BS
    now = now or datetime.now()
    url = 'https://m.okooo.com/jczq/'
    headers = {
        'User-Agent': (
            'Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) '
            'AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.0 Mobile/15E148 Safari/604.1'
        ),
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
        'Accept-Language': 'zh-CN,zh;q=0.9',
        'Referer': 'https://m.okooo.com/jczq/',
    }
    print(f"   📡 [澳客手机] 抓取竞足赛程: {url}")
    resp = _okooo_http_get(url, headers=headers, proxies=proxies, timeout=25)
    if resp is None:
        print("   ⚠️ [澳客手机] 竞足赛程抓取失败")
        return []
    text = _okooo_decode_page(resp)
    soup = _BS(text, 'html.parser')
    from okooo_mobile_cs import jingcai_board_row_finished, parse_mobile_nav_ft_score
    today_md = now.strftime('%m-%d')
    current_date = ''
    day_closed = False
    rows = []
    seen = set()
    for el in soup.select('.jsContentBar, .ctrl_eachmatch'):
        classes = el.get('class') or []
        if 'jsContentBar' in classes:
            mday = re.search(r'(\d{2}-\d{2})', el.get_text(' ', strip=True))
            current_date = mday.group(1) if mday else ''
            day_closed = 'jsEndHideBar' in classes
            continue
        finished = jingcai_board_row_finished(
            day_closed=day_closed,
            end=el.get('end'),
            inside_end_hide=el.find_parent(class_='jsEndHideContent') is not None,
        )
        status = '已开售'
        if finished:
            status = '停售'
        elif el.select_one('.ctrl_not_sale') is not None:
            status = '未开售'
        else:
            vs = el.select_one('.zVS')
            vs_txt = vs.get_text(strip=True) if vs else ''
            # 开赛后 zVS 会变成即时比分。这场不再建场，但即时比分不是完场。
            if re.fullmatch(r'\d+\s*-\s*\d+', vs_txt or ''):
                status = '停售'
        ft_score = ''
        if finished:
            vs_node = el.select_one('.zVS')
            vs_raw = vs_node.get_text(' ', strip=True) if vs_node else ''
            try:
                ft_score = parse_mobile_nav_ft_score(vs_raw)
            except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                parts = re.fullmatch(r'(\d{1,2})\s*-\s*(\d{1,2})', vs_raw or '')
                if parts and _plausible_ft_score(parts.group(1), parts.group(2)):
                    ft_score = f"{int(parts.group(1))}-{int(parts.group(2))}"
        xu_node = el.select_one('.xuhao')
        xu = re.sub(r'\s+', '', xu_node.get_text() if xu_node else '')
        m_no = re.match(r'([一二三四五六日])(\d{3})', xu)
        ordercn = (_OKOOO_DIGIT_WEEK.get(m_no.group(1), '') + m_no.group(2)) if m_no else xu
        node = el.select_one('[matchid]')
        mid = str(node.get('matchid') or '').strip() if node else ''
        if not mid or mid in seen:
            continue
        seen.add(mid)
        h_node = el.select_one('.ctrl_homename')
        a_node = el.select_one('.ctrl_awayname')
        t_node = el.select_one('.timetxt')
        hm = t_node.get_text(strip=True) if t_node else ''
        kick = ''
        # 时间格上的 22:00 是竞彩日切，不是这场开赛。开赛钟点以后面的「比赛时间」为准。
        if current_date and re.fullmatch(r'\d{1,2}:\d{2}', hm or '') and hm != '22:00':
            try:
                mm, dd = [int(x) for x in current_date.split('-')]
                hh, minu = [int(x) for x in hm.split(':')]
                kick = datetime(now.year, mm, dd, hh, minu).strftime('%Y-%m-%d %H:%M')
            except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                kick = ''
        h_short = h_node.get_text(strip=True) if h_node else ''
        a_short = a_node.get_text(strip=True) if a_node else ''
        # ctrl_*name / data-hname 常为短名；从整行文案还原完整队名后再进研判与监控
        row_txt = el.get_text(' ', strip=True) or ''
        try:
            h_full, a_full = _okooo_expand_full_team_names(row_txt, h_short, a_short)
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            h_full, a_full = h_short, a_short
        home = (h_full or h_short or '').strip()
        away = (a_full or a_short or '').strip()
        rows.append({
            'okooo_match_id': mid,
            'ordercn': ordercn,
            'no': ordercn,
            'cn': ordercn,
            'hname': home,
            'aname': away,
            'hname_short': h_short,
            'aname_short': a_short,
            'home': home,
            'away': away,
            'home_team': home,
            'away_team': away,
            'match': ' vs '.join(x for x in (home, away) if x),
            'sale_status': status,
            'sale_day': current_date,
            'is_today': bool(current_date and current_date == today_md),
            'match_time': kick,
            'time': kick,
            'kickoff_time': kick,
            'channel': 'mobile',
            'ft_score': ft_score,
        })
    n_on = sum(1 for r in rows if r['sale_status'] == '已开售')
    n_stop = sum(1 for r in rows if r['sale_status'] == '停售')
    n_wait = sum(1 for r in rows if r['sale_status'] == '未开售')
    print(
        f"   ✅ [澳客手机] 赛程 {len(rows)} 场｜已开售 {n_on}｜停售 {n_stop}｜未开售 {n_wait}"
    )
    return rows


_OKOOO_WEEKDAY_MAP = {
    '周一': 0, '周二': 1, '周三': 2, '周四': 3, '周五': 4, '周六': 5, '周日': 6,
    '星期一': 0, '星期二': 1, '星期三': 2, '星期四': 3, '星期五': 4, '星期六': 5, '星期日': 6,
}


def _okooo_expand_full_team_names(row_txt, h_short, a_short):
    """从澳客行全文还原完整队名（优先长名，禁止少字短名进研判）。"""
    txt = str(row_txt or '')
    h_short = str(h_short or '').strip()
    a_short = str(a_short or '').strip()
    bad = (
        '未开售', '已开售', '欧', '析', '态', '情',
        '中超', '英超', '西甲', '德甲', '意甲', '法甲',
        '荷甲', '土超', '希超', '新联', '亚冠', '欧联', '欧冠', '亚运',
        '芬超', '挪超', '女足亚洲杯', '亚运男足', '亚运女足',
    )

    def _is_noise(t):
        if not t or t in bad:
            return True
        if re.fullmatch(r'\d+(\.\d+)?', t):
            return True
        return bool(re.fullmatch(r'\d{1,2}:\d{2}', t))

    tokens = re.findall(r'[\u4e00-\u9fffA-Za-z0-9·\-]+', txt)

    def _cands_for(short):
        if not short:
            return []
        return [
            t for t in tokens
            if t.startswith(short) and len(t) >= len(short) and not _is_noise(t)
        ]

    def _expand_nth(short, n=0, exclude=None):
        """按行内出现序取第 n 个以 short 开头的候选（同短名主客可拆开）。"""
        exclude = exclude or set()
        cands = [t for t in _cands_for(short) if t not in exclude]
        # 优先严格更长名；同长保序
        longer = [t for t in cands if len(t) > len(short)]
        pool = longer if longer else cands
        if not pool:
            return short or ''
        if n >= len(pool):
            n = len(pool) - 1
        return pool[n]

    # 块解析：[排名] 联赛? 队名 赔率…
    # 兼容「[排名] 队名 赔率」和「[排名] 联赛 队名 赔率」
    blocks = re.findall(
        r'\[(\d+)\]\s*(?:'
        r'([^\d\[\]欧析态情]{1,12}?)\s+)?'
        # 队名捕获不得吞掉空格后的 VS/客队；空白处截断
        r'([^\d\[\]欧析态情·\-A-Za-z0-9]*[\u4e00-\u9fffA-Za-z][^\d\[\]欧析态情\s]*?)'
        r'(?=\s*(?:\d+\.\d+|未开售|欧|VS|vs|\[\d+\]))',
        txt,
    )
    # blocks: (rank, league_or_empty, team)
    block_teams = []
    for _rk, league, team in blocks:
        team = str(team or '').strip()
        league = str(league or '').strip()
        if league and league in bad and team:
            pass
        elif team in bad and league and league not in bad:
            team = league
        # 防止「日本 VS 巴拉圭」整段落进主队名
        if re.search(r'(?i)\bvs\.?\b|对阵', team):
            team = re.split(r'(?i)\s*vs\.?\s*|对阵', team, maxsplit=1)[0].strip()
        if team and not _is_noise(team) and team not in bad:
            block_teams.append(team)

    h_full = block_teams[0] if len(block_teams) >= 1 else ''
    a_full = block_teams[1] if len(block_teams) >= 2 else ''

    # 块名必须能对上短名前缀，否则弃用
    if h_full and h_short and not h_full.startswith(h_short):
        h_full = ''
    if a_full and a_short and not a_full.startswith(a_short):
        a_full = ''

    # 同短名主客：块序优先；否则按出现序拆第1、第2候选
    same_short = bool(h_short and a_short and h_short == a_short)
    if same_short and (not h_full or not a_full or h_full == a_full):
        cands = []
        for t in _cands_for(h_short):
            if t not in cands:
                cands.append(t)
        longer = [t for t in cands if len(t) > len(h_short)]
        pool = longer if len(longer) >= 2 else cands
        if len(pool) >= 2:
            h_full, a_full = pool[0], pool[1]
        elif len(pool) == 1:
            h_full = h_full or pool[0]
            a_full = a_full or pool[0]

    if not h_full or (h_short and len(h_full) < len(h_short)):
        h_full = _expand_nth(h_short, 0) or h_full or h_short
    if not a_full or (a_short and len(a_full) < len(a_short)):
        excl = {h_full} if (same_short or (h_full and a_short and h_full.startswith(a_short))) else set()
        # 客队取第2个同前缀候选，避免跟主队撞名
        a_idx = 1 if (same_short or (h_full and a_short and h_full.startswith(a_short))) else 0
        a_full = _expand_nth(a_short, a_idx, exclude=excl) or a_full or a_short

    if h_short and h_full == h_short:
        h_full = _expand_nth(h_short, 0) or h_full
    if a_short and a_full == a_short:
        a_idx = 1 if (h_full and a_short and h_full.startswith(a_short)) else 0
        a_full = _expand_nth(a_short, a_idx, exclude={h_full}) or a_full

    # 主客不得同名（除非短名也相同且行内确实无第二名）
    if h_full and a_full and h_full == a_full and h_short != a_short:
        h_full = _expand_nth(h_short, 0) or h_short
        a_full = _expand_nth(a_short, 0, exclude={h_full}) or a_short
    elif h_full and a_full and h_full == a_full and same_short:
        cands = []
        for t in _cands_for(h_short):
            if t not in cands:
                cands.append(t)
        longer = [t for t in cands if len(t) > len(h_short)]
        pool = longer if len(longer) >= 2 else cands
        if len(pool) >= 2:
            h_full, a_full = pool[0], pool[1]

    def _reject_vs_blob(name, short):
        """拒绝把「主队 VS 客队」整段当成队名。"""
        s = str(name or '').strip()
        if not s:
            return short or ''
        if re.search(r'(?i)\bVS\b|对阵', s) or ' vs ' in s.lower():
            return str(short or '').strip() or s.split()[0]
        # 主名里误夹客队短名
        sh = str(short or '').strip()
        if sh and s.startswith(sh) and a_short and a_short in s and s != sh and short == h_short:  # noqa: SIM102 - intentional degraded-mode guard or structure-preserving fallback
            if s != sh and a_short != h_short:
                return sh
        return s

    h_full = _reject_vs_blob(h_full, h_short)
    a_full = _reject_vs_blob(a_full, a_short)
    if h_full and a_short and a_short != h_short and a_short in h_full and h_full != h_short:
        h_full = h_short or h_full
    if a_full and h_short and h_short != a_short and h_short in a_full and a_full != a_short:
        a_full = a_short or a_full

    return h_full, a_full


def _okooo_parse_kickoff_from_row(ordercn, row_txt, now=None):
    """由行内日期+钟点合成开赛时间。行首 22:00 是竞彩日切，不能盖过后面的开赛钟点。"""
    now = now or datetime.now()
    txt = str(row_txt or '')
    dated = re.search(r'(\d{2})-(\d{2})\s+(\d{1,2}):(\d{2})', txt)
    if dated:
        month, day, hh, mm = (int(dated.group(i)) for i in range(1, 5))
        if 1 <= month <= 12 and 1 <= day <= 31 and hh <= 23 and mm <= 59:
            year = now.year
            try:
                pick = datetime(year, month, day, hh, mm)
            except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                pick = None
            if pick is not None:
                if pick > now + timedelta(days=200):
                    try:
                        pick = pick.replace(year=year - 1)
                    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                        pick = None
                if pick is not None:
                    return pick.strftime('%Y-%m-%d %H:%M')
    clocks = []
    for tm in re.finditer(r'(\d{1,2}):(\d{2})', txt):
        hh, mm = int(tm.group(1)), int(tm.group(2))
        if hh <= 23 and mm <= 59:
            clocks.append((hh, mm))
    if not clocks:
        return ''
    if len(clocks) >= 2 and clocks[0] == (22, 0):
        clocks = clocks[1:]
    hh, mm = clocks[0]
    wd = None
    for k, v in _OKOOO_WEEKDAY_MAP.items():
        if k in str(ordercn or ''):
            wd = v
            break
    if wd is None:
        try:
            return datetime(now.year, now.month, now.day, hh, mm).strftime('%Y-%m-%d %H:%M')
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            return ''
    # 锚定「本周」该星期：赛号「周四」在周五仍指本周四，不跳到下周四
    this_week_date = now.date() - timedelta(days=now.weekday()) + timedelta(days=wd)
    try:
        pick = datetime(this_week_date.year, this_week_date.month, this_week_date.day, hh, mm)
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return ''
    return pick.strftime('%Y-%m-%d %H:%M')


def filter_today_onsale_not_started(matches, now=None):
    """只保留手机竞足已开售且尚未开赛的场次。停售、未开售不进分析。"""
    now = now or datetime.now()
    out = []
    dropped = []
    for m in matches or []:
        if not isinstance(m, dict):
            continue
        status = str(m.get('sale_status') or '')
        if status in ('停售', '未开售'):
            _drop_name = (
                m.get('no') or m.get('cn') or m.get('ordercn')
                or m.get('match')
                or ('{} vs {}'.format(m.get('home') or m.get('hname') or '', m.get('away') or m.get('aname') or '')).strip()
                or m.get('okooo_match_id')
                or ''
            )
            dropped.append((_drop_name, status))
            continue
        ko = (
            m.get('match_time') or m.get('time') or m.get('kickoff_time')
            or m.get('fixture_date') or ''
        )
        # fixture_date 可能是 ISO
        if 'T' in str(ko):
            ko = str(ko).replace('T', ' ')[:16]
        dt = parse_match_time(ko)
        sale_day = str(m.get('sale_day') or '')
        sale_date = None
        if re.fullmatch(r'\d{2}-\d{2}', sale_day):
            try:
                sm, sd = [int(x) for x in sale_day.split('-')]
                sale_date = datetime(now.year, sm, sd).date()
            except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                sale_date = None
        if dt is None or (
            str(ko).endswith('22:00') and m.get('kickoff_source') != 'okooo_match_time'
        ):
            if sale_date is not None and sale_date < now.date():
                dropped.append((m.get('no') or m.get('cn') or '', f'过期赛日 {sale_day}'))
                continue
            m = dict(m)
            m['kickoff_unknown'] = True
            if str(m.get('time') or m.get('match_time') or '').endswith('22:00'):
                m['match_time'] = ''
                m['time'] = ''
                m['kickoff_time'] = ''
            out.append(m)
            continue
        if dt <= now or (sale_date is not None and sale_date < now.date() and dt.date() <= sale_date):
            dropped.append((m.get('no') or m.get('cn') or '', ko))
            continue
        m = dict(m)
        m['match_time'] = dt.strftime('%Y-%m-%d %H:%M')
        m['time'] = m['match_time']
        m['kickoff_unknown'] = False
        out.append(m)
    if dropped:
        print(f"   🧹 [在售过滤] 剔除停售/未开售/已开赛 {len(dropped)} 场，保留 {len(out)} 场")
        for name, ko in dropped[:8]:
            print(f"      · 跳过 {name} @ {ko}")
    else:
        print(f"   ✅ [未开赛过滤] 全部 {len(out)} 场尚未开赛")
    return out


def attach_okooo_ids_to_matches(all_raw, okooo_map=None):
    """把澳客 match_id 挂到竞彩赛程。空列表时只按手机已开售建场，停售与未开售不建。"""
    board = []
    try:
        board = fetch_okooo_mobile_jingcai_board()
    except Exception as _board_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [澳客手机] 赛程异常: {_board_err}")
        board = []
    onsale = [
        row for row in board
        if row.get('sale_status') == '已开售'
    ]
    onsale_ids = {str(row.get('okooo_match_id') or '') for row in onsale}
    if okooo_map is None:
        try:
            okooo_map = fetch_okooo_jingcai_match_map()
        except Exception as _e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [澳客竞彩] 映射异常: {_e}")
            okooo_map = {}
    if not isinstance(all_raw, list):
        all_raw = []
    if not all_raw and onsale:
        seen = set()
        for item in onsale:
            mid = item.get('okooo_match_id')
            ordercn = item.get('ordercn')
            if not mid or mid in seen:
                continue
            desk = {}
            if isinstance(okooo_map, dict):
                desk = okooo_map.get(ordercn) or okooo_map.get(str(mid)) or {}
            if str((desk or {}).get('data_end') or '') == '1':
                continue
            if not re.search(r'[一二三四五六日]', str(ordercn)):
                desk_no = str((desk or {}).get('ordercn') or '')
                if re.search(r'[一二三四五六日]', desk_no):
                    ordercn = desk_no
                    item = dict(item)
                    item['ordercn'] = ordercn
                else:
                    continue
            if desk:
                item = dict(item)
                for key in ('hname', 'aname', 'jc_handicap_int_okooo'):
                    if desk.get(key):
                        item[key] = desk.get(key)
                # 「比赛时间」是开赛钟点。手机时间格的 22:00 是日切，不能留下。
                desk_kick = ''
                if desk.get('kickoff_source') == 'okooo_match_time':
                    desk_kick = str(desk.get('match_time') or desk.get('time') or '')
                if desk_kick:
                    item['match_time'] = desk_kick
                    item['time'] = desk_kick
                    item['kickoff_time'] = desk_kick
                    item['kickoff_source'] = 'okooo_match_time'
                else:
                    for key in ('match_time', 'time', 'kickoff_time'):
                        if not item.get(key) and desk.get(key):
                            item[key] = desk.get(key)
            seen.add(mid)
            hn = item.get('hname') or ''
            an = item.get('aname') or ''
            m = {
                'no': str(ordercn),
                'cn': f"{hn} vs {an}".strip(),
                'home': hn,
                'away': an,
                'local_id': str(ordercn),
                'okooo_match_id': mid,
                'source': 'okooo_mobile_jczq',
                'sale_status': '已开售',
                'is_today': bool(item.get('is_today')),
                'sale_day': item.get('sale_day') or '',
            }
            for _tk in ('match_time', 'time', 'kickoff_time', 'kickoff_source'):
                if item.get(_tk):
                    m[_tk] = item.get(_tk)
            if item.get('jc_handicap_int_okooo') is not None:
                m['jc_handicap_int'] = item['jc_handicap_int_okooo']
            all_raw.append(m)
        print(f"   ✅ [澳客手机] 已开售建场 {len(all_raw)} 场（停售/未开售不建）")
    elif not all_raw and board and not onsale:
        print("   ✅ [澳客手机] 没有已开售场次，停售与未开售不抓取")
    if board and all_raw:
        onsale_orders = {str(row.get('ordercn') or '') for row in onsale}
        kept = []
        for m in all_raw:
            mid = str(m.get('okooo_match_id') or '')
            no = re.sub(r'^竞彩-', '', str(m.get('no') or m.get('local_id') or ''))
            if mid in onsale_ids or no in onsale_orders:
                m['sale_status'] = '已开售'
                kept.append(m)
        if len(kept) != len(all_raw):
            print(f"   🧹 [澳客手机] 建场后剔除停售/未开售 {len(all_raw) - len(kept)} 场")
        all_raw = kept
    if not okooo_map:
        return all_raw
    linked = 0
    for m in all_raw:
        if m.get('okooo_match_id'):
            linked += 1
            continue
        no = str(m.get('no') or m.get('local_id') or '')
        cn = str(m.get('cn') or m.get('cn_name') or m.get('match') or '')
        keys = []
        bare = no.replace('竞彩-', '').strip()
        if bare:
            keys.append(bare)
        # 从标题解析「周五011」等赛号（补发/旧 history 常只有 cn_name）
        for src in (no, cn):
            m_ord = re.search(r'([周星期]?[一二三四五六日]\d{3})', str(src))
            if m_ord:
                keys.append(m_ord.group(1).replace('星期', '').replace('周', '周') if False else m_ord.group(1))
            # 统一：竞彩-周五011 / [竞彩-周五011]
            m_ord2 = re.search(r'竞彩-([周][一二三四五六日]\d{3})', str(src))
            if m_ord2:
                keys.append(m_ord2.group(1))
            m3 = re.search(r'(\d{3})$', bare) if bare else None
            if m3:
                keys.append(m3.group(1))
        # 去重保序
        _seen_k = set()
        keys2 = []
        for k in keys:
            k = str(k).strip()
            if not k or k in _seen_k:
                continue
            _seen_k.add(k)
            keys2.append(k)
        keys = keys2
        hit = None
        for k in keys:
            if k in okooo_map:
                hit = okooo_map[k]
                break
        if not hit:
            for item in okooo_map.values():
                hn, an = item.get('hname') or '', item.get('aname') or ''
                if hn and an and hn in cn and an in cn:
                    hit = item
                    break
        if hit:
            m['okooo_match_id'] = hit['okooo_match_id']
            if hit.get('jc_handicap_int_okooo') is not None and m.get('jc_handicap_int') is None:
                m['jc_handicap_int'] = hit['jc_handicap_int_okooo']
            if not m.get('no') and hit.get('ordercn'):
                m['no'] = f"竞彩-{hit['ordercn']}"
            # 强制完整队名（禁短名）
            hn = str(hit.get('hname') or '').strip()
            an = str(hit.get('aname') or '').strip()
            if hn and an:
                m['home'] = hn
                m['away'] = an
                m['cn'] = f"{hn} vs {an}"
                # 同步常见展示字段，避免短名残留
                m['cn_name'] = f"[{m.get('no') or hit.get('ordercn') or ''}] {hn} vs {an}".strip()
                m['hname'] = hn
                m['aname'] = an
            hit_kick = ''
            if hit.get('kickoff_source') == 'okooo_match_time':
                hit_kick = str(hit.get('match_time') or hit.get('time') or '')
            if hit_kick:
                m['match_time'] = hit_kick
                m['time'] = hit_kick
                m['kickoff_time'] = hit_kick
                m['kickoff_source'] = 'okooo_match_time'
            else:
                for _tk in ('match_time', 'time', 'kickoff_time'):
                    if hit.get(_tk) and not m.get(_tk):
                        m[_tk] = hit.get(_tk)
            linked += 1
    print(f"   ✅ [澳客竞彩] 已关联 okooo_match_id: {linked}/{len(all_raw)}")
    return all_raw


def _betfair_from_mobile_pnl(pack):
    """必发交易盈亏收成现有 betfair_data。数字保持页面原文，不改方向锁。"""
    rows = ((pack or {}).get('betfair_trade') or {}).get('rows') or []
    by = {row.get('wdl'): row for row in rows if isinstance(row, dict)}
    if not by:
        return None

    def _g(side, key):
        return (by.get(side) or {}).get(key)

    vols = [_g(side, 'volume') for side in ('胜', '平', '负')]
    vol = sum(v for v in vols if isinstance(v, (int, float)))
    _ch = str((pack or {}).get('channel') or 'mobile')
    return {
        'available': True,
        'channel': _ch,
        'source': 'okooo_mobile_exchange' if _ch == 'mobile' else 'okooo_exchange',
        'unit': 'page_text',
        'home_profit_loss': _g('胜', 'pnl'),
        'draw_profit_loss': _g('平', 'pnl'),
        'away_profit_loss': _g('负', 'pnl'),
        'home_pnl': _g('胜', 'pnl'),
        'draw_pnl': _g('平', 'pnl'),
        'away_pnl': _g('负', 'pnl'),
        'home_volume': _g('胜', 'volume'),
        'draw_volume': _g('平', 'volume'),
        'away_volume': _g('负', 'volume'),
        'volume': vol or None,
        'writes_first_score': False,
    }


def _pack_reason(pack):
    """不可用原因：block_reason → reason → error → 'empty'，绝不吞掉真实原因。

    三个抓取器历史上只填 reason（如 external_fetch_not_configured），
    而日志只读 block_reason，于是真实原因被 'empty' 盖住。
    """
    if not isinstance(pack, dict):
        return 'invalid_payload'
    for key in ('block_reason', 'reason'):
        value = str(pack.get(key) or '').strip()
        if value:
            return value
    error = str(pack.get('error') or '').strip()
    if error:
        return error[:160]
    return 'empty'


def _attach_mobile_exchange_pnl(rec, match_id, proxies=None):
    """每场走手机竞足→析→盈亏，保存四块表。失败留空，不写 first_score。"""
    rec = rec if isinstance(rec, dict) else {}
    try:
        pack = scrape_okooo_mobile_exchange_pnl(match_id, proxies=proxies) or {}
    except Exception as _pnl_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [手机盈亏] 抓取失败: {_pnl_err}")
        pack = {
            'available': False,
            'channel': 'mobile',
            'source_path': '手机竞足→析→盈亏',
            'block_reason': 'attach_error',
            'writes_first_score': False,
        }
    rec['mobile_exchange_pnl'] = pack
    bf = _betfair_from_mobile_pnl(pack)
    if bf and not (isinstance(rec.get('betfair_data'), dict) and rec['betfair_data'].get('available')):
        rec['betfair_data'] = bf
    if pack.get('available'):
        _pnl_tag = '手机盈亏' if str(pack.get('channel') or '') == 'mobile' else '盈亏'
        print(
            f"   📱 [{_pnl_tag}] 保存={len((pack.get('jc_saved') or {}).get('rows') or [])} "
            f"人气={len((pack.get('jc_popularity') or {}).get('rows') or [])} "
            f"必发={len((pack.get('betfair_trade') or {}).get('rows') or [])} "
            f"分布={len((pack.get('trade_distribution') or {}).get('rows') or [])} "
            f"五要素={len((pack.get('five_elements') or {}).get('rows') or [])}"
        )
    else:
        print(f"   ⚠️ [手机盈亏] 不可用 reason={_pack_reason(pack)}")
    return pack


def _absence_count(pack):
    """伤停人数。兼容两种形状：[{side,name,...}] 或 [{rows:[...]}]。"""
    total = 0
    for item in (pack.get('absences') or []) if isinstance(pack.get('absences'), list) else []:
        if not isinstance(item, dict):
            continue
        if isinstance(item.get('rows'), list):
            total += len(item['rows'])
        elif item.get('name'):
            total += 1
    return total


