def _line_present(value):
    """盘口线算不算「有」。0.0（平手盘）算有；None/空串/空容器才算缺。"""
    if value is None:
        return False
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, (dict, list, tuple, set)):
        return bool(value)
    return True


def _merge_books_pack(prev, new):
    """公司明细包合并：抓取失败不要覆盖已经拿到的明细。

    失败包通常只有 available/block_reason，直接赋值会把上次抓到的
    companies + change.php 时间线整块冲掉，日志随即出现
    「亚指/大小 不可用」却又「AH=0.0 OU=2.5 来源 ah:ok」的自相矛盾。
    """
    prev = prev if isinstance(prev, dict) else {}
    new = new if isinstance(new, dict) else {}
    if not new:
        return prev or {'available': False}
    if new.get('available'):
        return new
    if not prev.get('available'):
        return new
    merged = dict(prev)
    # 失败原因保留在明细包里，便于日志诊断，但不改动已有数据。
    merged['last_attempt_reason'] = new.get('block_reason') or new.get('reason') or 'failed'
    return merged


def _attach_mobile_ah_ou_books(rec, match_id, proxies=None):
    """每场走手机竞足→析→亚指→大小球→最值。再点每家大小球公司，收下变化和时间线。不写 first_score。"""
    rec = rec if isinstance(rec, dict) else {}
    try:
        pack = scrape_okooo_mobile_ah_ou_books(match_id, proxies=proxies) or {}
    except Exception as _book_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [手机亚指/大小] 抓取失败: {_book_err}")
        pack = {
            'available': False,
            'channel': 'mobile',
            'source_path': '手机竞足→析→亚指→盘口→公司；析→亚指→大小球→最值→公司',
            'block_reason': 'attach_error',
            'writes_first_score': False,
            'changes_direction': False,
        }
    rec['mobile_ah_ou_books'] = _merge_books_pack(rec.get('mobile_ah_ou_books'), pack)
    pack = rec['mobile_ah_ou_books']
    ah_n = len(_as_dict(pack.get('asian_handicap')).get('companies') or [])
    ou_pack = _as_dict(pack.get('over_under'))
    ou_companies = ou_pack.get('companies') or []
    ou_n = len(ou_companies)
    ou_tl = sum(1 for row in ou_companies if isinstance(row, dict) and row.get('changes'))
    if pack.get('available'):
        _book_tag = '手机亚指/大小' if str(pack.get('channel') or '') == 'mobile' else '亚指/大小'
        print(f"   📱 [{_book_tag}] 亚指={ah_n} 大小球={ou_n} 大小球时间线={ou_tl}")
        if ou_n and not ou_tl and ou_pack.get('detail_block_reason'):
            print(f"   ⚠️ [手机大小球时间线] {ou_pack.get('detail_block_reason')}")
    else:
        # 公司明细抓取失败 ≠ 盘口线不可用。标量 AH/OU 由六盘口包提供，
        # 这里只说「公司明细不可用」，绝不因此把 AH/OU 置空（那会让日志出现
        # 「亚指/大小 不可用」旁边又写着「AH=0.0 OU=2.5 来源=ah:ok」的矛盾）。
        _have_lines = [
            name for name, key in (('AH', 'asian_handicap'), ('OU', 'ou_line'))
            if _line_present(rec.get(key))
        ]
        print(
            f"   ⚠️ [手机亚指/大小·公司明细] 不可用 reason={_pack_reason(pack)}"
            f"｜盘口线={'/'.join(_have_lines) if _have_lines else '无'}（明细失败不影响标量线）"
        )
    return pack


def _record_jc_handicap(rec):
    """竞彩让球整数。只认列表/落盘的整球，不把亚盘小数当成让球。"""
    rec = rec if isinstance(rec, dict) else {}
    for key in ('jc_handicap', 'jc_handicap_int', 'jingcai_handicap'):
        raw = rec.get(key)
        if raw is None or str(raw).strip() == '':
            continue
        try:
            val = float(raw)
        except (TypeError, ValueError):
            continue
        if abs(val - round(val)) > 1e-6 or abs(val) > 5:
            continue
        return float(round(val))
    return None


def _mobile_ou_line(rec):
    """只认已经标成手机通道的大小球盘口。500 兜底的 ou_line 不进六盘口。"""
    rec = rec if isinstance(rec, dict) else {}
    if str(rec.get('ou_channel') or '') != 'mobile':
        return None
    raw = rec.get('ou_line')
    if raw is None or str(raw).strip() == '':
        return None
    try:
        val = float(raw)
    except (TypeError, ValueError):
        return None
    if not (0.5 <= val <= 6.5):
        return None
    return round(val * 4.0) / 4.0


def _stamp_more_play_scores(rec, pack):
    """胜平负比分：竞足更多玩法 oddsData.SportteryScore，覆盖同键竞彩比分，不进市均。"""
    rec = rec if isinstance(rec, dict) else {}
    pack = pack if isinstance(pack, dict) else {}
    scores = _as_dict(pack.get('jc_score_odds'))
    if not scores:
        return 0
    # 同时落到 rec 上：31 全表重建要读 rec['jc_score_odds']（这是它的唯一写者）。
    if not rec.get('jc_score_odds'):
        rec['jc_score_odds'] = dict(scores)
    if pack.get('jc_score_source') and not rec.get('jc_score_source'):
        rec['jc_score_source'] = pack.get('jc_score_source')
    # 传带键的容器，而不是裸的比分映射：_okooo_apply_jc_score_fill 以前
    # 读 src['correct_score_jc_official'] / src['jc_score_odds']，
    # 裸映射两个键都没有，于是 correct_score_jc_official 永远写不进去（日志 jc=0）。
    return _okooo_apply_jc_score_fill(
        rec,
        {
            'jc_score_odds': scores,
            'correct_score_jc_official': scores,
        },
        source_note=pack.get('jc_score_source') or 'https://m.okooo.com/jczq/#oddsData.SportteryScore',
        overwrite=True,
    )


_WATER_FULL_SCRAPE_IDS = set()
_WATER_GAP_LOGGED = set()


def _water_gap_reason(rec, gaps):
    """把「为什么还缺」写成一句可诊断的话，直接来自各源的真实返回。"""
    six = _as_dict(rec.get('six_market_mobile'))
    report = _as_dict(six.get('source_report'))
    labels = {'asian_handicap': 'ah', 'ou_line': 'ou', 'odds_1x2': '1x2'}
    bits = []
    for gap in gaps:
        entry = _as_dict(report.get(labels.get(gap, '')))
        if not entry:
            bits.append(f'{gap}=无抓取记录')
            continue
        detail = f"{gap}:{entry.get('stage') or '-'}"
        if entry.get('status'):
            detail += f"/HTTP{entry.get('status')}"
        if entry.get('blocked'):
            detail += '/被拦截'
        elif entry.get('error'):
            detail += f"/{str(entry.get('error'))[:60]}"
        bits.append(detail)
    return '；'.join(bits)


def _log_water_gaps_once(rec, mid, gaps, prefix='   '):
    """每场只留一行水位结论：缺哪些字段 + 每个字段卡在哪一步。"""
    key = str(mid or '')
    if key and key in _WATER_GAP_LOGGED:
        return
    if key:
        _WATER_GAP_LOGGED.add(key)
    print(
        f"{prefix}[水位] mid={mid} 仍缺{'、'.join(gaps)}，不写待定"
        f"；原因: {_water_gap_reason(rec, gaps)}"
    )
_OKOOO_DETAIL_KEYS = (
    'correct_score_okooo', 'correct_score_page_avg', 'correct_score_books_avg',
    'correct_score_books_n', 'correct_score_site_avg', 'correct_score_jc_official',
    'correct_score_channel', 'correct_score_available', 'cs_fetch_url',
    'cs_block_reason', 'pool31_forbidden', 'okooo_match_id',
    'six_market_mobile', 'six_market_contradictions',
    'mobile_exchange_pnl', 'mobile_lineup', 'betfair_data', 'mobile_ah_ou_books',
    'prior_six_market_contradictions',
    'asian_handicap', 'ah_line', 'ah_channel', 'ou_line', 'ou_channel',
    'odds_1x2', 'odds_1x2_channel', 'jc_handicap',
    'jc_lottery_no', 'jc_morder', 'water_gaps',
    'jc_score_odds', 'jc_score_source', 'jc_score_orderid',
    # 明细与派生块：白名单曾经只收「水位标量」，于是 scrape_okooo_detail 新产出的
    # ah_detail（含 change.php 公司时间线）在这里被静默丢掉，seed 拿不到明细，
    # 记录里永远 0 家公司。新增生产者输出必须同步加进来（有测试盯着）。
    'ah_detail', 'ou_detail',
    'mobile_water_provenance', 'six_cs_settlement_v2', 'dual_source_facts',
    'water_scrape_finished',
    # 31 池的出处与完整性：pack 一直在产出这四项，白名单没列就整块丢掉，
    # 于是记录里只剩「已合并的 31 键市均」，下游再也分不清哪 9 项其实来自竞彩，
    # 31 行表把它们全标成 desktop_cs、市短还拿竞彩去比竞彩。
    'cs31_provenance', 'cs31_counts', 'cs31_extras', 'cs31_complete',
)


def _merge_okooo_detail_into_rec(rec, pack):
    """整场重抓的结果写回这场。水位包允许被空结果替换，不用旧盘口线充数。"""
    rec = rec if isinstance(rec, dict) else {}
    pack = pack if isinstance(pack, dict) else {}
    replace_even_empty = {
        'six_market_mobile', 'mobile_ah_ou_books', 'six_market_contradictions', 'water_gaps',
    }
    for key in _OKOOO_DETAIL_KEYS:
        if key not in pack:
            continue
        val = pack.get(key)
        if key not in replace_even_empty and val in (None, '', [], {}):
            continue
        if key == 'six_market_mobile':
            # 重抓失败时不要把已经抓到的竞彩31比分一起丢掉：新包没有的就沿用旧包。
            prev = rec.get('six_market_mobile')
            if isinstance(val, dict) and isinstance(prev, dict):
                for _keep in ('jc_score_odds', 'jc_score_source', 'jc_score_orderid'):
                    if not val.get(_keep) and prev.get(_keep):
                        val = dict(val)
                        val[_keep] = prev[_keep]
        rec[key] = val
    if isinstance(pack.get('markets'), dict) and pack.get('markets'):
        rec['okooo_markets'] = pack.get('markets')
    return rec


def _ensure_mobile_six(rec, mid, force=False):
    """已有比分市均时仍补抓手机六盘口，并记下矛盾供后续研判。

    六项水位任一没抓到，先整场重抓，不单补一块盘，也不用盘口线或 500 充水位。
    强制重抓条件（任一）：
    - force=True
    - 无 fetch_urls / 非 mobile
    - 缺核心盘口（胜平负∪亚盘∪大小）
    - 旧入口：fetch_urls 仍是 odds.php?Type=Asian/Overunder（无效页）
    """
    rec = rec if isinstance(rec, dict) else {}
    mid = str(mid or rec.get('okooo_match_id') or '').strip()
    if not mid:
        return False
    _water_gaps = missing_six_market_waters(rec)
    if _water_gaps:
        if str(mid) in _WATER_FULL_SCRAPE_IDS:
            rec['water_gaps'] = list(_water_gaps)
            _log_water_gaps_once(rec, mid, _water_gaps)
            return False
        # 单场单次：这一场这一轮只整场重抓一次，之后无论成败都封口。
        _WATER_FULL_SCRAPE_IDS.add(str(mid))
        print(f"   [水位重抓] mid={mid} 缺{'、'.join(_water_gaps)}，整场重新抓取（本场只重抓一次）")
        try:
            _pack = scrape_okooo_detail(mid, jc_handicap=_record_jc_handicap(rec), _water_attempt=1) or {}
        except Exception as _water_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   [水位重抓] 失败 mid={mid}: {type(_water_err).__name__}: {_water_err}")
            rec['water_gaps'] = list(_water_gaps)
            return False
        _merge_okooo_detail_into_rec(rec, _pack)
        _after = missing_six_market_waters(rec)
        rec['water_gaps'] = list(_after)
        if _after:
            _log_water_gaps_once(rec, mid, _after)
        else:
            print(f"   [水位] mid={mid} 六盘口已齐（本场重抓一次后补齐）")
        return True
    existing = _as_dict(rec.get('six_market_mobile'))
    _hit = _as_dict(existing.get('boards_hit'))
    _urls = [str(u) for u in (existing.get('fetch_urls') or [])]
    _stale_url = bool(_urls) and all(
        ('odds.php' in u and ('Type=Asian' in u or 'Type=Overunder' in u or 'Type=OU' in u))
        or False
        for u in _urls
    ) and not any('handicap.php' in u or 'ah.php' in u for u in _urls)
    # 仅欧指页三连打 = 旧爬虫，必须重抓
    _only_odds = bool(_urls) and all('odds.php' in u for u in _urls) and not any(
        'handicap.php' in u or 'ah.php' in u for u in _urls
    )
    _has_1x2 = bool(isinstance(existing.get('odds_1x2'), dict) and existing.get('odds_1x2'))
    _has_ah = existing.get('asian_handicap') is not None or bool(_hit.get('亚盘让球'))
    _has_ou = existing.get('ou_line') is not None or bool(_hit.get('大小球'))
    _total_goals_odds = existing.get('total_goals_odds')
    _has_tg = (
        isinstance(_total_goals_odds, dict)
        and len(_total_goals_odds) >= 4
        and existing.get('total_goals_source') == '手机竞足→更多玩法→总进球'
    )
    _htft_odds = existing.get('htft_odds')
    _has_hf = (
        isinstance(_htft_odds, dict)
        and len(_htft_odds) >= 6
        and existing.get('htft_source') == '手机竞足→更多玩法→半全场'
    )
    _jc_score_odds = existing.get('jc_score_odds')
    _has_sc = (
        isinstance(_jc_score_odds, dict)
        and len(_jc_score_odds) >= 20
        and existing.get('jc_score_source') == '手机竞足→更多玩法→胜平负比分'
    )
    _core_ok = bool(
        existing.get('channel') == 'mobile'
        and _urls
        and not _stale_url
        and not _only_odds
        and _has_1x2
        and _has_ah
        and _has_ou
        and _has_tg
        and _has_hf
        and _has_sc
    )
    if _core_ok and not force:
        _attach_mobile_lineup_if_missing(rec, mid)
        if existing.get('jc_handicap') is not None:
            return False
        _list_jc = _record_jc_handicap(rec)
        if _list_jc is None:
            return False
        existing['jc_handicap'] = _list_jc
        existing['jc_handicap_source'] = existing.get('jc_handicap_source') or 'mobile_jingcai_list'
        _boards = dict(existing.get('boards_hit') or {})
        _boards['竞彩让球胜平负'] = True
        existing['boards_hit'] = _boards
        existing['missing'] = [k for k in (existing.get('missing') or []) if k != '竞彩让球胜平负']
        rec['six_market_mobile'] = existing
        rec['jc_handicap'] = _list_jc
        if rec.get('jc_handicap_int') is None:
            rec['jc_handicap_int'] = int(_list_jc)
        cons = detect_six_market_contradictions(existing)
        rec['six_market_contradictions'] = cons
        rec['prior_six_market_contradictions'] = load_six_market_contradictions(mid)
        save_six_market_contradictions(mid, cons)
        print(f"   📱 [澳客手机·竞彩让球] 用竞足列表让球补上 { _list_jc:g}")
        return True
    try:
        pack = scrape_okooo_mobile_six_markets(mid, jc_handicap=_record_jc_handicap(rec)) or {}
    except Exception as _e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [手机六盘口] 补抓失败: {_e}")
        return False
    rec['six_market_mobile'] = pack
    _attach_mobile_exchange_pnl(rec, mid)
    _attach_mobile_lineup_if_missing(rec, mid)
    _attach_mobile_ah_ou_books(rec, mid)
    # seed 的第一个参数是**记录**（它自己读 record['mobile_ah_ou_books']）。
    # 这里曾把 books 包当记录传进去：函数内部读不到已挂上的明细，就把六盘口包
    # 整个当成结果返回，赋值又把 books 包覆盖掉，公司明细与时间线全丢。
    seed_mobile_ah_ou_books(rec, pack)
    _ou_before = pack.get('ou_line')
    _ah_before = pack.get('asian_handicap')
    apply_mobile_books_lines(rec)
    if _ou_before is None and pack.get('ou_line') is not None:
        print(f"   📱 [大小球盘口] 六盘口页未抓到，改用手机公司盘众数 {pack.get('ou_line')}")
    if _ah_before is None and pack.get('asian_handicap') is not None:
        print(f"   📱 [亚盘盘口] 六盘口页未抓到，改用手机公司盘众数 {pack.get('asian_handicap')}")
    cons = detect_six_market_contradictions(pack)
    rec['six_market_contradictions'] = cons
    rec['prior_six_market_contradictions'] = load_six_market_contradictions(mid)
    save_six_market_contradictions(mid, cons)
    if pack.get('asian_handicap') is not None:
        rec['asian_handicap'] = pack.get('asian_handicap')
        rec['ah_line'] = pack.get('asian_handicap')
        rec['ah_channel'] = 'mobile'
    if pack.get('ou_line') is not None:
        rec['ou_line'] = pack.get('ou_line')
        rec['ou_channel'] = 'mobile'
    elif _mobile_ou_line(rec) is not None:
        _kept_ou = _mobile_ou_line(rec)
        pack['ou_line'] = _kept_ou
        pack['ou_line_source'] = 'mobile_prior'
        _ou_boards = dict(pack.get('boards_hit') or {})
        _ou_boards['大小球'] = True
        pack['boards_hit'] = _ou_boards
        pack['missing'] = [k for k in (pack.get('missing') or []) if k != '大小球']
        cons = detect_six_market_contradictions(pack)
        rec['six_market_contradictions'] = cons
        print(f"   📱 [澳客手机·大小球] 沿用已抓到的手机盘口 {_kept_ou:g}")
    if isinstance(pack.get('odds_1x2'), dict) and pack.get('odds_1x2'):
        rec['odds_1x2'] = pack.get('odds_1x2')
        rec['odds_1x2_channel'] = 'mobile'
    if pack.get('jc_handicap') is not None:
        rec['jc_handicap'] = pack.get('jc_handicap')
    _stamp_more_play_scores(rec, pack)
    _report_raw = pack.get('source_report')
    _report: dict[str, Any] = _report_raw if isinstance(_report_raw, dict) else {}
    _report_text = '；'.join(
        '{k}:{stage}/HTTP{status}'.format(
            k=key,
            stage=(value or {}).get('stage') or '-',
            status=(value or {}).get('status'),
        )
        for key, value in _report.items()
        if isinstance(value, dict)
    ) or '无'
    print(
        f"   🔄 [手机六盘口] mid={mid} "
        f"AH={pack.get('asian_handicap')} OU={pack.get('ou_line')} "
        f"1X2={'有' if pack.get('odds_1x2') else '无'} "
        f"缺={','.join(pack.get('missing') or []) or '无'} | 来源={_report_text}"
    )
    _after_gaps = missing_six_market_waters(rec)
    if _after_gaps and str(mid) not in _WATER_FULL_SCRAPE_IDS:
        _WATER_FULL_SCRAPE_IDS.add(str(mid))
        print(f"   [水位重抓] mid={mid} 缺{'、'.join(_after_gaps)}，整场重新抓取（本场只重抓一次）")
        try:
            _pack = scrape_okooo_detail(mid, jc_handicap=_record_jc_handicap(rec), _water_attempt=1) or {}
        except Exception as _water_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   [水位重抓] 失败 mid={mid}: {type(_water_err).__name__}: {_water_err}")
            rec['water_gaps'] = list(_after_gaps)
            return True
        _merge_okooo_detail_into_rec(rec, _pack)
        _left_after = missing_six_market_waters(rec)
        rec['water_gaps'] = list(_left_after)
        if _left_after:
            _log_water_gaps_once(rec, mid, _left_after)
        else:
            print(f"   [水位] mid={mid} 六盘口已齐（本场重抓一次后补齐）")
    elif _after_gaps:
        rec['water_gaps'] = list(_after_gaps)
        _log_water_gaps_once(rec, mid, _after_gaps)
    return True


def enrich_history_okooo_cs_facts(rec, cn_name='', force_rescrape=False):
    """发报前补齐 okooo_match_id + 手机市均/竞方（写入 rec 原地）。返回是否补到可用市均。"""
    rec = rec if isinstance(rec, dict) else {}
    cn = str(cn_name or rec.get('match') or rec.get('cn_name') or '')
    mid = str(rec.get('okooo_match_id') or '').strip()
    has_cs = bool(
        (isinstance(rec.get('correct_score_jc_official'), dict) and rec.get('correct_score_jc_official'))
        or (isinstance(rec.get('correct_score_books_avg'), dict) and rec.get('correct_score_books_avg'))
        or (isinstance(rec.get('score_market_heat'), dict) and (rec.get('score_market_heat') or {}).get('ranking'))
    )
    if has_cs and mid and not force_rescrape:
        _ensure_mobile_six(rec, mid)
        return True
    if not mid:
        try:
            _tmp = attach_okooo_ids_to_matches([{
                'no': str(rec.get('no') or rec.get('local_id') or ''),
                'cn': cn,
                'cn_name': cn,
                'match': cn,
                'home': rec.get('home') or '',
                'away': rec.get('away') or '',
            }])
            if _tmp and _tmp[0].get('okooo_match_id'):
                mid = str(_tmp[0]['okooo_match_id'])
                rec['okooo_match_id'] = mid
                if _tmp[0].get('jc_handicap_int') is not None:
                    rec['jc_handicap'] = _tmp[0]['jc_handicap_int']
                    rec['jc_handicap_int'] = _tmp[0]['jc_handicap_int']
                # 强制完整队名回写
                _hn = str(_tmp[0].get('home') or '').strip()
                _an = str(_tmp[0].get('away') or '').strip()
                if _hn and _an:
                    rec['home'] = _hn
                    rec['away'] = _an
                    rec['match'] = f"{_hn} vs {_an}"
                    if not rec.get('cn_name') or ' vs ' in str(rec.get('cn_name') or ''):
                        _no = str(rec.get('no') or _tmp[0].get('no') or '').strip()
                        rec['cn_name'] = f"[{_no}] {_hn} vs {_an}".strip() if _no else f"{_hn} vs {_an}"
                for _tk in ('match_time', 'time', 'kickoff_time'):
                    if _tmp[0].get(_tk) and not rec.get(_tk):
                        rec[_tk] = _tmp[0].get(_tk)
                print(f"   🔗 [补挂] {cn} → okooo_match_id={mid} | {_hn} vs {_an}")
        except Exception as _e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [补挂] 失败: {_e}")
    if not mid:
        print(f"   ⚠️ [补挂] 无法解析澳客ID: {cn}")
    elif has_cs and not force_rescrape:
        _ensure_mobile_six(rec, mid)
        return True
    elif mid:
        try:
            pack = {}
            try:
                pack = scrape_okooo_detail(mid) or {}
            except Exception as _det_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                print(f"   ⚠️ [补抓] scrape_okooo_detail 失败，改直调手机CS: {_det_err}")
                pack = {}
            if not (isinstance(pack, dict) and pack.get('correct_score_available')):
                try:
                    pack = scrape_okooo_mobile_cs_zuizhi(
                        mid,
                        kickoff=(
                            rec.get('kickoff') or rec.get('time')
                            or rec.get('match_time') or rec.get('bj_time')
                        ),
                        match_name=cn or rec.get('match') or rec.get('cn_name'),
                        lottery_no=rec.get('jc_lottery_no') or rec.get('lottery_no'),
                    ) or {}
                except Exception as _mob_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [补抓] 手机CS失败: {_mob_err}")
                    pack = {}
            if isinstance(pack, dict) and pack:
                # 与 _merge_okooo_detail_into_rec 共用同一份键表：两处各留一份拷贝
                # 必然漂移（这里曾漏掉 jc_score_odds/jc_score_source/jc_score_orderid）。
                for _ck in _OKOOO_DETAIL_KEYS:
                    if pack.get(_ck) not in (None, '', [], {}):
                        rec[_ck] = pack.get(_ck)
                if isinstance(pack.get('markets'), dict):
                    rec['okooo_markets'] = pack.get('markets')
                _page = pack.get('correct_score_page_avg') or pack.get('correct_score_books_avg')
                try:
                    _hb = build_score_market_heat_ranking(
                        correct_score_rows=pack.get('correct_score_okooo') or [],
                        pool_enriched=None,
                        page_avg_odds=_page if isinstance(_page, dict) else None,
                        **_cs_heat_labels(pack),
                    )
                    if isinstance(_hb, dict) and _hb.get('ranking'):
                        rec['score_market_heat'] = _hb
                except Exception as _he:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    print(f"   ⚠️ [补挂市热] {_he}")
                # 「可用」不能只看竞彩官方比分或市热排行：桌面 /cs/ 的市均
                # 只写 correct_score_page_avg / books_avg（jc 官方与 heat 都可能空），
                # 旧条件会把刚抓到的 25 家市均判成不可用，然后白跑一趟 500 兜底。
                ok = bool(
                    (isinstance(rec.get('correct_score_jc_official'), dict) and rec.get('correct_score_jc_official'))
                    or (isinstance(rec.get('score_market_heat'), dict) and (rec.get('score_market_heat') or {}).get('ranking'))
                    or (isinstance(rec.get('correct_score_page_avg'), dict) and rec.get('correct_score_page_avg'))
                    or (isinstance(rec.get('correct_score_books_avg'), dict) and rec.get('correct_score_books_avg'))
                    or (isinstance(rec.get('correct_score_site_avg'), dict) and rec.get('correct_score_site_avg'))
                )
                if ok:
                    print(f"   OK [补抓CS] mid={mid} available={ok}")
                    _ensure_mobile_six(rec, mid)
                    # 手机市均抓到后也必须走双源互补，确认比分进入整合包
                    try:
                        from odds_fallback import (
                            ensure_dual_source_before_judgment as _ensure_dual,
                        )
                        _gate = _ensure_dual(rec)
                        print(
                            f"   ✅ [双源互补] ready={_gate.get('ready')} "
                            f"mobile_cs_entered={_gate.get('mobile_cs_entered')} "
                            f"cs_n={_gate.get('cs_books_n')} reason={_gate.get('reason')}"
                        )
                    except Exception as _dual_ok_e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                        print(f"   ⚠️ [双源互补] {_dual_ok_e}")
                    return True
        except Exception as _cs_e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [补抓CS] 异常: {_cs_e}")

    # ── 手机失败 / 无澳客ID：live.500.com + 析页清洗兜底（骨架仍走 DeepSeek 对比表）──
    # 竞彩 31 比分赔率齐全时，31 项已有真实市场赔率，不必再跑 500 兜底。
    # 注意：这不影响前面的市均抓取（books_avg/page_avg 仍要抓，供 heat 与双源闸门用）。
    # 判「要不要跑 500 兜底」之前，必须先把 jc31 抓到手。
    # 这行以前没有：guard 读的正是还没被填充的字段（实测 jc=0 → 500 兜底白跑一趟，
    # 而 _ensure_mobile_six 在 27961 才把 jc31 写进来）。
    # _ensure_mobile_six 自身有 _core_ok 短路，数据已在时几乎不花时间。
    if mid and not rec.get('jc_score_odds'):
        try:
            _ensure_mobile_six(rec, mid)
        except Exception as _jc_pre_err:  # noqa: BLE001 - 预取失败仍按原逻辑走兜底
            print(f"   ℹ️ [兜底] jc31 预取跳过: {type(_jc_pre_err).__name__}")
    _jc31_n = len(rec.get('jc_score_odds') or {}) if isinstance(rec.get('jc_score_odds'), dict) else 0
    if _jc31_n >= 31:
        print(
            f"   ℹ️ [兜底] 竞彩31比分赔率已齐（{_jc31_n}项），31池市场概率有合法来源，"
            f"跳过 live.500.com 兜底: {cn}"
        )
        return False
    try:
        from odds_fallback import apply_fallback_cs_to_rec, odds_fallback_enabled
        if odds_fallback_enabled():
            print(f"   🔁 [兜底] 澳客手机市均不可用，改抓 live.500.com/析页: {cn}")
            heat_fb = apply_fallback_cs_to_rec(rec, m_obj={
                'id': rec.get('id'),
                'fixture_id_500': rec.get('fixture_id_500'),
                'home': rec.get('home_team') or rec.get('home'),
                'away': rec.get('away_team') or rec.get('away'),
                'match': rec.get('match'),
                'no': rec.get('no'),
                'api_fixture_id': rec.get('api_fixture_id'),
            })
            # 500 盘口线只进 fallback_* 对照，不写入 six_market_mobile。
            _fenxi = _as_dict(rec.get('fallback_500_fenxi'))
            if _fenxi.get('available'):
                _notes = _fenxi.get('analysis_notes') or []
                print(
                    f"   ✅ [500析页] pages={len(_fenxi.get('pages') or {})} "
                    f"notes={len(_notes)} channel=fallback_500"
                )
                for _n in _notes[:4]:
                    print(f"      · {_n}")
            else:
                print("   ℹ️ [兜底] 500 盘口不写入亚盘、大小球和胜平负水位")
            ok_fb = bool(
                (isinstance(heat_fb, dict) and heat_fb.get('available'))
                or _fenxi.get('available')
            )
            print(
                f"   {'OK' if ok_fb else 'WARN'} [兜底] "
                f"source={heat_fb.get('source') if isinstance(heat_fb, dict) else None} "
                f"fenxi={bool(_fenxi.get('available'))}"
            )
            try:
                from odds_fallback import (
                    ensure_dual_source_before_judgment as _ensure_dual,
                )
                _gate = _ensure_dual(rec)
                _gate_line = (
                    f"ready={_gate.get('ready')} "
                    f"mobile_cs_entered={_gate.get('mobile_cs_entered')} "
                    f"cs_n={_gate.get('cs_books_n')} "
                    f"fill500={len(_gate.get('filled_from_500') or [])}"
                )
                if _gate.get('ready'):
                    print(f"   ✅ [双源互补] {_gate_line}")
                else:
                    print(f"   ⚠️ [双源互补] {_gate_line} reason={_gate.get('reason') or '未给出原因'}")
            except Exception as _dual_fb_e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                print(f"   ⚠️ [双源互补] 闸门异常: {type(_dual_fb_e).__name__}: {_dual_fb_e}")
            if mid:
                _ensure_mobile_six(rec, mid)
            return ok_fb
    except Exception as _fb_e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [兜底] 异常: {_fb_e}")
    return False


def scrape_okooo_detail(match_id, proxies=None, jc_handicap=None, _water_attempt=0):
    """手机竞足比分市均与六盘口。桌面分析页不抓，盘口数字只认手机澳客。

    胜平负、竞彩让球、总进球、半全场、亚盘、大小球任一水位没抓到，整场再抓一次。
    盘口线不算水位。第二次仍缺就记下 water_gaps，不用 500 或桌面填。
    """
    if not match_id:
        return {}
    result = {'okooo_match_id': str(match_id), 'markets': {}}
    if proxies is None:
        _proxies = _http_routes()[0]
    else:
        _proxies = proxies
    print(f"      [澳客手机] 直接抓比分市均与六盘口 match_id={match_id}")
    # ===== 5. 比分市均（写死：仅手机 竞足→欧指→比分→最值；禁止 desktop/pool31）=====
    try:
        _cs_pack = scrape_okooo_mobile_cs_zuizhi(
            match_id,
            proxies=_proxies,
            kickoff=result.get('kickoff') or result.get('time') or result.get('match_time'),
            match_name=result.get('match') or result.get('cn_name') or '',
            lottery_no=result.get('jc_lottery_no') or result.get('lottery_no'),
        )
        if isinstance(_cs_pack, dict) and _cs_pack.get('available'):
            for _k in (
                'correct_score_okooo', 'correct_score_page_avg',
                'correct_score_books_avg', 'correct_score_books_n',
                'correct_score_site_avg', 'correct_score_jc_official',
                'correct_score_channel', 'cs_fetch_url', 'source_note',
                'pool31_forbidden', 'markets', 'voting_3d',
            ):
                if _k in _cs_pack:
                    result[_k] = _cs_pack[_k]
            if isinstance(result.get('markets'), dict) and isinstance(_cs_pack.get('markets'), dict):
                result['markets'].update(_cs_pack.get('markets') or {})
            result['correct_score_available'] = True
            result['correct_score_channel'] = str(_cs_pack.get('correct_score_channel') or '')
            result['pool31_forbidden'] = True
            print(
                f"      ✅ [澳客比分] 市均可用 channel={result.get('correct_score_channel') or '-'} "
                f"books={len(result.get('correct_score_books_avg') or {})} "
                f"jc={len(result.get('correct_score_jc_official') or {})}"
            )
        else:
            result['correct_score_available'] = False
            result['correct_score_channel'] = ''
            result['pool31_forbidden'] = True
            if isinstance(_cs_pack, dict) and isinstance(_cs_pack.get('correct_score_jc_official'), dict):
                result['correct_score_jc_official'] = _cs_pack.get('correct_score_jc_official')
            _cs_reason = 'empty_payload'
            _cs_detail = ''
            if isinstance(_cs_pack, dict):
                _cs_reason = str(_cs_pack.get('block_reason') or _cs_pack.get('reason') or 'empty_payload')
                _cs_detail = str(_cs_pack.get('error') or '').strip()
                result['cs_block_reason'] = _cs_reason
                if _cs_detail:
                    result['cs_block_detail'] = _cs_detail
            print(
                f"      ⚠️ [澳客手机CS] 不可用 reason={_cs_reason}"
                + (f" | {_cs_detail}" if _cs_detail else '')
            )
    except Exception as _cs_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"      ⚠️ [澳客手机CS] 挂接异常: {type(_cs_err).__name__}: {_cs_err}")
        result['correct_score_available'] = False
        result['correct_score_channel'] = ''
        result['pool31_forbidden'] = True
    try:
        _jc_known = _record_jc_handicap(result)
        if _jc_known is None:
            _jc_known = _record_jc_handicap({'jc_handicap': jc_handicap})
        _six = scrape_okooo_mobile_six_markets(
            match_id, proxies=_proxies, jc_handicap=_jc_known,
        )
        result['six_market_mobile'] = _six if isinstance(_six, dict) else {'available': False}
        _cons = detect_six_market_contradictions(result['six_market_mobile'])
        result['six_market_contradictions'] = _cons
        result['prior_six_market_contradictions'] = load_six_market_contradictions(match_id)
        save_six_market_contradictions(match_id, _cons)
        _six_ok = result['six_market_mobile']
        if _six_ok.get('asian_handicap') is not None:
            result['asian_handicap'] = _six_ok.get('asian_handicap')
            result['ah_line'] = _six_ok.get('asian_handicap')
            result['ah_channel'] = 'mobile'
        if _six_ok.get('ou_line') is not None:
            result['ou_line'] = _six_ok.get('ou_line')
            result['ou_channel'] = 'mobile'
        if isinstance(_six_ok.get('odds_1x2'), dict) and _six_ok.get('odds_1x2'):
            result['odds_1x2'] = _six_ok.get('odds_1x2')
            result['odds_1x2_channel'] = 'mobile'
        if _six_ok.get('jc_handicap') is not None:
            result['jc_handicap'] = _six_ok.get('jc_handicap')
        _stamp_more_play_scores(result, _six_ok)
        print(
            f"      📱 [澳客手机·六盘口矛盾] {len(_cons)}条 "
            f"（含缺项 {sum(1 for x in _cons if x.get('kind')=='missing_board')}）"
        )
        _attach_mobile_exchange_pnl(result, match_id, proxies=_proxies)
        _attach_mobile_lineup(result, match_id, proxies=_proxies)
        _attach_mobile_ah_ou_books(result, match_id, proxies=_proxies)
        # 同上：传记录，不传 books 包；返回值也不要再赋回同一个键。
        seed_mobile_ah_ou_books(result, result.get('six_market_mobile'))
        _ou_before = _six_ok.get('ou_line')
        _ah_before = _six_ok.get('asian_handicap')
        apply_mobile_books_lines(result)
        if _ou_before is None and _six_ok.get('ou_line') is not None:
            print(f"      📱 [大小球盘口] 六盘口页未抓到，改用手机公司盘众数 {_six_ok.get('ou_line')}")
        if _ah_before is None and _six_ok.get('asian_handicap') is not None:
            print(f"      📱 [亚盘盘口] 六盘口页未抓到，改用手机公司盘众数 {_six_ok.get('asian_handicap')}")
        # 六盘口 × 波胆市均对比清算 v2（返还率/即时概率/凯利/主盘；不写 first_score）
        try:
            from odds_index_math import apply_six_cs_settlement_v2_to_rec
            _set_v2 = apply_six_cs_settlement_v2_to_rec(result)
            if isinstance(_set_v2, dict) and _set_v2.get('available'):
                _led = _set_v2.get('ledger') or {}
                print(
                    f"      ✅ [六盘口×市均清算v2] status={_led.get('data_status')} "
                    f"ah={_led.get('ah_line')} ou={_led.get('ou_line')} "
                    f"cs={_led.get('cs_market_count')} cos={_led.get('filtered_company_count')}"
                )
            else:
                print(
                    "      ⚠️ [六盘口×市均清算v2] 未形成 "
                    f"reason={(_set_v2 or {}).get('block_reason') or 'missing_inputs'}"
                )
        except Exception as _set_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"      ⚠️ [六盘口×市均清算v2] {_set_err}")
    except Exception as _six_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"      ⚠️ [澳客手机·六盘口] 挂接异常: {_six_err}")
        result['six_market_mobile'] = {'available': False, 'channel': 'mobile', 'block_reason': 'attach_error'}
        result['six_market_contradictions'] = []
    _water_gaps = missing_six_market_waters(result)
    result['water_gaps'] = list(_water_gaps)
    # 只有第一次进抓取时才允许一次整场重抓；重抓后无论成败都封口，绝不再来第二轮。
    if _water_gaps and _water_attempt == 0 and str(match_id) not in _WATER_FULL_SCRAPE_IDS:
        _WATER_FULL_SCRAPE_IDS.add(str(match_id))
        print(f"      [水位重抓] mid={match_id} 缺{'、'.join(_water_gaps)}，整场重抓一次")
        try:
            _retry_pack = scrape_okooo_detail(
                match_id,
                proxies=proxies,
                jc_handicap=jc_handicap,
                _water_attempt=_water_attempt + 1,
            ) or {}
        except Exception as _water_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"      [水位重抓] 失败 mid={match_id}: {type(_water_err).__name__}: {_water_err}")
            _retry_pack = {}
        if isinstance(_retry_pack, dict) and _retry_pack:
            _merge_okooo_detail_into_rec(result, _retry_pack)
        _water_gaps = missing_six_market_waters(result)
        result['water_gaps'] = list(_water_gaps)
    # 记账；不要把 finish_match_water_scrape 的返回值赋回 result（那会把整场结果换成一个空壳）。
    # 第三个参数是模块缺失兜底桩的签名；真实模块用 *args 收下，忽略即可。
    finish_match_water_scrape(result, _water_attempt, None)
    if _water_gaps:
        _log_water_gaps_once(result, match_id, _water_gaps, prefix='      ')
    else:
        print(f"      [水位] mid={match_id} 六盘口水位已齐")
    # 抓取结束即做双源整合骨架：手机市均必须进入 dual_source_facts（500 在 analyze 再并入）
    try:
        from odds_fallback import (
            ensure_dual_source_before_judgment as _ensure_dual_scrape,
        )
        _gate_sc = _ensure_dual_scrape(result)
        if _gate_sc.get('mobile_cs_entered'):
            print(
                f"      ✅ [双源互补·抓取末] mobile_cs_entered "
                f"cs_n={_gate_sc.get('cs_books_n')} ready={_gate_sc.get('ready')}"
            )
        elif str(result.get('correct_score_channel') or '') == 'mobile':
            print(
                f"      ⚠️ [双源互补·抓取末] 手机市均未进入整合包 "
                f"reason={_gate_sc.get('reason')}"
            )
    except Exception as _dual_sc_e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"      ⚠️ [双源互补·抓取末] {type(_dual_sc_e).__name__}: {_dual_sc_e}")
    return result


# ================= 【必发交易盈亏数据抓取】 =================

def normalize_team_name_suffixes(name):
    """去掉 U23/亚足/女足等后缀，供队名模糊匹配。缺这个函数时整段匹配会直接失败。"""
    text = str(name or '').strip()
    text = re.sub(r'[\s·.\-]+', '', text)
    for token in (
        'U23', 'U21', 'U20', 'U19', 'U18', 'U17',
        '亚足联', '亚足', '国奥', '奥运队', '奥林匹克',
        '女足', '女子',
    ):
        text = text.replace(token, '')
    return text.strip()


def scrape_betfair_profit_loss(match_info):
    """
    抓取必发(Betfair)交易盈亏数据 — 基于澳客网真实页面结构解析。
    
    页面结构（已验证）：
      - 每场比赛: div(含球队名header) + table#table(3行数据: 主胜/平局/客胜)
      - 球队名在 table 的前一个兄弟 div 中，格式如: "周二201友谊赛06-03 00:00[11][世]克罗地亚(-1)VS比利时[9][世]"
      - 表格每行最后一个数字是"模拟盈亏"（港元），第一个数字是"总成交额"（港元）
    
    Args:
        match_info: dict, 包含 cn_name 等比赛标识信息
    
    Returns:
        dict: 必发盈亏数据结构
    """
    from bs4 import BeautifulSoup
    _verify_tls = not _allow_insecure_ssl()
    if not _verify_tls:
        import urllib3
        urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)
    
    result = {
        'available': False,
        'home_profit_loss': None,
        'draw_profit_loss': None,
        'away_profit_loss': None,
        'volume': None,
        'home_volume': None,
        'draw_volume': None,
        'away_volume': None,
        'betfair_index': None,
        'kelly_index': None,
        'source': '',
        'analysis_hint': '',
        'raw_data': {},
    }
    
    cn_name = match_info.get('cn_name', '')
    
    _headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 '
                      '(KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
        'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8',
    }
    _max_retries = 2
    _verify_tls = not _allow_insecure_ssl()
    
    def _request_with_retry(url, headers=None, timeout=15, referer=None):
        """代理端口活着才走 7897，拒绝连接时改直连，不把环境代理再带上。"""
        _h = dict(_headers)
        if headers:
            _h.update(headers)
        if referer:
            _h['Referer'] = referer
        for _retry in range(_max_retries):
            for _px in _http_routes():
                try:
                    _proxies = cast(dict[str, str] | None, None if _px is _DIRECT_PROXIES else _px)
                    resp = requests.get(url, headers=_h, proxies=_proxies,
                                       timeout=timeout, verify=_verify_tls)
                    if resp.status_code == 200:
                        return resp
                except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    if _px is not _DIRECT_PROXIES:
                        _forget_dead_proxy()
                    continue
        return None
    
    # 提取球队名关键词用于匹配
    _home_team = ''
    _away_team = ''
    if ' vs ' in cn_name.lower():
        _parts = re.split(r'\s+vs\s+', cn_name, flags=re.IGNORECASE)
        _home_team = _parts[0].strip().split(']')[-1].strip() if ']' in _parts[0] else _parts[0].strip()
        _away_team = _parts[1].strip() if len(_parts) > 1 else ''
    elif 'vs' in cn_name.lower():
        _parts = re.split(r'vs', cn_name, flags=re.IGNORECASE)
        _home_team = _parts[0].strip().split(']')[-1].strip() if ']' in _parts[0] else _parts[0].strip()
        _away_team = _parts[1].strip() if len(_parts) > 1 else ''
    
    if not _home_team and not _away_team:
        print(f"      ⚠️ [必发盈亏] 无法从 cn_name='{cn_name}' 提取球队名")
        result['analysis_hint'] = '无法提取球队名，必发数据跳过'
        match_id = str(
            match_info.get('okooo_match_id') or match_info.get('match_id') or ''
        ).strip()
        proxies = match_info.get('proxies')
        # 手机路径比分市均（强制）：竞足→欧指→/cs/最值；失败则空市均，禁止 desktop/pool31 冒充
        try:
            _cs_pack = scrape_okooo_mobile_cs_zuizhi(
                match_id,
                proxies=proxies,
                kickoff=(
                    match_info.get('kickoff') or match_info.get('time')
                    or match_info.get('match_time')
                ),
                match_name=cn_name or match_info.get('match') or '',
                lottery_no=match_info.get('jc_lottery_no') or match_info.get('lottery_no'),
            )
            if isinstance(_cs_pack, dict) and _cs_pack.get('available'):
                result.update({
                    k: _cs_pack[k]
                    for k in (
                        'correct_score_okooo', 'correct_score_page_avg',
                        'correct_score_books_avg', 'correct_score_books_n',
                        'correct_score_site_avg', 'correct_score_jc_official',
                        'correct_score_channel', 'cs_fetch_url', 'source_note',
                        'pool31_forbidden', 'markets', 'voting_3d',
                    )
                    if k in _cs_pack
                })
                if isinstance(result.get('markets'), dict) and isinstance(_cs_pack.get('markets'), dict):
                    result['markets'].update(_cs_pack.get('markets') or {})
                result['correct_score_available'] = True
            else:
                result['correct_score_available'] = False
                result['correct_score_channel'] = ''
                result['pool31_forbidden'] = True
                if isinstance(_cs_pack, dict) and _cs_pack.get('block_reason'):
                    result['cs_block_reason'] = _cs_pack.get('block_reason')
        except Exception as _cs_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"      ⚠️ [澳客手机CS] 挂接异常: {_cs_err}")
            result['correct_score_available'] = False

        return result
    
    # 取球队名前2-3个字用于初筛（中文球队名通常2-4字）
    _home_key = _home_team[:3] if len(_home_team) >= 3 else _home_team[:2]
    _away_key = _away_team[:3] if len(_away_team) >= 3 else _away_team[:2]
    print(f"      📡 [必发盈亏] 匹配关键词: 主={_home_key}(全称:{_home_team}) 客={_away_key}(全称:{_away_team})")
    
    # ===== 模糊匹配函数：使用 difflib + 多策略融合 =====
    from difflib import SequenceMatcher

    # =====================================================================
    # 【修复·问题3】必发盈亏数据源的"中文队名孤岛"效应 —— 通用队名模糊匹配
    # 根因：国内不同数据源对小语种球队的翻译极不统一
    #      （如"库奥皮"vs"库奥皮奥"、"萨巴赫"vs"萨巴赫队"），
    #      精确匹配失败导致"澳客网未匹配到"→"所有数据源均未获取到"。
    # 方案：四级递进匹配——精确 → 子串包含（双向）→ 去常见后缀 → 编辑距离。
    # =====================================================================
    def fuzzy_match_team_name(target_name, candidate_list):
        """模糊匹配队名：精确→子串包含→去后缀→编辑距离（带安全降级）。

        Args:
            target_name: 目标队名（如 '库奥皮'）
            candidate_list: 候选队名列表（如页面上提取的所有队名）
        Returns:
            匹配到的候选队名，或 None
        """
        try:
            if not target_name or not candidate_list:
                return None
            target = str(target_name).strip()
            if not target:
                return None
            # 1. 精确匹配（最高优先级）
            for c in candidate_list:
                try:
                    if str(c).strip() == target:
                        return c
                except Exception:  # noqa: BLE001,S112 - intentional degraded-mode guard or structure-preserving fallback  # nosec B112  # intentional degraded-mode continue fallback
                    continue
            # 2. 子串包含（双向：如"库奥皮"包含于"库奥皮奥"）
            for c in candidate_list:
                try:
                    _c = str(c).strip()
                    if _c and (target in _c or _c in target):
                        return c
                except Exception:  # noqa: BLE001,S112 - intentional degraded-mode guard or structure-preserving fallback  # nosec B112  # intentional degraded-mode continue fallback
                    continue
            # 3. 去除常见后缀（含 U23/亚足/国奥 归一后再比）后再双向子串匹配
            suffixes = ['队', 'FC', '联', '足球俱乐部', '俱乐部', '体育会', '竞技', 'SC', 'CF',
                        '亚足联', '亚足', '国奥', '奥运队', '奥林匹克', '女足', '女子']
            clean_target = normalize_team_name_suffixes(target)
            for s in suffixes:
                clean_target = clean_target.replace(s, '')
            if clean_target:
                for c in candidate_list:
                    try:
                        clean_c = normalize_team_name_suffixes(str(c).strip())
                        for s in suffixes:
                            clean_c = clean_c.replace(s, '')
                        if clean_c and (clean_target in clean_c or clean_c in clean_target):
                            return c
                    except Exception:  # noqa: BLE001,S112 - intentional degraded-mode guard or structure-preserving fallback  # nosec B112  # intentional degraded-mode continue fallback
                        continue
            # 3.5 U23/亚足 归一后全名精确/子串
            try:
                _nt = normalize_team_name_suffixes(target)
                for c in candidate_list:
                    _nc = normalize_team_name_suffixes(str(c).strip())
                    if _nt and _nc and (_nt == _nc or _nt in _nc or _nc in _nt):
                        return c
            except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
                pass
            # 4. 编辑距离兄弟方案：difflib 相似度（等价于归一化 Levenshtein）作为最后手段
            _best_c, _best_ratio = None, 0.0
            for c in candidate_list:
                try:
                    _r = SequenceMatcher(
                        None,
                        normalize_team_name_suffixes(target),
                        normalize_team_name_suffixes(str(c).strip()),
                    ).ratio()
                    if _r > _best_ratio:
                        _best_ratio, _best_c = _r, c
                except Exception:  # noqa: BLE001,S112 - intentional degraded-mode guard or structure-preserving fallback  # nosec B112  # intentional degraded-mode continue fallback
                    continue
            if _best_c is not None and _best_ratio >= 0.80:  # 【Bug7修复】相似度阈值0.6→0.80，防止江原FC误匹配到纽约城等不相关球队
                return _best_c
            return None
        except Exception as _e_fuzzy:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            # 安全降级：模糊匹配自身异常时返回 None，不阻断主流程
            print(f"      ⚠️ [必发盈亏] fuzzy_match_team_name 异常（已降级返回 None）: {_e_fuzzy}")
            return None

    def _has_common_substr_global(s1, s2, min_len=2):
        """全局版共同子串检测（用于页面级别初筛）"""
        for i in range(len(s1) - min_len + 1):
            sub = s1[i:i+min_len]
            if sub in s2:
                return True
        return False
    
    def _fuzzy_team_match(header_text, home_team, away_team, home_key, away_key):
        """模糊匹配球队名，解决译名不一致问题（【修复·问题3】增强版）。
        策略优先级：
        1. 完整名包含（最精确）
        2. 前缀关键词包含（快速）
        2.5 去除常见后缀（"队"/"FC"/"联"等）后再包含匹配（解决译名后缀不统一）
        3. difflib 相似度 >= 0.6（容错，等价于归一化编辑距离）
        4. 共同子串 >= 2字（最后兆底）
        返回 (matched: bool, confidence: float)
        """
        h_text = str(header_text)
        
        # 策略 1：完整名直接包含
        if home_team in h_text and away_team in h_text:
            return (True, 1.0)
        
        # 策略 2：前缀关键词包含（原有逻辑）
        if home_key and away_key and home_key in h_text and away_key in h_text:
            return (True, 0.9)

        # 【修复·问题3】策略 2.5：去除常见后缀后再包含匹配
        # 解决如"萨巴赫队"vs"萨巴赫"、"某某FC"vs"某某"等译名后缀不统一问题
        try:
            _suffixes = ['队', 'FC', '联', '足球俱乐部', '俱乐部', '体育会', '竞技', 'SC', 'CF']
            _clean_home, _clean_away = home_team, away_team
            for _s in _suffixes:
                _clean_home = _clean_home.replace(_s, '')
                _clean_away = _clean_away.replace(_s, '')
            if _clean_home and _clean_away and _clean_home in h_text and _clean_away in h_text:
                return (True, 0.85)
        except Exception as _e_sfx:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            # 安全降级：去后缀匹配异常时继续后续策略，不阻断匹配流程
            print(f"      ⚠️ [必发盈亏] 去后缀匹配异常（已跳过）: {_e_sfx}")
        
        # 策略 3：提取 header 中的主客队名，用 difflib 计算相似度
        # 尝试从 header 中提取 VS 两侧的球队名
        _vs_m = re.search(r'[\]\)\s]([^\[\]\(\)\d]{2,8})\s*(?:\([^)]*\))?\s*[Vv][Ss]\s*([^\[\]\(\)\d]{2,8})[\[\s]', h_text)
        if not _vs_m:
            _vs_m = re.search(r'([\u4e00-\u9fff]{2,6})\s*(?:\([^)]*\))?\s*[Vv][Ss]\s*([\u4e00-\u9fff]{2,6})', h_text)
        
        if _vs_m:
            _h_name = _vs_m.group(1).strip()
            _a_name = _vs_m.group(2).strip()
            # 计算相似度
            _sim_h = SequenceMatcher(None, home_team, _h_name).ratio()
            _sim_a = SequenceMatcher(None, away_team, _a_name).ratio()
            # 两队都达到 0.5 以上，且平均 >= 0.6
            if _sim_h >= 0.5 and _sim_a >= 0.5 and (_sim_h + _sim_a) / 2 >= 0.6:
                return (True, (_sim_h + _sim_a) / 2)
        
        # 策略 4：共同子串检测（如"沙特"在"沙特阿拉伯"和"沙特阿"中都能匹配）
        def _has_common_substr(s1, s2, min_len=2):
            """s1 和 s2 是否共享长度>=min_len 的子串"""
            for i in range(len(s1) - min_len + 1):
                sub = s1[i:i+min_len]
                if sub in s2:
                    return True
            return False
        
        _home_in_header = _has_common_substr(home_team, h_text, min_len=2)
        _away_in_header = _has_common_substr(away_team, h_text, min_len=2)
        if _home_in_header and _away_in_header:
            return (True, 0.7)
        
        return (False, 0.0)
    
    # ===== 数据源0：手机交易盈亏页（唯一真给数的来源）=====
    # 桌面必发页已 405 失效；手机 exchanges.php 有「竞足保存盈亏 / 竞足人气盈亏」真数据，
    # 「必发交易盈亏」那一段常由页面自己写「暂无数据」——那就如实说没有，不拿竞足冒充必发。
    _bf_mobile_summary = '未执行'
    _bf_desktop_summary = '未执行'
    _zg_summary = '未执行'
    _mid_pnl = str(match_info.get('okooo_match_id') or '').strip()
    if _mid_pnl:
        try:
            print("      📡 [必发盈亏] 尝试数据源0: 手机交易盈亏页（竞足保存盈亏/人气盈亏/必发）...")
            _pnl_url = f'https://m.okooo.com/match/exchanges.php?MatchID={_mid_pnl}'
            _pnl_resp = None
            for _px in _http_routes():
                try:
                    _proxies_p = cast(dict[str, str] | None, None if _px is _DIRECT_PROXIES else _px)
                    _cand = requests.get(
                        _pnl_url,
                        headers={
                            'User-Agent': 'Mozilla/5.0 (Linux; Android 12; SM-G991B) AppleWebKit/537.36 '
                                          '(KHTML, like Gecko) Chrome/131.0.0.0 Mobile Safari/537.36',
                            'Accept-Language': 'zh-CN,zh;q=0.9',
                            'Referer': 'https://m.okooo.com/jczq/',
                        },
                        proxies=_proxies_p, timeout=15, verify=_verify_tls,
                    )
                    if _cand.status_code == 200 and _cand.content:
                        _pnl_resp = _cand
                        break
                except Exception as _route_err:  # noqa: BLE001 - 单个路由失败就换下一个
                    print(f"      ℹ️ [必发盈亏] 手机盈亏路由跳过: {type(_route_err).__name__}")
                    continue
            if _pnl_resp is None:
                _bf_mobile_summary = f'手机盈亏无响应(url={_pnl_url})'
            else:
                from okooo_mobile_cs import _mobile_exchange_pnl, decode_okooo_html
                _pnl_html = decode_okooo_html(_pnl_resp.content, _pnl_resp.headers)
                _pnl = _mobile_exchange_pnl(_pnl_html)
                _title_m = re.search(r'<title[^>]*>(.*?)</title>', _pnl_html, re.DOTALL | re.IGNORECASE)
                _pnl_title = re.sub(r'\s+', ' ', _title_m.group(1)).strip()[:40] if _title_m else ''
                _bf_mobile_summary = (
                    f'HTTP=200 bytes={len(_pnl_resp.content)} title={_pnl_title or "-"} '
                    f'竞足保存盈亏={"有" if _pnl.get("jc_saved") else "无"} '
                    f'人气={"有" if _pnl.get("jc_popularity") else "无"} '
                    f'必发={"有" if _pnl.get("betfair_available") else "暂无数据"}'
                )
                print(f"      📡 [必发盈亏] 手机盈亏页: {_bf_mobile_summary}")
                if _pnl.get('betfair_available'):
                    _bf_rows = _pnl.get('betfair_trade') or {}
                    _bf_vals = {
                        side: _bf_rows.get(side) or {} for side in ('胜', '平', '负')
                    }
                    if all((v.get('pnl') is not None) for v in _bf_vals.values()):
                        result['home_profit_loss'] = _bf_vals['胜']['pnl']
                        result['draw_profit_loss'] = _bf_vals['平']['pnl']
                        result['away_profit_loss'] = _bf_vals['负']['pnl']
                        result['home_volume'] = _bf_vals['胜'].get('volume')
                        result['draw_volume'] = _bf_vals['平'].get('volume')
                        result['away_volume'] = _bf_vals['负'].get('volume')
                        _vols = [v.get('volume') for v in _bf_vals.values()]
                        if any(isinstance(v, (int, float)) for v in _vols):
                            result['volume'] = sum(v for v in _vols if isinstance(v, (int, float)))
                        result['available'] = True
                        result['source'] = '手机交易盈亏·必发段'
                        result['analysis_hint'] = _generate_betfair_analysis_hint(result)
                        print("      ✅ [必发盈亏] 手机必发段取到三个方向盈亏")
                        return result
                if _pnl.get('betfair_note'):
                    print(f"      ℹ️ [必发盈亏] {_pnl['betfair_note']}")
                if _pnl.get('jc_saved'):
                    # 竞足保存盈亏是本地真数据：记进 raw_data 供报告对照，但不当必发用。
                    result['raw_data']['jc_saved_pnl'] = _pnl.get('jc_saved')
                    result['raw_data']['jc_saved_total'] = _pnl.get('saved_total')
                    print(
                        "      ℹ️ [必发盈亏] 竞足保存盈亏已记录（保存量"
                        f"={_pnl.get('saved_total')}），但不冒充必发盈亏"
                    )
        except Exception as _pnl_err:  # noqa: BLE001 - 必发永远不影响主流程
            _bf_mobile_summary = f'异常 {type(_pnl_err).__name__}: {str(_pnl_err)[:80]}'
            print(f"      ⚠️ [必发盈亏] 手机盈亏页异常（不影响主流程）: {type(_pnl_err).__name__}: {_pnl_err}")

    # ===== 数据源1：澳客网必发盈亏页面（桌面，已 405 失效，保留以留下证据）=====
    try:
        print("      📡 [必发盈亏] 尝试数据源: 澳客网必发盈亏...")
        bf_url = 'https://www.okooo.cn/jingcai/shuju/betfa/'
        resp = _request_with_retry(bf_url, referer='https://www.okooo.cn/jingcai/')
        if not resp:
            _bf_desktop_summary = f'无响应(url={bf_url})'
        elif resp.status_code != 200:
            _bf_desktop_summary = f'HTTP={resp.status_code} url={bf_url}'
        if resp and resp.status_code == 200:
            _bf_body = resp.text or ""
            _bf_title_m = re.search(r'<title[^>]*>(.*?)</title>', _bf_body, re.DOTALL | re.IGNORECASE)
            _bf_title = re.sub(r'\s+', ' ', _bf_title_m.group(1)).strip()[:60] if _bf_title_m else ''
            _bf_bytes = len(resp.content or b'')
            tables = []
            # 该页实际会给三种东西：WAF 拦截页（title 405 / blocked）、滑动验证页、
            # 或者空壳。三种都不是数据，全部如实记录，绝不按空表解析。
            _bf_waf = bool(
                _bf_title.strip() == '405'
                or 'your request has been blocked' in _bf_body.lower()
                or 'renderData' in _bf_body
            )
            if _bf_waf or "滑动验证" in _bf_body or "aliyuncaptcha" in _bf_body.lower():
                _bf_why = 'WAF拦截页' if _bf_waf else '验证页'
                print(f"      ⚠️ [必发盈亏] 桌面澳客必发页返回{_bf_why}，不按空表解析")
                _bf_desktop_summary = (
                    f'{_bf_why} bytes={_bf_bytes} title={_bf_title or "-"} url={bf_url}'
                )
            else:
                resp.encoding = 'gb2312'
                soup = BeautifulSoup(resp.text, 'html.parser')
                tables = soup.select('table#table')
                print(f"      📡 [必发盈亏] 澳客网找到 {len(tables)} 场比赛数据")
                _bf_desktop_summary = (
                    f'HTTP=200 bytes={_bf_bytes} title={_bf_title or "-"} '
                    f'tables={len(tables)} url={bf_url}'
                )
            
            for table in tables:
                # 从 table 的前一个兄弟 div 获取比赛信息
                prev_div = table.find_previous_sibling('div')
                if not prev_div:
                    continue
                
                header_text = prev_div.get_text(separator='', strip=True)
                
                # 检查球队名是否匹配（使用模糊匹配）
                match_found, _match_conf = _fuzzy_team_match(
                    header_text, _home_team, _away_team, _home_key, _away_key
                )
                
                if not match_found:
                    continue
                # 【Bug7修复】置信度低于0.80视为匹配失败，防止误匹配
                if _match_conf < 0.80:
                    print(f"      ⚠️ [必发盈亏] 低置信度匹配已拒绝(置信度{_match_conf:.2f}<0.80): {header_text[:60]}")
                    continue
                
                print(f"      ✅ [必发盈亏] 匹配到比赛(置信度{_match_conf:.2f}): {header_text[:60]}")
                
                # 解析表格行获取盈亏数据
                rows = table.select('tr')
                total_volume = 0
                for row in rows:
                    cells = row.select('td')
                    if not cells:
                        continue
                    
                    first_cell = cells[0].get_text(strip=True)
                    if first_cell not in ['主胜', '平局', '客胜']:
                        continue
                    
                    # 提取所有数字（安全处理空字符串与非数值内容）
                    numbers = []
                    for cell in cells[1:]:
                        cell_text = cell.get_text(strip=True).replace(',', '').replace('%', '').replace('—', '').replace('-', '').strip()
                        if not cell_text:
                            continue
                        try:
                            numbers.append(float(cell_text))
                        except (ValueError, TypeError):
                            continue
                    
                    if not numbers:
                        continue
                    
                    # 最后一个数字是模拟盈亏（港元）
                    profit_loss = numbers[-1]
                    # 第一个数字是总成交额（港元）
                    volume_hkd = numbers[0] if numbers else 0
                    total_volume += volume_hkd
                    
                    # 转换为万元（港元→万港元）
                    pl_wan = profit_loss / 10000.0
                    
                    if first_cell == '主胜':
                        result['home_profit_loss'] = pl_wan
                        result['home_volume'] = volume_hkd / 10000.0
                    elif first_cell == '平局':
                        result['draw_profit_loss'] = pl_wan
                        result['draw_volume'] = volume_hkd / 10000.0
                    elif first_cell == '客胜':
                        result['away_profit_loss'] = pl_wan
                        result['away_volume'] = volume_hkd / 10000.0
                
                # 总交易量（万港元）
                if total_volume > 0:
                    result['volume'] = total_volume / 10000.0
                
                # 检查是否成功获取了三个方向的盈亏
                if (result['home_profit_loss'] is not None and 
                    result['draw_profit_loss'] is not None and 
                    result['away_profit_loss'] is not None):
                    result['available'] = True
                    result['source'] = '澳客网必发盈亏'
                    result['raw_data']['header'] = header_text[:100]
                    result['analysis_hint'] = _generate_betfair_analysis_hint(result)
                    print(f"      ✅ [必发盈亏] 数据获取成功: "
                          f"主={result['home_profit_loss']:.2f}万 "
                          f"平={result['draw_profit_loss']:.2f}万 "
                          f"客={result['away_profit_loss']:.2f}万 "
                          f"量={result['volume']:.1f}万")
                    return result
                
                # 匹配到比赛但数据不完整
                print("      ⚠️ [必发盈亏] 匹配到比赛但盈亏数据不完整")
                break
            
            # 【修复·问题3】第一轮 header 匹配失败后，启动第二轮：
            # 提取页面所有 header 中的中文队名作为候选列表，
            # 用 fuzzy_match_team_name（精确→子串→去后缀→编辑距离）反向定位目标比赛，
            # 解决"库奥皮/萨巴赫"等小语种译名不统一导致的匹配孤岛。
            if not result['available']:
                try:
                    # 构建候选映射：队名候选 → 对应的 table 对象
                    _cand_map = {}  # {队名: table}
                    for _t2 in tables:
                        _pd2 = _t2.find_previous_sibling('div')
                        if not _pd2:
                            continue
                        _ht2 = _pd2.get_text(separator='', strip=True)
                        # 提取 VS 两侧的中文队名作为候选
                        _m2 = re.search(r'([\u4e00-\u9fff]{2,8})\s*(?:\([^)]*\))?\s*[Vv][Ss]\s*([\u4e00-\u9fff]{2,8})', _ht2)
                        if _m2:
                            _cand_map[_m2.group(1).strip()] = _t2
                            _cand_map[_m2.group(2).strip()] = _t2
                    _cand_names = list(_cand_map.keys())
                    # 主客队分别用四级模糊匹配反查候选队名
                    _fm_home = fuzzy_match_team_name(_home_team, _cand_names)
                    _fm_away = fuzzy_match_team_name(_away_team, _cand_names)
                    # 主客队都匹配到且指向同一张 table → 确认为目标比赛（双口径验证防误匹配）
                    if _fm_home and _fm_away and _cand_map.get(_fm_home) is _cand_map.get(_fm_away):
                        _tbl3 = _cand_map[_fm_home]
                        print(f"      ✅ [必发盈亏] 模糊匹配命中: {_home_team}→{_fm_home} / {_away_team}→{_fm_away}")
                        # 解析该 table 的盈亏数据（与主循环同构逻辑）
                        _rows3 = _tbl3.select('tr')
                        _tv3 = 0
                        for _row3 in _rows3:
                            _cells3 = _row3.select('td')
                            if not _cells3:
                                continue
                            _fc3 = _cells3[0].get_text(strip=True)
                            if _fc3 not in ['主胜', '平局', '客胜']:
                                continue
                            _nums3 = []
                            for _cell3 in _cells3[1:]:
                                _ct3 = _cell3.get_text(strip=True).replace(',', '').replace('%', '').replace('—', '').replace('-', '').strip()
                                if not _ct3:
                                    continue
                                try:
                                    _nums3.append(float(_ct3))
                                except (ValueError, TypeError):
                                    continue
                            if not _nums3:
                                continue
                            _pl3 = _nums3[-1]
                            _vol3 = _nums3[0] if _nums3 else 0
                            _tv3 += _vol3
                            _plw3 = _pl3 / 10000.0
                            if _fc3 == '主胜':
                                result['home_profit_loss'] = _plw3
                                result['home_volume'] = _vol3 / 10000.0
                            elif _fc3 == '平局':
                                result['draw_profit_loss'] = _plw3
                                result['draw_volume'] = _vol3 / 10000.0
                            elif _fc3 == '客胜':
                                result['away_profit_loss'] = _plw3
                                result['away_volume'] = _vol3 / 10000.0
                        if _tv3 > 0:
                            result['volume'] = _tv3 / 10000.0
                        if (result['home_profit_loss'] is not None and
                                result['draw_profit_loss'] is not None and
                                result['away_profit_loss'] is not None):
                            result['available'] = True
                            result['source'] = '澳客网必发盈亏(模糊匹配)'
                            result['analysis_hint'] = _generate_betfair_analysis_hint(result)
                            print(f"      ✅ [必发盈亏] 模糊匹配数据获取成功: "
                                  f"主={result['home_profit_loss']:.2f}万 "
                                  f"平={result['draw_profit_loss']:.2f}万 "
                                  f"客={result['away_profit_loss']:.2f}万")
                            return result
                except Exception as _e_fm2:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    # 安全降级：第二轮模糊匹配异常不影响后续数据源降级链路
                    print(f"      ⚠️ [必发盈亏] 第二轮模糊匹配异常（已跳过）: {_e_fm2}")
            if not result['available']:
                print(f"      ℹ️ [必发盈亏] 澳客网未匹配到 {_home_key}/{_away_key}")
    except Exception as e_okooo:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        _bf_desktop_summary = f'异常 {type(e_okooo).__name__}: {str(e_okooo)[:80]}'
        print(f"      ⚠️ [必发盈亏] 澳客网抓取异常: {type(e_okooo).__name__}: {e_okooo}")
    
    # ===== 数据源2：足彩网必发交易量 =====
    try:
        print("      📡 [必发盈亏] 尝试数据源2: 足彩网...")
        zgzcw_url = 'https://odds.zgzcw.com/jczq/bf_data.jsp'
        resp = _request_with_retry(zgzcw_url, referer='https://odds.zgzcw.com/')
        _zg_html = ''
        _zg_title = ''
        if resp is not None:
            resp.encoding = 'utf-8'
            _zg_html = resp.text or ''
            _zg_title_match = re.search(r'<title[^>]*>(.*?)</title>', _zg_html, re.DOTALL | re.IGNORECASE)
            _zg_title = re.sub(r'\s+', ' ', _zg_title_match.group(1)).strip()[:60] if _zg_title_match else ''
        if resp and resp.status_code == 200:
            soup = BeautifulSoup(resp.text, 'html.parser')
            
            # 足彩网可能使用不同的页面结构，尝试多种选择器
            # 先查找包含球队名的元素
            all_text = soup.get_text()
            # 使用模糊匹配检测页面是否包含目标球队
            _page_has_team = (_home_key in all_text or _away_key in all_text or
                             _has_common_substr_global(_home_team, all_text) or
                             _has_common_substr_global(_away_team, all_text))
            if _page_has_team:
                _zg_summary = (
                    f'HTTP=200 bytes={len(resp.content or b"")} title={_zg_title or "-"} 含球队关键词'
                )
                print("      ℹ️ [必发盈亏] 足彩网页面包含球队关键词，尝试解析...")
                # 尝试表格解析
                tables = soup.select('table')
                for table in tables:
                    table_text = table.get_text()
                    _tbl_match, _ = _fuzzy_team_match(table_text, _home_team, _away_team, _home_key, _away_key)
                    if _tbl_match:
                        rows = table.select('tr')
                        for row in rows:
                            row_text = row.get_text(separator='|', strip=True)
                            _row_match, _ = _fuzzy_team_match(row_text, _home_team, _away_team, _home_key, _away_key)
                            if _row_match:
                                cells = row.select('td')
                                numbers = []
                                for cell in cells:
                                    ct = cell.get_text(strip=True).replace(',', '').replace('%', '')
                                    numbers.append(float(ct))
                                if len(numbers) >= 3:
                                    result['home_profit_loss'] = numbers[-3] / 10000.0
                                    result['draw_profit_loss'] = numbers[-2] / 10000.0
                                    result['away_profit_loss'] = numbers[-1] / 10000.0
                                    result['available'] = True
                                    result['source'] = '足彩网必发'
                                    result['analysis_hint'] = _generate_betfair_analysis_hint(result)
                                    return result
            else:
                _zg_summary = (
                    f'HTTP=200 bytes={len(resp.content or b"")} '
                    f'title={_zg_title or "-"} 页面无球队关键词'
                )
                print(
                    f"      ℹ️ [必发盈亏] 足彩网页面未包含球队关键词 "
                    f"(HTTP={resp.status_code} bytes={len(resp.content or b'')} "
                    f"title={_zg_title or '-'})"
                )
        elif resp is not None:
            _zg_summary = f'HTTP={resp.status_code} url={zgzcw_url}'
        else:
            _zg_summary = f'无响应(url={zgzcw_url})'
    except Exception as e_zgzcw:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        _zg_summary = f'异常 {type(e_zgzcw).__name__}: {str(e_zgzcw)[:80]}'
        print(f"      ⚠️ [必发盈亏] 足彩网抓取异常: {type(e_zgzcw).__name__}: {e_zgzcw}")

    # 所有数据源均失败
    print(f"      ⚠️ [必发盈亏] 所有数据源均未获取到 '{cn_name}' 的必发盈亏数据")
    print(
        f"      ℹ️ [必发盈亏] 源摘要: 手机盈亏={_bf_mobile_summary} | "
        f"桌面澳客必发={_bf_desktop_summary} | 足彩网={_zg_summary}"
    )
    result['analysis_hint'] = '必发盈亏数据暂不可用（可能该场比赛尚未开盘或不在当前竞猜期）'
    return result


def _generate_betfair_analysis_hint(bf_data):
    """
    根据必发盈亏数据生成分析提示。
    
    核心逻辑：
    - 主胜盈亏为正（庄家盈利）：市场资金偏向主胜但庄家不怕，可能是诱多
    - 某方向盈亏为大额负值（庄家亏损）：庄家对该方向有真实恐惧，该方向可能是真实赛果
    - 交易量越大，数据越有参考价值
    """
    hints = []
    h_pl = bf_data.get('home_profit_loss')
    d_pl = bf_data.get('draw_profit_loss')
    a_pl = bf_data.get('away_profit_loss')
    volume = bf_data.get('volume')
    
    if h_pl is None or d_pl is None or a_pl is None:
        return '盈亏数据不完整'
    
    # 交易量评估
    vol_level = '低'
    if volume is not None:
        if volume >= 500:
            vol_level = '极高'
        elif volume >= 200:
            vol_level = '高'
        elif volume >= 50:
            vol_level = '中'
        hints.append(f"交易量{volume:.0f}万({vol_level})")
    
    # 找出庄家最大亏损方向（最负值）
    pl_map = {'主胜': h_pl, '平局': d_pl, '客胜': a_pl}
    pl_map = {key: coerce_float(value) for key, value in pl_map.items()}
    min_pl_dir = min(pl_map, key=lambda key: pl_map[key])
    max_pl_dir = max(pl_map, key=lambda key: pl_map[key])
    min_pl_val = pl_map[min_pl_dir]
    max_pl_val = pl_map[max_pl_dir]
    
    # 庄家最大亏损方向分析
    if min_pl_val < -50:
        hints.append(f"⚠️庄家在{min_pl_dir}方向巨额亏损({min_pl_val:.0f}万)，该方向为庄家真实恐惧区")
    elif min_pl_val < -20:
        hints.append(f"庄家在{min_pl_dir}方向明显亏损({min_pl_val:.0f}万)，需警惕该方向")
    elif min_pl_val < 0:
        hints.append(f"庄家在{min_pl_dir}方向轻微亏损({min_pl_val:.0f}万)")
    
    # 庄家最大盈利方向分析（可能是诱多方向）
    if max_pl_val > 50:
        hints.append(f"💰庄家在{max_pl_dir}方向大额盈利({max_pl_val:.0f}万)，可能是诱多陷阱")
    elif max_pl_val > 20:
        hints.append(f"庄家在{max_pl_dir}方向盈利({max_pl_val:.0f}万)，资金偏向该方向但庄家不怕")
    
    # 盈亏差异分析
    spread = max_pl_val - min_pl_val
    if spread > 100:
        hints.append(f"盈亏极差{spread:.0f}万，市场分歧极大，{min_pl_dir}方向可能是真实赛果")
    elif spread > 50:
        hints.append(f"盈亏极差{spread:.0f}万，市场有明显分歧")
    
    # 凯利指数：市场平均即时概率×公司指数；>返还率难打出，<返还率易打出
    kelly = bf_data.get('kelly_index')
    if kelly and isinstance(kelly, dict):
        try:
            from odds_index_math import calc_return_rate, normalize_return_rate
            rr = normalize_return_rate(kelly.get('return_rate'))
            if rr is None:
                rr = calc_return_rate(
                    kelly.get('odds_home') or bf_data.get('odds_home'),
                    kelly.get('odds_draw') or bf_data.get('odds_draw'),
                    kelly.get('odds_away') or bf_data.get('odds_away'),
                )
            risk = _as_dict(kelly.get('risk'))
            label = {'home': '主胜', 'draw': '平局', 'away': '客胜'}
            for side in ('home', 'draw', 'away'):
                kv = kelly.get(side)
                if kv is None:
                    continue
                tag = risk.get(side)
                if tag == 'hard' or (rr is not None and float(kv) > rr):
                    hints.append(f"凯利指数{label[side]}={float(kv):.3f}>返还率→难打出")
                elif tag == 'easy' or (rr is not None and float(kv) < rr):
                    hints.append(f"凯利指数{label[side]}={float(kv):.3f}<返还率→易打出")
        except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
            pass

    return ' | '.join(hints) if hints else '盈亏数据正常，无明显异常信号'


# ================== 【BladeQuant V2 - TG 结构化报告生成引擎】 ==================
class TelegramReportGenerator:
    """
    【BladeQuant V2 - TG 结构化报告生成与推送引擎】
    基于全新重构的解析模型，严格执行高维到低维的降维解析链路：
    比分盈利矩阵 -> 胜平负 -> 亚盘 -> 大小球。
    """

    def __init__(self, bot_token, chat_id):
        self.bot_token = bot_token
        self.chat_id = chat_id
        self.api_url = f"https://api.telegram.org/bot{self.bot_token}/sendMessage"

    def build_macro_section(self, data):
        """一、 核心量化指标与数据解构 - 宏观方向与概率底座"""
        th = data.get('theory', {})
        mk = data.get('market', {})

        text = "一、 核心量化指标与数据解构\n"
        text += "宏观方向与概率底座（理论 vs 市场）：\n"
        text += f"理论概率（泊松模型）： 主胜 {th.get('home', 0)}% | 平局 {th.get('draw', 0)}% | 客胜 {th.get('away', 0)}%\n"
        text += f"市场隐含概率： 主胜 {mk.get('home', 0)}% | 平局 {mk.get('draw', 0)}% | 客胜 {mk.get('away', 0)}%\n"
        text += f"量化特征： {data.get('macro_feature_desc', '')}\n\n"
        return text

    def build_micro_ibi_section(self, data):
        """一、 核心量化指标与数据解构 - 盈利矩阵及核心比分防备 (含平局配对)"""
        text = "核心比分防备与诱导识别（IBI 与 偏差）：\n"
        text += f"【绝对冰点·铁锚】 {data.get('anchors_scores', '')}： {data.get('anchors_desc', '')}\n"

        # 强制执行平局交叉配对分析：0-0与2-2配对，1-1与3-3配对
        text += f"【平衡防线及平局配对】 {data.get('balanced_scores', '')}： {data.get('balanced_desc', '')}\n"
        text += f"【资金诱饵陷阱】 {data.get('traps_scores', '')}： {data.get('traps_desc', '')}\n\n"
        return text

    def build_engine_decision_section(self, data):
        """一、 核心量化指标与数据解构 - 引擎裁决与风控流向"""
        text = "引擎裁决与风控流向：\n"
        text += f"纯系统确定性决策引擎（PSDE）判定：{data.get('psde_desc', '')}\n"
        text += f"风控警示（PSDE主导·DSCV冲突）：{data.get('dscv_warning', '')}\n\n"
        return text

    def build_final_conclusion_section(self, data):
        """
        二、 最终比分终裁结论
        依据解析顺序降维输出：矩阵反推 -> 胜平负 -> 亚盘 -> 大小球。
        最终落子以"概率簇"形式呈现，替代单一比分。
        """
        text = "二、 最终比分终裁结论\n"
        text += f"胜平负方向： {data.get('direction', '')}\n"
        text += f"让球盘口： {data.get('handicap', '')}\n"
        text += f"大小球倾向： {data.get('over_under', '')}\n"

        # 提取概率簇数据
        cluster_1 = data.get('cluster_1', {})
        cluster_2 = data.get('cluster_2', {})

        text += f"预判主概率簇①： {cluster_1.get('name', '')}(理由：{cluster_1.get('reason', '')})\n"
        text += f"预判防范簇②： {cluster_2.get('name', '')}(理由：{cluster_2.get('reason', '')})"
        return text

    def generate_report(self, match_meta, analysis_data):
        """
        组装全量刀片分析报告
        :param match_meta: dict, 包含联赛、主客队、时间的元数据
        :param analysis_data: dict, 包含所有量化指标和裁决文本的数据有效载荷
        :return: str, 格式化后的 Markdown 文本
        """
        header = f"\U0001f5e1\ufe0f 【刀片分析报告】 [{match_meta.get('league', '')}] \U0001f534{match_meta.get('home', '')} vs \U0001f534{match_meta.get('away', '')} | {match_meta.get('time', '')}\n\n"

        report = header
        report += self.build_macro_section(analysis_data.get('macro', {}))
        report += self.build_micro_ibi_section(analysis_data.get('micro', {}))
        report += self.build_engine_decision_section(analysis_data.get('engine', {}))
        report += self.build_final_conclusion_section(analysis_data.get('conclusion', {}))

        return report

    def send_to_tg(self, report_text):
        """
        执行 Telegram 发送动作
        :param report_text: str, 已排版好的报告文本
        """
        payload = {
            "chat_id": self.chat_id,
            "text": report_text,
            "parse_mode": "HTML"
        }
        try:
            response = requests.post(self.api_url, json=payload, timeout=10)
            response.raise_for_status()
        except requests.exceptions.RequestException:
            # 静默处理或对接系统的错误日志模块
            pass
# ================== 【END TelegramReportGenerator】 ==================


def format_betfair_for_tg(bf_data):
    """
    将必发盈亏数据格式化为TG报告文本。
    """
    if not bf_data or not bf_data.get('available'):
        return ''
    
    lines = []
    lines.append("💹【必发交易盈亏分析】")
    lines.append(f"━ 数据来源: {bf_data.get('source', '未知')}")
    
    h_pl = bf_data.get('home_profit_loss')
    d_pl = bf_data.get('draw_profit_loss')
    a_pl = bf_data.get('away_profit_loss')
    
    if h_pl is not None and d_pl is not None and a_pl is not None:
        # 用箭头标记盈亏方向
        def _pl_fmt(val):
            if val > 0:
                return f"+{val:.1f}万(庄盈)"
            elif val < 0:
                return f"{val:.1f}万(庄亏)"
            else:
                return "0(平衡)"
        
        lines.append(f"━ 主胜盈亏: {_pl_fmt(h_pl)}")
        lines.append(f"━ 平局盈亏: {_pl_fmt(d_pl)}")
        lines.append(f"━ 客胜盈亏: {_pl_fmt(a_pl)}")
    
    volume = bf_data.get('volume')
    if volume is not None:
        lines.append(f"━ 交易量: {volume:.0f}万")
    
    # 必发指数
    bf_idx = bf_data.get('betfair_index')
    if bf_idx and isinstance(bf_idx, dict):
        lines.append(f"━ 必发指数: 主{bf_idx.get('home', '-')}/平{bf_idx.get('draw', '-')}/客{bf_idx.get('away', '-')}")
    
    # 凯利指数
    kelly = bf_data.get('kelly_index')
    if kelly and isinstance(kelly, dict):
        lines.append(f"━ 凯利指数: 主{kelly.get('home', '-')}/平{kelly.get('draw', '-')}/客{kelly.get('away', '-')}")
    
    # 分析提示
    hint = bf_data.get('analysis_hint', '')
    if hint:
        lines.append(f"━ 盈亏研判: {hint}")
    
    return '\n'.join(lines)


# ================= 【必发交易盈亏数据抓取 END】 =================


# ================= 【空间拓扑与流动性账本 JSON 投喂协议】 =================
def build_topology_json_payload(match_name, home_team, away_team, asian_handicap,
                                 prob_dict, odds_correct_score, pool15_enriched,
                                 betfair_data, fixture_id=""):
    """将比赛数据映射为去特征化的空间拓扑与流动性账本 JSON 结构。

    该函数将传统中文文本表格格式的数据，转换为去特征化的 JSON 结构，
    用于投喂 DeepSeek 研判。

    映射规则:
        - home_team -> "Entity_Alpha", away_team -> "Entity_Beta"
        - asian_handicap: 主让X球 -> "pos_minus_X", 主受X球 -> "pos_plus_X", 平手 -> "level_0"
        - 比分坐标: "1-0" -> "[1, 0]", "胜其它" -> "[5, 0]", "平其它" -> "[4, 4]", "负其它" -> "[0, 5]"

    Returns:
        dict: 空间拓扑与流动性账本 JSON payload，异常时返回 None
    """
    from datetime import datetime as _dt

    try:
        # ---- 辅助：亚盘映射 ----
        def _map_asian_handicap(ah_str):
            """将亚盘让球文本映射为去特征化标识"""
            if not ah_str:
                return "level_0"
            ah_str = str(ah_str).strip()
            # 平手
            if ah_str in ('0', '平手', '0.0', 'level'):
                return "level_0"
            # 尝试提取数值
            import re as _re
            # 主让X球: 负数或含"让"字
            if '让' in ah_str or '主让' in ah_str:
                nums = _re.findall(r'[\d.]+', ah_str)
                if nums:
                    return f"pos_minus_{nums[0]}"
                return "pos_minus_1.0"
            # 主受X球: 正数或含"受"字
            if '受' in ah_str or '主受' in ah_str:
                nums = _re.findall(r'[\d.]+', ah_str)
                if nums:
                    return f"pos_plus_{nums[0]}"
                return "pos_plus_1.0"
            # 纯数值判断
            try:
                val = float(ah_str)
                if val < 0:
                    return f"pos_minus_{abs(val)}"
                elif val > 0:
                    return f"pos_plus_{val}"
                else:
                    return "level_0"
            except (ValueError, TypeError):
                return f"pos_minus_{ah_str}"

        # ---- 辅助：比分转坐标 ----
        def _score_to_coordinate(score_str):
            """将比分字符串转换为节点坐标"""
            score_str = str(score_str).strip()
            if '其它' in score_str:
                if '胜' in score_str:
                    return "[5, 0]"
                elif '平' in score_str:
                    return "[4, 4]"
                else:
                    return "[0, 5]"
            try:
                h, a = parse_score(score_str)

                return f"[{h}, {a}]"
            except (ValueError, IndexError):
                return "[0, 0]"

        # ---- 辅助：IBI 动态打标 ----
        def _compute_tags(ibi, theory_pct, topo_dev, is_max_theory=False):
            """根据 IBI/理论概率/拓扑偏差计算动态标签"""
            tags = []
            if ibi < 0.5:
                tags.append("absolute_zero_anchor")
                if is_max_theory:
                    tags.append("max_suppression")
            if ibi > 3.0:
                tags.append("abnormal_spike")
                if theory_pct < 3.0:
                    tags.append("liquidity_trap")
            if 0.8 <= ibi <= 1.2:
                tags.append("equilibrium_node")
            if topo_dev > 0.05:
                tags.append("market_inflation")
            if topo_dev < -0.10:
                tags.append("deep_compression")
            return tags

        # ---- 辅助：方向状态判定 ----
        def _axis_status(intrinsic, market):
            """判定 compressed/inflated/neutral"""
            if market < intrinsic - 0.001:
                return "compressed"
            elif market > intrinsic + 0.001:
                return "inflated"
            else:
                return "neutral"

        # ---- 辅助：从 betfair_data 兼容取值 ----
        def _bf_pick(bf, *keys):
            """兼容多种字段命名取浮点值"""
            if not bf or not isinstance(bf, dict):
                return 0.0
            for k in keys:
                v = bf.get(k)
                if v is not None:
                    try:
                        return float(v)
                    except (TypeError, ValueError):
                        continue
            return 0.0

        # ==== 1. event_metadata ====
        event_metadata = {
            "event_id": f"SEQ_{fixture_id}" if fixture_id else f"SEQ_{hash(match_name) % 100000:05d}",
            "entity_pos": "Entity_Alpha",
            "entity_neg": "Entity_Beta",
            "timestamp": _dt.now().isoformat(timespec='seconds'),
            "structural_leverage": _map_asian_handicap(asian_handicap),
        }

        # ==== 2. 构建15池数据并计算 macro_tensor_summary ====
        pool15_data = pool15_enriched if pool15_enriched else []

        # 计算方向汇总
        intrinsic_home, intrinsic_draw, intrinsic_away = 0.0, 0.0, 0.0
        market_home, market_draw, market_away = 0.0, 0.0, 0.0

        # 从 prob_dict 和 odds_correct_score 计算全局方向概率
        if prob_dict:
            for sc, p in prob_dict.items():
                sc_str = str(sc).strip()
                p_val = float(p) * 100 if float(p) <= 1.0 else float(p)
                if '其它' in sc_str:
                    if '胜' in sc_str:
                        intrinsic_home += p_val
                    elif '平' in sc_str:
                        intrinsic_draw += p_val
                    else:
                        intrinsic_away += p_val
                elif '-' in sc_str or ':' in sc_str:
                    try:
                        h, a = parse_score(sc_str)
                        if h is None or a is None:
                            continue

                        if h > a:
                            intrinsic_home += p_val
                        elif h == a:
                            intrinsic_draw += p_val
                        else:
                            intrinsic_away += p_val
                    except (ValueError, IndexError):
                        pass

        # 从赔率反推市场方向概率
        if odds_correct_score:
            _total_inv = sum(1.0 / float(v) for v in odds_correct_score.values()
                            if isinstance(v, (int, float)) and float(v) > 0)
            if _total_inv > 0:
                for sc, odds_v in odds_correct_score.items():
                    sc_str = str(sc).strip()
                    try:
                        mp = (1.0 / float(odds_v)) / _total_inv * 100 if float(odds_v) > 0 else 0.0
                    except (ValueError, TypeError, ZeroDivisionError):
                        continue
                    if '其它' in sc_str or 'Other' in sc_str:
                        if '胜' in sc_str or 'W' in sc_str:
                            market_home += mp
                        elif '平' in sc_str or 'D' in sc_str:
                            market_draw += mp
                        else:
                            market_away += mp
                    elif '-' in sc_str or ':' in sc_str:
                        try:
                            h, a = parse_score(sc_str)
                            if h is None or a is None:
                                continue

                            if h > a:
                                market_home += mp
                            elif h == a:
                                market_draw += mp
                            else:
                                market_away += mp
                        except (ValueError, IndexError):
                            pass

        intrinsic_total = intrinsic_home + intrinsic_draw + intrinsic_away
        market_total = market_home + market_draw + market_away

        # 计算平均阻力（IBI均值）
        ibi_values = [float(it.get('ibi', 0) or 0) for it in pool15_data if float(it.get('ibi', 0) or 0) > 0]
        avg_resistance = (sum(ibi_values) / len(ibi_values)) if ibi_values else 1.0

        macro_tensor_summary = {
            "intrinsic_total_mass": round(intrinsic_total, 4),
            "market_total_mass": round(market_total, 4),
            "average_resistance": round(avg_resistance, 4),
            "directional_bias": {
                "axis_positive": {
                    "intrinsic": round(intrinsic_home, 4),
                    "market": round(market_home, 4),
                    "status": _axis_status(intrinsic_home, market_home)
                },
                "axis_neutral": {
                    "intrinsic": round(intrinsic_draw, 4),
                    "market": round(market_draw, 4),
                    "status": _axis_status(intrinsic_draw, market_draw)
                },
                "axis_negative": {
                    "intrinsic": round(intrinsic_away, 4),
                    "market": round(market_away, 4),
                    "status": _axis_status(intrinsic_away, market_away)
                }
            }
        }

        # ==== 3. topology_matrix_15pool ====
        # 找出15池中理论概率最高的比分（用于 max_suppression 标签）
        max_theory_score = ""
        max_theory_val = -1.0
        for it in pool15_data:
            th = float(it.get('theory', 0) or 0)
            if th > max_theory_val:
                max_theory_val = th
                max_theory_score = str(it.get('score', ''))

        topology_matrix = []
        for it in pool15_data:
            try:
                sc = str(it.get('score', '')).strip()
                theory = float(it.get('theory', 0) or 0)
                market = float(it.get('market', 0) or 0)
                ibi = float(it.get('ibi', 0) or 0)
                delta = float(it.get('delta', 0) or 0)

                # topological_deviation = (market - theory) / 100 归一化为小数
                topo_dev = delta / 100.0 if abs(delta) > 0.001 else 0.0

                # institutional_resistance = IBI
                is_max_th = (sc == max_theory_score)
                tags = _compute_tags(ibi, theory, topo_dev, is_max_theory=is_max_th)

                topology_matrix.append({
                    "node_coordinate": _score_to_coordinate(sc),
                    "intrinsic_potential": round(theory, 4),
                    "market_conversion": round(market, 4),
                    "topological_deviation": round(topo_dev, 4),
                    "institutional_resistance": round(ibi, 4),
                    "tags": tags
                })
            except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                print(f"   ⚠️ [异常已捕获·continue降级 L22430] {_silent_err}")
                continue

        # ==== 4. liquidity_ledger ====
        bf = betfair_data if isinstance(betfair_data, dict) and betfair_data.get('available') else {}

        volume = _bf_pick(bf, 'volume', 'bf_volume')
        h_pnl = _bf_pick(bf, 'home_profit_loss', 'home_profit', 'home_pnl')
        d_pnl = _bf_pick(bf, 'draw_profit_loss', 'draw_profit', 'draw_pnl')
        a_pnl = _bf_pick(bf, 'away_profit_loss', 'away_profit', 'away_pnl')

        # spread_tension = abs(最大亏损) + 最大盈利
        pnl_list = [h_pnl, d_pnl, a_pnl]
        max_loss = min(pnl_list) if pnl_list else 0.0
        max_profit = max(pnl_list) if pnl_list else 0.0
        spread_tension = abs(max_loss) + max_profit

        # true_risk_axis 映射
        _axis_map = {'home': 'axis_positive', 'draw': 'axis_neutral', 'away': 'axis_negative'}
        # 从 betfair_data 中获取 true_direction
        raw_true_dir = ''
        if bf:
            raw_true_dir = bf.get('squeeze_true_direction', '') or bf.get('true_direction', '')
        if not raw_true_dir and pnl_list and min(pnl_list) < -20:
            # 降级：最大亏损方向
            min_idx = pnl_list.index(min(pnl_list))
            raw_true_dir = ['home', 'draw', 'away'][min_idx]
        true_risk_axis = _axis_map.get(raw_true_dir, 'axis_positive')

        liquidity_ledger = {
            "medium_source": "primary_dark_pool",
            "density_index": round(volume, 2),
            "clearing_exposure": {
                "axis_positive_pnl": round(h_pnl, 2),
                "axis_neutral_pnl": round(d_pnl, 2),
                "axis_negative_pnl": round(a_pnl, 2)
            },
            "spread_tension": round(spread_tension, 2),
            "true_risk_axis": true_risk_axis
        }

        # ==== 组装最终 payload ====
        payload = {
            "event_metadata": event_metadata,
            "macro_tensor_summary": macro_tensor_summary,
            "topology_matrix_15pool": topology_matrix,
            "liquidity_ledger": liquidity_ledger,
        }

        return payload

    except Exception as _build_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        import traceback
        print(f"   ⚠️ [空间拓扑JSON] 构建异常(已降级): {_build_err}")
        traceback.print_exc()
        return None

# ================= 【空间拓扑与流动性账本 JSON 投喂协议 END】 =================


def get_official_matches():
    """获取今日在售竞彩：仅澳客网 jingcai 列表；禁止 500/欧洲库进阶段1。"""
    print("\n[赛事获取] 澳客竞彩在售名单（OKOOO-only）...")
    all_raw = []

    # ===== 主源：澳客竞彩在售 =====
    try:
        all_raw = attach_okooo_ids_to_matches([])
        if all_raw:
            print(f"   ✅ [澳客竞彩] 在售 {len(all_raw)} 场（均带 okooo_match_id）")
    except Exception as _okooo_list_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [澳客竞彩] 列表失败: {_okooo_list_err}")
        all_raw = []

    # ===== 可选：500 仅作赛号/让球补缺（默认关；永不单独建场）=====
    _scrape_500 = str(os.environ.get('SCRAPE_500_ENABLED', '0')).strip().lower() in ('1', 'true', 'yes', 'on')
    if _scrape_500 and all_raw:
        _REQ_HEADERS = {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 '
                          '(KHTML, like Gecko) Chrome/128.0.0.0 Safari/537.36'
        }
        _PROXIES_LIST = [
            {'http': 'http://127.0.0.1:7897', 'https': 'http://127.0.0.1:7897'},
            None,
        ]

        def _safe_get(url, headers, timeout=20):
            _verify_tls = not _allow_insecure_ssl()
            if not _verify_tls:
                import urllib3
                urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)
            for proxies in _PROXIES_LIST:
                try:
                    return requests.get(url, headers=headers, timeout=timeout, proxies=proxies, verify=_verify_tls)
                except Exception:  # noqa: BLE001,S112 - intentional degraded-mode guard or structure-preserving fallback  # nosec B112  # intentional degraded-mode continue fallback
                    continue
            return None

        try:
            from bs4 import BeautifulSoup as BS4
            r500 = _safe_get('http://trade.500.com/jczq/', _REQ_HEADERS, timeout=20)
            if r500 is not None and r500.status_code == 200 and 'data-fixtureid' in (r500.text or ''):
                soup500 = BS4(r500.text, 'html.parser')
                by_no = {}
                for tr in soup500.find_all('tr', attrs={'data-fixtureid': True}):
                    tds = tr.find_all('td')
                    if len(tds) < 4:
                        continue
                    no_text = tds[0].text.strip()
                    if no_text:
                        by_no[no_text] = tr
                patched = 0
                for m in all_raw:
                    bare = re.sub(r'^竞彩-', '', str(m.get('no') or ''))
                    tr = by_no.get(bare) or by_no.get(str(m.get('no') or ''))
                    if tr is None:
                        continue
                    if not m.get('fixture_id_500'):
                        m['fixture_id_500'] = tr.get('data-fixtureid', '')
                        patched += 1
                    if m.get('jc_handicap_int') is None:
                        try:
                            _rq = tr.get('data-rangqiu', '')
                            if _rq and str(_rq).strip():
                                m['jc_handicap_int'] = int(str(_rq).strip())
                        except (TypeError, ValueError):
                            pass
                print(f"   ℹ️ [500补缺] 已补 fixture/让球 {patched} 场（不进市均）")
        except Exception as e_req500:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [500补缺] 跳过: {e_req500}")

    if all_raw:
        for m in all_raw:
            if not m.get('source'):
                m['source'] = 'okooo_jingcai'
            if not str(m.get('no', '')).startswith('竞彩-'):
                m['no'] = f"竞彩-{m['no']}"
                m['local_id'] = m['no']
        before = len(all_raw)
        all_raw = [m for m in all_raw if m.get('okooo_match_id')]
        if len(all_raw) < before:
            print(f"   🧹 [白名单] 剔除无澳客ID场次 {before - len(all_raw)} 场")

    if not all_raw:
        print("   ⚠️ [澳客竞彩] 在售名单为空，本轮无场次可分析（已禁止 API-Football/500 建场）")

    jingcai_map = {}
    others = []
    for m in all_raw:
        no = m.get('no', '')
        src = m.get('source', '')
        bare = re.sub(r'^(竞彩-)', '', no)
        if src in ('jingcai', 'okooo_jingcai') or no.startswith('竞彩-') or not src:
            jingcai_map[bare] = m
        else:
            others.append(m)
    merged = []
    for bare, jc in jingcai_map.items():
        jc_obj = dict(jc)
        if not jc_obj['no'].startswith('竞彩-'):
            jc_obj['no'] = f'竞彩-{bare}'
            jc_obj['local_id'] = jc_obj['no']
        merged.append(jc_obj)
    merged.extend(others)

    def _sort_key(obj):
        m = re.search(r'(\d+)', obj.get('no', ''))
        return int(m.group(1)) if m else 9999

    merged.sort(key=_sort_key)
    # 只保留今日开售且未开赛
    merged = filter_today_onsale_not_started(merged)
    print(f"   ✅ [整理完成] 竞彩在售未开赛 {len(merged)} 场（澳客-only）")
    return merged



def align_matches(raw_list):
    """
    【核心修复】双轨硬匹配 + 保底直通机制
    只保留澳客手机已开售场次，不再拉取欧洲库赛程。
    """
    if not raw_list:
        return []
    print("   ↳ 正在整合赛事阵列...")
    
    aligned = []

    # 2. 第一轨：国内数据源直通 (Hard Pass)
    # 如果抓到的是竞彩赛事（通常带有 fixture_id_500 或 cn），直接构建 aligned_item，不经过 LLM 翻译
    for raw in raw_list:
        # 判断是否为国内中文赛事（通常来自 500网 或 澳客网）
        is_domestic = bool(raw.get('fixture_id_500') or raw.get('okooo_match_id') or (raw.get('no', '').startswith('竞彩')))
        
        if is_domestic:
            # 直接组装，不依赖 API 匹配
            # 【修复】使用从500网提取的开赛时间
            _raw_time = raw.get('match_time') or raw.get('time') or raw.get('kickoff_time') or ''
            if _raw_time:
                try:
                    _fixture_date = datetime.strptime(str(_raw_time)[:16], "%Y-%m-%d %H:%M").strftime("%Y-%m-%dT%H:%M:%S")
                except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    _fixture_date = str(_raw_time)
            else:
                _fixture_date = ''
            _home = str(raw.get('home') or '').strip()
            _away = str(raw.get('away') or '').strip()
            _cn = str(raw.get('cn') or '').strip()
            if _home and _away:
                _cn = f"{_home} vs {_away}"
            aligned_item = {
                # 主键优先澳客 MatchID（写死数据源）；500 fid 仅作附属
                "id": str(raw.get('okooo_match_id') or raw.get('fixture_id_500') or raw.get('no')),
                "cn_name": f"[{raw.get('no', '未知')}] {_cn or '未知对阵'}",
                "home": _home,
                "away": _away,
                "match_time": str(_raw_time)[:16] if _raw_time else '',
                "league": raw.get('league', '竞彩赛事'),
                "fixture_date": _fixture_date,
            }
            if 'fixture_id_500' in raw:
                aligned_item['fixture_id_500'] = raw['fixture_id_500']
            if 'okooo_match_id' in raw:
                aligned_item['okooo_match_id'] = raw['okooo_match_id']
            if raw.get('jc_handicap_int') is not None:
                aligned_item['jc_handicap_int'] = raw['jc_handicap_int']
            if raw.get('kickoff_source'):
                aligned_item['kickoff_source'] = raw.get('kickoff_source')
                
            aligned.append(aligned_item)

    print(f"   ✅ [第一轨直通] 成功保留 {len(aligned)} 场国内赛事")

    return aligned


def _csp_get_runtime_setting(name, default):
    """【CSP 主链路】读取运行期调参（ev_threshold/kelly_mode 等）。
    优先取 Streamlit 侧边栏全局变量，CLI/Bot 模式回退默认值，避免 NameError。
    """
    try:
        val = globals().get(name)
        if val is not None:
            return val
    except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [异常已捕获·pass降级 L23166] {_silent_err}")
    return default


def build_csp_pipeline_state(fid=None, cn_name=None, league_name=None,
                              bj_time=None, cup_mode_name='常规'):
    """【CSP 主链路】构建 12 阶段共享的统一数据契约容器。

    所有主链路中间产物都写入该 dict，便于：
      1. Telegram 报告 / Streamlit 渲染统一读取
      2. DeepSeek Step3 prompt 集中引用
      3. 历史复盘 / 调试时一眼看清各阶段产出

    字段都是惰性填充，如某个阶段缺失仅保留空 dict 即可，不影响其他阶段。
    """
    return {
        'meta': {
            'fid': fid,
            'cn_name': cn_name,
            'league_name': league_name,
            'bj_time': bj_time,
            'cup_mode_name': cup_mode_name,
        },
        'market_inputs': {},                       # Stage-1
        'lambda_chain': {                          # Stage-2 / 3 / 6
            'historical': {'home': None, 'away': None},
            'calibrated': {'home': None, 'away': None},
            'dynamic':    {'home': None, 'away': None},
        },
        'llm_signals': {                           # Stage-4 / 5
            'fund_signal': {},
            'handicap_signal': {},
        },
        'matrix': {                                # Stage-7
            'prob_dict_size': 0,
            'derived_markets': {},
            'ml_prediction': {},
            'ranked_scores_top5': [],
        },
        'anomaly': {                               # Stage-9 内部三件套
            'kelly_variance': {},
            'cross_market': {},
            'cluster': {},

            'pruning': {},
            'stagnation': {},
            'summary': {},
        },
        'decision': {                              # Stage-9 / 10 最终决策
            'first_score': None,
            'second_score': None,
            'or_prediction': {},
            'confidence': None,
            'dti': None,
            'big_small': None,
            'game_theory_log': '',
        },
        'reports': {                               # Stage-11
            'step1_report': '',
            'step2_report': '',
            'final_report': '',
        },
    }


def _build_csp_pipeline_summary(state):
    """【CSP 主链路】基于 csp_pipeline 构建 Telegram 报告头部摘要。
    已精简：删除波胆预测、λ链、31节点Top5、资金/盘口信号的独立报告输出。
    仅保留异常检测（凯利离散度、跨盘口裂缝）的条件触发输出。
    """
    try:
        if not isinstance(state, dict):
            return ''
        anomaly = state.get('anomaly', {}) or {}
        lines = []
        # 异常检测三件套（仅显示有触发的）
        try:
            kv = anomaly.get('kelly_variance', {}) or {}
            if kv.get('risk_alerts'):
                lines.append('⚖️ 凯利离散度熔断：{}'.format(' / '.join(kv['risk_alerts'])))
            cm = anomaly.get('cross_market', {}) or {}
            if cm.get('alerts'):
                lines.append('🔮 跨盘口裂缝：{}'.format(' / '.join(cm['alerts'])))

        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L23251] {_silent_err}")
        return '\n'.join(lines)
    except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [异常已捕获·return ''降级 L23254] {_silent_err}")
        return ''
