# 📊【15池比分赔率波动追踪与分析模块】
# 每次分析时将本次抓取的15池比分赔率与上一次同场快照对比，
# 找出赔率下降/上升的比分，进行数理分析与波动性分析，并在TG报告输出。
# 设计原则：全程 try/except 包裹，异常绝不中断主流程；仅用标准库 statistics。
# ============================================================================



# ═══════════════════════════════════════════════════════════════════
# 【DataFetcher 爬虫区域·赛果抓取】以下为迁移集中的赛果爬虫函数
# ═══════════════════════════════════════════════════════════════════
def _strip_clock_tokens(score_text):
    """去掉钟点（如开赛 18:00），避免被当成比分 18-0。"""
    def _repl(m):
        try:
            hh = int(m.group(1))
            mm = int(m.group(2))
            ss = m.group(3)
            ss_ok = ss is None or 0 <= int(ss) <= 59
            if 0 <= hh <= 23 and 0 <= mm <= 59 and ss_ok:
                return ' '
        except Exception:  # noqa: BLE001,S110 - intentional degraded-mode guard or structure-preserving fallback  # nosec B110  # intentional degraded-mode pass fallback
            pass
        return m.group(0)

    return re.sub(
        r'(?<!\d)(\d{1,2})\s*[:：]\s*(\d{2})(?:\s*[:：]\s*(\d{2}))?(?!\d)',
        _repl,
        score_text or '',
    )


def _plausible_ft_score(home_goals, away_goals):
    """90分钟完场比分。日期 2026-09-10 和钟点 18:00 这类误读直接丢弃。"""
    try:
        h, a = int(home_goals), int(away_goals)
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return False
    return 0 <= h <= 9 and 0 <= a <= 9 and (h + a) <= 12


def _extract_score_candidates(score_text):
    """只在完场标记附近取比分。进行中页面没有完场标记时返回空。"""
    text = _strip_clock_tokens(score_text or '')
    text = text.replace('未完场', ' ')
    text = re.sub(r'\d{4}-\d{1,2}-\d{1,2}', ' ', text)
    text = re.sub(r'(?<!\d)\d{2}-\d{2}-\d{2}(?!\d)', ' ', text)
    windows = []
    for m in re.finditer(r'(?:完场比分|全场比分|最终比分|赛果|已结束|完赛|完场|终场)', text):
        windows.append(text[max(0, m.start() - 16):m.end() + 24])
    candidates = []
    for blob in windows:
        for h, a in re.findall(r'(?<!\d)(?<!\d-)(\d{1,2})\s*[:：-]\s*(\d{1,2})(?!\d)(?!-)', blob or ''):
            hs, a_s = int(h), int(a)
            if not _plausible_ft_score(hs, a_s):
                continue
            score = f"{hs}-{a_s}"
            if score not in candidates:
                candidates.append(score)
        if candidates:
            break
    return candidates


def _score_equals_kickoff_clock(score, info):
    """开赛钟点被读成比分时才丢弃，例如 18:00 → 18-0。

    0-0、1-0、2-0、3-0、4-0 这类完场比分会和 00:00–04:00 开赛撞车，必须保留。
    """
    sc = str(score or '').replace('：', '-').replace(':', '-').strip()
    parts = re.fullmatch(r'(\d{1,2})-(\d{1,2})', sc)
    if not parts or _plausible_ft_score(parts.group(1), parts.group(2)):
        return False
    t = ''
    if isinstance(info, dict):
        t = str(info.get('time') or info.get('match_time') or info.get('kickoff') or '')
    m = re.search(r'(?<!\d)(\d{1,2}):(\d{2})', t)
    if not m:
        return False
    hh, mm = int(m.group(1)), int(m.group(2))
    return int(parts.group(1)) == hh and int(parts.group(2)) == mm


def fetch_score_from_500(fixture_id_500):
    """从500网数据分析页提取完场比分；未开赛通常显示VS。"""
    if not fixture_id_500:
        return None
    url = f"http://odds.500.com/fenxi/shuju-{fixture_id_500}.shtml"
    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/123.0 Safari/537.36',
        'Referer': 'https://trade.500.com/'
    }
    try:
        resp = safe_api_get(url, headers=headers, timeout=15)
        if resp is None or resp.status_code != 200:
            return None
        resp.encoding = resp.apparent_encoding or 'gb18030'
        from bs4 import BeautifulSoup
        soup = BeautifulSoup(resp.text, 'html.parser')
        title_text = soup.title.get_text(' ', strip=True) if soup.title else ''
        header_text = soup.get_text(' ', strip=True)[:1800]
        for candidate in _extract_score_candidates(title_text + ' ' + header_text):
            return candidate
    except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [500网比分] 解析失败 fixture_id_500={fixture_id_500}: {e}")
    return None


def _okooo_this_match_ft_score(html, okooo_match_id):
    """只读历史页本场行。比分格 attr 与链接文字必须一致，日期和交锋行不取。"""
    mid = str(okooo_match_id or '').strip()
    if not mid or not html or 'jsThisMatch' not in html:
        return None
    row_m = re.search(
        rf'class="[^"]*jsThisMatch[^"]*"[^>]*data-matchid="{re.escape(mid)}"(.*?)</tr>',
        html,
        re.DOTALL,
    )
    if not row_m:
        return None
    cell = re.search(
        rf'attr="(\d{{1,2}}-\d{{1,2}})"[^>]*>\s*<a[^>]*href="/soccer/match/{re.escape(mid)}/"[^>]*>\s*(\d{{1,2}}-\d{{1,2}})',
        row_m.group(1),
        re.DOTALL,
    )
    if not cell or cell.group(1) != cell.group(2):
        return None
    home_goals, away_goals = cell.group(1).split('-', 1)
    if not _plausible_ft_score(home_goals, away_goals):
        return None
    return cell.group(1)


_MOBILE_FT_CACHE = {'at': 0.0, 'by_id': None}


def _mobile_board_ft_score(okooo_match_id):
    """历史页本场格仍是横线时，读手机竞足已完场行的比分。不建场。"""
    mid = str(okooo_match_id or '').strip()
    if not mid:
        return None
    import time as _time_mod
    now = _time_mod.time()
    cached = _MOBILE_FT_CACHE.get('by_id')
    if not isinstance(cached, dict) or (now - float(_MOBILE_FT_CACHE.get('at') or 0)) > 600:
        by_id = {}
        try:
            for row in fetch_okooo_mobile_jingcai_board() or []:
                row_id = str(row.get('okooo_match_id') or '')
                score = str(row.get('ft_score') or '')
                if row_id and score and row.get('sale_status') == '停售':
                    by_id[row_id] = score
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            by_id = {}
        _MOBILE_FT_CACHE['at'] = now
        _MOBILE_FT_CACHE['by_id'] = by_id
        cached = by_id
    return cached.get(mid) or None


def fetch_score_from_okooo(okooo_match_id):
    """完场比分只认手机比赛页顶栏全场。半场在括号里，历史交锋行不取。

    顶栏没有全场时，才读桌面历史页本场行；仍没有，才读手机竞足已完场行。
    """
    if not okooo_match_id:
        return None
    mobile_headers = {
        'User-Agent': (
            'Mozilla/5.0 (iPhone; CPU iPhone OS 16_0 like Mac OS X) '
            'AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.0 Mobile/15E148 Safari/604.1'
        ),
        'Referer': 'https://m.okooo.com/jczq/',
        'Accept-Language': 'zh-CN,zh;q=0.9',
    }
    mobile_url = f'https://m.okooo.com/match/history.php?MatchID={okooo_match_id}'
    try:
        resp = safe_api_get(mobile_url, headers=mobile_headers, timeout=15)
        if resp is not None and resp.status_code == 200 and resp.text:
            resp.encoding = resp.apparent_encoding or 'utf-8'
            from okooo_mobile_cs import parse_mobile_nav_ft_score
            nav_score = parse_mobile_nav_ft_score(resp.text, okooo_match_id)
            if nav_score:
                return nav_score
    except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [澳客网比分] 顶栏解析失败 okooo_match_id={okooo_match_id}: {e}")
    headers = {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/123.0 Safari/537.36',
        'Referer': 'https://www.okooo.com/jingcai/'
    }
    history_url = f"https://www.okooo.com/soccer/match/{okooo_match_id}/history/"
    try:
        resp = safe_api_get(history_url, headers=headers, timeout=15)
        if resp is not None and resp.status_code == 200 and resp.text:
            resp.encoding = resp.apparent_encoding or 'utf-8'
            structured = _okooo_this_match_ft_score(resp.text, okooo_match_id)
            if structured:
                return structured
    except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [澳客网比分] 解析失败 okooo_match_id={okooo_match_id}: {e}")
    return _mobile_board_ft_score(okooo_match_id)


