class MarketDefenseInsightAnalyzer:
    """市场序防线启示与深盘诱买陷阱分析器。

    该模块只负责把市场热度顺位、理论顺位、盘口深度、凯利风险和必发盈亏
    统一为可审计的风控结果；它不直接改写概率矩阵，最终选分只在主比分出口
    执行一次防线收敛，避免与旧的多重覆写逻辑发生冲突。
    """

    def __init__(self, handicap_threshold=1.0, kelly_threshold=1.05, delta_rank_threshold=15):
        self.handicap_threshold = float(handicap_threshold)
        self.kelly_threshold = float(kelly_threshold)
        self.delta_rank_threshold = int(delta_rank_threshold)

    @staticmethod
    def _score_key(value):
        return str(value or '').replace(':', '-').strip()

    @classmethod
    def build_market_inputs(cls, ranked_scores=None, odds_correct_score=None):
        """从现有池15/波胆赔率结构生成理论序、市场序和均赔升序热度列表。"""
        theoretical = {}
        for item in (ranked_scores or []):
            try:
                score, info = item[0], item[1]
                key = cls._score_key(score)
                if not key or '其它' in key or '其他' in key:
                    continue
                theoretical[key] = int(info.get('theory_rank', info.get('rank', len(theoretical) + 1))) if isinstance(info, dict) else len(theoretical) + 1
            except (IndexError, TypeError, ValueError, AttributeError):
                continue
        if theoretical:
            theoretical = {key: idx for idx, key in enumerate(sorted(theoretical, key=lambda key: theoretical[key]), 1)}

        market_odds = {}
        if isinstance(odds_correct_score, dict):
            for raw_key, raw_value in odds_correct_score.items():
                key = cls._score_key(raw_key)
                try:
                    value = coerce_float(raw_value.get('odds', raw_value.get('odd')) if isinstance(raw_value, dict) else raw_value)
                    if key and '其它' not in key and '其他' not in key and value > 1.0:
                        market_odds[key] = value
                except (TypeError, ValueError, AttributeError):
                    continue
        elif isinstance(odds_correct_score, (list, tuple)):
            for row in odds_correct_score:
                if not isinstance(row, dict):
                    continue
                key = cls._score_key(row.get('score', row.get('option', row.get('name'))))
                try:
                    value = coerce_float(row.get('odds', row.get('odd', row.get('value'))))
                    if key and '其它' not in key and '其他' not in key and value > 1.0:
                        market_odds[key] = value
                except (TypeError, ValueError):
                    continue
        market_hot = [key for key, _ in sorted(market_odds.items(), key=lambda pair: pair[1])]
        market_ranks = {key: idx for idx, key in enumerate(market_hot, 1)}
        return market_hot, theoretical, market_ranks

    def market_defense_insight_routing(self, market_hot_list, theoretical_ranks, market_ranks, is_deep_handicap):
        hidden_defensive_picks = []
        fomo_noise_traps = []
        market_hot_list = list(market_hot_list or [])
        theoretical_ranks = dict(theoretical_ranks or {})
        market_ranks = dict(market_ranks or {})
        all_keys = set(theoretical_ranks).union(market_ranks)
        if not all_keys:
            return {'hidden_defensive_picks': [], 'fomo_noise_traps': []}
        hot_threshold_len = max(3, int(len(market_hot_list) * 0.3))
        top_hot = set(market_hot_list[:hot_threshold_len])
        total = len(all_keys)
        for key in all_keys:
            t_rank = int(theoretical_ranks.get(key, total))
            m_rank = int(market_ranks.get(key, total))
            shift = t_rank - m_rank
            if is_deep_handicap and shift >= self.delta_rank_threshold and m_rank <= total * 0.35:
                fomo_noise_traps.append({'key': key, 't_rank': t_rank, 'm_rank': m_rank, 'shift': shift, 'risk_flag': 'HIGH_ALTITUDE_FOMO_NOISE'})
                continue
            if key in top_hot or (m_rank <= total * 0.4 and abs(shift) <= 10):
                hidden_defensive_picks.append({'key': key, 't_rank': t_rank, 'm_rank': m_rank, 'shift': shift, 'defense_score': m_rank + abs(shift) * 0.5})
        hidden_defensive_picks.sort(key=lambda row: (row['defense_score'], row['m_rank']))
        return {'hidden_defensive_picks': hidden_defensive_picks, 'fomo_noise_traps': fomo_noise_traps}

    def evaluate_trap_risk(self, handicap_val, max_kelly, market_hot_list, theoretical_ranks, market_ranks, profit_loss_data):
        handicap_val = abs(float(handicap_val or 0.0))
        max_kelly = float(max_kelly or 0.0)
        is_deep = handicap_val >= self.handicap_threshold
        is_kelly_risky = max_kelly >= self.kelly_threshold
        routed = self.market_defense_insight_routing(market_hot_list, theoretical_ranks, market_ranks, is_deep)
        pnl = profit_loss_data if isinstance(profit_loss_data, dict) else {}
        main_profit = float(pnl.get('main_profit', pnl.get('home_profit_loss', 0.0)) or 0.0)
        draw_profit = float(pnl.get('draw_profit', pnl.get('draw_profit_loss', 0.0)) or 0.0)
        forced = is_deep and (is_kelly_risky or (main_profit > 500.0 and draw_profit < -100.0) or len(routed['fomo_noise_traps']) >= 2)
        picks = routed['hidden_defensive_picks']
        primary = picks[0]['key'] if picks else None
        secondary = picks[1]['key'] if len(picks) > 1 else primary
        return {
            'available': bool(routed['hidden_defensive_picks'] or routed['fomo_noise_traps']),
            'is_deep_handicap': is_deep,
            'max_kelly': max_kelly,
            'trap_warning_triggered': forced,
            'market_defense_insights': picks,
            'detected_traps': routed['fomo_noise_traps'],
            'adjusted_selection': {'primary': primary, 'secondary': secondary},
            'profit_loss_context': {'main_profit': main_profit, 'draw_profit': draw_profit},
        }



