class DataFetcher:
    """爬虫统一门面：赛事列表、盘口详情、必发盈亏、赛果比分的标准化数据出口。

    设计原则（架构重构）：
    - 业务层禁止直接调用 requests / BeautifulSoup；统一经由本门面。
    - 每个方法返回标准化 dict（或 None），HTML 解析细节封装在底层函数内。
    """

    # —— 赛事列表与对齐 ——
    get_official_matches = staticmethod(get_official_matches)
    align_matches = staticmethod(align_matches)

    # —— 盘口/交易所详情 ——
    scrape_500_detail = staticmethod(scrape_500_detail)
    scrape_okooo_detail = staticmethod(scrape_okooo_detail)
    scrape_betfair_profit_loss = staticmethod(scrape_betfair_profit_loss)

    # —— 赛果比分：澳客优先，500 兜底 ——
    fetch_score_from_500 = staticmethod(fetch_score_from_500)
    fetch_score_from_okooo = staticmethod(fetch_score_from_okooo)

    # —— 网页 AI 提取 ——
    ai_extract_from_page = staticmethod(ai_extract_from_page)

def _normalize_odds_snapshot(odds_dict):
    """将赔率字典清洗为标准快照格式 {"1-0": 6.5, ...}（比分:赔率，float）。

    - 比分键统一为 "x-y" 形式（兼容 "x:y"）；
    - 仅保留可转为正浮点数的赔率；
    - 含"其它"等虚拟方向比分（无法做数值比分对比）一并保留键名但仍存赔率，
      供波动对比（仅按键名匹配，不参与比分方向数值拆分）。
    """
    snapshot = {}
    try:
        if not odds_dict or not isinstance(odds_dict, dict):
            return snapshot
        for _k, _v in odds_dict.items():
            try:
                if _k is None:
                    continue
                _key = str(_k).strip().replace(':', '-')
                if not _key:
                    continue
                _val = float(_v)
                if _val > 0:
                    snapshot[_key] = round(_val, 3)
            except (ValueError, TypeError):
                continue
    except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [异常已捕获·pass降级 L23635] {_silent_err}")
    return snapshot


def _score_direction(score_str):
    """判断比分方向：'home'(主胜)/'draw'(平)/'away'(客胜)/None(无法解析，如"胜其它")。"""
    try:
        _s = str(score_str).strip()
        if '其它' in _s or '其他' in _s:
            # 虚拟方向比分：尝试按名称粗判方向
            if _s.startswith('胜'):
                return 'home'
            if _s.startswith('平'):
                return 'draw'
            if _s.startswith('负'):
                return 'away'
            return None
        _h, _a = parse_score(_s)
        if _h is None or _a is None:
            return None
        if _h > _a:
            return 'home'
        if _h == _a:
            return 'draw'
        return 'away'
    except (ValueError, TypeError):
        return None


def analyze_odds_movement(prev_snapshot, curr_snapshot):
    """对比上一次与本次15池比分赔率快照，输出赔率波动数理分析结果。

    参数：
        prev_snapshot: dict, 上一次快照 {"1-0": 6.5, ...}
        curr_snapshot: dict, 本次快照

    返回 dict：
        available: bool, 是否有可对比数据（两个快照都非空且有共同比分）
        odds_down: list[(score, old, new, delta, pct)] 赔率下降（按降幅绝对值排序）
        odds_up:   list[(score, old, new, delta, pct)] 赔率上升（按升幅排序）
        volatility_index: float, 波动性指数（所有共同比分赔率变化绝对值的标准差）
        max_drop_score: str, 最大降幅比分（庄家重点关注方向）
        concentration_shift: dict, 概率集中度变化方向汇总
        direction_flow: dict, 主胜/平/客胜方向资金流向判断
        direction_verdict: str, 方向性研判结论文本
    """
    result = {
        'available': False,
        'odds_down': [],
        'odds_up': [],
        'volatility_index': 0.0,
        'max_drop_score': '',
        'concentration_shift': {},
        'direction_flow': {},
        'direction_verdict': '',
    }
    try:
        prev = _normalize_odds_snapshot(prev_snapshot)
        curr = _normalize_odds_snapshot(curr_snapshot)
        if not prev or not curr:
            return result
        # 共同比分集合
        _common = [s for s in curr if s in prev]
        if not _common:
            return result

        _abs_changes = []          # 所有赔率变化绝对值（波动性统计）
        _down, _up = [], []
        # 方向资金流向：赔率下降=资金流入=概率上升（庄家看好）
        _dir_down_count = {'home': 0, 'draw': 0, 'away': 0}
        _dir_down_mag = {'home': 0.0, 'draw': 0.0, 'away': 0.0}
        for _s in _common:
            _old = prev[_s]
            _new = curr[_s]
            _delta = round(_new - _old, 3)
            _pct = round((_delta / _old * 100.0), 2) if _old > 0 else 0.0
            _abs_changes.append(abs(_delta))
            if _delta < 0:
                # 赔率下降
                _down.append((_s, _old, _new, _delta, _pct))
                _dir = _score_direction(_s)
                if _dir in _dir_down_count:
                    _dir_down_count[_dir] += 1
                    _dir_down_mag[_dir] += abs(_delta)
            elif _delta > 0:
                _up.append((_s, _old, _new, _delta, _pct))

        # 排序：下降按降幅绝对值从大到小；上升按升幅从大到小
        _down.sort(key=lambda x: x[3])               # delta 最负的在前
        _up.sort(key=lambda x: x[3], reverse=True)   # delta 最正的在前

        # 波动性指数：所有共同比分赔率变化绝对值的标准差
        _vol = 0.0
        try:
            if len(_abs_changes) >= 2:
                _vol = float(statistics.pstdev(_abs_changes))
            elif len(_abs_changes) == 1:
                _vol = float(_abs_changes[0])
        except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            _vol = 0.0

        # 最大降幅比分（赔率下降幅度最大者 = 庄家核心看好）
        _max_drop = _down[0][0] if _down else ''

        # 概率集中度变化：下降比分数 vs 上升比分数
        _concentration = {
            'down_count': len(_down),
            'up_count': len(_up),
            'flat_count': len(_common) - len(_down) - len(_up),
            'net_shift': len(_down) - len(_up),  # 正数=整体概率向部分比分集中（庄家加注）
        }

        # 方向性研判
        _dir_label = {'home': '主胜', 'draw': '平局', 'away': '客胜'}
        _direction_flow = {
            _dir_label[k]: {'down_count': _dir_down_count[k], 'down_magnitude': round(_dir_down_mag[k], 3)}
            for k in ('home', 'draw', 'away')
        }
        # 取资金流入（赔率下降幅度合计）最大的方向
        _verdict = '各方向资金流向均衡，未见明显加注方向'
        try:
            _max_dir = max(_dir_down_mag.items(), key=lambda kv: kv[1])
            if _max_dir[1] > 0:
                _verdict = (
                    f"资金主要流入【{_dir_label[_max_dir[0]]}】方向"
                    f"（该向赔率下降比分{_dir_down_count[_max_dir[0]]}个、降幅合计{_max_dir[1]:.3f}），"
                    f"庄家概率向该方向集中"
                )
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L23765] {_silent_err}")

        result.update({
            'available': True,
            'odds_down': _down,
            'odds_up': _up,
            'volatility_index': round(_vol, 4),
            'max_drop_score': _max_drop,
            'concentration_shift': _concentration,
            'direction_flow': _direction_flow,
            'direction_verdict': _verdict,
        })
    except Exception as _aom_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        try:
            print(f"   \u26a0\ufe0f [赔率波动分析] 异常(已降级): {_aom_err}")
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L23781] {_silent_err}")
    return result


def build_odds_movement_tg_section(movement_result, prev_time='', curr_time='',
                                   predicted_score='', max_show=8):
    """将赔率波动分析结果格式化为 TG 报告段落文本。

    movement_result: analyze_odds_movement 返回的 dict；若 available=False 则视为首次采集。
    prev_time/curr_time: 快照时间戳字符串。
    predicted_score: 当前首选预测比分，用于做最大降幅一致性检验。
    """
    try:
        if not movement_result or not isinstance(movement_result, dict) or not movement_result.get('available'):
            return ("📊【15池赔率波动追踪】首次采集，暂无历史对比数据，"
                    "下次分析将展示赔率波动。")

        _lines = ["📊【15池赔率波动追踪·跨时段变分分析】"]
        _lines.append(f"⏱️ 对比时段：{prev_time or '上次'} → {curr_time or '本次'}")

        _down = movement_result.get('odds_down', []) or []
        _up = movement_result.get('odds_up', []) or []

        # 赔率下降（庄家加注方向）
        _lines.append("📉 赔率下降（庄家加注方向）：")
        if _down:
            for _s, _old, _new, _delta, _pct in _down[:max_show]:
                _lines.append(
                    f"   {_s}: {_old} → {_new} (↓{abs(_delta):.2f}, {_pct:.2f}%)"
                )
        else:
            _lines.append("   （无赔率下降比分）")

        # 赔率上升（庄家减注方向）
        _lines.append("📈 赔率上升（庄家减注方向）：")
        if _up:
            for _s, _old, _new, _delta, _pct in _up[:max_show]:
                _lines.append(
                    f"   {_s}: {_old} → {_new} (↑{abs(_delta):.2f}, +{_pct:.2f}%)"
                )
        else:
            _lines.append("   （无赔率上升比分）")

        # 波动性指数
        _vol = movement_result.get('volatility_index', 0.0)
        _lines.append(f"📐 波动性指数：{_vol:.4f}")

        # 最大降幅聚焦
        _max_drop = movement_result.get('max_drop_score', '') or '无'
        _lines.append(f"🎯 最大降幅聚焦：{_max_drop}（庄家核心看好）")

        # 最大降幅与当前预测一致性检验
        try:
            if _max_drop and _max_drop != '无' and predicted_score:
                _pred = str(predicted_score).strip().replace(':', '-')
                if _max_drop == _pred:
                    _lines.append(f"   ✅ 一致性检验：最大降幅比分与当前预测【{_pred}】一致，资金面共振")
                else:
                    _lines.append(f"   ⚠️ 一致性检验：最大降幅比分【{_max_drop}】与当前预测【{_pred}】不一致，需警惕资金背离")
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L23841] {_silent_err}")

        # 方向性研判
        _verdict = movement_result.get('direction_verdict', '') or '数据不足'
        _lines.append(f"🧭 方向性研判：{_verdict}")

        # 概率集中度补充
        try:
            _cs = movement_result.get('concentration_shift', {}) or {}
            if _cs:
                _net = _cs.get('net_shift', 0)
                _trend = '概率向少数比分集中（庄家收紧）' if _net > 0 else ('概率趋于发散（庄家放开）' if _net < 0 else '集中度基本持平')
                _lines.append(
                    f"📊 集中度变化：下降{_cs.get('down_count',0)}个 / 上升{_cs.get('up_count',0)}个 / 持平{_cs.get('flat_count',0)}个 → {_trend}"
                )
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L23857] {_silent_err}")

        return "\n".join(_lines)
    except Exception as _bom_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        try:
            print(f"   \u26a0\ufe0f [赔率波动TG段落] 拼装异常(已降级): {_bom_err}")
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L23864] {_silent_err}")
        return ""


# ============================================================================
# 【模块一·IBI时间序列求导 dIBI/dt 动能雷达】
# ----------------------------------------------------------------------------
# 基于每6小时（或临场分钟级）15池赔率快照序列，为每个比分计算 IBI 的一阶导数
# dIBI/dt 与二阶导数 d²IBI/dt²，识别两类庄家吸筹/恐吓手法：
#   - 慢炖吸筹(BOILING_FROG_TRAP)：IBI 从常态(~1.0)极度平滑缓慢爬升到高位(>2.5)，
#     dIBI/dt 持续为正但很小 → 温水煮青蛙
#   - 临场恐吓(LATE_SCARECROW)：IBI 长期极低后突然脉冲式正跳变，dIBI/dt >> 0
# 真实防线特征：抗震性强（dIBI/dt ≈ 0 且 IBI 持续低位）。
# 时间精度：有多个分钟级切片时用分钟级 dt，否则降级用 6 小时切片。
# 全程 try/except 降级，异常返回 available=False。
# ============================================================================


def _compute_ibi_series_from_snapshot(snapshot, theory_probs=None):
    """由某一时刻的15池赔率快照 {score: odds} 计算每个比分的 IBI。

    IBI(庄家防备指数) = 市场隐含概率 / 理论概率。
    - 市场隐含概率：由该快照赔率去水归一得到；
    - 理论概率：若提供 theory_probs 则用之，否则退化用市场概率自身(IBI恒=1，
      仅保留可比较的时间序列结构，供 dIBI/dt 观察相对变化)。
    返回 {score: ibi_float}。
    """
    ibi_map = {}
    try:
        snap = _normalize_odds_snapshot(snapshot)
        if not snap:
            return ibi_map
        # 市场隐含概率（去水归一）
        _inv_sum = 0.0
        _inv = {}
        for _s, _o in snap.items():
            try:
                if _o and float(_o) > 0:
                    _iv = 1.0 / float(_o)
                    _inv[_s] = _iv
                    _inv_sum += _iv
            except (TypeError, ValueError):
                continue
        if _inv_sum <= 0:
            return ibi_map
        for _s, _iv in _inv.items():
            _p_mkt = _iv / _inv_sum
            _p_theory = None
            if theory_probs and isinstance(theory_probs, dict):
                try:
                    _pt = theory_probs.get(_s)
                    if _pt is None:
                        _pt = theory_probs.get(str(_s).replace('-', ':'))
                    if _pt is not None:
                        _p_theory = float(_pt)
                        # 允许 theory 以百分数或小数传入，统一到 0~1
                        if _p_theory > 1.5:
                            _p_theory = _p_theory / 100.0
                except (TypeError, ValueError):
                    _p_theory = None
            if _p_theory and _p_theory > 0.001:
                ibi_map[_s] = round(_p_mkt / _p_theory, 4)
            else:
                # 无理论概率时退化：IBI 以市场概率相对均值的比值近似（保留时序结构）
                ibi_map[_s] = round(_p_mkt / (1.0 / max(len(_inv), 1)), 4)
    except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [异常已捕获·pass降级 L23930] {_silent_err}")
    return ibi_map


def analyze_ibi_derivative(ibi_timeline, theory_probs=None):
    """IBI 一阶/二阶导数动能雷达。

    参数：
        ibi_timeline: list[dict]，时间升序，每项形如
            {'timestamp': 'YYYY-mm-dd HH:MM:SS', 'ibi': {score: ibi}}
            或 {'timestamp': ..., 'odds': {score: odds}}（自动转 IBI）。
        theory_probs: 可选，理论概率 {score: prob}，用于由 odds 计算 IBI。
    返回 dict：
        {available, dt_mode('minute'|'6h'|'single'),
         scores: {score: {ibi_now, dibi_dt, d2ibi_dt2, tag, note}},
         tags: {score: tag}, alerts: [str], defense_scores: [str]}
    """
    result = {
        'available': False,
        'dt_mode': 'single',
        'scores': {},
        'tags': {},
        'alerts': [],
        'defense_scores': [],
    }
    try:
        if not ibi_timeline or not isinstance(ibi_timeline, (list, tuple)):
            return result
        # 规整为 [(t_seconds, {score: ibi})] 时间升序
        _seq = []
        for _slice in ibi_timeline:
            if not isinstance(_slice, dict):
                continue
            _ts_raw = _slice.get('timestamp') or _slice.get('time') or ''
            _t = None
            for _fmt in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%d %H:%M'):
                try:
                    _t = datetime.strptime(str(_ts_raw)[:19], _fmt)
                    break
                except (ValueError, TypeError):
                    continue
            _ibi = _slice.get('ibi')
            if not (_ibi and isinstance(_ibi, dict)):
                _ibi = _compute_ibi_series_from_snapshot(
                    _slice.get('odds') or _slice.get('odds_data') or {}, theory_probs)
            if _ibi:
                _seq.append((_t, _ibi))
        if len(_seq) < 2:
            # 单点：无法求导，只回填当前 IBI
            if len(_seq) == 1:
                for _s, _v in _seq[0][1].items():
                    result['scores'][_s] = {
                        'ibi_now': _v, 'dibi_dt': 0.0, 'd2ibi_dt2': 0.0,
                        'tag': 'INSUFFICIENT', 'note': '仅单个切片，无法求导'}
            return result

        # 判定 dt 精度：若相邻切片时间差中位数 <= 30 分钟 → minute 模式
        _dt_hours_list = []
        _has_time = all(_t is not None for _t, _ in _seq)
        if _has_time:
            for _i in range(1, len(_seq)):
                _dh = (_seq[_i][0] - _seq[_i - 1][0]).total_seconds() / 3600.0
                if _dh > 0:
                    _dt_hours_list.append(_dh)
        if _dt_hours_list:
            _med_dt = statistics.median(_dt_hours_list)
            result['dt_mode'] = 'minute' if _med_dt <= 0.75 else '6h'
        else:
            result['dt_mode'] = '6h'
            _dt_hours_list = [6.0] * (len(_seq) - 1)

        # 逐比分求导：dIBI/dt 用末段差分，d²IBI/dt² 用三点差分（如有>=3切片）
        _all_scores = set()
        for _, _ibi in _seq:
            _all_scores.update(_ibi.keys())

        for _s in _all_scores:
            _series = []
            for _idx, (_t, _ibi) in enumerate(_seq):
                if _s in _ibi:
                    _series.append((_idx, _ibi[_s]))
            if len(_series) < 2:
                continue
            # 一阶导：末两点
            _i1, _v1 = _series[-2]
            _i2, _v2 = _series[-1]
            _dt1 = _dt_hours_list[_i2 - 1] if 0 <= _i2 - 1 < len(_dt_hours_list) else 6.0
            _dt1 = _dt1 if _dt1 > 0 else 6.0
            _dibi_dt = round((_v2 - _v1) / _dt1, 5)
            # 二阶导：末三点
            _d2 = 0.0
            if len(_series) >= 3:
                _i0, _v0 = _series[-3]
                _dt0 = _dt_hours_list[_i1 - 1] if 0 <= _i1 - 1 < len(_dt_hours_list) else 6.0
                _dt0 = _dt0 if _dt0 > 0 else 6.0
                _slope_prev = (_v1 - _v0) / _dt0
                _slope_now = (_v2 - _v1) / _dt1
                _d2 = round((_slope_now - _slope_prev) / ((_dt0 + _dt1) / 2.0), 6)
            _ibi_now = _v2
            _ibi_min = min(v for _, v in _series)
            _ibi_max = max(v for _, v in _series)

            # ===== 手法识别 =====
            _tag = 'STABLE'
            _note = ''
            # 慢炖吸筹：全程平滑缓升、爬到高位、dIBI/dt 持续为正但小
            _all_positive = all(
                (_series[_k][1] - _series[_k - 1][1]) >= -0.02 for _k in range(1, len(_series)))
            _smooth = (_ibi_max - _ibi_min) > 0.8 and 0 < _dibi_dt < 0.30 and _all_positive
            if _ibi_now > 2.5 and _smooth and _ibi_min < 1.6:
                _tag = 'BOILING_FROG_TRAP'
                _note = (f"慢炖吸筹：IBI 从{_ibi_min:.2f}平滑爬升至{_ibi_now:.2f}，"
                         f"dIBI/dt={_dibi_dt:+.3f}(小幅持续为正)，温水煮青蛙诱多")
            # 临场恐吓：长期极低后脉冲式正跳变
            elif _dibi_dt >= 0.60 and _ibi_min < 0.7 and (_ibi_now - _ibi_min) > 1.0:
                _tag = 'LATE_SCARECROW'
                _note = (f"临场恐吓：IBI 长期低位({_ibi_min:.2f})后脉冲跳升至{_ibi_now:.2f}，"
                         f"dIBI/dt={_dibi_dt:+.3f}>>0，稻草人式吓阻")
            # 真实防线：抗震（dIBI/dt≈0 且 IBI 持续低位）
            elif abs(_dibi_dt) < 0.05 and _ibi_now < 0.9 and _ibi_max < 1.1:
                _tag = 'TRUE_DEFENSE'
                _note = (f"真实防线：抗震性强 dIBI/dt={_dibi_dt:+.3f}≈0 且 IBI 持续低位"
                         f"({_ibi_now:.2f})，庄家真实不设防")
                result['defense_scores'].append(_s)

            result['scores'][_s] = {
                'ibi_now': round(_ibi_now, 4),
                'ibi_min': round(_ibi_min, 4),
                'ibi_max': round(_ibi_max, 4),
                'dibi_dt': _dibi_dt,
                'd2ibi_dt2': _d2,
                'tag': _tag,
                'note': _note,
            }
            if _tag not in ('STABLE',):
                result['tags'][_s] = _tag
            if _tag == 'BOILING_FROG_TRAP':
                result['alerts'].append(f"🐸 {_s} 慢炖吸筹陷阱(BOILING_FROG_TRAP)：{_note}")
            elif _tag == 'LATE_SCARECROW':
                result['alerts'].append(f"🎃 {_s} 临场恐吓(LATE_SCARECROW)：{_note}")

        result['available'] = bool(result['scores'])
    except Exception as _ibi_deriv_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        try:
            print(f"   \u26a0\ufe0f [IBI动能雷达] 求导异常(已降级): {_ibi_deriv_err}")
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L24076] {_silent_err}")
    return result


# ============================================================================
# 【模块二·跨盘口全息雷达 Cross-Market Arbitrage / Holographic Radar】
# ----------------------------------------------------------------------------
# 计算隐含主胜概率 P_1x2(Home) 与亚盘折算主胜概率 P_AH(Home) 的离差，
# 当 |P_1x2 - P_AH| > epsilon(0.08) 时触发"逻辑裂缝"(LOGIC_CRACK)警报。
# 手法3(虚假示弱 FAKE_WEAKNESS)：欧赔抬高主胜赔率但亚盘深度不退 → 主胜掩护信号；
# 手法4(进球期望错位 GOALS_MISALIGNMENT)：泊松 λ_total 与大小球盘口线严重偏离
# (>0.75 球) → 服从盘口切断大球。
# 全程 try/except 降级，异常返回 available=False。
# ============================================================================


def analyze_cross_market_hologram(odds_1x2_dict=None, asian_handicap=None,
                                  ou_line=None, lam_total=None,
                                  euro_odds_500=None, epsilon=0.08,
                                  goals_epsilon=0.75):
    """跨盘口全息雷达：欧赔 vs 亚盘主胜概率离差 + 进球期望错位。

    参数：
        odds_1x2_dict: {'Home':x,'Draw':y,'Away':z} 欧赔（去水前）。
        asian_handicap: float 亚盘让球（主让为负，如 -0.75）。
        ou_line: float 大小球盘口线。
        lam_total: float 泊松总进球期望 λ_home+λ_away。
        euro_odds_500: 可选，500网多家欧赔 list，用于稳健均值。
    返回 dict：
        {available, p_1x2_home, p_ah_home, prob_divergence, logic_crack,
         fake_weakness, fake_weakness_dir, goals_misalignment,
         goals_delta, tags:[...], alerts:[...], verdict}
    """
    result = {
        'available': False,
        'p_1x2_home': 0.0,
        'p_ah_home': 0.0,
        'prob_divergence': 0.0,
        'logic_crack': False,
        'fake_weakness': False,
        'fake_weakness_dir': '',
        'goals_misalignment': False,
        'goals_delta': 0.0,
        'tags': [],
        'alerts': [],
        'verdict': '',
    }
    try:
        # ---- 1) 欧赔隐含主胜概率（去水归一）----
        _p_home = _p_draw = _p_away = None
        _oh = _od = _oa = None
        if odds_1x2_dict and isinstance(odds_1x2_dict, dict):
            try:
                _oh = float(odds_1x2_dict.get('Home') or odds_1x2_dict.get('home') or 0)
                _od = float(odds_1x2_dict.get('Draw') or odds_1x2_dict.get('draw') or 0)
                _oa = float(odds_1x2_dict.get('Away') or odds_1x2_dict.get('away') or 0)
            except (TypeError, ValueError):
                _oh = _od = _oa = None
        if (not _oh or _oh <= 1.0) and euro_odds_500 and isinstance(euro_odds_500, (list, tuple)):
            # 用500网多家欧赔均值兜底
            _hs, _ds, _as = [], [], []
            for _e in euro_odds_500:
                try:
                    _hs.append(float(_e.get('home') or _e.get('h')))
                    _ds.append(float(_e.get('draw') or _e.get('d')))
                    _as.append(float(_e.get('away') or _e.get('a')))
                except (TypeError, ValueError, AttributeError):
                    continue
            if _hs and _ds and _as:
                _oh = sum(_hs) / len(_hs)
                _od = sum(_ds) / len(_ds)
                _oa = sum(_as) / len(_as)
        if _oh and _od and _oa and _oh > 1.0 and _od > 1.0 and _oa > 1.0:
            _inv_h, _inv_d, _inv_a = 1.0 / _oh, 1.0 / _od, 1.0 / _oa
            _s = _inv_h + _inv_d + _inv_a
            if _s > 0:
                _p_home = _inv_h / _s
                _p_draw = _inv_d / _s
                _p_away = _inv_a / _s

        # ---- 2) 亚盘折算主胜概率 ----
        # 用标准正态近似：以让球线为分界，让球越深(主让越多)代表庄家判定主队越强。
        # P_AH(Home 赢盘) 通过让球线 + 泊松/经验映射折算主胜真实深度概率。
        _p_ah_home = None
        if asian_handicap is not None:
            try:
                _ah = float(asian_handicap)
                # 经验映射：让球线 → 主胜深度概率（logistic 拟合，主让为负数）
                # ah=0→~0.42, ah=-0.5→~0.55, ah=-1.0→~0.66, ah=-1.5→~0.75, ah=-2→~0.83
                _p_ah_home = 1.0 / (1.0 + math.exp(_ah * 1.05 + 0.32))
                _p_ah_home = max(0.02, min(0.98, _p_ah_home))
            except (TypeError, ValueError):
                _p_ah_home = None

        # ---- 3) 概率离差 → 逻辑裂缝 ----
        if _p_home is not None and _p_ah_home is not None:
            result['available'] = True
            result['p_1x2_home'] = round(_p_home, 4)
            result['p_ah_home'] = round(_p_ah_home, 4)
            _div = round(_p_1x2_home_minus := (_p_home - _p_ah_home), 4)
            result['prob_divergence'] = round(abs(_div), 4)
            if abs(_div) > epsilon:
                result['logic_crack'] = True
                result['tags'].append('LOGIC_CRACK')
                result['alerts'].append(
                    f"🕳️ 逻辑裂缝(LOGIC_CRACK)：欧赔主胜概率{_p_home:.1%} vs 亚盘折算主胜{_p_ah_home:.1%}，"
                    f"离差={abs(_div):.3f}>ε({epsilon})")
                # 手法3·虚假示弱：欧赔抬高主胜赔率(欧赔主胜概率偏低) 但亚盘深度不退(亚盘主胜概率高)
                if _div < -epsilon:
                    result['fake_weakness'] = True
                    result['fake_weakness_dir'] = 'home'
                    result['tags'].append('FAKE_WEAKNESS')
                    result['alerts'].append(
                        f"🎭 虚假示弱(FAKE_WEAKNESS·主胜掩护)：欧赔故意抬高主胜赔率压低概率至{_p_home:.1%}，"
                        f"但亚盘深度不退仍折算{_p_ah_home:.1%}，主胜真实方向被掩护")
                elif _div > epsilon:
                    # 反向：欧赔高看主胜但亚盘不给深度 → 客向虚假示弱/主胜诱多
                    result['fake_weakness'] = True
                    result['fake_weakness_dir'] = 'away'
                    result['tags'].append('FAKE_WEAKNESS')
                    result['alerts'].append(
                        f"🎭 虚假示弱(FAKE_WEAKNESS·客向掩护)：欧赔高看主胜{_p_home:.1%}但亚盘仅折算{_p_ah_home:.1%}，"
                        f"主胜或为诱多、客向真实方向被掩护")

        # ---- 4) 进球期望错位 ----
        if lam_total is not None and ou_line is not None:
            try:
                _lt = float(lam_total)
                _ol = float(ou_line)
                _gdelta = round(_lt - _ol, 3)
                result['goals_delta'] = _gdelta
                if abs(_gdelta) > goals_epsilon:
                    result['goals_misalignment'] = True
                    result['tags'].append('GOALS_MISALIGNMENT')
                    if _gdelta > 0:
                        result['alerts'].append(
                            f"⚽ 进球期望错位(GOALS_MISALIGNMENT)：泊松λ_total={_lt:.2f} 显著高于大小球盘口线{_ol:.2f}"
                            f"(偏离{_gdelta:+.2f}>{goals_epsilon}球) → 服从盘口，切断大球诱多")
                    else:
                        result['alerts'].append(
                            f"⚽ 进球期望错位(GOALS_MISALIGNMENT)：泊松λ_total={_lt:.2f} 显著低于大小球盘口线{_ol:.2f}"
                            f"(偏离{_gdelta:+.2f}球) → 服从盘口，警惕小球陷阱")
            except (TypeError, ValueError):
                pass

        # ---- 汇总研判 ----
        if result['tags']:
            result['verdict'] = ' | '.join(sorted(set(result['tags'])))
        else:
            result['verdict'] = '跨盘口逻辑自洽，未见明显裂缝'
            if result['p_1x2_home'] or result['p_ah_home']:
                result['available'] = True
    except Exception as _cmh_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        try:
            print(f"   \u26a0\ufe0f [跨盘口全息雷达] 异常(已降级): {_cmh_err}")
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L24232] {_silent_err}")
    return result


# ============================================================================
# 【模块四·诱导微观颗粒度细化 Micro-Granularity Deception Detector】
# ----------------------------------------------------------------------------
# 依据亚盘让球深度将局势分为两类，识别庄家的微观诱导手法：
#   - 强弱悬殊局(亚盘让球绝对值≥1.5)的奶酪陷阱(HONEYPOT_TRAP)：
#       让球平/卡盘比分(1-0/2-1)赔率被调高 + IBI 极低 → 实际穿盘
#   - 势均力敌局(亚盘让球绝对值≤0.5)的平局泥潭(QUAGMIRE_DECOY)：
#       0-0 和 1-1 的 IBI 两极分化 → 庄家用有进球平局(1-1)分流闷平(0-0)风险
# 全程 try/except 降级，异常返回 available=False。
# ============================================================================


def analyze_micro_granularity_deception(pool15_enriched=None, asian_handicap=None):
    """诱导微观颗粒度细化检测。

    参数：
        pool15_enriched: list[dict]，每项含 {'score','theory','market','ibi',...}
            （theory/market 为百分数或小数均兼容；ibi 为庄家防备指数）。
        asian_handicap: float 亚盘让球（主让为负）。
    返回 dict：
        {available, regime('mismatch'|'even'|'normal'),
         tags:{score: tag}, alerts:[...],
         honeypot_scores:[...], quagmire_scores:[...], verdict}
    """
    result = {
        'available': False,
        'regime': 'normal',
        'tags': {},
        'alerts': [],
        'honeypot_scores': [],
        'quagmire_scores': [],
        'verdict': '',
    }
    try:
        if not pool15_enriched or not isinstance(pool15_enriched, (list, tuple)):
            return result
        # 建立 score → {ibi, market, theory} 映射
        _map = {}
        _ibi_all = []
        for _x in pool15_enriched:
            if not isinstance(_x, dict):
                continue
            _s = str(_x.get('score', '')).replace(':', '-').strip()
            if not _s:
                continue
            _ibi = _x.get('ibi')
            try:
                _ibi = float(_ibi) if _ibi is not None else None
            except (TypeError, ValueError):
                _ibi = None
            _map[_s] = {
                'ibi': _ibi,
                'market': _x.get('market'),
                'theory': _x.get('theory'),
            }
            if _ibi is not None:
                _ibi_all.append(_ibi)
        if not _map:
            return result
        _ibi_median = statistics.median(_ibi_all) if _ibi_all else 1.0
        _ibi_low_thr = min(0.6, _ibi_median * 0.5)  # IBI 极低阈值（动态）

        _ah_abs = None
        if asian_handicap is not None:
            try:
                _ah_abs = abs(float(asian_handicap))
            except (TypeError, ValueError):
                _ah_abs = None

        # ===== A. 强弱悬殊局：奶酪陷阱 =====
        if _ah_abs is not None and _ah_abs >= 1.5:
            result['regime'] = 'mismatch'
            for _cand, _info in _map.items():
                if not _info or _info.get('ibi') is None:
                    continue
                _ibi = _info['ibi']
                # 赔率调高 = 市场概率被压低 = IBI 极低（庄家不设防，实际穿盘）
                if _ibi <= _ibi_low_thr:
                    result['tags'][_cand] = 'HONEYPOT_TRAP'
                    result['honeypot_scores'].append(_cand)
                    result['alerts'].append(
                        f"🧀 奶酪陷阱(HONEYPOT_TRAP)：强弱悬殊局(让球{asian_handicap})下卡盘比分{_cand} "
                        f"IBI={_ibi:.2f}极低(赔率被调高)，庄家不设防 → 实际大概率穿盘")

        # ===== B. 势均力敌局：平局泥潭 =====
        elif _ah_abs is not None and _ah_abs <= 0.5:
            result['regime'] = 'even'
            _ranked_ibi = [
                (_cand, _info.get('ibi'))
                for _cand, _info in _map.items()
                if _info and _info.get('ibi') is not None
            ]
            if len(_ranked_ibi) >= 2:
                _ranked_ibi.sort(key=lambda item: item[1])
                _lo_s, _lo = _ranked_ibi[0]
                _hi_s, _hi = _ranked_ibi[-1]
                _gap = abs(_hi - _lo)
                if _gap >= 0.6 and _hi_s != _lo_s:
                    result['tags'][_hi_s] = 'QUAGMIRE_DECOY'
                    result['tags'][_lo_s] = 'QUAGMIRE_DECOY'
                    result['quagmire_scores'].extend([_hi_s, _lo_s])
                    result['alerts'].append(
                        f"🌫️ 平局泥潭(QUAGMIRE_DECOY)：势均力敌局(让球{asian_handicap})下 "
                        f"{_lo_s}(IBI={_lo:.2f}) 与 {_hi_s}(IBI={_hi:.2f}) 两极分化(差{_gap:.2f})，"
                        f"庄家高防{_hi_s}分流{_lo_s}")

        result['available'] = True
        if result['tags']:
            result['verdict'] = ' | '.join(sorted(set(result['tags'].values())))
        else:
            result['verdict'] = f"微观颗粒度({result['regime']})：未触发奶酪/泥潭诱导"
    except Exception as _mgd_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        try:
            print(f"   \u26a0\ufe0f [微观颗粒度] 异常(已降级): {_mgd_err}")
        except Exception as _silent_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            print(f"   ⚠️ [异常已捕获·pass降级 L24355] {_silent_err}")
    return result



