    report_text = f"🎯 【今日战役复盘】{today_str}\n"
    report_text += "━━━━━━━━━━━━━━━━━━\n"
    report_text += f"📊 命中统计：首选{win_count}/{total_count} | 次选{win2_count}/{total_count} | 方向{dir_hit}/{total_count}\n"
    report_text += "━━━━━━━━━━━━━━━━━━\n"

    if hit_list:
        report_text += "✅ 命中场次：\n"
