def _parse_backfill_odds_payload(odds_res):
    """将 API-Sports 历史赔率响应整理成 build_feature_vector 所需格式。"""
    odds_data = {
        'opening_1x2': {},
        'instant_1x2': {},
        'opening_ah_line': None,
        'instant_ah_line': None,
        'opening_ou_line': None,
        'instant_ou_line': None,
        'asian_handicap': None,
        'ou_line': None,
    }
    try:
        if not odds_res.get('response'):
            return odds_data
        bookmakers = odds_res['response'][0].get('bookmakers', []) or []
        if not bookmakers:
            return odds_data
        bets = bookmakers[0].get('bets', []) or []
        for bet in bets:
            values = bet.get('values', []) or []
            if bet.get('name') == 'Match Winner':
                for item in values:
                    odd_val = MathUtils.safe_float(item.get('odd'))
                    label = str(item.get('value', '')).strip()
                    if odd_val is None:
                        continue
                    if label == 'Home':
                        odds_data['instant_1x2']['home'] = odd_val
                        odds_data['opening_1x2']['home'] = odd_val
                    elif label == 'Draw':
                        odds_data['instant_1x2']['draw'] = odd_val
                        odds_data['opening_1x2']['draw'] = odd_val
                    elif label == 'Away':
                        odds_data['instant_1x2']['away'] = odd_val
                        odds_data['opening_1x2']['away'] = odd_val
            elif bet.get('name') == 'Goals Over/Under' and len(values) >= 2:
                line_val = str(values[0].get('value', '')).replace('Over ', '').replace('Under ', '').strip()
                line_num = MathUtils.safe_float(line_val)
                if line_num is not None:
                    odds_data['instant_ou_line'] = standardize_ou_line(line_num)
                    odds_data['opening_ou_line'] = standardize_ou_line(line_num)
                    odds_data['ou_line'] = standardize_ou_line(line_num)
            elif bet.get('name') == 'Asian Handicap' and values:
                line_num = MathUtils.safe_float(values[0].get('value'))
                odds_data['instant_ah_line'] = standardize_ah_line(line_num)
                odds_data['opening_ah_line'] = standardize_ah_line(line_num)
                odds_data['asian_handicap'] = standardize_ah_line(line_num)
    except Exception as e:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        print(f"   ⚠️ [FeatureStore] 历史赔率解析失败: {e}")
    return odds_data


def _backfill_convert_time(utc_str):
    """将API返回的UTC时间字符串转换为北京时间字符串。"""
    try:
        if not utc_str:
            return ''
        utc_str = str(utc_str).strip()
        # API-Sports 返回格式如 '2026-04-12T15:00:00+00:00' 或 '2026-04-12T15:00:00Z'
        from datetime import datetime, timedelta, timezone
        utc_str_clean = utc_str.replace('Z', '+00:00')
        dt = datetime.fromisoformat(utc_str_clean)
        beijing_tz = timezone(timedelta(hours=8))
        dt_beijing = dt.astimezone(beijing_tz)
        return dt_beijing.strftime('%Y-%m-%d %H:%M')
    except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
        return str(utc_str)[:16] if utc_str else ''


def backfill_historical_data(days=30):
    """按日期回溯抓取历史比赛，构建特征向量并写入SQLite特征库。"""
    ensure_feature_store_table()
    days = max(1, int(days or 30))
    summary = {
        'days': days,
        'dates_processed': 0,
        'fixtures_seen': 0,
        'saved_count': 0,
        'completed_count': 0,
        'error_count': 0,
        'errors': [],
    }
    today = datetime.now().date()

    for offset in range(1, days + 1):
        target_date = (today - timedelta(days=offset)).strftime('%Y-%m-%d')
        try:
            resp = safe_api_get(
                f"https://v3.football.api-sports.io/fixtures?date={target_date}",
                headers=HEADERS,
                timeout=20
            )
            fixture_res = resp.json() if resp else {'response': []}
            fixtures = fixture_res.get('response', []) or []
            summary['dates_processed'] += 1
            summary['fixtures_seen'] += len(fixtures)
            print(f"   📦 [FeatureStore] 回溯日期 {target_date}，共 {len(fixtures)} 场比赛")

            for fixture_item in fixtures:
                try:
                    fixture_id = str(fixture_item.get('fixture', {}).get('id', '')).strip()
                    if not fixture_id:
                        continue
                    teams = fixture_item.get('teams', {}) or {}
                    home_name = teams.get('home', {}).get('name', '主队')
                    away_name = teams.get('away', {}).get('name', '客队')
                    league_name = fixture_item.get('league', {}).get('name', '')
                    status_short = str(fixture_item.get('fixture', {}).get('status', {}).get('short', '')).strip()
                    goals = fixture_item.get('goals', {}) or {}
                    actual_score = ''
                    record_status = 'pending'
                    if status_short in ['FT', 'AET', 'PEN']:
                        gh = goals.get('home') if goals.get('home') is not None else 0
                        ga = goals.get('away') if goals.get('away') is not None else 0
                        actual_score = f"{gh}-{ga}"
                        record_status = 'completed'
                        summary['completed_count'] += 1

                    pred_home = pred_draw = pred_away = None
                    pred_advice = ''
                    try:
                        pred_resp = safe_api_get(
                            f"https://v3.football.api-sports.io/predictions?fixture={fixture_id}",
                            headers=HEADERS,
                            timeout=15
                        )
                        pred_res = pred_resp.json() if pred_resp else {'response': []}
                        if pred_res.get('response'):
                            pred_block = pred_res['response'][0].get('predictions', {}) or {}
                            pred_pct = pred_block.get('percent', {}) or {}
                            pred_home = MathUtils.safe_float(pred_pct.get('home'))
                            pred_draw = MathUtils.safe_float(pred_pct.get('draw'))
                            pred_away = MathUtils.safe_float(pred_pct.get('away'))
                            # 【问题4修复·惰性数据过滤】接近 35/35/30 或 33/33/33（容差±3）则置0
                            _af_lazy2 = False
                            try:
                                if pred_home is not None and pred_draw is not None and pred_away is not None:
                                    _TOL = 3.0
                                    if (abs(pred_home - 35) <= _TOL and abs(pred_draw - 35) <= _TOL and abs(pred_away - 30) <= _TOL) or \
                                       (abs(pred_home - 33) <= _TOL and abs(pred_draw - 33) <= _TOL and abs(pred_away - 33) <= _TOL):
                                        _af_lazy2 = True
                            except Exception:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                                _af_lazy2 = False
                            if _af_lazy2:
                                pred_home = pred_draw = pred_away = None
                                print(f"   ⚠️ [API-Football] 检测到无效惰性数据(35/35/30)，已忽略（权重=0） fixture_id={fixture_id}")
                            else:
                                if pred_home is not None:
                                    pred_home /= 100.0
                                if pred_draw is not None:
                                    pred_draw /= 100.0
                                if pred_away is not None:
                                    pred_away /= 100.0
                            pred_advice = str(pred_block.get('advice', '')).strip()
                    except Exception as e_pred:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                        print(f"   ⚠️ [FeatureStore] 历史预测获取失败 fixture_id={fixture_id}: {e_pred}")

                    odds_res = {'response': []}
                    try:
                        odds_resp = safe_api_get(
                            f"https://v3.football.api-sports.io/odds?fixture={fixture_id}",
                            headers=HEADERS,
                            timeout=15
                        )
                        odds_res = odds_resp.json() if odds_resp else {'response': []}
                    except Exception as e_odds:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                        print(f"   ⚠️ [FeatureStore] 历史赔率获取失败 fixture_id={fixture_id}: {e_odds}")

                    odds_data = _parse_backfill_odds_payload(odds_res)
                    # =====================================================
                    # 【架构重构一·回填侧API惰性数据→欧赔转化概率】
                    # 与实时主流程保持一致：惰性数据被置 None 后，若回填赔率可用，
                    # 用去水隐含概率补齐 pred_home/pred_away/pred_draw，避免训练样本存入
                    # NaN 使后续统一训练集构建时整行被剔除。
                    # =====================================================
                    try:
                        if (pred_home is None or pred_away is None):
                            _bf_open = (odds_data.get('opening_1x2', {}) or {}) if isinstance(odds_data, dict) else {}
                            _bf_inst = (odds_data.get('instant_1x2', {}) or {}) if isinstance(odds_data, dict) else {}
                            _bf_odds_src = _bf_inst if (_bf_inst and _bf_inst.get('home')) else _bf_open
                            _bf_trip = _extract_prob_triplet(_bf_odds_src)
                            if _bf_trip.get('home') is not None and _bf_trip.get('away') is not None:
                                if pred_home is None:
                                    pred_home = coerce_float(_bf_trip['home'])
                                if pred_away is None:
                                    pred_away = coerce_float(_bf_trip['away'])
                                if pred_draw is None and _bf_trip.get('draw') is not None:
                                    pred_draw = coerce_float(_bf_trip['draw'])
                                print(f"   🩹 [FeatureStore·API概率回填] 惰性数据缺失→欧赔转化概率 fixture_id={fixture_id}")
                    except Exception as _bf_fill_err:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                        print(f"   ⚠️ [FeatureStore·API概率回填] 异常(已跳过): {_bf_fill_err}")
                    match_data = {
                        'pred_advice': pred_advice,
                        'pred_win_percent_home': pred_home,
                        'pred_win_percent_draw': pred_draw,
                        'pred_win_percent_away': pred_away,
                    }
                    feature_vector = build_feature_vector(match_data, {}, odds_data)
                    match_record = {
                        'fixture_id': fixture_id,
                        'match': f"{home_name} vs {away_name}",
                        'league': league_name,
                        'time': _backfill_convert_time(fixture_item.get('fixture', {}).get('date', '')),
                        'status': record_status,
                        'actual_score': actual_score,
                        'fusion_confidence': None,
                        'top_score_prob': None,
                        'feature_vector': feature_vector,
                        'source_tag': 'api_sports_backfill',
                    }
                    if save_features_to_db(match_record, feature_vector):
                        summary['saved_count'] += 1
                except Exception as e_fixture:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
                    summary['error_count'] += 1
                    err_text = f"{target_date} fixture处理失败: {e_fixture}"
                    summary['errors'].append(err_text)
                    print(f"   ⚠️ [FeatureStore] {err_text}")
        except Exception as e_date:  # noqa: BLE001 - intentional degraded-mode guard or structure-preserving fallback
            summary['error_count'] += 1
            err_text = f"{target_date} 日期回溯失败: {e_date}"
            summary['errors'].append(err_text)
            print(f"   ⚠️ [FeatureStore] {err_text}")

    return summary


def _ui_status_pill(label, value, ok=None):
    """状态条单格：值 + 颜色点。ok=None 表示未探测（灰），True 绿，False 红。"""
    dot = '⚪' if ok is None else ('🟢' if ok else '🔴')
    return f"{dot} **{label}** · {value}"


def _ui_render_status_strip() -> None:
    """侧栏顶部紧凑状态条：DB / sklearn / DeepSeek / Telegram / 代理。"""
    try:
        diag = build_system_diagnostics(force_tg_check=False)
    except Exception as exc:  # noqa: BLE001 - 状态条失败不能让页面挂掉
        st.sidebar.error(f"状态条读取失败：{type(exc).__name__}: {exc}")
        return
    db = _ui_dict(diag.get('db'))
    telegram = _ui_dict(diag.get('telegram_getme'))
    proxy = _ui_dict(diag.get('proxy'))

    db_path = str(db.get('path') or '未解析')
    schema_version = str(db.get('schema_version') or 'unknown')
    db_ok = not db.get('error')
    sklearn_ok = bool(globals().get('ML_SKLEARN_OK'))
    deepseek_ok = bool(diag.get('deepseek_key_present'))
    tg_present = bool(diag.get('telegram_token_present'))
    tg_status = str(telegram.get('status') or 'unknown')
    proxy_reachable = proxy.get('reachable')
    proxy_route = str(proxy.get('route') or 'auto')

    with st.sidebar.container(border=True):
        st.caption('系统状态')
        st.markdown(_ui_status_pill('DB', f'schema v{schema_version}', db_ok), unsafe_allow_html=False)
        st.caption(f"　`{db_path}`")
        st.markdown(_ui_status_pill('sklearn', '可用' if sklearn_ok else '缺失（走泊松兜底）', sklearn_ok))
        st.markdown(_ui_status_pill('DeepSeek', 'key 已配置' if deepseek_ok else 'key 缺失', deepseek_ok))
        if tg_present:
            st.markdown(_ui_status_pill('Telegram', tg_status, tg_status == 'ok'))
        else:
            st.markdown(_ui_status_pill('Telegram', 'token 未配置', False))
        if proxy.get('url_configured'):
            st.markdown(_ui_status_pill('代理', f"{proxy_route} · {'可达' if proxy_reachable else '不可达'}", bool(proxy_reachable)))
        else:
            st.markdown(_ui_status_pill('代理', f'{proxy_route} · 未配置', None))


def _ui_section_of(key: str) -> str:
    return str(st.session_state.get(key) or '概览')


def _ui_conf_badge(confidence: str) -> str:
    """置信度色标：高红、中高橙、中黄、中偏低蓝、低灰。"""
    palette = {
        '高': ('#B91C1C', '#FEE2E2'),
        '中偏高': ('#C2410C', '#FFEDD5'),
        '中': ('#A16207', '#FEF9C3'),
        '中偏低': ('#1D4ED8', '#DBEAFE'),
        '低': ('#4B5563', '#F3F4F6'),
    }
    fg, bg = palette.get(str(confidence or '').strip(), palette['低'])
    label = str(confidence or '未知')
    return (
        f"<span style='background:{bg};color:{fg};padding:2px 8px;border-radius:10px;"
        f"font-size:0.8rem;font-weight:600'>{label}</span>"
    )


def _ui_risk_badge(score) -> str:
    """风险色标：冷门分 ≥70 红、≥50 橙、其余灰。"""
    try:
        value = float(score or 0)
    except (TypeError, ValueError):
        value = 0.0
    if value >= 70:
        fg, bg = '#B91C1C', '#FEE2E2'
    elif value >= 50:
        fg, bg = '#C2410C', '#FFEDD5'
    else:
        fg, bg = '#4B5563', '#F3F4F6'
    return (
        f"<span style='background:{bg};color:{fg};padding:2px 8px;border-radius:10px;"
        f"font-size:0.8rem;font-weight:600'>{value:.0f}</span>"
    )


def _ui_metric_row(items) -> None:
    """统一指标卡：3 列自适应，缺值显示 ➖。"""
    rows = [item for item in (items or []) if isinstance(item, dict)]
    if not rows:
        st.caption('暂无指标')
        return
    for start in range(0, len(rows), 3):
        chunk = rows[start:start + 3]
        columns = st.columns(len(chunk))
        for column, item in zip(columns, chunk):
            column.metric(
                str(item.get('label') or '-'),
                str(item.get('value') if item.get('value') not in (None, '') else '➖'),
                help=str(item.get('hint') or ''),
            )


def _ui_render_summary_cards(data) -> None:
    """概览页顶部：总场次 / 未开赛 / 进行中 / 完场 / 冷门告警。"""
    records = [v for v in (data or {}).values() if isinstance(v, dict)]
    total = len(records)
    pending = sum(1 for r in records if str(r.get('status') or '').lower() == 'pending')
    live = sum(1 for r in records if str(r.get('status') or '').lower() == 'live')
    done = sum(1 for r in records if str(r.get('status') or '').lower() == 'completed')
    cold = sum(1 for r in records if float(r.get('cold_score') or 0) >= 50)
    columns = st.columns(5)
    columns[0].metric('总场次', total)
    columns[1].metric('未开赛', pending)
    columns[2].metric('进行中', live)
    columns[3].metric('已完场', done)
    columns[4].metric('冷门告警', cold, delta=None if not cold else '需关注', delta_color='inverse')
    if total == 0:
        st.info('暂无赛事数据：先点侧栏「自动化抓取分析」，或执行 `python app_v84_hermes.py --open-scrape`。')


def _ui_render_confidence_mix(data) -> None:
    """置信度分布：颜色随档次变化，便于一眼看结构。"""
    records = [v for v in (data or {}).values() if isinstance(v, dict)]
    if not records:
        st.caption('暂无置信度分布（等待抓取结果）')
        return
    order = ['高', '中偏高', '中', '中偏低', '低']
    counts = {label: 0 for label in order}
    for record in records:
        label = str(record.get('confidence') or '低').strip()
        counts[label if label in counts else '低'] += 1
    colors = {'高': '#B91C1C', '中偏高': '#C2410C', '中': '#A16207', '中偏低': '#1D4ED8', '低': '#6B7280'}
    figure = go.Figure(data=[go.Bar(
        x=order,
        y=[counts[label] for label in order],
        marker_color=[colors[label] for label in order],
        text=[counts[label] for label in order],
        textposition='outside',
    )])
    figure.update_layout(
        height=260,
        margin={"l": 10, "r": 10, "t": 20, "b": 10},
        yaxis_title='场次',
        template='plotly_white',
        showlegend=False,
    )
    st.plotly_chart(figure, width='stretch', key='war_room_conf_mix')


def _ui_table_style(frame, confidence_col=None, risk_col=None):
    """表格着色：置信度列按档位，风险列按分值。返回 Styler 或原表。"""
    try:
        styler = frame.style
    except Exception:  # noqa: BLE001 - Styler 不可用时直接返回原表
        return frame

    def _conf_color(value):
        mapping = {
            '高': 'background-color:#FEE2E2;color:#B91C1C;font-weight:600',
            '中偏高': 'background-color:#FFEDD5;color:#C2410C;font-weight:600',
            '中': 'background-color:#FEF9C3;color:#A16207',
            '中偏低': 'background-color:#DBEAFE;color:#1D4ED8',
            '低': 'background-color:#F3F4F6;color:#4B5563',
        }
        return mapping.get(str(value or '').strip(), '')

    def _risk_color(value):
        try:
            number = float(value)
        except (TypeError, ValueError):
            return ''
        if number >= 70:
            return 'background-color:#FEE2E2;color:#B91C1C;font-weight:600'
        if number >= 50:
            return 'background-color:#FFEDD5;color:#C2410C;font-weight:600'
        return ''

    try:
        if confidence_col and confidence_col in frame.columns:
            styler = styler.map(_conf_color, subset=[confidence_col])
        if risk_col and risk_col in frame.columns:
            styler = styler.map(_risk_color, subset=[risk_col])
    except Exception:  # noqa: BLE001 - 着色失败退回素表
        return frame
    return styler


